module.exports={"id":"wenli","name":"文理和合本","language":"文言文 · 1919","books":["创世记","出埃及记","利未记","民数记","申命记","约书亚记","士师记","路得记","撒母耳记上","撒母耳记下","列王纪上","列王纪下","历代志上","历代志下","以斯拉记","尼希米记","以斯帖记","约伯记","诗篇","箴言","传道书","雅歌","以赛亚书","耶利米书","耶利米哀歌","以西结书","但以理书","何西阿书","约珥书","阿摩司书","俄巴底亚书","约拿书","弥迦书","那鸿书","哈巴谷书","西番雅书","哈该书","撒迦利亚书","玛拉基书","马太福音","马可福音","路加福音","约翰福音","使徒行传","罗马书","哥林多前书","哥林多后书","加拉太书","以弗所书","腓立比书","歌罗西书","帖撒罗尼迦前书","帖撒罗尼迦后书","提摩太前书","提摩太后书","提多书","腓利门书","希伯来书","雅各书","彼得前书","彼得后书","约翰一书","约翰二书","约翰三书","犹大书","启示录"],"verses":[[1,1,1,"元始、上帝創造天地、"],[1,1,2,"地乃虛曠混沌、淵際晦冥、上帝之神煦育乎水面、"],[1,1,3,"上帝曰、宜有光、卽有光、"],[1,1,4,"上帝視光爲善、遂判光暗、"],[1,1,5,"謂光爲晝、謂暗爲夜、有夕有朝、是乃一日、○"],[1,1,6,"上帝曰、水中宜有穹蒼、使水判乎上下、"],[1,1,7,"遂作穹蒼、以分穹蒼上下之水、有如此也、"],[1,1,8,"上帝謂穹蒼爲天、有夕有朝、是乃二日、○"],[1,1,9,"上帝曰、天下諸水、宜匯一區、俾見大陸、有如此也、"],[1,1,10,"謂大陸爲地、謂匯水爲海、上帝視之爲善、"],[1,1,11,"上帝曰、地宜生草、及結實之蔬、結果之樹、果懷其核、各從其類、有如此也、"],[1,1,12,"地遂生草、及結實之蔬、結果之樹、果懷其核、各從其類、上帝視之爲善、"],[1,1,13,"有夕有朝、是乃三日、○"],[1,1,14,"上帝曰、穹蒼宜有輝光、以分晝夜、以爲兆象、以定四時年日、"],[1,1,15,"光麗於天、照臨於地、有如此也、"],[1,1,16,"上帝造二巨光、大者司晝、小者司夜、亦造星辰、"],[1,1,17,"置之穹蒼、照臨於地、"],[1,1,18,"以司晝夜、以分明晦、上帝視之爲善、"],[1,1,19,"有夕有朝、是乃四日、○"],[1,1,20,"上帝曰、水宜滋生生物、鳥飛地上、戾乎穹蒼、"],[1,1,21,"遂造巨魚、曁水中所滋生之動物、各從其類、又造羽族、各從其類、上帝視之爲善、"],[1,1,22,"祝之曰、生育衆多、鱗介充牣於海、禽鳥繁衍於地、"],[1,1,23,"有夕有朝、是乃五日、○"],[1,1,24,"上帝曰、地宜產生生物、各從其類、牲畜昆蟲走獸、各從其類、有如此也、"],[1,1,25,"遂造走獸牲畜、地上昆蟲、皆各從其類、上帝視之爲善、"],[1,1,26,"上帝曰、宜造人、其形其象肖我儕、以治海魚飛鳥牲畜、及動於地上之昆蟲、並治全地、"],[1,1,27,"遂造人、維肖乎己、象上帝形、造男亦造女、"],[1,1,28,"上帝祝之曰、生育衆多、遍滿於地、而治理之、以統轄海魚飛鳥、與地上動物、"],[1,1,29,"又曰、遍地結實之菜蔬、懷核之樹果、我予汝以爲食、"],[1,1,30,"至地上走獸、空中飛鳥、曁動於地上之生物、我賜之青草以爲食、有如此也、"],[1,1,31,"上帝視凡所造者盡善、有夕有朝、是乃六日、"],[1,2,1,"天地萬物旣成、"],[1,2,2,"七日上帝造物工竣、乃憩息、"],[1,2,3,"蓋是日上帝畢其工而安息、遂錫嘏此日、別之爲聖、○"],[1,2,4,"耶和華上帝創造天地之日、其畧如左、"],[1,2,5,"爾時野無草木、田間蔬菜未生、蓋耶和華上帝未降雨於地、亦無人耕之、"],[1,2,6,"惟霧由地上騰、普潤土壤、"],[1,2,7,"耶和華上帝摶土爲人、噓生氣於其鼻、乃成生靈、"],[1,2,8,"耶和華上帝植囿於東方之伊甸、置所造之人於其間、"],[1,2,9,"耶和華上帝使地生諸樹、觀可娛目、食可適口、當囿之中、有生命之樹、及別善惡之樹、"],[1,2,10,"有河流自伊甸、灌漑其囿、中分四支、"],[1,2,11,"一曰比遜、瀠洄於哈腓拉、其地產金、"],[1,2,12,"厥金精良、亦產珍珠碧玉、"],[1,2,13,"二曰基訓、環流於古實、"],[1,2,14,"三曰希底結、流於亞述東、四曰伯拉、"],[1,2,15,"耶和華上帝挈其人置伊甸囿、使之治理監守、"],[1,2,16,"命之曰、囿中樹果、任意可食、"],[1,2,17,"惟別善惡之樹、其果不可食、食之日必死、○"],[1,2,18,"耶和華上帝曰、人獨處非善、我將作一相助者以配之、"],[1,2,19,"耶和華上帝以土造野間走獸、空中飛鳥、攜至其人前、視其稱以何名、其所以稱各生物者、卽其物之名也、"],[1,2,20,"其人於牲畜飛鳥走獸、各命以名、惟己無相助者配之、"],[1,2,21,"耶和華上帝乃令其人酣睡、取其脇骨之一、彌縫其肉、"],[1,2,22,"以所取之脇骨造女、攜至其前、"],[1,2,23,"其人曰、是乃我骨中之骨、肉中之肉、可稱爲女、因自男出也、"],[1,2,24,"是以人將離父母、膠漆其妻、成爲一體、"],[1,2,25,"夫婦並裸、亦無愧焉、"],[1,3,1,"耶和華上帝所造之百獸、惟蛇最狡、蛇謂婦曰、囿中諸樹、上帝豈語汝勿食乎、"],[1,3,2,"婦曰、囿樹之實、我儕可食、"],[1,3,3,"惟囿之中一樹、上帝戒之、毋食毋捫、恐致死亡、"],[1,3,4,"蛇曰、爾未必死、"],[1,3,5,"蓋上帝知爾食之日、爾目必明、將如上帝、能辨善惡、"],[1,3,6,"婦視其樹、食可適口、觀可娛目、且可愛慕、益人智慧、遂取果食之、並以遺夫、夫亦食之、"],[1,3,7,"二人之目卽明、自知裸體、遂編無花果葉爲裳、"],[1,3,8,"晚涼時、耶和華上帝遊於囿、其人與婦聞其聲、匿囿樹間以避之、"],[1,3,9,"耶和華上帝呼其人曰、汝何在、"],[1,3,10,"曰、我聞爾聲於囿、以我裸故、畏而自匿、"],[1,3,11,"曰、孰語爾裸乎、我戒爾勿食之樹果、爾食之乎、"],[1,3,12,"曰、爾所賜偕我之婦、以樹果予我、而我食之、"],[1,3,13,"耶和華上帝謂婦曰、爾何爲耶、婦曰、蛇誘我、我遂食之、"],[1,3,14,"耶和華上帝謂蛇曰、爾旣爲此、較之六畜百獸、必更見詛、且以腹行、畢生食塵、"],[1,3,15,"我以仇隙置爾與婦之間、爰及苗裔、彼將傷爾首、爾將傷其踵、"],[1,3,16,"謂婦曰、我必增爾懷姙之苦、產育劬勞、爾必戀夫、夫必轄爾、"],[1,3,17,"謂亞當曰、爾旣聽婦言、食我所禁之果、土必緣爾見詛、爾畢生勤勞、食其所產、"],[1,3,18,"土將爲爾叢生荊棘蒺藜、汝所食者、田間之蔬、"],[1,3,19,"必汗流浹面、始可得食、迨爾歸土、蓋爾由土出、汝本爲土、終則歸之、"],[1,3,20,"其人名婦曰夏娃、以其爲羣生之母也、"],[1,3,21,"耶和華上帝爲亞當及婦、作皮衣衣之、○"],[1,3,22,"耶和華上帝曰、斯人能別善惡、彷彿我儕、恐其舉手、亦取生命樹果、食之而永生、"],[1,3,23,"遂遣其人出伊甸囿、以耕所自出之土、"],[1,3,24,"旣逐之出、又於伊甸囿東、置基路伯、與旋轉之焰劍、以防守生命樹之途、"],[1,4,1,"亞當與婦夏娃同室、懷姙生該隱、曰、耶和華使我得男、"],[1,4,2,"又生其弟亞伯、亞伯爲牧、該隱爲農、"],[1,4,3,"厥後、該隱以土所產奉耶和華、"],[1,4,4,"亞伯亦奉以首生之羊與脂、耶和華眷顧亞伯、與其祭品、"],[1,4,5,"而不眷顧該隱、與其祭品、該隱盛怒變色、"],[1,4,6,"耶和華曰、爾怒奚爲、變色曷故、"],[1,4,7,"苟爾行善、豈不懽顏、苟行不善、孽伏於門、彼必戀爾、爾其制之、"],[1,4,8,"該隱以告弟亞伯、在於田間、攻而殺之、○"],[1,4,9,"耶和華謂該隱曰、爾弟亞伯安在、曰、不知、我豈防守我弟者乎、"],[1,4,10,"曰、爾何爲耶、汝弟之血有聲、自地籲我、"],[1,4,11,"今地啟口、由於爾手、以受汝弟之血、爾必由地見詛、"],[1,4,12,"汝耕田、地不復効力、爾必流離於地、"],[1,4,13,"該隱謂耶和華曰、我刑之重、實所不堪、"],[1,4,14,"爾今逐我、俾離斯土、不復覿爾面、流離於地、遇我者必殺我、"],[1,4,15,"耶和華曰、凡殺該隱者、受罰七倍、乃賜以表記、免遇之者擊之、○"],[1,4,16,"該隱離耶和華前、往伊甸東挪得地居焉、"],[1,4,17,"該隱與妻同室、懷姙生以諾、建城、卽以其子之名、稱爲以諾、"],[1,4,18,"以諾生以拿、以拿生米戶雅利、米戶雅利生瑪土撒利、瑪土撒利生拉麥、"],[1,4,19,"拉麥娶妻二、一名亞大、一名洗拉、"],[1,4,20,"亞大生雅八、爲居幕牧畜者祖、"],[1,4,21,"其弟猶八、爲鼓琴品簫者祖、"],[1,4,22,"洗拉生土八該隱、乃造銅鐵諸利器者祖、其妹名拿瑪、"],[1,4,23,"拉麥謂妻曰、亞大洗拉歟、其聞我聲、拉麥之婦歟、其聽我言、人害我、我殺之、少者傷我、我戮之、"],[1,4,24,"若殺該隱、受罰七倍、若殺拉麥、必受罰七十七倍、○"],[1,4,25,"亞當復與妻同室、生子命名塞特、曰、上帝爲我立一子、以代亞伯、因其爲該隱所殺也、"],[1,4,26,"塞特亦生子、命名以挪士、是時人始籲耶和華之名、"],[1,5,1,"亞當之裔、其譜如左、上帝造人、乃肖其象、"],[1,5,2,"造男造女、當造之日、錫之以嘏、稱之曰人、"],[1,5,3,"亞當百有三十歲生子、克肖乎己、命名塞特、"],[1,5,4,"後歷八百年、猶生子女、"],[1,5,5,"享壽九百三十歲而終、○"],[1,5,6,"塞特百有五歲、生以挪士、"],[1,5,7,"後歷八百有七年、猶生子女、"],[1,5,8,"享壽九百十有二歲而終、○"],[1,5,9,"以挪士九十歲生該南、"],[1,5,10,"後歷八百十五年、猶生子女、"],[1,5,11,"享壽九百有五歲而終、○"],[1,5,12,"該南七十歲生瑪勒列、"],[1,5,13,"後歷八百四十年、猶生子女、"],[1,5,14,"享壽九百有十歲而終、○"],[1,5,15,"瑪勒列六十五歲生雅列、"],[1,5,16,"後歷八百三十年、猶生子女、"],[1,5,17,"享壽八百九十五歲而終、○"],[1,5,18,"雅列百六十二歲生以諾、"],[1,5,19,"後歷八百年、猶生子女、"],[1,5,20,"享壽九百六十二歲而終、○"],[1,5,21,"以諾六十五歲生瑪土撒拉、"],[1,5,22,"後與上帝偕行、歷三百年、猶生子女、"],[1,5,23,"享壽三百六十五歲、"],[1,5,24,"以諾與上帝偕行、上帝接之、遂不在焉、○"],[1,5,25,"瑪土撒拉百八十七歲生拉麥、"],[1,5,26,"後歷七百八十二年、猶生子女、"],[1,5,27,"享壽九百六十九歲而終、○"],[1,5,28,"拉麥百八十二歲生子、"],[1,5,29,"命名挪亞、曰、耶和華詛地、使我操作勞苦、此子必慰藉我、"],[1,5,30,"後拉麥歷五百九十五年、猶生子女、"],[1,5,31,"享壽七百七十七歲而終、○"],[1,5,32,"挪亞五百歲、生閃含雅弗、"],[1,6,1,"人民繁衍於地、乃生女子、"],[1,6,2,"上帝子見其豔麗、隨意遴選、娶以爲室、"],[1,6,3,"耶和華曰、人旣屬乎形軀、我神必不恆居其中、然其時日、尚可延至一百二十年、"],[1,6,4,"時、有偉人在世、厥後、上帝子與世人之女同室、生子爲上古英武有名之人、○"],[1,6,5,"耶和華鑒觀世人、罪惡貫盈、心所圖維、恆爲邪慝、"],[1,6,6,"乃悔造人於地、心焉憂之、"],[1,6,7,"耶和華曰、將以我所造之人、以及牲畜昆蟲飛鳥、翦滅於地、蓋我造之而悔矣、"],[1,6,8,"惟挪亞沾恩於耶和華前、○"],[1,6,9,"挪亞世紀、其畧如左、彼乃義人、於當世爲完人、與上帝偕行、"],[1,6,10,"所生三子、閃、含、雅弗、"],[1,6,11,"舉世敗壞於上帝前、強暴充塞、"],[1,6,12,"上帝見世敗壞、凡有血氣者、行爲邪僻、○"],[1,6,13,"上帝諭挪亞曰、凡有血氣者、厥期已盡、蓋其強暴遍滿於地、我將倂地而滅之、"],[1,6,14,"爾以柏木造方舟、中分爲艙、內外塗以瀝青、"],[1,6,15,"其式長三百肘、廣五十肘、高三十肘、"],[1,6,16,"舟上作牖、高一肘、旁置一門、必作三層、分上中下焉、"],[1,6,17,"我必使洪水氾濫於地、以滅天下有血氣之生物、凡在地者、淪胥以亡、"],[1,6,18,"惟我與爾約、爾與妻子及媳、悉入於舟、"],[1,6,19,"將諸生物族類、牝牡各一、挈之入舟、同保厥生、"],[1,6,20,"禽鳥牲畜昆蟲、皆各從其類、須以偶至、以全其生、"],[1,6,21,"蓄諸食品、備爾與物所食、"],[1,6,22,"挪亞悉遵上帝命而行、"],[1,7,1,"耶和華諭挪亞曰、爾與眷屬、可入方舟、蓋於斯世、我視爾爲義也、"],[1,7,2,"取畜之潔者、牝牡各七、不潔者、牝牡二、"],[1,7,3,"飛鳥亦取雌雄各七、以存其種、生於全地、"],[1,7,4,"蓋越七日、我將降雨於地、四十晝夜、以殲所造之生物、"],[1,7,5,"挪亞悉遵耶和華命而行、○"],[1,7,6,"洪水淹地時、挪亞六百歲、"],[1,7,7,"與其妻子及媳、俱入方舟以避之、"],[1,7,8,"畜之潔與不潔者、禽鳥及昆蟲、"],[1,7,9,"牝牡爲偶、隨挪亞入舟、循上帝所命、"],[1,7,10,"七日後、洪水氾濫於地、"],[1,7,11,"適挪亞六百歲、二月十七日、巨淵闢其泉、穹蒼啟其牖、"],[1,7,12,"雨降於地、四十晝夜、○"],[1,7,13,"是日挪亞與其妻、及三子、閃、含、雅弗、曁三子之婦、悉入方舟、"],[1,7,14,"百獸六畜、昆蟲禽鳥諸族、皆各從其類、"],[1,7,15,"凡有血氣之生物、各以匹偶、就挪亞入舟、"],[1,7,16,"凡入舟有血氣之物、有牝有牡、循上帝所命、耶和華閉之舟中、"],[1,7,17,"洪水氾濫四旬、水勢洶湧、舟浮於地、"],[1,7,18,"水愈漲溢、舟溯洄於水面、"],[1,7,19,"水勢橫流已甚、天下崇山、俱爲湮沒、"],[1,7,20,"水高於山、十有五肘、岑巖悉沒、"],[1,7,21,"地上衆生、飛鳥、六畜、百獸、昆蟲、以及人類、盡皆滅亡、"],[1,7,22,"凡在陸地、有鼻可通呼吸者、咸就淪喪、"],[1,7,23,"地上衆生、人及牲畜、昆蟲、禽鳥、悉滅於地、獨挪亞與在舟者得存、"],[1,7,24,"水溢於地、凡一百五十日、"],[1,8,1,"上帝眷念挪亞、曁同舟之百獸六畜、令風吹地、水勢漸殺、"],[1,8,2,"淵之泉、天之隙、俱已閉塞、霪雨旣止、"],[1,8,3,"水由地漸退、歷百有五十日而始消、"],[1,8,4,"七月十七日、舟停於亞拉臘山、"],[1,8,5,"水勢漸消、迨十月朔、山巔始見、○"],[1,8,6,"越四旬、挪亞啟舟之牖、"],[1,8,7,"放一鴉出、鴉飛翔還往、以待水涸、"],[1,8,8,"又放一鴿出、欲視水退與否、"],[1,8,9,"鴿無止足處、仍返於舟、挪亞以手接入、蓋水尚瀰漫地面也、"],[1,8,10,"又待七日、復放鴿出、"],[1,8,11,"薄暮鴿歸、口啣橄欖新葉、挪亞則知水退矣、"],[1,8,12,"更待七日、放其鴿、不復返、"],[1,8,13,"適挪亞六百有一歲、正月朔、地上之水盡涸、挪亞遂撤舟蓋、見土壤已乾、"],[1,8,14,"二月二十七日、地已燥、○"],[1,8,15,"上帝諭挪亞曰、"],[1,8,16,"爾與妻子及媳、可出方舟、"],[1,8,17,"凡偕爾之生物、卽禽鳥、牲畜、昆蟲、皆挈之出、使孳生產育、繁衍於地、"],[1,8,18,"挪亞乃與妻子及媳俱出、"],[1,8,19,"百獸、昆蟲、禽鳥、地上諸動物、各從其類、咸出方舟、○"],[1,8,20,"挪亞爲耶和華築壇、取各類禽畜之潔者、獻燔祭於其上、"],[1,8,21,"耶和華聞其馨香、意謂人自幼時、衷懷邪慝、嗣後我不緣之詛地、不復殄滅生物、如前所爲、"],[1,8,22,"地存之時、稼穡寒暑、冬夏晝夜、永不間絕、"],[1,9,1,"上帝錫嘏挪亞、及其子曰、生育衆多、遍滿於地、"],[1,9,2,"地上走獸、空中飛鳥、於爾是畏是懼、以及各類昆蟲、海中諸魚、悉付爾手、"],[1,9,3,"凡有生之動物、皆爲爾食、悉以賜爾、如菜蔬然、"],[1,9,4,"惟肉有血、卽其生命、毋食、"],[1,9,5,"有流爾血、害爾命者、或獸或人、我必討之、凡害人命者、我必討之、"],[1,9,6,"凡流人血者、人必流其血、蓋上帝造人、乃肖己象也、"],[1,9,7,"爾其生育衆多、昌熾繁衍於地、○"],[1,9,8,"上帝諭挪亞與其子曰、"],[1,9,9,"我與爾約、及爾後裔、"],[1,9,10,"並偕爾之生物、卽飛鳥、六畜、走獸、凡出自方舟、在於陸地者、"],[1,9,11,"我與爾約、不復以洪水滅衆生、不復以洪水湮地、"],[1,9,12,"上帝曰、我與爾曁偕爾之生物、立約有徵、以至永世、"],[1,9,13,"置虹雲中、爲我與世立約之徵、"],[1,9,14,"雲覆地時、虹見雲中、"],[1,9,15,"我則念我與爾衆、及凡有血氣之生物、所立之約、不復以洪水滅衆生、"],[1,9,16,"虹在雲中、我則觀之、以記上帝與地上凡有血氣之生物、所立之永約、"],[1,9,17,"上帝諭挪亞曰、我與地上衆生所立之約、此爲其徵、○"],[1,9,18,"挪亞子出方舟者、卽閃、含、雅弗、含生迦南、"],[1,9,19,"由挪亞三子、人民遍滿於地、○"],[1,9,20,"挪亞爲農、植葡萄園、"],[1,9,21,"飲酒而醉、裸體幕中、"],[1,9,22,"迦南父含、見父裸體、出告昆弟、"],[1,9,23,"閃與雅弗、荷衣於肩、卻行而前、以蔽父體、背面不見父裸、"],[1,9,24,"挪亞醉醒、方知仲子所爲、"],[1,9,25,"曰、迦南可詛、必於昆弟爲奴之隸、"],[1,9,26,"又曰、閃之上帝耶和華、宜頌美焉、迦南爲閃之僕、"],[1,9,27,"願上帝昌大雅弗、使居閃幕、迦南亦爲其僕、○"],[1,9,28,"洪水後、挪亞尚歷三百五十年、"],[1,9,29,"享壽九百五十歲而終、"],[1,10,1,"挪亞子閃、含、雅弗、洪水後生子、其裔如左、"],[1,10,2,"雅弗之子、歌篾、瑪各、瑪代、雅完、土巴、米設、提拉、"],[1,10,3,"歌篾之子、亞實基拿、利法、陀迦瑪、"],[1,10,4,"雅完之子、以利沙、他施、基提、多單、"],[1,10,5,"此數人散處州島、各爲方言、族姓、邦國、○"],[1,10,6,"含之子、古實、麥西、弗、迦南、"],[1,10,7,"古實之子、西巴、哈腓拉、撒弗他、拉瑪、撒弗提迦、拉瑪之子、示巴、底但、"],[1,10,8,"古實之裔甯錄、在世始爲英武、"],[1,10,9,"在耶和華前、爲獵夫之雄、故語云、斯人爲獵夫之雄、如甯錄在耶和華前也、"],[1,10,10,"其國肇於巴別、以力、亞甲、甲尼、俱在示拿地、"],[1,10,11,"由彼往亞述、建尼尼微、利河伯、迦拉、"],[1,10,12,"及尼尼微迦拉間之大邑利鮮、"],[1,10,13,"麥西生路低族、亞拿米族、利哈比族、拿弗土希族、"],[1,10,14,"帕斯魯細族、迦斯路希族、迦斐託族、非利士族由迦斯路希而出、○"],[1,10,15,"迦南生冢子西頓、與赫、"],[1,10,16,"及耶布斯族、亞摩利族、革迦撒族、"],[1,10,17,"希未族、亞基族、西尼族、"],[1,10,18,"亞瓦底族、洗瑪利族、哈馬族、此後迦南族姓曼衍、"],[1,10,19,"迦南之境、自西頓、越基拉耳、至迦薩、又越所多瑪、蛾摩拉、押瑪、洗扁、至拉沙、"],[1,10,20,"此乃含之子孫、各依其族姓、方言、疆域、邦國、○"],[1,10,21,"雅弗兄閃亦生子、閃爲希伯全族之祖、"],[1,10,22,"其子乃以攔、亞述、亞法撒、路德、亞蘭、"],[1,10,23,"亞蘭之子、乃烏斯、戶勒、基帖、瑪施、"],[1,10,24,"亞法撒生沙拉、沙拉生希伯、"],[1,10,25,"希伯二子、一名法勒、因是時世人分析也、法勒之弟名約坍、"],[1,10,26,"約坍生亞摩答、沙列、哈薩瑪非、耶拉、"],[1,10,27,"哈多蘭、烏薩、德拉、"],[1,10,28,"俄巴路、亞比瑪利、示巴、"],[1,10,29,"阿斐、哈腓拉、約巴、此皆約坍之子、"],[1,10,30,"其所居之域、自米沙以迄東山西發、"],[1,10,31,"此乃閃之子孫、各依其族姓、方言、疆域、邦國、○"],[1,10,32,"以上所載、皆挪亞子孫之宗族、依其世系邦國、洪水後分析於地、"],[1,11,1,"維時、天下音一語同、"],[1,11,2,"東徙、遇平原於示拿、遂居焉、"],[1,11,3,"彼此互議曰、我其作甎、爇以成之、於是以甎代石、石漆代泥、"],[1,11,4,"又曰、我其築城與臺、臺頂及天、以揚我名、庶免散於四方、"],[1,11,5,"耶和華臨格、欲觀世人所築之城與臺、"],[1,11,6,"曰、斯民爲一、言語亦同、今興是役、後之所謀、末由遏止、"],[1,11,7,"我儕臨格、淆其言語、使彼此不通、"],[1,11,8,"於是耶和華散之四方、遂罷築城之役、"],[1,11,9,"其城名曰巴別、因耶和華在彼淆億兆之言語、散之四方故也、○"],[1,11,10,"閃之裔如左、洪水後二年、閃百歲、生亞法撒、"],[1,11,11,"後歷五百年、猶生子女、"],[1,11,12,"亞法撒三十五歲生沙拉、"],[1,11,13,"後歷四百有三年、猶生子女、"],[1,11,14,"沙拉三十歲生希伯、"],[1,11,15,"後歷四百有三年、猶生子女、"],[1,11,16,"希伯三十四歲生法勒、"],[1,11,17,"後歷四百三十年、猶生子女、"],[1,11,18,"法勒三十歲生拉吳、"],[1,11,19,"後歷二百有九年、猶生子女、"],[1,11,20,"拉吳三十二歲生西鹿、"],[1,11,21,"後歷二百有七年、猶生子女、"],[1,11,22,"西鹿三十歲生拿鶴、"],[1,11,23,"後歷二百年、猶生子女、"],[1,11,24,"拿鶴二十九歲生他拉、"],[1,11,25,"後歷一百十九年、猶生子女、"],[1,11,26,"他拉七十歲生亞伯蘭、拿鶴、哈蘭、○"],[1,11,27,"他拉之裔如左、他拉生亞伯蘭、拿鶴、哈蘭、哈蘭生羅得、"],[1,11,28,"哈蘭先其父死於故土、迦勒底之吾珥、"],[1,11,29,"亞伯蘭拿鶴皆娶室、亞伯蘭妻名撒萊、拿鶴妻名密迦、密迦曁亦迦、俱哈蘭之女、"],[1,11,30,"撒萊不姙、無子、"],[1,11,31,"他拉挈子亞伯蘭、及孫、卽哈蘭子羅得、並子婦撒萊、卽亞伯蘭妻、咸出迦勒底之吾珥、欲往迦南、至於哈蘭居焉、"],[1,11,32,"他拉享壽二百有五歲、終於哈蘭、"],[1,12,1,"耶和華諭亞伯蘭曰、爾其出故土、離戚族、遠父家、往我所示之地、"],[1,12,2,"我將使爾成爲大邦、錫嘏於爾、丕顯爾名、爾爲福源、"],[1,12,3,"祝爾者吾亦祝之、詛爾者吾亦詛之、天下萬族、將緣爾獲福焉、"],[1,12,4,"亞伯蘭循耶和華命而往、羅得偕行、其離哈蘭時、年七十有五、"],[1,12,5,"挈妻撒萊、與姪羅得、曁在哈蘭所積之貨財、所得之婢僕、咸往迦南、卒至其地、"],[1,12,6,"經行至示劍摩利之橡、當時迦南族處其地、"],[1,12,7,"耶和華顯見於亞伯蘭曰、我將以斯土賜爾苗裔、亞伯蘭爲顯見之耶和華、築壇於彼、"],[1,12,8,"由此遷往伯特利東之山、以張其幕、西有伯特利、東有艾、又爲耶和華築壇於彼、而籲其名、"],[1,12,9,"後漸南徙、○"],[1,12,10,"其地適饑且甚、亞伯蘭乃旅於埃及、"],[1,12,11,"將入境、語妻撒萊曰、爾有殊色、我知之矣、"],[1,12,12,"埃及人見爾、必云此其妻也、將殺我而存爾、"],[1,12,13,"請爾謂爲我妹、俾我獲安、緣爾得全吾生、"],[1,12,14,"亞伯蘭至埃及、埃及人見其婦豔麗、"],[1,12,15,"法老之臣觀之、譽於法老前、遂納之入宮、"],[1,12,16,"法老緣婦故、厚遇亞伯蘭、遂有牛羊、牝牡之驢、駱駝、以及婢僕、"],[1,12,17,"耶和華以亞伯蘭妻撒萊故、降巨災於法老、曁其家室、"],[1,12,18,"法老召亞伯蘭曰、爾曷待我如是、彼乃爾妻、胡不告我、"],[1,12,19,"何以稱之爲妹、致我妻之、爾妻在此、可挈之去、"],[1,12,20,"於是命人送亞伯蘭與其妻、及凡所有而去、"],[1,13,1,"亞伯蘭挈妻與羅得、及凡所有、出埃及而南往、"],[1,13,2,"富有金銀牲畜、"],[1,13,3,"自南而行、歷程至伯特利、昔張幕之所、在伯特利與艾之間、"],[1,13,4,"卽前築壇之處、於彼籲耶和華名、"],[1,13,5,"偕行之羅得、亦有牛羊帷幕、"],[1,13,6,"二人之業浩繁、其地莫能容、弗獲同處、"],[1,13,7,"時、迦南與比利洗二族、猶居斯土、亞伯蘭之牧者、與羅得之牧者爭、"],[1,13,8,"亞伯蘭謂羅得曰、爾我乃骨肉之親、不可相爭、爾牧我牧、何競之有、"],[1,13,9,"地非具在爾前乎、爾其與我區別、爾左則我右、爾右則我左、"],[1,13,10,"時、所多瑪蛾摩拉、未爲耶和華所滅、自約但平原、至於瑣珥、土皆潤澤、如耶和華囿、與埃及地等、"],[1,13,11,"羅得舉目觀之、遂擇約但平原而東徙、二人相別、"],[1,13,12,"亞伯蘭居迦南地、羅得寓平原之邑、遷徙其幕、至所多瑪、"],[1,13,13,"所多瑪人作惡、重獲罪於耶和華、○"],[1,13,14,"羅得別後、耶和華諭亞伯蘭曰、爾其由此舉目、以觀東西南北、"],[1,13,15,"凡所見之地、我必賜爾、及爾苗裔、永世弗替、"],[1,13,16,"使爾苗裔如塵埃然、有能核塵埃之數者、則爾苗裔、亦可計矣、"],[1,13,17,"爾起遍歷斯土、縱橫而行、我必以之賜爾、"],[1,13,18,"亞伯蘭遂遷幕、至希伯崙、近幔利之橡而居、爲耶和華築壇焉、"],[1,14,1,"維時、示拿王暗拉非、以拉撒王亞畧、以攔王基大老瑪、戈印王提達、"],[1,14,2,"與所多瑪王比拉、蛾摩拉王比沙、押瑪王示納、洗扁王善以別、及比拉卽瑣珥王戰、"],[1,14,3,"五王咸會於西訂谷、卽今之鹽海、"],[1,14,4,"此五王事基大老瑪、歷十有二年、至十三年而叛、"],[1,14,5,"十四年、基大老瑪與同盟諸王來、擊利乏音族於亞特律加甯、蘇西族於哈麥、以米族於沙微基列亭、"],[1,14,6,"又擊何利族於西珥山、至鄰於曠野之伊勒巴蘭、"],[1,14,7,"四王歸至安密巴、卽加低斯、擊亞瑪力之全境、及居哈洗遜他瑪之亞摩利族、"],[1,14,8,"所多瑪王、蛾摩拉王、押瑪王、洗扁王、比拉卽瑣珥王、皆出、陳於西訂谷、"],[1,14,9,"以敵以攔王基大老瑪、戈印王提達、示拿王暗拉非、以拉撒王亞畧、四王與五王戰、"],[1,14,10,"西訂谷多石漆坑、所多瑪王與蛾摩拉王奔而陷其中、餘遁於山、"],[1,14,11,"四王奪所多瑪蛾摩拉之輜重糧食而去、"],[1,14,12,"亞伯蘭姪羅得居所多瑪、人與物皆被虜、○"],[1,14,13,"有逃遁者、以告希伯來人亞伯蘭、時、亞伯蘭居近亞摩利人幔利之橡、幔利乃以實各亞乃之兄弟、此三人曾與亞伯蘭結盟、"],[1,14,14,"亞伯蘭聞姪被虜、遂率習練之丁壯、素育於家者、三百一十八人、追敵至但、"],[1,14,15,"乘夜分隊進攻、追至大馬色北之何把、"],[1,14,16,"奪回所虜之物、曁姪羅得、與其所有、爰及人民婦女、○"],[1,14,17,"亞伯蘭旣戮基大老瑪與同盟諸王而歸、所多瑪王出、至沙微谷、卽今之王谷以迎之、"],[1,14,18,"撒冷王麥基洗德、爲至高上帝之祭司、攜餅與酒而出、"],[1,14,19,"祝之曰、願天地之主宰、至高之上帝、錫嘏於亞伯蘭、"],[1,14,20,"至高上帝、以敵付於爾手、宜頌美焉、亞伯蘭以其所獲者、什一奉之、"],[1,14,21,"所多瑪王謂亞伯蘭曰、以人歸我、物任爾取、"],[1,14,22,"亞伯蘭曰、我已舉手、指至高之上帝、天地之主宰耶和華而誓、"],[1,14,23,"凡屬爾者、一絲縷、一履帶、吾弗取焉、免爾云、我使亞伯蘭致富、"],[1,14,24,"惟少者所食、曁同行之亞乃、以實各、幔利、所應得者、可任其取之、"],[1,15,1,"嗣後耶和華於異象中、諭亞伯蘭曰、亞伯蘭歟、毋懼、我爲爾盾、大賚於爾、"],[1,15,2,"亞伯蘭曰、主耶和華歟、何以賜我、蓋我無子、承我業者、大馬色人以利以謝也、"],[1,15,3,"又曰、爾未賜我子、育於我家者、將爲我嗣、"],[1,15,4,"耶和華諭之曰、此非爾嗣、必自爾出者、乃爲爾嗣、"],[1,15,5,"遂攜之出、曰、仰觀於天、衆星可核數乎、又曰、汝苗裔必如是、"],[1,15,6,"亞伯蘭信耶和華、耶和華以此爲其義、"],[1,15,7,"又曰、我乃耶和華、昔挈爾出迦勒底之吾珥、將以此地、賜爾承之、"],[1,15,8,"曰、主耶和華歟、我承此地、何以知之、"],[1,15,9,"曰、爲我取三歲之牝牛、牝山羊、牡綿羊、及鳲鳩雛鴿各一、"],[1,15,10,"遂取而中剖之、置之兩旁、使各相對、惟鳥不剖、"],[1,15,11,"有鷙鳥下、集於牲牷、亞伯蘭驅之、"],[1,15,12,"日將入、亞伯蘭酣睡、幽暗臨之、使之恐懼、"],[1,15,13,"耶和華諭之曰、爾當實知、汝裔必旅於異邦、服役良苦、歷四百年、"],[1,15,14,"其所服事之邦、我必鞫之、厥後汝裔、得其重貲以出、"],[1,15,15,"爾必安然歸祖、考終而葬、"],[1,15,16,"越至四世、爾之苗裔、必歸斯土、蓋亞摩利族之罪、尚未貫盈、"],[1,15,17,"日入而昏、有出烟之爐、與已燃之炬、由牲牷中而過、"],[1,15,18,"當日耶和華與亞伯蘭約、曰、我以斯土、賜爾苗裔、自埃及河、至伯拉大河、"],[1,15,19,"卽基尼、基尼洗、甲摩尼、"],[1,15,20,"赫、比利洗、利乏音、"],[1,15,21,"亞摩利、迦南、革迦撒、耶布斯諸族之地、"],[1,16,1,"亞伯蘭妻撒萊不育、有埃及婢名夏甲、"],[1,16,2,"撒萊謂亞伯蘭曰、耶和華禁我生育、請爾與我婢同室、我或可因之得子、亞伯蘭從其言、"],[1,16,3,"其妻撒萊、納埃及婢夏甲於夫亞伯蘭、時、亞伯蘭居迦南、已歷十年、"],[1,16,4,"遂與夏甲同室、夏甲懷孕、自覺有姙、藐視主母、"],[1,16,5,"撒萊謂亞伯蘭曰、我寃在爾、以婢置於爾懷、彼覺有姙、乃藐視我、願耶和華於爾我間判之、"],[1,16,6,"亞伯蘭曰、婢爲爾所治、可任意以待、於是撒萊虐遇之、夏甲逃避焉、"],[1,16,7,"耶和華之使者見之於野、在書珥路之泉旁、"],[1,16,8,"曰、撒萊婢夏甲、適從何來、茲欲何往、曰、逃避主母撒萊、"],[1,16,9,"曰、宜歸主母、服於其下、"],[1,16,10,"又曰、我必使爾苗裔繁衍、不可勝數、"],[1,16,11,"又曰、爾今懷姙、必生男子、可命名以實瑪利、蓋耶和華已聞爾苦也、"],[1,16,12,"彼於人中、將爲野驢、擊衆而衆亦擊之、其所居之地、在同族之東、"],[1,16,13,"夏甲蒙耶和華諭、則稱其名曰監人之上帝、蓋曰、我豈於此、瞻仰夫監我者乎、"],[1,16,14,"故其泉名曰庇耳拉海萊、卽在加低斯巴列之間、"],[1,16,15,"夏甲生子、亞伯蘭命名以實瑪利、○"],[1,16,16,"夏甲生以實瑪利時、亞伯蘭年八十有六、"],[1,17,1,"亞伯蘭年九十有九、耶和華顯見、諭之曰、我乃全能之上帝、爾宜行於我前、而爲完人、"],[1,17,2,"我與爾約、使爾苗裔、繁衍昌熾、"],[1,17,3,"亞伯蘭遂俯伏焉、上帝與之言曰、"],[1,17,4,"我與爾約、爾必爲多族之父、"],[1,17,5,"今而後、爾不復名亞伯蘭、宜名亞伯拉罕、因我立爾爲多族之父也、"],[1,17,6,"我將使爾蕃息、成爲邦國、列王由爾而出、"],[1,17,7,"我必與爾及爾歷世苗裔、立我永約、爲爾及爾苗裔之上帝、"],[1,17,8,"爾今所旅之地、卽迦南全境、我將賜爾、及爾苗裔、以爲永業、我亦爲其上帝、○"],[1,17,9,"上帝諭亞伯拉罕曰、爾與後裔、宜守我約、歷世勿替、"],[1,17,10,"爾中男子、咸宜受割、卽我賜爾及爾後裔、所必守之約、"],[1,17,11,"爾必受割、爲我與爾立約之徵、"],[1,17,12,"爾歷世男子、或生於爾家、或購自異邦、非爾苗裔、旣生八日、皆必受割、"],[1,17,13,"家所生者、金所購者、俱必受割、我約加於爾躬、以爲永約、"],[1,17,14,"惟男子不受割者、是背我約、必絕之民中、○"],[1,17,15,"上帝諭亞伯拉罕曰、爾妻不復稱撒萊、宜稱撒拉、"],[1,17,16,"我必祝之、賜之生子、復錫以嘏、使爲列國之母、列王由之而出、"],[1,17,17,"亞伯拉罕俯伏而哂、竊謂百歲之人、猶能生子乎、撒拉年九十、猶能生育乎、"],[1,17,18,"乃對上帝曰、惟願以實瑪利生存於爾前、"],[1,17,19,"上帝曰、否、爾妻撒拉必生子、可名以撒、我將與彼立約、爲其後裔之永約、"],[1,17,20,"至以實瑪利、我亦允爾、賜之以福、使之蕃息、其裔繁衍昌熾、必出十二牧伯、成爲大族、"],[1,17,21,"惟我與以撒立約、卽明年此時、撒拉所生者、"],[1,17,22,"上帝言竟、離亞伯拉罕而上升、○"],[1,17,23,"是日亞伯拉罕遵上帝命、將其子以實瑪利、曁家所生、金所購之男子、咸與行割、"],[1,17,24,"亞伯拉罕受割時、年九十有九、"],[1,17,25,"其子以實瑪利、十有三歲受割、"],[1,17,26,"父子二人、同日受割、"],[1,17,27,"凡其所屬、或生於家、或購自異邦、均受割焉、"],[1,18,1,"一日亭午、亞伯拉罕坐於幕門、近幔利之橡、耶和華顯見於彼、"],[1,18,2,"亞伯拉罕舉目、見三人對之而立、乃自幕門趨迎、伏地、"],[1,18,3,"曰、若蒙主恩、願勿離僕而去、"],[1,18,4,"容取勺水、以濯爾足、且憩樹下、"],[1,18,5,"旣至僕所、我將取餅少許、壯爾心力而後行、曰、可依汝言、"],[1,18,6,"亞伯拉罕亟入幕、語撒拉曰、速備細麪三細亞、摶之作餅、"],[1,18,7,"又趨至牛羣、擇犢之肥美者付僕、僕急治之、"],[1,18,8,"亞伯拉罕遂以酥與乳、及所治之犢、臚陳其前、自侍樹下、三人食之、"],[1,18,9,"其人曰、爾妻撒拉何在、曰、在幕、"],[1,18,10,"其中一人曰、明年屆期、我必復至、爾妻撒拉將生子、撒拉在其後、於幕門聞此、"],[1,18,11,"亞伯拉罕與撒拉、皆壽高年邁、撒拉癸水已絕、"],[1,18,12,"竊哂曰、我老矣、吾主亦然、庸有喜乎、"],[1,18,13,"耶和華諭亞伯拉罕曰、撒拉何竊哂云、我已年老、詎生育乎、"],[1,18,14,"耶和華豈有難行之事哉、屆期、我將復至、撒拉必生子、"],[1,18,15,"撒拉懼而不承、曰、我未嘗哂也、曰、否、爾實哂、○"],[1,18,16,"三人乃起、觀望所多瑪、亞伯拉罕偕行以送之、"],[1,18,17,"耶和華曰、我之所爲、豈隱於亞伯拉罕乎、"],[1,18,18,"蓋彼必爲強大之族、天下萬民、因之獲福、"],[1,18,19,"我簡之、使命其子及眷屬、守我之道、秉公行義、致耶和華所言、悉以予之、"],[1,18,20,"又曰、所多瑪蛾摩拉罪孽深重、聲聞於我、"],[1,18,21,"我必臨格、監其動作、實如所聞、設若不然、我必知之、○"],[1,18,22,"二人往所多瑪、亞伯拉罕尚立於耶和華前、"],[1,18,23,"進曰、善者惡者、爾豈並滅之乎、"],[1,18,24,"假令邑中有五十義人、亦必翦滅乎、不緣其五十義人、而悉赦宥乎、"],[1,18,25,"善惡倂誅、臧否同待、此斷非爾所爲、鞫天下者、豈不行義乎、"],[1,18,26,"耶和華曰、所多瑪邑、設有五十義人、我必緣此、赦其一方、"],[1,18,27,"亞伯拉罕曰、我雖爲灰塵、敢告於主、"],[1,18,28,"假令五十義者缺其五、豈因缺五人、而滅此一邑乎、曰、設有四十五人、則亦弗滅、"],[1,18,29,"曰、設有四十人、則何如、曰、緣四十人、吾亦弗行是、"],[1,18,30,"曰、願主毋怒、容我言之、假令三十人、則何如、曰、有三十人、亦弗行是、"],[1,18,31,"曰、敢告於主、假令二十人、則何如、曰、緣二十人、我亦不滅、"],[1,18,32,"曰、願主毋怒、容我言之、惟此一次、假令十人、則何如、曰、緣十人、吾亦弗滅、"],[1,18,33,"耶和華言竟而往、亞伯拉罕乃歸、"],[1,19,1,"日暮、二天使至所多瑪、時、羅得坐於邑門、見之、遂起迎迓、伏地而拜、"],[1,19,2,"曰、吾主請返、以臨僕舍、濯足而宿、夙興以行、曰、否、我將竟夕於衢、"],[1,19,3,"羅得亟促之、乃旋踵、入其室、遂爲之設筵、炊無酵餅、天使食之、"],[1,19,4,"未及寢、所多瑪邑人、少長咸集、環其室、"],[1,19,5,"呼羅得曰、昏暮就汝之人何在、可出之、遂吾所欲、"],[1,19,6,"羅得出、閉門而就之、"],[1,19,7,"曰、請我兄弟、勿作斯惡、"],[1,19,8,"我有二女、尚未適人、容我出之、任爾所爲、惟此二人、旣臨我舍、請毋擾之、"],[1,19,9,"衆曰、退、又曰、斯人旅於斯土、乃欲爲士師、今將害爾、較彼尤甚、遂迫羅得、徑前欲破其門、"],[1,19,10,"天使手援羅得入、而閉其門、"],[1,19,11,"使衆於門外、少長目眯、索門致倦、○"],[1,19,12,"二人謂羅得曰、於此、爾尚有所屬乎、或子、或女、或壻、及邑中屬爾者、俱攜之出、"],[1,19,13,"我將滅此一方、因其罪惡甚大、聲聞於耶和華、故遣我滅之、"],[1,19,14,"羅得出、告聘其女之壻曰、爾起出此、耶和華將滅是邑、其壻聞之、以爲戲言、"],[1,19,15,"及旦、天使促羅得曰、起、挈若妻、曁在此二女、恐因斯邑之罪、共罹滅亡、"],[1,19,16,"羅得遲延、二人執其手、與妻及女、咸引之出、置於邑外、蓋耶和華矜之也、"],[1,19,17,"旣出、謂之曰、爾其遁逃、以全生命、毋返顧、毋止平原、宜避於山、免爾滅亡、"],[1,19,18,"羅得曰、主歟、勿爾、"],[1,19,19,"僕蒙爾恩、大施仁慈、以全我生、今我不能避於山、恐遭災禍而殞、"],[1,19,20,"前有一邑、旣小且近、容我遁彼、以全我生、此非蕞爾之區乎、"],[1,19,21,"曰、斯事我亦允爾、所言之邑、我不翦滅、"],[1,19,22,"汝其速遁於彼、蓋爾未至、吾不能有所爲、故其邑名曰瑣珥、○"],[1,19,23,"羅得入瑣珥時、日已出、"],[1,19,24,"耶和華自天雨火硫於所多瑪、蛾摩拉、"],[1,19,25,"於是城邑、平壤、居民、及土所產、無不毀滅、"],[1,19,26,"羅得妻隨行返顧、變爲鹽柱、"],[1,19,27,"亞伯拉罕夙興、至昔立於耶和華前之處、"],[1,19,28,"瞻望所多瑪蛾摩拉、與平原全境、見其烟燄上騰、如出於爐、○"],[1,19,29,"當上帝殄滅平原諸邑、傾覆羅得所居之邑時、眷念亞伯拉罕、拯羅得出於災、○"],[1,19,30,"羅得懼居瑣珥、挈二女去彼、而入於山、同處巖穴、"],[1,19,31,"長女謂季女曰、吾父已老、斯土又無人與我爲偶、以循人道、"],[1,19,32,"莫若使父飲酒、而與偕寢、以存其後、"],[1,19,33,"是夜飲父以酒、長女與之寢、女之臥起、父不及知、"],[1,19,34,"翌日、長女謂季女曰、我昨與父偕寢、今夕仍飲以酒、爾可偕寢、以存其後、"],[1,19,35,"是夜亦飲父以酒、季女偕寢、女之臥起、父亦不知、"],[1,19,36,"如是、羅得二女由父懷姙、"],[1,19,37,"長女生子、命名摩押、爲摩押族之祖、"],[1,19,38,"季女亦生子、命名便亞米、爲亞捫族之祖、"],[1,20,1,"亞伯拉罕南徙、旅於加低斯書珥間之基拉耳、"],[1,20,2,"稱其妻撒拉爲妹、基拉耳王亞比米勒遣人取之、"],[1,20,3,"夜夢上帝臨之曰、爾其死矣、蓋所取之婦、乃他人之妻也、"],[1,20,4,"亞比米勒未近婦身、曰、主歟、爲義之民、亦滅之乎、"],[1,20,5,"彼非對我稱婦爲妹、婦亦稱之爲兄乎、我之爲此、心正手潔、"],[1,20,6,"上帝曰、我知爾爲此、心本端正、故我阻爾、免玷婦身、干咎於我、"],[1,20,7,"今以婦歸其夫、彼乃先知、將爲爾祈、以全汝生、如不歸之、宜知爾與眷聚、必皆死亡、○"],[1,20,8,"亞比米勒夙興、召其諸僕、告以斯事、諸僕懼甚、"],[1,20,9,"亞比米勒召亞伯拉罕曰、爾於我儕、所爲何耶、我何事獲罪爾、乃陷我於重罪、爰及我國、爾之行於我者、實非所宜、"],[1,20,10,"又曰、爾何所見而行是、"],[1,20,11,"亞伯拉罕曰、我意此邦不畏上帝、必緣我妻而殺我、"],[1,20,12,"彼誠我妹、同父異母、我娶爲室、"],[1,20,13,"昔上帝命我離父家、遨遊於外、我謂婦曰、所適之邦、必稱我爲兄、是卽待我以恩也、"],[1,20,14,"亞比米勒遂以牛羊僕婢賜之、幷歸其妻撒拉、"],[1,20,15,"曰、吾之土地、具在爾前、可任意居之、"],[1,20,16,"謂撒拉曰、我以千金賜爾兄、以蔽爾容於衆前、則爾所行、無不義矣、"],[1,20,17,"亞伯拉罕祈於上帝、遂醫亞比米勒、與妻及婢、使能生育、"],[1,20,18,"蓋耶和華以撒拉故、曾使亞比米勒之眷聚不姙也、"],[1,21,1,"耶和華踐其前言、眷顧撒拉、予以所許、"],[1,21,2,"亞伯拉罕暮年、撒拉懷姙、屆上帝所言之期、誕生男子、"],[1,21,3,"亞伯拉罕以其所生之子、命名以撒、"],[1,21,4,"越至八日、遵上帝命、爲之行割、"],[1,21,5,"當以撒生時、亞伯拉罕適百歲、"],[1,21,6,"撒拉曰、上帝使我笑、凡聞之者、將與我同笑、"],[1,21,7,"又曰、孰曾告亞伯拉罕曰、撒拉將哺子乎、而我於其暮年、爲之生子矣、○"],[1,21,8,"子長而斷乳、斷乳之日、亞伯拉罕設盛饌、"],[1,21,9,"埃及婢夏甲、從亞伯拉罕所生之子戲謔之、撒拉見之、"],[1,21,10,"語亞伯拉罕曰、出此婢及其子、婢之子不得與我子以撒同嗣業、"],[1,21,11,"亞伯拉罕爲子之故、深以爲憂、"],[1,21,12,"上帝諭之曰、勿爲孺子曁爾婢而憂、可聽撒拉所言、蓋出自以撒者、得稱爲爾裔、"],[1,21,13,"然婢之子、亦屬爾裔、我必使之爲國、"],[1,21,14,"亞伯拉罕夙興、取餅、及革囊盛水、與夏甲、置之於肩、使攜子去、遂往、至別是巴野、迷其途、"],[1,21,15,"囊水旣罄、乃置子於小樹下、"],[1,21,16,"相去一矢、曰、我不忍見子死亡、相對而坐、揚聲號哭、"],[1,21,17,"上帝聞孺子聲、其使自天呼夏甲曰、夏甲、何事耶、爾勿懼、孺子在彼、上帝已聞其聲、"],[1,21,18,"起而扶之、我將使之成爲大國、"],[1,21,19,"上帝明其目、卽見水泉、遂往、以水充革囊、飲孺子、"],[1,21,20,"上帝佑其孺子、長而居野、長於弧矢、"],[1,21,21,"旅巴蘭野、母爲之娶埃及女爲室、○"],[1,21,22,"維時、亞比米勒與其軍長非各、謂亞伯拉罕曰、汝凡所爲、上帝偕之、"],[1,21,23,"今汝在此、當指上帝而誓、毋欺我曁我子孫、依我所厚待爾者、待我及爾所旅之邦、"],[1,21,24,"亞伯拉罕曰、我誓之、"],[1,21,25,"先是、有井爲亞比米勒僕強據、亞伯拉罕責之、"],[1,21,26,"亞比米勒曰、是誰所爲、吾弗知也、爾未告我、今日我始聞之、"],[1,21,27,"亞伯拉罕以牛羊饋亞比米勒、互相結約、"],[1,21,28,"又以牝羔七、別置一處、"],[1,21,29,"亞比米勒曰、此七牝羔、別置一處、何也、"],[1,21,30,"曰、爾必由我受之、以爲我鑿此井之據、"],[1,21,31,"因二人相誓於彼、故名其地曰別是巴、"],[1,21,32,"彼旣立約於別是巴、亞比米勒與其軍長非各啟行、歸非利士地、"],[1,21,33,"亞伯拉罕植垂絲柳於別是巴、禱永生上帝耶和華之名、"],[1,21,34,"旅於非利士地、歷有多日、"],[1,22,1,"厥後、上帝試亞伯拉罕、呼之曰、亞伯拉罕、曰、我在此、"],[1,22,2,"曰、攜汝所愛獨生之子以撒、往摩利亞地、在我所示之山、獻爲燔祭、"],[1,22,3,"亞伯拉罕夙興、備驢、攜二僕及子以撒、劈柴爲燔、詣上帝所示之地、"],[1,22,4,"越至三日、舉目遙瞻其處、"],[1,22,5,"謂僕曰、爾與驢姑待於此、我與孺子往彼、崇拜卽返、"],[1,22,6,"遂以燔柴、付於其子以撒負之、己則持火及刃、與之偕行、"],[1,22,7,"以撒曰、父歟、曰、吾子、余在此、曰、火與柴則有之矣、而所燔之羔安在、"],[1,22,8,"曰、吾子、上帝將自備羔、以爲燔祭、於是偕行、○"],[1,22,9,"至上帝所示之處、亞伯拉罕築壇、臚列其柴、縛子以撒、置於其上、"],[1,22,10,"舉手執刃、將宰其子、"],[1,22,11,"耶和華之使者自天呼曰、亞伯拉罕、亞伯拉罕、曰、我在此、"],[1,22,12,"曰、爾於孺子、勿著手、勿加傷、蓋爾於我、不惜獨生之子、我知爾寅畏上帝矣、"],[1,22,13,"亞伯拉罕舉目以觀、見有牡綿羊在後、角繫林叢、遂往取之、獻爲燔祭、以代其子、"],[1,22,14,"稱其地曰耶和華亦勒、迄今尚有人云、在耶和華山必預備也、"],[1,22,15,"耶和華之使者自天復呼亞伯拉罕、"],[1,22,16,"曰、耶和華云、爾旣行是、不惜獨生之子、我則指己而誓、"],[1,22,17,"必錫爾嘏、昌熾爾裔、如天上之星、如海濱之沙、爾裔必據諸敵之邑、"],[1,22,18,"緣爾遵我命、天下萬民、將因爾裔而獲福、"],[1,22,19,"亞伯拉罕返至僕所、起而偕行、至別是巴居焉、○"],[1,22,20,"自時厥後、或告亞伯拉罕曰、密迦從爾弟拿鶴亦生子、"],[1,22,21,"長子烏斯、及弟布斯、與亞蘭父基母利、"],[1,22,22,"曁基薛、哈瑣、必達、益拉、彼土利、"],[1,22,23,"此八人、皆密迦從亞伯拉罕弟拿鶴所生、彼土利生女利百加、"],[1,22,24,"拿鶴妾名流瑪、生子提八、迦含、他轄、瑪迦、"],[1,23,1,"撒拉享壽一百二十七歲、"],[1,23,2,"卒於迦南之基列亞巴、卽希伯崙、亞伯拉罕來、爲之哀哭、"],[1,23,3,"後起離尸、語赫人曰、"],[1,23,4,"我於爾中爲賓旅、請以塚地與我、葬我死者、使之離我、"],[1,23,5,"赫人曰、"],[1,23,6,"吾主、請聽、爾於我中、爲上帝之牧伯、在我塚地間、擇其佳域、以葬爾之死者、我中無人禁之、"],[1,23,7,"亞伯拉罕起、向土人赫族而鞠躬、"],[1,23,8,"曰、爾若有意容我得葬死者、使之離我、則請聽我言、爲我求瑣轄子以弗崙、"],[1,23,9,"以其田隅之麥比拉穴、足其價值、售我爲業、俾於爾中得有塚地、"],[1,23,10,"以弗崙、赫族也、時、坐於赫人中、於入邑門之赫人前、謂亞伯拉罕曰、"],[1,23,11,"主歟、勿爾、請聽我言、我以田及田之穴、於我同族人前予爾、可葬汝之死者、"],[1,23,12,"亞伯拉罕遂向土人而鞠躬、"],[1,23,13,"當衆前謂以弗崙曰、請聽我言、我將以金購田、爾其受之、使我得葬死者、"],[1,23,14,"以弗崙曰、吾主、請聽、其田值金四百舍客勒、"],[1,23,15,"爾我之間、何足算哉、請葬死者、"],[1,23,16,"亞伯拉罕從以弗崙言、依其當赫人前所定、權商賈通用之金四百舍客勒予之、○"],[1,23,17,"如是、以弗崙之田、在麥比拉、與幔利相對者、田與穴、曁四周之林木、"],[1,23,18,"於入邑門之赫人前、俱定與亞伯拉罕爲業、"],[1,23,19,"厥後亞伯拉罕、葬其妻撒拉於對乎幔利、麥比拉田之穴、幔利卽希伯崙、在迦南地、"],[1,23,20,"田及穴、赫人定與亞伯拉罕爲塚地、"],[1,24,1,"亞伯拉罕壽高年邁、耶和華於凡事錫之嘏、"],[1,24,2,"亞伯拉罕語其家宰、卽司全業之老僕曰、爾其置手於我髀下、"],[1,24,3,"指天地之上帝耶和華而誓、我居迦南人中、勿娶其女、爲我子婦、"],[1,24,4,"必返故土、在戚族中、爲我子以撒娶焉、"],[1,24,5,"僕曰、假令其女不欲從我來此、我以爾子仍歸故鄉可乎、"],[1,24,6,"亞伯拉罕曰、愼勿使我子歸故鄉、"],[1,24,7,"天上上帝耶和華、昔導我出父家、離故土、誓以斯地錫我苗裔、必遣厥使導爾、使爲我子娶於故土、"],[1,24,8,"設女不欲從爾、則此誓與爾無與、惟不可挈我子返於故鄉、"],[1,24,9,"僕遂置手於其主亞伯拉罕髀下、如命而誓、○"],[1,24,10,"於是僕自其主之駝中取十、並攜主家之佳品、起而往米所波大米、詣拿鶴所居之邑、"],[1,24,11,"日暮、衆女出汲時、僕使駝伏於邑外井旁、"],[1,24,12,"曰、吾主亞伯拉罕之上帝耶和華歟、祈施恩於我主亞伯拉罕、使我今日所遇順適、"],[1,24,13,"我立井旁、邑人之女、出以汲水、"],[1,24,14,"我將謂一女曰、請爾下缾飲我、彼若云請飲、亦飲爾駝、則願其女爲爾所定、與爾僕以撒爲妻、由此可知爾施恩於我主、"],[1,24,15,"言未旣、利百加肩負缾出、彼乃亞伯拉罕弟拿鶴、與妻密迦之子彼土利所生者、"],[1,24,16,"女容甚麗、尚爲處子、未曾適人、臨井汲水、盈缾而上、"],[1,24,17,"僕趨迎之、曰、請以缾水、飲我少許、"],[1,24,18,"曰、吾主、請飲、乃急下缾以飲之、"],[1,24,19,"飲畢、又曰、我更汲水、以飲爾駝、迨足其量、"],[1,24,20,"遂急傾缾於槽、復趨井而汲、以飲羣駝、"],[1,24,21,"僕目之、默然弗語、欲知耶和華果賜坦途否、"],[1,24,22,"俟駝飲竟、乃取金環、重半舍客勒、金釧二、重十舍客勒、"],[1,24,23,"謂之曰、汝誰氏女、請告我、汝父之家、有隙地以寓我乎、"],[1,24,24,"曰、我乃拿鶴與密迦子彼土利之女、"],[1,24,25,"又曰、我家芻糧具足、亦有隙地、可以容宿、"],[1,24,26,"僕遂俯首、崇拜耶和華、"],[1,24,27,"曰、吾主亞伯拉罕之上帝耶和華、宜頌美焉、彼於我主、不絕其仁與誠、且於途中導我、至吾主昆弟之家、○"],[1,24,28,"女趨告其母家、"],[1,24,29,"利百加有兄名拉班、見環與手釧、聞妹利百加述僕所言、則趨外而迎之、"],[1,24,30,"時、僕尚立井旁、駝亦在側、"],[1,24,31,"語之曰、爾蒙耶和華錫嘏者、請入、奚竚於外、我已備室、駝亦有所、"],[1,24,32,"僕遂入室、拉班釋駝之負、給以芻糧、取水與僕及從者濯足、"],[1,24,33,"陳食其前以食之、僕曰、吾事未述、不敢先食、曰、請述之、"],[1,24,34,"曰、我乃亞伯拉罕僕、"],[1,24,35,"耶和華錫嘏吾主甚厚、使之昌大、賜以金銀僕婢、牛羊駝驢、"],[1,24,36,"主母撒拉、老而生子、我主所有、悉予斯男、"],[1,24,37,"吾主令我誓曰、余居迦南、勿娶其女、爲我子婦、"],[1,24,38,"必詣父家戚屬、爲子娶室、"],[1,24,39,"我謂主曰、恐女不從我、"],[1,24,40,"主曰、我所事之耶和華、將遣厥使偕爾、賜爾坦途、可於父家戚屬中、爲子娶室、"],[1,24,41,"設或造我戚屬、而彼不與、則此誓與爾無與、"],[1,24,42,"今日我至井旁、禱曰、吾主亞伯拉罕之上帝耶和華、如果賜我坦途、"],[1,24,43,"茲立井旁、有女出汲、我謂之曰、請以缾水、飲我少許、"],[1,24,44,"若言且飲、亦爲駝汲、則願其女爲耶和華所定、以與吾主之子、"],[1,24,45,"默祝未竟、而利百加出、負缾於肩、臨井以汲、我謂之曰、請予我飲、"],[1,24,46,"女卽下缾、曰、且飲、吾亦飲駝、我遂飲、女亦飲駝、"],[1,24,47,"我問曰、汝誰氏女、曰、我乃拿鶴與密迦子彼土利之女也、我遂置環於其鼻、著釧於其手、"],[1,24,48,"俯首崇拜、頌美吾主亞伯拉罕之上帝耶和華、導我以正途、使取主弟之孫、爲主子之室、"],[1,24,49,"爾若待我主以仁誠、則告我、否亦告我、使我知所左右、○"],[1,24,50,"拉班與彼土利曰、斯事由於耶和華、我儕不能與汝言其是非、"],[1,24,51,"利百加在爾前、可攜之歸、與主之子爲室、遵耶和華命、"],[1,24,52,"亞伯拉罕之僕聞言、俯伏於地、崇拜耶和華、"],[1,24,53,"出金銀器皿與衣、饋利百加、又以寶物饋其兄、及其母、"],[1,24,54,"僕與從者飲食而宿、夙興、曰、願遣歸我主、"],[1,24,55,"利百加兄與其母曰、容女少留、偕我居處、歷至旬日、然後啟行、"],[1,24,56,"曰、勿阻我、耶和華賜我坦途、請遣歸我主、"],[1,24,57,"曰、可呼女而問之、"],[1,24,58,"乃呼利百加曰、爾願與此人偕行乎、曰、願之、"],[1,24,59,"遂遣利百加與其媼、同亞伯拉罕僕、曁從者而去、"],[1,24,60,"祝利百加曰、願妹爲億兆之母、爾裔獲仇敵之邑、○"],[1,24,61,"利百加起、與婢乘駝從僕、僕攜之歸、"],[1,24,62,"時、以撒居南方、適自庇耳拉海萊來、"],[1,24,63,"暮出於田、默然靜思、舉目見羣駝至、"],[1,24,64,"利百加望見以撒、乃下駝、"],[1,24,65,"問僕曰、遊於田而迓我者爲誰、曰、我主也、利百加遂取帕自蒙、"],[1,24,66,"僕以所爲悉告以撒、"],[1,24,67,"以撒導利百加入母撒拉之幕、娶以爲室、且愛慕之、自母沒後、至此始獲慰藉、"],[1,25,1,"亞伯拉罕繼娶一妻、名基土拉、"],[1,25,2,"生心蘭、約珊、米但、米甸、伊施巴、書亞、"],[1,25,3,"約珊生示巴、底但、底但生亞書利族、利都是族、利烏米族、"],[1,25,4,"米甸生以法、以弗、哈諾、亞比大、以勒大、咸屬基土拉之裔、"],[1,25,5,"亞伯拉罕以凡所有、遺於以撒、"],[1,25,6,"衆妾之子、貺以財物、當其存時、遣往東方、以避以撒、"],[1,25,7,"亞伯拉罕享壽一百七十五歲、"],[1,25,8,"壽高年邁、氣絕而終、歸於列祖、"],[1,25,9,"其子以撒、與以實瑪利、葬之於麥比拉穴、與幔利相對、赫人瑣轄子以弗崙之田、"],[1,25,10,"卽亞伯拉罕購自赫人者、亞伯拉罕與妻撒拉、同葬於此、"],[1,25,11,"亞伯拉罕卒後、上帝錫嘏其子以撒、以撒附庇耳拉海萊而居、○"],[1,25,12,"亞伯拉罕子以實瑪利、卽撒拉婢埃及女夏甲所生者、"],[1,25,13,"其裔、循其世系名氏、記列於左、以實瑪利長子尼拜約、及基達、亞德別、米比衫、"],[1,25,14,"米施瑪、度瑪、瑪撒、"],[1,25,15,"哈大、提瑪、伊突、拿非施、基底瑪、"],[1,25,16,"此皆以實瑪利諸子之名、隨其鄉里屯營、爲十二族之牧伯、"],[1,25,17,"以實瑪利享壽一百三十七歲、氣絕而終、歸於列祖、"],[1,25,18,"其裔所居之地、在其同族之東、自哈腓拉、至埃及左之書珥、達於亞述、○"],[1,25,19,"以撒之紀如左、亞伯拉罕生以撒、"],[1,25,20,"以撒年四十、娶利百加爲妻、卽巴旦亞蘭地、亞蘭人彼土利之女、拉班之妹、"],[1,25,21,"以撒之妻不姙、以撒爲之祈耶和華、耶和華允之、利百加遂懷姙、"],[1,25,22,"腹中雙胎相爭、利百加曰、如果有此、我何以爲生、乃往問於耶和華、"],[1,25,23,"耶和華曰、爾胎所懷、乃爲二國、自腹而出、分爲二民、此強於彼、長事其幼、"],[1,25,24,"屆期孿生、"],[1,25,25,"首產者紅、遍體有毛如裘、命名以掃、"],[1,25,26,"後出之弟、手執兄踵、命名雅各、二子生時、以撒年已六旬、○"],[1,25,27,"二子旣長、以掃善獵、遨遊於野、雅各恬靜、居處於幕、"],[1,25,28,"以撒嗜野味、愛以掃、利百加愛雅各、"],[1,25,29,"一日雅各煮羹、以掃自野歸、憊甚、"],[1,25,30,"謂雅各曰、我憊矣、以此紅者食我、緣是、以掃又名以東、"],[1,25,31,"雅各曰、爾以長子之業、先鬻於我、"],[1,25,32,"以掃曰、我將死矣、長子之業、於我奚裨、"],[1,25,33,"雅各曰、先誓於我、以掃誓之、於是以其長子之業、鬻於雅各、"],[1,25,34,"雅各乃以餅及豆羹予以掃、以掃食之飲之、起而往、其藐視長子之業如此、"],[1,26,1,"亞伯拉罕時、歲饑、以撒時、其地又饑、乃往基拉耳、詣非利士王亞比米勒、"],[1,26,2,"耶和華顯見、諭以撒曰、毋往埃及、必居我所示之地、"],[1,26,3,"旅於斯土、我將偕爾、錫爾以嘏、以此列邦賜爾、爰及苗裔、昔與乃父亞伯拉罕所誓者、我必踐其言、"],[1,26,4,"繁衍爾裔、如天之星、以此列邦予之、天下萬民、因之獲福、"],[1,26,5,"蓋亞伯拉罕聽我言、奉我令、遵我誡命、典章法度、"],[1,26,6,"以撒旅於基拉耳、"],[1,26,7,"居民詢及其妻、曰、我妹也、蓋有殊色、故懼以妻相稱、恐居民爲利百加而殺之也、"],[1,26,8,"居彼日久、非利士王亞比米勒自牖窺之、適以撒與利百加嬉戲、"],[1,26,9,"召之曰、彼果爾妻、何謂爲妹、曰、竊恐因之見殺、"],[1,26,10,"亞比米勒曰、爾於我儕、所爲何耶、幾致民中有人與爾妻寢、陷我於罪、"],[1,26,11,"乃諭民曰、犯此人與其妻者、殺無赦、○"],[1,26,12,"以撒耕稼於斯、是年獲有百倍、耶和華錫之嘏、"],[1,26,13,"遂以昌大、日增月盛、竟成巨富、"],[1,26,14,"牛羊成羣、僕從甚衆、非利士人妒之、"],[1,26,15,"昔其父亞伯拉罕僕所鑿之井、非利士人塞之以土、"],[1,26,16,"亞比米勒謂以撒曰、爾較我強大、請去我、"],[1,26,17,"遂去之、張幕於基拉耳谷居焉、○"],[1,26,18,"亞伯拉罕所鑿之井、非利士人塞之、以撒復鑿、以父所名名之、"],[1,26,19,"以撒僕鑿井於谷中、得活泉、"],[1,26,20,"基拉耳牧者與以撒牧者爭曰、此水屬我、緣相爭故、以撒名其井曰埃色、"],[1,26,21,"又鑿一井、猶相爭、故名之曰西提拿、"],[1,26,22,"以撒離彼、復鑿一井、乃不相爭、故名之曰利河伯、曰、耶和華使我寬舒、將繁衍於斯土、○"],[1,26,23,"以撒去彼、往別是巴、"],[1,26,24,"是夜耶和華顯見、諭之曰、我乃爾父亞伯拉罕之上帝、勿懼、爲我僕亞伯拉罕故、我必偕爾、錫爾以嘏、繁衍爾裔、"],[1,26,25,"以撒築壇於彼、籲耶和華名、遂張幕、僕鑿井焉、○"],[1,26,26,"亞比米勒與友亞戶撒、及軍長非各、自基拉耳來見之、"],[1,26,27,"以撒曰、昔爾憾我屛我、今何來見、"],[1,26,28,"曰、我儕知耶和華偕汝、竊謂爾我間當立誓、互相結盟、"],[1,26,29,"俾爾無害於我、如我未害於爾、惟厚待爾、送爾安然以歸、爾乃耶和華所錫嘏者、"],[1,26,30,"以撒遂爲之設筵、式飲式食、"],[1,26,31,"夙興相誓、以撒送之、安然以歸、"],[1,26,32,"是日以撒僕以鑿井事來告曰、我得水矣、"],[1,26,33,"乃名之曰示巴、故其邑名別是巴、至於今日、○"],[1,26,34,"以掃年四十、娶赫人比利之女猶滴、與赫人以倫之女巴實抹爲室、"],[1,26,35,"二婦使以撒與利百加心憂、"],[1,27,1,"以撒年邁、目眊不明、召長子以掃曰、吾子、曰、我在此、"],[1,27,2,"曰、吾老矣、不知何日而死、"],[1,27,3,"其執爾器、弓與矢囊、往於田野、爲我行獵、"],[1,27,4,"以作嘉肴、依我所嗜、進與我食、及我未死、爲爾祝嘏、○"],[1,27,5,"以撒語子以掃之言、利百加聞之、"],[1,27,6,"以掃旣適野獵獸、利百加謂子雅各曰、我聞爾父謂爾兄以掃云、"],[1,27,7,"可獲野獸、以作嘉肴、與我食之、及我未死、於耶和華前、爲爾祝嘏、"],[1,27,8,"我子須聽我言、循我所命、"],[1,27,9,"可往羊羣、取山羊之美羔二、我作嘉肴、依父所嗜、"],[1,27,10,"爾進於父食之、及其未死、爲爾祝嘏、"],[1,27,11,"雅各謂母曰、我兄遍體有毛、我乃光潔、"],[1,27,12,"設父捫我、以我欺父、恐求祝而反見詛、"],[1,27,13,"母曰、吾子、爾若見詛、我自當之、第從我言、往取其羔、"],[1,27,14,"乃往取與母、母作嘉肴、依父所嗜、"],[1,27,15,"長子以掃有美服、存於室、利百加取之、以衣季子雅各、"],[1,27,16,"又以山羊羔皮蒙其手、及光潔之頸、"],[1,27,17,"以所作之嘉肴與餅、付子雅各、○"],[1,27,18,"雅各進於父曰、父歟、曰、我在此、吾子、爾爲誰、"],[1,27,19,"雅各曰、我乃長子以掃、遵命而行、請起而坐、食所獵者、祝嘏於我、"],[1,27,20,"以撒曰、吾子獲之、何若是之速也、曰、爾上帝耶和華使我疾獲之、"],[1,27,21,"以撒曰、吾子來前、俾我捫爾、果我子以掃否、"],[1,27,22,"雅各進前、以撒捫之、曰、聲則雅各聲、手則以掃手也、"],[1,27,23,"因其手有毛、似兄以掃、末由分辨、遂爲祝嘏、"],[1,27,24,"又曰、爾誠我子以掃否、曰、然、"],[1,27,25,"曰、以子所獲者陳於前、待我食之、爲爾祝嘏、乃進前、父食之、又奉酒、亦飲之、"],[1,27,26,"以撒曰、吾子來前、與我接吻、"],[1,27,27,"遂前吻父、父聞其衣馨香祝曰、吾子之馨香、如耶和華所祚之田然、"],[1,27,28,"願上帝錫爾天之甘露、地之沃壤、穀酒豐盛、"],[1,27,29,"兆民服役爾側、列國拜跪爾前、兄弟尊爾爲主、同胞拜跪於爾、詛爾者必見詛、祝爾者必見祝、○"],[1,27,30,"以撒祝竟、雅各甫離父出、適其兄以掃獵而歸、"],[1,27,31,"亦作嘉肴、進於父、曰、請父起、食子所獵、祝嘏於我、"],[1,27,32,"其父以撒曰、爾爲誰、曰、長子以掃、"],[1,27,33,"以撒戰慄不勝、曰、爾未至、誰進嘉肴於我、我已食之、爲彼祝嘏、彼必承之、"],[1,27,34,"以掃聞言、大聲痛哭、曰、請父亦爲我祝嘏、"],[1,27,35,"曰、爾弟來、施其詭譎、奪爾福祉、"],[1,27,36,"以掃曰、宜其名雅各、彼欺我者再、昔奪我長子之業、今又奪我之嘏耶、又曰、豈更無嘏、可爲我祝乎、"],[1,27,37,"以撒曰、我已立雅各爲主、兄弟皆爲其役、以穀與酒供之、吾子、今將爲爾何爲乎、"],[1,27,38,"以掃曰、父之祝嘏、豈惟一而已乎、父歟、請亦祝我、遂大聲號哭、"],[1,27,39,"以撒曰、爾所居之地、遠乎沃壤、天露不及、"],[1,27,40,"爾必恃刃以圖生、服役於爾弟、爾得釋時、則脫其軛於爾項、○"],[1,27,41,"以掃因父爲雅各祝嘏、懷恨雅各、竊言父喪伊邇、我必殺弟、"],[1,27,42,"或以長子言告利百加、遂召季子曰、兄將殺爾、以雪其恨、"],[1,27,43,"吾子宜從我言、奔哈蘭、投我兄拉班、"],[1,27,44,"偕居數日、待爾兄怒息、"],[1,27,45,"其氣已平、忘爾所爲、我則遣人召爾、奚爲一日喪二子乎、"],[1,27,46,"利百加謂以撒曰、緣赫人女、我厭厥生、倘雅各亦娶赫族如此之女、我生何益之有、"],[1,28,1,"以撒召雅各、爲之祝嘏、囑曰、毋娶迦南女爲室、"],[1,28,2,"起往巴旦亞蘭、詣爾母父彼土利家、娶爾母兄拉班之女爲室、"],[1,28,3,"願全能之上帝、錫嘏於爾、使爾生育繁衍、爲衆族祖、"],[1,28,4,"以亞伯拉罕之嘏錫爾、及爾苗裔、俾承所旅之地、卽昔上帝所賜亞伯拉罕者、"],[1,28,5,"以撒遣雅各、遂往巴旦亞蘭、投亞蘭人彼土利子拉班、卽以掃雅各母利百加之兄、○"],[1,28,6,"以掃見以撒爲雅各祝嘏、遣至巴旦亞蘭、在彼娶妻、祝時、囑其毋娶迦南女爲室、"],[1,28,7,"又見雅各循父母命、往巴旦亞蘭、"],[1,28,8,"知迦南女不悅於父、"],[1,28,9,"乃適以實瑪利家、於其二妻外、更娶亞伯拉罕孫、以實瑪利女、尼拜約妹瑪哈拉爲室、○"],[1,28,10,"雅各離別是巴、向哈蘭而行、"],[1,28,11,"日旣沒、至一方宿焉、取石爲枕而臥、"],[1,28,12,"夢有梯立於地、頂及於天、上帝之使、陟降其上、"],[1,28,13,"耶和華立其巔曰、我乃耶和華、爾祖亞伯拉罕、與以撒之上帝、爾所寢之地、悉以畀爾、爰及苗裔、"],[1,28,14,"爾裔必繁衍如土塵、蔓延四方、天下萬民、將緣爾與裔而獲福、"],[1,28,15,"我必偕爾、無論何往、我必護爾、使歸斯土、不汝遐棄、吾所許者、必踐其言、"],[1,28,16,"雅各醒曰、耶和華果在此、而我不知、"],[1,28,17,"乃懼、曰、此地何其可畏、非他、乃上帝之室、天之門也、○"],[1,28,18,"雅各夙興、以所枕之石立爲柱、傾膏其上、"],[1,28,19,"其邑原名路斯、易之曰伯特利、"],[1,28,20,"雅各許願曰、如上帝偕我、佑我於所行之路、賜我以衣食、"],[1,28,21,"使安然而返父家、則耶和華必爲我之上帝、"],[1,28,22,"所立柱石、將爲上帝室、凡上帝所錫我者、十輸其一以獻之、"],[1,29,1,"雅各啟行、至東人處、"],[1,29,2,"見有井於野、羊羣三、附井而臥、蓋人素由此飲之、井口覆以大石、"],[1,29,3,"羣羊咸集、則移石啟井、汲以飲之、飲竟、仍覆以石、"],[1,29,4,"雅各曰、兄弟奚自、曰、自哈蘭、"],[1,29,5,"曰、拿鶴之孫拉班、爾識之否、曰、識之、"],[1,29,6,"曰、安乎、曰、安、今其女拉結偕羊以至、"],[1,29,7,"曰、日尚高懸、聚羣之時、猶未至也、莫若飲羊、而往牧之、"],[1,29,8,"曰、不可、必待羣畜咸集、移石啟井、方可飲羊、"],[1,29,9,"言際、拉結偕父羊至、蓋牧之也、"],[1,29,10,"雅各見母兄拉班之女拉結與羊、則前移石啟井、以飲其羊、"],[1,29,11,"與拉結接吻、大聲而哭、"],[1,29,12,"告拉結曰、我乃爾父之甥、利百加子、拉結遂趨告其父、○"],[1,29,13,"拉班聞妹子雅各至、卽趨迎之、抱而接吻、引之入室、雅各告以所遇、"],[1,29,14,"拉班曰、爾誠骨肉之親、雅各偕居一月、"],[1,29,15,"拉班謂之曰、爾雖我甥、豈可徒役於我、告我欲得何值、"],[1,29,16,"拉班有二女、長名利亞、季名拉結、"],[1,29,17,"利亞目眊、而拉結美丰姿、有殊色、"],[1,29,18,"雅各愛拉結、曰、我願爲季女拉結、服役七年、"],[1,29,19,"拉班曰、妻爾愈於妻人、可偕我居、"],[1,29,20,"雅各爲拉結服役七年、因愛之甚、視七年如數日、○"],[1,29,21,"雅各謂拉班曰、期已屆、請以妻我、使我成禮、"],[1,29,22,"拉班設筵招鄰里、"],[1,29,23,"旣昏、以長女利亞與雅各、遂與同室、"],[1,29,24,"又以其婢悉帕、予女利亞爲婢、"],[1,29,25,"及旦、乃知爲利亞、謂拉班曰、曷待我若是、我非爲拉結服役乎、何欺我爲、"],[1,29,26,"拉班曰、未嫁長而先嫁季、斯土不爲此也、"],[1,29,27,"爾與長盈七日之期、則以季予爾、爾復服役七年、"],[1,29,28,"雅各從之、與利亞盈七日之期、拉班以女拉結妻之、"],[1,29,29,"以其婢辟拉、予女拉結爲婢、"],[1,29,30,"雅各亦與拉結同室、愛之逾於利亞、又服役拉班七年、○"],[1,29,31,"耶和華視利亞不見寵、賜之生育、惟拉結不姙、"],[1,29,32,"利亞懷姙生子、命名流便、曰、耶和華俯念我苦、今而後、夫必愛我、"],[1,29,33,"再姙生子、命名西緬、曰、耶和華聞我不見寵、復錫我此子、"],[1,29,34,"又姙生子、命名利未、曰、今生三子、夫必膠漆於我、"],[1,29,35,"又姙生子、曰、我今頌美耶和華、故名子曰猶大、嗣後利亞不姙、"],[1,30,1,"拉結見己不爲雅各生子、則妒厥姊、謂雅各曰、賜我生子、不然、我死矣、"],[1,30,2,"雅各怒曰、使爾不育者、上帝也、我豈代爲上帝乎、"],[1,30,3,"曰、我婢辟拉、爾與同室、俾其生子、撫於我膝、我則因而得子、"],[1,30,4,"遂以婢辟拉予之、雅各與之同室、"],[1,30,5,"辟拉懷姙生子、"],[1,30,6,"拉結名之曰、但、曰、上帝伸我寃、聽我祈、賜我一子、"],[1,30,7,"辟拉再姙、爲雅各生子、"],[1,30,8,"拉結命名拿弗他利、曰、我與姊力爭獲勝、○"],[1,30,9,"利亞因不姙、以婢悉帕與雅各同室、"],[1,30,10,"悉帕生子、"],[1,30,11,"利亞謂爲吉慶、故名之曰迦得、"],[1,30,12,"悉帕再爲雅各生子、"],[1,30,13,"利亞曰、我福矣、羣女將謂我有福、故名之曰亞設、○"],[1,30,14,"麥秋時、流便往於田、獲風茄、奉母利亞、拉結謂利亞曰、請以爾子之風茄與我、"],[1,30,15,"曰、爾奪我夫、豈細故耶、今欲奪我子之風茄乎、拉結曰、爲汝子之風茄、是夜夫可與爾同寢、"],[1,30,16,"及暮、雅各自田歸、利亞出而迓之、曰、爾必與我偕入、我以吾子之風茄得爾、故是夜與之同室、"],[1,30,17,"上帝俞允利亞之祈、遂懷姙、爲雅各生第五子、"],[1,30,18,"利亞曰、昔我以婢與夫、今蒙上帝予我值、故名之曰以薩迦、"],[1,30,19,"利亞復姙、生第六子、"],[1,30,20,"命名西布倫、曰、上帝賜我嘉賚、夫必偕我、因我爲之生六子、"],[1,30,21,"後生一女、命名底拿、"],[1,30,22,"上帝眷念拉結、俯聽其祈、使之誕育、"],[1,30,23,"懷姙生子、曰、上帝已洒我恥、"],[1,30,24,"乃命名約瑟、曰、願耶和華復增我子、○"],[1,30,25,"拉結生約瑟後、雅各謂拉班曰、請遣我歸、返於故土、"],[1,30,26,"我事爾所得之妻子、請以予我、而遣我歸、我如何事爾、汝所知也、"],[1,30,27,"拉班曰、深知耶和華緣爾錫嘏於我、若蒙爾恩、仍偕我居、"],[1,30,28,"請言其值、我必給之、"],[1,30,29,"曰、我於爾服役若何、羣畜若何、爾悉知之、"],[1,30,30,"當我未至、所有鮮少、今則滋育繁多、耶和華緣我足跡所至、錫爾以嘏、然我何時成立己家乎、"],[1,30,31,"拉班曰、我何以予爾、曰、無須、惟有一事、爾若行之、則仍牧守爾羣、"],[1,30,32,"今我徧閱爾羣、凡有斑點與椶色之綿羊、及有斑點之山羊、悉驅出之、有若此者、歸我爲值、"],[1,30,33,"異日爾來察之、凡山羊非有斑點、綿羊非椶色者、卽擬我盜可也、以此爲我公義之徵、"],[1,30,34,"拉班曰、可如爾言、"],[1,30,35,"當日將牡山羊之有文有點者、牝山羊之斑駁成點、兼雜白文者、曁綿羊之椶色者、悉驅出之、付與其子、"],[1,30,36,"俾距雅各三日之程、雅各牧拉班之餘羊、○"],[1,30,37,"雅各將楊杏楓之柔條、剝皮成文、使條之白間露、"],[1,30,38,"置於溝壑水槽、羣羊來飲之處、與羣相對、俾其飲時、牝牡相誘、"],[1,30,39,"羣羊附條相誘、遂產有文有點有斑之羔、"],[1,30,40,"雅各將羔羊區別之、使此有文及椶色者、與拉班之羊相對、以己之羊驅於一方、不與拉班之羊相雜、"],[1,30,41,"遇羊之健者相誘、雅各置條水溝、而當其前、使附條相誘、"],[1,30,42,"其弱者不置條、於是弱者歸拉班、健者歸雅各、"],[1,30,43,"雅各遂大興盛、多有羊羣、僕婢駝驢、"],[1,31,1,"雅各聞拉班衆子言曰、我父所有者、雅各盡奪之、因父之資、獲此榮盛、"],[1,31,2,"又見拉班容貌、不如疇昔、"],[1,31,3,"耶和華謂雅各曰、爾其歸祖地、返故鄉、我必偕爾、"],[1,31,4,"雅各遣人召拉結、利亞、至田間羣畜所、"],[1,31,5,"語之曰、我見汝父容貌、不如疇昔、然吾父之上帝偕我、"],[1,31,6,"我竭力事汝父、汝所知也、"],[1,31,7,"爾父乃欺我、十易我值、惟上帝不容其加害、"],[1,31,8,"若云有點者爲我值、而羣畜咸有點、若云有文者爲我值、而羣畜俱有文、"],[1,31,9,"是上帝取爾父羣畜、賜於我矣、"],[1,31,10,"遇牝牡相誘之際、我於夢中、見牡羊乘其牝者、皆有文、有點、有斑、"],[1,31,11,"我夢上帝之使呼曰、雅各、我曰、在此、"],[1,31,12,"曰、試觀牡羊乘其牝者、皆有文、有點、有斑、蓋拉班之待爾、我已監之、"],[1,31,13,"我乃伯特利之上帝、昔爾在彼、以膏沃柱、許願於我、今起離此、返於故土、"],[1,31,14,"拉結利亞曰、我於父家、豈尚有分有業乎、"],[1,31,15,"父旣鬻我、又侵食我值、非以我爲外人乎、"],[1,31,16,"上帝所奪於我父者、皆屬於我及我子、上帝所諭爾者、爾悉行之、○"],[1,31,17,"雅各遂起、使妻子乘駝、"],[1,31,18,"攜其牲畜、及凡所有、卽在巴旦亞蘭所獲之物、往迦南地、見父以撒、"],[1,31,19,"時、拉班往剪羊毛、拉結竊其父之家神、"],[1,31,20,"雅各背亞蘭人拉班而去、不以其奔告之、"],[1,31,21,"挈凡所有、渡河、往基列山而遁、○"],[1,31,22,"越至三日、或以雅各之遁告拉班、"],[1,31,23,"乃率戚族、追之七日、至基列山及焉、"],[1,31,24,"夜間、上帝見夢、諭亞蘭人拉班曰、愼之哉、爾於雅各、或善或惡、均勿與言、"],[1,31,25,"雅各張幕於山、拉班追及之、與其戚族、亦張幕焉、"],[1,31,26,"拉班謂雅各曰、爾何背我、攜我二女、如俘虜然、"],[1,31,27,"曷爲竊遁、而不告我、俾我鼓琴、播鼗謳歌、忻然以送、"],[1,31,28,"不容我與子女接吻、爾之所爲、是不智也、"],[1,31,29,"我本有力、能以害爾、惟前夕爾父之上帝諭我曰、愼之哉、爾於雅各、或善或惡、均勿與言、"],[1,31,30,"今爾雖思父家、不得不歸、奚竊我之神像乎、"],[1,31,31,"雅各曰、我懼、意謂爾必強奪爾女、"],[1,31,32,"至爾之神像、爾獲之於誰所、不容其生、物有屬爾者、於爾我戚族前、可自辨而取之、蓋雅各不知拉結竊其神像也、○"],[1,31,33,"拉班遂進雅各幕、及利亞幕、二女婢之幕、皆無獲、後出利亞幕、入拉結幕、"],[1,31,34,"拉結置神像於駝鞍下、而坐其上、拉班徧索不得、"],[1,31,35,"拉結謂父曰、天癸適至、不得起迎、吾主勿怒、拉班徧索神像、終不獲、"],[1,31,36,"雅各怒、斥之曰、我何罪愆、使爾迫追我、"],[1,31,37,"今旣徧索吾物、有屬於爾者乎、果有之、則置之爾我戚族前、俾主裁於爾我間、"],[1,31,38,"此二十年、我偕爾處、爾綿羊山羊之牝、無殰胎者、爾羊之牡、我不食之、"],[1,31,39,"死於野獸者、我不歸爾、悉以補之、晝夜所盜、惟我是問、"],[1,31,40,"我晝則冒暑、夜則受寒、二目不寐、"],[1,31,41,"我居爾家、歷二十年、爲爾二女、服役十四年、爲爾羣羊六年、而爾十易我值、"],[1,31,42,"使吾祖亞伯拉罕之上帝、吾父以撒所畏者、不與我偕、爾必使我徒返、惟上帝監我操作辛勤、故前夕譴爾、○"],[1,31,43,"拉班曰、斯女卽我女、斯子卽我子、斯畜卽我畜、凡爾所見者、咸屬於我、茲於我女、及其所生之子、吾何能爲、"],[1,31,44,"今來結盟、於爾我間爲證、"],[1,31,45,"雅各遂取石立柱、"],[1,31,46,"亦命戚族積石、衆乃取石、積累爲堆、共食其側、"],[1,31,47,"拉班名之曰伊迦爾撒哈杜他、雅各名之曰迦累得、"],[1,31,48,"拉班曰、此堆今日爲證於爾我間、故名曰迦累得、"],[1,31,49,"又名米斯巴、蓋曰、爾我相暌隔時、願耶和華鑒察其間、"],[1,31,50,"爾若負吾女、別有所娶、雖無人同在、而上帝證之、"],[1,31,51,"拉班又謂雅各曰、可觀此堆、爾我間所立之柱、"],[1,31,52,"此堆此柱乃爲其證、我不越此堆害爾、爾亦不越此堆與柱害我、"],[1,31,53,"願亞伯拉罕之上帝、拿鶴之上帝、及其祖之上帝、主裁於爾我間、雅各乃指其父以撒所畏者而誓、"],[1,31,54,"又在山獻祭、招其戚族共食、後宿於山、"],[1,31,55,"拉班夙興、接吻子女、爲之祝嘏、而歸故土、"],[1,32,1,"雅各復行、上帝之使遇焉、"],[1,32,2,"雅各見之曰、此乃上帝之軍、故名其地曰瑪哈念、○"],[1,32,3,"雅各遣人、先往西珥地以東田、見兄以掃、"],[1,32,4,"囑曰、告我主以掃云、爾僕雅各曰、我旅於拉班家、越至今日、"],[1,32,5,"有牛羊驢僕婢、特遣人告我主、望沾主恩、"],[1,32,6,"使者反告雅各曰、吾儕詣爾兄以掃、彼率四百人來迎爾、"],[1,32,7,"雅各大懼、且憂、以從者及牛羊駝、分爲二隊、"],[1,32,8,"曰、若以掃來擊此隊、則彼隊可逃、"],[1,32,9,"遂禱曰、吾祖亞伯拉罕之上帝、吾父以撒之上帝耶和華歟、昔爾命我回故土、返戚屬、許待以善、"],[1,32,10,"爾所施於僕之恩寵誠實、卽至微者、亦不堪受、昔我惟執一杖、濟此約但、今我已成二隊、"],[1,32,11,"求爾拯我、脫於吾兄以掃之手、蓋我懼之、恐其來擊我、爰及母子、"],[1,32,12,"爾曾許待以善、使我苗裔、如海之沙、不可勝數、○"],[1,32,13,"是夜雅各宿於彼、簡其所有、饋兄以掃、"],[1,32,14,"卽山羊牝二百、牡二十、綿羊牝二百、牡二十、"],[1,32,15,"牝駝與子三十、牝牛四十、牡牛十、牝驢二十、小驢十、"],[1,32,16,"各爲其羣、付於僕手、曰、爾先我往、使各羣相距、"],[1,32,17,"囑其前者曰、我兄以掃遇爾、問爾屬誰、將何往、爾前之畜屬誰、"],[1,32,18,"則曰、屬我主之僕雅各、以饋我主以掃、雅各亦在後、"],[1,32,19,"又囑其二其三、曁一切驅畜者曰、爾遇以掃、亦宜如是告之、"],[1,32,20,"且曰、爾僕雅各在後、蓋雅各自謂、必以前行之禮物、釋兄之憾、然後覿面、庶幾接我、"],[1,32,21,"於是禮物先行、雅各是夜宿於隊中、○"],[1,32,22,"雅各夜起、使二妻二婢及十一子、濟雅博渡、"],[1,32,23,"眷聚旣濟、凡所有者亦濟、"],[1,32,24,"雅各獨留、遇一人與之角力、迄於黎明、"],[1,32,25,"相角之時、其人自知不勝、觸雅各髀傷之、"],[1,32,26,"曰、容我去、天明矣、曰、不爲我祝嘏、必不容爾去、"],[1,32,27,"曰、爾何名、曰、雅各、"],[1,32,28,"曰、今而後、爾不復名雅各、當名以色列、蓋爾與上帝及人較量、而獲勝也、"],[1,32,29,"雅各曰、請以爾名告我、曰、曷問我名、遂在彼爲之祝嘏、"],[1,32,30,"雅各名其地曰毘努伊勒、曰、我與上帝覿面、而我命尚存、"],[1,32,31,"日出時、雅各過毘努伊勒、髀傷、其行蹣跚、"],[1,32,32,"因其人觸雅各髀、傷其巨筋、故以色列人不食髀之巨筋、至於今日、"],[1,33,1,"雅各舉目、見以掃率四百人至、遂區別諸子、付與利亞拉結曁二婢、"],[1,33,2,"置二婢及其子於前、利亞及其子於中、拉結及約瑟於後、"],[1,33,3,"己則先行、俯伏者七、方近厥兄、"],[1,33,4,"以掃趨迎、抱頸接吻、彼此涕泣、"],[1,33,5,"以掃見婦與子、問偕爾者何人、曰、上帝施恩、賜僕之子、"],[1,33,6,"二婢及其子前而拜、"],[1,33,7,"利亞及其子前而拜、後拉結及約瑟、亦前而拜、"],[1,33,8,"以掃曰、我所遇之羣畜何意、曰、望沾恩於主、"],[1,33,9,"曰、吾弟、我已足矣、爾所有者存之、"],[1,33,10,"曰、勿爾、若沾爾恩、請受我禮、蓋我覿爾面、蒙爾悅納、如覿上帝面然、"],[1,33,11,"上帝施恩、使我富有、請受所奉之禮、迫之乃受、"],[1,33,12,"以掃曰、吾儕啟行而往、我爲爾先導、"],[1,33,13,"曰、主知我之子女猶稚、而牛羊方字、若一日亟驅之、則羣畜盡死、"],[1,33,14,"請我主前往、僕率子女牲畜、依其步履、徐徐而進、詣我主於西珥、"],[1,33,15,"曰、容我留從者數人、與爾偕行、曰、焉用此、惟得沾主恩足矣、"],[1,33,16,"是日以掃返於西珥、"],[1,33,17,"雅各至疎割、爲己築室、爲畜作廬、故其地名曰疎割、○"],[1,33,18,"雅各自巴旦亞蘭安然而歸、至迦南地示劍邑、張幕其東、"],[1,33,19,"後出百金、與示劍父哈抹子孫、以購張幕之所、"],[1,33,20,"在彼築壇、名之曰上帝以色列之上帝、"],[1,34,1,"雅各之女底拿、利亞所生也、往見鄰女、"],[1,34,2,"彼地牧伯希未人哈抹子示劍見之、執之偕寢、而玷辱焉、"],[1,34,3,"中心膠漆、愛慕殊深、語以甘言、"],[1,34,4,"示劍告父哈抹曰、請爲我娶此女爲室、"],[1,34,5,"雅各聞女底拿被辱時、衆子牧羣於田、故緘口無詞、以待子歸、"],[1,34,6,"示劍父哈抹出、欲與雅各語、"],[1,34,7,"雅各衆子聞之、自田歸、因示劍與雅各女偕寢、干咎於以色列族、爲所不當爲、不勝憂忿、"],[1,34,8,"哈抹語之曰、我子示劍之心、戀爾女弟、請與之爲室、"],[1,34,9,"爾我互相嫁娶、以爾女嫁我、我女任爾娶、"],[1,34,10,"爾我偕處、地在爾前、爾其居此貿易、得其產業、"],[1,34,11,"示劍謂女之父兄曰、望沾爾恩、任爾所求、我必與之、"],[1,34,12,"聘禮之索、惟命是從、第以女予我爲室、"],[1,34,13,"雅各衆子以妹底拿被玷、詭詞對哈抹示劍曰、"],[1,34,14,"此事不可行、人未受割、而我以妹與之、自取辱耳、"],[1,34,15,"惟爾男子、咸效我受割、方可從爾言、"],[1,34,16,"如是、我儕以女嫁爾、亦娶爾女、彼此偕居、合爲一族、"],[1,34,17,"若不聽我言而受割、我則攜妹而去、○"],[1,34,18,"哈抹與子示劍善其言、"],[1,34,19,"少者示劍、爲宗族所推尊、緣愛雅各女故、從言弗緩、"],[1,34,20,"哈抹與子示劍至其邑門、語邑人曰、"],[1,34,21,"斯人與我睦、此地又廣、足以容之、可准其居此貿易、我娶其女、亦以我女嫁之、"],[1,34,22,"惟我中男子、必先受割、與彼相同、則其人願偕我居、成爲一族、"],[1,34,23,"如是、則其牛羊、牲畜貨財、豈不皆爲我有、莫若許之、使偕我居、"],[1,34,24,"凡出邑門之男子、聽哈抹示劍言、悉皆受割、"],[1,34,25,"越至三日、其人痛劇時、雅各二子、底拿兄西緬利未、各執刃、潛襲邑、殲其男子、"],[1,34,26,"以刃戮哈抹及示劍、攜底拿出其室而去、"],[1,34,27,"雅各衆子因妹受辱、剝其尸、刦其邑、"],[1,34,28,"奪其牛羊驢、與在邑在田諸物、"],[1,34,29,"盡掠其貨財、虜其妻子、取其室中所有、"],[1,34,30,"雅各謂西緬利未曰、爾曹累我、令我遺臭於居此之迦南比利洗人、且我人寡、彼必聚而攻我、殲我及家、"],[1,34,31,"曰、彼待我妹若妓、可乎、"],[1,35,1,"上帝諭雅各曰、昔爾避兄以掃時、我在伯特利顯見於爾、今起往彼而居、爲我築壇、"],[1,35,2,"雅各命家人與從者曰、當除爾中異邦神像、潔己更衣、"],[1,35,3,"昔我遭難、上帝允我之祈、我行於途、上帝偕我、今當赴伯特利、爲之築壇、"],[1,35,4,"遂以異邦神像、及耳環與之、雅各藏於近乎示劍之橡下、"],[1,35,5,"啟行而往、上帝使四周諸邑之民懼甚、無追雅各子者、"],[1,35,6,"雅各與從者、至迦南之路斯、卽伯特利、"],[1,35,7,"昔雅各避兄以掃、上帝顯見、故在彼築壇、名其地曰伊勒伯特利、"],[1,35,8,"時、利百加媼底波拉死、葬於伯特利橡下、名其樹曰亞倫巴古、○"],[1,35,9,"雅各自巴旦亞蘭歸、上帝與之顯見、錫之以嘏、"],[1,35,10,"曰、爾名雅各、今而後不復稱此、當名以色列、遂名之曰以色列、"],[1,35,11,"又曰、我乃全能之上帝、爾其蕃息昌熾、一族衆族由爾而生、多王由爾而出、"],[1,35,12,"我所賜亞伯拉罕以撒之地、亦將錫爾、爰及苗裔、"],[1,35,13,"上帝言竟、離之上升、"],[1,35,14,"雅各卽於上帝與言之處、立石爲柱、奠之以酒、沃之以膏、"],[1,35,15,"名其處曰伯特利、○"],[1,35,16,"由伯特利而徙、去以法他無幾、拉結臨產甚艱、"],[1,35,17,"難產之際、收生者曰、毋懼、爾又得子、"],[1,35,18,"拉結臨死、魂將逝時、名其子曰便俄尼而死、惟其父命名便雅憫、"],[1,35,19,"拉結旣卒、葬於以法他、卽伯利恆之途側、"],[1,35,20,"雅各立碑於墓、至今猶稱拉結墓碑、"],[1,35,21,"以色列復徙、過以得臺而張幕、"],[1,35,22,"居彼時、流便烝父妾辟拉、事聞於以色列、○"],[1,35,23,"雅各有子十二、長子流便、及西緬、利未、猶大、以薩迦、西布倫、乃利亞所出、"],[1,35,24,"約瑟、便雅憫、乃拉結所出、"],[1,35,25,"但、拿弗他利、乃拉結婢辟拉所出、"],[1,35,26,"迦得、亞設、乃利亞婢悉帕所出、是皆雅各於巴旦亞蘭所生者、"],[1,35,27,"雅各至幔利之基列亞巴、卽希伯崙、見父以撒、亞伯拉罕與以撒曾旅於此、○"],[1,35,28,"以撒享壽一百八十歲、"],[1,35,29,"壽高年邁、氣絕而終、歸於列祖、其子以掃雅各葬之、"],[1,36,1,"以掃卽以東、其裔如左、"],[1,36,2,"以掃娶迦南女爲室、卽赫人以倫女亞大、與希未人祭便孫、亞拿女阿何利巴瑪、"],[1,36,3,"又娶以實瑪利女、尼拜約妹巴實抹、"],[1,36,4,"亞大生以利法、巴實抹生流珥、"],[1,36,5,"阿何利巴瑪生耶烏施、雅蘭、可拉、此皆以掃於迦南地所生者、"],[1,36,6,"以掃率妻、與子女家人、牛羊牲畜、及在迦南所得之資財、往詣他方、離弟雅各、"],[1,36,7,"蓋二人資財豐盛、牲畜繁多、所旅之地、不能容之、弗獲同居、"],[1,36,8,"以掃卽以東、居西珥山、○"],[1,36,9,"以掃居西珥山、爲以東族祖、厥裔如左、"],[1,36,10,"其子名以利法、亞大所生、流珥、巴實抹所生、"],[1,36,11,"以利法生提幔、阿抹、洗玻、迦坦、基納斯、"],[1,36,12,"以利法妾亭納、生亞瑪力、此皆以掃妻亞大之裔、"],[1,36,13,"流珥生拿哈、謝拉、沙瑪、米撒、此皆以掃妻巴實抹之裔、"],[1,36,14,"祭便孫、亞拿女阿何利巴瑪、從以掃生耶烏施、雅蘭、可拉、○"],[1,36,15,"以掃胤中、有爲族長者、其畧如左、以掃冢子以利法子孫中、有提幔族長、阿抹族長、洗玻族長、基納斯族長、"],[1,36,16,"可拉族長、迦坦族長、亞瑪力族長、此以利法後裔中之族長、在以東地、皆亞大之裔、○"],[1,36,17,"以掃子流珥子孫中、有拿哈族長、謝拉族長、沙瑪族長、米撒族長、此流珥後裔中之族長、在以東地、皆以掃妻巴實抹之裔、"],[1,36,18,"阿何利巴瑪子孫中、有耶烏施族長、雅蘭族長、可拉族長、此皆以掃妻亞拿女阿何利巴瑪之裔、"],[1,36,19,"上所記諸族長、皆以掃卽以東之子孫、○"],[1,36,20,"素居是地者、何利人西珥子孫、其畧如左、羅坍、朔巴、祭便、亞拿、"],[1,36,21,"底順、以察、底珊、此皆以東地何利人西珥裔中之族長、"],[1,36,22,"羅坍子何利、希幔妹亭納、"],[1,36,23,"朔巴子亞勒文、瑪拿轄、以巴錄、示玻、阿南、"],[1,36,24,"祭便子亞雅、亞拿、當時在野牧父祭便之驢、遇温泉者、卽此亞拿、"],[1,36,25,"亞拿子底順、女阿何利巴瑪、"],[1,36,26,"底順子欣但、伊是班、益蘭、基蘭、"],[1,36,27,"以察子辟罕、撒番、亞干、"],[1,36,28,"底珊子烏斯、亞蘭、"],[1,36,29,"何利族長、其畧如左、羅坍族長、朔巴族長、祭便族長、亞拿族長、"],[1,36,30,"底順族長、以察族長、底珊族長、此皆何利人在西珥地爲族長者、○"],[1,36,31,"當以色列人未有王時、王於以東地者、其畧如左、"],[1,36,32,"比珥子比拉爲王於以東、都亭哈巴、"],[1,36,33,"比拉薨、波斯拉人謝拉子約巴嗣位、"],[1,36,34,"約巴薨、提幔人戶珊嗣位、"],[1,36,35,"戶珊薨、比達子哈達、卽昔於摩押田擊米甸人者嗣位、都亞未得、"],[1,36,36,"哈達薨、瑪士利加人桑拉嗣位、"],[1,36,37,"桑拉薨、河濱利河伯人掃羅嗣位、"],[1,36,38,"掃羅薨、亞革波子巴勒哈南嗣位、"],[1,36,39,"巴勒哈南薨、哈達嗣位、都巴烏、其后米希他別、乃米薩合孫、瑪特利之女、○"],[1,36,40,"以掃裔諸族長、依其世系居處名氏、其畧如左、亭納族長、亞勒瓦族長、耶帖族長、"],[1,36,41,"阿何利巴瑪族長、以拉族長、比嫩族長、"],[1,36,42,"基納斯族長、提幔族長、米比薩族長、"],[1,36,43,"瑪基疊族長、以蘭族長、以上所載、皆以東之族長、依其疆域、在其壤地、以東族祖、卽以掃是、"],[1,37,1,"雅各居迦南、卽父所旅之地、"],[1,37,2,"其畧如左、孺子約瑟、年十有七、偕兄牧羊、與父妾辟拉悉帕諸子爲侶、以其過告父、"],[1,37,3,"以色列之生約瑟也、年已邁矣、故愛之逾於諸子、爲製彩衣、"],[1,37,4,"諸兄見父愛約瑟逾於己、遂憾之、不能語以善言、○"],[1,37,5,"約瑟得夢、述於諸兄、諸兄憾之愈甚、"],[1,37,6,"約瑟曰、我所夢者、請聽之、"],[1,37,7,"吾儕於田束禾、我所束者起而立、爾所束者環而拜、"],[1,37,8,"諸兄曰、爾果將君我乎、抑轄我乎、故因其夢與言、而益憾之、"],[1,37,9,"約瑟復夢、告諸兄曰、我夢得其二矣、有日月十一星、皆拜我、"],[1,37,10,"約瑟告父兄時、父叱之曰、爾所夢者何耶、我與汝母汝兄、果將俯伏拜爾乎、"],[1,37,11,"諸兄嫉之、惟父誌其言、○"],[1,37,12,"諸兄往示劍、牧父羣羊、"],[1,37,13,"以色列語約瑟曰、來、爾兄非牧於示劍乎、吾將遣爾詣之、曰、我在斯、"],[1,37,14,"曰、往觀諸兄、及羣羊安否、而返告我、遂由希伯崙谷遣之、乃往示劍、"],[1,37,15,"躑躅田間、或遇之曰、爾何求耶、"],[1,37,16,"曰、求我兄、彼牧羊何所、請告我、"],[1,37,17,"曰、已去此矣、我聞其言、將往多坍、約瑟追之、見於多坍、○"],[1,37,18,"約瑟未至、諸兄遙見、共謀殺之、"],[1,37,19,"相語曰、作夢者來矣、"],[1,37,20,"莫若殺之、擲於井、謂爲惡獸所食、觀其夢有何徵驗、"],[1,37,21,"流便聞之、欲救約瑟曰、勿戕其命、"],[1,37,22,"又曰、勿流其血、勿著以手、曠野有井、投之於中可也、蓋欲援之、歸諸其父、"],[1,37,23,"約瑟至、諸兄褫其彩衣、"],[1,37,24,"執而投諸眢井、○"],[1,37,25,"諸兄坐而食餅、望見以實瑪利人、聯隊自基列來、以羣駝負香料乳香沒藥、欲下埃及、"],[1,37,26,"猶大謂兄弟曰、殺弟而匿其血、何益之有、"],[1,37,27,"彼乃我弟、我之骨肉、毋著以手、莫若鬻於以實瑪利人、兄弟從之、"],[1,37,28,"以實瑪利人乃米甸賈、適經其處、諸兄乃援約瑟出井、鬻之、獲金二十、以實瑪利人挈約瑟往埃及、○"],[1,37,29,"流便至井、窺約瑟不在、遂裂己衣、"],[1,37,30,"返見諸弟曰、孺子不在、我將焉往、"],[1,37,31,"昆弟宰牡山羊、濡約瑟衣於血、"],[1,37,32,"遣人攜之詣父曰、我儕得此、試觀爲爾子之衣否、"],[1,37,33,"雅各識之、曰、是吾子之衣也、彼爲惡獸所食、約瑟破裂無疑矣、"],[1,37,34,"遂裂己衣、腰束以麻、傷悼日久、"],[1,37,35,"子女羣來相慰、父不受慰、曰、我必悲哀至於陰府、就子乃已、父之痛子如此、"],[1,37,36,"米甸賈攜約瑟至埃及、鬻與法老臣侍衞長波提乏、"],[1,38,1,"維時、猶大離諸昆弟、就亞杜蘭人希拉、"],[1,38,2,"見迦南人書亞女、娶之、與之同室、"],[1,38,3,"婦姙生子、猶大名之曰珥、"],[1,38,4,"再姙生子、母名之曰俄南、"],[1,38,5,"復姙生子、名之曰示拉、時、猶大居於基悉、"],[1,38,6,"猶大爲長子珥娶室、名他瑪、"],[1,38,7,"珥行惡於耶和華前、耶和華殺之、"],[1,38,8,"猶大命俄南曰、汝其與嫂同室、以盡弟分、生子嗣兄、"],[1,38,9,"俄南知子不歸己、不欲爲兄存後、與嫂偕寢時、遺洩於地、"],[1,38,10,"所爲不悅於耶和華、耶和華亦殺之、"],[1,38,11,"猶大恐季子亦死、如二兄然、謂媳他瑪曰、姑居父家、守志勿嫁、待吾子示拉長、遂往居父家、○"],[1,38,12,"久之、猶大妻書亞女死、猶大旣得慰藉、與友亞杜蘭人希拉往亭拿、就剪羊毛者、"],[1,38,13,"或告他瑪曰、汝舅往亭拿剪羊毛、"],[1,38,14,"他瑪見示拉長、而未得嫁之、乃去嫠服、以帕蒙面蔽體、坐於伊拿印邑門、在往亭拿之途側、"],[1,38,15,"猶大見其蔽面、以爲妓、"],[1,38,16,"道旁就之曰、來、我與爾偕寢、蓋不知爲媳也、婦曰、與我偕寢、何以贈我、"],[1,38,17,"曰、必遺羣中山羊之羔、曰、羔未至、與質否、"],[1,38,18,"曰、與爾何質、曰、爾印與紳、及手中杖、乃畀之、遂與偕寢、婦卽懷姙、"],[1,38,19,"起而去、脫帕、仍衣嫠服、"],[1,38,20,"猶大託友亞杜蘭人遺之羔、由婦取質、而不獲見、"],[1,38,21,"詢居民曰、伊拿印道旁、有妓安在、曰、此地無妓、"],[1,38,22,"返見猶大曰、求之不得、居民亦言彼地無妓、"],[1,38,23,"猶大曰、吾旣託爾遺羔、不得其人、任婦得質、免我貽羞、○"],[1,38,24,"約越三月、或告猶大曰、爾媳他瑪有淫行、今已懷姙、猶大曰、曳出焚之、"],[1,38,25,"旣出、遣人謂舅曰、我之懷姙、由於此物之主、試觀此印、及紳與杖、爲誰所有、"],[1,38,26,"猶大承之、曰、我不嫁之與子示拉、婦猶賢於我也、嗣後猶大不復近之、"],[1,38,27,"婦臨產、知其孿生、"],[1,38,28,"產際、其一出手、收生者以絳絲繫之、曰、此首出也、"],[1,38,29,"手入、其他出矣、收生者曰、爾何自坼、故命名法勒斯、"],[1,38,30,"其手繫絳絲者後出、命名謝拉、"],[1,39,1,"約瑟被攜至埃及、法老臣侍衞長波提乏、由以實瑪利人購之、"],[1,39,2,"約瑟居其主埃及人家、耶和華偕之、所爲暢遂、"],[1,39,3,"厥主見耶和華偕之、使其諸事亨通、"],[1,39,4,"故加以恩、俾侍左右、委治家業、悉以所有、歸其掌握、"],[1,39,5,"自委治家業、耶和華爲約瑟故、錫嘏其主埃及人家、凡在室在田、咸蒙福祉、"],[1,39,6,"其主遂以所有、悉付約瑟、於己所食外、不知其他、約瑟儀容秀美、○"],[1,39,7,"嗣後主母目約瑟曰、與我偕寢、"],[1,39,8,"約瑟弗從、曰、主不知家事、以凡所有、歸我掌握、"],[1,39,9,"此家之中、莫大於我、除爾爲主室外、無一不歸我者、曷敢干此元惡、獲罪於上帝、"],[1,39,10,"婦日誘之、約瑟弗從、不與偕寢、亦不與同在、"],[1,39,11,"一日入室治事、旁無家人、"],[1,39,12,"主母執其衣、曰、與我偕寢、約瑟棄衣而遁、"],[1,39,13,"婦見其遁、遺衣在手、"],[1,39,14,"則呼家人曰、主使希伯來人至此、調戲我儕、適來欲偕我寢、我厲聲號呼、"],[1,39,15,"彼聞我揚聲、遺衣逃遁而出、"],[1,39,16,"婦存其衣、以待主歸、"],[1,39,17,"至則告曰、爾所攜至之希伯來僕、入而戲我、"],[1,39,18,"我揚聲號呼、彼乃遺衣遁去、○"],[1,39,19,"主聞其妻言曰、僕待我如是、則怒、"],[1,39,20,"執約瑟下獄、卽犯王章者幽囚之處、由是約瑟下獄、"],[1,39,21,"耶和華偕之、施以慈惠、令沾思於司獄、"],[1,39,22,"司獄以獄囚悉畀約瑟掌理、獄中所爲、悉由約瑟、"],[1,39,23,"司獄一無所顧、咸歸約瑟、蓋耶和華偕之、使其所爲、無不亨通、"],[1,40,1,"厥後、埃及王之酒政膳長、干犯其主、"],[1,40,2,"法老怒酒政膳長二臣、"],[1,40,3,"下之於獄、在侍衞長第中、卽約瑟幽囚之處、"],[1,40,4,"侍衞長付與約瑟、俾侍其側、二人在獄日久、"],[1,40,5,"王之酒政膳長、繫於獄中、同夜得夢、夢各有兆、"],[1,40,6,"詰朝約瑟入、見其有憂色、"],[1,40,7,"問曰、爾曹今日、何有憂色若是、"],[1,40,8,"曰、我儕得夢、無人能占、曰、占夢豈非由於上帝乎、請述於我、○"],[1,40,9,"酒政以夢告約瑟曰、吾夢有葡萄樹於前、"],[1,40,10,"樹有三枝、恍若萌芽舒蕊、結實纍然而熟、"],[1,40,11,"吾手執法老爵、摘取葡萄、擠汁其中、以奉法老、"],[1,40,12,"約瑟曰、三枝者、三日也、"],[1,40,13,"三日間、法老將提爾出獄、復爾原職、奉爵法老、如昔爲酒政然、此其占也、"],[1,40,14,"爾旣得志、請垂念我、施恩於我、爲我告法老、拯我出此、"],[1,40,15,"我乃被掠、出自希伯來境、在此未作關於繫獄之事、"],[1,40,16,"膳長見其占吉、謂約瑟曰、我亦得夢、有白餅三筐在於首、"],[1,40,17,"上筐盛法老所食之炙饌、有鳥啄之、"],[1,40,18,"約瑟曰、三筐者、三日也、"],[1,40,19,"三日間、法老將斷爾首、懸爾於木、鳥啄汝肉、此其占也、"],[1,40,20,"越至三日、法老誕辰、賜宴羣臣、召酒政膳長出獄、"],[1,40,21,"復酒政職、奉爵於前、"],[1,40,22,"懸膳長於木、悉如約瑟所占、"],[1,40,23,"然酒政不念約瑟、竟忘之矣、"],[1,41,1,"越二年、法老夢立河濱、"],[1,41,2,"見七牝牛自河出、色美體肥、齧芻蘆中、"],[1,41,3,"又見七牝牛自河出、色惡體瘠、與前所見之牛、同立河濱、"],[1,41,4,"色惡體瘠者、吞其色美體肥者、法老乃寤、"],[1,41,5,"再寢、復夢、見麥一莖生七穗、旣茂且佳、"],[1,41,6,"後又生七穗、細弱而暴於東風、"],[1,41,7,"細弱之穗、吞其旣茂且佳之七穗、法老寤、知爲夢、"],[1,41,8,"詰朝、中心憂疑、召埃及博士哲人、以夢告之、無能占者、○"],[1,41,9,"酒政謂法老曰、今日我憶昔日之咎、"],[1,41,10,"曩者法老怒臣、以我及膳長、囚於侍衞長第中之獄、"],[1,41,11,"彼與我同夜得夢、夢各有兆、"],[1,41,12,"時、有希伯來少者、偕我在獄、爲侍衞長之役、我儕以夢告之、彼循各夢而占、"],[1,41,13,"後依所占而應、臣得復職、膳長懸木、○"],[1,41,14,"法老遣使召約瑟、急令出獄、薙髮易衣、入覲法老、"],[1,41,15,"法老謂約瑟曰、我得一夢、無人能占、或告我曰、汝聞夢能占之、"],[1,41,16,"約瑟對曰、此非我所能、惟上帝必以平安之兆示法老、"],[1,41,17,"法老曰、我夢立河濱、"],[1,41,18,"見七牛自河出、體肥色美、齧芻蘆中、"],[1,41,19,"又見七牛繼之而上、色惡體瘠、如斯陋劣、遍埃及未之見也、"],[1,41,20,"瘠且惡者、吞其先出之七肥牛、"],[1,41,21,"旣吞、依然陋劣、末由知其食之、我乃寤、"],[1,41,22,"復夢、見一莖生七穗、旣茂且佳、"],[1,41,23,"厥後又生七穗、枯且細、暴於東風、"],[1,41,24,"細者吞其七佳穗、我以此夢告諸博士、莫能述之、○"],[1,41,25,"約瑟謂法老曰、法老之夢一也、上帝以所欲爲、示於法老、"],[1,41,26,"七美牛者、七年也、七佳穗者、亦七年也、其夢維一、"],[1,41,27,"繼而上之七牛、瘠且惡者、七年也、無實之七穗、暴於東風者、亦七年、卽饑年也、"],[1,41,28,"我言上帝以所欲爲示法老者、此之謂也、"],[1,41,29,"遍埃及地、將有七豐年、"],[1,41,30,"後則繼以七饑年、使斯土爲凶荒所滅、不憶前此之豐稔、"],[1,41,31,"蓋後至之凶荒特甚、故疇昔之豐稔不知也、"],[1,41,32,"上帝定此、將速成之、故使法老復夢、"],[1,41,33,"今可擇一才智之士、使治埃及、"],[1,41,34,"亦立羣督於國、俾於七豐年中、征糧五分之一、"],[1,41,35,"斂豐年之糧、歸法老之手、積之於廩、守之於城、"],[1,41,36,"以爲將來七凶年之蓄、庶免此國滅於凶荒、○"],[1,41,37,"法老與羣臣善其言、"],[1,41,38,"法老謂羣臣曰、如此之人、感於上帝之神、豈易得乎、"],[1,41,39,"又謂約瑟曰、上帝旣以此示汝、爾之才智、莫與比擬、"],[1,41,40,"爾可治我家、我民舉止、咸遵爾命、我尊於爾、只在國位、"],[1,41,41,"又曰、我立爾統轄埃及、"],[1,41,42,"遂脫指環、授約瑟手、衣以枲衣、復以金鏈垂其項、"],[1,41,43,"乘以副車、前驅者呼曰跪、由是立爲通國之宰、"],[1,41,44,"法老謂約瑟曰、我乃法老、埃及通國、非有爾命、無敢舉手足者、"],[1,41,45,"法老賜約瑟名曰撒發那忒巴內亞、以安邑祭司波提非拉女亞西納妻之、約瑟出巡埃及、○"],[1,41,46,"約瑟覲埃及王法老時、年已三十、爰離法老、遍巡四方、"],[1,41,47,"七豐年中、物產蕃盛、"],[1,41,48,"約瑟斂埃及七年之糧、儲於城內、各邑郊之糧、儲於本邑、"],[1,41,49,"遂積穀如海沙之多、不復計算、不可勝數故也、"],[1,41,50,"荒年未至、安邑祭司波提非拉女亞西納、爲約瑟生二子、"],[1,41,51,"長子命名瑪拿西、曰、上帝使我不復念昔日之苦、以及父家、"],[1,41,52,"季子命名以法蓮、曰、上帝於我歷苦之地、使我昌熾、○"],[1,41,53,"埃及地、七年之豐裕旣過、"],[1,41,54,"七年之凶荒繼至、應約瑟言、列國皆饑、惟埃及遍處有糧、"],[1,41,55,"迨埃及饑、民求食於法老、法老諭曰、往見約瑟、循其所命而行、"],[1,41,56,"維時、天下皆饑、埃及之饑亦甚、約瑟遂啟倉廩、糶糧於埃及人、"],[1,41,57,"諸國至埃及、乞糴於約瑟、天下皆饑故也、"],[1,42,1,"雅各知埃及有糧、謂諸子曰、爾曹曷相觀望、"],[1,42,2,"我聞埃及有糧、可往糴之、以延生命、免於死亡、"],[1,42,3,"於是約瑟諸昆十人、往糴於埃及、"],[1,42,4,"其弟便雅憫、雅各不遣之偕行、曰、恐其罹害、"],[1,42,5,"羣詣埃及糴糧、以色列諸子亦至、迦南地饑故也、"],[1,42,6,"時、約瑟秉國鈞、糶糧於兆民、諸昆至、俯伏以拜、"],[1,42,7,"約瑟見而識之、佯爲不識、厲聲曰、爾奚自、曰、自迦南來乞糴、"],[1,42,8,"約瑟識諸昆、而諸昆不之識、"],[1,42,9,"約瑟憶前夢、語諸昆曰、爾曹乃偵者、今來此、特窺是邦之虛實耳、"],[1,42,10,"曰、吾主、不然、僕爲乞糴而來、"],[1,42,11,"我儕一父所生、爲人篤實、非偵者也、"],[1,42,12,"曰、否、爾曹來窺是邦之虛實耳、"],[1,42,13,"曰、僕昆弟十二、迦南一人之子、一弟已亡、季者偕父、"],[1,42,14,"約瑟曰、汝爲偵者、我言誠是、"],[1,42,15,"若不攜季者至、以徵爾言之眞僞、吾指法老生命而誓、不許爾出此、"],[1,42,16,"爾中惟遣一人攜汝弟來、其餘禁錮、俟徵爾語、知爾誠否、非然、吾指法老生命而言、汝果偵者、"],[1,42,17,"遂同幽於獄三日、○"],[1,42,18,"至三日、語之曰、我寅畏上帝、有一策焉、爾若從之、則可得生、"],[1,42,19,"爾果篤實、則囚一人於獄、其餘載糧而歸、以救爾家之饑、"],[1,42,20,"攜季者至、以徵爾言、免於死亡、乃遵命而行、"],[1,42,21,"相語曰、昔吾儕緣弟獲戾、見其苦衷、而不聽其祈求、故遭此難、"],[1,42,22,"流便曰、我豈不曰、勿干咎於孺子、惟爾弗聽、故討其血於我也、"],[1,42,23,"諸昆不知約瑟識其言、蓋彼此藉譯傳語、"],[1,42,24,"約瑟退而哭、復出與語、自衆中取西緬、繫之於前、"],[1,42,25,"命以糧充諸昆囊、各反其金於中、饋之餱糧、遂如命以行、○"],[1,42,26,"其人負糧於驢而去、"],[1,42,27,"至旅邸、一人啟囊、以糧飼驢、見金在囊口、"],[1,42,28,"告昆弟曰、我金見反、猶在於囊、衆心沮喪、戰慄而相告曰、上帝於我、所爲何耶、"],[1,42,29,"遂歸迦南、見父雅各、告以所遇、"],[1,42,30,"曰、國宰厲聲叱我、以我爲偵者、"],[1,42,31,"我曰、吾儕爲人篤實、非偵者也、"],[1,42,32,"同父昆弟、十有二人、一弟已亡、季者偕父、在於迦南、"],[1,42,33,"國宰謂我曰、爾果篤實、有策可知、卽於爾中、必留一人偕我、其餘載糧、以救爾家之饑、"],[1,42,34,"攜季者來斯、則知爾非偵者、誠爲篤實、我乃反爾昆弟、聽爾貿易於國、○"],[1,42,35,"迨傾厥囊、所緘之金、具在其中、父子見之、皆懼、"],[1,42,36,"其父雅各謂之曰、爾曹喪我子矣、約瑟已亡、西緬亦亡、今欲取便雅憫、此皆有害於我、"],[1,42,37,"流便語父曰、請付我手、我必反之、不攜之歸、殺我二子可也、"],[1,42,38,"曰、我之幼子、必不與爾偕行、其兄已亡、惟彼獨存、如途間遭害、則爾使我皓首慘然下陰府矣、"],[1,43,1,"境內饑甚、"],[1,43,2,"埃及所運之糧已罄、父曰、復往、少爲乞糴、"],[1,43,3,"猶大曰、其人切告我曰、如不攜季者至、不得覿吾面、"],[1,43,4,"若遣弟偕往、我則爲爾乞糴、"],[1,43,5,"不遣、我則不往、蓋其人曰、如不攜季者至、不得覿吾面、"],[1,43,6,"以色列曰、胡爲如是苦我、告以有弟、"],[1,43,7,"曰、其人詰我及戚族云、爾父尚在、猶有弟否、我以實告、豈知其命我攜弟來耶、"],[1,43,8,"猶大謂父以色列曰、遣孺子與我偕、卽起而往、爾我曁子女、均可延生不死、"],[1,43,9,"我敢保之、惟我是問、如不攜歸、置於爾前、我畢生負咎、"],[1,43,10,"若無濡滯、已往返者再、"],[1,43,11,"其父以色列曰、若然、可如是行、盛斯土之佳品於器、攜饋其人以爲禮、乳香與蜜少許、及香料、沒藥、榧子、杏仁、"],[1,43,12,"挈金乞糴、倍其前數、昔得於囊之金、悉以返之、恐其或有差謬也、"],[1,43,13,"更攜汝弟、往見其人、"],[1,43,14,"願全能之上帝、使爾蒙矜恤於其前、釋爾兄與便雅憫、若我喪子、則喪之耳、"],[1,43,15,"遂取品物、挈糴金倍其數、及便雅憫詣埃及、立約瑟前、○"],[1,43,16,"約瑟見便雅憫偕至、謂家宰曰、導此人入室、宰牲設席、是日亭午、彼與我共食、"],[1,43,17,"家宰遵命、導之入室、"],[1,43,18,"十人導至約瑟家、則懼、曰、緣昔反金於囊、故招我入、欲乘隙攻我、執我爲奴、而攘我驢、"],[1,43,19,"乃就家宰於門側、謂之曰、"],[1,43,20,"吾主、昔我來此乞糴、"],[1,43,21,"歸至旅邸、啟囊、見各人之金猶在、其數無缺、今我反之、"],[1,43,22,"此外尚挈金乞糴、藏金於囊、不識誰爲之、"],[1,43,23,"曰、安哉、無懼、爾之上帝、卽爾父之上帝、賜財於爾囊、爾金我已受之矣、遂出西緬相見、"],[1,43,24,"咸導入約瑟室、給水濯足、且飼其驢、"],[1,43,25,"昆弟聞將食於此、乃備品物、以待約瑟亭午至、○"],[1,43,26,"約瑟旣歸、昆弟陳品物於室、俯伏拜之、"],[1,43,27,"約瑟問其安、曰、汝前言之老父、尚在無恙乎、"],[1,43,28,"曰、吾主之僕我父、尚在無恙、遂鞠躬而拜、"],[1,43,29,"約瑟目覩同母弟便雅憫、曰、爾前言之季弟、卽斯人乎、又曰、小子、願上帝施恩於汝、"],[1,43,30,"約瑟慕弟情急、擇所而哭、乃入內室哭焉、"],[1,43,31,"後靧面出、強制其情、命進饌、"],[1,43,32,"遂進之、約瑟一席、昆弟一席、共食之埃及人一席、緣埃及人與希伯來族同席、以爲不屑、"],[1,43,33,"昆弟列坐於前、長幼各依其序、彼此異之、"],[1,43,34,"約瑟推食食之、惟便雅憫之饌五倍、遂飲同樂、"],[1,44,1,"約瑟命家宰曰、以糧充其人之囊、依所能負、反金於中、"],[1,44,2,"以我銀爵、與季者之糴金、置於季者囊、家宰如命而行、"],[1,44,3,"黎明、人與驢、俱遣之去、"],[1,44,4,"距邑未遠、約瑟謂家宰曰、起追其人、及之、則曰、曷以惡報善耶、"],[1,44,5,"此器非吾主所用以飲、而藉以卜者乎、爾行此事、是不良也、"],[1,44,6,"追旣及、如言以告、"],[1,44,7,"曰、吾主、何出此言、斯事僕斷不爲、"],[1,44,8,"昔得金於囊、我自迦南來、攜以反爾、則我豈竊金銀於爾主之室乎、"],[1,44,9,"可索僕中、獲之於誰、卽致之死、我衆爲爾奴、"],[1,44,10,"曰、如爾言、獲之於誰、當爲我奴、餘皆無辜、"],[1,44,11,"各急下囊啟之、"],[1,44,12,"家宰索焉、自長迄幼、得爵於便雅憫囊、"],[1,44,13,"衆則裂衣、使驢負載、而返於邑、○"],[1,44,14,"猶大與昆弟至、約瑟尚在室、遂俯伏其前焉、"],[1,44,15,"約瑟曰、爾所行者何耶、我之爲人、信能占卜、爾不知乎、"],[1,44,16,"猶大曰、我儕於主、夫復何言、尚有何辭、焉能自解、上帝摘僕之咎、獲爵於其手者、與我儕咸爲主之奴、"],[1,44,17,"約瑟曰、我斷不爲此、獲爵於其手者、當爲我奴、爾衆安然以歸、見父可也、○"],[1,44,18,"猶大前曰、吾主歟、爾與法老一體、容僕進一言於主耳、請毋怒、"],[1,44,19,"昔主問僕云、父尚在否、有兄弟否、"],[1,44,20,"我告吾主曰、老父尚在、暮年生季子、其同母之兄亡矣、厥母惟遺此子、父愛之、"],[1,44,21,"主語僕曰、攜之來、使我目覩之、"],[1,44,22,"僕告主曰、孺子不能離父、離之則父死、"],[1,44,23,"主曰、季弟不偕至、爾曹不復覿吾面、"],[1,44,24,"僕歸、見主之僕我父、以主言告之、"],[1,44,25,"父曰、復往、少爲乞糴、"],[1,44,26,"僕曰、不可往也、若季弟偕往則可、蓋季弟不同行、不得見其人之面、"],[1,44,27,"主之僕我父曰、爾知我妻惟生二子、"],[1,44,28,"一出不歸、我曰必破裂矣、至今未見、"],[1,44,29,"若亦攜此而去、設其遘害、則爾使我皓首慘然下陰府矣、"],[1,44,30,"父子二人、相依爲命、我歸見主之僕我父、而孺子不與我偕、"],[1,44,31,"父不見孺子必死、是僕使主之僕我父、皓首慘然下陰府也、"],[1,44,32,"且僕曾保孺子於父曰、如不攜歸以見、我畢生負咎於父前、"],[1,44,33,"今求准僕代孺子居此、爲吾主之奴、容其偕兄歸、"],[1,44,34,"若孺子不與我同返、父之悲慘、何忍見乎、"],[1,45,1,"約瑟當侍者前、情不能制、遂呼曰、屛衆、約瑟使昆弟相識時、左右無人、"],[1,45,2,"遂大聲號哭、埃及人與法老家悉聞之、"],[1,45,3,"約瑟謂昆弟曰、我乃約瑟、吾父尚在乎、昆弟惶懼於其前、無辭以對、"],[1,45,4,"約瑟曰、請前、則皆前、曰、吾乃爾弟約瑟、爾鬻於埃及者、"],[1,45,5,"勿以鬻我來此、自憂自恨、蓋上帝遣我先爾而至、以全爾生、"],[1,45,6,"境內已饑二年、猶有五載、無稼無穡、"],[1,45,7,"上帝遣我先爾而至、存爾後裔於世、大施拯救、以全爾生、"],[1,45,8,"我之至此、非爾所使、乃上帝也、使我爲法老父、兼司宗室、治理埃及通國、"],[1,45,9,"爾速詣吾父、告曰、汝子約瑟言上帝立我爲埃及宰、請來此、毋稽留、"],[1,45,10,"爾與子孫牛羊、及凡所有、居於歌珊、密邇乎我、"],[1,45,11,"饑饉尚有五年、我於彼供養爾、庶免爾與眷聚、及所有者匱乏、"],[1,45,12,"我親與爾言、爾曹與弟便雅憫、皆目覩之、"],[1,45,13,"我在埃及所得之榮曁爾所見、返告吾父、速迎之來、"],[1,45,14,"遂抱弟便雅憫頸而哭、便雅憫亦抱其頸而哭、"],[1,45,15,"約瑟與諸昆弟接吻而哭、厥後、昆弟始與之言、○"],[1,45,16,"其事聞於法老宮、曰、約瑟之兄弟至、法老與其臣咸悅、"],[1,45,17,"法老命約瑟曰、囑爾兄弟負物於畜、而往迦南、"],[1,45,18,"迎父與眷聚就我、我必以埃及嘉物予爾、俾爾食其肥甘、"],[1,45,19,"今我命爾、必如是行、以埃及車、載厥妻孥、迎父而至、"],[1,45,20,"毋惜爾之器用、蓋埃及嘉物、皆爲爾有也、○"],[1,45,21,"以色列諸子、依此而行、約瑟循法老命、給之車乘、饋之餱糧、"],[1,45,22,"各贈衣一襲、贈便雅憫金三百、衣五襲、"],[1,45,23,"其饋父也、牡驢十、負埃及之嘉物、牝驢十、負糧與食品爲父途中之需、"],[1,45,24,"遣兄弟歸、曰、途間愼毋相爭、"],[1,45,25,"遂離埃及往迦南、詣父雅各、"],[1,45,26,"告之曰、約瑟尚在、爲埃及通國之宰、雅各心灰、不信其言、"],[1,45,27,"諸子告以約瑟語、雅各見約瑟遣車載己、其神復蘇、"],[1,45,28,"曰、足矣、吾子約瑟尚在、我未死、必往見之、"],[1,46,1,"以色列攜凡所有啟行、至別是巴、獻祭於父以撒之上帝、"],[1,46,2,"夜間、上帝於異象中、呼以色列曰、雅各、雅各、曰、吾在此、"],[1,46,3,"曰、我乃上帝、卽爾父之上帝、爾往埃及、勿懼、在彼、我必使爾成爲大國、"],[1,46,4,"我將偕爾至埃及、導爾歸故土、約瑟將按厥手、俾爾瞑目、"],[1,46,5,"雅各由別是巴啟行、諸子以法老所遣之車、載父雅各、及其妻孥、"],[1,46,6,"雅各與其戚屬、挈羣畜、曁在迦南所得之貨財、往於埃及、"],[1,46,7,"諸子、諸孫、諸女、諸孫女、咸至埃及、○"],[1,46,8,"以色列族至埃及者、其名如左、雅各與其諸子、長子流便、"],[1,46,9,"流便之子、哈諾、法路、希斯崙、迦米、"],[1,46,10,"西緬之子、耶母利、雅憫、阿轄、雅斤、瑣轄、及迦南女所生之掃羅、"],[1,46,11,"利未之子、革順、哥轄、米拉利、"],[1,46,12,"猶大之子、珥、俄南、示拉、法勒斯、謝拉、珥與俄南死於迦南、法勒斯之子希斯倫、哈母勒、"],[1,46,13,"以薩迦之子、陀拉、普瓦、約伯、伸崙、"],[1,46,14,"西布倫之子、西烈、以倫、雅利、"],[1,46,15,"此利亞在巴旦亞蘭、從雅各所生之子孫、與女底拿、共三十三人、"],[1,46,16,"迦得之子、洗非芸、哈基、書尼、以斯本、以利、亞羅底、亞列利、"],[1,46,17,"亞設之子、音拿、亦施瓦、亦施韋、比利亞、及女西拉、比利亞之子、希別、瑪結、"],[1,46,18,"此拉班所賜利亞之婢悉帕、從雅各所生之子孫、共十六人、"],[1,46,19,"雅各妻拉結之子、約瑟、便雅憫、"],[1,46,20,"安邑祭司波提非拉女亞西納、在埃及從約瑟生瑪拿西、以法蓮、"],[1,46,21,"便雅憫之子、比拉、比結、亞實別、基拉、乃幔、以希、羅實、母平、戶平、亞勒、"],[1,46,22,"此拉結從雅各所生之子孫、共十四人、"],[1,46,23,"但之子戶伸、"],[1,46,24,"拿弗他利之子、雅薛、沽尼、耶色、示冷、"],[1,46,25,"此拉班所賜拉結之婢辟拉、從雅各所生之子孫、共七人、"],[1,46,26,"凡雅各所出、同至埃及者、共六十六人、子婦不與焉、"],[1,46,27,"約瑟在埃及生二子、屬於雅各家至埃及者、共七十人、○"],[1,46,28,"雅各遣猶大先詣約瑟、導往歌珊、衆咸至焉、"],[1,46,29,"約瑟備車、往歌珊迓父、見之、抱頸而哭不輟、"],[1,46,30,"以色列謂約瑟曰、爾旣尚存、我見汝面、雖死無憾、"],[1,46,31,"約瑟謂昆弟及父家曰、我將往告法老、昔在迦南、我之昆弟曁父家咸至、"],[1,46,32,"彼乃牧者、養畜爲業、今攜牛羊、及凡所有而至、"],[1,46,33,"法老召爾時、問汝何業、"],[1,46,34,"則曰、爾僕自幼迄今、養畜爲業、我祖亦然、如是、可居歌珊、蓋埃及人視牧者爲可憎也、"],[1,47,1,"約瑟覲法老、告曰、我之父兄、挈牛羊及所有、來自迦南、今在歌珊、"],[1,47,2,"約瑟簡兄弟五人、引見法老、"],[1,47,3,"法老曰、爾操何業、曰、僕與祖俱牧羊、"],[1,47,4,"又曰、迦南饑甚、牲畜無芻、故來旅此、求許僕居歌珊、"],[1,47,5,"法老諭約瑟曰、爾之父兄、旣至爾處、"],[1,47,6,"埃及地在爾前、俾爾父兄、處彼膏壤、可任其居歌珊、倘知昆弟中有能者、使爲我牧畜長、"],[1,47,7,"約瑟引父覲法老、雅各爲法老祝嘏、"],[1,47,8,"法老問之曰、爾年幾何矣、"],[1,47,9,"對曰、余旅世年百有三十、我之歲月無幾、且歷艱苦、不及吾祖旅世之年、"],[1,47,10,"雅各再爲法老祝嘏而退、"],[1,47,11,"約瑟循法老命、處父兄於埃及之沃土、卽蘭塞境、與之爲業、"],[1,47,12,"約瑟供養父兄、曁父眷屬、各視其家而給之、○"],[1,47,13,"饑旣太甚、四方無糧、埃及迦南、因而匱乏、"],[1,47,14,"埃及與迦南人、以金易糧、約瑟斂二地所有之金、儲於法老之庫、"],[1,47,15,"埃及迦南之金已盡、埃及人詣約瑟曰、金盡矣、請予我糧、奚爲斃於爾前、"],[1,47,16,"約瑟曰、金旣盡、以畜付我、我以糧易之、"],[1,47,17,"民牽畜就約瑟、約瑟以糧易其驢馬牛羊、是年因易其畜、給之以糧、"],[1,47,18,"歲終、明年民復至曰、在主之前、我不敢隱、我金已盡、羣畜悉歸吾主、可見我無所有、惟身與田而已、"],[1,47,19,"何忍見我死而田荒、請以糧購我及我田、我與我田、効力於法老、第給我以種、使我延生不死、而田不荒、○"],[1,47,20,"埃及人窘於饑、各鬻其田、約瑟爲法老購之、通國之田、皆歸法老、"],[1,47,21,"約瑟移埃及四境之民於城邑、"],[1,47,22,"惟祭司之田未購、蓋法老頒糧於祭司、祭司食其糈、故不鬻田、"],[1,47,23,"約瑟告民曰、今我爲法老購爾及田、有種於此、播田可也、"],[1,47,24,"穡時、當五輸其一、以納法老、爾得其四、爲種以播、亦爲爾及爾家人稚子所食、"],[1,47,25,"曰、爾援我命、願沾主恩、爲法老僕、"],[1,47,26,"約瑟立埃及田賦之法、五輸其一、以納法老、獨祭司之田、不歸法老、以迄於今、○"],[1,47,27,"以色列族居埃及之歌珊、在彼獲業、生育甚多、"],[1,47,28,"雅各居埃及十有七年、享壽一百四十七歲、"],[1,47,29,"以色列死期將至、召子約瑟曰、如爲爾所愛、則當置手於吾髀下、誓以仁誠待我、勿葬我於埃及、"],[1,47,30,"俟我與祖父偕眠時、必攜我出埃及、葬於先人之兆、曰、必循爾命而行、"],[1,47,31,"曰、爾誓之、遂誓之、以色列乃倚牀頭、而崇拜焉、"],[1,48,1,"厥後、或告約瑟曰、爾父有疾、約瑟攜二子瑪拿西以法蓮至、"],[1,48,2,"或告雅各曰、汝子約瑟來見、以色列強坐於牀、"],[1,48,3,"謂約瑟曰、昔在迦南之路斯、全能上帝顯見、錫嘏於我、"],[1,48,4,"曰、我將使爾生育繁多、成爲羣族、以斯土錫爾、爰及苗裔、以爲恆業、"],[1,48,5,"我未至埃及、爾所生之二子、以法蓮瑪拿西、俱屬於我、如流便西緬然、"],[1,48,6,"嗣後爾有所生、則爲爾子、於彼昆弟名下共其業、"],[1,48,7,"昔我自巴旦至迦南、途間去以法他無幾、拉結死、我葬之以法他、卽伯利恆途側、○"],[1,48,8,"以色列見約瑟二子、曰、此何人也、"],[1,48,9,"約瑟曰、乃上帝於斯、所賜我之子、曰、擄之來前、我爲祝嘏、"],[1,48,10,"以色列年邁、目昏無見、約瑟攜子進前、乃吻而抱之、"],[1,48,11,"謂約瑟曰、吾不意覿爾面、上帝復使覩爾子、"],[1,48,12,"約瑟令二子離膝前、而自伏地以拜、"],[1,48,13,"後攜二子、右執以法蓮、向以色列左、左執瑪拿西、向以色列右、進於其前、"],[1,48,14,"以色列伸右手、按季子以法蓮首、以左手按長子瑪拿西首、交叉其臂、有意存焉、"],[1,48,15,"乃祝約瑟曰、昔我祖父亞伯拉罕以撒所崇事之上帝、迄今一生育我之上帝、"],[1,48,16,"拯我出患難之使者、願其錫嘏童蒙、使歸我及我祖父亞伯拉罕以撒名下、繁衍於地、"],[1,48,17,"約瑟見父以右手按以法蓮首、不悅、乃舉父手、欲自以法蓮首、移於瑪拿西首、"],[1,48,18,"曰、吾父勿爾、此乃長子、請按右手於其首、"],[1,48,19,"父不許、曰、吾子、我知之矣、此子亦必成爲一族、且復昌大、惟季必越於長、其裔成爲羣族、"],[1,48,20,"是日祝之曰、以色列族祝嘏、必曰、願上帝使之若以法蓮瑪拿西然、於是立以法蓮在瑪拿西之先、"],[1,48,21,"以色列語約瑟曰、我將死矣、惟上帝必偕爾、俾返先人之處、"],[1,48,22,"今我賜爾一區、較諸昆弟爲尤多、其地卽我以刃以弓、奪於亞摩利人之手者也、"],[1,49,1,"雅各召諸子曰、爾其會集、我以日後所遇之事告爾、"],[1,49,2,"雅各諸子咸集以聽、從爾父以色列言、"],[1,49,3,"流便歟、爾乃吾之冢子、吾之能力、我強健時、所首生者、厥榮及權、超越於衆、"],[1,49,4,"惟爾如水之沸、故不卓犖、緣登父牀、而汚我榻、"],[1,49,5,"西緬利未、乃兄弟也、所用之刃、是爲兇器、"],[1,49,6,"我心不與同謀、我靈不與共會、蓋其乘怒而戕人命、縱欲而斷牛筋、"],[1,49,7,"厥怒烈可呪、厥氣暴可詛、我必分之於雅各家、散之於以色列族、"],[1,49,8,"維汝猶大、兄弟頌揚、爾父之子、伏拜爾前、爾手扼敵之頸、"],[1,49,9,"吾子猶大、猛如稚獅、食其所攫而去、臥如牡獅、蹲如牝獅、孰敢攖之、"],[1,49,10,"厥梃不離猶大、秉鈞者之杖、弗去其足間、迨細羅至、民咸歸之、"],[1,49,11,"縶驢於葡萄樹、維小驢於葡萄樹之佳者、以酒澣衣、以葡萄汁濯服、"],[1,49,12,"厥目緣酒而赤、厥齒緣乳而白、"],[1,49,13,"西布倫將居海濱、爲泊舟之所、界延西頓、"],[1,49,14,"以薩迦如健驢、臥於羊牢、"],[1,49,15,"視安靜爲可嘉、見土壤之甚美、鞠躬而負荷、作苦以服役、"],[1,49,16,"但爲以色列支派之一、將治其民、"],[1,49,17,"但爲道上之蛇、途間之蝮、以傷馬足、而墜騎者、"],[1,49,18,"耶和華歟、爾之拯救、我所企望、"],[1,49,19,"迦得爲軍所逼、反迫其後、"],[1,49,20,"亞設所產食物、乃爲肥甘、必出珍饈、爲王所用、"],[1,49,21,"拿弗他利如釋放之麀鹿、陳述嘉言、"],[1,49,22,"約瑟如結實之樹枝、在於泉旁、其條蔓延踰垣、"],[1,49,23,"矢人虐遇之、射傷之、窘迫之、"],[1,49,24,"然其弓堅勁、其臂健捷、惟賴雅各全能之主、其爲牧者、以色列之磐石、由之而出、"],[1,49,25,"彼爲爾父之上帝、必輔助爾、全能之主、必錫嘏爾、賜以上天之祜、源泉之澤、產育乳哺之福、"],[1,49,26,"汝父所祝之嘏、愈於吾祖所祝之嘏、如岡陵之恆久、如山嶽之高大、悉歸約瑟之首、臨乎冠昆弟者之頂、"],[1,49,27,"便雅憫如攫物之狼、朝吞所獲、夕分所奪、○"],[1,49,28,"此乃以色列十二支派、其父爲之祝嘏而言、各依其所應得者、"],[1,49,29,"復命之曰、我將歸於列祖、當葬我於吾祖父之側、在赫人以弗崙田之穴、"],[1,49,30,"卽迦南境、與幔利相對、麥比拉田之穴、昔亞伯拉罕自赫人以弗崙、所購爲業之塚地、"],[1,49,31,"曩於斯處、葬亞伯拉罕及其妻撒拉、亦葬以撒及其妻利百加、我亦葬利亞、"],[1,49,32,"其田與穴、購自赫人、"],[1,49,33,"雅各命衆子畢、斂足於牀、氣絕而終、歸於列祖、"],[1,50,1,"約瑟俯於父面、涕泣而吻之、"],[1,50,2,"命其醫士、以香料殮父尸、遂以香料殮之、"],[1,50,3,"歷至四旬、厥期旣盈、埃及人哭之七旬、○"],[1,50,4,"哭期旣竟、約瑟語法老之臣曰、若蒙汝恩、請告法老曰、"],[1,50,5,"吾父使我誓云、我將死矣、必葬於迦南地所修之墓、求容我往、葬父而返、"],[1,50,6,"法老曰、依汝父令爾所誓、可往葬之、"],[1,50,7,"約瑟遂往葬父、法老之臣、與宮庭長老、曁埃及長老偕行、"],[1,50,8,"約瑟眷聚、昆弟戚族俱往、獨留孩稚牛羊於歌珊、"],[1,50,9,"車馬同行、羣從成隊、"],[1,50,10,"至約但東、亞達禾場、號哭慟甚、約瑟爲父悲哀七日、"],[1,50,11,"迦南居民、見其在亞達禾場號哭、則曰、埃及人之悲哀、甚矣哉、故其地名曰亞伯麥西、在約但東、"],[1,50,12,"雅各諸子、循父命而行、"],[1,50,13,"舁父至迦南、葬於麥比拉田之穴、與幔利相對、昔亞伯拉罕自赫人以弗崙、所購爲業之塚地、○"],[1,50,14,"約瑟葬父旣畢、與昆弟及送葬者、咸歸埃及、○"],[1,50,15,"約瑟昆弟見父旣沒、相語曰、約瑟或憾我、念我之惡待、而盡報之、"],[1,50,16,"乃遣人語約瑟曰、父未沒之先、囑云、"],[1,50,17,"當謂約瑟曰、昔諸昆惡待於爾、請宥諸昆之罪、我儕爲汝父上帝之僕、請赦我過、言間、約瑟哭焉、"],[1,50,18,"昆弟咸至、俯伏其前、曰我爲爾僕、"],[1,50,19,"約瑟曰、毋懼、我豈代爲上帝乎、"],[1,50,20,"爾曹意欲害我、而上帝反益我、以保兆人之命、得如今日、"],[1,50,21,"今爾勿恐、我必養爾、及爾子孫、遂以善言慰藉之、○"],[1,50,22,"約瑟與父家屬居埃及、享壽百有十歲、"],[1,50,23,"得見以法蓮之子孫三代、瑪拿西孫、瑪吉之子、亦育於其膝前、"],[1,50,24,"約瑟謂昆弟曰、我瀕死矣、上帝必眷顧爾、導爾出斯土、反至所誓賜亞伯拉罕以撒雅各之地、"],[1,50,25,"約瑟使以色列族發誓、曰、上帝必眷顧爾、須攜我骨出於斯土、"],[1,50,26,"約瑟享壽百有十歲而終、人以香料殮之、蓋棺於埃及、"],[2,1,1,"以色列子、各攜眷屬、偕雅各至埃及者、其名如左、"],[2,1,2,"流便、西緬、利未、猶大、"],[2,1,3,"以薩迦、西布倫、便雅憫、"],[2,1,4,"但、拿弗他利、迦得、亞設、"],[2,1,5,"凡由雅各而出者、共七十人、約瑟已在埃及、"],[2,1,6,"約瑟與諸昆弟、及同世之人皆沒、"],[2,1,7,"以色列族生育繁多、昌熾強大、充滿是邦、○"],[2,1,8,"埃及有新王起、不知約瑟、"],[2,1,9,"告民曰、以色列族強庶過我、"],[2,1,10,"莫若以智謀馭之、免其衆多、遇有戰事、附敵攻我、離國而去、"],[2,1,11,"於是立督、加重負以虐之、使爲法老建比東蘭塞二邑、以爲府庫、"],[2,1,12,"然虐之愈甚、其生愈繁、埃及人憂之、"],[2,1,13,"遂嚴督其役、"],[2,1,14,"使之作苦、以勞其生、和泥、陶瓦、力田、所服之役、無不以嚴、○"],[2,1,15,"希伯來之收生者、一名施弗拉、一名普阿、"],[2,1,16,"埃及王命之曰、爾爲希伯來婦收生、值臨產時、男則殺之、女則存焉、"],[2,1,17,"惟收生者畏上帝、不遵埃及王命、竟存男子、"],[2,1,18,"王召之曰、存男奚爲、"],[2,1,19,"對曰、希伯來婦健捷、與埃及婦不同、收生者未至、而子已產矣、"],[2,1,20,"緣此、上帝施恩於收生者、民之生育、繁衍強大、"],[2,1,21,"因收生者畏上帝、上帝俾其成立家室、"],[2,1,22,"法老命其民曰、凡其所生之男、悉投諸河、生女則全其命、"],[2,2,1,"有利未族人、娶利未族女、"],[2,2,2,"懷姙生子、見子俊美、匿之三月、"],[2,2,3,"不可復匿、則取萑爲箱、以石漆瀝青塗之、納子其中、置於河濱蘆間、"],[2,2,4,"子之姊遙立、視其所遇若何、"],[2,2,5,"時、法老女臨河以浴、其婢遊於河濱、女見蘆中有箱、遣婢取之、"],[2,2,6,"啟箱見子、子哭、遂憐之、曰、此希伯來人之子也、"],[2,2,7,"子之姊謂法老女曰、我往招希伯來乳媼、以哺此子可乎、"],[2,2,8,"曰、可、乃往招其子之母、"],[2,2,9,"法老女謂之曰、取此子爲我哺之、我予汝值、婦取子哺之、"],[2,2,10,"子稍長、母攜之詣法老女、遂爲其子、女名之曰摩西、曰、我援之於水、○"],[2,2,11,"摩西旣壯、至昆弟處、視其作苦、見埃及人擊其兄弟希伯來人、"],[2,2,12,"顧左右無人、遂擊殺埃及人、掩之以沙、"],[2,2,13,"翌日復出、見希伯來二人鬬、謂不義者曰、曷擊爾同儔、"],[2,2,14,"曰、孰立汝爲君長士師以治我、爾欲殺我、如殺埃及人乎、摩西懼、曰、事洩矣、"],[2,2,15,"法老聞之、欲殺摩西、摩西避法老、逃往米甸居焉、"],[2,2,16,"坐於井側、米甸祭司有七女、來汲水、盈其槽、以飲父之羣羊、"],[2,2,17,"衆牧至、逐之、摩西起而助女、飲其羣羊、"],[2,2,18,"女歸見父流珥、父曰、今日爾歸、何速也、"],[2,2,19,"曰、有埃及人拯我、脫於衆牧手、亦爲我汲水飲羣羊、"],[2,2,20,"父曰、其人安在、胡爲遺之、請之來食、"],[2,2,21,"摩西願與偕居、其人以女西坡拉妻之、"],[2,2,22,"生子、摩西命名革舜、曰、我爲旅於異地、○"],[2,2,23,"歷年旣久、埃及王薨、以色列族因其服役、歎息號呼、聲聞於上帝、"],[2,2,24,"上帝聞其呻吟、遂追憶與亞伯拉罕以撒雅各所立之約、"],[2,2,25,"眷顧以色列人、特垂念焉、"],[2,3,1,"摩西爲其外戚、米甸祭司葉忒羅牧羊、引羊至野外、迄上帝之山何烈、"],[2,3,2,"耶和華之使者顯見於荊棘之火焰中、摩西視之、荊棘焚而不燬、"],[2,3,3,"曰、我必轉而觀此異象、荊棘何以不燬、"],[2,3,4,"耶和華上帝見摩西轉而觀之、則自荊棘中呼之曰、摩西、摩西、曰、我在此、"],[2,3,5,"曰、勿前、脫屨於足、蓋爾所立之處、乃聖地也、"],[2,3,6,"又曰、我乃爾祖父之上帝、卽亞伯拉罕之上帝、以撒之上帝、雅各之上帝、摩西蒙面、不敢視上帝、"],[2,3,7,"耶和華曰、吾民在埃及之艱辛、我見之矣、因受督役者之酷暴而哀號、我聞之矣、彼之愁苦、我知之矣、"],[2,3,8,"今我降臨、以拯之於埃及人手、導出其境、以至膏腴寬廣、流乳與蜜之地、卽迦南人、赫人、亞摩利人、比利洗人、希未人、耶布斯人之境、"],[2,3,9,"以色列人之哀號、達於我前、埃及人之虐遇、我亦鑒之、"],[2,3,10,"爾來、我遣爾詣法老、導吾民以色列人出埃及、"],[2,3,11,"摩西對上帝曰、我何人斯、得詣法老、而導以色列人出埃及乎、"],[2,3,12,"曰、我必偕爾、旣導民出埃及、爾曹必於是山崇事上帝、以此爲我遣爾之徵、○"],[2,3,13,"摩西曰、我至以色列族、告曰、爾祖之上帝遣我就爾、彼若詰我其名爲何、將奚以對、"],[2,3,14,"上帝曰、我乃自有、當告以色列族曰、自有者遣我就爾、"],[2,3,15,"又曰、亦告以色列族曰、遣我就爾者爲耶和華、乃爾祖之上帝、卽亞伯拉罕之上帝、以撒之上帝、雅各之上帝、耶和華乃我恆久之名、歷世爲誌、"],[2,3,16,"爾往集以色列長老、而告之曰、耶和華爾祖之上帝、卽亞伯拉罕之上帝、以撒之上帝、雅各之上帝、顯見於我、曰、我臨涖爾、鑒爾於埃及所遇者、"],[2,3,17,"我已言之、必導爾出埃及之苦、至流乳與蜜之地、卽迦南人、赫人、亞摩利人、比利洗人、希未人、耶布斯人之境、"],[2,3,18,"以色列長老必從爾言、爾與彼見埃及王、語之曰、希伯來人之上帝耶和華臨我、請爾許我詣野、歷程三日、以祭我上帝耶和華、"],[2,3,19,"然我知雖施大能之手、埃及王亦必不容汝往、"],[2,3,20,"我將伸手、行諸異蹟於埃及以擊之、後則使爾往、"],[2,3,21,"我將俾斯民沾恩於埃及人、爾行時、不令徒手而去、"],[2,3,22,"諸婦必向其鄰、及寓於其家之女、索金飾銀飾與衣服、以裝爾之子女、奪取埃及人之財物、"],[2,4,1,"摩西對曰、恐彼不信、不從我言、必曰耶和華未嘗顯見於爾、"],[2,4,2,"耶和華曰、爾手所執者何、曰、杖、"],[2,4,3,"曰、可擲於地、遂擲之、卽化爲蛇、摩西避焉、"],[2,4,4,"耶和華曰、伸爾手、執其尾、遂伸手執之、仍化爲杖、"],[2,4,5,"曰、如是、可使之信耶和華、其祖之上帝、卽亞伯拉罕之上帝、以撒之上帝、雅各之上帝、顯見於爾、"],[2,4,6,"又曰、置手於懷、遂置於懷、出之、手乃生癩、其白如雪、"],[2,4,7,"又曰、再置手於懷、遂置於懷、出之、手復原、同乎體、"],[2,4,8,"曰、如彼不聽、不信前之異蹟、必信後之異蹟、"],[2,4,9,"若不信此二者、不從爾言、則取河水傾於陸地、其水必變爲血、○"],[2,4,10,"摩西對曰、主歟、我素無才辯、爾語僕之後亦然、訥於口、鈍於舌、"],[2,4,11,"耶和華曰、造人之口者誰乎、使人或瘖或聾、或明或瞽者誰乎、非我耶和華乎、"],[2,4,12,"今其往哉、我必助爾之口、以所當言示爾、"],[2,4,13,"曰、主歟、請遣所欲遣者、"],[2,4,14,"耶和華怒之、曰、不有汝兄利未人亞倫乎、我知其善爲說辭、今出迓爾、見爾必喜、"],[2,4,15,"爾與之言、以詞授之、我必助爾與彼之口、示爾以所當行、"],[2,4,16,"亞倫爲汝傳語於民、彼於爾代爲口、爾於彼代爲上帝、"],[2,4,17,"手執此杖、以行異蹟、○"],[2,4,18,"摩西乃返、見外戚葉忒羅曰、容我往見昆弟於埃及、視其存否、葉忒羅曰、安然而往、"],[2,4,19,"耶和華於米甸諭摩西曰、可返埃及、欲索爾命者、皆死矣、"],[2,4,20,"摩西遂挈妻孥、乘之於驢、手執上帝之杖、而返埃及、"],[2,4,21,"耶和華諭摩西曰、汝歸時、我所示爾之異蹟、務行於法老前、我將使之剛愎厥心、不釋斯民、"],[2,4,22,"當告法老曰、耶和華云、以色列乃我冢子、"],[2,4,23,"故我諭爾、宜釋吾子、俾其崇事於我、而爾不欲釋之、我必殺爾冢子、"],[2,4,24,"摩西於途間之旅邸、耶和華遇之、欲致之死、"],[2,4,25,"西坡拉取火石、爲子行割、擲皮於其足前、曰、爾爲我流血之夫矣、"],[2,4,26,"旣而耶和華釋之、婦言爾爲我流血之夫、以行割故也、○"],[2,4,27,"耶和華諭亞倫曰、往於野、迓摩西、乃往、遇於上帝之山、與之接吻、"],[2,4,28,"摩西以耶和華遣之之言、及命其所行之異蹟、悉告亞倫、"],[2,4,29,"摩西亞倫遂往集以色列長老、"],[2,4,30,"亞倫以耶和華諭摩西之言告之、並行異蹟於民前、"],[2,4,31,"民乃信之、旣聞耶和華眷顧以色列人、鑒其困苦、遂俯首崇拜焉、"],[2,5,1,"厥後、摩西亞倫入告法老曰、以色列之上帝耶和華云、當釋吾民往野守節、"],[2,5,2,"法老曰、耶和華爲誰、使我聽其命、而釋以色列民乎、我不識耶和華、亦不釋以色列民、"],[2,5,3,"曰、希伯來人之上帝臨我、請爾許我適野、歷程三日、以祭我上帝耶和華、免其以疫癘鋒刃擊我、"],[2,5,4,"王曰、摩西亞倫、爾何釋民、俾不操作、爾其往服厥役、"],[2,5,5,"又曰、斯民衆多、爾乃弛其負擔、"],[2,5,6,"是日法老諭民之督工者、與其有司曰、"],[2,5,7,"厥後斯民陶瓦、勿如疇昔給之以草、使往自斂、"],[2,5,8,"所陶之瓦、其數如前、毋容少減、彼惰、故號呼曰、容我往祭我之上帝、"],[2,5,9,"當重其役、使之辛勞、不聽浮言、○"],[2,5,10,"民之督工者、與其有司、出告民曰、法老云、我不給爾以草、"],[2,5,11,"爾往可得之處斂之、爾工毋得少減、"],[2,5,12,"民乃散往埃及遍地、斂禾本以代草、"],[2,5,13,"督者促之曰、日竣其工、與昔有草同、"],[2,5,14,"法老所委之督、撻其所派以色列之有司、曰、昨與今日、所陶之瓦、不如曩之竣工何也、○"],[2,5,15,"以色列之有司入見法老、而呼籲曰、曷待僕如是、"],[2,5,16,"不給以草、而命陶瓦、僕又被撻、咎在王民、"],[2,5,17,"曰、爾惰矣、爾惰矣、故曰、容我往祭耶和華、"],[2,5,18,"爾往操作、不給爾草、瓦必如數以納、"],[2,5,19,"以色列之有司聞日所陶之瓦、毋容少減、則知已處於難、"],[2,5,20,"覲法老而出、遇摩西亞倫竚立於途、"],[2,5,21,"謂之曰、爾使我見惡於法老及羣臣、如惡惡臭、授刃其手以殺我、願耶和華鑒察辨白、○"],[2,5,22,"摩西返、詣耶和華曰、主歟、奚苦斯民、何爲遣我、"],[2,5,23,"自我覲法老、奉爾名與之言、彼益荼毒斯民、而爾未嘗拯之、"],[2,6,1,"耶和華諭摩西曰、今我所行於法老者、爾必目擊、使彼因我大能之手、釋吾民衆、驅之出境、○"],[2,6,2,"上帝諭摩西曰、我乃耶和華、"],[2,6,3,"昔我於亞伯拉罕、以撒、雅各、顯見爲全能之上帝、惟未嘗以我耶和華名示之、"],[2,6,4,"我與之約、錫以所旅之迦南地、"],[2,6,5,"今埃及人使以色列族服役、我聞其呻吟、追念吾約、"],[2,6,6,"當告以色列人曰、我乃耶和華、將脫爾於埃及人所加之重負、罷爾苦役、以奮臂巨災贖爾、"],[2,6,7,"我將以爾爲民、吾爲爾之上帝、使知我乃爾上帝耶和華、脫爾於埃及人所加之重負者、"],[2,6,8,"昔我誓賜亞伯拉罕以撒雅各之地、必導爾入之、予爾爲業、我乃耶和華也、"],[2,6,9,"摩西以告以色列人、彼緣役酷心憂、不聽其言、○"],[2,6,10,"耶和華諭摩西曰、"],[2,6,11,"入告埃及王法老、俾釋以色列民出其境、"],[2,6,12,"摩西曰、以色列人尚不我聽、法老焉能聽我拙口者乎、"],[2,6,13,"耶和華命摩西亞倫詣以色列族、與埃及王法老、導以色列人出埃及地、○"],[2,6,14,"以色列之族長、臚列如左、以色列長子流便之子、哈諾、法路、希斯崙、迦米、此乃流便之家、"],[2,6,15,"西緬之子耶母利、雅憫、阿轄、雅斤、瑣轄、及迦南女所生之掃羅、此乃西緬之家、"],[2,6,16,"利未之子、革順、哥轄、米拉利、依其世系、利未享壽一百三十七歲、"],[2,6,17,"革順之子、立尼、示每、依其家族、"],[2,6,18,"哥轄之子、暗蘭、以斯哈、希伯倫、烏薛、哥轄享壽一百三十三歲、"],[2,6,19,"米拉利之子、抹利、母示、此乃利未之家、依其世系、"],[2,6,20,"暗蘭娶其姑約基別、生亞倫、摩西、暗蘭享壽一百三十七歲、"],[2,6,21,"以斯哈之子、哥拉、尼斐、細基利、"],[2,6,22,"烏薛之子、米沙利、以利撒反、西提利、"],[2,6,23,"亞倫娶亞米拿達女、拿順妹以利沙巴、生拿答、亞比戶、以利亞撒、以他瑪、"],[2,6,24,"可拉之子、亞惜、以利加拿、亞比亞撒、此乃可拉之家、"],[2,6,25,"亞倫之子以利亞撒、娶普鐵之女、生非尼哈、以上所載、皆利未之族長、俱依其家、"],[2,6,26,"耶和華所命導以色列人聯隊出埃及者、卽此摩西亞倫、"],[2,6,27,"後告埃及王法老、導以色列人出其境者、亦此二人也、○"],[2,6,28,"耶和華於埃及地、與摩西言時、諭之曰、"],[2,6,29,"我乃耶和華、當以我所諭爾者、悉告埃及王法老、"],[2,6,30,"摩西曰、我拙口、法老焉能聽我哉、"],[2,7,1,"耶和華諭摩西曰、我使爾於法老、如爲上帝、爾兄亞倫、代爾發言、"],[2,7,2,"我所諭爾者、當悉言之、爾兄亞倫宜告法老、俾釋以色列人出其境、"],[2,7,3,"我將使之剛愎厥心、且多行我之異蹟奇事於埃及、"],[2,7,4,"法老必不聽爾、我將伸手於埃及、降以巨災、導我軍旅以色列民出其境、"],[2,7,5,"我伸手於埃及、導以色列民出其間、則埃及人知我爲耶和華、"],[2,7,6,"摩西亞倫遵耶和華命而行、"],[2,7,7,"語法老時、摩西年八十、亞倫八十有三、○"],[2,7,8,"耶和華諭摩西亞倫曰、"],[2,7,9,"法老命爾行奇事以爲徵、可令亞倫執杖、擲於其前、俾化爲蛇、"],[2,7,10,"摩西亞倫入覲法老、遵耶和華命而行、亞倫擲杖於法老及羣臣前、遂化爲蛇、"],[2,7,11,"法老召博士及巫覡、卽埃及之術士至、亦施厥術、以行是事、"],[2,7,12,"各擲其杖、俱化爲蛇、而其杖爲亞倫之杖所吞、"],[2,7,13,"法老剛愎厥心、不聽從之、如耶和華所言、○"],[2,7,14,"耶和華諭摩西曰、法老心頑、不欲釋民、"],[2,7,15,"詰朝法老詣河、爾往、立於河濱迎之、手執化蛇之杖、"],[2,7,16,"告之曰、希伯來人之上帝耶和華、遣我見爾曰、宜釋吾民、使往曠野、崇事於我、迄今爾未從之、"],[2,7,17,"耶和華曰、我將以杖擊河水、其水必變爲血、緣此、爾乃知我爲耶和華、"],[2,7,18,"河魚將亡、河水將臭、埃及人厭飲其水、"],[2,7,19,"耶和華諭摩西曰、當命亞倫云、執爾杖、伸手於埃及之水、使其江河池沼、咸變爲血、埃及遍地、木石諸器、無不有血、○"],[2,7,20,"摩西亞倫遵命而行、於法老及羣臣前、舉杖擊河水、其水變爲血、"],[2,7,21,"河魚盡斃、河水悉臭、埃及人不能飲其水、通國有血、"],[2,7,22,"埃及術士亦施厥術、以行是事、法老剛愎厥心、不聽從之、如耶和華所言、"],[2,7,23,"法老返宮、不以爲意、"],[2,7,24,"埃及人不能飲河水、乃沿河掘地、求水而飲、"],[2,7,25,"耶和華擊河、歷至七日、"],[2,8,1,"耶和華諭摩西曰、入覲法老、告之曰、耶和華云、宜釋吾民、使其崇事於我、"],[2,8,2,"如不釋之、我必使蛙害爾四境、"],[2,8,3,"蛙必滋生於河、上而進爾宮庭、入爾寢室、登爾牀榻、入爾臣之屋、上爾民之身、及乎爐竈麪器、"],[2,8,4,"蛙必上於爾身、與爾臣民之身、"],[2,8,5,"耶和華諭摩西曰、當命亞倫云、執爾杖、伸手於江河池沼、使蛙上於埃及地、"],[2,8,6,"亞倫遂伸手於埃及之水、蛙至、充斥埃及、"],[2,8,7,"術士亦施厥術、使蛙至於埃及、○"],[2,8,8,"法老召摩西亞倫曰、爾其求耶和華、去蛙離我及我民、我則釋斯民、俾祭耶和華、"],[2,8,9,"摩西曰、惟命是聽、當於何時、爲爾與爾臣民求、使蛙滅於爾身、及爾宮庭、第留於河、"],[2,8,10,"曰、明日、曰、可如爾言、使爾知我上帝耶和華、無可比擬、"],[2,8,11,"蛙必離爾、與爾宮庭、及爾臣民、第留於河、"],[2,8,12,"摩西亞倫退、摩西爲耶和華所降法老之蛙災籲焉、"],[2,8,13,"耶和華如摩西所言、第宅庭院田疇之蛙悉斃、"],[2,8,14,"人積之成堆、地因而腥臭、"],[2,8,15,"法老見災暫弭、剛愎厥心、不聽從之、如耶和華所言、○"],[2,8,16,"耶和華諭摩西曰、當命亞倫云、舉爾杖以擊塵土、使化爲蚋、遍於埃及地、"],[2,8,17,"乃遵命而行、亞倫執杖、伸手以擊塵土、遂有蚋附於人畜之身、埃及通國之塵土、悉化爲蚋、"],[2,8,18,"術士亦施厥術、欲生蚋而不能、蚋在人畜、"],[2,8,19,"術士告法老曰、此上帝之手也、法老剛愎厥心、不聽從之、如耶和華所言、○"],[2,8,20,"耶和華諭摩西曰、詰朝法老詣水濱、汝夙興、立於其前、告之曰、耶和華云、宜釋吾民、使其崇事於我、"],[2,8,21,"如不釋之、我必遣羣蠅集於爾、曁爾臣民、入爾宮庭、充斥埃及人之第宅、與其所處之地、"],[2,8,22,"是時我將區別我民所居之歌珊、在彼必無羣蠅、使爾知我爲耶和華於宇內、"],[2,8,23,"區別我民與爾民、明日必有此徵、"],[2,8,24,"耶和華如言而行、遂有羣蠅爲災、入法老宮庭、及羣臣第宅、埃及遍地、俱受其害、○"],[2,8,25,"法老召摩西亞倫曰、爾往、祭爾上帝於斯土、"],[2,8,26,"摩西曰、此不宜也、我祭我上帝耶和華、必宰牲以獻、是埃及人所憎者、若於其前宰牲爲祭、彼豈不以石擊我乎、"],[2,8,27,"我儕必往曠野、歷程三日、以祭我上帝耶和華、依其所命、"],[2,8,28,"法老曰、我今釋爾、俾祭爾上帝耶和華於野、第勿遠行、願爲我祈、"],[2,8,29,"摩西曰、我今退出、祈耶和華、使羣蠅明日離乎法老及臣民、但法老毋再欺、不釋斯民往祭耶和華、"],[2,8,30,"摩西退、禱於耶和華、"],[2,8,31,"耶和華如摩西所言、使羣蠅離乎法老與臣民、一無所遺、"],[2,8,32,"是時法老仍剛愎厥心、不釋斯民、"],[2,9,1,"耶和華諭摩西曰、入覲法老、告之曰、希伯來人之上帝耶和華云、宜釋吾民、使其崇事於我、"],[2,9,2,"如其不釋、而仍拘之、"],[2,9,3,"則耶和華加手於爾在田之羣畜、馬驢駱駝牛羊、必有重疫、"],[2,9,4,"以色列與埃及之羣畜、耶和華必區別之、以色列人所有、無一斃者、"],[2,9,5,"耶和華定期曰、明日我於斯土、必行是事、"],[2,9,6,"翌日、耶和華果行之、埃及之羣畜盡斃、而以色列族之羣畜、無一斃者、"],[2,9,7,"法老使人瞷之、見以色列族之羣畜、一無所斃、惟法老心頑、不釋斯民、○"],[2,9,8,"耶和華諭摩西亞倫曰、取爐灰盈掬、摩西於法老前、向天揚之、"],[2,9,9,"必化爲塵、徧於埃及、俾通國人畜、生瘍與疹、"],[2,9,10,"二人遂取爐灰、立法老前、摩西向天揚之、使人及畜生瘍與疹、"],[2,9,11,"術士因有瘡痍、不能立於摩西前、蓋術士與埃及人、皆生瘍也、"],[2,9,12,"耶和華使法老剛愎厥心、不聽從之、如耶和華所諭摩西之言、○"],[2,9,13,"耶和華諭摩西曰、詰朝夙興、立法老前、告之曰、希伯來人之上帝耶和華云、宜釋吾民、使其崇事於我、"],[2,9,14,"今我必降諸災於爾、以及臣民、使爾知宇內無如我者、"],[2,9,15,"我若伸手、以疫擊爾、及爾之民、爾必見滅於斯世、"],[2,9,16,"然我之立爾、實欲顯我能於爾、且揚我名於天下、"],[2,9,17,"爾猶自高、禁阻我民、不釋之往乎、"],[2,9,18,"明日此時、我必雨雹甚厲、自埃及肇基迄今、無若是者、"],[2,9,19,"今當遣人促爾羣畜、及田間所有、使之旋返、凡人與畜、在田不歸者、雹必降而斃之、"],[2,9,20,"法老之臣畏耶和華言者、使僕與畜避歸於舍、"],[2,9,21,"其不以耶和華言爲意者、則遺僕與畜於田、○"],[2,9,22,"耶和華諭摩西曰、舉手向天、使雹雨於埃及、傷通國之人畜、及其田蔬、"],[2,9,23,"摩西遂舉杖向天、耶和華使雷震雹降、火閃於地、雹遍埃及、"],[2,9,24,"雹中雜火、其勢甚烈、自埃及肇基以來、未之有也、"],[2,9,25,"埃及通國人畜、凡在田者、咸被雹擊、田蔬悉傷、園木盡折、"],[2,9,26,"惟以色列人所居之歌珊無雹、○"],[2,9,27,"法老召摩西亞倫曰、我今有罪、耶和華乃義、我與我民皆惡也、"],[2,9,28,"雷轟雹降足矣、請禱於耶和華、我則釋汝、不復留此、"],[2,9,29,"摩西曰、俟我出邑、卽舉手以禱耶和華、雷必止、雹不降、使爾知宇內悉屬耶和華、"],[2,9,30,"然我知爾與羣臣、不畏上帝耶和華、"],[2,9,31,"當時麰麥初穗、胡麻始華、是以俱壞、"],[2,9,32,"小麥麤麥未長、是以不壞、"],[2,9,33,"摩西退、出邑、舉手以禱耶和華、雷雹卽止、雨不復注、"],[2,9,34,"法老見雨雹與雷皆止、仍干罪戾、同其羣臣剛愎厥心、"],[2,9,35,"其心頑梗、不釋以色列人、如耶和華所諭摩西之言、"],[2,10,1,"耶和華諭摩西曰、入覲法老、我旣使彼與其羣臣剛愎厥心、以顯我異蹟於其間、"],[2,10,2,"俾爾以我於埃及所爲之事、曁行於其中之異蹟、告爾子若孫、使爾知我爲耶和華、"],[2,10,3,"摩西亞倫入覲法老曰、希伯來人之上帝耶和華諭云、爾於我前、不欲自卑、將至何時、宜釋吾民、使其崇事於我、"],[2,10,4,"如不釋之、明日我將使蝗入爾境、"],[2,10,5,"掩蔽於地、無隙可見、必食雹所未壞之餘、以及園中諸木、"],[2,10,6,"爾之宮庭、及羣臣之第宅、埃及人之家室、咸充斥之、自爾祖父高曾在世、以迄於今、未之見也、摩西返身而退、"],[2,10,7,"羣臣奏法老曰、斯人陷我、伊于胡底、宜釋其人、使崇事其上帝耶和華、豈不知埃及危亡乎、"],[2,10,8,"乃復召摩西亞倫詣法老、法老曰、往哉、崇事爾上帝耶和華、但欲往者何人、"],[2,10,9,"摩西曰、我儕老幼子女、以及牛羊、無不偕往、蓋我必守節期、以奉耶和華、"],[2,10,10,"曰、與其釋爾及爾幼稚、寧願耶和華偕爾、汝其愼之、禍在爾前、"],[2,10,11,"不可皆行、惟長者往崇事耶和華、此爾之所欲也、遂驅之出、○"],[2,10,12,"耶和華諭摩西曰、伸手於埃及、使蝗入其境、盡食田蔬、卽經雹所遺者、"],[2,10,13,"摩西舉杖於埃及、耶和華令東風吹其地、終日終夜、明晨、風吹蝗至、"],[2,10,14,"蝗至埃及、止於四境、其災甚厲、若斯之蝗、先世後世、未之有也、"],[2,10,15,"蝗蔽於地、地因而晦冥、田蔬及雹擊所遺之木實、悉爲所食、埃及通國、林木田蔬、青葱之物、無復遺餘、"],[2,10,16,"法老急召摩西亞倫曰、我獲罪於爾上帝耶和華、亦獲罪於爾、"],[2,10,17,"惟此一次、求宥我罪、禱爾上帝耶和華、脫我於此死、"],[2,10,18,"摩西退、禱於耶和華、"],[2,10,19,"耶和華轉令西風暴作、吹起厥蝗、驅入紅海、埃及境內、一無所遺、"],[2,10,20,"耶和華使法老剛愎厥心、不釋以色列人、○"],[2,10,21,"耶和華諭摩西曰、舉手向天、使埃及地晦冥、其暗可捫、"],[2,10,22,"摩西舉手向天、遍埃及地、晦冥甚深、三日之久、"],[2,10,23,"三日之間、各不相見、無人起離其所、惟以色列人之第宅有光、"],[2,10,24,"法老召摩西曰、爾往崇事耶和華、幼稚可偕、只留牛羊、"],[2,10,25,"摩西曰、必給我祭品燔牲、以祭我上帝耶和華、"],[2,10,26,"我之牲畜、亦當偕往、弗遺一蹄、我必以此奉事我上帝耶和華、未臨其地、不知以何物奉事之、"],[2,10,27,"耶和華使法老剛愎厥心、弗釋以色列人、"],[2,10,28,"法老曰、爾且退、愼之哉、勿復覿我面、覿面之日、爾必死、"],[2,10,29,"摩西曰、爾之言然、我不復覿爾面矣、"],[2,11,1,"耶和華諭摩西曰、我再降一災於法老與埃及、然後彼乃釋汝去此、釋時、促爾出境、"],[2,11,2,"當語庶民、使諸男女、索金飾銀飾於其鄰、"],[2,11,3,"耶和華使民沾恩於埃及人、摩西在埃及、於法老臣民前、極其尊大、○"],[2,11,4,"摩西謂法老曰、耶和華云、約至中夜、我將巡行埃及、"],[2,11,5,"自居位之法老、迄旋磨之婢女、凡其長子、及羣畜首生者、必皆死亡、"],[2,11,6,"埃及通國、必大號哭、先世後世、無若是者、"],[2,11,7,"至以色列族、或人或畜、無犬敢鼓舌以吠之、俾爾知埃及人與以色列人、爲耶和華所區別、"],[2,11,8,"爾之羣臣必下詣我、俯伏我前、曰、爾其與從爾之衆出境、然後我乃出焉、摩西盛怒而退、○"],[2,11,9,"耶和華諭摩西曰、法老必不聽爾、致增我之異蹟於埃及地、"],[2,11,10,"摩西亞倫行此異蹟於法老前、而耶和華使之剛愎厥心、不釋以色列人出其境、"],[2,12,1,"耶和華於埃及諭摩西亞倫曰、"],[2,12,2,"是月必爲爾之正月、而作歲首、"],[2,12,3,"當告以色列會衆曰、是月十日、按其家族、各家必取一羔、"],[2,12,4,"若其人寡、一羔食不能盡、則與比鄰同取、隨其人數、各如其量、"],[2,12,5,"羔宜一歲牡而無疵者、取於綿羊山羊、俱可、"],[2,12,6,"留至是月十四日夕、以色列會衆皆宰羔、"],[2,12,7,"取血以釁左右橛、及門楣、於食羔之室、"],[2,12,8,"是夕炙其肉、與無酵餅共苦菜食之、"],[2,12,9,"勿生食、勿水烹、必炙以火、首足與臟、皆食之、"],[2,12,10,"無留於明晨、留於明晨者、以火燬之、"],[2,12,11,"當腰束帶、足納履、手執杖、迅速而食、是爲耶和華之逾越節、"],[2,12,12,"是夜我將巡行埃及、擊其長子、與羣畜首生者、而罰埃及諸神、我乃耶和華、"],[2,12,13,"惟汝居室、以血爲徵、我見之、將逾越爾、擊埃及時、不令施剿者臨爾、"],[2,12,14,"當誌是日、以爲耶和華之節期、歷世守之、永爲定例、○"],[2,12,15,"七日間、當食無酵餅、首日必於爾室除酵、自首日至七日、凡食酵者、必絕於以色列、"],[2,12,16,"首日必集聖會、七日亦集聖會、是二日、勿操作、惟備食而已、"],[2,12,17,"當守除酵節、蓋是日我導爾軍旅出埃及、歷世守之、永爲定例、"],[2,12,18,"正月十四日夕、至二十一日夕、宜食無酵餅、"],[2,12,19,"七日間、勿存酵於爾室、無論賓旅土著、若食有酵之物、必絕於以色列會、"],[2,12,20,"有酵者勿食、凡百居所、當食無酵餅、○"],[2,12,21,"摩西召以色列長老、謂之曰、隨爾家數、取羔宰之、以爲逾越節禮、"],[2,12,22,"束牛膝草、濡盂中血、以釁門楣、與左右橛、至明晨勿出戶、"],[2,12,23,"蓋耶和華將巡行、擊埃及人、見楣橛釁血、必逾越其門、不令施剿者入室擊爾、"],[2,12,24,"爾與子孫、必守此禮、永爲定例、"],[2,12,25,"至耶和華所許錫爾之地、宜守此禮、"],[2,12,26,"如爾子孫問曰、行此禮曷故、"],[2,12,27,"則曰、是乃耶和華逾越之祭禮、當耶和華擊埃及時、逾越我第宅、拯救我家屬、於是以色列民俯首而拜、"],[2,12,28,"往遵耶和華所諭摩西亞倫之命而行、○"],[2,12,29,"中夜、耶和華擊埃及地諸長子、自居位之法老、至獄中之俘囚、凡其長子、及羣畜首生者、無不隕沒、"],[2,12,30,"法老與其羣臣、曁埃及民衆、夜間悉起、埃及大有哀號、蓋無家無死者、"],[2,12,31,"法老夜召摩西亞倫曰、爾與以色列族、其起、出離我民、而往崇事耶和華、如爾所言、"],[2,12,32,"亦攜牛羊偕往、如爾所言、更請爲我祝嘏、"],[2,12,33,"埃及人促以色列民、速出其境、曰、我儕皆死人也、"],[2,12,34,"民取未置酵之溼麪、以衣裹摶器、荷之於肩、"],[2,12,35,"亦從摩西言、索金飾銀飾及衣服於埃及人、"],[2,12,36,"耶和華使民沾恩於埃及人、悉予所索、遂取埃及人之財物、○"],[2,12,37,"以色列人自蘭塞啟行、至於疎割、童穉而外、徒行丁男、約六十萬、"],[2,12,38,"亦有雜族之衆同行、羣畜牛羊甚多、"],[2,12,39,"民以所攜無酵溼麪、炊爲無酵餅、因其被促出境、不得濡滯、且未備餱糧也、"],[2,12,40,"以色列人旅於埃及、共歷四百三十年、"],[2,12,41,"四百三十年旣竟、是日耶和華之軍旅、咸出埃及、"],[2,12,42,"是夜耶和華導之出埃及、當爲耶和華特守之、以色列衆當歷世守是夜、○"],[2,12,43,"耶和華諭摩西亞倫曰、逾越節例、外人不可食羔、"],[2,12,44,"惟以金所購之僕、旣受割、則可食、"],[2,12,45,"賓旅與傭人、不可食、"],[2,12,46,"食之必在一室、毋攜肉於外、不折一骨、"],[2,12,47,"以色列會衆、宜皆守此禮、"],[2,12,48,"有外人寓於爾中、欲爲耶和華守逾越節、必其丁男受割、然後容其進而守之、同於土著、惟未受割者不可食、"],[2,12,49,"土著與寓於爾中之外人、皆同一例、"],[2,12,50,"以色列人遂遵耶和華所諭摩西亞倫之命而行、"],[2,12,51,"是日耶和華導以色列人、聯隊出埃及、"],[2,13,1,"耶和華諭摩西曰、"],[2,13,2,"以色列族中、凡首生者、無論人畜、皆當爲我區別爲聖、乃屬於我、○"],[2,13,3,"摩西語民曰、是日耶和華以其手力、導爾出埃及、脫於奴隸之室、故當誌之、毋食有酵餅、"],[2,13,4,"是日乃亞筆月、卽爾出時、"],[2,13,5,"迨耶和華導爾入迦南人、赫人、亞摩利人、希未人、耶布斯人之境、卽其誓於爾祖、賜爾流乳與蜜之地、當於是月守此禮、"],[2,13,6,"七日間、當食無酵餅、至七日、乃耶和華之節期、"],[2,13,7,"斯七日、必食無酵餅、酵餅與酵、毋得見於爾之全境、"],[2,13,8,"其時當告汝子云、是禮也、乃誌出埃及時、耶和華爲我所行者、"],[2,13,9,"當以之爲號於手、爲記於額、俾耶和華之法律、恆在爾口、蓋耶和華施厥大能、導爾出埃及、"],[2,13,10,"每歲屆期、必守此例、○"],[2,13,11,"迨耶和華依其所誓於爾、及爾祖者、導爾入迦南、錫爾以斯土、"],[2,13,12,"必以初胎之男子、首生之牡畜、區別歸於耶和華、"],[2,13,13,"首生之驢、必贖以羔、否則折其頸、爾中男子、凡爲首生、必皆贖之、"],[2,13,14,"異日爾子若問爾曰、此何意也、則告之曰、耶和華以其手力、導我出埃及、脫於奴隸之室、"],[2,13,15,"法老頑梗、不釋我往、耶和華將埃及之首生者、或人或畜、盡皆誅戮、故我以首生之牡畜祭之、其初胎之男子、則贖之焉、"],[2,13,16,"當以之爲號於手、爲飾於額、蓋耶和華以其手力、導我出埃及、○"],[2,13,17,"法老旣釋斯民、上帝不導之經非利士之近途、蓋曰、恐民遇戰、或生悔心、旋歸埃及、"],[2,13,18,"乃導之沿紅海、遶野而行、以色列人執兵出埃及、"],[2,13,19,"昔約瑟使以色列人誓、曰、上帝必眷顧爾、須攜我骨偕歸、故摩西攜之歸、"],[2,13,20,"民自疎割啟行、列營於以倘、在野之隅、"],[2,13,21,"耶和華先之而往、晝在雲柱以導之、夜在火柱以燭之、俾其行邁、晝夜俱可、"],[2,13,22,"晝之雲柱、夜之火柱、弗離民前、"],[2,14,1,"耶和華諭摩西曰、"],[2,14,2,"命以色列人旋返、在密奪與海間之比哈希錄境、巴力洗分前、建營於相近之海濱、"],[2,14,3,"法老必謂以色列族迷於途、困於野、"],[2,14,4,"我必使之剛愎厥心、追襲於後、我將獲榮於法老、及其軍旅、俾埃及人知我爲耶和華、以色列人遂如是行、"],[2,14,5,"或以民遁告埃及王、法老與羣臣乃變厥心、曰、奚爲釋以色列族、俾不服役於我、"],[2,14,6,"遂備其車、率軍偕往、"],[2,14,7,"並率特簡之車六百乘、及通國之車、各有車長、"],[2,14,8,"耶和華使埃及王法老剛愎厥心、追襲以色列人、以色列人毅然而出、"],[2,14,9,"埃及人衆、法老之車馬軍旅追之、及於瀕海建營之處、近比哈希錄、在巴力洗分前、○"],[2,14,10,"法老相去伊邇、以色列族舉目、見埃及人追襲其後、懼甚、呼籲耶和華、"],[2,14,11,"謂摩西曰、豈以埃及無塚地、而導我出、使亡於野乎、曷待我如是、俾我去埃及耶、"],[2,14,12,"我在埃及時、豈不曰、任我爲埃及人服役、與其死於曠野、寧服役於埃及人、"],[2,14,13,"摩西曰、毋懼、可立而觀耶和華今日爲爾所施之拯救、蓋是日所見之埃及人、後必不復見也、"],[2,14,14,"耶和華必代爾戰、爾惟默然、○"],[2,14,15,"耶和華諭摩西曰、胡爲籲我、當命以色列人前往、"],[2,14,16,"爾其舉杖、伸手指海、令其中判、以色列民入海履陸、"],[2,14,17,"我必使埃及人剛愎厥心、追入於海、我將因法老、及其軍旅車騎而獲榮焉、"],[2,14,18,"我旣獲榮於法老、及其車騎、則埃及人始知我爲耶和華、"],[2,14,19,"上帝之使昔行於以色列營前、今移於後、雲柱亦離其前、而立於後、"],[2,14,20,"在埃及以色列二營之間、有雲有暗、夕則發光、彼此終夜不相近、○"],[2,14,21,"摩西伸手指海、耶和華令東風大作、海水一夜退流、海遂爲陸、水判於中、"],[2,14,22,"以色列人入海履陸、左右水爲壁壘、"],[2,14,23,"埃及人衆、法老之車騎、盡皆追襲其後、而入於海、"],[2,14,24,"昧爽、耶和華自火雲柱中、俯視埃及軍旅、亂其行伍、"],[2,14,25,"脫其車輪、使之難行、埃及人曰、耶和華爲以色列族而攻我、我其避之而遁、○"],[2,14,26,"耶和華諭摩西曰、伸手指海、使水反淹埃及人、及其車騎、"],[2,14,27,"摩西伸手指海、及旦、水復反如故、埃及人趨而避之、耶和華投之於海、"],[2,14,28,"法老之軍旅車騎、追隨以色列族入於海者、海水回流、悉淹沒之、靡有孑遺、"],[2,14,29,"惟以色列人、在海中行陸地、左右水爲壁壘、"],[2,14,30,"是日耶和華拯以色列民、脫於埃及人手、以色列民目覩埃及人之屍於海濱、"],[2,14,31,"又見耶和華於埃及人所施之大能、遂寅畏耶和華、而篤信之、亦信其僕摩西、"],[2,15,1,"維時、摩西與以色列民謳歌、頌美耶和華曰、我欲歌頌耶和華、以其顯榮獲勝、馬與騎者、俱投於海、"],[2,15,2,"耶和華乃我之力、是我所歌、爲我之援、我之上帝、我稱揚之、我父之上帝、我尊崇之、"],[2,15,3,"耶和華爲戰士、其名乃耶和華、"],[2,15,4,"法老之車、與其軍旅、悉投於海、特簡之將、胥溺紅海、"],[2,15,5,"波濤覆之、如石沉淵、"],[2,15,6,"耶和華歟、爾之右手表彰榮力、耶和華歟、爾之右手糜爛寇讎、"],[2,15,7,"大顯威嚴、傾覆叛逆、爰發烈怒、燬之若蒭、"],[2,15,8,"鼻噓水累、浪立如堆、水凝海中、"],[2,15,9,"敵云、我將追之、且必及之、分其財物、以厭我心、拔我刀劍、手殲厥衆、"],[2,15,10,"爾吹以風、海則淹之、如鉛之沉、沒於洪水、"],[2,15,11,"耶和華歟、諸神之中、誰其似汝、旣聖且榮、可頌可畏、施行異蹟、孰堪比擬、"],[2,15,12,"爾伸右手、敵爲地吞、"],[2,15,13,"所贖之民、以慈導之、施厥大能、引入聖所、"],[2,15,14,"列邦聞之而戰慄、非利士居民因之而悽愴、"],[2,15,15,"以東侯伯悚惶、摩押英豪震慴、迦南居民銷鑠、"],[2,15,16,"驚駭恐懼、臨及其身、耶和華歟、因爾巨臂、彼皆寂然如石、俟爾之民過焉、俟爾所贖之民過焉、"],[2,15,17,"爾必導之而入、樹之於爾恆業之山、卽爾耶和華爲己所備之居所、爾手所立之聖所、"],[2,15,18,"耶和華秉權、歷世靡曁、○"],[2,15,19,"法老之馬、與其車騎入海、耶和華使水回流淹沒之、惟以色列人在海中行陸地、"],[2,15,20,"亞倫姊女先知米利暗、手執鼗、諸女亦執鼗相從、舞蹈而出、"],[2,15,21,"米利暗和之曰、爾其歌頌耶和華、以其顯榮獲勝、馬與騎者、俱投於海、○"],[2,15,22,"摩西引以色列族、離紅海而前行、至書珥野歷程三日、而不見水、"],[2,15,23,"至瑪拉、水苦不能飲、故其地名曰瑪拉、"],[2,15,24,"民怨摩西曰、我將何飲、"],[2,15,25,"摩西籲耶和華、耶和華示之以木、遂投諸水中、其水卽甘、在彼耶和華立典及律、以試斯民、"],[2,15,26,"曰、爾若聽爾上帝耶和華言、行其所義、循其誡、守其典、則我所加於埃及人之疾、必不加諸爾、我乃耶和華醫爾者也、"],[2,15,27,"民至以琳、在彼有水泉十二、椶樹七十、乃近水建營焉、"],[2,16,1,"以色列人自以琳啟行、出埃及後、二月望日、會衆至於汛野、在以琳西乃間、"],[2,16,2,"會衆於野、怨摩西亞倫曰、"],[2,16,3,"願在埃及、死於耶和華手、爾時坐於肉鼎之側、食餅而飽、爾導我入此野、是欲以饑殺斯會衆也、○"],[2,16,4,"耶和華諭摩西曰、我必自天雨糧、民宜日出、斂日所需、以試其遵我法律否、"],[2,16,5,"至於六日、所斂者必備之、其數倍於他日、"],[2,16,6,"摩西亞倫語以色列人曰、至夕必知導爾出埃及者、乃耶和華、"],[2,16,7,"詰朝爾將覩耶和華之榮光、蓋爾出怨言、耶和華聞之矣、我何人斯、爾乃怨我、"],[2,16,8,"摩西又曰、迨耶和華夕食爾以肉、朝飽爾以糧、此言始應、蓋爾之怨言、耶和華聞之矣、我何人斯、爾非怨我、乃怨耶和華也、"],[2,16,9,"摩西謂亞倫曰、告以色列會衆云、進於耶和華前、蓋爾之怨言、彼已聞之、"],[2,16,10,"亞倫言時、以色列會衆瞻望於野、見耶和華之榮光顯於雲中、"],[2,16,11,"耶和華諭摩西曰、"],[2,16,12,"以色列族之怨言、我已聞之、當告之曰、夕必食肉、朝必飽糧、則知我乃爾之上帝耶和華、○"],[2,16,13,"夕有鶉來、蔽乎營壘、朝有露降、在營四周、"],[2,16,14,"厥露旣晞、野有圓物、細微如霜、"],[2,16,15,"以色列民見而弗識、相語曰、此何物耶、摩西曰、此耶和華食爾之糧、"],[2,16,16,"耶和華之命曰、各宜斂取、如其食量、視幕中人數、各得一俄梅爾、"],[2,16,17,"以色列人遵命而取、或多或寡、"],[2,16,18,"以量量之、多者無餘、寡者無乏、其斂之也、各隨其量、"],[2,16,19,"摩西告民曰、毋留其餘、逮於明旦、"],[2,16,20,"有不從摩西言者、留之明旦、乃生蟲而臭惡、摩西怒焉、○"],[2,16,21,"每晨各如食量而斂之、日暴則消、"],[2,16,22,"至於六日、斂糧倍之、人得二俄梅爾、諸會長來告摩西、"],[2,16,23,"摩西曰、耶和華有言曰、翌日安息、乃耶和華之聖日、欲炙者炙、欲煮者煮、食旣有餘、存於明旦、"],[2,16,24,"乃遵摩西命、存於明旦、不臭惡、不生蟲、"],[2,16,25,"摩西曰、今日可食此、蓋今爲耶和華之安息日、在野索之不得、"],[2,16,26,"六日間、可斂之、惟七日乃安息、必無所有、"],[2,16,27,"至七日、民有出而斂者、索之不得、"],[2,16,28,"耶和華諭摩西曰、爾曹不守我誡、不遵我律、將至何時、"],[2,16,29,"耶和華以安息日賜爾、故於六日、予爾兼日之糧、至七日、各居其地、勿出其所、"],[2,16,30,"民遂於七日安息焉、○"],[2,16,31,"以色列族稱斯糧曰瑪那、狀如芫荽子、其色白、味如蜜餅、"],[2,16,32,"摩西曰、耶和華命以此物一俄梅爾、留於後世、使見我導汝出埃及時、於野所食爾之糧、"],[2,16,33,"遂語亞倫曰、以壺盛瑪那一俄梅爾、置之耶和華前、留於後世、"],[2,16,34,"亞倫遵耶和華所命摩西者、置於法匱前以存之、"],[2,16,35,"以色列人食瑪那、歷四十年、迨至迦南境、人居之處而後已、"],[2,16,36,"一俄梅爾、乃伊法十分之一、"],[2,17,1,"以色列會衆遵耶和華命、自汛野啟行、依程而進、建營於利非訂、無水可飲、"],[2,17,2,"民與摩西爭曰、飲我以水、摩西曰、奚與我爭、奚試耶和華乎、"],[2,17,3,"民渴、索水、怨摩西曰、曷導我出埃及、使我與子及畜、燥渴而死、"],[2,17,4,"摩西籲耶和華曰、斯民幾欲以石擊我、何以待之、"],[2,17,5,"耶和華曰、爾執擊河之杖、率以色列長老數人、過於民前、"],[2,17,6,"我於何烈磐上、向爾而立、爾擊斯磐、水由之出、使民得飲、摩西遂於以色列長老前行此、"],[2,17,7,"名其地曰瑪撒、亦曰米利巴、因以色列人爭於斯、並試耶和華曰、耶和華在我中否也、○"],[2,17,8,"時、亞瑪力族至、與以色列人戰於利非訂、"],[2,17,9,"摩西命約書亞曰、爲我選人、出與亞瑪力戰、明日我執上帝杖、立於山巔、"],[2,17,10,"約書亞遵摩西命、與亞瑪力戰、摩西亞倫戶珥俱陟山巔、"],[2,17,11,"摩西舉手、則以色列勝、垂手、則亞瑪力勝、"],[2,17,12,"摩西手疲、亞倫戶珥移石使坐、左右扶持、手乃穩固、至於日入、"],[2,17,13,"約書亞以刃擊仆亞瑪力王與其民、"],[2,17,14,"耶和華諭摩西曰、我將塗亞瑪力之誌於天下、當筆之於簡、誦之於約書亞耳、"],[2,17,15,"摩西築壇、名之曰耶和華尼西、"],[2,17,16,"曰、亞瑪力舉手攻耶和華之座、故耶和華必與之戰、歷世靡曁、"],[2,18,1,"摩西外戚、米甸祭司葉忒羅、聞上帝爲摩西、與上帝之民以色列所爲、卽耶和華導以色列人出埃及、"],[2,18,2,"昔摩西遣其妻西坡拉歸於父家、今其外戚葉忒羅攜之以來、"],[2,18,3,"及其二子、其一摩西命名革順、蓋曰、我於異邦爲旅、"],[2,18,4,"其一命名以利以謝、蓋曰、我父之上帝佑我、拯我脫於法老刃、"],[2,18,5,"摩西外戚葉忒羅攜其妻孥、詣之於野、近上帝山、建營之處、"],[2,18,6,"遣人告曰、我葉忒羅、爾之外戚、攜爾之妻、及其二子、偕來就爾、"],[2,18,7,"摩西出迓之、伏拜接吻、彼此問安入幕、"],[2,18,8,"摩西以耶和華緣以色列故、所行於法老與埃及人、並在途所歷之艱難、及耶和華之救援、具告其外戚、"],[2,18,9,"葉忒羅因耶和華施諸恩於以色列、脫之於埃及人手、欣喜不勝、"],[2,18,10,"曰、當頌美耶和華、彼拯爾曹、脫於埃及人與法老之手、援斯民於埃及人、"],[2,18,11,"今知耶和華較諸神爲大、卽於埃及人狂傲之事顯之也、"],[2,18,12,"葉忒羅以燔祭及他祭、獻於上帝、亞倫曁以色列長老咸集、與摩西外戚食於上帝前、○"],[2,18,13,"翌日摩西坐以鞫民、民立於側、自朝至暮、"],[2,18,14,"摩西外戚見其所行於民、則曰、汝於斯民何爲、爾奚獨坐、而民環立、自朝迄暮、"],[2,18,15,"摩西曰、民就我諮詢於上帝耳、"],[2,18,16,"人與其鄰有訟、則至我前、我折中於其間、且以上帝典章法度教之、"],[2,18,17,"摩西外戚曰、汝所爲非宜也、"],[2,18,18,"此事繁重、爾難獨理、如是、則爾與民、必俱憊矣、"],[2,18,19,"我進一策、其聽我言、願上帝偕爾、汝向上帝、爲民代表、而呈其事於上帝、"],[2,18,20,"教以典章法度、示以必由之道、當爲之事、"],[2,18,21,"於衆民中、簡其具有才能、寅畏上帝、尚誠實、惡不義之財者、立爲千夫長、百夫長、五十夫長、十夫長、以治民、"],[2,18,22,"使其隨時鞫民、事大則呈爾、事小則自鞫、如是、彼與汝共任、而爾事輕矣、"],[2,18,23,"爾若行是、上帝亦以命爾、則爾可久、民亦安歸其所、"],[2,18,24,"摩西聆其外戚之訓、行其所言、"],[2,18,25,"於以色列衆中、簡其有才能者、立爲民長、卽千夫長、百夫長、五十夫長、十夫長、"],[2,18,26,"隨時鞫民、難事則以呈、細故則自鞫、"],[2,18,27,"摩西任其外戚旋歸、遂返故土、"],[2,19,1,"以色列人出埃及後、由利非訂啟行、"],[2,19,2,"越三月、至西乃野、建營山前、"],[2,19,3,"摩西登山、覲於上帝、耶和華呼之曰、告雅各家、諭以色列族云、"],[2,19,4,"我所行於埃及人、並負爾、如鷹以翼負雛、俾歸於我、爾咸覩之、"],[2,19,5,"宇內咸屬於我、爾果聽我言、守我約、則爾於列國中、特爲我業、"],[2,19,6,"亦爲祭司之國、成聖之民於我前、其以此言告以色列族、○"],[2,19,7,"摩西往召民間長老、悉以耶和華所命告之、"],[2,19,8,"衆民僉曰、凡耶和華所諭、我必奉行、摩西乃以民言覆於耶和華、"],[2,19,9,"耶和華諭摩西曰、我於密雲臨爾、我與爾言、俾民聽聞、而恆久信爾、摩西以民言告耶和華、"],[2,19,10,"耶和華曰、汝詣於民、使今日明日、潔己濯衣、"],[2,19,11,"以爲三日之備、蓋至三日、耶和華必降臨西乃山、爲衆民目擊、"],[2,19,12,"在山四周、爲民定界、告之曰、爾其愼之、毋陟於山、毋犯其境、犯之者、殺無赦、"],[2,19,13,"手勿捫之、必擊以石、或射以矢、無論人畜、不存其生、迨鳴角旣久、可至山前、"],[2,19,14,"摩西下山、至於民處、使之自潔、民乃濯衣、"],[2,19,15,"摩西謂之曰、必爲三日之備、勿近婦人、○"],[2,19,16,"三日黎明、雷電交作、密雲蔽山、角鳴甚厲、營中之民、罔不戰慄、"],[2,19,17,"摩西率民出營、以迓上帝、民立山下、"],[2,19,18,"耶和華於火中降臨西乃山、徧山有烟、其烟上騰、有若爐烟、全山大震、"],[2,19,19,"角鳴愈久、其聲愈厲、摩西發言、上帝以聲應之、"],[2,19,20,"耶和華臨涖西乃山巔、召摩西陟之、摩西陟焉、"],[2,19,21,"耶和華諭之曰、爾下戒民、勿越境、以窺耶和華、致多隕沒、"],[2,19,22,"卽近耶和華之祭司、亦當自潔、免我突出擊之、"],[2,19,23,"摩西曰、爾曾諭我、在山四周定界、區別爲聖、故民不得上之、"],[2,19,24,"耶和華曰、爾下、同亞倫上、惟祭司庶民、勿越境、上就耶和華、免其突出擊之、"],[2,19,25,"摩西遂下、以此告民、"],[2,20,1,"上帝垂諭曰、"],[2,20,2,"我乃爾之上帝耶和華、導爾出埃及、脫於奴隸之室、○"],[2,20,3,"余而外、勿更有他神、○"],[2,20,4,"勿雕偶像、勿造上天下地、地下水中、百物之像、"],[2,20,5,"勿拜跪、勿崇奉、以我耶和華爾之上帝、乃忌邪之上帝、惡我者、討其罪、自父及子、至三四世、"],[2,20,6,"愛我守我誡者、錫之慈惠、至千百世、○"],[2,20,7,"勿妄稱爾上帝耶和華之名、蓋耶和華必不以妄稱者爲無罪、○"],[2,20,8,"當誌安息日、守之爲聖、"],[2,20,9,"六日間、宜勤勞、作爾庶務、"],[2,20,10,"惟七日、乃爾上帝耶和華之安息、是日爾與子女、僕婢牲畜、及寓爾家之遠人、皆勿操作、"],[2,20,11,"蓋六日間、耶和華造天地海、曁其中萬物、七日休息、故耶和華錫嘏於安息日、別之爲聖、○"],[2,20,12,"當敬爾父母、以致延年於爾上帝耶和華所賜之地、○"],[2,20,13,"毋殺人、○"],[2,20,14,"毋行淫、○"],[2,20,15,"毋攘竊、○"],[2,20,16,"毋妄證以陷人、○"],[2,20,17,"毋貪人之第宅、與其妻室、僕婢牛驢、及凡所有、○"],[2,20,18,"民見雷轟、電閃、角鳴、烟騰於山、則戰懼、遙立、"],[2,20,19,"謂摩西曰、汝與我言、我必聽從、上帝勿與我言、恐我死亡、"],[2,20,20,"摩西曰、勿懼、上帝臨格以試爾、俾爾敬畏、免干厥罪、"],[2,20,21,"民仍遙立、摩西進於上帝所居晦冥之處、○"],[2,20,22,"耶和華諭摩西曰、告以色列人云、我自天與爾言、爾所覩也、"],[2,20,23,"勿造神像匹我、勿作金銀之像、"],[2,20,24,"當爲我以土築壇、獻牛羊於其上、以爲燔祭、及酬恩祭、凡誌吾名之所、我必臨格、錫嘏於爾、"],[2,20,25,"如爲我以石建壇、勿用雕琢之石、若以器加之、卽汚厥壇、"],[2,20,26,"升壇勿歷階、免露下體、"],[2,21,1,"茲有律例、當宣於民前曰、"],[2,21,2,"如購希伯來僕、可役事六年、迨七年、則使之自由、不索贖金、"],[2,21,3,"若孑身而來、則亦孑身而去、有妻則與俱去、"],[2,21,4,"若主給妻、生有子女、則妻孥屬主、僕孑然而去、"],[2,21,5,"若僕明言、我愛吾主、及我妻孥、不欲自由、"],[2,21,6,"則其主攜之詣上帝前、附門或門橛、以錐貫其耳、僕則恆事之、○"],[2,21,7,"如人鬻女爲婢、則弗釋之、不與僕同、"],[2,21,8,"若主納之、而不見悅、則許其贖身、旣已欺之、不可鬻於他族、"],[2,21,9,"若聘之與子、則當視之如女、"],[2,21,10,"若別有所娶、則其衣食之資、好合之誼、不可闕如、"],[2,21,11,"若不行此三者、則容其自去、毋索贖金、○"],[2,21,12,"擊人死者、殺無赦、"],[2,21,13,"若非謀殺、乃上帝付於其手、我必爲之定可避之區、"],[2,21,14,"若擅攻其鄰、以詭計殺之、雖逃於我壇、亦執而殺之、○"],[2,21,15,"擊父母者、殺無赦、○"],[2,21,16,"虜人而鬻之、或留於其手者、殺無赦、○"],[2,21,17,"詛父母者、殺無赦、○"],[2,21,18,"如人相爭、或擊以石以拳、傷不至死、惟臥於牀、"],[2,21,19,"後起扶杖而出、則擊之者免刑、惟償其失時之值、醫之使愈、○"],[2,21,20,"以杖擊僕婢、而斃杖下者、必受刑、"],[2,21,21,"若一二日不死、則不受刑、蓋以金購之也、○"],[2,21,22,"如人相鬬、傷姙婦墮胎、而無他害、則當罰金、依其夫所定、折中於士師、"],[2,21,23,"若有他害、則當以命償命、"],[2,21,24,"目償目、齒償齒、手償手、足償足、"],[2,21,25,"烙償烙、傷償傷、擊償擊、○"],[2,21,26,"如人擊毀僕婢之一目、必緣其目而釋之、"],[2,21,27,"擊折僕婢之一齒、必緣其齒而釋之、○"],[2,21,28,"牛觸男女致死、必以石擊斃之、勿食其肉、牛主無罪、"],[2,21,29,"若牛素觸人、或以告牛主、而不之禁、至殺男女、則以石斃牛、而致牛主於死、"],[2,21,30,"若擬罰金以償、必如所擬而納、以贖厥命、"],[2,21,31,"若觸人子女、亦循此例、"],[2,21,32,"若觸人僕婢、則以金三十給其主、而以石斃牛、○"],[2,21,33,"如人啟井、或掘井而不蓋、致牛驢陷於中、"],[2,21,34,"則捐金以償其主、死畜歸己、○"],[2,21,35,"牛觸他人之牛致死、則鬻生牛、以分其金、死牛分其肉、"],[2,21,36,"若知其牛素觸人、而主不禁、則以牛償牛、死者歸己、"],[2,22,1,"如人盜牛羊、或宰或鬻、當以五牛償一牛、四羊償一羊、"],[2,22,2,"遇盜穿窬、擊斃之、不抵罪、"],[2,22,3,"若日已出、斃之則抵罪、盜須償所竊、設無所有、則鬻其身以償、"],[2,22,4,"倘其所竊牛羊或驢、尚生存於盜手、則償之維倍、○"],[2,22,5,"如放畜牧於人之田、或葡萄園、則以己田己園之佳者償之、○"],[2,22,6,"如火燃棘、延燒露積、或禾稼、或田園、則舉火者必償之、○"],[2,22,7,"如以金或什物、託鄰守之、被盜所竊、盜者見獲、償之維倍、"],[2,22,8,"若盜弗獲、則家主必詣上帝前、擬其果取人之財物否、"],[2,22,9,"凡過犯、或爲牛羊驢、或爲衣服、或爲失物、有人謂爲己有、則兩造必以其事告上帝、上帝所罪者、償之維倍、○"],[2,22,10,"如以驢、或牛羊、或他畜、託鄰守之、或死傷、或被驅、別無人見、"],[2,22,11,"則二人同在、守者指耶和華而誓曰、未嘗取人之物、畜主當諾之、守者毋庸償、"],[2,22,12,"若被盜、則必償之、"],[2,22,13,"若被裂、則持以爲證、毋庸償、○"],[2,22,14,"如借人之物、或傷或死、其主不同在、則必償之、"],[2,22,15,"主同在、則不償、旣爲人僱、其值當之、○"],[2,22,16,"如誘未聘之女同寢、則必以金聘之爲室、"],[2,22,17,"若其父不欲妻之、則予以金、如聘女之數、○"],[2,22,18,"巫蠱之女、勿容其生、○"],[2,22,19,"與獸淫合者、殺無赦、○"],[2,22,20,"於耶和華外、祭他神者、必翦滅之、"],[2,22,21,"勿侮旅人而虐之、蓋爾曹在埃及、亦爲旅也、"],[2,22,22,"勿苦孤寡、"],[2,22,23,"若苦之、彼籲於我、我必聞之、"],[2,22,24,"我怒必烈、以刃誅爾、寡爾妻、孤爾子、○"],[2,22,25,"吾民貧者、與爾偕居、若貸之金、勿爲債主、而取其利、"],[2,22,26,"如取人衣爲質、日未入必反之、"],[2,22,27,"蓋彼蔽體只有此衣、無之何以安寢、我乃仁慈、彼籲於我、我必聞之、○"],[2,22,28,"毋謗上帝、毋詛民長、"],[2,22,29,"穡中之穀、醡出之酒、奉我勿遲、首生男子、必獻於我、"],[2,22,30,"牛羊亦同此例、七日偕母、越至八日、必獻於我、"],[2,22,31,"爾當爲我聖民、田野之間、爲獸所裂之畜勿食、其肉必投諸犬、"],[2,23,1,"勿播虛言、勿與惡人聯合、以爲妄證、"],[2,23,2,"勿從衆以行惡、遇訟作證、勿狥衆以反正、"],[2,23,3,"貧者有訟、勿偏袒之、○"],[2,23,4,"如遇仇之牛驢迷路、牽而歸之、"],[2,23,5,"見憾汝者之驢、伏於重負之下、勿遺棄之、必助其人解之、○"],[2,23,6,"貧者有訟、勿枉斷、"],[2,23,7,"遠諸虛僞、勿殺不辜、勿戮義人、蓋我不以惡人爲義、"],[2,23,8,"勿受賄、蓋賄使明者目盲、義者詞屈、"],[2,23,9,"勿虐旅人、蓋爾曹旅於埃及、悉彼旅情、○"],[2,23,10,"六年間、耕種田畝、斂其所產、"],[2,23,11,"越至七年、使之休息、留爲閒田、以食民之貧者、餘任野獸食之、葡萄園橄欖園亦然、"],[2,23,12,"六日間、宜操作、至七日、則安息、使爾牛驢休息、婢子賓旅、得以暢適、"],[2,23,13,"凡我所諭、宜愼守之、他神之名、毋言及、毋口誦、○"],[2,23,14,"每歲守節凡三、以奉事我、"],[2,23,15,"亞筆月爾出埃及、屆期、必守除酵節、七日食無酵餅、如我所命、覲我者毋徒手、"],[2,23,16,"於力田得其初實之季、守穫稼節、於歲暮斂厥田穀之季、守收藏節、"],[2,23,17,"爾之丁男、每歲三覲主耶和華、○"],[2,23,18,"獻我祭牲之血、勿與酵餅共獻、其脂勿留於明日、"],[2,23,19,"爾土所出之初實、必薦於爾上帝耶和華之室、烹山羊羔、勿用其母之乳、○"],[2,23,20,"我將遣使於爾前、護爾於道途、導爾至我所備之處、"],[2,23,21,"爾當愼之、聽從其命、勿干厥怒、彼不宥爾愆、蓋我名在彼、"],[2,23,22,"爾誠聽從其言、行我所諭、我則爲敵爾者之敵、爲仇爾者之仇、"],[2,23,23,"我使先爾、導爾入亞摩利人、赫人、比利洗人、迦南人、希未人、耶布斯人之地、我必翦滅其衆、"],[2,23,24,"勿拜跪其神、勿崇奉之、勿傚其所爲、當傾其神像、碎其柱像、"],[2,23,25,"宜奉事爾之上帝耶和華、則必祚爾飲食、除爾疾病、"],[2,23,26,"境內無墮胎者、無不姙者、我亦使爾終其天年、"],[2,23,27,"我在爾前、發我威烈、於爾所至、潰亂其民、使敵背爾而逃、"],[2,23,28,"必遣大蜂起於爾前、以驅希未人、迦南人、赫人、"],[2,23,29,"惟一年中、不盡逐之、免土地荒蕪、野獸孳生而害爾、"],[2,23,30,"我漸逐之、待爾昌熾、以承斯土、"],[2,23,31,"將定爾境、自紅海至非利士海、自曠野至大河、斯土之民、將付爾手、逐於爾前、"],[2,23,32,"毋與其人其神立約、"],[2,23,33,"毋容其居爾土、恐使爾獲罪於我、若奉其神、必爲爾之坎阱、"],[2,24,1,"耶和華諭摩西曰、爾與亞倫拿答亞比戶、及以色列長老七十人、其上詣我、遙立而拜、"],[2,24,2,"惟摩西可近耶和華、其餘不可、民亦勿與俱來、"],[2,24,3,"摩西以耶和華之言與律、往告於民、民同聲對曰、耶和華所言、我悉遵行、"],[2,24,4,"摩西盡錄耶和華之言、夙興、築壇山下、立柱十二、循以色列十二支派、"],[2,24,5,"遣以色列族少者獻燔祭、並以牛爲酬恩祭、獻於耶和華、"],[2,24,6,"摩西取血、半盛於盂、半灑於壇、"],[2,24,7,"宣讀約書、俾民聽聞、僉曰、耶和華所言、我悉遵行、"],[2,24,8,"摩西以血灑民曰、此血係乎盟約、卽耶和華依此詞、與爾所立者、○"],[2,24,9,"摩西與亞倫拿答亞比戶、及以色列長老七十人、咸登、"],[2,24,10,"覲以色列之上帝、在其足下、如蒼玉平鋪、如昊天清朗、"],[2,24,11,"以色列之尊者、上帝不著手加害、彼覲上帝、式飲式食、○"],[2,24,12,"耶和華諭摩西曰、登峯詣我而居、我以石版、及所書之法律誡命錫爾、俾以訓民、"],[2,24,13,"摩西與從者約書亞興、登上帝之山、"],[2,24,14,"先告諸長老曰、爾曹處此、以待我反、爾有亞倫戶珥同在、有訟者可詣之、"],[2,24,15,"摩西登山、山爲雲蔽、"],[2,24,16,"耶和華之榮光止於西乃山、雲蔽之六日、越至七日、耶和華自雲中呼摩西、"],[2,24,17,"耶和華之榮光在於山巔、以色列人觀之、狀如烈火、"],[2,24,18,"摩西入雲登山、日夜在彼、凡歷四旬、"],[2,25,1,"耶和華諭摩西曰、"],[2,25,2,"告以色列族云、當奉禮物於我、凡出於心所願者、可從而受之、"],[2,25,3,"所受禮物、卽金銀銅、"],[2,25,4,"藍紫絳三色之縷、與細枲、山羊毛、"],[2,25,5,"牡綿羊皮之染紅者、海獺皮、皂莢木、"],[2,25,6,"燃燈之油、作膏作香之芳品、"],[2,25,7,"紅玉及他寶石、以飾聖衣補服、"],[2,25,8,"當爲我構聖所、俾處民中、"],[2,25,9,"造幕與器、遵我所示之式、○"],[2,25,10,"以皂莢木作匱、長二肘有半、廣一肘有半、高一肘有半、"],[2,25,11,"內外包以精金、其上四周、飾以金緣、"],[2,25,12,"鑄金環四、置於四足、左右各二、"],[2,25,13,"以皂莢木作杠、包之以金、"],[2,25,14,"貫於匱旁之環、用以舁匱、"],[2,25,15,"杠常貫環、而弗離、"],[2,25,16,"我所賜爾之法、宜藏於匱、"],[2,25,17,"以精金作施恩座、長二肘有半、廣一肘有半、"],[2,25,18,"以金用鏇法作基路伯二、置施恩座之兩端、"],[2,25,19,"每端各一、與施恩座相連、"],[2,25,20,"基路伯高展其翮、以覆施恩座、其面向之、彼此相對、"],[2,25,21,"置施恩座於匱上、我所賜爾之法、藏於匱中、"],[2,25,22,"我將於彼臨爾、在施恩座、法匱上基路伯間、以我所命諭爾、使告以色列民、○"],[2,25,23,"以皂莢木作几、長二肘、廣一肘、高一肘有半、"],[2,25,24,"包以精金、四周飾以金緣、"],[2,25,25,"置棖四周、廣約一掌、以金緣之、"],[2,25,26,"作金環四、置於足上四隅、"],[2,25,27,"環附其棖、貫杠以舁、"],[2,25,28,"以皂莢木作杠、包之以金、俾得舁几、"],[2,25,29,"以精金作盤匙、及灌奠之壺盂、"],[2,25,30,"几上恆置陳設餅、在於我前、○"],[2,25,31,"以精金用鏇法作燈臺、其座、其梃、其盞、其節、其花、悉連爲一、"],[2,25,32,"其梃出枝凡六、兩旁各三、"],[2,25,33,"枝各有盞、狀似杏蕊、有節有花、燈之六枝皆然、"],[2,25,34,"梃亦有盞凡四、狀似杏蕊、有節有花、"],[2,25,35,"梃所出之六枝、每二枝下、各有一節、六枝皆然、"],[2,25,36,"其節其枝、俱連爲一、以精金用鏇法爲之、"],[2,25,37,"燈盌凡七、置於其上、使光對耀、"],[2,25,38,"其剪與盤、造以精金、"],[2,25,39,"製燈臺與諸器、用精金一他連得、"],[2,25,40,"爾其愼而爲之、必循在山所示爾之式焉、"],[2,26,1,"作幕用幔凡十、以撚綫細枲布、與藍紫絳三色之縷爲之、上繡良工所製之基路伯、"],[2,26,2,"每幔長二十八肘、廣四肘、諸幔長短同、"],[2,26,3,"幔相連各五、"],[2,26,4,"幔邊之聯絡處、作藍襻、次幔亦然、"],[2,26,5,"幅邊各作襻五十、兩邊之襻相對、"],[2,26,6,"又作金鈎五十、鈎連諸幔、成爲一幕、○"],[2,26,7,"以山羊毛作幔十一、爲幕外帷、"],[2,26,8,"每幔長三十肘、廣四肘、十一幔長短同、"],[2,26,9,"五幔相聯、六幔亦相聯、其第六幔、宜重複於幕前、"],[2,26,10,"幔邊之聯絡處、作五十襻、次幔亦然、"],[2,26,11,"又作銅鈎五十、鈎連諸襻、成爲一帷、"],[2,26,12,"帷之餘半、必垂幕後、"],[2,26,13,"帷幔之餘、每旁一肘、垂幕兩旁、障其左右、"],[2,26,14,"以牡綿羊皮之染紅者爲幕幬、其上蒙以海獺皮、○"],[2,26,15,"以皂莢木作幕板、立於四周、"],[2,26,16,"板長十肘、廣一肘有半、"],[2,26,17,"二榫相接、幕之諸板皆然、"],[2,26,18,"幕之南、作板二十、"],[2,26,19,"銀座四十、板下各二、與二榫相對、"],[2,26,20,"幕之北、作板二十、"],[2,26,21,"銀座四十、板下各二、"],[2,26,22,"幕後西旁、作板六、"],[2,26,23,"幕後兩隅、作板二、"],[2,26,24,"自下而上、連於一環、兩隅皆然、"],[2,26,25,"厥板凡八、銀座十六、板下各二、○"],[2,26,26,"以皂莢木作楗、"],[2,26,27,"左幕板五楗、右幕板五楗、後幕板五楗、"],[2,26,28,"板之中楗、貫乎兩端、"],[2,26,29,"以金包板、作金環貫楗、包楗以金、"],[2,26,30,"立幕、必循在山示汝之式、○"],[2,26,31,"以藍紫絳三色之縷、與撚綫細枲布作㡘、上繡良工所製之基路伯、"],[2,26,32,"以皂莢木作柱四、包之以金、垂㡘其上、以金製鈎、銀座凡四、"],[2,26,33,"㡘垂鈎下、運法匱入、㡘介聖所與至聖所之間、"],[2,26,34,"施恩座置於至聖所法匱上、"],[2,26,35,"置几於㡘外幕北、置燈臺於幕南、與几相對、"],[2,26,36,"以藍紫絳三色之縷、與撚綫細枲布、繡爲外帷門㡘、"],[2,26,37,"以皂莢木作柱五、包之以金、作金鈎、鑄五銅座、以垂其㡘、"],[2,27,1,"以皂莢木作壇、其式維方、長五肘、廣五肘、高三肘、"],[2,27,2,"四隅作四角、與壇相連、俱包以銅、"],[2,27,3,"作盆以盛壇灰、及鏟盤肉鍤、火鼎諸器、悉以銅造、"],[2,27,4,"以銅作壇網、網之四隅、作銅環四、"],[2,27,5,"置網於壇之四周緣下、上及壇之半、"],[2,27,6,"以皂莢木作壇杠、包之以銅、"],[2,27,7,"貫杠於環、在壇兩旁以舁之、"],[2,27,8,"壇以板作、而虛其中、必循在山示爾之式、而製作之、○"],[2,27,9,"又立幕院、南面之帷長百肘、以撚綫細枲布爲之、"],[2,27,10,"其柱二十、銅座二十、柱鈎與環、皆以銀作、"],[2,27,11,"北面之帷長百肘、其柱二十、銅座二十、柱鈎與環、皆以銀作、"],[2,27,12,"院之西面、帷廣五十肘、其柱十、其座十、"],[2,27,13,"院之東面、廣五十肘、"],[2,27,14,"門左之帷、長十五肘、其柱三、其座三、"],[2,27,15,"門右之帷十五肘、其柱三、其座三、"],[2,27,16,"院門之㡘、以藍紫絳三色之縷、與撚綫細枲布、繡工製之、長二十肘、其柱四、其座四、"],[2,27,17,"院四周之柱、其鈎與環、俱以銀作、其座則銅、"],[2,27,18,"院長百肘、廣五十肘、帷高五肘、以撚綫細枲布爲之、其座乃銅、"],[2,27,19,"幕中所用之器與釘、及院之釘、悉以銅作、○"],[2,27,20,"宜命以色列民、取橄欖擣清油、使燈常燃、"],[2,27,21,"會幕中、法匱前之㡘外、亞倫與其子、自夕達旦、理燈於耶和華前、此爲以色列族歷世之永例、"],[2,28,1,"宜自以色列族中、引爾兄亞倫、及其子拿答、亞比戶、以利亞撒、以他瑪、進於爾前、立爲祭司、以奉事我、"],[2,28,2,"爲爾兄亞倫製聖服、以彰榮美、"],[2,28,3,"凡有慧心之人、卽我以智神所充者、爾命之爲亞倫製衣、別之爲聖、俾任祭司職、以奉事我、"],[2,28,4,"所當製之衣、乃補服、聖衣、長衣、及縱橫相間之裏衣、並冠與紳、必爲爾兄亞倫、曁其子製聖服、俾任祭司職、以奉事我、"],[2,28,5,"製以金絲、與藍紫絳三色之縷、及細枲布、○"],[2,28,6,"作聖衣、用金絲與藍紫絳三色之縷、及良工所製之撚綫細枲布、"],[2,28,7,"必有肩帶二、綴其前後、使之相連、"],[2,28,8,"其上巧製之紳、以束聖衣、與聖衣同式、相連爲一、俱以金絲、與藍紫絳三色之縷、及撚綫細枲布而作、"],[2,28,9,"將紅玉二、上鐫以色列諸子之名、"],[2,28,10,"六名在此、六名在彼、咸序以齒、"],[2,28,11,"用玉工鐫印法、鐫以色列諸子之名於二玉、嵌於金闌、"],[2,28,12,"置二玉於聖衣之肩帶、以爲以色列諸子之誌石、亞倫荷其名於兩肩、爲記於耶和華前、"],[2,28,13,"以金作闌、"],[2,28,14,"用編索法、作精金鏈二、繫於金闌、○"],[2,28,15,"作補服用以斷事、良工之製、同於聖衣、以金絲與藍紫絳三色之縷、及撚綫細枲布爲之、"],[2,28,16,"補服方而複、長廣各一布指、"],[2,28,17,"上綴寶石四行、一爲瑪瑙、淡黃玉、葱珩、"],[2,28,18,"二爲青玉、藍玉、金鋼石、"],[2,28,19,"三爲赤玉、白瑪瑙、紫玉、"],[2,28,20,"四爲水蒼玉、紅玉、碧玉、悉嵌於金闌、"],[2,28,21,"寶石之數、循以色列諸子之名、凡十有二、用鐫印法、每寶石鐫一名、以當十二支派、"],[2,28,22,"以精金作鏈、形如編索、屬於補服、"],[2,28,23,"作金環二、置於補服兩端、"],[2,28,24,"以二金編鏈、鈎於補服兩端之二環、"],[2,28,25,"其二端接於二金闌、置於聖衣肩帶之前、"],[2,28,26,"作金環二、置於補服兩邊之內、附於聖衣、"],[2,28,27,"又作金環二、置於聖衣之前、兩肩帶下、近乎連結之處、在聖衣巧製之紳上、"],[2,28,28,"以藍組貫於補服之環、接於聖衣之環、使補服貼乎聖衣巧製之紳、補服不離聖衣、"],[2,28,29,"亞倫入聖所時、必將斷事補服、所載以色列諸子之名、服之於膺、在耶和華前、永以爲誌、"],[2,28,30,"以烏陵與土明、置於補服內、亞倫覲耶和華時、服之於膺、亞倫必將以色列族斷事之具、服之於膺、在耶和華前、○"],[2,28,31,"作聖衣內之長衣、其色純藍、"],[2,28,32,"中留空隙、以穿首領、四周織緣、如甲孔然、免其綻裂、"],[2,28,33,"以藍紫絳三色之縷、製爲石榴、垂於衣下四周之緣、間繫金鈴、"],[2,28,34,"衣下四周、石榴與金鈴相間、"],[2,28,35,"亞倫任職、必衣此服、出入聖所、覲耶和華時、有聲可聞、免於死亡、○"],[2,28,36,"以精金作牌、用鐫印法、鐫字其上、曰於耶和華爲聖、"],[2,28,37,"繫以藍紃、綴於冠前、"],[2,28,38,"使亞倫戴於額、以色列人奉獻聖物、有何罪愆、亞倫任之、恆戴其牌於額、俾獻禮者、蒙耶和華悅納、"],[2,28,39,"以精枲織裏衣、縱橫相間、以細枲布爲冠、又以繡工製紳、○"],[2,28,40,"爲亞倫子製衣、與紳及冠、以彰榮美、"],[2,28,41,"衣爾兄亞倫及其子、且沐以膏、別之爲聖、俾任祭司職、以奉事我、"],[2,28,42,"以枲作袴、自腰至髀、以蔽下體、"],[2,28,43,"亞倫與子進會幕、近祭壇、供事於聖所、必服之、免其負罪而死、此於亞倫曁其後裔、永爲定例、"],[2,29,1,"別之爲聖、俾任祭司職、以奉事我、宜取牡犢一、無疵之牡綿羊二、"],[2,29,2,"無酵之餅、及和油之餅、抹油之薄餅、俱無酵、以細麥麪作之、"],[2,29,3,"盛於一筐、並犢與羊、攜之而至、"],[2,29,4,"引亞倫及其子、造會幕門、以水濯之、"],[2,29,5,"衣亞倫以衣、卽裏衣、長衣、聖衣、補服、束以巧製之紳、"],[2,29,6,"以冠冠首、上加聖冕、"],[2,29,7,"傾膏其首以膏之、"],[2,29,8,"攜其子來、衣之以衣、"],[2,29,9,"束以紳、冠以冠、別之爲聖、使亞倫與其子任祭司職、以爲永例、○"],[2,29,10,"牽犢至會幕門、使亞倫及子按手其首、"],[2,29,11,"宰於耶和華前、會幕門外、"],[2,29,12,"取犢之血、以指釁於壇角、餘血傾於壇基、"],[2,29,13,"以蓋臟之脂、及肝網、二腎與其脂、悉焚於壇、"],[2,29,14,"惟其肉皮與矢、火之營外、此爲贖罪之祭、○"],[2,29,15,"取牡綿羊之一、使亞倫及子按手其首、"],[2,29,16,"於焉宰之、以血灑於壇之四周、"],[2,29,17,"臠切其肉、洗臟及腿、與臠切者曁首、置於一處、"],[2,29,18,"以其全體焚於壇上、是爲燔祭、獻於耶和華、以爲馨香之火祭、○"],[2,29,19,"取牡綿羊之二、使亞倫及子按手其首、"],[2,29,20,"於焉宰之、以血釁於亞倫及子之右耳垂、與右手之巨擘、右足之將指、灑血於壇四周、"],[2,29,21,"取壇上之血與膏、灑於亞倫及子之身與衣、區別其身及衣爲聖、"],[2,29,22,"此羊乃爲立職之祭、故取其脂與尾、蓋臟之脂、肝網、二腎及其脂、並右腿、"],[2,29,23,"於耶和華前、無酵餅筐中、取饅一、油餅一、薄餅一、"],[2,29,24,"皆置於亞倫及子之手、搖於耶和華前、以爲搖祭、"],[2,29,25,"爾自其手接之、加於燔祭之上、焚之於壇、是爲馨香之火祭、獻於耶和華、○"],[2,29,26,"立亞倫任聖職、所用之羊、宜取其腔、搖於耶和華前、以爲搖祭、後歸於爾、"],[2,29,27,"立亞倫與子任聖職、所用之羊、必以所搖之腔、所舉之腿爲聖、"],[2,29,28,"必永歸於亞倫、及其子孫、此乃以色列人所奉之舉祭、每獻酬恩祭時、以此舉祭獻於耶和華、○"],[2,29,29,"亞倫之聖服、必遺其子孫、使衣之以受膏、而任聖職、"],[2,29,30,"其子繼爲祭司、入會幕、供職於聖所、必衣是衣、歷至七日、○"],[2,29,31,"宜取立任聖職所用之羊、烹其肉於聖所、"],[2,29,32,"亞倫與子、必於會幕門前、食羊及筐中之餅、"],[2,29,33,"所以爲之贖罪、立任聖職、區別爲聖之物、彼當食之、外人勿食、因爲聖物故也、"],[2,29,34,"如有立任聖職、所用之肉或餅、留於明晨、則勿食、必爇以火、因爲聖物故也、○"],[2,29,35,"爾必遵我所諭、施於亞倫及其子、行此立任聖職之禮、歷至七日、"],[2,29,36,"日獻牡犢一、爲贖罪之祭、並贖壇以潔之、沃之以膏、俾其爲聖、"],[2,29,37,"贖壇七日、使之成聖、其壇遂爲至聖、凡觸之者、皆爲聖焉、○"],[2,29,38,"宜日獻於壇者、卽一歲之羔二、"],[2,29,39,"晨獻其一、暮獻其一、"],[2,29,40,"晨獻羔、加細麪伊法十分之一、和擣油一欣四分之一、及酒一欣四分之一、以爲灌祭、"],[2,29,41,"暮獻羔、如晨禮、亦獻素祭灌祭、以爲耶和華馨香之火祭、"],[2,29,42,"此歷世恆獻之燔祭、行於耶和華前、在會幕門、我將臨而諭汝之所、"],[2,29,43,"我必與以色列人會於此、使幕因我榮光而爲聖、"],[2,29,44,"我將使會幕及祭壇成聖、且使亞倫與子爲聖、任祭司職、以奉事我、"],[2,29,45,"我必處以色列族中、爲其上帝、"],[2,29,46,"俾知我乃耶和華、彼之上帝、導之出埃及、欲居其中、我乃耶和華、彼之上帝也、"],[2,30,1,"以皂莢木作焚香壇、"],[2,30,2,"形製維方、長一肘、廣一肘、高二肘、其角與壇相連、"],[2,30,3,"上面與四周及角、俱以精金包之、四周施以金緣、"],[2,30,4,"緣下兩旁、作金環二、貫杠以舁、"],[2,30,5,"以皂莢木作杠、包之以金、"],[2,30,6,"置壇於法匱旁之㡘外、法版之上、施恩座前、我將臨汝之處、"],[2,30,7,"每晨理燈時、亞倫必以芳品所製之香、焚於其上、"],[2,30,8,"薄暮燃燈時、亦必焚之、是爲歷世恆焚之香、在耶和華前、"],[2,30,9,"於此壇上、毋焚他香、毋獻燔祭素祭、毋行灌祭、"],[2,30,10,"亞倫必以贖罪祭牲之血、釁於壇角、歲凡一次、歷世如此、以贖斯壇、斯壇爲至聖於耶和華前、○"],[2,30,11,"耶和華諭摩西曰、"],[2,30,12,"爾核以色列人數時、各以贖命之值、獻於耶和華、以免核數之際、遭遇災害、"],[2,30,13,"凡被核者、必依聖所權衡、以金半舍客勒、奉於耶和華、一舍客勒、卽二十季拉、"],[2,30,14,"年二十以上被核者、皆奉之、"],[2,30,15,"富無所加、貧無所減、俱以金半舍客勒、獻於耶和華、以贖其命、"],[2,30,16,"必由以色列人取此贖金、以備會幕之需、爲以色列人之誌於耶和華前、以贖其命、○"],[2,30,17,"耶和華諭摩西曰、"],[2,30,18,"以銅作浴盤、與其座、以備洗濯、置於會幕祭壇間、盛水其中、"],[2,30,19,"使亞倫與其子、在彼盥手濯足、"],[2,30,20,"每入會幕、或近祭壇供職、獻火祭於耶和華、必以水洗滌、不至殞沒、"],[2,30,21,"必盥手濯足、免於死亡、此爲亞倫及其後裔、歷世之永例、○"],[2,30,22,"耶和華諭摩西曰、"],[2,30,23,"取芬芳之上品、卽流質沒藥五百舍客勒、香肉桂一半、卽二百五十舍客勒、香菖蒲二百五十舍客勒、"],[2,30,24,"玉桂五百舍客勒、咸依聖所權衡、和橄欖油一欣、"],[2,30,25,"用調香法、製爲聖膏、"],[2,30,26,"以膏會幕及法匱、"],[2,30,27,"几與其器、燈臺與其器、並焚香壇、"],[2,30,28,"燔祭壇與其器、浴盤與其座、"],[2,30,29,"均別之爲至聖、凡觸之者、皆爲聖焉、"],[2,30,30,"亦膏亞倫及其子、使之爲聖、任祭司職、以奉事我、"],[2,30,31,"當告以色列族曰、此膏於我、歷世爲聖、"],[2,30,32,"毋傾於人身、毋循是法私製此膏、斯乃聖物、必視之爲聖、"],[2,30,33,"凡私製此膏、或以之膏外人者、必絕於民中、○"],[2,30,34,"耶和華諭摩西曰、取香品、卽蘇合香、螺弇香、楓脂香、和乳香之清者、權之相等、"],[2,30,35,"加以鹽、循調香法、製爲純潔且聖之香、"],[2,30,36,"取其少許、擣之極細、置於會幕內法匱前、我將臨汝之處、必視之爲至聖、"],[2,30,37,"如法而製之香、勿私爲之、必視之爲聖、屬於耶和華、"],[2,30,38,"凡作此香以嗅之者、必絕於民中、"],[2,31,1,"耶和華諭摩西曰、"],[2,31,2,"試觀猶大支派、戶珥孫、烏利子比撒列、我以名召之、"],[2,31,3,"充以上帝之神、使有智慧、聰明知識、以作諸工、"],[2,31,4,"思索技藝、製金銀銅之器、"],[2,31,5,"鐫玉以鑲嵌、雕木作巧工、"],[2,31,6,"又派但之支派、亞希撒抹子亞何利亞伯輔之、凡有慧心者、我更賜以聰明、俾依我所命爾者而造、"],[2,31,7,"會幕法匱、與其上施恩座、曁幕中器皿、"],[2,31,8,"几與其器、精金燈臺與其器、香壇、"],[2,31,9,"燔祭壇與其器、浴盤與其座、"],[2,31,10,"精製之衣、祭司亞倫之聖服、及其子之衣、以供祭司職、"],[2,31,11,"膏與聖所芳品之香、悉遵我所命爾者而作、○"],[2,31,12,"耶和華諭摩西曰、"],[2,31,13,"告以色列人云、必守我安息日、於爾我間、歷世爲徵、俾知我乃耶和華、使爾成聖、"],[2,31,14,"故當守安息日、以爲聖日、凡凟之者、殺無赦、操作於是日者、必絕於民中、"],[2,31,15,"六日間、宜操作、至七日、則安息、於耶和華爲聖日、安息日操作者、殺無赦、"],[2,31,16,"以色列人歷世必守安息日以休息、此爲永約、"],[2,31,17,"於我及以色列族間、永世爲徵、蓋六日間、我耶和華造天地、七日休息、而暢適焉、○"],[2,31,18,"耶和華於西乃山諭摩西畢、錫以法版二、卽上帝手書之石版、"],[2,32,1,"民見摩西遲迴於山不下、則集於亞倫前曰、爾其爲我造神像、以爲我之先導、蓋率我出埃及之摩西、不知其何所遇矣、"],[2,32,2,"亞倫曰、脫爾妻孥垂耳之金環、攜以予我、"],[2,32,3,"民卽脫之、以授亞倫、"],[2,32,4,"亞倫受之、鎔鑄刻鏤爲犢、衆曰、以色列人歟、此卽導爾出埃及之神也、"],[2,32,5,"亞倫見之、築壇其前、宣告曰、詰朝可爲耶和華之節期、"],[2,32,6,"翌日民夙興、獻燔祭與酬恩祭、坐而飲食、起而舞蹈、○"],[2,32,7,"耶和華諭摩西曰、爾其下山、爾之民、爾所導出埃及者、已自敗壞、"],[2,32,8,"我所諭之道、彼速違之、鑄犢崇拜祭祀、曰以色列人歟、此卽導爾出埃及之神也、"],[2,32,9,"又曰、我觀斯民、強項者流、"],[2,32,10,"爾且聽我、予赫斯怒、盡滅是族、使爾後裔成爲大邦、"],[2,32,11,"摩西祈其上帝耶和華曰、耶和華歟、爾以巨能大力、導爾民出埃及、今何怒之甚乎、"],[2,32,12,"胡令埃及人云、彼導之出、乃欲加害、殺之山中、滅之地上、請爾回意、息厥烈怒、不降禍於爾民、"],[2,32,13,"求憶爾僕亞伯拉罕、以撒、以色列、昔爾指己而誓、必昌厥後、如天星之多、錫以所言之地、俾其永居、"],[2,32,14,"耶和華乃回意、不降禍於其民、○"],[2,32,15,"摩西退而下山、手持法版二、兩面各有文字、"],[2,32,16,"其版乃上帝所作、其文亦上帝所書、刻之於版、"],[2,32,17,"約書亞聞民喧譁、謂摩西曰、營中有戰聲、"],[2,32,18,"曰、非戰勝之聲、亦非戰敗之聲、我所聞者、乃謳歌之聲也、"],[2,32,19,"摩西近營見犢、及民舞蹈、怒甚、擲版、碎於山下、"],[2,32,20,"取所造之犢、爇以火、擣爲粉、播於水、令以色列人飲之、"],[2,32,21,"謂亞倫曰、斯民於爾何爲、使陷重罪、"],[2,32,22,"亞倫曰、我主勿怒、斯民決志作惡、爾所知也、"],[2,32,23,"彼謂我曰、爾其爲我造神像、以爲我之先導、蓋率我出埃及之摩西、不知其何所遇矣、"],[2,32,24,"我曰、凡有金者、脫而予我、我投之火、此犢出焉、"],[2,32,25,"摩西見民放恣、爲亞倫所縱、貽笑於敵、"],[2,32,26,"乃立營門曰、凡從耶和華者、可詣我、利未族咸集詣之、"],[2,32,27,"摩西曰、以色列之上帝耶和華云、各宜繫刃於腰、往來營中、自此門至彼門、殺其昆弟、友朋鄰里、"],[2,32,28,"利未人從其言、是日民中殞者、約三千人、"],[2,32,29,"摩西曾曰、今日爾當自潔、歸耶和華爲聖、各擊子女昆弟、致蒙錫嘏於爾、○"],[2,32,30,"翌日、摩西告民曰、汝干重罪、我今上詣耶和華、爾罪庶幾可贖、"],[2,32,31,"乃返耶和華所、曰、噫、斯民干重罪、以金造神像、"],[2,32,32,"今爾若宥其罪、不然、則塗我名於爾册、"],[2,32,33,"耶和華曰、孰獲罪於我、則塗其名於我册、"],[2,32,34,"爾往、率民至我所言之地、我使必爲先導、然討罪之日我必討之、"],[2,32,35,"耶和華擊民、以其使亞倫造犢也、"],[2,33,1,"耶和華諭摩西曰、昔我誓於亞伯拉罕、以撒、雅各、許錫其裔之地、今爾與所導出埃及之民、啟行往彼、"],[2,33,2,"我遣使於爾前、驅迦南人、亞摩利人、赫人、比利洗人、希未人、耶布斯人、"],[2,33,3,"導爾至流乳與蜜之地、我不與之偕往、因爾衆強項、恐我滅之於途間、"],[2,33,4,"民聞此凶言、爲之哀悼、無佩文飾、"],[2,33,5,"耶和華諭摩西曰、告以色列族云、爾乃強項之民、我若俄頃之間臨於爾中、必行翦滅、爾且去其文飾、我思何以待爾、"],[2,33,6,"以色列族去其文飾、自離何烈山後、不復佩之、○"],[2,33,7,"摩西以幕張於營外、距營稍遠、稱曰會幕、凡求耶和華者、出營詣幕、"],[2,33,8,"摩西每出詣幕、民起、立於己之幕門、瞻望摩西、迨其入幕、"],[2,33,9,"入時、雲柱下止幕門、耶和華與摩西言、"],[2,33,10,"民見雲柱止於幕門、咸起、崇拜於己之幕門、"],[2,33,11,"耶和華與摩西覿面相語、如人與友言、摩西歸營、惟嫩之子少者約書亞、爲其侍從、弗離於幕、○"],[2,33,12,"摩西謂耶和華曰、爾命我導斯民、未嘗示我遣誰偕往、惟爾曾曰、我以爾名識爾、爾沾恩於我前、"],[2,33,13,"如沾爾恩、請以爾道示我、使我識爾、果沾恩於爾前、是族乃爾之民、請垂念焉、"],[2,33,14,"曰、我躬自偕往、俾爾獲安、"],[2,33,15,"曰、若弗躬自偕往、毋導我離此、"],[2,33,16,"我與爾民沾恩、於何知之、非在爾與我儕偕往、使我及民、別於天下億兆乎、○"],[2,33,17,"耶和華諭摩西曰、爾所求者、我必爲之、因爾沾恩於我前、我以爾名識爾、"],[2,33,18,"曰、請顯爾榮於我、"],[2,33,19,"曰、我必顯我諸德、宣耶和華名於爾前、我所欲矜恤者矜恤之、欲憐憫者憐憫之、"],[2,33,20,"又曰、爾不可覿我面、人而覿我、不得生存、"],[2,33,21,"又曰、近我有處、爾可立於磐上、"],[2,33,22,"我之榮光過時、必藏爾於磐穴、掩爾以手、俟我過焉、"],[2,33,23,"後則移手、使觀我背、惟不得瞻我面、"],[2,34,1,"耶和華諭摩西曰、爾琢石版二、其式如前所碎者、我以前版之文、書於其上、"],[2,34,2,"爾備詰旦陟西乃山、詣我於山巔、"],[2,34,3,"勿令他人共登、遍山渺無人跡、牛羊亦不齧草於山麓、"],[2,34,4,"摩西乃琢石版如前、遵耶和華命、夙興執版登山、"],[2,34,5,"耶和華乘雲降臨、與摩西偕立、宣耶和華名、"],[2,34,6,"又過摩西前、言曰、耶和華、耶和華乃仁慈矜憫之上帝也、遲於發怒、富有恩惠、大顯誠實、"],[2,34,7,"錫恩於億兆、赦免愆尤、過失罪惡、惟當罰者、必不義之、於父之罪、加諸子孫、至三四世、"],[2,34,8,"摩西急俯首崇拜、"],[2,34,9,"曰、主歟、如沾恩於爾前、請主偕行、斯民強項、望赦我儕之罪愆、以爲爾業、"],[2,34,10,"曰、我今立約、將行異蹟於爾民前、天下萬民之中、未嘗行之、四周之居民、必見耶和華所爲、蓋我向爾所行、乃可畏也、"],[2,34,11,"我今所命、爾必守之、我將驅亞摩利人、迦南人、赫人、比利洗人、希未人、耶布斯人於爾前、"],[2,34,12,"爾其愼之、所往之地、勿與其居民立約、恐爲爾之坎阱、"],[2,34,13,"必毀其壇、碎其柱像、斫其木偶、"],[2,34,14,"勿崇奉他神、蓋耶和華乃忌邪之上帝、名爲忌邪、"],[2,34,15,"勿與居民立約、恐彼狥欲、從其神而獻祭、招爾共食祭品、"],[2,34,16,"而爾取其女妻爾子、其女狥欲從其神、使爾子亦狥欲從之、"],[2,34,17,"勿鑄神像、"],[2,34,18,"宜守除酵節、遵我所命、在亞筆月食無酵餅、歷至七日、蓋爾於是日出埃及也、"],[2,34,19,"凡初胎男子、與首生牡畜、或牛或羊、皆屬於我、"],[2,34,20,"首生之驢、必贖以羔、否則折其頸、首生之男、必悉贖之、覲我者毋徒手、"],[2,34,21,"六日間、宜操作、至七日、則安息、稼穡之時、亦當安息、"],[2,34,22,"麥初熟時、宜守七七節、歲暮宜守收藏節、"],[2,34,23,"爾之丁男、每歲三覲耶和華、以色列之上帝、"],[2,34,24,"我必驅列邦於爾前、恢廓爾境、每歲三往覲爾上帝耶和華時、無人覬覦爾地、"],[2,34,25,"獻我祭牲之血、勿與酵餅共獻、逾越節之祭品、勿留於明日、"],[2,34,26,"爾土所出之初實、必薦於爾上帝耶和華之室、烹羔勿用其母之乳、"],[2,34,27,"耶和華諭摩西曰、宜錄斯言、蓋我循其意、與爾及以色列人立約、"],[2,34,28,"摩西與耶和華同在四十晝夜、不飲不食、耶和華以約法之十誡、書於二版、○"],[2,34,29,"摩西手持二法版、下西乃山、因與耶和華言、容光激射、而不自覺、"],[2,34,30,"亞倫及以色列衆、見其容光則懼、不敢前、"],[2,34,31,"摩西召之、亞倫與會長乃返、摩西與之言、"],[2,34,32,"後以色列衆亦前、摩西以耶和華在西乃山所諭者命之、"],[2,34,33,"摩西言竟、取帕蒙面、"],[2,34,34,"每入與耶和華言、則去其帕、及出、以所命告以色列人、"],[2,34,35,"以色列人見摩西容光激射、摩西復以帕蒙面、迨入與耶和華言、則去之、"],[2,35,1,"摩西集以色列會衆曰、耶和華諭爾所當行者、今以告爾、"],[2,35,2,"六日間、宜操作、越至七日、乃爲聖日、當守爲耶和華之安息、是日操作者、殺無赦、"],[2,35,3,"爾第宅中、安息日毋舉火、○"],[2,35,4,"摩西告以色列會衆曰、耶和華諭爾云、"],[2,35,5,"宜獻禮物於耶和華、凡心願者可奉之、以爲禮物、"],[2,35,6,"卽金銀銅、藍紫絳三色之縷、與細枲、山羊毛、"],[2,35,7,"牡綿羊皮之染紅者、海獺皮、皂莢木、"],[2,35,8,"燃燈之油、作膏作香之芳品、"],[2,35,9,"紅玉及他寶石、以飾聖衣補服、"],[2,35,10,"爾中有慧心者、可來造作、遵耶和華所諭、"],[2,35,11,"會幕、外帷與幬、鈎板楗柱座、"],[2,35,12,"匱與杠、施恩座、及其前之㡘、"],[2,35,13,"几與杠、及諸器、陳設之餅、"],[2,35,14,"燈臺與器、其盞與油、"],[2,35,15,"香壇及杠、膏與香、幕門㡘、"],[2,35,16,"燔祭壇及銅網、與杠及器、浴盤與座、"],[2,35,17,"院帷及柱與座、院門㡘、"],[2,35,18,"幕釘、院帷之釘及索、"],[2,35,19,"供事聖所精製之衣、祭司亞倫之聖服、及其子之衣、以供祭司職、○"],[2,35,20,"以色列會衆乃退、"],[2,35,21,"凡衷懷受感、出於心所願者、咸攜禮物而至、奉於耶和華、以備作會幕、盡役事、製聖服、"],[2,35,22,"凡樂輸之男女、獻金於耶和華者、咸攜纓絡、耳環、指環、手釧、所有金飾而至、"],[2,35,23,"凡有藍紫絳三色之縷、細枲布、山羊毛、牡綿羊皮之染紅者、海獺皮、亦攜之至、"],[2,35,24,"凡以銀銅獻耶和華者、亦攜之至、有皂莢木、宜於造作者、亦攜之至、"],[2,35,25,"凡有慧心之婦、親紡藍紫絳三色之縷、與細枲、攜之而至、"],[2,35,26,"凡婦具有慧心、而受感者、則紡山羊毛、"],[2,35,27,"會長奉紅玉及他寶石、以飾聖衣補服、"],[2,35,28,"芳品與油、用以燃燈、作膏作香、"],[2,35,29,"以色列之男女、凡出於心所願者、咸樂獻禮物於耶和華、以備耶和華所命摩西諸工之用、○"],[2,35,30,"摩西告以色列人曰、試觀猶大支派、戶珥孫、烏利子比撒列、耶和華以名召之、"],[2,35,31,"充以上帝之神、使有智慧、聰明知識、以作諸工、"],[2,35,32,"思索技藝、製金銀銅之器、"],[2,35,33,"鐫玉以鑲嵌、雕木作巧工、"],[2,35,34,"又感其心、與但之支派、亞希撒抹子亞何利亞伯之心、俾能誨人、"],[2,35,35,"且以慧心充之、使作諸工、卽雕工、巧工、藍紫絳三色之縷、與細枲之繡工、及織工、精於製造、思索技藝、"],[2,36,1,"比撒列與亞何利亞伯、及諸具有慧心之人、卽耶和華賦以智慧聰明、使知成作聖所諸工者、必循耶和華所命而爲、○"],[2,36,2,"摩西召比撒列與亞何利亞伯、及諸具有慧心之人、卽耶和華賦以聰明、衷懷受感、而來造作者、"],[2,36,3,"以色列人所攜禮物、爲作聖所而獻者、悉由摩西受之、民又每晨奉以樂獻之禮物、"],[2,36,4,"作聖所諸工之有智者、各停其工、"],[2,36,5,"就摩西曰、民之所奉、備耶和華所命之工之用、綽有餘裕、"],[2,36,6,"摩西傳命、使宣於營曰、男女毋再造作、以獻聖所、民遂止、不復獻、"],[2,36,7,"蓋所有之材、足作諸工、且有餘也、○"],[2,36,8,"其中諸有智者作幕、以撚綫細枲布、與藍紫絳三色之縷、作幔十、上繡良工所製之基路伯、"],[2,36,9,"每幔長二十八肘、廣四肘、諸幔長短維一、"],[2,36,10,"幔相連各五、"],[2,36,11,"幔邊之聯絡處、作藍襻、次幔亦然、"],[2,36,12,"幅邊各作襻五十、兩邊之襻相對、"],[2,36,13,"又作金鈎五十、鈎連諸幔、成爲一幕、○"],[2,36,14,"以山羊毛作幔十一、爲幕外帷、"],[2,36,15,"每幔長三十肘、廣四肘、十一幔長短同、"],[2,36,16,"五幔相聯、六幔亦相聯、"],[2,36,17,"幔邊之聯絡處、作五十襻、次幔亦然、"],[2,36,18,"又作銅鈎五十、聯爲一帷、"],[2,36,19,"以牡綿羊皮之染紅者爲幕幬、其上蒙以海獺皮、○"],[2,36,20,"以皂莢木作幕板、立於四周、"],[2,36,21,"板長十肘、廣一肘有半、"],[2,36,22,"二榫相接、幕之諸板皆然、"],[2,36,23,"幕之南、作板二十、"],[2,36,24,"銀座四十、板下各二、與二榫相對、"],[2,36,25,"幕之北、作板二十、"],[2,36,26,"銀座四十、板下各二、"],[2,36,27,"幕後西旁、作板六、"],[2,36,28,"幕後兩隅、作板二、"],[2,36,29,"自下而上、連於一環、兩隅皆然、"],[2,36,30,"厥板凡八、銀座十六、板下各二、○"],[2,36,31,"以皂莢木作楗、左幕板五楗、"],[2,36,32,"右幕板五楗、後幕板五楗、"],[2,36,33,"板之中楗、貫乎兩端、"],[2,36,34,"以金包板、作金環貫楗、包楗以金、○"],[2,36,35,"以藍紫絳三色之縷、與撚綫細枲布作㡘、上繡良工所製之基路伯、"],[2,36,36,"以皂莢木作柱四、包之以金、以金製鈎、銀座凡四、"],[2,36,37,"以藍紫絳三色之縷、與撚綫細枲布、繡爲外帷門㡘、"],[2,36,38,"其柱凡五、及鈎、柱頂與環、俱包以金、五座乃銅、"],[2,37,1,"比撒列以皂莢木作匱、長二肘有半、廣一肘有半、高一肘有半、"],[2,37,2,"內外包以精金、其上四周、飾以金緣、"],[2,37,3,"鑄金環四、置於四足、左右各二、"],[2,37,4,"以皂莢木作杠、包之以金、"],[2,37,5,"貫於匱旁之環、用以舁匱、○"],[2,37,6,"以精金作施恩座、長二肘有半、廣一肘有半、"],[2,37,7,"以金用鏇法作基路伯二、置於施恩座之兩旁、"],[2,37,8,"每旁各一、與施恩座相連、"],[2,37,9,"基路伯高展其翮、以覆施恩座、其面向之、彼此相對、○"],[2,37,10,"以皂莢木作几、長二肘、廣一肘、高一肘有半、"],[2,37,11,"包以精金、四周飾以金緣、"],[2,37,12,"置棖四周、廣約一掌、以金緣之、"],[2,37,13,"鑄金環四、置於足上四隅、"],[2,37,14,"環附其棖、貫杠以舁、"],[2,37,15,"以皂莢木作杠、包之以金、俾得舁几、"],[2,37,16,"以精金作几上器皿、盤匙及灌奠之盂壺、○"],[2,37,17,"以精金用鏇法作燈臺、其座、其梃、其盞、其節、其花、悉連爲一、"],[2,37,18,"其梃出枝凡六、兩旁各三、"],[2,37,19,"枝各有盞、狀似杏蕊、有節有花、燈之六枝皆然、"],[2,37,20,"梃亦有盞凡四、狀似杏蕊、有節有花、"],[2,37,21,"梃所出之六枝、每二枝下、各有一節、六枝皆然、"],[2,37,22,"其節其枝、俱連爲一、以精金用鏇法爲之、"],[2,37,23,"燈盌凡七、其剪與盤、造以精金、"],[2,37,24,"製燈臺與諸器、用精金一他連得、○"],[2,37,25,"以皂莢木作香壇、形製維方、長一肘、廣一肘、高二肘、其角與壇相連、"],[2,37,26,"上面與四周及角、俱以精金包之、四周施以金緣、"],[2,37,27,"緣下兩旁、作金環二、貫杠以舁、"],[2,37,28,"以皂莢木作杠、包之以金、"],[2,37,29,"以芳品製聖膏、與純潔之香、依調香法而爲之、"],[2,38,1,"以皂莢木作燔祭壇、其式維方、長五肘、廣五肘、高三肘、"],[2,38,2,"四隅作角、與壇相連、俱包以銅、"],[2,38,3,"作壇之器、卽盆鏟盤、肉鍤火鼎、悉以銅造、"],[2,38,4,"以銅作壇網、置於壇之四周緣下、上及壇之半、"],[2,38,5,"鑄銅環四、置於銅網四隅、用以貫杠、"],[2,38,6,"以皂莢木作杠、包之以銅、"],[2,38,7,"貫杠於環、在壇兩旁以舁之、壇以板作、而虛其中、○"],[2,38,8,"以銅作浴盤與其座、婦女從事於會幕門者、取其鑑而爲之、○"],[2,38,9,"又立幕院、南面之帷、長百肘、以撚綫細枲布爲之、"],[2,38,10,"其柱二十、銅座二十、柱鈎與環、皆以銀作、"],[2,38,11,"北面之帷、長百肘、其柱二十、銅座二十、柱鈎與環、皆以銀作、"],[2,38,12,"西面之帷、廣五十肘、其柱十、其座十、柱鈎與環、皆以銀作、"],[2,38,13,"東面之帷、廣五十肘、"],[2,38,14,"門左之帷、長十五肘、其柱三、其座三、門右亦然、"],[2,38,15,"左右之帷、各長十五肘、其柱三、其座三、"],[2,38,16,"四周院帷、悉以撚綫細枲布爲之、"],[2,38,17,"柱與座皆銅、鈎與環皆銀、柱頂以銀包之、院柱俱有銀環、"],[2,38,18,"院門之㡘、繡以藍紫絳三色之縷、與撚綫細枲布、長二十肘、高五肘、與院帷相等、"],[2,38,19,"柱座皆銅、各有其四、鈎環皆銀、柱頂以銀包之、"],[2,38,20,"幕與院四周之釘、俱以銅製、○"],[2,38,21,"凡作法幕、利未人所用之材、總目如左、乃祭司亞倫子以他瑪循摩西命所核者、"],[2,38,22,"凡耶和華所命摩西之物、猶大支派、戶珥孫、烏利子比撒列悉作之、"],[2,38,23,"但之支派、亞希撒抹子亞何利亞伯爲其輔佐、彼乃雕工、有技藝者、又以藍紫絳三色之縷、與細枲布爲刺繡、○"],[2,38,24,"所獻之金、以作聖所者、循聖所權衡、計二十九他連得、七百三十舍客勒、"],[2,38,25,"所核會衆、其銀共一百他連得、一千七百七十五舍客勒、"],[2,38,26,"凡被核者、自二十歲以上、計六十萬三千五百五十人、各獻銀一比加、卽舍客勒之半、循聖所權衡、"],[2,38,27,"用銀一百他連得、鑄聖所諸板之座、與幬柱之座、座計一百、每座一他連得、共用銀一百他連得、"],[2,38,28,"用銀一千七百七十五舍客勒、作柱鈎與環、包其柱頂、"],[2,38,29,"所獻之銅、共七十他連得、二千四百舍客勒、"],[2,38,30,"作會幕門之座、銅壇銅網、及壇之諸器、"],[2,38,31,"院四周與院門之座、會幕與院四周之釘、"],[2,39,1,"以藍紫絳三色之縷、作供事聖所精製之衣、曁亞倫之聖服、循耶和華所諭摩西之命、"],[2,39,2,"以金與藍紫絳三色之縷、及撚綫細枲布作聖衣、"],[2,39,3,"擣金成片、切之爲絲、與藍紫絳三色之縷、及精枲相間、良工之製、"],[2,39,4,"作肩帶二、綴其前後、使之相連、"],[2,39,5,"其上巧製之紳、以束聖衣、與聖衣同式、相連爲一、俱以金絲、與藍紫絳三色之縷、及撚綫細枲布而作、循耶和華所諭摩西之命、○"],[2,39,6,"琢紅玉二、嵌於金闌、用鐫印法、鐫以色列諸子之名於其上、"],[2,39,7,"置於聖衣之肩帶、以爲以色列人之誌石、循耶和華所諭摩西之命、○"],[2,39,8,"作補服、良工之製、同於聖衣、以金絲與藍紫絳三色之縷、及撚綫細枲布爲之、"],[2,39,9,"補服方而複、長廣各一布指、"],[2,39,10,"上綴寶石四行、一爲瑪瑙、淡黃玉、葱珩、"],[2,39,11,"二爲青玉、藍玉、金鋼石、"],[2,39,12,"三爲赤玉、白瑪瑙、紫玉、"],[2,39,13,"四爲水蒼玉、紅玉、碧玉、悉嵌於金闌、"],[2,39,14,"寶石之數、循以色列諸子之名、凡十有二、用鐫印法、每寶石鐫一名、以當十二支派、"],[2,39,15,"以精金作鏈、形如編索、屬於補服、"],[2,39,16,"作金闌二、及金環二、置金環於補服兩端、"],[2,39,17,"以二金編鏈、鈎於補服兩端之二環、"],[2,39,18,"其二端接於二金闌、置於聖衣肩帶之前、"],[2,39,19,"作金環二、置於補服兩邊之內、附於聖衣、"],[2,39,20,"又作金環二、置於聖衣之前、兩肩帶下、近乎連結之處、在聖衣巧製之紳上、"],[2,39,21,"以藍組貫於補服之環、接於聖衣之環、使補服貼乎聖衣巧製之紳、補服不離聖衣、循耶和華所諭摩西之命、○"],[2,39,22,"作聖衣內之長衣、其色純藍、"],[2,39,23,"中留空隙、如甲孔然、四周織緣、免其綻裂、"],[2,39,24,"以藍紫絳三色之縷、製爲石榴、垂於衣下之緣、"],[2,39,25,"以精金作鈴、繫於石榴間、在衣下四周之緣、"],[2,39,26,"鈴與石榴相間、在衣下之四周、衣此服以任職、循耶和華所諭摩西之命、○"],[2,39,27,"以織成之精枲布、爲亞倫及其子作裏衣、"],[2,39,28,"以細枲布作冠、及華美頭巾、以撚綫細枲布作袴、"],[2,39,29,"以撚綫細枲布、與藍紫絳三色之縷作紳、良工之製、循耶和華所諭摩西之命、○"],[2,39,30,"以精金作牌、置於聖冕、用鐫印法、鐫字其上、曰於耶和華爲聖、"],[2,39,31,"繫以藍紃、綴於冠前、循耶和華所諭摩西之命、○"],[2,39,32,"於是會幕工竣、耶和華所諭摩西之命、以色列人悉行之、"],[2,39,33,"以幕與帷及器、攜至摩西、卽鈎板楗柱座、"],[2,39,34,"牡綿羊皮之染紅爲幬者、海獺皮之蒙幬者、蔽匱之㡘、"],[2,39,35,"法匱與其杠、施恩座、"],[2,39,36,"几與其器、陳設之餅、"],[2,39,37,"精金之燈臺、陳列之盞、及其諸器、燃燈之油、"],[2,39,38,"金壇膏香、外帷門㡘、"],[2,39,39,"銅壇銅網、其杠與器、浴盤與座、"],[2,39,40,"院帷及柱與座、院門之㡘、及索與釘、會幕所用諸器、"],[2,39,41,"供事聖所精製之衣、祭司亞倫之聖服、及其子之衣、以供祭司職、"],[2,39,42,"以色列人循耶和華所諭摩西之命、而竣諸工、"],[2,39,43,"摩西觀諸工、悉遵耶和華命而作、乃爲民祝嘏、"],[2,40,1,"耶和華諭摩西曰、"],[2,40,2,"正月朔、宜建會幕、"],[2,40,3,"以法匱置其中、垂㡘以蔽之、"],[2,40,4,"舁几入幕、陳其所有、舁燈臺入、而燃其燈、"],[2,40,5,"以金香壇置法匱前、垂㡘於幕門、"],[2,40,6,"置燔祭壇於幕門前、"],[2,40,7,"置浴盤於幕壇間、盛水其中、"],[2,40,8,"四周立帷、垂㡘於院門、"],[2,40,9,"以膏膏幕、及內所有、潔幕與器、區別爲聖、"],[2,40,10,"膏燔祭壇與諸器、區別其壇、使爲至聖、"],[2,40,11,"膏浴盤與其座、區別爲聖、"],[2,40,12,"攜亞倫及其子至會幕門、濯之以水、"],[2,40,13,"以聖服衣亞倫、沐之以膏、區別爲聖、俾任祭司職、以奉事我、"],[2,40,14,"又攜其子、以衣衣之、"],[2,40,15,"膏之如父、俾任祭司職、以奉事我、彼旣受膏、則永爲祭司、歷世弗替、"],[2,40,16,"摩西悉遵耶和華所命而行、○"],[2,40,17,"二年正月朔、幕始建、"],[2,40,18,"摩西建幕、置座豎板、貫楗立柱、"],[2,40,19,"張帷於幕上、覆之以幬、循耶和華所諭摩西之命、"],[2,40,20,"以法版置之匱中、貫杠於旁、置施恩座於上、"],[2,40,21,"舁匱入幕、垂㡘以蔽之、循耶和華所諭摩西之命、"],[2,40,22,"幕中㡘外、北向設几、"],[2,40,23,"陳餅其上、在耶和華前、循耶和華所諭摩西之命、"],[2,40,24,"南向置燈臺、與几相對、"],[2,40,25,"燃燈於耶和華前、循耶和華所諭摩西之命、"],[2,40,26,"置金壇於幕中㡘前、"],[2,40,27,"上焚芳品之香、循耶和華所諭摩西之命、"],[2,40,28,"垂㡘於幕門、"],[2,40,29,"置燔祭壇於幕門、上獻燔祭與素祭、循耶和華所諭摩西之命、"],[2,40,30,"置浴盤於幕壇間、盛水以濯、"],[2,40,31,"摩西與亞倫及其子、盥手濯足、"],[2,40,32,"或入會幕、或近祭壇、則必洗滌、循耶和華所諭摩西之命、"],[2,40,33,"幕與壇四周施院帷、垂㡘於院門、於是摩西竣厥工、○"],[2,40,34,"時、雲覆會幕、耶和華之榮光盈其中、"],[2,40,35,"摩西不能入會幕、因雲止其上、耶和華之榮光充之也、"],[2,40,36,"雲由會幕上升、以色列人啟行前往、"],[2,40,37,"雲不升、則不行、以待雲升、"],[2,40,38,"晝則耶和華之雲在幕上、夜則雲中有火光、以色列人於其所行之途、悉目擊焉、"],[3,1,1,"耶和華從會幕呼摩西、諭之曰、"],[3,1,2,"告以色列族云、爾中有人獻祭於耶和華、必獻牲畜、牛羊是也、"],[3,1,3,"如獻牛爲燔祭、當取牡者、純全無疵、獻於會幕門、冀蒙悅納於耶和華、"],[3,1,4,"按手燔牲之首、則蒙悅納、俾罪得贖、"],[3,1,5,"宰牛於耶和華前、亞倫子孫爲祭司者、必奉其血、沃於會幕門前壇之四周、"],[3,1,6,"剝取燔牲之皮、臠切其肉、"],[3,1,7,"祭司亞倫子孫、必置火於壇、陳柴其上、"],[3,1,8,"所臠切者、與首及脂、亞倫子孫爲祭司者、陳之於柴、在壇火之上、"],[3,1,9,"惟臟及腿、洗滌以水、祭司悉焚於壇、以爲燔祭、而作馨香之火祭、奉於耶和華、○"],[3,1,10,"如獻綿羊山羊爲燔祭、當取牡者、純全無疵、"],[3,1,11,"在壇之北、宰於耶和華前、亞倫子孫爲祭司者、必以其血沃於壇之四周、"],[3,1,12,"臠切其肉、幷首及脂、祭司陳之於柴、在壇火之上、"],[3,1,13,"惟臟及腿、洗滌以水、祭司悉獻之、而焚於壇、是爲燔祭、以爲馨香之火祭、奉於耶和華、○"],[3,1,14,"如獻禽爲燔祭、以奉耶和華、則獻鳲鳩、或雛鴿、"],[3,1,15,"祭司攜至壇前、扭去其首、而焚於壇、瀝血壇旁、"],[3,1,16,"必去其膆及矢、擲於壇東棄灰之處、"],[3,1,17,"裂其翼而弗盡、陳之於柴、焚之於壇、是爲燔祭、以爲馨香之火祭、奉於耶和華、"],[3,2,1,"人奉素祭於耶和華、必獻細麪、傾油其上、加以乳香、"],[3,2,2,"攜至亞倫子孫爲祭司者、取其油麪一撮、及所有之乳香、焚之於壇、以爲記誌、是爲馨香之火祭、奉於耶和華、"],[3,2,3,"素祭之餘、當歸亞倫、及其子孫、獻耶和華之火祭中、此爲至聖之品、○"],[3,2,4,"如奉爐烤之素祭、必取和油之細麪餅、或抹油之薄餅、俱無酵、"],[3,2,5,"如奉釜烤之素祭、必取和油無酵之細麪、"],[3,2,6,"分之爲塊、傾油其上、是爲素祭、"],[3,2,7,"如奉釜煎之素祭、必以細麪與油製之、"],[3,2,8,"當以所製之素祭、攜至耶和華所、奉諸祭司、祭司攜至壇前、"],[3,2,9,"於素祭中、祭司當有所取、以爲記誌、焚之於壇、是爲馨香之火祭、奉於耶和華、"],[3,2,10,"素祭之餘、當歸亞倫、及其子孫、獻耶和華之火祭中、此爲至聖之品、"],[3,2,11,"凡獻耶和華之素祭、皆弗置酵、凡酵與蜜、毋焚爲火祭、以奉耶和華、"],[3,2,12,"獻於耶和華爲初熟之品則可、惟焚於壇爲馨香、則不可、"],[3,2,13,"凡所獻之素祭、必鹽以鹽、上帝與爾立約之鹽、於爾素祭中、不可缺之、爾之諸祭、必以鹽獻、"],[3,2,14,"如獻初熟之品於耶和華、以爲素祭、必奉火烘之麥穗、旣擣之新穀、"],[3,2,15,"傾油其上、加以乳香、是爲素祭、"],[3,2,16,"祭司當由所擣之穀、與油、取其少許、及所有之乳香、焚之以爲記誌、是爲火祭、奉於耶和華、"],[3,3,1,"人獻酬恩之祭、如其用牛、或牡或牝、必純全無疵、奉於耶和華前、"],[3,3,2,"按手其首、宰於會幕門、亞倫子孫爲祭司者、必以其血沃於壇之四周、"],[3,3,3,"由酬恩之祭、獻火祭於耶和華、卽蓋臟及腸間之脂、"],[3,3,4,"腰間二腎與其脂、及肝網、宜悉取之、"],[3,3,5,"亞倫子孫陳之於柴、在燔祭之上、倂焚於壇、是爲馨香之火祭、奉於耶和華、○"],[3,3,6,"如獻羊爲酬恩之祭、或牡或牝、必純全無疵、奉於耶和華、"],[3,3,7,"或獻羔羊、必攜至耶和華前、"],[3,3,8,"按手其首、宰於會幕前、亞倫子孫、必以其血沃於壇之四周、"],[3,3,9,"由酬恩之祭、獻火祭於耶和華、卽其脂與全尾、尾必依尻而斷、及蓋臟與腸間之脂、"],[3,3,10,"腰間二腎與其脂、及肝網、宜悉取之、"],[3,3,11,"祭司焚之於壇、是爲火祭之食、奉於耶和華、○"],[3,3,12,"如獻山羊、奉於耶和華前、"],[3,3,13,"必按手其首、宰於會幕前、亞倫子孫、必以其血沃於壇之四周、"],[3,3,14,"其中當獻於耶和華之火祭、卽蓋臟及腸間之脂、"],[3,3,15,"腰間二腎與其脂、及肝網、宜悉取之、"],[3,3,16,"祭司焚之於壇、是爲馨香火祭之食、奉於耶和華、所有之脂、咸歸耶和華、"],[3,3,17,"於爾所居之處、凡脂與血、均勿食之、著爲永例、歷世勿替、"],[3,4,1,"耶和華諭摩西曰、"],[3,4,2,"告以色列族云、如有人誤干耶和華之命、爲所不當爲、"],[3,4,3,"如受膏之祭司干罪、貽害於民、則必緣其所犯之罪、取純全之牡犢、獻於耶和華、爲贖罪之祭、"],[3,4,4,"牽犢至會幕門、按手其首、宰於耶和華前、"],[3,4,5,"受膏之祭司、當取犢血入會幕、"],[3,4,6,"染指其中、在耶和華前、對聖所之㡘而灑者七、"],[3,4,7,"復取血少許、釁於會幕內耶和華前香壇之角、傾餘血於會幕門祭壇之基、"],[3,4,8,"取贖罪犢之脂、卽蓋臟及腸間之脂、"],[3,4,9,"腰間二腎與其脂、及肝網、宜悉取之、"],[3,4,10,"如獻牛爲酬恩之祭、而取其脂然、祭司焚之於壇、"],[3,4,11,"犢之皮肉首腿、與臟及矢、"],[3,4,12,"全體攜出營外、至潔清之地、棄灰之所、置於柴、爇以火、棄灰焚犢、必在一處、○"],[3,4,13,"如以色列會衆誤干耶和華之命、爲所不當爲、以取罪戾、而不自知、"],[3,4,14,"厥罪旣顯、會衆必獻牡犢、爲贖罪之祭、牽至會幕、"],[3,4,15,"會之長老、必於耶和華前、按手其首而宰之、"],[3,4,16,"受膏之祭司、當取犢血入會幕、"],[3,4,17,"染指其中、在耶和華前、對㡘而灑者七、"],[3,4,18,"復取血少許、釁於會幕內耶和華前香壇之角、傾餘血於會幕門祭壇之基、"],[3,4,19,"悉取其脂、焚之於壇、"],[3,4,20,"如獻犢爲贖罪之祭然、如是祭司爲之贖罪、乃蒙赦宥、"],[3,4,21,"攜犢營外、爇之以火、如前所焚之犢然、此會衆贖罪之祭也、○"],[3,4,22,"如民長誤干其上帝耶和華之命、爲所不當爲、以取罪戾、"],[3,4,23,"自知其過、必獻牡山羊、純全無疵、"],[3,4,24,"按手其首、宰於耶和華前、在宰燔祭犧牲之處、此贖罪之祭也、"],[3,4,25,"祭司必以指取血、釁於祭壇之角、傾餘血於壇基、"],[3,4,26,"焚脂於壇、如焚酬恩祭牲之脂然、如是祭司爲之贖罪、乃蒙赦宥、○"],[3,4,27,"如有庶民誤干耶和華之命、爲所不當爲、以取罪戾、"],[3,4,28,"自知其過、必緣所犯、獻牝山羊、純全無疵、爲贖罪之祭、"],[3,4,29,"按手其首、宰於燔祭之所、"],[3,4,30,"祭司必以指取血、釁於祭壇之角、傾餘血於壇基、"],[3,4,31,"悉取其脂、如取酬恩祭牲之脂然、祭司焚之於壇、以爲馨香、奉於耶和華、如是祭司爲之贖罪、乃蒙赦宥、○"],[3,4,32,"如獻綿羊之羔、爲贖罪之祭、必取牝者、純全無疵、"],[3,4,33,"按手其首、宰於燔祭之所、爲贖罪之祭、"],[3,4,34,"祭司必以指取血、釁於祭壇之角、傾餘血於壇基、"],[3,4,35,"悉取其脂、如取酬恩祭牲之脂然、祭司焚之於壇、在耶和華火祭之上、如是祭司爲之贖罪、乃蒙赦宥、"],[3,5,1,"如人或聞或知其事、能爲其證、旣聞召爲確證、而不以告、於是有罪、必任厥咎、"],[3,5,2,"如捫野獸六畜昆蟲不潔之尸、以致自汚、而不自知、則爲有罪、"],[3,5,3,"如捫人之不潔、而不自知、無論所汚若何、迨及知之、則爲有罪、"],[3,5,4,"如人造次發誓、行善行惡、而不自知、無論所誓何若、迨及知之、則爲有罪、"],[3,5,5,"以上數罪、若犯其一、則當自認其罪、"],[3,5,6,"因其所犯之罪、必攜牝羊、或羔羊或山羊、以爲補過贖罪之祭、獻於耶和華、祭司代爲贖罪、"],[3,5,7,"如其資財、不足備羔、則必緣其所犯之罪、攜鳲鳩二、或雛鴿二、詣耶和華前、一爲贖罪之祭、一爲燔祭、"],[3,5,8,"攜至祭司、祭司先獻其一、爲贖罪之祭、扭去其首、弗剖其體、"],[3,5,9,"取血少許、灑於壇旁、瀝餘血於壇基、是爲贖罪之祭、"],[3,5,10,"後復獻其一、以爲燔祭、循其常例、祭司代爲贖罪、乃蒙赦宥、"],[3,5,11,"如其資財、不足備鳲鳩、或雛鴿、則獻細麪伊法十分之一、爲贖罪之祭、勿置油、勿加乳香、蓋爲贖罪之祭、"],[3,5,12,"攜至祭司、祭司取其一撮、以爲記誌、焚之於壇、在耶和華火祭之上、是爲贖罪之祭、"],[3,5,13,"若犯以上數罪之一、祭司代爲贖罪、乃蒙赦宥、祭物之餘、悉歸祭司、若素祭然、○"],[3,5,14,"耶和華諭摩西曰、"],[3,5,15,"如人於獻耶和華之聖物、偶有差失、致獲罪愆、則必獻補過之祭於耶和華、卽牡綿羊之一、純全無疵、循聖所權衡、依爾所估之價、幾舍客勒、以補其過、"],[3,5,16,"於聖物之差失、必償所缺、加五分之一、攜至祭司、祭司取羊、代爲贖罪、乃蒙赦宥、○"],[3,5,17,"如人犯罪、干耶和華之命、爲所不當爲、雖出無意、亦爲有過、必任其咎、"],[3,5,18,"必以牡綿羊之一、純全無疵、依爾所估之價、攜至祭司、祭司緣其無知而犯之過、代爲贖罪、乃蒙赦宥、"],[3,5,19,"此乃補過之祭、緣其人在耶和華前、實有罪戾也、"],[3,6,1,"耶和華諭摩西曰、"],[3,6,2,"如人獲罪、干犯耶和華、於受託、貿易而欺人、或竊物、或虐鄰、"],[3,6,3,"拾人所遺、而誑言發誓、於此諸事獲罪、"],[3,6,4,"旣已獲罪有咎、必以所竊取、所虐取、所受託、所拾遺、及所誑言發誓而據之物、悉反諸人、"],[3,6,5,"於罪顯露之日、必以原物之值、加五分之一、歸於其主、"],[3,6,6,"且以牡綿羊、純全無疵、依爾所估之價、攜至祭司、獻於耶和華、爲補過之祭、"],[3,6,7,"祭司於耶和華前、代爲贖罪、其人所犯之罪、乃蒙赦宥、○"],[3,6,8,"耶和華諭摩西曰、"],[3,6,9,"命亞倫及其子云、燔祭之例如左、燔祭在壇、焚之以柴、通宵達旦、火必常燃、"],[3,6,10,"祭司衣枲衣、亦服枲褌、以蔽下體、取燔祭火燼之灰、置於壇側、"],[3,6,11,"旣而易衣、服其他服、攜灰出營、至潔清之地、"],[3,6,12,"壇火常燃不滅、每旦祭司爇柴、臚陳燔祭於上、且焚酬恩祭牲之脂、"],[3,6,13,"火於壇上、常燃不滅、○"],[3,6,14,"素祭之例如左、亞倫子孫、必攜至耶和華前、獻之於壇、"],[3,6,15,"取其細麪一撮、與油、及所有之乳香、焚之於壇、以爲記誌、而作馨香、奉於耶和華、"],[3,6,16,"素祭之餘、亞倫及其子當食之、在聖地會幕場食之、炊之毋和以酵、"],[3,6,17,"獻我之火祭中、此爲彼之所應得、是爲至聖、如贖罪補過之祭然、"],[3,6,18,"凡獻我之火祭、亞倫子孫諸丁男、得而食之、此乃永例、歷世弗替、凡捫斯祭者、必成爲聖、○"],[3,6,19,"耶和華諭摩西曰、"],[3,6,20,"亞倫受膏之日、與其子孫當獻之祭如左、細麪伊法十分之一、爲常獻之素祭、晨奉其半、暮奉其半、"],[3,6,21,"和以油、炊以釜、厥油旣浸、擘之獻爲素祭、而作馨香、奉於耶和華、"],[3,6,22,"亞倫子孫中、有代亞倫受膏爲祭司者、必獻是祭、焚之務盡、以奉耶和華、此爲永例、"],[3,6,23,"凡祭司所獻之素祭、必盡焚、毋食、○"],[3,6,24,"耶和華諭摩西曰、"],[3,6,25,"告亞倫及其子云、贖罪之祭、其例如左、於宰燔牲之處、宰贖罪之牲、在耶和華前、是乃至聖、"],[3,6,26,"爲罪獻祭之祭司可食之、當在聖地會幕場食之、"],[3,6,27,"凡捫其肉者、必成爲聖、如其血灑人衣、必澣之於聖地、"],[3,6,28,"烹肉所用瓦器、必毀之、如用銅器、必磨之、而滌以水、"],[3,6,29,"是肉至聖、惟祭司諸丁男可食、"],[3,6,30,"凡贖罪祭之牲、攜其血入會幕、以贖罪於聖所者、其肉不得食、必焚之以火、"],[3,7,1,"補過之祭、其例如左、此祭至聖、"],[3,7,2,"於宰燔牲之處、宰補過之牲、祭司必以其血沃於壇之四周、"],[3,7,3,"獻其所有之脂、其尾及蓋臟之脂、"],[3,7,4,"腰間二腎與其脂、及肝網、宜悉取之、"],[3,7,5,"祭司焚之於壇、以爲火祭、奉於耶和華、是爲補過之祭、"],[3,7,6,"此物至聖、惟祭司諸丁男可食之、在聖地食之、"],[3,7,7,"補過之祭、與贖罪之祭同、其例維一、代爲贖罪之祭司、俱必得之、"],[3,7,8,"祭司爲人獻燔祭、可得其牲之皮、"],[3,7,9,"凡素祭以爐烤、以釜炊、以鐺製者、俱歸獻之之祭司、"],[3,7,10,"凡素祭或和油與否、必歸亞倫子孫、而均分之、○"],[3,7,11,"獻耶和華酬恩之祭、其例如左、"],[3,7,12,"如因感謝而獻、則以和油無酵之餅、抹油無酵之薄餅、與浸油之細麪餅、隨同犧牲獻之、"],[3,7,13,"因感謝而獻酬恩祭、亦當同獻有酵之餅、"],[3,7,14,"由所獻之餅中、各取其一、獻於耶和華爲舉祭、歸於灑酬恩祭牲血之祭司、"],[3,7,15,"因感謝而獻之酬恩祭牲、其肉必於是日食之、勿留於明日、"],[3,7,16,"如所獻之祭、或以償願、或出樂獻、必於是日食之、其餘明日亦可食、"],[3,7,17,"祭肉之餘、留至三日、必爇以火、"],[3,7,18,"如於三日而食酬恩祭肉、則其祭不見納、於獻者亦不得爲祭、乃爲可憎之物、食之者必任其咎、"],[3,7,19,"祭肉爲穢物所觸、則不得食、必爇以火、祭肉惟清潔者可食、"],[3,7,20,"人蒙不潔、而食歸耶和華之酬恩祭肉、必絕於民中、"],[3,7,21,"如人捫不潔、或不潔之人、或不潔之獸、或不潔可憎之物、而食歸耶和華之酬恩祭肉、必絕於民中、○"],[3,7,22,"耶和華諭摩西曰、"],[3,7,23,"告以色列族云、牛與綿羊山羊、其脂均勿食、"],[3,7,24,"或自斃、或爲獸所裂之畜、其脂可供他需、惟不可食、"],[3,7,25,"獻耶和華爲火祭之牲、有食其脂者、必絕於民中、"],[3,7,26,"於爾所居之處、或禽或獸、其血均勿食、"],[3,7,27,"凡食血者、必絕於民中、"],[3,7,28,"耶和華諭摩西曰、"],[3,7,29,"告以色列族云、凡獻酬恩之祭於耶和華、必由所獻之中、取其歸耶和華者而奉之、"],[3,7,30,"手奉耶和華之火祭、卽脂與腔、搖於耶和華前、以爲搖祭、"],[3,7,31,"祭司必焚脂於壇、腔則歸亞倫、及其子孫、"],[3,7,32,"酬恩祭中、以右腿與祭司、以爲舉祭、"],[3,7,33,"亞倫子孫、獻酬恩祭牲之血與脂者、必得右腿、"],[3,7,34,"蓋以色列族所獻酬恩之祭、我取所搖之腔、所舉之腿、錫於祭司亞倫、及其子孫、著爲永例、○"],[3,7,35,"亞倫及其子、受膏立爲祭司、奉事耶和華時、"],[3,7,36,"耶和華命以色列族、於火祭中、以此賜亞倫、及其子孫、爲其所應得者、歷世弗替、"],[3,7,37,"燔祭、素祭、贖罪之祭、補過之祭、區別任職之祭、酬恩之祭、其例如此、"],[3,7,38,"乃耶和華在西乃山所諭摩西、於西乃野所命以色列族獻於耶和華者、"],[3,8,1,"耶和華諭摩西曰、"],[3,8,2,"汝攜亞倫及其子、與衣曁膏、並贖罪祭之牡犢一、牡綿羊二、無酵餅一筐、"],[3,8,3,"集會衆於會幕門、"],[3,8,4,"摩西遵耶和華命、會衆集於會幕門、"],[3,8,5,"摩西告之曰、今日所行、乃耶和華所命、"],[3,8,6,"遂攜亞倫及其子、以水濯之、"],[3,8,7,"以衣衣亞倫、束以帶、服以長衣、加以聖衣、束以良工所織之紳、"],[3,8,8,"亦予補服、置烏陵土明於其中、"],[3,8,9,"以冠冠之、冠前置金牌、卽爲聖冕、遵耶和華所諭摩西之命、"],[3,8,10,"摩西取膏釁會幕、及內所有、區別爲聖、"],[3,8,11,"以膏灑壇凡七、釁壇與器、盤及其座、區別爲聖、"],[3,8,12,"傾膏於亞倫首以膏之、區別爲聖、"],[3,8,13,"遂攜亞倫諸子進前、衣之以衣、束之以帶、冠之以冠、遵耶和華所諭摩西之命、"],[3,8,14,"摩西又牽贖罪祭之牡犢、亞倫與子按手其首、"],[3,8,15,"於焉宰之、摩西以指取血、釁於壇之四角、以潔其壇、傾餘血於壇基、爲之贖罪、區別爲聖、"],[3,8,16,"取蓋臟之脂、與肝網、左右腎及其脂、焚之於壇、"],[3,8,17,"惟犢之身、與其皮肉及矢、焚於營外、遵耶和華所諭摩西之命、"],[3,8,18,"奉爲燔祭之牡綿羊、亞倫與子按手其首、"],[3,8,19,"於焉宰之、摩西以其血沃於壇四周、"],[3,8,20,"臠切其肉、所臠切者、與首及脂、爇之以火、"],[3,8,21,"以水洗臟與腿、爇其全體於壇、是爲馨香之燔祭、奉於耶和華爲火祭、遵耶和華所諭摩西之命、"],[3,8,22,"又奉牡綿羊之一、卽爲區別任職之祭、亞倫與子按手其首、"],[3,8,23,"於焉宰之、摩西取血、釁於亞倫右耳之下垂、與右手之巨擘、右足之將指、"],[3,8,24,"又攜亞倫之子進前、以血釁其右耳之下垂、與右手之巨擘、右足之將指、沃餘血於壇四周、"],[3,8,25,"取脂及尾、蓋臟之脂、肝網、左右腎與其脂、曁右腿、"],[3,8,26,"於耶和華前無酵餅筐中、取無酵餅一、和油餅一、薄餅一、置於脂及右腿上、"],[3,8,27,"均付諸亞倫及其子之手、搖於耶和華前、以爲搖祭、"],[3,8,28,"摩西自其手接之、爇於壇、在燔祭之上、是爲任聖職之馨香、奉於耶和華之火祭、"],[3,8,29,"復取羊腔、搖於耶和華前、以爲搖祭、此於任聖職之祭羊、爲摩西所應得、遵耶和華所諭摩西之命、"],[3,8,30,"復取膏、及壇上之血、灑於亞倫及其子之身與衣、區別其身與衣爲聖、"],[3,8,31,"摩西告亞倫及其子曰、烹祭肉於會幕門、在彼食之、及區別任職筐中之餅、循我所命曰、亞倫及其子當食之、"],[3,8,32,"餘肉與餅、爇之以火、"],[3,8,33,"行區別任職之禮、共歷七日、此七日內、勿出會幕門、迨盈其日、"],[3,8,34,"今日所爲、乃耶和華所命、爲汝贖罪、"],[3,8,35,"必居會幕門、晝夜無間、歷至七日、守耶和華所命之役事、免爾死亡、我所奉之命如此、"],[3,8,36,"亞倫及其子、悉循耶和華藉摩西所命之事而行、"],[3,9,1,"屆八日、摩西召亞倫及其子、曁以色列長老、"],[3,9,2,"告亞倫曰、取牡犢一、爲贖罪之祭、牡綿羊一、爲燔祭、純全無疵、獻於耶和華、"],[3,9,3,"且命以色列人、取牡山羊一、爲贖罪之祭、取一歲之犢一、羔一、純全無疵、以爲燔祭、"],[3,9,4,"亦取牡牛一、牡綿羊一、爲酬恩之祭、獻於耶和華、又取和油之細麪、以爲素祭、蓋今日耶和華必顯見於爾、"],[3,9,5,"民攜摩西所命之品、至會幕前、會衆進而立於耶和華前、"],[3,9,6,"摩西曰、此乃耶和華所命、爾當行之、致其榮光顯著於爾、"],[3,9,7,"又告亞倫曰、當近於壇、獻汝贖罪之祭、及燔祭、爲爾及民贖罪、亦獻民之禮物、爲之贖罪、循耶和華所命、"],[3,9,8,"亞倫遂近於壇、宰爲己贖罪之犢、"],[3,9,9,"其子奉血、亞倫以指染之、釁於壇角、傾餘血於壇基、"],[3,9,10,"贖罪祭牲之脂、及左右腎、肝網、焚之於壇、遵耶和華所諭摩西之命、"],[3,9,11,"其肉與皮、焚於營外、"],[3,9,12,"旣而宰燔祭之牲、其子奉血、亞倫沃於壇四周、"],[3,9,13,"復奉燔祭臠切之肉、及首、亞倫焚之於壇、"],[3,9,14,"洗臟及腿、焚之於壇、在燔祭之上、"],[3,9,15,"亞倫奉民之祭品、取爲民贖罪之山羊、宰之以獻、爲贖罪祭、如前之獻犢然、"],[3,9,16,"奉牲爲燔祭、循例而獻、"],[3,9,17,"晨獻燔祭而外、亦奉素祭、取其一撮、焚之於壇、"],[3,9,18,"宰牡牛與牡羊、爲民作酬恩祭、其子奉血、亞倫沃於壇四周、"],[3,9,19,"取牛羊之脂、及羊尾、蓋臟之脂、左右腎與肝網、"],[3,9,20,"置脂於腔、焚脂於壇、"],[3,9,21,"腔及右腿、亞倫搖於耶和華前、以爲搖祭、循摩西所命、"],[3,9,22,"亞倫舉手祝民、獻贖罪祭、燔祭、酬恩祭旣畢、乃下、"],[3,9,23,"摩西亞倫入會幕、出而祝民、耶和華之榮光顯見、爲民目擊、"],[3,9,24,"火自耶和華前而出、焚壇上之燔祭與脂、民見之、懽呼俯伏、"],[3,10,1,"亞倫子拿答亞比戶、各取己鼎、置火與香、以獻耶和華、然所獻者、乃不聖之火、非耶和華所命、"],[3,10,2,"火自耶和華前而出、焚燬二人、死於耶和華前、"],[3,10,3,"摩西謂亞倫曰、此乃耶和華所諭云、近我者必以我爲聖、我在民前、必得其榮、亞倫默然、"],[3,10,4,"摩西召亞倫叔烏薛子米沙利以利撒反曰、爾曹來前、舁爾親屬、出聖所、至營外、"],[3,10,5,"二人乃前、舁尸營外、不解其衣、循摩西所命、"],[3,10,6,"摩西諭亞倫、及其子以利亞撒以他瑪曰、毋披爾髮、毋裂爾衣、免爾死亡、並免耶和華怒及會衆、惟爾之兄弟以色列全家、可爲耶和華所燃之火哀悼、"],[3,10,7,"爾曹毋出會幕、免爾死亡、蓋耶和華之膏在爾身、乃遵摩西之命而行、○"],[3,10,8,"耶和華諭亞倫曰、"],[3,10,9,"爾與爾子入會幕時、清酒醇醪勿飲、免爾死亡、此爲永例、歷世弗替、"],[3,10,10,"俾爾得以區別聖與不聖、潔與不潔、"],[3,10,11,"且以耶和華所諭摩西之典章、訓迪以色列族、○"],[3,10,12,"摩西諭亞倫、及其尚存之子以利亞撒以他瑪曰、獻耶和華之火祭中、素祭之餘、乃爲至聖、當食於壇旁、毋置酵、"],[3,10,13,"必在聖地食之、獻耶和華之火祭中、此爲爾及子孫所應得、我所奉之命如此、"],[3,10,14,"所搖之腔、所舉之腿、爾及子女必在潔地食之、以色列族所獻酬恩之祭、此爲爾及子孫所應得、"],[3,10,15,"人獻脂爲火祭、當與所舉之腿、所搖之腔同獻、搖於耶和華前、以爲搖祭、後則歸爾、及爾子孫得之、著爲永例、循耶和華所命、○"],[3,10,16,"贖罪之山羊、摩西索之、知已燔矣、則怒亞倫二子以利亞撒以他瑪、"],[3,10,17,"曰、贖罪之牲、旣爲至聖、曷不食之於聖所、蓋上帝賜之於爾、以任民愆、代爲贖罪於耶和華前、"],[3,10,18,"其血未入聖所、固當食牲於聖地、循我所命、"],[3,10,19,"亞倫對曰、今日彼獻贖罪祭與燔祭於耶和華前、我遭斯事、如食贖罪之牲、豈見悅於耶和華乎、"],[3,10,20,"摩西聞是言而善之、"],[3,11,1,"耶和華諭摩西亞倫曰、"],[3,11,2,"告以色列族云、地上牲畜、有可食者、"],[3,11,3,"凡畜之分蹄支趾反齧者、可食、"],[3,11,4,"惟分蹄反齧之畜中、有不可食者、若駝反齧而不分蹄、爾當以爲不潔、"],[3,11,5,"沙番反齧而不分蹄、當以爲不潔、"],[3,11,6,"野兔反齧而不分蹄、當以爲不潔、"],[3,11,7,"豕雖分蹄支趾、而不反齧、當以爲不潔、"],[3,11,8,"其肉勿食、其尸勿捫、當以爲不潔、○"],[3,11,9,"水中百族、或在海、或在河、有翅有鱗者、俱可食、"],[3,11,10,"凡在海在河、水中動物、無翅無鱗者、俱爲可憎、"],[3,11,11,"爾必視爲可憎、毋食其肉、亦視其尸爲可憎、"],[3,11,12,"凡水族無翅無鱗者、當以爲可憎、○"],[3,11,13,"羽族中所可憎、而不可食者、卽鷹、鶚、鵰、"],[3,11,14,"鸇、鷂、與其類、"],[3,11,15,"鴉與其類、"],[3,11,16,"鴕鳥、夜鷹、魚鷹、雀鷹、與其類、"],[3,11,17,"鸕鶿、魚狗、鷺鷥、"],[3,11,18,"角鴟、鵜鶘、爰居、"],[3,11,19,"白鶴、蒼鷺、戴鵀、蝙蝠與其類、○"],[3,11,20,"凡有羽翼、以四足而行者、俱爲可憎、"],[3,11,21,"惟有四足之羽蟲、有長腿能躍於地者、可食、"],[3,11,22,"卽蝗蟲、蛗蟲、蜤蟲、蟿蟲、與其類、"],[3,11,23,"其餘羽蟲、凡有四足者、當以爲可憎、○"],[3,11,24,"此類咸能汚爾、凡捫其尸、必蒙不潔、迨夕乃免、"],[3,11,25,"負其尸者、必蒙不潔、當澣其衣、迨夕乃免、"],[3,11,26,"牲畜分蹄而不支趾、又不反齧者、當以爲不潔、凡捫之者、必蒙其汚、"],[3,11,27,"四足之獸、行地用蹯者、當以爲不潔、凡捫其尸、必蒙厥汚、迨夕乃免、"],[3,11,28,"其尸不潔、負之者必蒙厥汚、當澣其衣、迨夕乃免、○"],[3,11,29,"凡物匍匐於地、當以爲不潔者、卽鼬鼠、鼫鼠、蜥蜴、與其類、"],[3,11,30,"蛤蚧、龍子、守宮、蛇醫、蝘蜓、"],[3,11,31,"凡此匍匐之物、悉爲不潔、捫其尸者、必蒙厥汚、迨夕乃免、"],[3,11,32,"凡木器、衣服、皮革、橐囊、不論所用何器、有斯物之尸墮其上、卽蒙厥汚、必置於水、迨夕乃潔、"],[3,11,33,"凡瓦器、有斯物墮其中、則所貯之物亦爲汚、其器必毀、"],[3,11,34,"器中貯有濡水之食物、必蒙厥汚、或貯有飲啜之物、亦蒙厥汚、"],[3,11,35,"無論何器、有斯物之尸墮其上、俱蒙厥汚、或爐或竈、悉必毀之、當以爲汚、"],[3,11,36,"至墮於泉、或井匯水之處、則水仍潔、惟觸其尸、必蒙厥汚、"],[3,11,37,"如其尸墮於將播之種、則仍潔、"],[3,11,38,"然種濡以水、而其尸墮於上、則不潔、○"],[3,11,39,"如可食之畜自斃、捫其尸者、必蒙厥汚、迨夕乃免、"],[3,11,40,"或食其肉、或負其尸、俱蒙厥汚、當澣其衣、迨夕乃免、○"],[3,11,41,"凡匍匐於地之物、俱爲可憎、毋食、"],[3,11,42,"凡物以腹行、或四足、或多足、匍匐於地者、俱爲可憎、毋食、"],[3,11,43,"勿緣匍匐之物、使己爲可憎、亦勿因之自汚、而爲不潔、"],[3,11,44,"蓋我乃耶和華、爾之上帝、我聖、爾亦當聖、勿緣匍匐於地之物、致汚己身、"],[3,11,45,"我乃耶和華、導爾出埃及、爲汝之上帝、我聖汝亦當聖、○"],[3,11,46,"凡走獸飛鳥、水中動物、地上匍匐之物、區別潔與不潔、可食與不可食、其例若此、"],[3,11,47,"凡走獸飛鳥、水中動物、地上匍匐之物、區別潔與不潔、可食與不可食、其例若此、"],[3,12,1,"耶和華諭摩西曰、"],[3,12,2,"告以色列族云、婦懷姙生男、必蒙不潔、歷至七日、如癸水行時之不潔然、"],[3,12,3,"八日、必爲其子行割、"],[3,12,4,"洗滌其血、三十三日乃潔、斯日未盈、不可捫聖物、不可入聖所、"],[3,12,5,"若生女子、必二七日蒙不潔、如癸水行時之不潔然、洗滌其血、六十六日乃潔、"],[3,12,6,"無論誕育男女、潔日旣盈、當攜一歲之羔爲燔祭、及鳲鳩或雛鴿之一、爲贖罪祭、至會幕門、付與祭司、"],[3,12,7,"祭司獻於耶和華、代爲贖罪、婦流血蒙不潔、如是始潔、婦生男女、其例若此、"],[3,12,8,"如其資財不足備羔、則必攜鳲鳩二、或雛鴿二、一爲燔祭、一爲贖罪祭、祭司代爲贖罪、而婦乃潔、"],[3,13,1,"耶和華諭摩西亞倫曰、"],[3,13,2,"人若膚腫、或生疥、或有斑、狀如癩疾、則必攜之詣祭司亞倫、或其子孫之一爲祭司者、"],[3,13,3,"祭司必察其膚之疾、如患處之毫變白、其狀入膚較深、則屬癩疾、祭司察之、必謂其不潔、"],[3,13,4,"如斑爲白、其狀入膚不深、其毫猶未白者、祭司必禁錮其人、歷至七日、"],[3,13,5,"屆期察之、如其疾止、不散於膚、祭司仍禁錮之、歷至七日、"],[3,13,6,"屆期必再察之、如其患處微變爲暗、不散於膚、則疥而已、祭司必謂其爲潔、其人澣衣成潔、"],[3,13,7,"祭司察後、其疾蔓延於膚、復詣祭司、"],[3,13,8,"祭司察之、見其疾果蔓延、則必謂其不潔、乃屬癩疾、○"],[3,13,9,"人有癩疾、必攜之詣祭司、"],[3,13,10,"祭司察之、如其膚腫而白、毫亦變白、肉腫而紅、"],[3,13,11,"乃膚際之舊癩、此誠汚衊、祭司必謂其不潔、毋庸禁錮其人、"],[3,13,12,"如其癩疾散布於膚、自頂至踵、無在不有、"],[3,13,13,"祭司察之、見癩蔓延全體、則謂其爲潔、蓋全體旣白、其人乃潔也、"],[3,13,14,"如肉紅腫、見於其身、則爲不潔、"],[3,13,15,"祭司驗之、必謂其不潔、紅腫之肉不潔、是乃癩疾、"],[3,13,16,"如紅腫之肉、復原而變白、則必復詣祭司、"],[3,13,17,"祭司察之、見患處變白、必謂其爲潔、其人乃爲潔、○"],[3,13,18,"如人膚際生瘡、而後得醫、"],[3,13,19,"瘡處或腫而白、或有斑斕、紅白相間、則必示於祭司、"],[3,13,20,"祭司察之、若其狀深入膚際、其毫變白、則謂其不潔、是乃癩疾、由瘡而成、"],[3,13,21,"如祭司察之、見無白毫、不深入膚、患處微變爲暗、則必禁錮其人、歷至七日、"],[3,13,22,"倘蔓延於膚、則屬癩疾、祭司必謂其不潔、"],[3,13,23,"若斑斕如前、而不蔓延、則爲瘡瘢、祭司必謂其爲潔、○"],[3,13,24,"如人之膚爲火所灼、其處起有斑爛、紅白相間、"],[3,13,25,"祭司必察之、見斑斕處、其毫變白、其狀入膚較深、則屬癩疾、由灼所致、必謂其不潔、"],[3,13,26,"如祭司察之、斑斕處無白毫、不深入膚、患處微變爲暗、則必禁錮其人、歷至七日、"],[3,13,27,"屆期察之、如蔓延於膚、則屬癩疾、必謂其不潔、"],[3,13,28,"若斑斕如前、而不蔓延、患處微變爲暗、此屬疥疾、由灼所致、第爲火灼之瘢、必謂其爲潔、○"],[3,13,29,"如男女在首在鬚有疾、"],[3,13,30,"祭司察之、若其狀入膚較深、中有細毫、其色維黃、此屬癩癬、或生於首、或生於鬚、必謂其不潔、"],[3,13,31,"如祭司察其癬、不深入膚、中無黑毫、則必禁錮其人、歷至七日、"],[3,13,32,"屆期察之、如癬不蔓延、中無黃毫、不深入膚、"],[3,13,33,"則薙鬚髮、留其癬處、禁錮其人、歷至七日、"],[3,13,34,"屆期察之、癬不蔓延、不深入膚、必謂其爲潔、其人澣衣成潔、"],[3,13,35,"成潔之後、如癬蔓延於膚、"],[3,13,36,"祭司察之、若果蔓延、則無庸求其黃毫、其人乃爲不潔、"],[3,13,37,"如癬已止、中發黑毫、其癬已愈、其人已潔、必謂其爲潔、○"],[3,13,38,"如男女膚生斑、色白而亮、"],[3,13,39,"祭司察之、若斑微暗、則屬癬疾、發生於膚、其人爲潔、○"],[3,13,40,"如髮脫落、則屬頭童、其人爲潔、"],[3,13,41,"如頂髮凋殘、則爲頇額、其人爲潔、"],[3,13,42,"若頭童頇額處發疾、紅白相間、此乃癩疾之發於頭額者、"],[3,13,43,"祭司察之、若頭童頇額處之疾、其色紅白相間、如膚生癩疾然、"],[3,13,44,"其人乃癩、而爲不潔、祭司必謂其不潔、其癩疾在首也、○"],[3,13,45,"凡患癩者、必裂衣散髮、掩口自呼曰、汚矣、汚矣、"],[3,13,46,"當其患癩時、必爲不潔、旣已不潔、必獨處、在營外、○"],[3,13,47,"若衣發霉、或毳衣、或枲衣、"],[3,13,48,"或經或緯、或織以枲、或織以毳、或皮、及革製之物、"],[3,13,49,"所染之衣皮經緯、革製之物、其色或綠或紅、此屬癩疾、必示祭司、"],[3,13,50,"祭司察之、藏所染者、歷至七日、"],[3,13,51,"屆期察之、若其斑蔓延於衣、或於經緯、或於皮、及革製之物、此屬霉毒之癩、乃爲不潔、"],[3,13,52,"則所染之衣、無論經緯毳枲、及革製之物、必俱焚之、此屬霉毒之癩、必爇以火、"],[3,13,53,"祭司察之、如其斑不復蔓延於衣、或於經緯、或於皮革、"],[3,13,54,"宜使澣濯、而復藏之、歷至七日、"],[3,13,55,"澣濯之後、必再察之、若其斑色猶未變、雖未蔓延、亦爲不潔、乃屬霉毒之癩、無論在表在裏、必爇以火、"],[3,13,56,"旣經澣濯、祭司察之、若色微暗、則必裂其衣皮經緯、而去除之、"],[3,13,57,"如仍見於衣之經緯、或於皮革、此癩復發、必爇以火、"],[3,13,58,"如衣之經緯、或皮革、旣經澣濯、去除其斑、則必再澣、使成爲潔、"],[3,13,59,"以上所載毳衣枲衣、或經或緯、及革製之物、爲癩所染、謂其爲潔爲不潔其例如此、"],[3,14,1,"耶和華諭摩西曰、"],[3,14,2,"患癩之人成潔之日、亦有其例、必攜之詣祭司、"],[3,14,3,"祭司至營外察之、見其癩疾已愈、"],[3,14,4,"則命人爲之取生禽二、惟潔是務、亦取香柏、絳縷、牛膝草、"],[3,14,5,"以瓦器盛活水、宰一禽於上、"],[3,14,6,"取彼生禽、及香柏、絳縷、牛膝草、濡於禽血之中、卽在活水上所宰者、"],[3,14,7,"以灑患癩欲潔者凡七、而謂其爲潔、乃縱生禽於野、"],[3,14,8,"欲潔之人、必澣衣薙髮、以水濯身、得以成潔、後可入營、惟居己幕之外、歷至七日、"],[3,14,9,"屆期、毫髮鬚眉、薙之務盡、澣衣濯身、而後成潔、"],[3,14,10,"越至八日、必取牡綿羊之羔二、一歲之牝羔一、純全無疵、細麪伊法十分之三、調和以油、又取油一羅革、以爲素祭、"],[3,14,11,"爲人行潔禮之祭司、必以欲潔之人及物、置於耶和華前、會幕門外、"],[3,14,12,"取一牡羔、獻爲補過之祭、又取油一羅革、俱搖於耶和華前、以爲搖祭、"],[3,14,13,"宰羔於聖地、卽宰牲爲贖罪祭爲燔祭之處、補過祭牲歸祭司、如贖罪祭牲然、是爲至聖、"],[3,14,14,"祭司必取補過祭牲之血、釁於欲潔者右耳之下垂、及右手之巨擘、右足之將指、"],[3,14,15,"祭司又取所加之油少許、傾於左掌、"],[3,14,16,"染以右指、灑於耶和華前凡七、"],[3,14,17,"以餘油少許、膏於欲潔者右耳之下垂、及右手之巨擘、右足之將指、在補過祭牲之血上、"],[3,14,18,"掌中餘油、沃於欲潔者之首、代爲贖罪於耶和華前、"],[3,14,19,"祭司乃獻贖罪之祭、代欲潔者贖罪、後宰燔祭之牲、"],[3,14,20,"與素祭同獻於壇、代爲贖罪、其人乃潔、○"],[3,14,21,"如其匱乏、不能得此、則必取牡綿羊羔一、以備搖之、爲補過祭、代爲贖罪、且以和油之細麪、伊法十分之一爲素祭、並油一羅革、"],[3,14,22,"又取鳲鳩二、或雛鴿二、隨其力所能得、一爲贖罪祭、一爲燔祭、"],[3,14,23,"越至八日、爲其成潔、必以攜至會幕門、耶和華前、付與祭司、"],[3,14,24,"祭司必取補過祭之羔、與油一羅革、搖於耶和華前、以爲搖祭、"],[3,14,25,"宰羔取血、釁於欲潔者右耳之下垂、及右手之巨擘、右足之將指、"],[3,14,26,"傾油少許於左掌、"],[3,14,27,"以右指灑於耶和華前凡七、"],[3,14,28,"取油少許、膏於欲潔者右耳之下垂、及右手之巨擘、右足之將指、在補過祭牲之血上、"],[3,14,29,"掌中餘油、沃於欲潔者之首、代爲贖罪於耶和華前、"],[3,14,30,"必獻鳲鳩一、或雛鴿一、隨其力所能得、"],[3,14,31,"一爲贖罪祭、一爲燔祭、與素祭同獻、祭司則於耶和華前、代欲潔者贖罪、"],[3,14,32,"癩者匱乏、成潔之禮不能全備者、其例若此、○"],[3,14,33,"耶和華諭摩西亞倫曰、"],[3,14,34,"我所賜爾爲業之迦南地、迨爾入之、我若使癩汚染第宅、"],[3,14,35,"其宅主必至祭司、告曰、我觀第宅、似有汚染、"],[3,14,36,"祭司未入以察、必使空其宅、免宅中所有、俱蒙不潔、嗣後祭司入宅以察、"],[3,14,37,"察時、見其汚染有紋、紅綠參錯、深入於壁、"],[3,14,38,"祭司必出宅門、扃閉七日、"],[3,14,39,"屆期察之、若其汚染蔓延於壁、"],[3,14,40,"則命取其汚染之石、擲於邑外不潔之所、"],[3,14,41,"宅中四周之壁、必加劖削、取其塗泥、傾於邑外不潔之所、"],[3,14,42,"取他石以代之、取他泥以塗之、"],[3,14,43,"去石劖壁、再塗之後、如其汚染復發於宅、"],[3,14,44,"祭司必入而察之、見汚染蔓延、此屬宅中潰爛之癩、是爲不潔、"],[3,14,45,"必毀其第宅、去其木石塗泥、遷於邑外不潔之所、"],[3,14,46,"扃閉之時、人入其宅、必蒙厥汚、迨夕乃免、"],[3,14,47,"寢食於宅者、必澣其衣、"],[3,14,48,"厥宅再塗之後、祭司入察、見汚染不蔓延、則謂其爲潔、以其汚染已除、"],[3,14,49,"使宅成潔、必取二禽、與香柏、絳縷、牛膝草、"],[3,14,50,"以瓦器盛活水、宰一禽於上、"],[3,14,51,"取香柏、牛膝草、絳縷、生禽、濡於所宰禽之血、及活水中、灑宅凡七、"],[3,14,52,"以禽血、活水、生禽、香柏、絳縷、牛膝草、使宅成潔、"],[3,14,53,"縱生禽於邑外野間、如是代爲贖罪、其宅乃潔、○"],[3,14,54,"以上所載、癩疾癬疥、"],[3,14,55,"或衣或宅之汚染、"],[3,14,56,"及紅腫瘡瘢斑斕、"],[3,14,57,"示以潔與不潔、其例若此、"],[3,15,1,"耶和華諭摩西亞倫曰、"],[3,15,2,"告以色列族云、人患白濁、是蒙不潔、"],[3,15,3,"或淋或凝、俱蒙不潔、"],[3,15,4,"所臥之牀、所坐之物、悉爲不潔、"],[3,15,5,"捫其牀者、必蒙不潔、當澣衣濯身、迨夕乃免、"],[3,15,6,"坐其座者、必蒙不潔、當澣衣濯身、迨夕乃免、"],[3,15,7,"捫其體者、必蒙不潔、當澣衣濯身、迨夕乃免、"],[3,15,8,"患白濁者、唾於潔者之身、其人則蒙不潔、當澣衣濯身、迨夕乃免、"],[3,15,9,"患者所乘之鞍、必蒙不潔、"],[3,15,10,"凡其所御之物、捫之者必蒙不潔、迨夕乃免、負之者亦蒙不潔、當澣衣濯身、迨夕乃免、"],[3,15,11,"患者不盥手而捫人、其人必蒙不潔、當澣衣濯身、迨夕乃免、"],[3,15,12,"捫瓦器必毀、捫木器必洗、"],[3,15,13,"患者成潔、必計七日、洗滌其衣、以活水濯其身、而後爲潔、"],[3,15,14,"越至八日、必取鳲鳩二、或雛鴿二、至耶和華前、會幕之門、付於祭司、"],[3,15,15,"祭司獻之、一爲贖罪祭、一爲燔祭、緣其所患之疾、爲之贖罪於耶和華前、○"],[3,15,16,"如人夢遺、則蒙不潔、必濯全體、迨夕乃免、"],[3,15,17,"或衣或皮、爲精所玷、俱蒙不潔、當澣以水、迨夕乃免、"],[3,15,18,"男女媾精、俱蒙不潔、必濯其身、迨夕乃免、○"],[3,15,19,"婦行癸流血、必蒙不潔、計至七日、凡捫之者、必蒙不潔、迨夕乃免、"],[3,15,20,"婦不潔時、所寢之牀、所坐之物、必蒙不潔、"],[3,15,21,"捫其牀者、必蒙不潔、當澣衣濯身、迨夕乃免、"],[3,15,22,"捫其座者、必蒙不潔、當澣衣濯身、迨夕乃免、"],[3,15,23,"在牀及座之物、凡捫之者、必蒙不潔、迨夕乃免、"],[3,15,24,"若與斯婦同寢、染其汚衊、必蒙不潔、歷至七日、其人所寢之牀、亦爲不潔、○"],[3,15,25,"婦行癸之前、患痭多日、或行癸之後患痭、俱蒙不潔、患痭之時、皆爲不潔、如行癸之時然、"],[3,15,26,"患痭之日、所寢之牀、所坐之物、必蒙不潔、如行癸之日然、"],[3,15,27,"凡捫斯物者、必蒙不潔、當澣衣濯身、迨夕乃免、"],[3,15,28,"厥痭旣止、必計七日、然後爲潔、"],[3,15,29,"越至八日、必取鳲鳩二、或雛鴿二、至會幕門、付於祭司、"],[3,15,30,"祭司獻之、一爲贖罪祭、一爲燔祭、緣其患痭不潔、爲之贖罪於耶和華前、"],[3,15,31,"如是區別以色列族、使離汚衊、免玷我幕、陷於死亡、○"],[3,15,32,"凡男患白濁及夢遺、致蒙厥汚、"],[3,15,33,"女患行癸之疾、或患淋之男女、或與不潔之婦同寢者、其例若此、"],[3,16,1,"亞倫二子詣耶和華前而死、"],[3,16,2,"厥後耶和華諭摩西曰、告爾兄亞倫云、聖所㡘內、法匱施恩座前、毋頻入之、免其死亡、緣我必乘雲見於施恩座上、"],[3,16,3,"亞倫欲入聖所、必奉牡犢一爲贖罪祭、牡綿羊一爲燔祭、"],[3,16,4,"衣爲聖之枲衣、著枲褌、束枲紳、冠枲冠、此乃聖服、當濯其身、而後服之、"],[3,16,5,"由以色列會衆、取牡山羊二爲贖罪祭、牡綿羊一爲燔祭、"],[3,16,6,"亞倫獻犢、爲己與其家贖罪、"],[3,16,7,"以山羊二、置於會幕門、在耶和華前、"],[3,16,8,"緣二山羊掣籤、一歸耶和華、一歸阿撒瀉勒、"],[3,16,9,"必以所掣歸耶和華之羊、獻爲贖罪祭、"],[3,16,10,"以所掣歸阿撒瀉勒之羊、生置耶和華前、用以贖罪、後釋於曠野、俾歸阿撒瀉勒、"],[3,16,11,"乃奉贖罪之犢、宰之、爲己及家贖罪、"],[3,16,12,"取耶和華壇上爇炭、盛之以鼎、又取乳香之屑一掬、攜入㡘內、"],[3,16,13,"焚香於火、在耶和華前、香篆蔽法匱上之施恩座、俾亞倫免於死亡、"],[3,16,14,"以指取血、灑於施恩座東、又灑其前凡七、"],[3,16,15,"後取爲民贖罪之山羊、宰之、攜血入㡘、灑於施恩座上、又灑其前、如灑犢血然、"],[3,16,16,"緣以色列族之不潔、及其罪愆、爲聖所贖罪、並因會幕在其汚中、爲之贖罪、"],[3,16,17,"亞倫入聖所、爲己及家、與以色列會衆贖罪時、不許人在會幕、宜待其出、"],[3,16,18,"旣出、則至耶和華前之壇、爲之贖罪、取牡犢山羊之血、釁壇四角、"],[3,16,19,"以指灑血於壇凡七、去其爲以色列族所染之汚、潔之爲聖、"],[3,16,20,"旣爲聖所會幕祭壇贖罪、當奉生羊、"],[3,16,21,"亞倫按二手於其首、承認以色列族之過犯愆尤、所有罪戾、使之悉歸羊首、俾預簡之人牽至曠野、"],[3,16,22,"羊乃負諸罪戾、縱之適野、至於荒渺之地、"],[3,16,23,"亞倫入聖所時、所服之枲衣、入會幕必解之、留於其間、"],[3,16,24,"於聖地以水濯身、衣衣而出、爲己及民獻燔祭、代爲贖罪、"],[3,16,25,"贖罪祭牲之脂、焚之於壇、"],[3,16,26,"縱羊歸阿撒瀉勒者、必澣衣濯身、而後入營、"],[3,16,27,"贖罪之牡犢及山羊、其血旣攜入聖所、以爲贖罪、其體必攜出營外、與其皮肉及矢、俱爇以火、"],[3,16,28,"爇之者當澣衣濯身、然後入營、○"],[3,16,29,"七月十日、爾之宗族、及旅於爾中者、當苦其心、免於操作、著爲永例、"],[3,16,30,"是日必爲爾贖罪、使於耶和華前去惡成潔、"],[3,16,31,"此爲安息日、當苦其心、著爲永例、"],[3,16,32,"受膏之祭司、繼父任職者、必衣枲聖服、獻祭贖罪、"],[3,16,33,"代爲聖所會幕祭壇祭司會衆贖罪、"],[3,16,34,"緣以色列族蹈於愆尤、代爲贖罪、歲凡一次、著爲永例、亞倫遵耶和華所諭摩西之命而行、"],[3,17,1,"耶和華諭摩西曰、"],[3,17,2,"告亞倫及其子、與以色列衆云、耶和華有命、"],[3,17,3,"以色列族凡宰牛羊與羔、無論營內營外、"],[3,17,4,"不攜至會幕門、獻於耶和華、在其幕前者、必以流血之罪歸之、絕於民中、"],[3,17,5,"用使以色列族宰牲於野、嗣後攜至會幕門、付諸祭司、獻於耶和華、爲酬恩之祭、"],[3,17,6,"在會幕門前、耶和華之壇、祭司必灑血其上、焚脂以爲馨香、奉於耶和華、"],[3,17,7,"勿復狥欲、祭牡山羊狀之鬼神、著爲永例、歷世弗替、○"],[3,17,8,"當告之曰、凡以色列族、及旅於其中者、或獻燔祭、或獻他祭、"],[3,17,9,"不攜至會幕門、奉於耶和華者、必絕於民中、○"],[3,17,10,"凡以色列族、及旅於其中者、苟食血、我必敵之、絕於民中、"],[3,17,11,"生物之命在血、我賜爾灑之於壇、以贖爾命、蓋以血贖罪、因生命在焉、"],[3,17,12,"故諭以色列族云、凡爾有衆、及旅於爾中者、俱毋食血、○"],[3,17,13,"凡以色列族、及旅於其中者、如獵取可食之禽獸、必傾其血、掩之以土、"],[3,17,14,"蓋諸生物、其血與命爲一、故諭以色列族云、凡生物之血毋食、因生物之命在血、食之者必見絕、"],[3,17,15,"無論宗族賓旅、食自斃、或爲獸所裂之物、必蒙不潔、當澣衣濯身、迨夕乃免、"],[3,17,16,"若不澣衣濯身、必負其罪、"],[3,18,1,"耶和華諭摩西曰、"],[3,18,2,"告以色列族云、我乃耶和華、爾之上帝、"],[3,18,3,"昔爾居埃及、勿從其土之俗、今我導爾至迦南、勿行其人之行、勿循其典章、"],[3,18,4,"爾必守我律例、循我典章、我乃耶和華、爾之上帝、"],[3,18,5,"故當循我典章、守我律例、人若行之、則緣此而得生、我乃耶和華也、○"],[3,18,6,"勿干骨肉、而行淫亂、我乃耶和華也、"],[3,18,7,"勿烝爾母、烝之是辱父母、"],[3,18,8,"父之繼室、勿烝之、烝之則辱父、"],[3,18,9,"至於姊妹、無論同父異母、同母異父、生於家、產於外者、勿亂之、"],[3,18,10,"子之女、女之女、勿亂之、亂之是辱己、"],[3,18,11,"同父異母之姊妹、亦爲爾之姊妹、勿亂之、"],[3,18,12,"父之姊妹、乃父骨肉之親、勿烝之、"],[3,18,13,"母之姊妹、乃母骨肉之親、勿烝之、"],[3,18,14,"伯叔之妻、爾之姆嬸、勿烝之、"],[3,18,15,"子之妻、爾媳也、勿亂之、"],[3,18,16,"兄弟之妻、勿亂之、亂之是辱兄弟、"],[3,18,17,"婦有女、勿同娶、婦之子有女、婦之女有女、亦勿同娶、皆妻骨肉之親、勿亂之、斯乃惡俗、"],[3,18,18,"爾妻尚存、勿娶其姊妹、辱妻而致其妒、"],[3,18,19,"婦行癸不潔時、毋與之近、而行好合、"],[3,18,20,"勿與他人之妻同寢、致辱己身、"],[3,18,21,"勿使爾子女經火、以奉摩洛、勿凟爾上帝之名、我乃耶和華也、"],[3,18,22,"勿親男色、如近婦人、斯事可憎、"],[3,18,23,"男勿淫於獸以玷身、女勿淫於獸以逆性、○"],[3,18,24,"勿緣斯事自辱厥躬、我於爾前所逐之民、行此自玷、"],[3,18,25,"厥地見汚、故我以罪加之、俾其居民爲地所吐、"],[3,18,26,"爾曹不論宗族、及旅於爾中者、當守我典章律例、毋爲此可憎之事、"],[3,18,27,"昔居斯土之人、行此可憎之事、致玷厥地、"],[3,18,28,"爾勿效之、而汚斯地、免爲所吐、如吐先爾之民然、"],[3,18,29,"凡爲此可憎之事、必絕於民中、"],[3,18,30,"爾當守我所命、勿從在昔可憎之俗、而玷爾身、我乃耶和華、爾之上帝也、"],[3,19,1,"耶和華諭摩西曰、"],[3,19,2,"告以色列會衆云、我乃耶和華、爾之上帝、我聖爾亦當聖、"],[3,19,3,"各宜敬畏父母、守我安息日、我乃耶和華、爾之上帝也、"],[3,19,4,"勿崇假神、勿鑄偶像、我乃耶和華、爾之上帝也、"],[3,19,5,"爾若獻酬恩祭於耶和華、冀蒙悅納、"],[3,19,6,"當於是日明日食其祭品、若留至三日、宜爇以火、"],[3,19,7,"如三日食之、則爲可憎、不蒙悅納、"],[3,19,8,"凡食之者、乃凟耶和華之聖物、必負厥罪、絕於民中、○"],[3,19,9,"穫田所產、勿刈其隅、勿拾所遺、"],[3,19,10,"園有葡萄、採勿務盡、勿拾隕果、當留於貧乏及賓旅、我乃耶和華、爾之上帝也、"],[3,19,11,"毋竊毋誑、毋相詐虞、"],[3,19,12,"毋指我名而妄誓、致凟爾上帝之名、我乃耶和華也、"],[3,19,13,"勿虐人、勿刦人、傭人之值、勿留至明晨、"],[3,19,14,"勿詛聾者、勿置窒礙於瞽者前、宜畏爾之上帝、我乃耶和華也、"],[3,19,15,"聽訟之際、勿行非義、勿偏袒貧乏、勿重視權勢、宜秉公以行鞫、"],[3,19,16,"勿往來於閭里、評人短長、勿與人敵、致之於死、我乃耶和華也、"],[3,19,17,"勿憾同儔、必責人非、免負其罪、"],[3,19,18,"勿報仇、勿怨宗族、宜愛人如己、我乃耶和華也、"],[3,19,19,"爾宜守我典章、牲畜異類、勿使遊牝、百穀之種、播田毋雜、勿衣雜織之衣、"],[3,19,20,"婢受人聘、猶未見贖、不得自由、人若與私、俱當受刑、惟不致死、蓋婢未能自由也、"],[3,19,21,"男必攜牡綿羊一、爲補過之祭、詣會幕門、奉於耶和華、"],[3,19,22,"祭司獻羊、代爲贖罪、則所犯者、乃蒙赦宥、"],[3,19,23,"爾至迦南、栽培結實之樹、必以初實爲不潔、如人之未受割然、三年毋食、"],[3,19,24,"至於四年、其實爲聖、可奉獻之、以頌美耶和華、"],[3,19,25,"迨至五年、其菓可食、使之結實纍然、我乃耶和華、爾之上帝也、"],[3,19,26,"毋食有血之物、毋用卜筮術數、"],[3,19,27,"首之四周勿薙、鬚之四周勿損、"],[3,19,28,"勿爲死者割肉、勿黥爾身、我乃耶和華也、"],[3,19,29,"勿辱爾女、使之爲妓、恐斯土淫亂、邪惡充乎其間、"],[3,19,30,"宜守我安息日、敬我聖所、我乃耶和華也、"],[3,19,31,"巫覡勿問、術士勿從、免致受玷、我乃耶和華、爾之上帝也、"],[3,19,32,"見皓首者當起、敬厥耆老、畏爾上帝、我乃耶和華也、"],[3,19,33,"旅於斯土者、勿侮之、"],[3,19,34,"當視若宗族、愛之如己、蓋爾曾旅於埃及、我乃耶和華、爾之上帝也、"],[3,19,35,"聽訟勿行非義、於度權量亦然、"],[3,19,36,"度量權衡、俱當公平、我乃耶和華、爾之上帝、導爾出埃及、"],[3,19,37,"當守我典章律例、而遵行之、我乃耶和華也、"],[3,20,1,"耶和華諭摩西曰、"],[3,20,2,"告以色列族云、凡以色列族、及旅於其中者、以子女獻摩洛、殺無赦、斯土之民以石擊之、"],[3,20,3,"以子女獻摩洛、乃汚我聖所、凟我聖名、我必怒之、絕於民中、"],[3,20,4,"若斯土之民、見其獻子女於摩洛、佯爲不見、不致之死、"],[3,20,5,"我必怒之、與其眷屬、及凡狥欲從摩洛者、絕之民中、"],[3,20,6,"凡狥欲從巫覡術士者、我必怒之、絕於民中、"],[3,20,7,"當自潔爲聖、我乃耶和華、爾之上帝也、"],[3,20,8,"當守我典章、而遵行之、我乃耶和華、使爾成聖也、"],[3,20,9,"詛父母者、殺無赦、旣詛父母、罪必歸之、"],[3,20,10,"淫人妻者、淫夫淫婦、俱殺無赦、"],[3,20,11,"烝父繼室、是辱父、罪必歸之、俱殺無赦、"],[3,20,12,"如亂其媳、是爲逆倫、罪必歸之、俱殺無赦、"],[3,20,13,"若親男色、如近婦人、所行可憎、罪必歸之、俱殺無赦、"],[3,20,14,"如人娶妻、並娶其母、是乃邪惡、三人俱爇以火、去邪惡於爾中、"],[3,20,15,"如人與獸淫合、必殺無赦、亦必殺獸、"],[3,20,16,"如女近合於獸、其罪歸之、必殺無赦、亦必殺獸、"],[3,20,17,"如人娶姊妹、無論同父異母、異父同母者、事屬可恥、俱必絕之民中、旣辱姊妹、必負其罪、"],[3,20,18,"如婦行癸、人與同寢、婦亦相從、則犯其經、俱絕於民中、"],[3,20,19,"勿烝父母之姊妹、因辱戚屬、俱負其罪、"],[3,20,20,"如烝伯叔之妻、是辱伯叔、俱負其罪、絕嗣而亡、"],[3,20,21,"如娶兄弟之妻、是辱兄弟、斯乃穢事、俱必絕嗣、○"],[3,20,22,"當守我典章律例、而遵行之、使我導爾所入之地、不爾吐棄、"],[3,20,23,"我於爾前所逐之族、行此惡事、我實憎之、勿從其俗、"],[3,20,24,"我曾諭爾云、爾必承斯土、卽我賜爾爲業、流乳與蜜之地、我乃耶和華、爾之上帝、區別爾於萬民、"],[3,20,25,"故當區別禽獸之潔與不潔、勿因我所區別爲汚之禽獸、匍匐於地之昆蟲、致己爲可憎、"],[3,20,26,"當歸我爲聖、蓋我耶和華乃聖、區別爾於萬民、俾爾屬我、○"],[3,20,27,"無論男女、凡爲巫覡術士者、殺無赦、其罪歸之、當擊以石、"],[3,21,1,"耶和華諭摩西曰、告亞倫子孫爲祭司者云、族中有死亡者、勿因之自汚、"],[3,21,2,"惟骨肉之親、如父母、兄弟、子女、則可、"],[3,21,3,"姊妹尚爲處女、未適人者、亦可、"],[3,21,4,"旣爲民長、則勿從俗、致汚己身、"],[3,21,5,"祭司勿髠髮、勿薙鬚之四周、勿割肉、"],[3,21,6,"旣獻火祭於耶和華、享厥上帝、故當成聖歸之、毋凟上帝之名、"],[3,21,7,"祭司爲聖、歸於上帝、故娼妓、淫女、棄婦、勿娶、"],[3,21,8,"必以祭司爲聖、因其獻食於上帝、必視之爲聖、蓋我耶和華乃聖、使爾爲聖也、"],[3,21,9,"如祭司之女行淫自玷、是辱其父、必爇以火、○"],[3,21,10,"兄弟中爲大祭司者、首沐以膏、任聖職、衣聖服、勿披髮、勿裂衣、"],[3,21,11,"勿近尸、卽父母之尸、亦勿緣之自汚、"],[3,21,12,"勿出聖所、勿汚上帝之聖所、緣上帝之膏、加於其首以爲冕、我乃耶和華也、"],[3,21,13,"必娶處女爲室、"],[3,21,14,"嫠婦、棄婦、淫女、娼妓、勿娶、惟宗族之處女、則可、"],[3,21,15,"勿使其苗裔玷於民中、蓋我乃耶和華、使之成聖也、○"],[3,21,16,"耶和華諭摩西曰、"],[3,21,17,"告亞倫云、凡爾歷世子孫、厥體有疵者、勿近其上帝而獻食、"],[3,21,18,"凡體有疵者、不得近之、如瞽、跛、凹鼻、肢體不均、"],[3,21,19,"或手足傷毀、"],[3,21,20,"或傴僂、或侏儒、或瞕翳、或疥癬、或瘡痍、或傷損外腎、"],[3,21,21,"凡祭司亞倫之裔、厥體有疵者、勿近耶和華、以獻火祭、體旣有疵、不得進前、獻食於其上帝、"],[3,21,22,"所獻上帝之食、無論聖與至聖、彼亦得而食之、"],[3,21,23,"㡘內不可入、壇前不可近、體旣有疵、恐其玷我聖所、蓋我乃耶和華、使之成聖也、"],[3,21,24,"摩西以此告亞倫及其子、並以色列衆、"],[3,22,1,"耶和華諭摩西曰、"],[3,22,2,"告亞倫及其子云、當於以色列族所獻我之聖物、自爲區別、免凟我聖名、我乃耶和華也、"],[3,22,3,"當語之曰、凡爾歷世子孫、有蒙不潔、而近以色列族所獻耶和華之聖物、必絕於我前、我乃耶和華也、"],[3,22,4,"凡亞倫子孫患癩、或白濁、不可食聖物、待潔則可、或緣尸而蒙不潔、或夢遺之人、"],[3,22,5,"或捫致汚之蟲、或捫致汚之人、"],[3,22,6,"凡若此者、爾如捫之、必蒙不潔、迨夕乃免、苟非洗濯其身、勿食聖物、"],[3,22,7,"迨日入時則潔、可食聖物、蓋此藉以養生、"],[3,22,8,"自斃或爲獸所裂之物、毋食、恐蒙不潔、我乃耶和華也、"],[3,22,9,"當守我誡命、免爲汚所玷、負罪而死、蓋我乃耶和華、使之成聖也、"],[3,22,10,"外人不得食聖物、爲旅爲傭於祭司家者、亦不得食之、"],[3,22,11,"惟祭司購以金、或生於其家者、可得而食、"],[3,22,12,"如祭司之女嫁與外人、不可食舉祭之聖物、"],[3,22,13,"如爲嫠、或爲夫所棄、無子而大歸父家、與少時無異、則父所食者、亦得食之、惟外人不可、"],[3,22,14,"如人誤食聖物、則必加五分之一、付於祭司、"],[3,22,15,"以色列族奉耶和華之聖物、不可凟之、"],[3,22,16,"免食聖物、自取罪戾、蓋我乃耶和華、使之成聖也、○"],[3,22,17,"耶和華諭摩西曰、"],[3,22,18,"告亞倫及其子、與以色列族云、凡以色列族、曁其中之賓旅、或爲償願、或出樂輸、以獻燔祭、"],[3,22,19,"冀蒙悅納、則必取牛、或綿羊、或山羊、惟牡是尚、純全無疵、"],[3,22,20,"厥體有疵者、則勿獻之、不蒙悅納、"],[3,22,21,"如獻酬恩祭於耶和華、或爲償願、或出樂輸、無論牛羊、必務純全、厥體無疵、始蒙悅納、"],[3,22,22,"凡瞽目、毀傷、損缺、瘡瘍、疥癬、創瘢、俱勿奉於耶和華、勿獻於壇以爲火祭、"],[3,22,23,"牛羊肢體不均、或有損缺、若出樂輸而獻、則可、以之償願而獻、則不蒙悅納、"],[3,22,24,"外腎或損、或傷、或破、或被閹割者、勿獻於耶和華、在爾所居之地、勿行閹割、"],[3,22,25,"外人奉此、爾勿受之、獻爲上帝之食、蓋體毀傷而有疵者、不蒙悅納、○"],[3,22,26,"耶和華諭摩西曰、"],[3,22,27,"凡犢、或綿羊山羊之羔、旣字必偕母七日、越至八日、可獻於耶和華、以爲火祭、始蒙悅納、"],[3,22,28,"牝牛牝羊、勿偕子同日以宰、"],[3,22,29,"若因感謝、獻祭於耶和華、當冀蒙悅納而獻之、"],[3,22,30,"祭肉必於是日食之、勿留於明晨、我乃耶和華也、"],[3,22,31,"當守我誡命、而遵行之、我乃耶和華也、"],[3,22,32,"勿凟我聖名、當尊我爲聖於以色列族中、我乃耶和華、使爾成聖、"],[3,22,33,"導爾出埃及、爲爾之上帝、我乃耶和華也、"],[3,23,1,"耶和華諭摩西曰、"],[3,23,2,"告以色列族云、耶和華之節期、汝當宣告爲聖會、"],[3,23,3,"六日間、宜操作、至七日、乃安息、是爲聖會、無論何工、俱勿作、在爾所居之處、必守是日爲耶和華之安息日、"],[3,23,4,"此外耶和華之節期、屆時、爾必宣告爲聖會、"],[3,23,5,"正月十四日薄暮、乃耶和華之逾越節、"],[3,23,6,"是月之望、爲除酵節、以奉事耶和華、當食無酵餅、歷至七日、"],[3,23,7,"首日有聖會、毋作苦、"],[3,23,8,"此七日間、日獻火祭於耶和華、越至七日、亦有聖會、毋作苦、○"],[3,23,9,"耶和華諭摩西曰、"],[3,23,10,"告以色列族云、爾至我所賜爾之地、穫田所產、必取初實之穀一束、奉於祭司、"],[3,23,11,"安息日之翌目、祭司以之搖於耶和華前、冀蒙悅納、"],[3,23,12,"搖穀之日、必取一歲之牡羔、純全無疵、以爲燔祭、獻於耶和華、"],[3,23,13,"和油之細麪伊法十分之二、以爲素祭、獻於耶和華、爲馨香之火祭、酒一欣四分之一、以爲灌祭、"],[3,23,14,"此日之先、未獻斯祭於耶和華、餅與烘穀新穗、毋食、在爾所居之處、著爲永例、歷世弗替、○"],[3,23,15,"自安息日之翌日、搖穀之日、必核七安息日、而盈其數、"],[3,23,16,"於安息日之翌日、計至五旬、獻素祭於耶和華、以薦其新、"],[3,23,17,"自爾居所、取細麪伊法十分之二、和以酵、製餅二、以爲初實之搖祭、獻於耶和華、"],[3,23,18,"隨餅而獻一歲之羔七、純全無疵、牡犢一、牡綿羊二、與其素祭灌祭、悉燔之、以爲馨香之火祭、奉於耶和華、"],[3,23,19,"又獻牡山羊一、爲贖罪祭、一歲之牡綿羊羔二、爲酬恩祭、"],[3,23,20,"祭司取此、與初實之麥所作之餅、以爲搖祭、搖於耶和華前、是物於耶和華爲聖、必歸祭司、"],[3,23,21,"是日必宣告有聖會、毋作苦、在爾所居之處、著爲永例、歷世弗替、"],[3,23,22,"穫田所產、勿刈其隅、勿拾所遺、當留於貧乏及賓旅、我乃耶和華、爾之上帝也、○"],[3,23,23,"耶和華諭摩西曰、"],[3,23,24,"告以色列族云、七月之朔、當守安息日、必有聖會、吹角爲記、"],[3,23,25,"是日毋作苦、必獻火祭於耶和華、○"],[3,23,26,"耶和華諭摩西曰、"],[3,23,27,"七月十日、爲贖罪之期、必守爲聖會、當苦其心、獻火祭於耶和華、"],[3,23,28,"是日乃贖罪之期、無論何工、俱勿作、而贖爾罪於爾上帝耶和華前、"],[3,23,29,"是日不自苦者、必絕之民中、"],[3,23,30,"於是日操作者、必滅之民中、"],[3,23,31,"是日無論何工、俱勿作、在爾所居之處、著爲永例、歷世弗替、"],[3,23,32,"當守是日爲肅安息日、而苦其心、是月九日薄暮、至明日薄暮、守爲安息日、○"],[3,23,33,"耶和華諭摩西曰、"],[3,23,34,"告以色列族云、七月之望、爲耶和華守構廬之節期、歷至七日、"],[3,23,35,"首日有聖會、毋作苦、"],[3,23,36,"此七日間、日獻火祭於耶和華、越至八日、亦爲聖會、必獻火祭於耶和華、斯爲肅會、毋作苦、○"],[3,23,37,"上所言者、乃耶和華之節期、必宣告爲聖會、獻火祭、燔祭、素祭、灌祭、及他祭於耶和華、各依日之所宜、"],[3,23,38,"此在耶和華之安息日、與償願樂輸、及獻耶和華他祭品之外、○"],[3,23,39,"七月之望、田疇所產、斂藏旣畢、必守耶和華之節期、歷至七日、首日爲肅安息、八日亦爲肅安息、"],[3,23,40,"首日必取佳木之菓、椶樹之條、茂樹之枝、溪旁之柳、欣喜歡忭於爾上帝耶和華前、歷至七日、"],[3,23,41,"每歲七月間、必守此節七日、以奉事耶和華、著爲永例、歷世弗替、"],[3,23,42,"凡爾宗族、必處是廬、歷至七日、"],[3,23,43,"俾爾子孫、歷世知我導其祖出埃及時、使之居廬、我乃耶和華、爾之上帝也、"],[3,23,44,"摩西以耶和華之節期、宣告以色列衆、"],[3,24,1,"耶和華諭摩西曰、"],[3,24,2,"告以色列族云、當取橄欖擣油、惟潔是務、攜以與爾、使燈常燃、"],[3,24,3,"會幕中、法匱前㡘外、亞倫必理燈於耶和華前、自夕達旦、著爲永例、歷世弗替、"],[3,24,4,"必置盞於精金燈臺之上、恆理之於耶和華前、○"],[3,24,5,"當取細麪、製餅十二、每餅伊法十分之二、"],[3,24,6,"列爲二行、行各六餅、置諸精金之几、在耶和華前、"],[3,24,7,"每行餅上、必置乳香、惟潔是務、以爲記誌、獻於耶和華爲火祭、"],[3,24,8,"每安息日、陳餅於耶和華前、以色列族守爲永約、"],[3,24,9,"斯餅悉歸亞倫、及其子孫、當於聖地食之、著爲永例、蓋獻耶和華之火祭中、此爲至聖也、○"],[3,24,10,"以色列族、但之支派、底伯利女、名示羅密、適於埃及人、所生之子、往來以色列族中、與一以色列人鬬於營、褻凟耶和華名、加以呪詛、人曳之至摩西、"],[3,24,11,"以色列族、但之支派、底伯利女、名示羅密、適於埃及人、所生之子、往來以色列族中、與一以色列人鬬於營、褻凟耶和華名、加以呪詛、人曳之至摩西、"],[3,24,12,"禁於獄、俟耶和華口諭於衆、○"],[3,24,13,"耶和華諭摩西曰、"],[3,24,14,"呪詛之人、曳出營外、使聞之者、按手其首、會衆以石擊之、"],[3,24,15,"當告以色列族云、呪詛其上帝者、必負其罪、"],[3,24,16,"褻凟耶和華名者、殺無赦、會衆必擊以石、無論宗族賓旅、褻凟耶和華名者、殺無赦、"],[3,24,17,"擊人致死者、殺無赦、"],[3,24,18,"擊人之畜致死者、必償之、以牲償牲、"],[3,24,19,"殘缺人體者、必依其所行而反之、"],[3,24,20,"傷償傷、目償目、齒償齒、若何使人殘缺、必如是反之、"],[3,24,21,"殺人之畜必償、殺人者、殺無赦、"],[3,24,22,"無論宗族賓旅、俱循一例、我乃耶和華、爾之上帝也、"],[3,24,23,"摩西命以色列人曳咒詛者出營外、擊之以石、以色列人遵耶和華諭摩西之命而行、"],[3,25,1,"耶和華於西乃山諭摩西曰、"],[3,25,2,"告以色列族云、爾旣入我所錫之地、當爲耶和華休息土壤、"],[3,25,3,"六年間、耕種田畝、治理葡萄、斂其所產、"],[3,25,4,"越至七年、土壤安息、爲耶和華肅守之、斯時田畝勿耕、葡萄勿治、"],[3,25,5,"禾稼之不殖而生者、勿穫、葡萄之不治而實者、勿摘、蓋是年其土乃休息、"],[3,25,6,"安息年之土產、爲爾及僕婢傭人賓旅所食、"],[3,25,7,"爾之六畜野獸、亦得而食之、○"],[3,25,8,"爾宜核數安息之年凡七、七七相乘、計四十九年、"],[3,25,9,"七月十日、爲贖罪之期、當使遍地吹角、大發厥聲、"],[3,25,10,"第五十年、當爲聖年、普告境內居民、此爲禧年、得以自由、人各歸其業、返其家、"],[3,25,11,"每五十年必爲禧年、田畝勿耕、禾稼之不殖而生者、勿穫、葡萄之不治而實者、勿摘、"],[3,25,12,"此乃禧年、必以爲聖、田之所產、人俱可食、"],[3,25,13,"禧年旣屆、各歸其業、"],[3,25,14,"如有所鬻於人、或有所購於人、皆勿相欺、"],[3,25,15,"或購或鬻、皆由禧年之後、核其年數、視物產之多寡而計之、"],[3,25,16,"年多增值、年寡減值、蓋所鬻者、乃物產之數也、"],[3,25,17,"故勿相欺、當畏上帝、我乃耶和華、爾之上帝也、"],[3,25,18,"宜循我典章、守我律例、而遵行之、藉以安居斯土、"],[3,25,19,"地有所產、使爾果腹、安然居處、"],[3,25,20,"若問旣至七年、不稼不穡、將何以食、"],[3,25,21,"我必於第六年、錫嘏於爾、俾收三年之實、"],[3,25,22,"八年耕種、尚食舊穀、至於九年、新穀乃登、"],[3,25,23,"田畝屬我、汝乃賓旅、不得永鬻於人、"],[3,25,24,"凡爾所有之地、許人贖之、○"],[3,25,25,"假令宗族貧乏、鬻其產業、近戚當往贖之、"],[3,25,26,"如無贖者、而己積資、足以自贖、"],[3,25,27,"則自鬻時、核其年之多寡、以其餘期所值、償之於人、而歸其業、"],[3,25,28,"如己無力以贖、則所鬻之業、存於購者、以待禧年、屆期、業歸其主、○"],[3,25,29,"如人鬻邑中之宅、則鬻後期年、有權可贖、"],[3,25,30,"如年已周不贖、則邑中之宅、永存於購者、歷世弗替、卽屆禧年、亦不歸主、"],[3,25,31,"但宅在鄉里、而無城垣、則視如田畝、可得贖之、禧年歸主、"],[3,25,32,"惟利未族之邑、卽其業中諸邑之宅、隨時可贖、"],[3,25,33,"如人贖利未族邑中之宅、屆禧年、必歸其主、蓋在以色列族中、利未人以所得邑中之宅爲業、"],[3,25,34,"利未族邑郊之田、爲其恆業、不得鬻於人、○"],[3,25,35,"如宗族中、有貧窮者、爾見其手匱乏、當濟助之、使之偕居、若旅人然、"],[3,25,36,"勿取其利、宜畏爾之上帝、使之偕居、"],[3,25,37,"貸金與粟、毋取其利、"],[3,25,38,"我乃耶和華、爾之上帝、導爾出埃及、以迦南地賜爾、爲爾上帝、○"],[3,25,39,"如宗族中、有匱乏者、自鬻於爾、勿視若奴、"],[3,25,40,"當偕爾居、如傭人旅人然、供爾役事、以待禧年、"],[3,25,41,"屆期、彼及子女去爾、而歸其家、復得其祖遺業、"],[3,25,42,"我導以色列族出埃及、彼爲我僕、不得鬻爲奴隸、"],[3,25,43,"勿治以嚴、宜畏爾之上帝、○"],[3,25,44,"異邦之民、來自四方者、可購爲僕婢、"],[3,25,45,"外人旅於爾中、及其子女生於爾地者、可購爲爾有、"],[3,25,46,"遺於子孫、恆爲爾僕、惟以色列人爲爾宗族、勿以嚴相治、○"],[3,25,47,"如爾中賓旅有豐裕者、爾之同儔窮乏、自鬻於彼、或其戚屬、"],[3,25,48,"鬻後可贖、同族亦可代贖、"],[3,25,49,"或叔伯、或叔伯之子、或近親他人、俱可贖之、如己積資、足以自贖、自贖亦可、"],[3,25,50,"彼與購者、同自鬻時、計至禧年、揆其期之遠近、酌傭人之值幾何、以償鬻金之多寡、"],[3,25,51,"年遠、付其贖值、償其鬻金宜多、"],[3,25,52,"年近、付其贖值、償其鬻金宜少、"],[3,25,53,"歲必偕居、待若傭人、勿治以嚴、"],[3,25,54,"如未得贖、禧年旣屆、彼及子女、可出而自由、"],[3,25,55,"我導以色列族出埃及、彼爲我僕、我乃耶和華、爾之上帝也、"],[3,26,1,"於爾所居之地、勿作偶像、勿立雕像、或柱像、或勒像之石、而崇拜之、我乃耶和華、爾之上帝、"],[3,26,2,"當守我安息日、敬我聖所、我乃耶和華也、○"],[3,26,3,"爾若循我典章、守我誡命、而遵行之、"],[3,26,4,"我必降以時雨、使土地產物、園樹結果、"],[3,26,5,"俾爾碾穀延及摘葡萄、摘葡萄延及播種之時、得以果腹安居、"],[3,26,6,"賜爾境內平康、可以安寢、無人恐爾、我必絕滅暴獸於斯土、刀劍不行於爾地、"],[3,26,7,"爾將追敵、以刃擊之、仆於爾前、"],[3,26,8,"爾中之人、五可驅百、百可驅萬、以刃擊敵、仆於爾前、"],[3,26,9,"我將眷顧爾、使爾繁衍昌熾、踐我與爾所立之約、"],[3,26,10,"爾食舊穀、新穀旣登、舊穀則徙、"],[3,26,11,"我將立幕於爾中、心不厭爾、"],[3,26,12,"周遊爾間、爲爾上帝、爾爲我民、"],[3,26,13,"我乃耶和華、爾之上帝、導爾出埃及、免爲其奴隸、斷爾所負之軛、俾爾昂首而行、○"],[3,26,14,"爾若不聽我言、弗遵我命、"],[3,26,15,"棄我典章、蔑我律例、違我誡命、背我盟約、"],[3,26,16,"我必加以威烈、使爾身癆體熱、以致目盲神敗、播種徒勞、爲敵所食、"],[3,26,17,"我必敵爾、使見擊於敵前、憾爾者將制爾、無人追襲、爾亦遁逃、"],[3,26,18,"爾若仍不聽從、將懲爾罪、至於七倍、"],[3,26,19,"爾恃強之驕傲、我必毀之、並使爾天若鐵、爾地若銅、"],[3,26,20,"爾徒力作、田無所產、樹不結實、"],[3,26,21,"爾尚頑梗、不欲順從、則按罪降災、至於七倍、"],[3,26,22,"使暴獸入爾境、攘爾子女、滅爾牲畜、以致戶口凋零、道途寂寞、○"],[3,26,23,"爾猶不悛、所行逆我、"],[3,26,24,"我必拂逆爾、緣爾之罪扑責爾、至於七倍、"],[3,26,25,"我使鋒刃臨爾、以報背約之仇、爾集於邑垣、我則降疫癘於其中、付爾於敵、"],[3,26,26,"旣絕餱糧、如折爾杖、十婦炊餅於一爐、權之以給、爾得食而不飽、○"],[3,26,27,"汝猶不聽從、所行逆我、"],[3,26,28,"我必震怒、以拂逆爾、督責爾罪、至於七倍、"],[3,26,29,"爾將食子女之肉、"],[3,26,30,"我亦毀爾崇邱、斫爾日像、以爾尸骸、擲於偶像之上、我心必厭惡爾、"],[3,26,31,"俾爾邑垣荒墟、聖所寂寞、不享爾馨香、"],[3,26,32,"使爾土地荒蕪、處此之敵、無不駭異、"],[3,26,33,"我必散爾於異邦、襲爾以白刃、荒涼爾土、闃寂爾邑、"],[3,26,34,"爾旣寓於敵國、斯土荒寂、其壤則閒、而享安息、"],[3,26,35,"地旣荒寂、必享安息、爾居斯土、其壤所未獲之安息、此時必得享之、"],[3,26,36,"爾之孑遺、處於敵國、必使其心頹敗、風吹葉落、聞聲而怖、彼之遁逃、若避鋒刃、卽無追者、亦必顚仆、"],[3,26,37,"無人追襲、自相蹂躪、如在鋒刃之前、無力拒敵、"],[3,26,38,"爾必危亡於異邦、吞噬於敵國、"],[3,26,39,"爾之孑遺、處於敵國、爲一己之愆尤、幷前人之罪戾、日漸消亡、"],[3,26,40,"是時必承己愆、及前人之罪、自認所行逆我、"],[3,26,41,"我拂逆之、散之敵國、緣其不潔之心、自卑服罪、"],[3,26,42,"我則追憶我與亞伯拉罕以撒雅各所立之約、而俯念斯土、"],[3,26,43,"彼旣蔑視我律例、心厭我典章、致離故土、使田荒寂、於無人時、得享安息、代民服罪、"],[3,26,44,"雖然、彼處於敵國、我不屛斥之、厭惡之、殲滅之、致廢我約、蓋我乃耶和華、彼之上帝、"],[3,26,45,"昔我導其宗祖出於埃及、爲其上帝、異邦無不目擊、故我必念其約、我乃耶和華也、"],[3,26,46,"以上典章律例法度、乃耶和華於西乃山、藉摩西與以色列人所立者、"],[3,27,1,"耶和華諭摩西曰、"],[3,27,2,"告以色列族云、以人許願、俾歸耶和華、則必估其價、"],[3,27,3,"循聖所權衡、自二十歲至六十歲者、男五十舍客勒、"],[3,27,4,"女三十舍客勒、"],[3,27,5,"自五歲至二十歲者、男二十舍客勒、女十舍客勒、"],[3,27,6,"自一月至五歲者、男五舍客勒、女三舍客勒、"],[3,27,7,"自六十歲以上者、男十五舍客勒、女十舍客勒、"],[3,27,8,"倘其人貧乏、不能如價、則宜攜至祭司前、祭司視其力以估之、○"],[3,27,9,"如以可獻之牲畜、許於耶和華、則必以爲聖、"],[3,27,10,"美惡毋相易、如以此易彼、則所許所易者、俱必爲聖、"],[3,27,11,"如所許者、爲不潔之畜、不堪以獻耶和華、則必置之祭司前、"],[3,27,12,"祭司估其價、或美或惡、依其所估而定、"],[3,27,13,"如欲贖之、必於所估之價、加五分之一、○"],[3,27,14,"如以第宅區別爲聖、歸於耶和華、祭司必估其價、或美或惡、依其所估而定、"],[3,27,15,"如欲贖之、必於所估之價、加五分之一、宅則歸己、○"],[3,27,16,"如以爲業之田區別爲聖、歸於耶和華、當視播種之多寡、以估其價、播大麥一賀梅爾者、價值五十舍客勒、"],[3,27,17,"如其獻田自禧年始、則爾所估之價爲定、"],[3,27,18,"如其獻田在禧年後、則祭司必核其後至禧年之歲月、以減其價、"],[3,27,19,"如獻田者自欲贖之、當於所估之價、加五分之一、田則歸己、"],[3,27,20,"如不贖之、或鬻於他人、則不可復贖、"],[3,27,21,"禧年旣屆、必以其田歸耶和華爲聖、如永獻之地然、而爲祭司之業、"],[3,27,22,"如以所購於人、非其所受爲業之田、獻於耶和華爲聖、"],[3,27,23,"則祭司必依爾所估之價、視禧年之遠近而定、是日彼以其金、歸於耶和華爲聖、"],[3,27,24,"迨至禧年、田歸鬻者、卽其原主、"],[3,27,25,"凡爾所估之價、必循聖所權衡、二十季拉爲一舍客勒、"],[3,27,26,"惟首生之畜、或牛或羊、旣歸耶和華爲聖、不得再獻、乃屬於耶和華也、"],[3,27,27,"若爲不潔之畜、則必贖之、依爾所估之價、加五分之一、如其不贖、則依所估而鬻之、○"],[3,27,28,"凡獻於耶和華之物、無論人畜田畝、俱不得鬻、亦不得贖、凡所獻者、乃爲至聖、屬於耶和華、"],[3,27,29,"凡當滅者、不可復贖、必致之死、○"],[3,27,30,"凡土所產、無論地之穀、樹之果、什一歸諸耶和華、是爲聖物、"],[3,27,31,"所應輸之什一、人欲贖之、必加五分之一、"],[3,27,32,"牛羊過於杖下者、必以什一歸諸耶和華爲聖、"],[3,27,33,"或美或惡、毋庸察、亦毋庸易、如其易之、則二者俱爲聖、不得復贖、"],[3,27,34,"以上所載、乃耶和華在西乃山、諭摩西告以色列族之誡命、"],[4,1,1,"以色列族出埃及後、二年二月朔、耶和華在西乃野、會幕中、諭摩西曰、"],[4,1,2,"以色列會衆、循其室家宗族、凡諸丁男、按名以核其數、"],[4,1,3,"自二十歲以上、能臨陳之以色列人、爾及亞倫、當依其行伍而計之、"],[4,1,4,"每支派中、當有一人偕爾、爲其族長、"],[4,1,5,"偕爾之人、其名列下、屬流便者、示丟珥子以利蓿、"],[4,1,6,"屬西緬者、蘇利沙代子示路蔑、"],[4,1,7,"屬猶大者、亞米拿達子拿順、"],[4,1,8,"屬以薩迦者、蘇押子拿坦業、"],[4,1,9,"屬西布倫者、希倫子以利押、"],[4,1,10,"約瑟之裔、屬以法蓮者、亞米忽子以利沙瑪、屬瑪拿西者、比大蓿子迦瑪列、"],[4,1,11,"屬便雅憫者、基多尼子亞比但、"],[4,1,12,"屬但者、亞米沙代子亞希以謝、"],[4,1,13,"屬亞設者、俄蘭子帕結、"],[4,1,14,"屬迦得者、丟珥子以利雅薩、"],[4,1,15,"屬拿弗他利者、以南子亞希拉、"],[4,1,16,"此乃自會中所簡、宗族之牧伯、皆爲以色列軍中之長、"],[4,1,17,"以上所列諸名、摩西亞倫召之、"],[4,1,18,"二月朔、集會衆、循其室家宗族、自二十歲以上、依其名數、述其譜系、"],[4,1,19,"摩西遵耶和華命、在西乃野核其數、○"],[4,1,20,"以色列長子、流便子孫、循其室家宗族、依其名數、自二十歲以上、凡諸丁男、能臨陳者、"],[4,1,21,"計四萬六千五百、"],[4,1,22,"西緬子孫、循其室家宗族、依其名數、自二十歲以上、凡諸丁男、能臨陳者、"],[4,1,23,"計五萬九千三百、"],[4,1,24,"迦得子孫、循其室家宗族、依其名數、自二十歲以上、能臨陳者、"],[4,1,25,"計四萬五千六百五十、"],[4,1,26,"猶大子孫、循其室家宗族、依其名數、自二十歲以上、能臨陳者、"],[4,1,27,"計七萬四千六百、"],[4,1,28,"以薩迦子孫、循其室家宗族、依其名數、自二十歲以上、能臨陳者、"],[4,1,29,"計五萬四千四百、"],[4,1,30,"西布倫子孫、循其室家宗族、依其名數、自二十歲以上、能臨陳者、"],[4,1,31,"計五萬七千四百、"],[4,1,32,"約瑟之裔、以法蓮子孫、循其室家宗族、依其名數、自二十歲以上、能臨陳者、"],[4,1,33,"計四萬有五百、"],[4,1,34,"瑪拿西子孫、循其室家宗族、依其名數、自二十歲以上、能臨陳者、"],[4,1,35,"計三萬二千二百、"],[4,1,36,"便雅憫子孫、循其室家宗族、依其名數、自二十歲以上、能臨陳者、"],[4,1,37,"計三萬五千四百、"],[4,1,38,"但之子孫、循其室家宗族、依其名數、自二十歲以上、能臨陳者、"],[4,1,39,"計六萬二千七百、"],[4,1,40,"亞設子孫、循其室家宗族、依其名數、自二十歲以上、能臨陳者、"],[4,1,41,"計四萬一千五百、"],[4,1,42,"拿弗他利子孫、循其室家宗族、依其名數、自二十歲以上、能臨陳者、"],[4,1,43,"計五萬三千四百、"],[4,1,44,"以上所載、乃摩西亞倫與以色列之牧伯十二人、各爲其宗族所核計、"],[4,1,45,"以色列人、按其宗族、自二十歲以上、能臨陳者、"],[4,1,46,"綜計六十萬三千五百五十人、"],[4,1,47,"利未宗族、不列其數、"],[4,1,48,"蓋耶和華曾諭摩西曰、"],[4,1,49,"利未支派勿核、勿與以色列族同計其數、"],[4,1,50,"必立之以理法幕、及其器皿、與其所有、彼必舁幕曁器、供役其中、四周建營、"],[4,1,51,"徙幕時、利未人撤之、張幕時、利未人立之、外人近其側、必致之死、"],[4,1,52,"以色列衆張幕、各在其營、各循其纛、各依其伍、"],[4,1,53,"惟利未人建營、當環法幕、免以色列會衆干怒、守衞法幕、乃利未人之責任、"],[4,1,54,"以色列族、遵耶和華所諭摩西之命而行、"],[4,2,1,"耶和華諭摩西亞倫曰、"],[4,2,2,"以色列族建營、當各隨其纛、附宗族之斾、在會幕四周、"],[4,2,3,"東方日出之所、凡隸猶大營之纛者、按其行伍建營、亞米拿達子拿順爲其牧伯、"],[4,2,4,"彼之軍旅、見核者、計七萬四千六百、"],[4,2,5,"以薩迦支派附之建營、蘇押子拿坦業爲其牧伯、"],[4,2,6,"彼之軍旅、見核者、計五萬四千四百、"],[4,2,7,"西布倫支派次之、希倫子以利押爲其牧伯、"],[4,2,8,"彼之軍旅、見核者、計五萬七千四百、"],[4,2,9,"凡隸猶大營者、按其行伍、綜計十八萬六千四百、是爲前隊、○"],[4,2,10,"南方有流便營之纛、按其行伍、示丟珥子以利蓿爲其牧伯、"],[4,2,11,"彼之軍旅、見核者、計四萬六千五百、"],[4,2,12,"西緬支派附之建營、蘇利沙代子示路蔑爲其牧伯、"],[4,2,13,"彼之軍旅、見核者、計五萬九千三百、"],[4,2,14,"迦得支派次之、丟珥子以利雅薩爲其牧伯、"],[4,2,15,"彼之軍旅、見核者、計四萬五千六百五十、"],[4,2,16,"凡隸流便營者、按其行伍、綜計十五萬一千四百五十、是爲二隊、○"],[4,2,17,"隨後會幕啟行、利未營在諸營之中、其啟行也、依其建營之序、各歸其隊、各隨其纛、○"],[4,2,18,"西方有以法蓮營之纛、按其行伍、亞米忽子以利沙瑪爲其牧伯、"],[4,2,19,"彼之軍旅、見核者、計四萬有五百、"],[4,2,20,"瑪拿西支派附之建營、比大蓿子迦瑪列爲其牧伯、"],[4,2,21,"彼之軍旅、見核者、計三萬二千二百、"],[4,2,22,"便雅憫支派次之、基多尼子亞比但爲其牧伯、"],[4,2,23,"彼之軍旅、見核者、計三萬五千四百、"],[4,2,24,"凡隸以法蓮營者、按其行伍、綜計十萬八千一百、是爲三隊、○"],[4,2,25,"北方有但營之纛、按其行伍、亞米沙代子亞希以謝爲其牧伯、"],[4,2,26,"彼之軍旅、見核者、計六萬二千七百、"],[4,2,27,"亞設支派附之建營、俄蘭子帕結爲其牧伯、"],[4,2,28,"彼之軍旅、見核者、計四萬一千五百、"],[4,2,29,"拿弗他利支派次之、以南子亞希拉爲其牧伯、"],[4,2,30,"彼之軍旅、見核者、計五萬三千四百、"],[4,2,31,"凡隸但之營者、按其行伍、綜計十五萬七千六百、是爲後隊、隨纛而行、○"],[4,2,32,"以上所載、乃以色列人循其宗族、按其行伍、諸營見核者、綜計六十萬三千五百五十、"],[4,2,33,"利未族不列其數、遵耶和華所諭摩西之命、"],[4,2,34,"以色列族各隨其纛以建營、循其室家宗族而啟行、悉遵耶和華所諭摩西之命、"],[4,3,1,"耶和華在西乃山諭摩西時、亞倫摩西之裔如左、"],[4,3,2,"亞倫之子、長拿答、次亞比戶、以利亞撒、以他瑪、"],[4,3,3,"彼之諸子、咸沐以膏、摩西區別之、俾任祭司職、"],[4,3,4,"拿答亞比戶在西乃野、以不聖之火獻耶和華、故死於其前、二人無子、以利亞撒以他瑪在父亞倫前、供祭司之職、○"],[4,3,5,"耶和華諭摩西曰、"],[4,3,6,"使利未族近前、立於祭司亞倫前、而服事之、"],[4,3,7,"爲亞倫及會衆、供其役事於幕、"],[4,3,8,"守會幕之器、爲以色列族供其役事於幕、"],[4,3,9,"必以利未人畀亞倫及其子、蓋彼自以色列族中、歸於亞倫、"],[4,3,10,"惟立亞倫及其子爲祭司、以守厥職、外人近會幕、必致之死、○"],[4,3,11,"耶和華諭摩西曰、"],[4,3,12,"我自以色列族中、取利未人、代以色列族初胎之男、故利未人屬我、"],[4,3,13,"蓋首生者、悉屬於我、昔在埃及戮其首生者時、我取以色列族之首生者、或人或畜、區別爲聖、以歸於我、我乃耶和華也、○"],[4,3,14,"耶和華在西乃野、諭摩西曰、"],[4,3,15,"當循利未人之室家宗族、而核其數、凡諸丁男、自一月以上者核之、"],[4,3,16,"摩西遵耶和華命而核之、"],[4,3,17,"利未諸子之名如左、革順、哥轄、米拉利、"],[4,3,18,"革順之子、循其室家、其名立尼、示每、"],[4,3,19,"哥轄之子、循其室家、其名暗蘭、以斯哈、希伯倫、烏薛、"],[4,3,20,"米拉利之子、循其室家、其名抹利、母示、斯乃利未室家、循其宗族、○"],[4,3,21,"屬革順者、有立尼示每室家二、"],[4,3,22,"見核丁男、自一月以上、計七千五百、"],[4,3,23,"於幕之後、西向建營、"],[4,3,24,"拉伊勒子以利亞薩、爲革順族之牧伯、"],[4,3,25,"革順子孫、於會幕中所當守者、幕與帷、及其幬、會幕門㡘、"],[4,3,26,"幕壇四周之院帷、及院門之㡘、曁所用之索、○"],[4,3,27,"屬哥轄者、有暗蘭、以斯哈、希伯倫、烏薛室家四、"],[4,3,28,"見核丁男、自一月以上、計八千六百、以守聖所、"],[4,3,29,"於幕南向建營、"],[4,3,30,"烏薛子以利撒反、爲哥轄族之牧伯、"],[4,3,31,"哥轄人所當守者、匱、案、燈臺曁壇、及聖所所用之器、㡘與屬㡘之物、"],[4,3,32,"祭司亞倫子以利亞撒、爲利未族牧伯之長、統理守聖所之人、○"],[4,3,33,"屬米拉利者、有抹利母示室家二、"],[4,3,34,"見核丁男、自一月以上、計六千二百、"],[4,3,35,"於幕北向建營、亞比亥子蘇列、爲米拉利二室家之牧伯、"],[4,3,36,"米拉利子孫之職、乃守會幕之板、楗、柱、座、與所用之器皿、"],[4,3,37,"及院四周之柱、座、釘、索、"],[4,3,38,"摩西亞倫及亞倫子、乃於幕前、東向建營、守衞聖所、以代以色列族之任、外人近前、必致之死、"],[4,3,39,"摩西亞倫遵耶和華命、核利未人數、依其室家、凡諸丁男、自一月以上、計二萬二千、○"],[4,3,40,"耶和華諭摩西曰、以色列族首生之男、自一月以上者核之、記其名數、"],[4,3,41,"我乃耶和華、當取利未人歸我、代以色列族首生之男、並取利未人之畜、代以色列族首生之畜、"],[4,3,42,"摩西循耶和華命爲以色列族首生之男、核計其數、"],[4,3,43,"按名見核者、自一月以上、計二萬二千二百七十三、○"],[4,3,44,"耶和華諭摩西曰、"],[4,3,45,"取利未人、代以色列族首生之男、取利未人之畜、代其首生之畜、使利未人歸我、我乃耶和華也、"],[4,3,46,"以色列族首生之男、其數較諸利未人、多二百七十三人、俱當贖之、"],[4,3,47,"宜爲各人取金五舍客勒、循聖所權衡、一舍客勒卽二十季拉、"],[4,3,48,"以此贖金、歸亞倫及其子、"],[4,3,49,"利未人所贖者之外、摩西由以色列族首生之男、取其贖金、計一千三百六十五舍客勒、依聖所權衡、"],[4,3,50,"利未人所贖者之外、摩西由以色列族首生之男、取其贖金、計一千三百六十五舍客勒、依聖所權衡、"],[4,3,51,"以與亞倫及其子、循耶和華所命、"],[4,4,1,"耶和華諭摩西亞倫曰、"],[4,4,2,"利未族中、哥轄子孫、當核其數循其室家宗族、"],[4,4,3,"自三十歲至五十、凡任職從事於會幕者核之、"],[4,4,4,"哥轄子孫、於會幕所供役者、乃至聖之什物、"],[4,4,5,"移營之時、亞倫及其子宜入、撤㡘以掩法匱、"],[4,4,6,"施獺皮其上、覆以純藍之布、而貫其杠、"],[4,4,7,"陳餅之几、覆以藍布、盤匙與灌奠之盂盃、及恆陳之餅、悉置其上、"],[4,4,8,"覆以紫布、蓋以獺皮、而貫其杠、"],[4,4,9,"以藍布蓋燈臺、及盞剪盤、與所用之油器、"],[4,4,10,"覆以獺皮、悉置於架、"],[4,4,11,"以藍布覆金壇、蓋以獺皮、而貫其杠、"],[4,4,12,"聖所供事之器、裹以藍布、蓋以獺皮、悉置於架、"],[4,4,13,"祭壇之灰必棄、覆以紫布、"],[4,4,14,"火鼎、鈎、鏟、盆、及凡屬壇之器、悉置其上、蓋以獺皮、而貫其杠、"],[4,4,15,"移營之時、亞倫及其子、蓋聖所諸器已畢、哥轄子孫、則前以舁、惟不可捫聖物、免其死亡、此乃哥轄子孫、在會幕之職任、"],[4,4,16,"祭司亞倫子以利亞撒所守者、乃燈油、芳品、日獻之素祭、及膏、統理會幕、曁其中所有、聖所與其器、"],[4,4,17,"耶和華諭摩西亞倫曰、"],[4,4,18,"勿絕哥轄族於利未族中、"],[4,4,19,"彼衆近至聖之物時、亞倫及其子、當入聖室、定衆所役所荷、如是而行、俾其仍可生存、不致死亡、"],[4,4,20,"惟哥轄人、須臾勿入聖所以觀、免其死亡、○"],[4,4,21,"耶和華諭摩西曰、"],[4,4,22,"革順子孫、宜核其數、循其室家宗族、"],[4,4,23,"自三十歲至五十、凡任職從事於會幕者核之、"],[4,4,24,"革順人之供役、與其負荷如左、"],[4,4,25,"會幕與帷、及幬、在上之獺皮、幕門之㡘、"],[4,4,26,"幕壇四周之院帷、及院門之㡘、索與所有供事之器、彼經理之、"],[4,4,27,"革順人之供役、與其負荷、悉從亞倫及其子之命、彼之所荷、令其監守、"],[4,4,28,"此乃革順族之室家、在會幕之職任、祭司亞倫子以他瑪統理之、○"],[4,4,29,"米拉利子孫、宜核其數、循其室家宗族、"],[4,4,30,"自三十歲至五十、凡任職從事於會幕者核之、"],[4,4,31,"彼於會幕供役、所當守者、幕之板楗柱座、"],[4,4,32,"院四周之柱座釘索、與供事之器、皆按名指定之、"],[4,4,33,"此乃米拉利族之室家、在會幕之職任、祭司亞倫子以他瑪統理之、○"],[4,4,34,"摩西亞倫及會衆之牧伯、核數哥轄子孫、循其室家宗族、"],[4,4,35,"自三十歲至五十、凡任職從事於會幕者、"],[4,4,36,"計二千七百五十、"],[4,4,37,"摩西亞倫遵耶和華所諭摩西之命、核數哥轄子孫、凡從事於會幕者、其數卽此、○"],[4,4,38,"革順子孫、循其室家宗族、"],[4,4,39,"自三十歲至五十、凡任職從事於會幕者、"],[4,4,40,"計二千六百三十、"],[4,4,41,"摩西亞倫遵耶和華命、核數革順子孫、凡從事於會幕者、其數卽此、○"],[4,4,42,"米拉利子孫、循其室家宗族、"],[4,4,43,"自三十歲至五十、凡任職從事於會幕者、"],[4,4,44,"計三千二百、"],[4,4,45,"摩西亞倫遵耶和華所諭摩西之命、核數米拉利子孫、其數卽此、○"],[4,4,46,"摩西亞倫及以色列牧伯、核數利未人、循其室家宗族、"],[4,4,47,"自三十歲至五十、凡任職從事於會幕、而負重者、"],[4,4,48,"共計八千五百八十、"],[4,4,49,"摩西循其供役負荷、而核數之、悉遵耶和華命、"],[4,5,1,"耶和華諭摩西曰、"],[4,5,2,"命以色列族云、凡患癩疾、白濁、及捫尸蒙汚之人、"],[4,5,3,"無論男女、悉當出之、屛於營外、免汚其營、我所居者、"],[4,5,4,"以色列族遵耶和華所諭摩西之命、出之營外、○"],[4,5,5,"耶和華諭摩西曰、"],[4,5,6,"告以色列族云、如男女蹈愆、干犯耶和華、自取罪戾、"],[4,5,7,"當認其過、盡償所負、加五分之一、與所負之人、"],[4,5,8,"倘欲償之、而其人無戚屬、則宜償於耶和華、而歸於祭司、此外、亦獻牡綿羊爲祭、以贖其罪、"],[4,5,9,"以色列族所有舉祭、奉於祭司者、必歸祭司、"],[4,5,10,"人所獻之聖物、必歸祭司、凡與祭司者、必歸之、○"],[4,5,11,"耶和華諭摩西曰、"],[4,5,12,"告以色列族云、如人之妻、有違婦道、獲罪於夫、"],[4,5,13,"與人有私、以玷其身、事屬隱祕、夫不及知、無人爲證、亦未被執、"],[4,5,14,"其夫若生疑忌、無論婦之有玷與否、"],[4,5,15,"必攜其妻詣祭司、以麰麥麪伊法十分之一、奉爲禮物、勿傾以油、勿加乳香、乃爲疑忌而獻之素祭、俾念罪愆、"],[4,5,16,"祭司必使婦進而立於耶和華前、"],[4,5,17,"以瓦器盛聖水、取幕地之塵、置於水中、"],[4,5,18,"婦旣立於耶和華前、祭司必散其髮、取爲疑忌而獻之素祭、俾念罪愆者、置於其手、祭司執致詛之苦水、"],[4,5,19,"令婦發誓、謂之曰、如爾未私於人、未嘗背夫而行穢事、則願爾免此致詛苦水之害、"],[4,5,20,"如爾背夫而行穢事、有私於人、爲人所玷、"],[4,5,21,"則可發誓、願耶和華使汝見詛於民中、髀消腹鼓、"],[4,5,22,"此致詛之苦水、將入汝腸、令汝髀消腹鼓、婦宜曰、阿們、阿們、"],[4,5,23,"祭司必書此詛於簡、塗其文於苦水、"],[4,5,24,"令婦飲此致詛之水、入腹爲苦、"],[4,5,25,"祭司遂自婦手、取爲疑忌而獻之素祭、搖於耶和華前、攜以詣壇、"],[4,5,26,"於其中取一握、以爲記誌、焚之於壇、然後使婦飲水、"],[4,5,27,"旣飲之後、如婦被玷、獲罪於夫、則致詛之水、入其腹而爲苦、使其腹鼓髀消、見詛於民中、"],[4,5,28,"如婦潔清無玷、則免罪戾、而能懷姙、"],[4,5,29,"此乃婦旣有夫、而違婦道、玷及其身、則夫懷疑而忌其婦之法、"],[4,5,30,"置婦於耶和華前、祭司遵法而行、"],[4,5,31,"夫則無愆、婦有罪則負之、"],[4,6,1,"耶和華諭摩西曰、"],[4,6,2,"告以色列族云、如男女許願爲拿細耳人、自爲區別、歸於耶和華、"],[4,6,3,"清酒醇醪、必戒之、清酒醇醪所釀之醯、及葡萄汁、均勿飲、葡萄或鮮或乾、均勿食、"],[4,6,4,"自爲區別時、葡萄樹所產、自實及皮、均不可食、"],[4,6,5,"旣自許願區別、薙髮之刀、勿加於首、迨區別歸於耶和華之日旣盈、彼必爲聖、當留其髮、"],[4,6,6,"自爲區別、歸於耶和華時、毋近尸側、"],[4,6,7,"旣已留髮、顯其歸於上帝、雖其父母兄弟姊妹死、毋爲之蒙不潔、"],[4,6,8,"自爲區別時、彼歸耶和華爲聖、"],[4,6,9,"倘有人猝死其側、致首蒙汚、必待七日而後爲潔、是日薙髮、"],[4,6,10,"越至八日、攜鳲鳩二、或雛鴿二、至會幕門、付於祭司、"],[4,6,11,"祭司獻之、一爲贖罪祭、一爲燔祭、贖其近尸之罪、卽日俾首成潔、"],[4,6,12,"自爲區別時、因其蒙汚、宜復區別、歸於耶和華、攜一歲之牡羔一、爲補過祭、旣往之日、乃爲虛度、○"],[4,6,13,"爲拿細耳人者、所許之日旣盈、其例如左、當攜之至會幕門前、"],[4,6,14,"獻禮物於耶和華、一歲之牡羔一、爲燔祭、一歲之牝羔一、爲贖罪祭、牡綿羊一、爲酬恩祭、俱須無疵、"],[4,6,15,"曁無酵餅一筐、和油之細麪餅、抹油之無酵薄餅、及相隨之素祭灌祭、"],[4,6,16,"祭司取而奉於耶和華前、爲之獻贖罪祭、及燔祭、"],[4,6,17,"亦獻牡綿羊、爲酬恩祭、並獻無酵餅一筐、與相隨之素祭灌祭、"],[4,6,18,"拿細耳人於會幕門、必薙其區別之髮、投於酬恩祭下之火、"],[4,6,19,"旣薙之後、祭司取所烹之羊肩、與筐中之無酵餅一、無酵薄餅一、付於拿細耳人之手、"],[4,6,20,"祭司必搖於耶和華前、以爲搖祭、此物與所搖之腔、所舉之腿、同爲聖物、歸於祭司、厥後拿細耳人方可飲酒、"],[4,6,21,"拿細耳人許願區別、以禮物奉耶和華、其例若是、外此如能別有所加、必循區別之例、依其所許之願而行、○"],[4,6,22,"耶和華諭摩西曰、"],[4,6,23,"告亞倫及其子云、爾爲以色列族祝嘏、必曰、"],[4,6,24,"願耶和華福祚爾、護持爾、"],[4,6,25,"願耶和華使其容光照爾、施恩於爾、"],[4,6,26,"願耶和華歡顏顧爾、錫爾平康、"],[4,6,27,"如是以我名加以色列族、我必錫嘏焉、"],[4,7,1,"建幕旣畢、摩西膏之、及其諸器、區別爲聖、亦膏祭壇、及其諸器、區別爲聖、"],[4,7,2,"當日以色列族長、卽諸支派中見核之人之牧伯、奉獻禮物、"],[4,7,3,"攜至耶和華前、卽蒙幭之車六、牛十有二、每二牧伯獻一車、每一牧伯獻一牛、奉於幕前、"],[4,7,4,"耶和華諭摩西曰、"],[4,7,5,"爾其收之、以供會幕之用、給予利未人、各循其役事、"],[4,7,6,"摩西遂以車與牛、予利未人、"],[4,7,7,"兩車四牛、予革順子孫、循其役事、"],[4,7,8,"四車八牛、予米拉利子孫、循其役事、祭司亞倫子以他瑪統理之、"],[4,7,9,"惟哥轄子孫弗予、因其供聖所之役事、以肩負荷也、"],[4,7,10,"膏壇時、牧伯獻禮物於壇前、以區別之、"],[4,7,11,"耶和華諭摩西曰、牧伯各循其日、獻禮物以區別其壇、○"],[4,7,12,"首日獻禮物者、猶大支派、亞米拿達子拿順、"],[4,7,13,"所獻者、銀盤一、重一百三十舍客勒、銀盂一、重七十舍客勒、循聖所權衡、俱盈以和油之細麪、爲素祭、"],[4,7,14,"金甌一、重十舍客勒、盈以香、"],[4,7,15,"牡犢一、牡綿羊一、一歲之牡羔一、爲燔祭、"],[4,7,16,"牡山羊一、爲贖罪祭、"],[4,7,17,"牛二、牡綿羊五、牡山羊五、一歲之牡羔五、爲酬恩祭、皆亞米拿達子拿順所獻、○"],[4,7,18,"二日、以薩迦牧伯、蘇押子拿坦業獻禮物、"],[4,7,19,"銀盤一、重一百三十舍客勒、銀盂一、重七十舍客勒、循聖所權衡、俱盈以和油之細麪、爲素祭、"],[4,7,20,"金甌一、重十舍客勒、盈以香、"],[4,7,21,"牡犢一、牡綿羊一、一歲之牡羔一、爲燔祭、"],[4,7,22,"牡山羊一、爲贖罪祭、"],[4,7,23,"牛二、牡綿羊五、牡山羊五、一歲之牡羔五、爲酬恩祭、皆蘇押子拿坦業所獻、○"],[4,7,24,"三日、西布倫牧伯、希倫子以利押獻禮物、"],[4,7,25,"銀盤一、重一百三十舍客勒、銀盂一、重七十舍客勒、循聖所權衡、俱盈以和油之細麪、爲素祭、"],[4,7,26,"金甌一、重十舍客勒、盈以香、"],[4,7,27,"牡犢一、牡綿羊一、一歲之牡羔一、爲燔祭、"],[4,7,28,"牡山羊一、爲贖罪祭、"],[4,7,29,"牛二、牡綿羊五、牡山羊五、一歲之牡羔五、爲酬恩祭、皆希倫子以利押所獻、○"],[4,7,30,"四日、流便牧伯、示丟珥子以利蓿獻禮物、"],[4,7,31,"銀盤一、重一百三十舍客勒、銀盂一、重七十舍客勒、循聖所權衡、俱盈以和油之細麪、爲素祭、"],[4,7,32,"金甌一、重十舍客勒、盈以香、"],[4,7,33,"牡犢一、牡綿羊一、一歲之牡羔一、爲燔祭、"],[4,7,34,"牡山羊一、爲贖罪祭、"],[4,7,35,"牛二、牡綿羊五、牡山羊五、一歲之牡羔五、爲酬恩祭、皆示丟珥子以利蓿所獻、○"],[4,7,36,"五日、西緬牧伯、蘇利沙代子示路蔑獻禮物、"],[4,7,37,"銀盤一、重一百三十舍客勒、銀盂一、重七十舍客勒、循聖所權衡、俱盈以和油之細麪、爲素祭、"],[4,7,38,"金甌一、重十舍客勒、盈以香、"],[4,7,39,"牡犢一、牡綿羊一、一歲之牡羔一、爲燔祭、"],[4,7,40,"牡山羊一、爲贖罪祭、"],[4,7,41,"牛二、牡綿羊五、牡山羊五、一歲之牡羔五、爲酬恩祭、皆蘇利沙代子示路蔑所獻、○"],[4,7,42,"六日、迦得牧伯、丟珥子以利雅薩獻禮物、"],[4,7,43,"銀盤一、重一百三十舍客勒、銀盂一、重七十舍客勒、循聖所權衡、俱盈以和油之細麪、爲素祭、"],[4,7,44,"金甌一、重十舍客勒、盈以香、"],[4,7,45,"牡犢一、牡綿羊一、一歲之牡羔一、爲燔祭、"],[4,7,46,"牡山羊一、爲贖罪祭、"],[4,7,47,"牛二、牡綿羊五、牡山羊五、一歲之牡羔五、爲酬恩祭、皆丟珥子以利雅薩所獻、○"],[4,7,48,"七日、以法蓮牧伯、亞米忽子以利沙瑪獻禮物、"],[4,7,49,"銀盤一、重一百三十舍客勒、銀盂一、重七十舍客勒、循聖所權衡、俱盈以和油之細麪、爲素祭、"],[4,7,50,"金甌一、重十舍客勒、盈以香、"],[4,7,51,"牡犢一、牡綿羊一、一歲之牡羔一、爲燔祭、"],[4,7,52,"牡山羊一、爲贖罪祭、"],[4,7,53,"牛二、牡綿羊五、牡山羊五、一歲之牡羔五、爲酬恩祭、皆亞米忽子以利沙瑪所獻、○"],[4,7,54,"八日、瑪拿西牧伯、比大蓿子迦瑪列獻禮物、"],[4,7,55,"銀盤一、重一百三十舍客勒、銀盂一、重七十舍客勒、循聖所權衡、俱盈以和油之細麪、爲素祭、"],[4,7,56,"金甌一、重十舍客勒、盈以香、"],[4,7,57,"牡犢一、牡綿羊一、一歲之牡羔一、爲燔祭、"],[4,7,58,"牡山羊一、爲贖罪祭、"],[4,7,59,"牛二、牡綿羊五、牡山羊五、一歲之牡羔五、爲酬恩祭、皆比大蓿子迦瑪列所獻、○"],[4,7,60,"九日、便雅憫牧伯、基多尼子亞比但獻禮物、"],[4,7,61,"銀盤一、重一百三十舍客勒、銀盂一、重七十舍客勒、循聖所權衡、俱盈以和油之細麪、爲素祭、"],[4,7,62,"金甌一、重十舍客勒、盈以香、"],[4,7,63,"牡犢一、牡綿羊一、一歲之牡羔一、爲燔祭、"],[4,7,64,"牡山羊一、爲贖罪祭、"],[4,7,65,"牛二、牡綿羊五、牡山羊五、一歲之牡羔五、爲酬恩祭、皆基多尼子亞比但所獻、○"],[4,7,66,"十日、但之牧伯、亞米沙代子亞希以謝獻禮物、"],[4,7,67,"銀盤一、重一百三十舍客勒、銀盂一、重七十舍客勒、循聖所權衡、俱盈以和油之細麪、爲素祭、"],[4,7,68,"金甌一、重十舍客勒、盈以香、"],[4,7,69,"牡犢一、牡綿羊一、一歲之牡羔一、爲燔祭、"],[4,7,70,"牡山羊一、爲贖罪祭、"],[4,7,71,"牛二、牡綿羊五、牡山羊五、一歲之牡羔五、爲酬恩祭、皆亞米沙代子亞希以謝所獻、○"],[4,7,72,"十一日、亞設牧伯、俄蘭子帕結獻禮物、"],[4,7,73,"銀盤一、重一百三十舍客勒、銀盂一、重七十舍客勒、循聖所權衡、俱盈以和油之細麪、爲素祭、"],[4,7,74,"金甌一、重十舍客勒、盈以香、"],[4,7,75,"牡犢一、牡綿羊一、一歲之牡羔一、爲燔祭、"],[4,7,76,"牡山羊一、爲贖罪祭、"],[4,7,77,"牛二、牡綿羊五、牡山羊五、一歲之牡羔五、爲酬恩祭、皆俄蘭子帕結所獻、○"],[4,7,78,"十二日、拿弗他利牧伯、以南子亞希拉獻禮物、"],[4,7,79,"銀盤一、重一百三十舍客勒、銀盂一、重七十舍客勒、循聖所權衡、俱盈以和油之細麪、爲素祭、"],[4,7,80,"金甌一、重十舍客勒、盈以香、"],[4,7,81,"牡犢一、牡綿羊一、一歲之牡羔一、爲燔祭、"],[4,7,82,"牡山羊一、爲贖罪祭、"],[4,7,83,"牛二、牡綿羊五、牡山羊五、一歲之牡羔五、爲酬恩祭、皆以南子亞希拉所獻、○"],[4,7,84,"膏壇時、以色列牧伯所獻、銀盤十二、銀盂十二、金甌十二、"],[4,7,85,"盤各重一百三十舍客勒、盂各重七十舍客勒、諸器皿之銀、共計二千四百舍客勒、循聖所權衡、"],[4,7,86,"金甌十二、盈以香、甌各重十舍客勒、共計一百二十舍客勒、循聖所權衡、"],[4,7,87,"牡犢十有二、牡綿羊十有二、一歲之牡羔十有二、以爲燔祭、與其素祭、山羊之羔十有二、爲贖罪祭、"],[4,7,88,"牡牛二十四、牡綿羊六十、牡山羊六十、一歲之牡羔六十、爲酬恩祭、皆膏壇後所獻、○"],[4,7,89,"摩西入會幕、與耶和華言、則聞二基路伯間、法匱施恩座上、有聲與之言、卽耶和華與之言也、"],[4,8,1,"耶和華諭摩西曰、"],[4,8,2,"告亞倫云、燃燈之時、宜使七盞明耀於臺前、"],[4,8,3,"亞倫遵耶和華所諭摩西之命而行、燃燈明耀於臺前、"],[4,8,4,"燈臺以金爲之、自座及花、悉用鏇法而造、遵耶和華所示摩西之式、○"],[4,8,5,"耶和華諭摩西曰、"],[4,8,6,"於以色列族中、取利未人潔之、"],[4,8,7,"潔禮如左、以贖罪之水灑之、使以薙刀、薙其全體、濯衣潔身、"],[4,8,8,"取牡犢爲燔祭、和油之細麪爲素祭、又取牡犢一、爲贖罪祭、"],[4,8,9,"攜利未人至會幕前、集以色列會衆、"],[4,8,10,"旣引利未人於耶和華前、使以色列人按手其首、"],[4,8,11,"亞倫奉利未人於耶和華、爲以色列族獻之、以爲搖祭、供耶和華之役事、"],[4,8,12,"利未人按手於二犢之首、爾則獻之、一爲贖罪祭、一爲燔祭、奉於耶和華、以贖其罪、"],[4,8,13,"使利未人立於亞倫及其子前、奉於耶和華、以爲搖祭、"],[4,8,14,"如是區別利未人於以色列族、使之歸我、"],[4,8,15,"厥後利未人必入會幕、供其役事、爾必潔之、奉爲搖祭、"],[4,8,16,"蓋利未人悉歸於我、我取其人、代以色列族初胎之男、使爲我有、"],[4,8,17,"以色列族諸首生者、或人或畜、咸爲我有、我戮埃及首生者時、區別之以歸我、"],[4,8,18,"我取利未人、以代以色列族初胎之男、"],[4,8,19,"亦取之、以賜亞倫及其子、於會幕中、爲以色列族供其役事、代之贖罪、免以色列族近於聖所、而遭災禍、"],[4,8,20,"摩西亞倫曁以色列會衆、如是待利未人、悉遵耶和華命、"],[4,8,21,"利未人去罪爲潔、洗濯其衣、亞倫奉於耶和華、以爲搖祭、代爲贖罪、使之成潔、"],[4,8,22,"厥後利未人入會幕、於亞倫及其子前、以供役事、耶和華指利未人、所諭摩西者、以色列人悉遵行之、○"],[4,8,23,"耶和華諭摩西曰、"],[4,8,24,"利未人供役事、有定例焉、自二十五歲以上、可入會幕、以供役事、"],[4,8,25,"至於五十、乃罷其役、"],[4,8,26,"偕其兄弟同守會幕、毋再役事、其例若此、"],[4,9,1,"出埃及二年正月、耶和華於西乃野、諭摩西曰、"],[4,9,2,"屆期、以色列族當守逾越節、"],[4,9,3,"月之十四日薄暮、遵典章律例、而守節期、"],[4,9,4,"摩西遂告以色列族守逾越節、"],[4,9,5,"正月十四日薄暮、以色列族在西乃野、守逾越節、循耶和華所諭摩西之命、○"],[4,9,6,"有人緣尸蒙汚、不得於是日守逾越節、至摩西亞倫前、"],[4,9,7,"曰、吾儕緣尸蒙汚、屆期奚禁我與以色列族、同獻禮物於耶和華、"],[4,9,8,"摩西曰、姑待此、我將聽耶和華何以諭爾、○"],[4,9,9,"耶和華諭摩西曰、"],[4,9,10,"告以色列族云、凡爾曹及後裔、若緣尸蒙汚、或行遠道、亦當守逾越節、以奉事耶和華、"],[4,9,11,"二月十四日薄暮守之、食羔、及無酵餅、與苦菜、"],[4,9,12,"勿留其餘於明晨、勿折其骨、悉遵逾越節例而守之、"],[4,9,13,"如人未蒙不潔、未行遠道、而弗守逾越節者、必絕於民中、因屆期不獻禮物於耶和華、必負其罪、"],[4,9,14,"如外人旅於爾中、欲守逾越節、以奉事耶和華、必循典章律例而守之、賓旅宗族、俱爲一例、○"],[4,9,15,"張法幕之日、有雲覆之、自夕達旦、幕上明耀如火、"],[4,9,16,"恆久如斯、雲覆厥幕、夜間其狀若火、"],[4,9,17,"雲昇離幕、以色列族啟行、雲止之所、以色列族建營、"],[4,9,18,"以色列族啟行建營、俱循耶和華命、雲覆幕時、民則處營、"],[4,9,19,"雲止於幕、歷日旣久、則以色列族遵耶和華命、而不啟行、"],[4,9,20,"雲止於幕、爲日無幾、則處營、或啟行、俱循耶和華命、"],[4,9,21,"有時雲止、自夕達旦、詰朝而昇、民則啟行、有時雲止、歷一晝夜而昇、民則啟行、"],[4,9,22,"雲止於幕、或兩日、或一月、或一年、以色列族則處於營、而不前往、以待雲昇、然後啟行、"],[4,9,23,"建營啟行、俱循耶和華命、悉遵耶和華所諭摩西之命而行、"],[4,10,1,"耶和華諭摩西曰、"],[4,10,2,"宜用鏇法、製銀角二、用集會衆、使營啟行、"],[4,10,3,"吹二角時、會衆宜集、就爾於會幕前、"],[4,10,4,"吹一角時、以色列軍旅之牧伯、必集就爾、"],[4,10,5,"吹角以警、則東營啟行、"],[4,10,6,"二次、則南營啟行、啟行時、必吹角以警、"],[4,10,7,"集會衆時、可吹角、勿警人、"],[4,10,8,"亞倫子孫爲祭司者、必吹其角、著爲永例、歷世弗替、"],[4,10,9,"有敵犯境、爾往攻之、必以角聲警人、則耶和華爾之上帝、必垂念爾、拯爾於敵、"],[4,10,10,"樂日、節期、月朔、當因獻燔祭、酬恩祭、而吹其角、以爲紀念於爾上帝前、我乃耶和華、爾之上帝也、○"],[4,10,11,"二年二月二十日、雲離法幕、"],[4,10,12,"以色列族啟行、去西乃野、雲止於巴蘭野、"],[4,10,13,"民遵耶和華所諭摩西之命而啟行、乃始於此、"],[4,10,14,"從猶大營之纛者、按其行伍、啟行爲前隊、亞米拿達子拿順統領其軍、"],[4,10,15,"蘇押子拿坦業統以薩迦軍、"],[4,10,16,"希倫子以利押統西布倫軍、"],[4,10,17,"繼而徹幕、革順米拉利子孫、負之啟行、"],[4,10,18,"從流便營之纛者、按其行伍啟行、示丟珥子以利蓿統領其軍、"],[4,10,19,"蘇利沙代子示路蔑統西緬軍、"],[4,10,20,"丟珥子以利雅薩統迦得軍、"],[4,10,21,"哥轄子孫、負聖所什物啟行、先行之人、建幕以待其至、"],[4,10,22,"從以法蓮營之纛者、按其行伍啟行、亞米忽子以利沙瑪統領其軍、"],[4,10,23,"比大蓿子迦瑪列統瑪拿西軍、"],[4,10,24,"基多尼子亞比但統便雅憫軍、"],[4,10,25,"從但營之纛者、啟行爲後隊、亞米沙代子亞希以謝統領其軍、"],[4,10,26,"俄蘭子帕結統亞設軍、"],[4,10,27,"以南子亞希拉統拿弗他利軍、"],[4,10,28,"以色列族按其行伍啟行如是、○"],[4,10,29,"摩西謂其外戚、米甸人流珥子何巴曰、我儕今往耶和華所許賜我之地、汝且偕行、我善待爾、蓋耶和華論以色列族、出以嘉言、"],[4,10,30,"何巴曰、我不偕往、將歸故鄉、返我宗族、"],[4,10,31,"摩西曰、爾勿棄我、我於曠野建營、爾知其事、可爲我目、"],[4,10,32,"如與我儕偕行、則耶和華如何施恩於我、我亦如是施爾、○"],[4,10,33,"以色列族離耶和華之山、歷程三日、此三日、耶和華之約匱先行、以擇安處之所、"],[4,10,34,"民啟行時、耶和華之雲、晝覆其上、"],[4,10,35,"約匱移時、摩西曰、耶和華歟、尚其興起、願敵潰散、願憾爾者遁逃、"],[4,10,36,"約匱止時、則曰、耶和華歟、尚其返於以色列億兆、"],[4,11,1,"民發怨言、耶和華聞其惡語而怒、其火燃於民中、燬營邊隅、"],[4,11,2,"民籲摩西、摩西禱於耶和華、火燄隨熄、"],[4,11,3,"其地遂稱曰他備拉、以耶和華之火燃於民中也、○"],[4,11,4,"雜處流氓、貪慾無厭、以色列族亦哭泣曰、誰予我肉食、"],[4,11,5,"我憶在埃及時、不費財而食魚、亦有王瓜、瓠、韭、葱、蒜、"],[4,11,6,"今我精神消減、瑪那而外、別無所見、"],[4,11,7,"夫瑪那狀如芫荽之實、色如珍珠、"],[4,11,8,"民衆四出、各相斂取、或磨以磨、或搗以臼、或煑於鼎、或以作餅、味若和油之食、"],[4,11,9,"夜間露降於營、瑪那隨之而下、"],[4,11,10,"摩西聞民室家、各在帳幕門前哭泣、致耶和華震怒、摩西不悅、"],[4,11,11,"告耶和華曰、何虐待爾僕、不施恩於我、而以治民之任加我、"],[4,11,12,"斯民豈我所孕、豈我所育、爾乃謂我、汝其抱之於懷、猶父之懷乳子、攜至誓許其祖之地、"],[4,11,13,"彼哭於我前云、以肉食我、我何由得肉、以予有衆乎、"],[4,11,14,"治民之任綦重、我不能獨負、"],[4,11,15,"如蒙爾恩、與其待我若此、毋寧殺我、免我遭諸困苦、○"],[4,11,16,"耶和華諭摩西曰、於以色列之耆老中、簡七十人、皆爾夙知其爲民之長老有司、攜至會幕前、與爾偕立、"],[4,11,17,"我將臨而語爾、取爾所感之神、賦之於彼、使其同負治民之任、免爾獨負、"],[4,11,18,"爾語民曰、自潔爲聖、以備明日食肉、蓋耶和華聞爾哭聲云、誰以肉食我、昔在埃及、我儕善矣、故耶和華將賜爾以肉、爾得食之、"],[4,11,19,"非止一日、二日、五日、十日、二十日已也、"],[4,11,20,"必至一月、致由鼻孔噴而出之、爲爾厭惡、蓋爾厭棄寓於爾中之耶和華、哭於其前曰、我何爲出埃及乎、"],[4,11,21,"摩西曰、我偕居之民、步卒六十萬、爾言予之肉食、至於一月、"],[4,11,22,"豈宰羣羊及牛、抑集海中鱗族、以饜之乎、"],[4,11,23,"耶和華曰、耶和華之臂豈短耶、今必見我言之應否、○"],[4,11,24,"摩西出、以耶和華言告民、集民之長老七十人、立於幕之四周、"],[4,11,25,"耶和華乘雲降臨、與摩西言、以感摩西之神、賦於長老、旣已賦之、則感神而言、厥後不復如此、"],[4,11,26,"所錄者中有二人、一名伊利達、一名米達、仍居於營、未適會幕、神旣賦之、則在營中感神而言、"],[4,11,27,"有一少者、趨告摩西曰、伊利達米達在營中、感神而言、"],[4,11,28,"嫩之子約書亞自幼爲摩西從者、曰、我主摩西歟、請禁之、"],[4,11,29,"摩西曰、爾緣我故、有所嫉乎、願耶和華以神賦於民衆、使之感神而言、"],[4,11,30,"摩西及以色列長老、遂返於營、"],[4,11,31,"有風自耶和華而發、使鶉自海而至、散於營之四周、相去約一日之程、距地二肘、"],[4,11,32,"民起捕鶉、永朝永夕、至於明日、獲之少者、尚得十賀梅爾、布於營之四周、"],[4,11,33,"肉在牙間、猶未咀嚼、耶和華怒之、降重災以擊之、"],[4,11,34,"其地遂稱曰基博羅哈他瓦、因貪欲之人葬於彼也、"],[4,11,35,"民自基博羅哈他瓦啟行、至哈洗錄居焉、"],[4,12,1,"昔摩西娶古實女、米利暗亞倫非之、"],[4,12,2,"曰、耶和華豈第語摩西、而不語我儕乎、斯言耶和華聞之、"],[4,12,3,"摩西秉性温柔、勝於世之億兆、"],[4,12,4,"耶和華猝諭摩西亞倫米利暗曰、爾曹出至會幕、三人乃出、"],[4,12,5,"耶和華乘雲柱臨於幕門、召亞倫米利暗、二人乃前、"],[4,12,6,"耶和華曰、其聽我言、爾中如有先知、我必藉異象而顯見、或夢中諭之、"],[4,12,7,"惟於我僕摩西、則不然、彼盡忠於我家、"],[4,12,8,"故我與之晤言、明以相告、不以隱語、彼亦覩耶和華之容、爾曹非之、曷不懼乎、"],[4,12,9,"耶和華怒之而去、"],[4,12,10,"雲離會幕、米利暗患癩、色皎如雪、亞倫顧之、見其患癩、"],[4,12,11,"乃謂摩西曰、我儕愚昧、干厥咎戾、請吾主勿加罪、"],[4,12,12,"勿使彼若已死之人、出母胎體已半朽者、"],[4,12,13,"摩西籲耶和華曰、上帝歟、其醫之、"],[4,12,14,"耶和華曰、若彼父唾於其面、豈不蒙羞七日乎、必禁之營外、歷至七日、然後可導之入、"],[4,12,15,"遂禁米利暗營外、至於七日、民不啟行、待其復入、"],[4,12,16,"厥後離哈洗錄、在巴蘭野建營、"],[4,13,1,"耶和華諭摩西曰、"],[4,13,2,"於支派中、各簡牧伯一人、以窺迦南地、卽我所錫以色列族者、"],[4,13,3,"摩西遵耶和華命、自巴蘭野遣之、所遣者、悉屬以色列族長、"],[4,13,4,"其名如左、屬流便支派、撒刻子沙母亞、"],[4,13,5,"屬西緬支派、何利子沙法、"],[4,13,6,"屬猶大支派、耶孚尼子迦勒、"],[4,13,7,"屬以薩迦支派、約色子以迦、"],[4,13,8,"屬以法蓮支派、嫩之子何西阿、"],[4,13,9,"屬便雅憫支派、拉孚子帕提、"],[4,13,10,"屬西布倫支派、梭底子迦疊、"],[4,13,11,"約瑟之裔、屬瑪拿西支派、穌西子迦底、"],[4,13,12,"屬但之支派、基瑪利子亞米利、"],[4,13,13,"屬亞設支派、米迦勒子西帖、"],[4,13,14,"屬拿弗他利支派、縛西子拿比、"],[4,13,15,"屬迦得支派、瑪基子臼利、"],[4,13,16,"摩西所遣以窺地者、卽斯人也、嫩之子何西阿、摩西易其名爲約書亞、"],[4,13,17,"摩西遣十二人以窺迦南、曰、自其南境而往、入彼山地、"],[4,13,18,"察其土壤、觀其居民、強弱衆寡、"],[4,13,19,"其處之所、或美或惡、其居之邑、或類營壘、或類城垣、"],[4,13,20,"其土壤、或瘠或腴、有無林木、宜強乃志、彼地之菓、可攜而歸、其時乃葡萄初稔之際、"],[4,13,21,"其人遂往窺地、自尋野至利合、及哈馬之道、"],[4,13,22,"轉而南向、至希伯崙、此邑之建、前於埃及之瑣安七年、在彼有亞衲族亞希幔、示篩、撻買、"],[4,13,23,"至以實各谷、在彼斫葡萄枝、上具葡萄一穗、"],[4,13,24,"故其地名曰以實各谷、"],[4,13,25,"四十日後、窺地而返、"],[4,13,26,"至巴蘭野之加低斯、見摩西亞倫、及以色列會衆、告以諸事、以厥土之菓示之、"],[4,13,27,"謂摩西曰、爾遣我所往之地、我已至焉、果流乳蜜、此其菓也、"],[4,13,28,"雖然、居民強悍、其邑廣大、俱有城垣、我見亞衲族於彼、"],[4,13,29,"亞瑪力族居南方、赫人、耶布斯人、亞摩利人居山地、迦南人瀕海與約但河居焉、"],[4,13,30,"迦勒於摩西前、慰安民曰、我儕能克其地、其往取之、"],[4,13,31,"偕行者曰、彼強於我、不可往攻、"],[4,13,32,"遂毀所窺之地、謂以色列族曰、我所窺之地、吞噬居民、我所見之人、軀幹修偉、"],[4,13,33,"在彼見偉人亞衲族、我自較之、形猶蟿蟲、彼之視我亦若是、"],[4,14,1,"會衆大聲號呼、是夜咸哭、"],[4,14,2,"以色列族怨摩西亞倫、僉曰、願我亡於埃及、或殞於斯野爲幸、"],[4,14,3,"耶和華何爲導我至此、使我仆於刃、妻孥被虜、我歸埃及、不猶美乎、"],[4,14,4,"遂相議曰、莫若立帥、以歸埃及、"],[4,14,5,"摩西亞倫俯伏於以色列會衆前、"],[4,14,6,"窺其地者、間有嫩之子約書亞、耶孚尼子迦勒、自裂其衣、"],[4,14,7,"告以色列會衆曰、我所經行、窺察之地、厥土甚美、"],[4,14,8,"流乳與蜜、如耶和華悅我、必導我至其地、以之錫我、"],[4,14,9,"勿叛耶和華、勿畏其地之民、彼無扞衞、必爲我食、耶和華與我偕、勿懼之、"],[4,14,10,"會衆命擊以石、耶和華之榮光、顯於會幕、在以色列衆前、○"],[4,14,11,"耶和華諭摩西曰、斯民輕我、將至何時、我於其中行斯異蹟、而彼仍弗信我、將至何時、"],[4,14,12,"我必降疫癘以擊之、絕之於其業、使爾後裔爲國、較彼尤大且強、"],[4,14,13,"摩西對耶和華曰、如是、埃及人必聞其事、蓋爾昔施大能、率斯民出其中、"],[4,14,14,"埃及人必以告斯土之民、彼已聞爾耶和華居以色列族中、因爾顯見、爲衆目擊、爾雲止於其上、晝導以雲柱、夜導以火柱、"],[4,14,15,"今爾若殲斯民、如戮一人、嘗聞爾名之國必曰、"],[4,14,16,"耶和華不能導斯民、入所誓許之地、故滅之於野、"],[4,14,17,"茲求我主、施厥大力、如昔所言曰、"],[4,14,18,"耶和華遲於發怒、富有恩惠、宥愆赦過、惟當罰者、必不義之、以父之罪、加諸子孫、至三四世、"],[4,14,19,"今求依爾鴻慈、宥民之罪、如昔宥之、自出埃及、迄於今日、"],[4,14,20,"耶和華曰、我從爾言、而行赦宥、"],[4,14,21,"雖然、我指我生、及我榮必充於天下而誓、"],[4,14,22,"斯民旣於埃及曁曠野、見我榮光、及所行之異蹟、而猶試我、至於十次、不聽我言、"],[4,14,23,"必不得見我所誓於厥祖之地、凡輕視我者、皆不得見之、"],[4,14,24,"惟我僕迦勒、性質殊異於衆、專從乎我、所往之地、必導之入、其裔據以爲業、"],[4,14,25,"今亞瑪力與迦南人、居於斯谷、詰旦爾其旋返、道由紅海、而往曠野、○"],[4,14,26,"耶和華諭摩西亞倫曰、"],[4,14,27,"此惡會衆、我忍之將至何時、以色列族怨我之言、我聞之矣、"],[4,14,28,"當告之曰、耶和華云、我指己生以誓、必依爾言而行、"],[4,14,29,"爾尸必僵於斯野、爾中見核而怨我者、自二十歲以上、"],[4,14,30,"俱不得入、我誓賜爾以居之地、惟耶孚尼子迦勒、及嫩之子約書亞入之、"],[4,14,31,"爾之幼穉、爾言將被擄者、我必導入、得識爾所蔑視之土、"],[4,14,32,"惟爾之尸、必僵於野、"],[4,14,33,"爾之子女、緣爾狥欲、必負其罪、流離於野、歷四十年、迨爾尸骸消滅、"],[4,14,34,"爾窺厥地、歷四十日、今將以日易年、爾負其罪、歷四十載、使知我離逖焉、"],[4,14,35,"我耶和華旣言之、必行之於此惡會衆、集攻我者、俾其亡於斯野、盡皆消滅、"],[4,14,36,"摩西所遣窺地之人、返而毀之、致會衆怨摩西、"],[4,14,37,"咸遘疫癘、死於耶和華前、"],[4,14,38,"惟其中二人、嫩之子約書亞、耶孚尼子迦勒生存、"],[4,14,39,"摩西以此告以色列族、民憂甚、"],[4,14,40,"夙興登山巔、曰、我儕有罪、今集於斯、願往耶和華所許之地、"],[4,14,41,"摩西曰、奚違耶和華命、此行不利、"],[4,14,42,"耶和華不在爾中、勿往、恐爲敵所敗、"],[4,14,43,"亞瑪力及迦南人在爾前、爾必仆於其刃、緣爾違逆、不從耶和華、耶和華必不偕爾、"],[4,14,44,"民擅登山巔、惟摩西與耶和華約匱未離營、"],[4,14,45,"亞瑪力人、及居山之迦南人、下而擊之、至於何珥瑪、"],[4,15,1,"耶和華諭摩西曰、"],[4,15,2,"告以色列族云、旣至我所賜爾以居之地、"],[4,15,3,"欲以牛羊奉於耶和華爲火祭、卽燔祭、或他祭、以之償願、或以爲樂獻祭、或屆節期、以爲馨香、奉於耶和華、"],[4,15,4,"則獻祭者、必取細麪伊法十分之一、和油一欣四分之一、爲素祭、奉於耶和華、"],[4,15,5,"並爲各羔、取酒一欣四分之一、爲灌祭、與燔祭、或他祭同獻、"],[4,15,6,"如獻牡綿羊、則必取細麪伊法十分之二、和油一欣三分之一、爲素祭、"],[4,15,7,"酒一欣三分之一、爲灌祭、以爲馨香、奉於耶和華、"],[4,15,8,"如以牡犢爲燔祭、或他祭、或以之償願、或爲酬恩祭、以獻耶和華、"],[4,15,9,"則必取細麪伊法十分之三、和油一欣之半、爲素祭、與牡犢同獻、"],[4,15,10,"酒一欣之半、爲灌祭、以爲馨香之火祭、奉於耶和華、"],[4,15,11,"每獻牡犢、牡綿羊、綿羊羔、山羊羔、所備者必如是、"],[4,15,12,"依所獻之數而備之、"],[4,15,13,"凡生於本土者、欲獻火祭於耶和華、以爲馨香、必遵是例、"],[4,15,14,"外人之旅於爾中、或歷世與爾偕居者、欲以馨香之火祭獻於耶和華、亦必如是而行、"],[4,15,15,"凡爾會衆、及旅於爾中者、典章相同、歷世弗替、在耶和華前、爾衆若何、賓旅亦若何、"],[4,15,16,"爾及寓於爾中之賓旅、俱循一律一例、○"],[4,15,17,"耶和華諭摩西曰、"],[4,15,18,"告以色列族云、爾至我所導入之土、"],[4,15,19,"旣食其所產、必以舉祭獻於耶和華、"],[4,15,20,"當取初稔之麥、爲屑作餅、以爲舉祭、與舉禾場之穀一例、"],[4,15,21,"必取初稔之麥爲屑、以爲舉祭、獻於耶和華、歷世弗替、○"],[4,15,22,"爾或誤犯、不從耶和華所諭摩西之命、"],[4,15,23,"卽自昔迄今、及厥後歷世所諭之命、"],[4,15,24,"或有所犯、而會衆不知、則必獻牡犢一、爲燔祭、以爲馨香、奉於耶和華、與其素祭、灌祭、悉循常例、亦獻牡山羊一、爲贖罪祭、"],[4,15,25,"祭司遂爲以色列會衆贖罪、俾蒙赦宥、因係誤犯、且爲其咎、已獻火祭、及贖罪祭於耶和華、"],[4,15,26,"如是、則以色列會衆、及旅於爾中者、俱蒙赦宥、緣其所犯、出於無知、"],[4,15,27,"如一人誤干罪戾、則必獻一歲之牝山羊、爲贖罪祭、"],[4,15,28,"祭司當在耶和華前、爲誤犯者贖罪、俾蒙赦宥、"],[4,15,29,"凡誤干罪戾、無論生於以色列本土、或旅於其中者、俱爲一例、"],[4,15,30,"如其故犯、乃褻凟耶和華、不論宗族賓旅、必絕於民中、"],[4,15,31,"旣藐視耶和華之言、干犯其命、則必見絕、厥罪歸之、○"],[4,15,32,"以色列族居野時、遇人於安息日採薪、"],[4,15,33,"攜之至摩西亞倫及會衆前、"],[4,15,34,"囚之於獄、因未定擬何以處之、"],[4,15,35,"耶和華諭摩西曰、其人必殺勿赦、會衆當於營外擊之以石、"],[4,15,36,"遂攜出營外、以石擊斃之、遵耶和華所諭摩西之命、○"],[4,15,37,"耶和華諭摩西曰、"],[4,15,38,"當令以色列族、衣邊之下作繸、各繸之上、緣以藍帶、歷世弗替、"],[4,15,39,"爾觀其繸、可憶耶和華誡、而遵行之、不致隨爾心目、狥欲如故、"],[4,15,40,"宜憶我誡、而爲聖於上帝、"],[4,15,41,"我乃爾之上帝耶和華、導爾出埃及、爲爾之上帝、我乃耶和華、爾之上帝也、"],[4,16,1,"利未之裔、哥轄孫、以斯哈子可拉、流便之裔、以利押子大坍、亞比蘭、比勒子安、"],[4,16,2,"與以色列會衆之牧伯、卽有名譽之議士、二百五十人、集攻摩西亞倫、"],[4,16,3,"曰、爾逾分矣、會衆盡皆爲聖、耶和華亦在其中、爾奚自大、欲超軼於耶和華之會衆乎、"],[4,16,4,"摩西聞而俯伏、"],[4,16,5,"語可拉及其黨曰、詰朝、耶和華必明示爾曹、誰屬之、誰爲聖、俾進其前、彼所簡者、得以近之、"],[4,16,6,"爾可拉及爾黨、當如是行、"],[4,16,7,"明日執鼎盛火、置香於耶和華前、耶和華所簡者、卽以爲聖、汝利未裔逾分矣、"],[4,16,8,"又語可拉曰、汝利未裔、宜聽我言、"],[4,16,9,"以色列之上帝、區別爾曹於會衆、使近其前、服役於耶和華幕、立會衆前、以爲供役、其事豈微細哉、"],[4,16,10,"旣使爾及兄弟利未裔、近於其前、爾猶覬覦祭司之職乎、"],[4,16,11,"爾及爾黨之集、乃攻耶和華、亞倫何人、致爾怨之、"],[4,16,12,"摩西使人召以利押子大坍、亞比蘭、對曰、不往、"],[4,16,13,"爾攜我儕出流乳與蜜之地、欲殺於野、其事豈微細哉、尚欲自立、爲我君乎、"],[4,16,14,"爾未導我至流乳與蜜之地、未嘗賜我田疇、及葡萄園、豈欲抉斯衆之目乎、我不往、"],[4,16,15,"摩西怒甚、謂耶和華曰、勿眷顧其所獻、我未取其一驢、害其一人、"],[4,16,16,"乃謂可拉曰、明日爾與爾黨、偕亞倫詣耶和華前、"],[4,16,17,"人各執鼎、置香於中、共二百五十鼎、爾及亞倫、亦各執鼎、詣耶和華前、"],[4,16,18,"遂各執鼎、燃火置香、與摩西亞倫立於會幕門、"],[4,16,19,"可拉集會衆、至幕門攻之、耶和華之榮光顯見、會衆目擊、○"],[4,16,20,"耶和華諭摩西亞倫曰、"],[4,16,21,"爾其離此會衆、俟我滅之於俄頃、"],[4,16,22,"二人俯伏曰、上帝、世人諸神之上帝歟、曷因一人干罪、而怒及會衆乎、"],[4,16,23,"耶和華諭摩西曰、"],[4,16,24,"爾命會衆、離可拉大坍亞比蘭幕之四周、"],[4,16,25,"摩西乃起、往大坍亞比蘭所、以色列長老隨其後、"],[4,16,26,"摩西謂會衆曰、離此惡黨之幕、勿捫其物、恐與其罪、與之偕亡、"],[4,16,27,"衆遂離可拉大坍亞比蘭幕之四周、大坍亞比蘭出、立於幕門、妻孥偕之、"],[4,16,28,"摩西曰、耶和華遣我行此、非由我意、爾可知焉、"],[4,16,29,"倘彼如常而終、所遇與衆無異、則知耶和華未嘗遣我、"],[4,16,30,"倘耶和華創行新事、使地張口、吞噬其衆、及凡所有、生墮陰府、則知其人藐視耶和華矣、"],[4,16,31,"言竟、其下土壤坼裂、"],[4,16,32,"地張厥口、吞噬可拉徒黨、與其眷屬什物、"],[4,16,33,"彼曁所有、悉生墮於陰府、地復合之、致彼絕於會中、"],[4,16,34,"以色列族在於四周、聞其號呼而遁、曰、恐我儕亦爲地所吞、"],[4,16,35,"火自耶和華出、燬其焚香者二百五十人、○"],[4,16,36,"耶和華諭摩西曰、"],[4,16,37,"告祭司亞倫子以利亞撒云、取鼎於火中、傾其爇炭於他處、蓋鼎爲聖、"],[4,16,38,"人雖犯罪、自殞厥命、然其鼎嘗奉於耶和華、故爲聖、當取而擣之成片、以包祭壇、爲以色列族之鑑戒、"],[4,16,39,"祭司以利亞撒遂取奉火見燬者之銅鼎、擣之以包祭壇、"],[4,16,40,"爲以色列族之記誌、以示外人非亞倫之裔者、不得近而焚香於耶和華前、恐遭厥害、若可拉及其黨然、遵耶和華所諭摩西之命、○"],[4,16,41,"詰旦、以色列會衆怨摩西亞倫曰、耶和華之民、爲爾所戮、"],[4,16,42,"會衆集攻摩西亞倫時、瞻望會幕、爲雲所覆、耶和華之榮光顯見、"],[4,16,43,"摩西亞倫至會幕前、"],[4,16,44,"耶和華諭摩西曰、"],[4,16,45,"離此會衆、我將滅之於俄頃、二人俯伏、"],[4,16,46,"摩西告亞倫曰、耶和華震怒、疫癘已起、爾當執鼎、取壇上之火、置香、急詣會衆、代爲贖罪、"],[4,16,47,"亞倫循摩西言取鼎、趨詣會中、疫癘已起、"],[4,16,48,"乃立於生者死者間、焚香爲民贖罪、疫癘始弭、"],[4,16,49,"緣可拉事而殞者外、遘疫而死者、計一萬四千七百人、"],[4,16,50,"疫癘旣止、亞倫反見摩西於會幕門、"],[4,17,1,"耶和華諭摩西曰、"],[4,17,2,"爾諭以色列人、由之取杖、按宗族之牧伯、取杖十二、宗族各一、書名其上、"],[4,17,3,"亞倫名書於利未族之杖、牧伯各有其杖、"],[4,17,4,"以杖置於會幕法匱前、我所蒞臨之處、"],[4,17,5,"我所簡者、其杖必萌芽、使以色列族怨爾之言息焉、"],[4,17,6,"摩西以此言告以色列人、諸牧伯各付其杖、循其宗族、計十有二、亞倫之杖在其中、"],[4,17,7,"摩西置諸法幕、在耶和華前、"],[4,17,8,"翌日、摩西入法幕、見亞倫之杖、屬利未族者、萌芽舒蕊、結杏已稔、"],[4,17,9,"摩西取杖於耶和華前、攜至以色列衆、彼旣觀之、各取其杖、"],[4,17,10,"耶和華諭摩西曰、反亞倫杖於法匱前、存之爲誌、使此叛逆之輩、息怨於我、免其隕沒、"],[4,17,11,"摩西遵耶和華命而行、○"],[4,17,12,"以色列族謂摩西曰、我將死矣、我其亡乎、我悉亡矣、"],[4,17,13,"凡近耶和華之幕者死、我將皆亡乎、"],[4,18,1,"耶和華諭亞倫曰、人若干犯聖所、爾及子孫宗族、必負其罪、爾及子孫、爲祭司而溺職、亦必負其罪、"],[4,18,2,"可攜爾兄弟、卽屬汝祖利未支派者、偕汝而供役事、惟爾及子孫、宜在法幕前、"],[4,18,3,"彼爲爾服役、且守會幕、惟不可近聖所之器皿及壇、免其與爾俱致死亡、"],[4,18,4,"彼偕爾而守會幕、供其役事、外人勿近乎爾、"],[4,18,5,"聖所及壇、爾當恪守、俾以色列族免遭震怒、"],[4,18,6,"我於以色列族中、已取爾兄弟利未人歸耶和華、今賜於汝、以供會幕役事、"],[4,18,7,"爾及子孫、宜守祭司之職、壇前㡘內、供其役事、我以祭司之職畀爾、外人近前、必致之死、○"],[4,18,8,"耶和華諭亞倫曰、所獻之舉祭、卽以色列族區別爲聖之物、我付爾守之、緣爾受膏、是物歸爾、爰及子孫、著爲永例、"],[4,18,9,"凡奉我之素祭、贖罪祭、補過祭、其中不焚以火者、皆爲至聖、必歸於爾、爰及子孫、"],[4,18,10,"旣爲至聖之物、於爾爲聖、諸丁男可食之、"],[4,18,11,"以色列族所獻舉祭搖祭之禮物、咸爲爾有、我賜於汝、爰及子女、家中凡爲潔者、可得而食、著爲永例、"],[4,18,12,"油與葡萄酒、及穀之嘉者、所獻於耶和華初稔之物、我以錫爾、"],[4,18,13,"其地初稔之物、所獻於耶和華者、俱歸諸爾、家中凡爲潔者、可得而食、"],[4,18,14,"以色列族區別之物、皆必歸爾、"],[4,18,15,"凡初胎男子、首生牡畜、奉於耶和華者、皆必歸爾、惟首生之男必贖、首生不潔之畜亦必贖、"],[4,18,16,"其中所當贖者、誕已彌月贖之、其價依爾所估、五舍客勒、循聖所權衡、一舍客勒、卽二十季拉、"],[4,18,17,"首生之牛、綿羊、山羊、俱爲聖物、毋贖之、以其血灑於壇、焚其脂、以爲馨香之火祭、奉於耶和華、"],[4,18,18,"厥肉歸爾、與搖腔右腿同、"],[4,18,19,"凡以色列族所獻聖物之中、奉於耶和華之舉祭、我錫於爾、及爾子女、著爲永例、此於耶和華前、爲爾及裔所立之鹽約、"],[4,18,20,"耶和華諭亞倫曰、爾於以色列人境內、不得有產有業、在以色列族中、我爲爾之業、爾之產、○"],[4,18,21,"我於以色列族之土產、什取其一、以錫利未人、爲其供役會幕之值、"],[4,18,22,"自是以後、以色列族不可近會幕、免其負罪而死、"],[4,18,23,"利未人供役於會幕、如有干犯、必負其罪、著爲永例、歷世弗替、於以色列族中、不得業產、"],[4,18,24,"以色列人什輸其一、獻於耶和華爲舉祭者、我賜於利未人爲業、故曰、彼不得業於以色列中也、○"],[4,18,25,"耶和華諭摩西曰、"],[4,18,26,"告利未人云、爾得以色列族所輸之什一、我所錫爾爲業者、必於其中、復取什一、以爲舉祭、獻於耶和華、"],[4,18,27,"爾之舉祭、視爲爾曹禾場之穀、酒醡之汁、"],[4,18,28,"爾自以色列族所得之什一、當復取其什一、獻於耶和華、使獻耶和華之舉祭、歸祭司亞倫、"],[4,18,29,"所得禮物、必取其嘉者、區別爲聖、獻於耶和華爲舉祭、"],[4,18,30,"宜命利未人曰、旣舉而獻其嘉者、必視爲禾場酒醡之所出、"],[4,18,31,"爾與眷屬、隨在可食、蓋爾供役於會幕、得此爲值、"],[4,18,32,"旣舉而獻其嘉者、則不負罪、勿凟以色列之聖物、免致死亡、"],[4,19,1,"耶和華諭摩西亞倫曰、"],[4,19,2,"耶和華所命之法典、今示於爾、宜令以色列族、牽牝犢一、其色維騂、純全無疵、未嘗負軛者詣爾、"],[4,19,3,"付於祭司以利亞撒、牽出營外、宰於其前、"],[4,19,4,"祭司以利亞撒以指取血、灑於會幕前凡七、"],[4,19,5,"焚犢於祭司前、皮肉血矢、悉焚之、"],[4,19,6,"祭司取香柏、牛膝草、絳色綫、投諸焚犢之火、"],[4,19,7,"祭司當澣衣濯身、而後入營、其蒙不潔、迨夕乃免、"],[4,19,8,"焚犢者當澣衣濯身、其蒙不潔、迨夕乃免、"],[4,19,9,"潔者必取犢灰、置於營外潔地、和爲去汚之水、爲以色列族存之、此亦贖罪之祭也、"],[4,19,10,"取犢灰者、當澣厥衣、其蒙不潔、迨夕乃免、此乃以色列族、及旅於其中者之永例也、"],[4,19,11,"凡捫人尸、必蒙不潔、歷至七日、"],[4,19,12,"迨及三日、必以斯水自滌、歷至七日則潔、若三日不自滌、則七日不爲潔、"],[4,19,13,"凡捫死者之尸、而不自滌、玷耶和華之幕、必絕於以色列中、去汚之水未灑其身、必爲不潔、其汚仍存、"],[4,19,14,"人死於幕、有定例焉、凡入此幕、或在幕中者、必蒙不潔、歷至七日、"],[4,19,15,"凡開啟之器、未覆以蓋者、亦蒙不潔、"],[4,19,16,"在野見殺於刃者、或自斃之尸、或人骨、或荒塚、捫之者必蒙不潔、歷至七日、"],[4,19,17,"當爲不潔者、取所焚贖罪祭之灰、置於器中、加以活水、"],[4,19,18,"必潔者一人、浸牛膝草於水中、灑幕與其諸器、及在幕中之衆、與捫見殺者自斃者之尸、捫骨捫塚者、"],[4,19,19,"三日及七日、潔者必灑不潔者、至七日、使之成潔、其人澣衣濯身、迨夕乃潔、"],[4,19,20,"人蒙不潔、而不自滌、玷耶和華聖所、必絕於民中、去汚之水未灑其身、必爲不潔、"],[4,19,21,"凡灑去汚之水、當澣厥衣、凡捫去汚之水、必蒙不潔、迨夕乃免、著爲永例、"],[4,19,22,"蒙不潔者所捫之物、皆爲不潔、捫其物者、亦蒙不潔、迨夕乃免、"],[4,20,1,"正月以色列會衆至尋野、居於加低斯、米利暗死、葬於彼、"],[4,20,2,"會衆無水、集攻摩西亞倫、"],[4,20,3,"與摩西爭曰、昔我兄弟死於耶和華前、我儕甚願與之偕亡、"],[4,20,4,"曷導耶和華之會衆、至斯曠野、使我與牲畜悉死於此、"],[4,20,5,"奚令我出埃及、至此惡地、無田可種、不產無花果、與葡萄石榴、亦無水可飲、"],[4,20,6,"摩西亞倫離會衆、至會幕門俯伏、耶和華之榮光顯見、"],[4,20,7,"耶和華諭摩西曰、"],[4,20,8,"爾其執杖、與汝兄亞倫集會衆、於其前命磐出水、必使水出於磐、遍飲會衆、及厥牲畜、"],[4,20,9,"摩西遵命、取杖於耶和華前、"],[4,20,10,"與亞倫集會衆於磐前、摩西曰、爾叛逆之輩聽之、我爲爾取水於磐乎、"],[4,20,11,"摩西舉杖擊磐者二、水卽汨汨其來、會衆羣畜共飲焉、"],[4,20,12,"耶和華諭摩西亞倫曰、汝不我信、不尊我爲聖於以色列族前、不得導斯衆入我所賜之地、"],[4,20,13,"以色列族與耶和華爭、致耶和華顯爲聖於其中、故斯水稱曰米利巴、○"],[4,20,14,"摩西自加低斯遣使詣以東王曰、爾之兄弟以色列人云、我儕遭遇多艱、爾所知也、"],[4,20,15,"我祖往埃及、居彼日久、埃及人虐待我祖、爰及我儕、"],[4,20,16,"我呼籲耶和華、蒙其垂聽、遣使導我出埃及、今在加低斯、爾國之疆隅也、"],[4,20,17,"請容我過爾地、我不越田畝、不入葡萄園、不飲井水、行由大道、不偏於左、不偏於右、以過爾境、"],[4,20,18,"以東人對曰、勿過我境、免我執刃、出而攻爾、"],[4,20,19,"以色列族曰、我行由大道、如我與牲畜飲爾之水、必償厥值、不圖其他、第欲徒行、以過爾境、"],[4,20,20,"曰、爾毋過焉、以東王率其羣衆、大力以禦之、"],[4,20,21,"如是以東不許以色列族過其境、以色列族遂轉離之、○"],[4,20,22,"以色列會衆自加低斯啟行、至何珥山、"],[4,20,23,"山在以東之邊隅、耶和華諭摩西亞倫曰、"],[4,20,24,"昔在米利巴水、爾曹逆我命、故亞倫必歸其祖、不得入我所賜以色列人之地、"],[4,20,25,"當攜亞倫及其子以利亞撒、陟何珥山、"],[4,20,26,"解亞倫之衣、以衣其子、亞倫必沒、"],[4,20,27,"摩西遵耶和華命而行、三人陟山、會衆目擊、"],[4,20,28,"摩西解亞倫之衣、以衣其子、亞倫死於山巔、摩西以利亞撒乃下、"],[4,20,29,"以色列會衆見亞倫死、爲之哀哭三旬、"],[4,21,1,"居南方之迦南人亞拉得王、聞以色列族由亞他林道而進、則與之戰、虜其數人、"],[4,21,2,"以色列族指耶和華許願曰、若以此民付於我手、我必盡滅其邑、"],[4,21,3,"耶和華應以色列族所求、以迦南人付之、遂盡滅厥衆、及其邑、故其地稱曰何珥瑪、○"],[4,21,4,"以色列族自何珥山啟行、由紅海道、繞以東地、因路艱難、民心恇怯、"],[4,21,5,"怨上帝及摩西曰、奚導我出埃及、使死於野、無糧無水、所食淡薄、我心厭之、"],[4,21,6,"耶和華遣火蛇、入民中嚙之、以色列族多死亡者、"],[4,21,7,"民就摩西曰、我怨耶和華及爾、干厥罪戾、請祈耶和華、爲我驅蛇、摩西爲之祈、"],[4,21,8,"耶和華諭摩西曰、爾造火蛇之象、懸之於竿、被嚙者望之而得生、"],[4,21,9,"摩西遂造銅蛇、懸之於竿、爲蛇所嚙者、觀之而得生、○"],[4,21,10,"以色列族啟行、建營於阿伯、"],[4,21,11,"自阿伯啟行、建營於以耶亞巴琳、在摩押野之東、"],[4,21,12,"由此而往、建營於撒烈谷、"],[4,21,13,"再往、建營於亞嫩溪東、其溪在野、源出亞摩利境、原爲摩押及亞摩利之界、"],[4,21,14,"耶和華戰紀曰、蘇法之哇哈伯及亞嫩谷、"],[4,21,15,"諸谷之地勢、斜趨亞珥鄉、附近摩押界、"],[4,21,16,"由此而往、至於比珥、在彼有井、昔耶和華諭摩西曰、汝集人民、我飲以水、"],[4,21,17,"時、以色列族謳歌曰、井泉湧兮、爾曹詠之、"],[4,21,18,"惟此井兮、牧伯鑿之、民之長者、以梃以杖掘之、"],[4,21,19,"厥後離野、往瑪他拿、自瑪他拿往拿哈列、自拿哈列往巴末、"],[4,21,20,"自巴末往摩押郊之谷、至毘斯迦山巔、與野相望之處、○"],[4,21,21,"以色列族遣使詣亞摩利王西宏曰、"],[4,21,22,"請容我過爾地、我不偏入田畝、及葡萄園、不飲井水、行由大道、以過爾境、"],[4,21,23,"西宏不許、乃集厥民、往於曠野、至雅雜、與以色列族戰、"],[4,21,24,"以色列族以刃擊之、據有其地、自亞嫩迄於雅博溪、至亞捫而止、蓋亞捫族之邊境險固、"],[4,21,25,"亞摩利人之邑希實本、及其鄉里、以色列族悉取之、居處其中、"],[4,21,26,"昔亞摩利王西宏、與摩押先王戰、徧取斯地、至亞嫩溪、希實本乃其都也、"],[4,21,27,"詩人詠之曰、希實本、爾其詣之、西宏邑、願建築之、"],[4,21,28,"火自希實本而出、焰自西宏邑而發、燬摩押之亞珥、及亞嫩崇邱之牧伯、"],[4,21,29,"摩押其有禍兮、基抹之民其將亡兮、厥子遁逃、厥女見攘、爲亞摩利王西宏所獲、"],[4,21,30,"我已射之、希實本危亡、爰及底本、我已滅之、至於挪法、迄米底巴、○"],[4,21,31,"於是以色列族、居亞摩利人之地、"],[4,21,32,"摩西遣人窺察雅謝、遂取其鄉里、驅遂亞摩利人、"],[4,21,33,"以色列族旋返、往巴珊道、巴珊王噩率衆出而攻之、在以得來與之戰、"],[4,21,34,"耶和華諭摩西曰、毋畏之、我以斯王、及其人民土地、咸付爾手、汝待遇之、如都希實本之亞摩利王西宏然、"],[4,21,35,"遂擊王、及其子其民、靡有孑遺、據有其地、"],[4,22,1,"以色列族啟行、建營於摩押平原、約但之東、近耶利哥、○"],[4,22,2,"以色列族於亞摩利人所行之事、西撥子巴勒目擊、"],[4,22,3,"摩押人又緣斯民衆多、恐懼憂戚、"],[4,22,4,"告米甸長老曰、此衆將吞我四方、如牛嚙田野之草、時、西撥子巴勒爲摩押王、"],[4,22,5,"遣使往比珥子巴蘭本族之地、卽河濱之毘奪、召之曰、有民出自埃及、周遍於地、實逼處此、"],[4,22,6,"斯民強甚、我非其敵、請汝至此、爲我詛之、庶我擊之獲勝、驅之出境、蓋我素知爾所祝者、則必受祝、爾所詛者、則必受詛、"],[4,22,7,"摩押及米甸長老、手執卜筮之值、往見巴蘭、以巴勒言告之、"],[4,22,8,"巴蘭曰、今夕宿此、待聆耶和華之諭、以復於爾、摩押使臣、遂與巴蘭同處、"],[4,22,9,"上帝臨格、問巴蘭曰、偕爾者爲誰、"],[4,22,10,"對曰、摩押王西撥子巴勒、遣人就我曰、"],[4,22,11,"有民出自埃及、周遍於地、願爾式臨、爲我詛之、庶可戰而驅之、"],[4,22,12,"上帝曰、爾勿偕往、亦勿詛民、蓋斯民受祝矣、"],[4,22,13,"巴蘭夙興、告巴勒使臣曰、汝返故土、蓋耶和華不許我偕往、"],[4,22,14,"摩押使臣乃歸、告巴勒曰、巴蘭不與我偕來、"],[4,22,15,"巴勒又遣使臣、較之於前、位尊且衆、"],[4,22,16,"旣至、謂巴蘭曰、西撥子巴勒有言、爾勿有所扞格、而不我臨、"],[4,22,17,"我將使爾尊顯、凡爾所言、我必依行、請爾蒞臨、以詛斯民、"],[4,22,18,"巴蘭告其臣曰、卽使巴勒以盈室之金銀饋我、無論事之鉅細、不可逾越我上帝耶和華之命、"],[4,22,19,"今夕爾姑宿此、俟耶和華更有所諭、"],[4,22,20,"是夜上帝臨格、諭巴蘭曰、如其人來招、姑與偕往、然我所諭、汝必遵循、"],[4,22,21,"巴蘭夙興備驢、與摩押使臣偕往、"],[4,22,22,"上帝因其往而怒、耶和華之使者立於途以禦之、巴蘭乘驢、二役相隨、"],[4,22,23,"驢見使者拔刃立於途、遂離其道、入於田間、巴蘭策驢、使歸於道、"],[4,22,24,"耶和華之使者立於狹路、在二葡萄園間、左右有垣、"],[4,22,25,"驢見之、衝突垣側、擠傷巴蘭之足於垣、又策之、"],[4,22,26,"耶和華之使者前往、立於途之隘處、左右無地轉移、"],[4,22,27,"驢見使者、則伏地、巴蘭怒、以杖策之、"],[4,22,28,"耶和華使驢啟口、謂巴蘭曰、我於爾何爲、致爾策我者三、"],[4,22,29,"巴蘭曰、汝戲我、願有刃在我手、我必殺汝、"],[4,22,30,"驢曰、我非爾驢、爾畢生所乘者乎、我素有是行否、曰、無之、"],[4,22,31,"耶和華明巴蘭目、乃見使者拔刃立於途、遂俯首伏地、"],[4,22,32,"使者曰、三策爾驢何也、爾所行者逆我、故我出以禦爾、"],[4,22,33,"驢見我而避者三、不然、我已殺爾、使驢得生、"],[4,22,34,"巴蘭曰、獲罪矣、不識爾立途中以禦我、爾若不悅我往、我將返、"],[4,22,35,"曰、姑與其人偕往、惟我所諭、爾必言之、於是巴蘭與巴勒使臣偕往、"],[4,22,36,"巴勒聞其至、則往國之邊界、亞嫩溪濱、摩押都以迎之、"],[4,22,37,"巴勒謂巴蘭曰、我非特遣使召爾乎、爾曷不至、我豈不能舉爾致尊顯乎、"],[4,22,38,"巴蘭曰、我今已至、我豈能自擅而言、上帝授我之言、我必言之、"],[4,22,39,"巴蘭與巴勒偕行、至基列胡瑣、"],[4,22,40,"巴勒宰牛羊、饋於巴蘭、及與偕之使臣、"],[4,22,41,"詰旦、巴勒引巴蘭至巴力崇邱、觀以色列營之邊隅、"],[4,23,1,"巴蘭謂巴勒曰、爾於此築壇七、備牡牛七、牡綿羊七、"],[4,23,2,"巴勒遵言而行、二人在各壇、獻牛一羊一、"],[4,23,3,"巴蘭謂巴勒曰、汝立於燔祭側、我且前往、庶幾耶和華臨我、其所示者、我必告爾、遂陟童山、"],[4,23,4,"上帝臨巴蘭、巴蘭曰、我備七壇、各獻牛一羊一、"],[4,23,5,"耶和華以言授巴蘭曰、返見巴勒、以此言告之、"],[4,23,6,"巴蘭返、見巴勒與摩押使臣、立於燔祭側、"],[4,23,7,"乃作歌曰、巴勒招我於亞蘭、摩押王導我於東岳、曰來、爲我詛雅各、詈以色列、"],[4,23,8,"上帝未詛者、我焉能詛之、耶和華未詈者、我焉能詈之、"],[4,23,9,"我自山巖而視之、我自陵巔而望之、斯族乃獨居、不列於萬國、"],[4,23,10,"雅各之塵、孰能核之、以色列族四分之一、孰能計之、善人之死、我願如之、義者之終、我願似之、"],[4,23,11,"巴勒謂巴蘭曰、爾於我何爲、我召爾詛敵、爾竟祝之、"],[4,23,12,"對曰、耶和華授我之言、我不愼述之乎、"],[4,23,13,"巴勒曰、請偕我之他、而瞻望之、勿觀其全營、只窺其一隅、爲我詛之、"],[4,23,14,"乃導至瑣腓野毘斯迦山巔、爰築七壇、各獻牛一羊一、"],[4,23,15,"謂巴蘭曰、汝立於燔祭側、我往於彼、以覲耶和華、"],[4,23,16,"耶和華臨巴蘭、以言授之曰、返見巴勒、以此言告之、"],[4,23,17,"至則見巴勒與摩押使臣、立於燔祭側、巴勒問曰、耶和華語爾何詞、"],[4,23,18,"巴蘭作歌曰、巴勒其起以聽、西撥子聽我言、"],[4,23,19,"上帝非人、致誑於言、亦非人子、致回厥意、旣有言、詎不行之、旣出辭、詎不踐之、"],[4,23,20,"我受命以祝嘏、上帝祝之、我難反之、"],[4,23,21,"上帝未見雅各家有愆尤、以色列有乖謬、彼之上帝耶和華與之偕、其中有歡然呼王之聲焉、"],[4,23,22,"上帝導之出埃及、有力可擬於兕、"],[4,23,23,"無術數以害雅各家、無卜筮以攻以色列、於斯時也、人論雅各以色列云、上帝待之、何其奇歟、"],[4,23,24,"斯民之興也如牝獅、其動也如牡獅、未食被攫之物、不飲見殺之血、則不偃臥、○"],[4,23,25,"巴勒謂巴蘭曰、爾勿詛之、亦勿祝之、"],[4,23,26,"巴蘭對曰、我豈不語汝、耶和華所諭、我必遵循、"],[4,23,27,"巴勒曰、爾來、我將引爾之他、庶幾上帝使爾於彼、爲我詛之、"],[4,23,28,"遂引至毘珥山巔、與野相望之處、"],[4,23,29,"巴蘭曰、於此築壇七、備牛七羊七、"],[4,23,30,"巴勒從其言、壇上各獻牛一羊一、"],[4,24,1,"巴蘭見耶和華欲錫嘏於以色列、不復用術、如昔所爲、乃瞻於野、"],[4,24,2,"舉目觀以色列族、循其支派、爰居爰處、則感於上帝之神、"],[4,24,3,"作歌曰、比珥子巴蘭云、明目者有詞、"],[4,24,4,"聞上帝之言、覩全能者之異象、身臥而目明者云、"],[4,24,5,"美哉、雅各之幕、以色列之居歟、"],[4,24,6,"如陵谷之延袤、如園囿之臨河、如耶和華所植之沉香、如溪旁之香柏、"],[4,24,7,"厥水溢於其器、厥種播於河濱、其王尊於亞甲、其國得而振興、"],[4,24,8,"上帝導之出埃及、有力可擬於兕、必吞敵國、而碎其骨、穿之以矢、"],[4,24,9,"蹲如牡獅、臥如牝獅、孰敢攖之、祝爾者必見祝、詛爾者必見詛、"],[4,24,10,"巴勒怒巴蘭、拊掌而言曰、我召爾詛敵、爾乃祝之者三、"],[4,24,11,"爾須速返故土、我意使爾尊顯、而耶和華禁之、"],[4,24,12,"巴蘭謂巴勒曰、我豈不告爾使臣、"],[4,24,13,"卽使巴勒以盈室之金銀饋我、亦不可逾越耶和華之命、擅行善惡、惟耶和華所諭、我則言之、"],[4,24,14,"今我將歸、爾其來前、此民至於季世、所以待爾民者、我將告汝、"],[4,24,15,"乃作歌曰、比珥子巴蘭云、明目者有詞、"],[4,24,16,"聞上帝之言、知至上者之智慧、覩全能者之異象、身臥而目明者曰、"],[4,24,17,"我見之不於今日、我觀之非在近時、有一星焉、自雅各家而出、有一杖焉、自以色列而興、擊破摩押之隅、殲滅鼓譟之士、"],[4,24,18,"以東必爲所獲、其敵西珥必爲其業、以色列族毅然而行、"],[4,24,19,"操權者將出自雅各、殲滅斯邑之遺民、"],[4,24,20,"又望亞瑪力作歌曰、亞瑪力爲列國之初興、終亦必亡、"],[4,24,21,"又望基尼族作歌曰、爾居鞏固、爾巢在於巖穴、"],[4,24,22,"雖然、基尼必將衰微、終爲亞述所虜、"],[4,24,23,"乃賡載歌曰、噫嘻乎、上帝行是、孰能得生、"],[4,24,24,"有舟至自基提、虐遇亞述、苛待希伯、彼亦淪亡、"],[4,24,25,"巴蘭乃返故土、巴勒亦歸、"],[4,25,1,"以色列族居什亭、淫於摩押女、"],[4,25,2,"蓋其女請民至、同祭其神、民遂食其祭品、共拜其神、"],[4,25,3,"以色列族附於巴力毘珥、耶和華怒之、"],[4,25,4,"諭摩西曰、取彼民長、向日懸於耶和華前、使耶和華釋怒於以色列族、"],[4,25,5,"摩西告以色列士師曰、凡附於巴力毘珥者、爾曹各誅其人、"],[4,25,6,"摩西與以色列會衆、號哭於會幕門、時、有以色列人攜米甸女、適其同儕、爲衆目擊、"],[4,25,7,"祭司亞倫孫、以利亞撒子非尼哈見之、遂離會衆、取戟於手、"],[4,25,8,"襲彼以色列人之後、入其穹廬、以戟刺其人、及女之腹、疫癘遂止於以色列族中、"],[4,25,9,"遘疫而死者、計二萬四千人、○"],[4,25,10,"耶和華諭摩西曰、"],[4,25,11,"祭司亞倫孫、以利亞撒子非尼哈、以我嫉邪爲心、致我釋怒於以色列人、當嫉邪時、不行殲滅、"],[4,25,12,"爾其告之、我將賜以平康之約、"],[4,25,13,"使彼及裔恆爲祭司、蓋爲其上帝嫉邪、爲以色列民贖罪、"],[4,25,14,"與米甸女同戮之以色列人、乃西緬族長、撒路子心利、"],[4,25,15,"被誅之女、乃米甸族長蘇珥之女哥斯比、○"],[4,25,16,"耶和華諭摩西曰、"],[4,25,17,"爾必擾害米甸人而擊之、"],[4,25,18,"蓋米甸人擾害爾曹、於奉毘珥、及其姊妹、米甸牧伯女哥斯比之事、詭計誘爾、是女於遘疫時、因奉毘珥之事、亦見殺焉、"],[4,26,1,"疫癘之後、耶和華諭摩西、及祭司亞倫子以利亞撒曰、"],[4,26,2,"當核以色列會衆、循其室家、自二十歲以上、能臨陳者核之、"],[4,26,3,"遂在摩押平原、約但河濱、近耶利哥、摩西及祭司以利亞撒告衆云、"],[4,26,4,"當核民數、自二十歲以上者、循耶和華所諭出自埃及之摩西、與以色列衆之命、○"],[4,26,5,"以色列長子流便、流便之子哈諾、爲哈諾族祖、法路、爲法路族祖、"],[4,26,6,"希斯崙、爲希斯崙族祖、迦米、爲迦米族祖、"],[4,26,7,"此流便之室家、見核者、計四萬三千七百三十人、"],[4,26,8,"法路子以利押、"],[4,26,9,"以利押子尼母利、大坍、亞比蘭、大坍亞比蘭乃在會中被簡者、與可拉黨同攻摩西亞倫、以逆耶和華、"],[4,26,10,"地張厥口而吞之、與可拉黨偕亡、當時二百五十人爲火所燬、垂爲鑑戒、"],[4,26,11,"惟可拉子孫未亡焉、○"],[4,26,12,"西緬之子、循其室家、尼母利、爲尼母利族祖、雅憫、爲雅憫族祖、雅斤、爲雅斤族祖、"],[4,26,13,"謝拉、爲謝拉族祖、掃羅、爲掃羅族祖、"],[4,26,14,"此西緬之室家、見核者、計二萬二千二百人、○"],[4,26,15,"迦得之子、循其室家、洗分、爲洗分族祖、哈基、爲哈基族祖、書尼、爲書尼族祖、"],[4,26,16,"阿斯尼、爲阿斯尼族祖、以利、爲以利族祖、"],[4,26,17,"亞律、爲亞律族祖、亞利利、爲亞利利族祖、"],[4,26,18,"此迦得之室家、見核者、計四萬有五百人、○"],[4,26,19,"猶大子珥、俄南、俱死於迦南、"],[4,26,20,"猶大之子、循其室家、示拉、爲示拉族祖、法勒斯、爲法勒斯族祖、謝拉、爲謝拉族祖、"],[4,26,21,"法勒斯之子希斯崙、爲希斯崙族祖、哈母勒、爲哈母勒族祖、"],[4,26,22,"此猶大之室家、見核者、計七萬六千五百人、○"],[4,26,23,"以薩迦之子、循其室家、陀拉、爲陀拉族祖、普瓦、爲普瓦族祖、"],[4,26,24,"雅述、爲雅述族祖、伸崙、爲伸崙族祖、"],[4,26,25,"此以薩迦之室家、見核者、計六萬四千三百人、○"],[4,26,26,"西布倫之子、循其室家、西列、爲西列族祖、以倫、爲以倫族祖、雅利、爲雅利族祖、"],[4,26,27,"此西布倫之室家、見核者、計六萬有五百人、○"],[4,26,28,"約瑟之子、循其室家、瑪拿西、以法蓮、"],[4,26,29,"瑪拿西之子瑪吉、爲瑪吉族祖、瑪吉生基列、爲基列族祖、"],[4,26,30,"基列之子伊以謝、爲伊以謝族祖、希勒、爲希勒族祖、"],[4,26,31,"亞斯烈、爲亞斯烈族祖、示劍、爲示劍族祖、"],[4,26,32,"示米大、爲示米大族祖、希弗、爲希弗族祖、"],[4,26,33,"希弗子西羅非哈無子、有女名瑪拉、挪阿、曷拉、密迦、得撒、"],[4,26,34,"此瑪拿西之室家、見核者、計五萬二千七百人、○"],[4,26,35,"以法蓮之子、循其室家、書提拉、爲書提拉族祖、比結、爲比結族祖、他罕、爲他罕族祖、"],[4,26,36,"書提拉之子以蘭、爲以蘭族祖、"],[4,26,37,"此以法蓮之室家、見核者、計三萬二千五百人、以上所載、乃約瑟之子孫、循其室家、○"],[4,26,38,"便雅憫之子、循其室家、比拉、爲比拉族祖、亞實別、爲亞實別族祖、亞希蘭、爲亞希蘭族祖、"],[4,26,39,"書反、爲書反族祖、戶反、爲戶反族祖、"],[4,26,40,"比拉之子亞勒、乃幔、亞勒、爲亞勒族祖、乃幔、爲乃幔族祖、"],[4,26,41,"此便雅憫之子孫、循其室家、見核者、計四萬五千六百人、○"],[4,26,42,"但之子、循其室家、書含、爲書含族祖、"],[4,26,43,"書含之室家見核者、計六萬四千四百人、○"],[4,26,44,"亞設之子、循其室家、音拿、爲音拿族祖、亦施韋、爲亦施韋族祖、比利亞、爲比利亞族祖、"],[4,26,45,"比利亞之子希別、爲希別族祖、瑪結、爲瑪結族祖、"],[4,26,46,"亞設之女名西拉、"],[4,26,47,"此亞設之子孫、循其室家、見核者、計五萬三千四百人、○"],[4,26,48,"拿弗他利之子、循其室家、雅薛、爲雅薛族祖、沽尼、爲沽尼族祖、"],[4,26,49,"耶色、爲耶色族祖、示冷、爲示冷族祖、"],[4,26,50,"此拿弗他利之子孫、循其室家、見核者、計四萬五千四百人、"],[4,26,51,"以色列族見核者、共計六十萬一千七百三十人、○"],[4,26,52,"耶和華諭摩西曰、"],[4,26,53,"分土與衆爲業、循其名數、"],[4,26,54,"人衆則給業多、人寡則給業少、所給之業、依其所核之數、"],[4,26,55,"惟地必掣籤而分之、循厥祖之支派、而得其業、"],[4,26,56,"衆寡之間、所當分者、掣籤而定、"],[4,26,57,"利未之族、循其室家、見核者、革順、爲革順族祖、哥轄、爲哥轄族祖、米拉利、爲米拉利族祖、"],[4,26,58,"利未之室家、乃立尼家、希伯倫家、瑪利家、母示家、可拉家、"],[4,26,59,"哥轄生暗蘭、暗蘭之妻、乃利未之孫、生於埃及、名約基別、適暗蘭生亞倫、摩西、與其姊米利暗、"],[4,26,60,"亞倫生拿答、亞比戶、以利亞撒、以他瑪、"],[4,26,61,"拿答亞比戶以不聖之火、獻於耶和華而死、"],[4,26,62,"利未族之丁男、自一月以上見核者、計二萬有三千、未與以色列族同核、因於以色列中未得其業、"],[4,26,63,"以上所載、乃在摩押平原、約但河濱、耶利哥相對之所、摩西與祭司以利亞撒、所核以色列之衆、"],[4,26,64,"昔在西乃野、摩西與祭司亞倫所核以色列人中、今無一人在其數者、"],[4,26,65,"蓋耶和華曾有言曰、其人必死於曠野、故耶孚尼子迦勒、嫩之子約書亞而外、靡有孑遺、"],[4,27,1,"約瑟子瑪拿西族、瑪拿西元孫、瑪吉曾孫、基列孫、希弗子西羅非哈之女瑪拉、挪阿、曷拉、密迦、得撒、"],[4,27,2,"俱至會幕門、立於摩西與祭司以利亞撒、及會長會衆之前曰、"],[4,27,3,"我父死於曠野、不在可拉黨中、集攻耶和華、第爲己罪而死、而無子嗣、"],[4,27,4,"何因無子、而删其名、絕於譜系、請在叔伯之中、以產予我、"],[4,27,5,"摩西以其事呈於耶和華、"],[4,27,6,"耶和華諭摩西曰、"],[4,27,7,"西羅非哈女之言是也、必以其父之產歸之、俾在叔伯中有其恆業、"],[4,27,8,"爾告以色列族云、如人死而無子、必歸其業於女、"],[4,27,9,"無女則歸諸兄弟、"],[4,27,10,"無兄弟則歸諸叔伯、"],[4,27,11,"無叔伯則歸諸近親、爲以色列族之典章律例、循耶和華所諭摩西之命、○"],[4,27,12,"耶和華諭摩西曰、爾陟亞巴琳山、觀我所賜以色列族之地、"],[4,27,13,"爾旣觀之、必歸乃祖、如爾兄亞倫然、"],[4,27,14,"昔在尋野水濱、會衆紛爭、爾曹悖逆我命、不於民前尊我爲聖、所言之水、在加低斯米利巴、"],[4,27,15,"摩西籲耶和華曰、"],[4,27,16,"請耶和華、世人諸神之上帝、簡立一人、統轄會衆、"],[4,27,17,"出入其前、導之往返、免耶和華會衆、猶羊之無牧、"],[4,27,18,"耶和華諭摩西曰、嫩之子約書亞、乃感於神、汝可取之、按手其上、"],[4,27,19,"置於祭司以利亞撒及會衆前、付託以命、"],[4,27,20,"以汝尊榮、加諸其身、使以色列會衆無不聽從、"],[4,27,21,"彼必立於祭司以利亞撒前、以利亞撒爲之諮諏烏陵於耶和華前、彼及以色列會衆、必聽其命而出、亦聽其命而入、"],[4,27,22,"摩西遵耶和華命、取約書亞、使立於祭司以利亞撒及會衆前、"],[4,27,23,"按手其上、以命託之、循耶和華所諭摩西之命、"],[4,28,1,"耶和華諭摩西曰、"],[4,28,2,"命以色列族云、所獻於我之食、爲馨香之火祭、當循其期以獻、"],[4,28,3,"更告之曰、所當日獻耶和華之火祭、卽一歲之牡羔二、純全無疵、恆爲燔祭、"],[4,28,4,"朝一暮一、"],[4,28,5,"又獻細麪伊法十分之一、和清油一欣四分之一、爲素祭、"],[4,28,6,"昔在西乃山、所命恆獻燔祭、以爲馨香之火祭、奉於耶和華者、卽此、"],[4,28,7,"獻其一羔、所奉灌祭之酒、一欣四分之一、必以醇醪奠於聖所、以爲灌祭、奉於耶和華、"],[4,28,8,"薄暮獻其一羔、循其清晨素祭灌祭之例、以爲馨香之火祭、奉於耶和華、○"],[4,28,9,"值安息日、獻一歲之牡羔二、純全無疵、和油之細麪伊法十分之二、爲素祭、及其灌祭、"],[4,28,10,"此每安息日所獻之燔祭、在恆獻之燔祭、及灌祭而外也、○"],[4,28,11,"月朔、必以燔祭獻耶和華、牡犢二、牡綿羊一、一歲之羔七、純全無疵、"],[4,28,12,"爲每牡犢、獻和油之細麪伊法十分之三、爲素祭、爲牡綿羊、獻和油之細麪伊法十分之二、爲素祭、"],[4,28,13,"爲每羔羊、獻和油之細麪伊法十分之一、爲素祭、均爲燔祭、以爲馨香之火祭、奉於耶和華、"],[4,28,14,"所奉灌祭、爲每牡犢、用酒一欣之半、爲牡綿羊、用一欣三分之一、爲每羔羊、用一欣四分之一、一歲之中、每月所獻爲燔祭者、卽此、"],[4,28,15,"恆獻之燔祭、及灌祭而外、亦獻一牡山羊於耶和華、爲贖罪祭、○"],[4,28,16,"正月十四日、爲耶和華之逾越節、"],[4,28,17,"是月之望、必守節期、當食無酵餅、歷至七日、"],[4,28,18,"節之首日、必有聖會、毋作苦、"],[4,28,19,"取牡犢二、牡綿羊一、一歲之羔七、純全無疵、獻於耶和華爲火祭、"],[4,28,20,"所獻素祭、乃和油之細麪、爲每牡犢、用伊法十分之三、爲牡綿羊、用伊法十分之二、"],[4,28,21,"爲每羔羊、用伊法十分之一、"],[4,28,22,"更獻牡山羊一、爲贖罪祭、以贖爾罪、"],[4,28,23,"上所獻者、乃在清晨恆獻燔祭之外、"],[4,28,24,"恆獻之燔祭、及灌祭而外、宜循此例、七日中、每日獻火祭之食、以爲馨香、奉於耶和華、"],[4,28,25,"越至七日、必有聖會、毋作苦、○"],[4,28,26,"七七日節、初實之際、獻新素祭於耶和華時、必有聖會、毋作苦、"],[4,28,27,"取牡犢二、牡綿羊一、一歲之羔七、獻爲燔祭、以爲馨香、奉於耶和華、"],[4,28,28,"所獻素祭、乃和油之細麪、爲每牡犢、用伊法十分之三、爲牡綿羊、用伊法十分之二、"],[4,28,29,"爲每羔羊、用伊法十分之一、"],[4,28,30,"更獻牡山羊一、以贖爾罪、"],[4,28,31,"上所獻者、必純全無疵、乃在恆獻之燔祭、及其素祭灌祭之外、"],[4,29,1,"七月朔、乃吹角之期、必有聖會、毋作苦、"],[4,29,2,"取牡犢一、牡綿羊一、一歲之羔七、純全無疵、獻爲燔祭、以爲馨香、奉於耶和華、"],[4,29,3,"所獻素祭、乃和油之細麪、爲牡犢、用伊法十分之三、爲牡綿羊、用伊法十分之二、"],[4,29,4,"爲每羔羊、用伊法十分之一、"],[4,29,5,"更獻牡山羊一、爲贖罪祭、以贖爾罪、"],[4,29,6,"此在月朔之燔祭素祭、與恆獻之燔祭素祭、及循例之灌祭之外、以爲馨香之火祭、奉於耶和華、○"],[4,29,7,"七月十日、必有聖會、當苦其心、勿操作、"],[4,29,8,"取牡犢一、牡綿羊一、一歲之羔七、純全無疵、獻爲燔祭、以爲馨香、奉於耶和華、"],[4,29,9,"所獻素祭、乃和油之細麪、爲牡犢、用伊法十分之三、爲牡綿羊、用伊法十分之二、"],[4,29,10,"爲每羔羊、用伊法十分之一、"],[4,29,11,"更獻牡山羊一、爲贖罪祭、此在贖罪之祭、與恆獻之燔祭、及其素祭灌祭之外、○"],[4,29,12,"七月十五日、必有聖會、毋作苦、七日守節、以奉事耶和華、"],[4,29,13,"取牡犢十三、牡綿羊二、一歲之羔十四、純全無疵、獻爲燔祭、以爲馨香之火祭、奉於耶和華、"],[4,29,14,"所獻素祭、乃和油之細麪、爲十三牡犢、各用伊法十分之三、爲二牡綿羊、各用伊法十分之二、"],[4,29,15,"爲十四羔羊、各用伊法十分之一、"],[4,29,16,"更獻牡山羊一、爲贖罪祭、此在恆獻之燔祭、及其素祭灌祭之外、○"],[4,29,17,"二日必獻牡犢十二、牡綿羊二、一歲之羔十四、純全無疵、"],[4,29,18,"所獻素祭、灌祭、均依牡犢牡綿羊及羔之數、俱循其例、"],[4,29,19,"更獻牡山羊一、爲贖罪祭、此在恆獻之燔祭、及其素祭灌祭之外、○"],[4,29,20,"三日必獻牡犢十一、牡綿羊二、一歲之羔十四、純全無疵、"],[4,29,21,"所獻素祭灌祭、均依牡犢牡綿羊及羔之數、俱循其例、"],[4,29,22,"更獻牡山羊一、爲贖罪祭、此在恆獻之燔祭、及其素祭灌祭之外、○"],[4,29,23,"四日必獻牡犢十、牡綿羊二、一歲之羔十四、純全無疵、"],[4,29,24,"所獻素祭灌祭、均依牡犢牡綿羊及羔之數、俱循其例、"],[4,29,25,"更獻牡山羊一、爲贖罪祭、此在恆獻之燔祭、及其素祭灌祭之外、○"],[4,29,26,"五日必獻牡犢九、牡綿羊二、一歲之羔十四、純全無疵、"],[4,29,27,"所獻素祭灌祭、均依牡犢牡綿羊及羔之數、俱循其例、"],[4,29,28,"更獻牡山羊一、爲贖罪祭、此在恆獻之燔祭、及其素祭灌祭之外、○"],[4,29,29,"六日必獻牡犢八、牡綿羊二、一歲之羔十四、純全無疵、"],[4,29,30,"所獻素祭灌祭、均依牡犢牡綿羊及羔之數、俱循其例、"],[4,29,31,"更獻牡山羊一、爲贖罪祭、此在恆獻之燔祭、及其素祭灌祭之外、○"],[4,29,32,"七日必獻牡犢七、牡綿羊二、一歲之羔十四、純全無疵、"],[4,29,33,"所獻素祭灌祭、均依牡犢牡綿羊及羔之數、俱循其例、"],[4,29,34,"更獻牡山羊一、爲贖罪祭、此在恆獻之燔祭、及其素祭灌祭之外、○"],[4,29,35,"八日必有肅會、毋作苦、"],[4,29,36,"取牡犢一、牡綿羊一、一歲之羔七、純全無疵、獻爲燔祭、以爲馨香之火祭、奉於耶和華、"],[4,29,37,"所獻素祭灌祭、均依牡犢牡綿羊及羔之數、俱循其例、"],[4,29,38,"更獻牡山羊一、爲贖罪祭、此在恆獻之燔祭、及其素祭灌祭之外、○"],[4,29,39,"值節期、必以上所言者、獻於耶和華、以爲燔祭、素祭、灌祭、酬恩祭、此在許願樂獻之祭而外、"],[4,29,40,"摩西告以色列族、俱循耶和華所命、"],[4,30,1,"摩西告以色列族長曰、耶和華命曰、"],[4,30,2,"如人指耶和華許願、或發誓以制其心、則勿食言、必循其口所出、"],[4,30,3,"若女年幼、尚在父家、指耶和華許願、以束其身、"],[4,30,4,"若父聞其所許之願、制心之約、默然無語、則其所許之願、制心之約爲定、"],[4,30,5,"如父聞而不允、則其所許之願、制心之約弗定、耶和華必宥之、因其父不允也、"],[4,30,6,"如女許願、或造次出言、以制其心、而後適人、"],[4,30,7,"夫聞之日、默然無語、則其所許之願、制心之約爲定、"],[4,30,8,"如夫聞而不允、則其所許之願、造次制心之言以廢、耶和華必宥之、"],[4,30,9,"惟嫠婦棄婦、所許的願當償、制心之約爲定、"],[4,30,10,"如婦在夫家許願、或發誓以制其心、"],[4,30,11,"夫聞默然、而不之禁、則其所許之願、制心之約爲定、"],[4,30,12,"如夫聞而廢之、則其許願所出之言、制心之約弗定、耶和華必宥之、因其夫廢之也、"],[4,30,13,"婦或許願、或發誓束身、以苦其心、夫可成之、亦可廢之、"],[4,30,14,"如夫歷日默然無語、則其所許之願、束身之約、爲夫所定、蓋聞之而默然也、"],[4,30,15,"如夫聞而廢之、必負其罪、"],[4,30,16,"以上所載、乃耶和華所諭摩西、夫於其婦、父於在家之幼女、其例若此、"],[4,31,1,"耶和華諭摩西曰、"],[4,31,2,"當擊米甸人、爲以色列族報仇、後歸乃祖、"],[4,31,3,"摩西告民曰、爾中簡人、執兵出征、攻米甸人、爲耶和華復仇、"],[4,31,4,"以色列支派、各出千人臨陳、"],[4,31,5,"於是以色列支派各出千人、總計一萬二千、執兵備戰、"],[4,31,6,"摩西遣之、又遣祭司以利亞撒子非尼哈、執聖所之器、與示警之角、"],[4,31,7,"遂遵耶和華所諭摩西之命、與米甸戰、殲其丁男、"],[4,31,8,"又殺米甸五王、以未、利金、蘇珥、戶珥、利巴、亦以刃戮比珥子巴蘭、"],[4,31,9,"以色列人虜其婦孺、奪其牛羊、及其貨財、"],[4,31,10,"所居之城邑、曁營壘、燬之以火、"],[4,31,11,"貨財人物、刦之以歸、"],[4,31,12,"以所虜之人與財物、攜至摩押平原、約但河濱、耶利哥相對之營壘、詣摩西及祭司以利亞撒、與以色列會衆、○"],[4,31,13,"摩西及祭司以利亞撒、曁諸會長、出營以迓、"],[4,31,14,"摩西見自陳而歸之軍長、千夫長、百夫長、怒之曰、"],[4,31,15,"爾生存衆婦乎、"],[4,31,16,"彼從巴蘭之謀、使以色列族因奉毘珥、干罪於耶和華、致疫行於耶和華之會、"],[4,31,17,"當殺幼穉中諸男、並殺與男同寢諸婦、"],[4,31,18,"惟未與男同寢之幼女、爾可爲己存其生命、"],[4,31,19,"爾曹居於營外七日、凡殺人、或捫尸者、必於三日七日自潔、所虜之人亦然、"],[4,31,20,"當緣衣皮毛木諸物自潔、"],[4,31,21,"祭司以利亞撒告臨陳之軍士曰、耶和華所諭摩西之典章、卽此、"],[4,31,22,"惟金銀銅鐵錫鉛、"],[4,31,23,"能勝火者、當使經火、然後爲潔、亦當滌以去汚之水、如不克勝火之物、必滌以水、"],[4,31,24,"越至七日、爾當澣衣、然後爲潔、可入於營、○"],[4,31,25,"耶和華諭摩西曰、"],[4,31,26,"汝與祭司以利亞撒、曁會中族長、宜計所虜之人與畜、"],[4,31,27,"分之爲二、一歸臨陳之軍士、一歸會衆、"],[4,31,28,"臨陳軍士所得之半、人驢牛羊、五百輸一、貢於耶和華、"],[4,31,29,"付諸祭司以利亞撒、以爲舉祭、獻於耶和華、"],[4,31,30,"以色列人所得之半、人驢牛羊、與各牲畜、五十輸一、以給守耶和華幕之利未人、"],[4,31,31,"摩西及祭司以利亞撒、遵耶和華所諭而行、"],[4,31,32,"軍士所虜之物外、計獲羊六十七萬五千、"],[4,31,33,"牛七萬二千、"],[4,31,34,"驢六萬一千、"],[4,31,35,"未與男同寢之女、三萬二千、"],[4,31,36,"臨陳者所得之半、計羊三十三萬七千五百、"],[4,31,37,"貢於耶和華者、六百七十五、"],[4,31,38,"牛三萬六千、貢於耶和華者七十二、"],[4,31,39,"驢三萬有五百、貢於耶和華者六十一、"],[4,31,40,"人一萬六千、貢於耶和華者三十二、"],[4,31,41,"所貢於耶和華、以爲舉祭者、摩西付諸祭司以利亞撒、遵耶和華所命、"],[4,31,42,"軍士所獲之物、摩西取其半、歸以色列會衆者、"],[4,31,43,"計羊三十三萬七千五百、"],[4,31,44,"牛三萬六千、"],[4,31,45,"驢三萬有五百、"],[4,31,46,"人一萬六千、"],[4,31,47,"摩西由斯人畜、五十取一、以給守耶和華幕之利未人、遵耶和華所命、○"],[4,31,48,"軍長、千夫長、百夫長、咸就摩西、"],[4,31,49,"曰、爾僕核數所統之軍士、不損一人、"],[4,31,50,"茲攜禮物、獻於耶和華、各隨所得之金珠、足鏈、手釧、指環、耳環、臂釧、以爲己命贖罪於耶和華前、"],[4,31,51,"摩西與祭司以利亞撒、收其金製之寶、"],[4,31,52,"千夫長百夫長所獻於耶和華之舉祭、其金計一萬六千七百五十舍客勒、"],[4,31,53,"軍士所獲者爲己有、"],[4,31,54,"摩西與祭司以利亞撒、取千夫長百夫長之金、攜入會幕、以爲以色列族之記誌、在耶和華前、"],[4,32,1,"流便族、迦得族、牲畜衆多、見雅謝基列二地、堪爲牧畜之所、"],[4,32,2,"乃就摩西及祭司以利亞撒、曁諸會長曰、"],[4,32,3,"亞大錄、底本、雅謝、寧拉、希實本、以利亞利、示班、尼波、比穩、"],[4,32,4,"卽耶和華於以色列族前、所攻取之地、堪爲牧畜之所、僕有羣畜、"],[4,32,5,"如沾爾恩、請以斯地錫我爲業、毋庸攜我渡約但、"],[4,32,6,"摩西曰、汝之昆弟往戰、汝安坐於此乎、"],[4,32,7,"奚使以色列族灰心、不濟至耶和華所錫之地、"],[4,32,8,"昔在加低斯巴尼亞、我遣爾祖窺察斯土、彼亦如是而行、"],[4,32,9,"旣至以實各谷、而見其地、則使以色列族灰心、不入耶和華所錫之地、"],[4,32,10,"當日耶和華怒而誓曰、"],[4,32,11,"出埃及之衆、自二十歲以上者、旣不專從乎我、皆不獲見我所誓於亞伯拉罕以撒雅各之地、"],[4,32,12,"惟基尼洗人耶孚尼子迦勒、嫩之子約書亞得見之、以其專從耶和華也、"],[4,32,13,"維時、耶和華怒以色列族、使流離於曠野、歷四十年、迨及斯代之民、違逆耶和華者、盡皆滅沒、"],[4,32,14,"今爾繼祖、增益罪人之數、使耶和華怒以色列族愈甚、"],[4,32,15,"如爾違逆不從、彼必復遣以色列族於野、是爾滅斯有衆也、"],[4,32,16,"其人進曰、我必在此、爲羣畜作牢、爲幼稚建邑、"],[4,32,17,"我必備執兵械、爲以色列族之先導、攜入其所、惟我幼稚、緣畏斯土之民、必居於堅城、"],[4,32,18,"我不旋返、迨以色列族各得其業、"],[4,32,19,"我不與彼得業於約但西、因已得之約但東矣、"],[4,32,20,"摩西曰、若爾如是而行、執兵爲戰於耶和華前、"],[4,32,21,"所有軍士濟約但河、迨耶和華驅逐諸敵、"],[4,32,22,"俾其地服耶和華、然後旋返、則在耶和華及以色列族前無辜、此地歸爾爲業、"],[4,32,23,"不然、則干犯耶和華、當知罪必及爾、"],[4,32,24,"可依所言而行、爲幼稚築邑、爲羣畜作牢、"],[4,32,25,"迦得流便二族、對摩西曰、僕循我主之命、"],[4,32,26,"妻孥牛羊、留於基列諸邑、"],[4,32,27,"僕必濟河、所有執兵之士、爲戰於耶和華前、從我主所言、○"],[4,32,28,"摩西命祭司以利亞撒、嫩之子約書亞、及以色列支派之族長、"],[4,32,29,"曰、如迦得流便二族、凡執兵備戰者、偕爾有衆、於耶和華前、濟約但河、攻取其地、則必以基列地與之爲業、"],[4,32,30,"若不執兵偕濟、則必得業於爾中、在迦南地、"],[4,32,31,"迦得流便二族對曰、耶和華所命、僕將遵行、"],[4,32,32,"我必於耶和華前、執兵濟河、至迦南地、惟我之業、在約但東、"],[4,32,33,"於是摩西以亞摩利王西宏、巴珊王噩之地、及境內之城邑、四周之鄉里、俱給迦得流便二族、約瑟子瑪拿西支派之半、○"],[4,32,34,"迦得人建築底本、亞他錄、亞羅珥、"],[4,32,35,"亞他錄朔反、雅謝、約比哈、"],[4,32,36,"伯寧拉、伯哈蘭、皆爲堅城、亦作羊牢、"],[4,32,37,"流便人建築希實本、以利亞利、基列亭、"],[4,32,38,"尼波、巴力免、此二邑易其名、又建築西比瑪、俱以新名稱之、"],[4,32,39,"瑪拿西子瑪吉之裔、往取基列、驅逐亞摩利人、"],[4,32,40,"摩西卽以其地錫之、遂處其中、"],[4,32,41,"瑪拿西子睚珥、往取其鄉里、稱之爲哈倭特睚珥、"],[4,32,42,"挪巴往取基納與其鄉里、以己名稱之爲挪巴、"],[4,33,1,"以色列族循其行伍、從摩西亞倫出埃及地、歷程如左、"],[4,33,2,"摩西遵耶和華命、以其所歷之程、筆之於書、"],[4,33,3,"正月之望、逾越節之翌日、以色列族自蘭塞啟行、昂然而出、爲埃及人目擊、"],[4,33,4,"時埃及人喪其長子、爲耶和華所擊者、彼之諸神、耶和華亦譴之、"],[4,33,5,"以色列族自蘭塞啟行、建營於疎割、"],[4,33,6,"自疎割啟行、建營於濱野之以倘、"],[4,33,7,"自以倘啟行、返而至於比哈希錄、巴力洗分相對之所、建營於密奪、"],[4,33,8,"自比哈希錄啟行、經海而入伊坦之野、歷程三日、建營於瑪拉、"],[4,33,9,"自瑪拉啟行、至以琳、在彼有水泉十二、椶樹七十、遂建營焉、"],[4,33,10,"自以琳啟行、建營於紅海之濱、"],[4,33,11,"自紅海濱啟行、建營於汛野、"],[4,33,12,"自汛野啟行、建營於脫加、"],[4,33,13,"自脫加啟行、建營於亞錄、"],[4,33,14,"自亞錄啟行、建營於利非訂、在彼、民衆無水可飲、"],[4,33,15,"自利非訂啟行、建營於西乃野、"],[4,33,16,"自西乃野啟行、建營於基博羅哈他瓦、"],[4,33,17,"自基博羅哈他瓦啟行、建營於哈洗錄、"],[4,33,18,"自哈洗錄啟行、建營於利提瑪、"],[4,33,19,"自利提瑪啟行、建營於臨門帕烈、"],[4,33,20,"自臨門帕烈啟行、建營於立拿、"],[4,33,21,"自立拿啟行、建營於勒撒、"],[4,33,22,"自勒撒啟行、建營於基希拉他、"],[4,33,23,"自基希拉他啟行、建營於沙斐山、"],[4,33,24,"自沙斐山啟行、建營於哈拉大、"],[4,33,25,"自哈拉大啟行、建營於瑪吉希錄、"],[4,33,26,"自瑪吉希錄啟行、建營於他哈、"],[4,33,27,"自他哈啟行、建營於他拉、"],[4,33,28,"自他拉啟行、建營於密加、"],[4,33,29,"自密加啟行、建營於哈摩拿、"],[4,33,30,"自哈摩拿啟行、建營於摩西錄、"],[4,33,31,"自摩西錄啟行、建營於比尼雅干、"],[4,33,32,"自比尼雅干啟行、建營於曷哈及甲、"],[4,33,33,"自曷哈及甲啟行、建營於約巴他、"],[4,33,34,"自約巴他啟行、建營於阿博拿、"],[4,33,35,"自阿博拿啟行、建營於以旬迦別、"],[4,33,36,"自以旬迦別啟行、建營於尋野、卽加低斯、"],[4,33,37,"自加低斯啟行、建營於何珥山、在以東界、"],[4,33,38,"以色列族出自埃及、歷四十年、五月朔、祭司亞倫遵耶和華命、陟何珥山而死、"],[4,33,39,"時亞倫年一百二十三、"],[4,33,40,"當時亞拉得王居於迦南之南、聞以色列族至、"],[4,33,41,"以色列族自何珥山啟行、建營於撒摩拿、"],[4,33,42,"自撒摩拿啟行、建營於普嫩、"],[4,33,43,"自普嫩啟行、建營於阿伯、"],[4,33,44,"自阿伯啟行、建營於以耶亞巴琳、在摩押界、"],[4,33,45,"自以耶亞巴琳啟行、建營於底本迦得、"],[4,33,46,"自底本迦得啟行、建營於亞門低比拉太音、"],[4,33,47,"自亞門低比拉太音啟行、建營於尼波前、亞巴琳山、"],[4,33,48,"自亞巴琳山啟行、建營於摩押平原、約但河濱、耶利哥相對之所、"],[4,33,49,"沿約但河建營、自伯耶施末、至摩押平原之亞伯什亭、○"],[4,33,50,"在摩押平原、約但河濱、耶利哥相對之所、耶和華諭摩西曰、"],[4,33,51,"告以色列族云、汝渡約但入於迦南、"],[4,33,52,"必於爾前驅其居民、壞其雕刻之木石、鎔鑄之偶像、毀厥崇邱、"],[4,33,53,"必取其地而居之、蓋我以斯土賜汝爲業、"],[4,33,54,"必掣籤分地、按爾室家、人衆則給地多、人寡則給地少、各隨所掣之籤、循其宗族、得以爲業、"],[4,33,55,"斯土之民、爾不驅逐、則爾所遺者、必爲爾目中之刺、脅下之棘、擾爾於所居之地、"],[4,33,56,"如是我將罰爾、猶欲罰彼然、"],[4,34,1,"耶和華諭摩西曰、"],[4,34,2,"告以色列族云、汝入迦南地、得其四境爲業、"],[4,34,3,"爾之南境、起於尋野、近乎以東、南界自鹽海之極處而東、"],[4,34,4,"繞亞克拉濱山之南、延至於尋、出加低斯巴尼亞之南、越哈薩亞達、至於押們、"],[4,34,5,"自押們繞至埃及溪、止於大海、"],[4,34,6,"西界大海、"],[4,34,7,"北界起於大海、延至何珥山、"],[4,34,8,"自何珥山至哈馬郊、延及西達達、"],[4,34,9,"自西斐崙而往、至哈薩以難爲極、是爲爾之北界、"],[4,34,10,"東界起於哈薩以難、延至示番、"],[4,34,11,"自示番延至利比拉、在亞延之東、又至基尼烈海之東隅、"],[4,34,12,"沿約但河、至鹽海爲極、爾地四界、卽此、"],[4,34,13,"摩西告以色列族曰、斯卽耶和華所命、掣籤分於九支派、及半支派之地、"],[4,34,14,"蓋流便迦得二支派、及瑪拿西半支派、循其宗族、已得其業、"],[4,34,15,"在約但東、與耶利哥相對、日出之處、○"],[4,34,16,"耶和華諭摩西曰、"],[4,34,17,"爲爾分地爲業者、乃祭司以利亞撒、嫩之子約書亞、"],[4,34,18,"又簡各支派牧伯一人、"],[4,34,19,"其人之名、猶大支派、耶孚尼子迦勒、"],[4,34,20,"西緬支派、亞米忽子示母利、"],[4,34,21,"便雅憫支派、基斯崙子以利達、"],[4,34,22,"但之支派、約利子布基、"],[4,34,23,"約瑟子瑪拿西支派、以弗子漢聶、"],[4,34,24,"以法蓮支派、拾弗但子基母利、"],[4,34,25,"西布倫支派、帕納子以利撒番、"],[4,34,26,"以薩迦支派、阿散子帕鐵、"],[4,34,27,"亞設支派、示羅米子亞希忽、"],[4,34,28,"拿弗他利支派、亞米忽子比大黑、"],[4,34,29,"以上所載、卽耶和華所命、以迦南地分以色列族爲業者、"],[4,35,1,"在摩押平原、約但河濱、耶利哥相對之處、耶和華諭摩西曰、"],[4,35,2,"命以色列族於其所得之業、以邑與郊予利未人、"],[4,35,3,"其邑爲民居處、其郊爲置牛羊牲畜物產之所、"],[4,35,4,"所予利未人者、邑垣而外、四周一千肘爲郊、"],[4,35,5,"邑外之地、東西南北、各量二千肘、邑在其中、此卽邑之郊也、"],[4,35,6,"所予利未人之邑、其中有逃城六、使誤殺人者可遁於彼、此外又予邑四十有二、"],[4,35,7,"所予利未人之邑與郊、共四十有八、"],[4,35,8,"以色列族所得之業、必視邑之多寡、以予利未人、邑多則所予者多、邑寡則所予者寡、各循所得之業而予焉、○"],[4,35,9,"耶和華諭摩西曰、"],[4,35,10,"告以色列族云、汝渡約但、入於迦南、"],[4,35,11,"必簡邑爲逃城、使誤殺人者可遁於彼、"],[4,35,12,"此邑爲避復仇者之所、俾誤殺人者不致死亡、俟見鞫於會衆、"],[4,35,13,"逃城必有其六、"],[4,35,14,"約但東三、迦南地三、"],[4,35,15,"此六邑、爲以色列族、及旅於其中者之避所、凡誤殺人者、可遁於彼、"],[4,35,16,"若以鐵器擊人至死、是爲故殺、故殺人者殺毋赦、"],[4,35,17,"若以石擊人至死、是爲故殺、故殺人者殺毋赦、"],[4,35,18,"若以木器擊人至死、是爲故殺、故殺人者殺毋赦、"],[4,35,19,"故殺人者、復仇者必殺之、遇卽殺之、"],[4,35,20,"若蓄怨而仆人、或潛伏而以物擲人至死、"],[4,35,21,"或因憾而手擊人至死、是爲故殺、故殺人者殺毋赦、復仇者遇卽殺之、"],[4,35,22,"如無釁隙、而猝然刺人、或非潛伏、而以物擲人、"],[4,35,23,"或未之見、而以石擲人至死、本非結讎、亦非加害、"],[4,35,24,"則會衆必於殺人復仇者之間、循例而剖析、"],[4,35,25,"救誤殺人者、脫於復仇者之手、使遁逃城以居、待受聖膏之祭司長終焉、"],[4,35,26,"如誤殺人者出逃城之境、"],[4,35,27,"復仇者在邑外、遇而殺之、則無流血之罪、"],[4,35,28,"緣彼當居逃城、待祭司長死、祭司長旣死、殺人者返其故土可也、"],[4,35,29,"於爾所居之地、此爲律例、歷世弗替、"],[4,35,30,"故殺人者、有人爲證、必殺毋赦、但證人惟一則不可、"],[4,35,31,"故殺人者、不得以金贖其命、必殺毋赦、"],[4,35,32,"遁於逃城者、祭司長未死之先、不可取其贖金、使歸故土、"],[4,35,33,"如是、則不汚爾所居之地、蓋流人血、乃汚其地、非流殺人者之血、則無以潔之、"],[4,35,34,"我耶和華居以色列族中、勿汚爾土、我所處者、"],[4,36,1,"約瑟曾孫、瑪拿西孫、瑪吉子基列後裔之族長、"],[4,36,2,"就摩西及以色列族長之爲牧伯者曰、耶和華命我主、掣籤分土、予以色列族爲業、亦命我主、以我昆弟西羅非哈之業予其女、"],[4,36,3,"如適以色列他支派之人、則減我祖之業、而加於其夫之支派、如是、於我籤分之業有損、"],[4,36,4,"值以色列族禧年、則女之業、必歸於其夫之支派、而我祖之業必減焉、"],[4,36,5,"摩西遵耶和華命、告以色列族曰、約瑟子之支派、所言是也、"],[4,36,6,"耶和華命曰、西羅非哈之女、任其適人、惟必適父同宗支派之人、"],[4,36,7,"如是、以色列族之業、不至由此移彼、以色列各支派之人、守祖遺業、"],[4,36,8,"凡以色列支派中、承業之女、必適其父同宗支派之人、使以色列族各承厥祖之遺業、"],[4,36,9,"如是、則業不至由此移彼、以色列支派、必各守其業、"],[4,36,10,"西羅非哈之女、遂遵耶和華命摩西之言而行、"],[4,36,11,"其女瑪拉、得撒、曷拉、密迦、挪阿、俱適叔伯之子、"],[4,36,12,"歸於約瑟子瑪拿西宗族、其業存於父之同宗支派、"],[4,36,13,"以上所載、乃於摩押平原、約但河濱、耶利哥相對之所、耶和華藉摩西、告以色列族之誡命律例也、"],[5,1,1,"此乃摩西宣於以色列衆之言、在約但東之曠野、疎弗相對之亞拉巴、巴蘭陀弗拉班哈洗錄底撒哈之間、"],[5,1,2,"自何烈啟行、經西珥山、至加低斯巴尼亞、歷程十有一日、"],[5,1,3,"四十年十一月朔、摩西遵耶和華命、悉諭以色列人、"],[5,1,4,"時、摩西已戮居希實本之亞摩利王西宏、並在以得來、戮居亞斯他錄之巴珊王噩、"],[5,1,5,"在約但東摩押地、始宣此律、曰、"],[5,1,6,"昔在何烈、我上帝耶和華諭我儕云、爾居此山已久、"],[5,1,7,"當啟行、改道至亞摩利山地、與附近之處、亞拉巴、山地、窪地、南土、沿海一帶、迦南地、利巴嫩、抵伯拉大河、"],[5,1,8,"昔耶和華誓以斯土、錫爾祖亞伯拉罕以撒雅各、及其苗裔、今地具在爾前、可入而據之、○"],[5,1,9,"當時我告爾曰、我不能獨負爾任、"],[5,1,10,"爾上帝耶和華使爾昌熾、今爾如天星之多、"],[5,1,11,"願爾祖之上帝耶和華、更增爾數千倍、循其所許、錫嘏於爾、"],[5,1,12,"爾之繁劇、爾之重負、爾之爭競、我焉能獨任、"],[5,1,13,"當循爾之支派、簡衆所識之明哲練達人、我立之爲爾長、"],[5,1,14,"爾曹對曰、爾所言者、我儕行之、善也、"],[5,1,15,"我遂於爾支派爲首者中、簡衆所識之明哲人、依爾支派、立之爲長、卽千夫長、百夫長、五十夫長、十夫長、及有司、"],[5,1,16,"當時我命爾士師曰、爾聽訟、或人與宗族、或人與賓旅、當秉公以行鞫、"],[5,1,17,"鞫時、毋行偏視、無論貴賤、必聽其詞、不可畏人、蓋鞫事屬上帝也、事遇難斷、則呈我聽之、"],[5,1,18,"彼時我以爾所當行者、悉諭於爾、○"],[5,1,19,"厥後、我儕遵我上帝耶和華命、自何烈啟行、經歷曠野、大而可畏、爾所目覩、道由亞摩利山地、至加低斯巴尼亞、"],[5,1,20,"我告爾曰、爾已至亞摩利山地、卽我上帝耶和華所賜我者、"],[5,1,21,"試觀爾上帝耶和華備斯土於爾前、當循爾祖之上帝耶和華言、前往據之、毋懼毋怯、"],[5,1,22,"爾衆詣我曰、不如先遣人爲我窺其地、返而告我、當行何道、將至何邑、"],[5,1,23,"斯事我視爲善、簡人十二、支派各一、"],[5,1,24,"遂啟行登山、至以實各谷探之、"],[5,1,25,"取其土產、攜至我所、復我曰、我上帝耶和華所賜我者、肥美之地也、"],[5,1,26,"乃爾不願前往、逆爾上帝耶和華之命、"],[5,1,27,"在幕中興怨言曰、耶和華憾我、故導我出埃及、付於亞摩利人之手、以殲滅我、"],[5,1,28,"我將何往、我同儕使我喪膽、言斯土之民、較我修偉、城垣廣大鞏固、高可參天、且見亞衲族在彼、"],[5,1,29,"我告爾曰、毋懼、毋畏之、"],[5,1,30,"爾上帝耶和華爲爾先導、必爲爾戰、如昔行於埃及、爾所目擊者然、"],[5,1,31,"又在曠野、由爾所經之道、至於此地、爾上帝耶和華保抱爾、如人之保抱其子、爲爾所見、"],[5,1,32,"然在此事、爾不信爾上帝耶和華、"],[5,1,33,"彼爲爾先導、擇張幕之所、夜以火、晝以雲、示爾當行之道、"],[5,1,34,"耶和華聞爾言、怒而誓曰、"],[5,1,35,"昔我誓以沃壤賜爾祖、此惡世之人、必無一得見者、"],[5,1,36,"惟耶孚尼子迦勒專從耶和華、必得見之、其所履之地、我將賜之、及其子孫、"],[5,1,37,"耶和華緣爾故、亦怒我曰、爾亦不得入此地、"],[5,1,38,"惟侍爾者、嫩之子約書亞得入、當堅厥志、彼必使以色列人據有斯土、"],[5,1,39,"爾之幼穉、所言必被虜者、爾之子女、不能別善惡者、必得入之、我將賜彼、使之據有其地、"],[5,1,40,"惟爾當由紅海之道、而入曠野、"],[5,1,41,"爾曹對曰、我獲罪於耶和華、願遵我上帝耶和華命、前往以戰、於是各佩軍器、急欲入山、"],[5,1,42,"耶和華命我告民曰、毋往、毋戰、恐敗於敵、蓋我不在爾中、"],[5,1,43,"我以告爾、爾不聽從、違耶和華命、擅自登山、"],[5,1,44,"居山之亞摩利人、出而攻爾、追爾、勢若蜂擁、自西珥擊爾、至何珥瑪、"],[5,1,45,"爾曹乃返、哭於耶和華前、耶和華不爲側耳、不聽爾聲、"],[5,1,46,"於是爾居加低斯、積有多日、"],[5,2,1,"厥後、我儕遵耶和華命、啟行旋返、由紅海之道、而入曠野、繞西珥山多日、"],[5,2,2,"耶和華諭我曰、"],[5,2,3,"爾繞此山已久、可轉而北行、"],[5,2,4,"宜諭民曰、爾同族以掃子孫、居西珥山、爾過其境、彼必畏懼、爾其愼之、"],[5,2,5,"勿與之爭、其地卽容一足之區、我不爾予、蓋我已將西珥山賜以掃爲業、"],[5,2,6,"爾必以金、購糧而食、購水而飲、"],[5,2,7,"蓋爾上帝耶和華、於爾凡百所爲、錫嘏於爾、彼知爾行於大野、偕爾歷四十年、爾無所缺、"],[5,2,8,"於是我儕離我同族、卽以掃子孫、居於西珥山者、由亞拉巴之道、及以拉他以旬迦別、轉向摩押曠野而行、○"],[5,2,9,"耶和華諭我曰、勿擾摩押、勿與之戰、其地我不爾予、蓋我已將亞珥賜羅得子孫爲業、"],[5,2,10,"昔以米族居彼、其民衆多、軀幹修偉、如亞衲族然、"],[5,2,11,"斯民與亞衲族、同爲利乏音族、摩押人稱之爲以米族、"],[5,2,12,"昔何利人居西珥、以掃子孫滅之、繼居其地、如以色列人所行於耶和華賜以爲業之地者然、"],[5,2,13,"耶和華亦諭我曰、今起、渡撒烈溪、我儕遂渡之、"],[5,2,14,"自離加低斯巴尼亞、至渡撒烈溪時、歷三十有八年、斯時也、此代武士俱絕於營中、如耶和華所誓之言、"],[5,2,15,"蓋耶和華攻之、使盡滅於營中、○"],[5,2,16,"民中武士、旣已盡滅、"],[5,2,17,"耶和華諭我曰、"],[5,2,18,"今日爾經摩押邊隅之亞珥、"],[5,2,19,"近亞捫族、勿擾之、勿與戰、其地我不爾予、蓋我已賜羅得子孫爲業、"],[5,2,20,"斯土亦屬利乏音、昔爲利乏音族所居、亞捫人稱之爲散送冥、"],[5,2,21,"其民衆多、軀幹修偉、如亞衲族然、耶和華滅之於亞捫人前、使繼居其地、"],[5,2,22,"如爲以掃子孫、居西珥者、滅何利人於其前、使繼居其地、以至今日、"],[5,2,23,"又有亞衞人村居、延及迦薩、迦斐託人出而滅之、繼居其地、"],[5,2,24,"耶和華亦諭我曰、爾起前往、度亞嫩谷、我以亞摩利人希實本王西宏、及其土地、付於爾手、可與之戰、肇業於斯、"],[5,2,25,"自今日始、我使天下萬民、緣爾而懼、彼聞爾名、無不戰慄憯怛、○"],[5,2,26,"摩西曰、我自基底莫野、遣使往見希實本王西宏、以和好之言告之云、"],[5,2,27,"請容我經爾地、必由大道、不偏於左、不偏於右、"],[5,2,28,"爾受我金、鬻我以糧、給我以水、第容我過爾境、"],[5,2,29,"待遇我儕、若居西珥之以掃子孫、居亞珥之摩押人所爲、迨我渡約但、至我上帝耶和華賜我之地、"],[5,2,30,"乃希實本王西宏、不容我過其境、蓋爾上帝耶和華使其心志頑梗、致付爾手、有如今日、"],[5,2,31,"耶和華又諭我曰、我今以西宏及其地、始付於爾、據以爲業、"],[5,2,32,"西宏率其民衆、出而攻我、戰於雅雜、"],[5,2,33,"我上帝耶和華付之於我、我遂擊之、爰及其子與民、"],[5,2,34,"取其諸邑、殲滅居民、曁厥婦孺、靡有孑遺、"],[5,2,35,"惟彼牲畜、與諸邑之財物、爲我所得、"],[5,2,36,"自亞嫩谷濱之亞羅珥、及谷中之邑、至於基列、無一崇高之城、不爲我所拔者、我上帝耶和華、盡付於我矣、"],[5,2,37,"惟亞捫人之境、卽沿雅博溪之地、山中之邑、凡我上帝耶和華所禁者、爾未近之、"],[5,3,1,"我儕轉由巴珊之道、巴珊王噩、率其民衆咸出、與我戰於以得來、"],[5,3,2,"耶和華諭我曰、毋畏之、彼及其民與地、我悉付於爾手、爾待之、如昔待居希實本之亞摩利王西宏然、"],[5,3,3,"於是我上帝耶和華、以巴珊王噩及其民、付於我手、我擊之、至無所遺、"],[5,3,4,"取其諸邑、無邑不爲我儕所得、邑凡六十、乃亞珥歌伯全境、卽噩之國巴珊也、"],[5,3,5,"諸邑俱有高垣、與門及楗、此外無垣之鄉里甚衆、"],[5,3,6,"我滅其邑、殲厥居民、及其婦孺、如昔行於希實本王西宏者然、"],[5,3,7,"惟彼牲畜、與邑中財物、爲我所得、"],[5,3,8,"當時我自約但東、亞摩利二王之手、取其土地、自亞嫩谷、至黑門山、"],[5,3,9,"黑門山、西頓人稱爲西連、亞摩利人稱爲示尼珥、"],[5,3,10,"其平原諸邑、基列全地、巴珊全地、以及撒迦與以得來、乃噩之國、巴珊之邑、悉爲我取、"],[5,3,11,"利乏音族所存者、惟巴珊王噩、其床以鐵爲之、長九肘、廣四肘、以人肘爲度、今在亞捫人之拉巴邑、"],[5,3,12,"時、我儕旣得斯土、自亞嫩谷濱之亞羅珥、及基列山之半、與其諸邑、我以之予流便族、迦得族、"],[5,3,13,"基列餘地、及噩之國巴珊全地、亞珥歌伯四境、我以之予瑪拿西支派之半、巴珊昔稱爲利乏音地、"],[5,3,14,"瑪拿西裔睚珥、得亞珥歌伯四境、至基述瑪迦二族之界、依其名、稱巴珊爲哈倭特睚珥、以至今日、"],[5,3,15,"我以基列予瑪吉、"],[5,3,16,"自基列至亞嫩谷、以谷中爲界、抵亞捫界之雅博溪、"],[5,3,17,"及亞拉巴、沿約但河之地、自基尼列、至亞拉巴之鹽海、並毘斯迦山麓以東之地、悉以予流便族、迦得族、○"],[5,3,18,"時、我命爾曰、爾上帝耶和華、旣以斯土錫爾爲業、爾之勇士、必皆執兵、先爾兄弟以色列人而往、"],[5,3,19,"我知爾牲畜衆多、爾之妻孥牲畜、可留於我予爾之邑、"],[5,3,20,"迨爾兄弟於約但西、得爾上帝耶和華所錫之地、而享安息、與爾無異、後則返我予爾爲業之地、"],[5,3,21,"我又命約書亞曰、爾上帝耶和華所行於二王者、爾悉目擊、今爾所往諸國、耶和華亦如是待之、"],[5,3,22,"毋畏之、蓋爲爾戰者、爾上帝耶和華也、○"],[5,3,23,"時、我祈耶和華曰、"],[5,3,24,"主耶和華歟、爾以大威大能、顯示爾僕、在天在地、尚有何神、能爲爾所爲、行爾所行大能之事乎、"],[5,3,25,"求爾容我渡約但、觀河西之美地佳山、及利巴嫩、"],[5,3,26,"惟耶和華緣爾曹故怒我、不允我所求、諭我曰、如是足矣、勿以此事、再言於我、"],[5,3,27,"爾可登毘斯迦巔、向東西南北而瞻望、以目觀之、不得渡約但、"],[5,3,28,"當命約書亞、勗之壯之、因其必率斯民而渡、俾承爾所將見之地、"],[5,3,29,"我儕遂居伯毘珥相對之谷中、"],[5,4,1,"以色列人歟、我今教爾遵守之典章律例、宜聽從之以得生、爾祖之上帝耶和華賜爾之地、可入而承之、"],[5,4,2,"我所諭爾之言、不可增、亦不可減、惟遵爾上帝耶和華之誡命、我所諭爾者、"],[5,4,3,"耶和華緣巴力毘珥所行之事、乃爾目擊、凡從巴力毘珥者、爾上帝耶和華已滅之於爾中、"],[5,4,4,"惟爾附爾上帝耶和華者、迄今尚存、"],[5,4,5,"我遵我上帝耶和華所命、教爾以典章律例、使行於入而爲業之地、"],[5,4,6,"守之行之、是爲爾之智慧通達、在列邦民前、彼聞此典章、必曰、此大國、乃智慧通達之民也、"],[5,4,7,"有何大國、得神近之、猶我上帝耶和華於我禱時之近我乎、"],[5,4,8,"有何大國、典章律例、如是公平、若我今日所宣於爾者乎、○"],[5,4,9,"惟當自愼、謹守乃心、免忘爾目所見、畢生不去於懷、以之示爾子孫、"],[5,4,10,"昔爾在何烈、立於爾上帝耶和華前時、耶和華諭我曰、當集斯民、我使之聽我言、俾其在世、一生學寅畏我、而教子女、"],[5,4,11,"爾遂來前、立於山下、火焚於山、其焰冲天、陰雲密布、幽暗晦冥、"],[5,4,12,"耶和華由火中諭爾、爾聞其聲、不見其象、"],[5,4,13,"彼以爾所當守之約示爾、十誡是也、並書之二石版、"],[5,4,14,"耶和華命我以典章律例教爾、使爾行於所往據以爲業之地、"],[5,4,15,"昔在何烈、耶和華由火中諭爾時、爾曹未見何像、故當謹愼、"],[5,4,16,"恐爾自敗、雕偶以仿諸像、或男或女、"],[5,4,17,"或地上走獸、空中飛禽、"],[5,4,18,"或地上昆蟲、水中鱗介、"],[5,4,19,"又恐爾仰觀於天、見日月星諸象、乃爾上帝耶和華爲天下萬民所陳者、受惑而崇事之、"],[5,4,20,"耶和華導爾出埃及、脫於冶爐、以爲其業之民、有如今日、"],[5,4,21,"耶和華緣爾故怒我、誓不容我渡約但、入其錫爾爲業之美地、"],[5,4,22,"我必死於此、不得渡約但、惟爾其濟、得彼沃土、"],[5,4,23,"爾當謹愼、免忘爾上帝耶和華與爾所立之約、爲己雕偶、仿其所禁諸物之像、"],[5,4,24,"蓋爾上帝耶和華乃烈火、忌邪之上帝、○"],[5,4,25,"厥後、爾久居斯土、生子生孫、如其自敗、依像雕偶、作惡於爾上帝耶和華前、以激其怒、"],[5,4,26,"我今日籲天地爲證、爾於濟約但所承之地、必速絕滅、不得延年、淪胥以亡、"],[5,4,27,"耶和華必散爾於列邦、在其導爾所至之國、餘者無幾、"],[5,4,28,"爾曹在彼、將事人手所造木石之神、不能見聞食嗅者、"],[5,4,29,"惟爾在彼、盡心盡意求爾上帝耶和華、則必得之、"],[5,4,30,"迨至季世、爾遇苦難、所言諸事、臨及爾身、爾必歸爾上帝耶和華、而聽其命、"],[5,4,31,"爾上帝耶和華、乃仁慈之上帝、必不棄爾、不滅爾、不忘與爾列祖所立之約、"],[5,4,32,"粵稽往古、自上帝造人於世、由天涯至地極、有如此之大事乎、曾聞之乎、"],[5,4,33,"曾有國民、聞上帝出自火中之言、如爾所聞、而猶生存者乎、"],[5,4,34,"上帝豈曾以試鍊、異蹟、奇事、爭戰、能手、奮臂、大而可畏之事、於他國中導出他民、如爾上帝耶和華爲爾所行於埃及、爾所目擊者乎、"],[5,4,35,"以此顯示於爾、俾知耶和華乃上帝、其外無他、"],[5,4,36,"自天令爾聞其聲、以教誨爾、在地使爾見其大火、由火中聞其言、"],[5,4,37,"因愛爾祖、選其後裔、施厥大能、親導爾出埃及、"],[5,4,38,"爲爾驅逐較爾強大之民、導爾入境、賜爾以爲業、有如今日、"],[5,4,39,"今爾當知、中心思維、天上地下、惟耶和華爲上帝、其外無他、"],[5,4,40,"我今以其典章誡命諭爾、爾當遵守、則爾與子孫、皆可得福、亦可延年、於爾上帝耶和華所賜之地、○"],[5,4,41,"當時摩西在約但東、日出之處、區別三邑、"],[5,4,42,"使素無仇怨、而誤殺人者、可逃入之、以保其生、"],[5,4,43,"一爲原野之比悉、爲流便人而設、一爲基列之拉末、爲迦得人而設、一爲巴珊之哥蘭、爲瑪拿西人而設、○"],[5,4,44,"以上所載、乃摩西爲以色列人所宣之律也、"],[5,4,45,"法度典章律例、出埃及後、摩西以之諭於以色列人、"],[5,4,46,"在約但東、伯毘珥相對之谷中、此地昔屬居希實本之亞摩利王西宏、摩西與以色列人出埃及時擊之、"],[5,4,47,"取其地以爲業、又得巴珊王噩之地、此二人、俱爲亞摩利王、在約但東、日出之處、"],[5,4,48,"其地自亞嫩谷濱之亞羅珥、至西雲山、卽黑門山、"],[5,4,49,"又得約但東之亞拉巴全地、至亞拉巴之海、近毘斯迦山麓、"],[5,5,1,"摩西召以色列衆、告之曰、以色列人歟、我所諭爾之典章律例、爾當聽從、學習遵行、"],[5,5,2,"我上帝耶和華在何烈、與我儕立約、"],[5,5,3,"非與我祖立約、乃與我儕今日在此尚存者也、"],[5,5,4,"耶和華在山上、由火中與爾晤對而言、"],[5,5,5,"當時爾曹懼火、不敢登山、我立於耶和華與爾曹之間、以耶和華言告爾曰、"],[5,5,6,"我乃爾之上帝耶和華、導爾出埃及、脫於奴隸之室、○"],[5,5,7,"余而外、勿更有他神、○"],[5,5,8,"勿雕偶像、勿造上天下地、地下水中、百物之像、"],[5,5,9,"勿拜跪、勿崇奉、以我耶和華爾之上帝、乃忌邪之上帝、惡我者討其罪、自父及子、至三四世、"],[5,5,10,"愛我守我誡者、錫之慈惠、至千百世、○"],[5,5,11,"勿妄稱爾上帝耶和華之名、蓋耶和華必不以妄稱者爲無罪、○"],[5,5,12,"當守安息日、以爲聖日、遵爾上帝耶和華所命、"],[5,5,13,"六日間、宜勤勞、作爾庶務、"],[5,5,14,"惟七日、乃爾上帝耶和華之安息、是日爾與子女、僕婢牛驢、曁諸牲畜、及寓爾家之遠人、皆毋操作、使爾僕婢休憩、與爾無異、"],[5,5,15,"當憶昔在埃及、服役於人、爾上帝耶和華以能手奮臂、導爾出之、故命爾守安息日、○"],[5,5,16,"遵爾上帝耶和華命、敬爾父母、以致延年納福、於爾上帝耶和華所錫之地、○"],[5,5,17,"毋殺人、○"],[5,5,18,"毋行淫、○"],[5,5,19,"毋攘竊、○"],[5,5,20,"毋妄證以陷人、○"],[5,5,21,"毋貪人之妻室、與其第宅田疇、僕婢牛驢、及凡所有、○"],[5,5,22,"以上諸言、耶和華在山上、由火雲幽暗中、大聲諭爾會衆、此外無復增益、書之二石版、以授於我、"],[5,5,23,"當時火焚於山、聲出晦冥、爾旣聞之、爾之族長長老、進於我前、"],[5,5,24,"曰、我上帝耶和華顯其大榮大威、俾我目覩、我聞其聲、由火中出、今日乃知上帝與人言、而人猶得生存、"],[5,5,25,"今我胡爲致死、此大火將滅我、如我再聞我上帝耶和華之聲、則必隕沒、"],[5,5,26,"凡有血氣者、誰如我聞維生上帝出自火中之聲、而猶生存者乎、"],[5,5,27,"爾其近前、聽我上帝耶和華所言、我上帝耶和華所諭爾者、以告於我、我必聽從遵行、○"],[5,5,28,"爾以此言告我、耶和華悉聞之、諭我曰、我聞斯民所語於爾、皆善言也、"],[5,5,29,"願其存心畏我、恆守我誡、俾受福祉、爰及子孫、歷世靡曁、"],[5,5,30,"爾往告曰、當歸汝幕、"],[5,5,31,"惟爾侍立我側、我將以誡命典章律例示爾、以教斯民、使行於我所賜爲業之地、"],[5,5,32,"故爾上帝耶和華所命爾者、爾當謹守遵行、勿偏於左、勿偏於右、"],[5,5,33,"遵行爾上帝耶和華所命之道、致爾生存納福、延年於爾所得爲業之地、"],[5,6,1,"此誡命典章律例、乃爾上帝耶和華所命、以教爾者、使爾行之於爾所得爲業之地、"],[5,6,2,"俾爾及子孫、畢生寅畏爾上帝耶和華、守其典章誡命、凡我所命爾者、以致延年、"],[5,6,3,"以色列歟、爾其聽之、謹守遵行、致可納福昌熾、於彼流乳與蜜之地、如爾祖之上帝耶和華所許爾者、○"],[5,6,4,"以色列歟、爾其聽之、我上帝耶和華、惟一而已、"],[5,6,5,"當盡心盡性盡力、愛爾上帝耶和華、"],[5,6,6,"我今命爾之言、當存於心、"],[5,6,7,"勤誨子女、坐於室、行於路、或寢或興、恆論乎此、"],[5,6,8,"擊於手以爲號、戴於額以爲飾、"],[5,6,9,"書於爾室門柱、及爾邑門、○"],[5,6,10,"昔爾上帝耶和華、誓於爾祖亞伯拉罕以撒雅各、賜爾之地、旣導爾入、使得大而且美之邑、非爾所自建者、"],[5,6,11,"得其第宅、充以嘉物、非爾所自充者、得已鑿之井、非爾所自鑿者、得所植之葡萄園、橄欖樹、非爾所自植者、爾食之而飽、"],[5,6,12,"當斯時也、愼勿忘耶和華、卽導爾出埃及、脫於奴隸之室者、"],[5,6,13,"宜寅畏爾上帝耶和華、而崇事之、指其名而發誓、"],[5,6,14,"勿從四周諸民之神、"],[5,6,15,"恐爾上帝耶和華震怒、滅爾於地、蓋在爾中之上帝耶和華、乃忌邪之上帝也、○"],[5,6,16,"勿試爾上帝耶和華、如昔在瑪撒然、"],[5,6,17,"爾上帝耶和華所諭爾之誡命法度典章、爾當恪守、"],[5,6,18,"凡耶和華所視爲正爲善者、爾宜行之、致受福祉、可入而得耶和華所誓許爾祖之美地、"],[5,6,19,"耶和華亦必驅逐諸敵、踐其前言、○"],[5,6,20,"厥後爾子若問爾曰、我上帝耶和華、以此法度典章律例諭爾、其意云何、"],[5,6,21,"必告之曰、我儕昔在埃及、爲法老之奴隸、耶和華以大能手、導我出之、"],[5,6,22,"在我目前、施行旣大且劇之異蹟奇事於埃及、與法老及其全家、"],[5,6,23,"導我出彼、俾入其所誓許我祖、錫我之地、"],[5,6,24,"故耶和華命我守此典章、寅畏我上帝耶和華、永享福祚、保全生命、有如今日、"],[5,6,25,"我儕若守我上帝耶和華所諭之誡命、而遵行之、是卽我之義也、"],[5,7,1,"迨爾上帝耶和華、導爾入所往據之地、驅逐諸族、卽赫人、革迦撒人、亞摩利人、迦南人、比利洗人、希未人、耶布斯人、此七族較爾強大、"],[5,7,2,"爾上帝耶和華旣付於爾、爲爾所擊、必殲滅之、勿與立約、勿加矜恤、"],[5,7,3,"勿相嫁娶、爾女勿嫁其子、爾子勿娶其女、"],[5,7,4,"彼必誘爾子、不從耶和華、而事他神、致耶和華震怒、滅爾甚速、"],[5,7,5,"爾當毀其壇、碎其柱像、斫其木偶、火其雕像、必如是待之、"],[5,7,6,"蓋爾乃爾上帝耶和華之聖民、爾上帝耶和華於寰區億兆中、特選爾爲己民、"],[5,7,7,"耶和華悅爾選爾、非爲爾多於他邦之民、爾數較之維寡、"],[5,7,8,"惟因耶和華悅爾、欲踐所誓爾祖之言、以大能手導爾出、贖爾於奴隸之室、拯爾於埃及王法老之手、"],[5,7,9,"當知惟爾上帝耶和華爲上帝、乃信實之上帝、愛之而守其誡者、彼必爲之踐約施恩、迄於千代、"],[5,7,10,"惡之者、彼必報之、滅之、凡惡之者、必報弗緩、"],[5,7,11,"故我今所諭爾之誡命、典章律例、爾宜謹守遵行、○"],[5,7,12,"爾若聽從律例、而遵行之、則爾上帝耶和華、必踐與爾祖以誓而立之約、施恩於爾、"],[5,7,13,"亦必眷愛爾、福祚爾、昌熾爾、且於誓許爾祖、賜爾之地、錫嘏爾身所出、爾土所產、及爾穀酒與油、使爾牛羊蕃滋、"],[5,7,14,"爾將蒙福、勝於萬民、男女牲畜、無不生育、"],[5,7,15,"耶和華必除爾諸病、爾所識埃及之惡疾、不加諸爾、而加諸敵、"],[5,7,16,"爾上帝耶和華所付爾之民、必翦滅之、勿加顧惜、勿事其神、蓋爲爾之坎阱、○"],[5,7,17,"爾若意謂、此諸族較多於我、何能驅逐、"],[5,7,18,"勿懼之、當憶爾上帝耶和華、所行於法老與埃及之事、"],[5,7,19,"卽爾所目覩之試鍊、異蹟、奇事、能手、奮臂、爾上帝耶和華用以導爾出者、爾所懼之諸族、爾上帝耶和華亦必如是待之、"],[5,7,20,"爾上帝耶和華必使大蜂至其中、迨藏匿之遺民、滅於爾前、"],[5,7,21,"勿因之而懼、爾上帝耶和華在爾中、乃大而可畏之上帝、"],[5,7,22,"爾上帝耶和華將漸逐斯族、勿速滅之、恐野獸孳生而害爾、"],[5,7,23,"爾上帝耶和華必以之付爾、大擾亂之、至於盡絕、"],[5,7,24,"亦付其王於爾手、爾必滅其名於天下、莫能禦爾、迨爾殲之、"],[5,7,25,"其神之雕像、必焚以火、其上金銀、勿貪勿取、免爾因此陷於坎阱、以其爲爾上帝耶和華所惡也、"],[5,7,26,"可憎之物、勿攜入室、恐爾亦成爲當滅者、與物無異、必憾之甚、憎之極、以其爲當滅之物也、"],[5,8,1,"我今所諭諸誡、爾必謹守遵行、得以生存繁衍、入耶和華所誓爾祖之地、據以爲業、"],[5,8,2,"當憶爾上帝耶和華、此四十年、於野導爾之路、卑抑爾、試驗爾、欲知爾心、守其誡否、"],[5,8,3,"彼卑抑爾、任爾饑餓、食以瑪那、爾與爾祖所未識者、俾知人之生、不第恃食、惟恃耶和華口所出之言、"],[5,8,4,"此四十年、爾衣不敝、爾足不腫、"],[5,8,5,"當思爾上帝耶和華督責爾、如人督責其子、"],[5,8,6,"必寅畏爾上帝耶和華、守其誡、行其道、"],[5,8,7,"爾上帝耶和華導爾入腴壤、其地有溪、有泉有源、自陵與谷而出、"],[5,8,8,"有小麥、麰麥、葡萄、無花果、石榴、橄欖諸樹、與蜜、"],[5,8,9,"爾在斯土、糧食罔缺、無所匱乏、其石乃鐵、其山出銅、"],[5,8,10,"必食而飽、因所賜之腴壤、頌美爾上帝耶和華、"],[5,8,11,"愼勿忘爾上帝耶和華、不守其誡命、律例典章、卽我今日所諭爾者、"],[5,8,12,"恐爾飽食、華屋而居、"],[5,8,13,"牛羊蕃滋、金銀增益、所有之物、旣豐且盛、"],[5,8,14,"心遂高傲、忘爾上帝耶和華、導爾出埃及、脫於奴隸之室、"],[5,8,15,"引爾經歷大而可畏之野、中有火蛇與蠍、旱乾無水之域、爲爾使堅石出水、"],[5,8,16,"又於野間、食爾以瑪那、乃爾祖所未識者、卑抑爾、試驗爾、俾終獲福、"],[5,8,17,"恐爾自謂、得此貨財、乃我之能、與我之力、"],[5,8,18,"當憶爾上帝耶和華、因彼賜爾以力、俾得貨財、以踐所誓爾祖之約、有如今日、"],[5,8,19,"如爾忘爾上帝耶和華、而從他神、事之拜之、必致滅亡、今日我以戒爾、"],[5,8,20,"耶和華滅諸族於爾前、爾曹亦必如是見滅、因不聽爾上帝耶和華命故也、"],[5,9,1,"以色列歟、爾其聽之、爾今濟約但、據有其國、其民較爾強大、其邑宏廣、其垣參天、"],[5,9,2,"其民乃亞衲族、軀幹修偉、爾所識者、亦嘗聞語云、孰能敵亞衲族乎、"],[5,9,3,"今當知爾上帝耶和華必如烈火、爲爾先導、毀敗之、伏之於爾前、爾則驅逐之、速滅之、如耶和華所諭爾者、"],[5,9,4,"爾上帝耶和華旣驅逐之、爾勿意謂因我有義、故耶和華導我入據斯土、實因斯族之惡、而驅逐之、"],[5,9,5,"爾之入據其地、非爲爾義、及心之正、乃爾上帝耶和華因斯族之惡、而驅逐之、以踐所誓爾祖亞伯拉罕以撒雅各之言、"],[5,9,6,"當知爾上帝耶和華非爲爾義、錫爾沃壤爲業、爾乃強項之民、"],[5,9,7,"當憶弗忘、爾在曠野、激爾上帝耶和華之怒、自出埃及至此、爾違逆耶和華、"],[5,9,8,"爾在何烈、激耶和華怒、耶和華意欲滅爾、"],[5,9,9,"當時我登山受石版、卽耶和華與爾所立之約、居山四十晝夜、不食不飲、"],[5,9,10,"耶和華授我二石版、其上所載、乃上帝手書者、卽爾大會之日、耶和華在山、由火中諭爾之言、"],[5,9,11,"四十晝夜後、耶和華以盟約之二版授我、"],[5,9,12,"諭曰、爾其速下、爾之民、爾所導出埃及者、已自敗壞、我所諭之道、彼速違之、爲己鑄像、"],[5,9,13,"又曰、我觀斯民、強項者流、"],[5,9,14,"爾且聽我、我殲滅之、塗其名於天下、使爾後裔爲國、較彼尤大且強、"],[5,9,15,"我轉而下山、厥火炎炎、盟約之版、在於我手、"],[5,9,16,"我乃望見、爾獲罪於爾上帝耶和華、鑄造犢像、速違耶和華所諭之道、"],[5,9,17,"我擲手中二版、碎於爾前、"],[5,9,18,"如昔伏於耶和華前、四十晝夜、不食不飲、因爾犯罪行惡、激耶和華怒、"],[5,9,19,"耶和華忿怒威烈、將殲滅爾、我畏懼之、然彼尚允我所祈、"],[5,9,20,"時、耶和華甚怒亞倫、將行翦滅、我爲之祈、"],[5,9,21,"爾之罪戾、卽造犢像、我燬之以火、擣磨成塵、揚於自山而流之溪、"],[5,9,22,"爾在他備拉、瑪撒、基博羅哈他瓦、激耶和華怒、"],[5,9,23,"耶和華命爾離加低斯巴尼亞、曰、往得我所賜爾之地、是時爾乃逆爾上帝耶和華、不信其言、不聽其命、"],[5,9,24,"自我識爾之日、爾違逆耶和華、"],[5,9,25,"我因耶和華言、必殲滅爾、伏於耶和華前、四十晝夜、"],[5,9,26,"我禱耶和華曰、主耶和華歟、勿滅爾民爾業、爾所贖以大威、以大能導出埃及者、"],[5,9,27,"求憶爾僕亞伯拉罕以撒雅各、勿視斯民之剛愎、及其邪惡罪愆、"],[5,9,28,"恐爾導我所出之地、其民曰、耶和華因不能導斯民入其所許之地、又因憾之、故導之出、滅之於野、"],[5,9,29,"然彼誠爲爾民爾業、爾以大能奮臂導出者也、"],[5,10,1,"維時、耶和華諭我曰、爾琢石版二、其式如前、陟山詣我、且以木作匱、"],[5,10,2,"爾前所碎之版、我復書其文於此版、爾置於匱、"],[5,10,3,"我遂以皂莢木造匱、又琢石版二、其式如前、執以登山、"],[5,10,4,"耶和華乃循其前文、以爾大會之日、在山由火中所諭爾之十誡、書於版以賜我、"],[5,10,5,"我轉而下山、置諸所造之匱、遵耶和華所命、至今猶存、○"],[5,10,6,"以色列人自比羅比尼亞干啟行、至摩西拉、亞倫死、葬於彼、其子以利亞撒繼任祭司之職、"],[5,10,7,"由此啟行、至谷歌大、自谷歌大至約巴他、其地有溪、"],[5,10,8,"時、耶和華區別利未支派、使舁耶和華約匱、立於耶和華前、以崇事之、奉其名而禱祝、迄於今日、"],[5,10,9,"故利未人在昆弟中、無分無業、耶和華爲其業、循爾上帝耶和華所言、"],[5,10,10,"我居於山、四十晝夜如昔、此次耶和華又復垂聽、不殲滅爾、"],[5,10,11,"耶和華諭我曰、爾其啟行、導民入據我所誓許厥祖、賜彼之地、○"],[5,10,12,"以色列人歟、爾上帝耶和華何求於爾、第寅畏之、遵行其道、一心一意、愛之事之、"],[5,10,13,"守耶和華之誡命典章、我今日所諭爾者、俾爾獲益、"],[5,10,14,"天與天上之天、地與地上所有、俱屬爾上帝耶和華、"],[5,10,15,"惟耶和華悅爾祖而愛之、於萬民中、選其苗裔卽爾、有如今日、"],[5,10,16,"故當祛除爾心之汚、勿復強項、"],[5,10,17,"蓋爾上帝耶和華、爲萬神之神、萬主之主、惟皇上帝、有能可畏、不偏視、不受賄、"],[5,10,18,"爲孤寡行鞫、爲羇旅施仁、賜之衣食、"],[5,10,19,"爾亦當愛旅人、緣爾曾旅於埃及、"],[5,10,20,"當寅畏爾上帝耶和華、事之附之、指其名而發誓、"],[5,10,21,"彼乃爾所頌美、爾之上帝、爲爾行此大而可畏之事、爾所目擊、"],[5,10,22,"昔爾列祖下埃及時、惟七十人、今爾上帝耶和華、使爾如天星之多焉、"],[5,11,1,"故當愛爾上帝耶和華、恆守其諭、及其典章、律例誡命、"],[5,11,2,"爾之子女、我不與之言、因其未知未見爾上帝耶和華之督責、及其大威、能手奮臂、"],[5,11,3,"異蹟奇事、所行於埃及法老王、與其全國、"],[5,11,4,"及於埃及軍旅車馬追爾時、使紅海之水覆沒之、翦滅之、以迄今日、"],[5,11,5,"爾由曠野至此、所行於爾、"],[5,11,6,"及於流便裔、以利押子大坍、亞比蘭、使地啟口吞之、與其眷屬、帷幕人物、絕於以色列族中、"],[5,11,7,"耶和華所爲之大事、惟爾目擊、"],[5,11,8,"故我今日所諭爾之誡命、爾當恪守、致強厥志、以入所往而得之地、"],[5,11,9,"延年於耶和華誓賜爾祖、及其後裔之土、卽流乳與蜜之地、"],[5,11,10,"爾所出之埃及地、旣播其種、以足導水灌之、如灌蔬圃、"],[5,11,11,"惟爾所往而得之地不然、乃有陵谷、自受天雨、"],[5,11,12,"乃爾上帝耶和華眷顧之地、自年始迄歲終、垂顧不已、○"],[5,11,13,"我今所諭之誡命、爾若聽從、愛爾上帝耶和華、一心一意而奉事之、"],[5,11,14,"則必降雨於地、春秋以時、使爾獲穀、及酒與油、食之而飽、"],[5,11,15,"野有草萊、以養牲畜、"],[5,11,16,"爾其愼之、勿受惑而轉移、崇事他神、"],[5,11,17,"致耶和華震怒擊爾、使天閉塞不雨、物產不生、爾則於耶和華所賜之美地、必速滅亡、"],[5,11,18,"故爾必以我言、藏於衷、存於心、繫於手以爲號、戴於額以爲飾、"],[5,11,19,"誨爾子女、坐於室、行於路、或寢或興、恆論乎此、"],[5,11,20,"書於爾室門柱、及爾邑門、"],[5,11,21,"俾爾與子、增加時日、於耶和華誓賜爾祖之地、如天覆地之久、"],[5,11,22,"若守我所諭爾之誡命、於爾上帝耶和華愛之附之、而行其道、"],[5,11,23,"則耶和華必於爾前、逐此較爾強大之族、使爾據有其土、"],[5,11,24,"爾足所履之地、必爲爾有、自曠野至利巴嫩、自伯拉大河至西海、悉爲爾境、"],[5,11,25,"必無人能禦爾、於爾所履之地、爾上帝耶和華、必使其民悚懼恐惶、以踐其言、○"],[5,11,26,"今日我以祝與詛置於爾前、"],[5,11,27,"爾若聽爾上帝耶和華之誡命、卽我所諭爾者、則必受祝、"],[5,11,28,"若弗聽之、轉離我今所諭爾之道、而從素所未識之神、則必受詛、"],[5,11,29,"旣至爾上帝耶和華導入爲業之地、當以祝詞宣於基利心山、以詛詞宣於以巴路山、"],[5,11,30,"此二山、非在約但西、日入之處、居亞拉巴之迦南人境內、與吉甲相對、近摩利之橡林乎、"],[5,11,31,"爾將渡約但、入據爾上帝耶和華所賜之地、而居於彼、"],[5,11,32,"我今陳於爾前之典章律例、當謹守遵行焉、"],[5,12,1,"爾在爾祖之上帝耶和華所賜之地、畢生所當守之典章律例、我今諭爾、"],[5,12,2,"爾所驅逐諸族、事神之處、或山邱之上、或綠樹之下、俱當毀滅、"],[5,12,3,"毀其壇、碎其柱像、焚其木偶、斫其雕像、滅其名於斯土、"],[5,12,4,"勿效其俗、以事爾上帝耶和華、"],[5,12,5,"爾上帝耶和華於爾支派中、所選寄名之處、爾當詣而求之、"],[5,12,6,"奉獻爾之燔祭、他祭、所應輸之什一、舉祭、許願祭、樂獻祭、及首生之牛羊、"],[5,12,7,"在彼食於爾上帝耶和華前、與爾眷屬、樂乎爾手所爲、卽爾上帝耶和華錫嘏之事、"],[5,12,8,"我今在此、各行其是、後勿復爾、"],[5,12,9,"爾上帝耶和華賜爾安居爲業之地、爾尚未至、"],[5,12,10,"旣渡約但、居於爾上帝耶和華使爾所據之地、脫於四周諸敵之擾、得其綏安、"],[5,12,11,"所命爾之燔祭、他祭、所應輸之什一、舉祭、及許願於耶和華之美祭、俱當攜之、至爾上帝耶和華所選寄名之處、"],[5,12,12,"爾與子女僕婢、及居爾邑無分無業之利未人、咸樂於爾上帝耶和華前、"],[5,12,13,"愼勿隨在獻爾燔祭、"],[5,12,14,"惟當獻於耶和華在爾支派中所選之處、在彼行我所命、"],[5,12,15,"然於諸邑、可以隨意宰牲食肉、依爾上帝耶和華所賜之福、潔與不潔之人、俱可食之、猶食獐鹿、"],[5,12,16,"惟勿食血、必傾於地、有如傾水、"],[5,12,17,"穀與酒油之什一、首生之牛羊、許願祭、樂獻祭、舉祭、不可食於諸邑、"],[5,12,18,"惟於爾上帝耶和華所選之處、爾與子女僕婢、及居爾邑之利未人食之、樂乎爾手所爲、於爾上帝耶和華前、"],[5,12,19,"爾其愼之、居於斯土、畢生勿遺利未人、○"],[5,12,20,"迨爾上帝耶和華踐其前言、闢爾土宇、如爾意謂、我欲食肉、則可隨其所欲、"],[5,12,21,"若爾上帝耶和華所選寄名之處、離爾甚遠、則可取耶和華所賜爾之牛羊宰之、隨意食於諸邑、循我所命、"],[5,12,22,"食之如食獐鹿、潔與不潔之人、俱可食之、"],[5,12,23,"惟當決志、勿食其血、蓋血乃生命也、不可倂生命而食之、"],[5,12,24,"必傾於地、有如傾水、"],[5,12,25,"毋食之、以行耶和華所視爲正者、而享福祉、爰及子孫、"],[5,12,26,"惟爾所有聖物、與許願所獻者、必攜至耶和華所選之處、"],[5,12,27,"燔祭之肉與血、當獻於爾上帝耶和華之壇、此外犧牲之血、必傾於壇、而食其肉、"],[5,12,28,"我所命爾之言、當聽而守之、致行爾上帝耶和華所視爲善爲正者、而享福祉、爰及子孫、歷世靡曁、○"],[5,12,29,"迨爾上帝耶和華、在爾將往而據之地、滅其族於爾前、爾得其地而居之、"],[5,12,30,"彼旣滅於爾前、爾當愼之、勿受誘而從之、勿問其神、自謂斯族若何事神、我亦如之、"],[5,12,31,"爾事爾上帝耶和華、不可效之、蓋耶和華所憎之惡事、彼悉行之於其神、至以子女焚而獻之、"],[5,12,32,"凡我所諭爾者、爾必謹守遵行、毋增毋減、"],[5,13,1,"如爾中有先知、或作夢者起、施行異蹟奇事、"],[5,13,2,"所言有驗、遂語爾曰、宜從他神而事之、乃爾素所未識者、"],[5,13,3,"毋聽其言、蓋爾上帝耶和華試爾、欲知爾果一心一意、愛爾上帝耶和華否、"],[5,13,4,"當順從爾上帝耶和華、而寅畏之、守其誡、聽其命、事之附之、"],[5,13,5,"爾上帝耶和華導爾出埃及、脫於奴隸之室、惟彼先知、與作夢者、以言逆之、誘爾違爾上帝耶和華所命行之道、則必殺之、以除爾中之惡、○"],[5,13,6,"如爾同母兄弟、或爾子女、或懷中之妻、或如命之友、私誘爾曰、我其往事他神、爾與爾祖所未識者、"],[5,13,7,"卽爾四周諸族之神、或近或遠、自地極至天涯、"],[5,13,8,"爾毋從之、毋聽之、毋惜之、毋恤之、毋匿之、必殺勿赦、"],[5,13,9,"爾先加手擊之、衆後擊之、"],[5,13,10,"爾上帝耶和華導爾出埃及、脫於奴隸之室、彼欲誘爾離之、故當以石擊之致死、"],[5,13,11,"以色列衆聞之必懼、不復行此惡於爾中、○"],[5,13,12,"爾上帝耶和華賜爾諸邑、俾爾居之、"],[5,13,13,"若聞一邑之中、有匪類出、誘居民曰、我其往事他神、乃爾所未識者、"],[5,13,14,"則當究問詳察、如得其情、果於爾中有此可惡之事、"],[5,13,15,"必以刃擊其邑民、與其牲畜、及凡所有、而殄滅之、"],[5,13,16,"聚其貨財於衢、爲爾上帝耶和華焚之、並焚其邑、俾爲邱墟、毋得再建、"],[5,13,17,"應滅之物、毋少存於爾手、使耶和華息其烈怒、矜爾恤爾、俾爾昌熾、踐其所誓爾祖之言、"],[5,13,18,"緣爾聽爾上帝耶和華之言、守我今日所諭之誡、行其所視爲正者也、"],[5,14,1,"爾曹皆爾上帝耶和華之子、毋爲死者割肉薙額、"],[5,14,2,"蓋爾乃爾上帝耶和華之聖民、耶和華於天下萬民中、特選爾爲己民、○"],[5,14,3,"可憎之物、爾不可食、"],[5,14,4,"畜中所可食者、牛與綿羊山羊、"],[5,14,5,"鹿、獐、赤鹿、麕、麢羊、麈、麋、"],[5,14,6,"畜之分蹄支趾而反齧者、可食、"],[5,14,7,"惟反齧分蹄之畜中、有不可食者、若駝、兔、沙番、反齧而不分蹄、當以爲不潔、"],[5,14,8,"豕雖分蹄、而不反齧、當以爲不潔、斯畜之肉毋食、其尸毋捫、○"],[5,14,9,"水中百族、有翅有鱗者、俱可食、"],[5,14,10,"無翅無鱗者、不可食、當以爲不潔、"],[5,14,11,"羽族之潔者、俱可食、"],[5,14,12,"其不可食者、卽鷹、鶚、鵰、"],[5,14,13,"鳶、鸇、鷂、與其類、"],[5,14,14,"鴉、與其類、"],[5,14,15,"鴕鳥、夜鷹、魚鷹、雀鷹、與其類、"],[5,14,16,"鸕鶿、鷺鷥、角鴟、"],[5,14,17,"鵜鶘、爰居、魚狗、"],[5,14,18,"白鶴、蒼鷺、與其類、戴鵀、蝙蝠、"],[5,14,19,"凡飛蟲、必以爲不潔、不可食、"],[5,14,20,"羽族之潔者、俱可食、○"],[5,14,21,"爾乃爾上帝耶和華之聖民、凡自斃之物不可食、旅於爾中者、可予之食、鬻於外人亦可、毋以羔母之乳烹羔、○"],[5,14,22,"每歲播種所產、田疇所出、當什輸其一、"],[5,14,23,"爾穀與酒與油、什輸其一、及牛羊之首生者、皆必食於爾上帝耶和華前、在其所選寄名之處、以習恆畏爾上帝耶和華、"],[5,14,24,"爾上帝耶和華錫爾嘏時、如其所選寄名之處、離爾甚遠、不能攜之至彼、"],[5,14,25,"則必易之以金、包而執之、往爾上帝耶和華所選之處、"],[5,14,26,"以金市物、牛羊、清酒、醇醪、隨心所欲、食於爾上帝耶和華前、與爾眷屬同樂、"],[5,14,27,"居於爾邑之利未人、無分無業、亦勿遺之、○"],[5,14,28,"每三年中、必以是年所產、什輸其一、貯於爾邑、"],[5,14,29,"使無分無業之利未人、與居爾邑之賓旅、以及孤寡、皆來食之而飽、致爾上帝耶和華、於爾凡百所爲、錫嘏於爾、"],[5,15,1,"每屆七年、當有豁免、"],[5,15,2,"其例如左、耶和華之豁免、旣經布告、凡借貸於鄰者、必豁免之、不索其償、"],[5,15,3,"如外人可索之、惟屬己之物、貸於兄弟者、則當豁免、"],[5,15,4,"爾若聽爾上帝耶和華之命、守我今日所諭爾之誡、則爾中必無貧乏者、蓋爾上帝耶和華、必在所賜爲業之地、錫嘏於爾、"],[5,15,5,"爾若聽爾上帝耶和華之命、守我今日所諭爾之誡、則爾中必無貧乏者、蓋爾上帝耶和華、必在所賜爲業之地、錫嘏於爾、"],[5,15,6,"爾上帝耶和華必踐其言、錫嘏於爾、爾則貸金於列邦、不貸列邦之金、可轄列邦、不受列邦之轄、○"],[5,15,7,"爾上帝耶和華賜爾之地、無論何邑、有窮乏之昆弟、毋頑爾心、握手而不之濟、"],[5,15,8,"必啟爾手、貸之以補其缺、"],[5,15,9,"愼勿惡念是懷、謂七年豁免之期伊邇、遂睥睨貧乏之昆弟、而弗之給、致彼籲耶和華、歸罪於爾、"],[5,15,10,"爾必給之、給時心不憂鬱、爲此之故、爾上帝耶和華、必於凡爾所行、及手所爲、錫嘏於爾、"],[5,15,11,"其地不無貧人、故我命爾、必啟爾手、以濟境內窮乏之昆弟、○"],[5,15,12,"如爾昆弟希伯來人、或男或女鬻於爾、服役六年、越至七年、必釋之、"],[5,15,13,"旣釋之、毋使徒手而去、"],[5,15,14,"必由羊羣、禾場、酒醡、取而予之、依爾上帝耶和華錫嘏於爾者、從優給之、"],[5,15,15,"當憶爾昔在埃及爲奴、爾上帝耶和華贖爾、故我今日以此諭爾、"],[5,15,16,"僕若愛爾及爾家、以與爾同居爲善、謂爾、不願離爾而去、"],[5,15,17,"則當取錐貫耳於門、俾其永爲爾僕、待婢亦然、"],[5,15,18,"彼事爾六年、較之傭人、其值維倍、故釋之時、勿以爲難、爾上帝耶和華、必於凡爾所爲、錫嘏於爾、○"],[5,15,19,"牛羊首生之牡者、當區別爲聖、獻於爾上帝耶和華、首生之牛、毋令其耕、首生之羊、毋剪其毛、"],[5,15,20,"爾與眷屬、每歲於爾上帝耶和華所選之處食之、"],[5,15,21,"如有殘缺、或跛或瞽、無論何疵、不可以祭爾上帝耶和華、可於爾邑食之、潔與不潔之人、俱可食之、如食獐鹿、"],[5,15,22,"惟毋食其血、必傾於地、有如傾水、"],[5,16,1,"屆亞筆月、必爲爾上帝耶和華守逾越節、因於是月之夜、爾上帝耶和華導爾出埃及、"],[5,16,2,"必在耶和華所選寄名之處、獻牛羊於爾上帝耶和華、以爲逾越之祭、"],[5,16,3,"毋食有酵之餅、七日之內、必食無酵餅、卽困苦餅、以爾昔出埃及維速、當憶是日、畢生勿忘、"],[5,16,4,"七日間、爾四境毋存酵、首日薄暮、所獻祭肉、毋留於明晨、"],[5,16,5,"勿於爾上帝耶和華所賜諸邑、獻逾越之祭、"],[5,16,6,"惟獻於爾上帝耶和華所選寄名之處、在薄暮日入時、卽爾出埃及時也、"],[5,16,7,"在爾上帝耶和華所選之處、烹而食之、明晨歸於己幕、"],[5,16,8,"六日間、必食無酵餅、越至七日、必有肅會、以事爾上帝耶和華、是日不可操作、○"],[5,16,9,"當核七七日、自刈麥之首日始、"],[5,16,10,"守七七節、以事爾上帝耶和華、依爾上帝耶和華所錫之嘏、以樂獻祭奉之、"],[5,16,11,"爾與子女僕婢、曁居爾中之利未人、以及賓旅孤寡、咸在爾上帝耶和華所選寄名之處、樂於其前、"],[5,16,12,"爾當追憶、昔在埃及爲奴、必守此典、而遵行之、○"],[5,16,13,"禾場酒醡所出、爾旣斂藏、當守構廬節七日、"],[5,16,14,"節期之間、爾與子女僕婢、曁居爾邑之利未人、以及賓旅孤寡、俱必喜樂、"],[5,16,15,"七日必守節於爾上帝耶和華前、在其所選之處、蓋爾上帝耶和華、於爾物產、及凡所爲、錫嘏於爾、必當喜樂不勝、"],[5,16,16,"除酵節、七七節、構廬節、爾之丁男、每歲三覲爾上帝耶和華、於其所選之處、毋徒手而至、"],[5,16,17,"各依爾上帝耶和華所錫之嘏、隨力以獻、○"],[5,16,18,"於爾上帝耶和華所賜之邑、按各支派、設立士師、有司、秉公鞫民、"],[5,16,19,"毋反其正、毋偏視人、毋受賄賂、蓋賄賂使明者目盲、義者詞屈、"],[5,16,20,"必循至公、則可生存、得爾上帝耶和華所錫之土、"],[5,16,21,"爲爾上帝耶和華築壇、毋樹木偶於側、"],[5,16,22,"毋立柱像、乃爾上帝耶和華所惡者也、"],[5,17,1,"牛羊如有殘缺、或有惡疾、勿獻於爾上帝耶和華、蓋此爲爾上帝耶和華所惡也、○"],[5,17,2,"在爾上帝耶和華所賜之邑、爾中如有男女、作惡於爾上帝耶和華前、違背其約、"],[5,17,3,"往事他神、而崇拜之、或日月、或天象、非我所命者、"],[5,17,4,"或以告爾、爾旣聞之、則必詳察、如得其情、果於以色列中、有此可惡之事、"],[5,17,5,"必攜行惡之男女、至於邑門、以石擊之致死、"],[5,17,6,"當殺之人、必有二三人爲證、則可殺、證人惟一、則不可、"],[5,17,7,"證者先加手擊之、衆後擊之、以除爾中之惡、○"],[5,17,8,"如爾邑中有訟事、爲流血、爲爭競、爲鬬毆、爾所難鞫者、則當詣爾上帝耶和華所選之處、"],[5,17,9,"見利未人祭司、與在位之士師、而詢問之、彼必示爾如何判斷、"],[5,17,10,"在耶和華所選之處、凡其所示所教者、爾當遵行、"],[5,17,11,"彼所教之法律、所示之判斷、所諭之語言、爾必遵行、毋偏於左、毋偏於右、"],[5,17,12,"有人擅行、不從立於爾上帝耶和華前服役之祭司、或不從士師、其人必死、除惡於以色列中、"],[5,17,13,"民衆聞此必懼、不復擅行、○"],[5,17,14,"旣至爾上帝耶和華所錫之地、據而居之、意謂必立王以治我、如四周之國然、"],[5,17,15,"則必以爾上帝耶和華所選者、立之爲王、必爾同儕方可、外族之人不可治爾、"],[5,17,16,"王勿增馬、勿使民返埃及、以增其馬、蓋耶和華曾諭爾曰、不可復往此途、"],[5,17,17,"毋多置妃嬪、恐致心偏、毋廣積金銀、"],[5,17,18,"旣登國位、當從利未人祭司所存之法律、錄爲一册、"],[5,17,19,"置於其側、畢生誦之、以習寅畏其上帝耶和華、遵守法律之言、及厥典章、"],[5,17,20,"免其對於昆弟、中心驕矜、違此誡命、偏於左右、則可延年於國、在以色列中、爰及子孫、"],[5,18,1,"利未人祭司、及其全支派、在以色列中無分無業、可食獻於耶和華之火祭、及其產業、"],[5,18,2,"彼在昆弟中無業、耶和華爲其業、如其所諭、"],[5,18,3,"民獻祭、或牛或羊、祭司所當得者、前腿兩頰與胃、"],[5,18,4,"初熟之穀、及酒與油、首剪之羊毛、亦必給之、"],[5,18,5,"蓋爾上帝耶和華於爾諸支派中、選彼及其子孫、藉耶和華之名、侍立服役、歷世靡曁、○"],[5,18,6,"如有利未人離其所居以色列之邑、一心願至耶和華所選之處、"],[5,18,7,"則亦可藉其上帝耶和華之名、以供役事、如其昆弟立於耶和華前之利未人然、"],[5,18,8,"分其所得之食、而己鬻祖業所得之金不與焉、○"],[5,18,9,"旣至爾上帝耶和華所賜之地、勿效其民所爲可惡之事、"],[5,18,10,"凡使子女經火者、卜筮者、觀兆者、用法術者、行邪術者、"],[5,18,11,"持咒者、交鬼者、爲覡者、招魂者、勿留之於爾中、"],[5,18,12,"凡行此者、皆爲耶和華所惡、諸族行此可惡之事、故爾上帝耶和華逐之於爾前、"],[5,18,13,"爾於爾上帝耶和華、當爲純全之人、"],[5,18,14,"爾所將逐之族、聽從觀兆者、卜筮者、惟爾上帝耶和華、不容爾行是、"],[5,18,15,"爾上帝耶和華將於爾昆弟中、爲爾挺生先知若我、爾宜聽之、"],[5,18,16,"昔在何烈大會之日、爾求爾上帝耶和華曰、我上帝耶和華之聲、勿使再聞、烈火勿令復見、免我死亡、"],[5,18,17,"時、耶和華諭我曰、彼所言者善也、"],[5,18,18,"我將於其昆弟中、爲彼挺生先知如爾、以我言授於其口、使以我命悉告於衆、"],[5,18,19,"彼藉我名所傳之言、凡不聽從者、我必討之、"],[5,18,20,"如有先知擅藉我名、言我所未諭者、或藉他神之名而言、必致之死、"],[5,18,21,"如爾意謂、耶和華所未諭之言、何以知之、"],[5,18,22,"凡先知藉耶和華之名而言、事有不成不驗、則非耶和華之言、乃先知自擅而言耳、爾勿畏之、"],[5,19,1,"爾上帝耶和華旣滅諸族、以地錫爾、使爾繼之、居於其邑、其室、"],[5,19,2,"則當於爾上帝耶和華所賜爲業之地、區別三邑、"],[5,19,3,"以其所賜之地、分爲三區、修築道途、俾誤殺人者可遁於彼、"],[5,19,4,"誤殺人者遁於彼而得生、有定例焉、素無仇怨、而誤殺人、"],[5,19,5,"如人結侶入林伐木、斫時斧脫於柯、中侶致死、其人必遁於斯邑而得生、"],[5,19,6,"免報復者、心急追之、以路遙遠、及而殺之、然彼與見殺者、素無仇怨、罪不應死、"],[5,19,7,"故我諭爾區別三邑、"],[5,19,8,"我今所諭之命、爾果謹守、愛爾上帝耶和華、恆行其道、蒙爾上帝耶和華踐其所誓爾祖之言、恢廓爾境、以所許賜爾祖之地錫爾、則必於三邑之外、別設三邑、"],[5,19,9,"我今所諭之命、爾果謹守、愛爾上帝耶和華、恆行其道、蒙爾上帝耶和華踐其所誓爾祖之言、恢廓爾境、以所許賜爾祖之地錫爾、則必於三邑之外、別設三邑、"],[5,19,10,"免無辜之血、流於爾上帝耶和華所賜爲業之地、流血之罪歸爾、"],[5,19,11,"如人憾其鄰里、伏而擊之致死、逃於斯邑之一、"],[5,19,12,"其邑之長老、必遣人執之、付於報復者之手、而致之死、"],[5,19,13,"爾勿惜之、必除無辜之血於以色列中、俾爾獲福、○"],[5,19,14,"爾於爾上帝耶和華所賜之地、旣得爲業、則鄰里之界址、前人所定者、毋得遷移、○"],[5,19,15,"人有所犯、無論何罪、證者惟一、毋聽之、必憑二三證者之言、以定其讞、"],[5,19,16,"如有妄證、起而罪人、"],[5,19,17,"訟者二人當就耶和華、立於當時之祭司士師前、"],[5,19,18,"士師詳察、其證果僞、欲害昆弟、"],[5,19,19,"則必以其所欲加諸昆弟者、加乎其身、以除惡於爾中、"],[5,19,20,"他人聞之必懼、不復行此惡事、"],[5,19,21,"爾毋惜之、必以命償命、目償目、齒償齒、手償手、足償足、"],[5,20,1,"爾出與敵戰、見車馬人民、較爾尤衆、毋畏之、蓋爾上帝耶和華、導爾出埃及者偕爾、"],[5,20,2,"臨陳時、祭司當至民前、"],[5,20,3,"告之曰、以色列歟、爾其聽之、今日臨敵而戰、毋怯心、毋畏懼、毋戰慄、毋因敵而驚恐、"],[5,20,4,"蓋爾上帝耶和華與爾偕往、攻敵拯爾、"],[5,20,5,"族長當告民曰、築室未賀者可歸、免亡於陳、而他人賀之、"],[5,20,6,"植葡萄園、未食其果者可歸、免亡於陳、而他人食之、"],[5,20,7,"聘妻未娶者可歸、免亡於陳、而他人娶之、"],[5,20,8,"族長又當告民曰、畏葸心怯者可歸、免使同儕亦喪膽、"],[5,20,9,"族長言竟、當立軍長以率衆、○"],[5,20,10,"爾臨城攻之、先告以和、"],[5,20,11,"如以和應、自啟邑門、則邑民必納貢而事爾、"],[5,20,12,"如不欲和而欲戰、則必環而攻之、"],[5,20,13,"迨爾上帝耶和華以邑付爾、必刃擊其丁男、"],[5,20,14,"惟其婦女、孩提牲畜、與邑中所有之貨財、爾可取之、爾上帝耶和華所賜敵人之物、爾可享之、"],[5,20,15,"離爾甚遠之邑、不屬斯族者、必如是待之、"],[5,20,16,"惟此諸族之邑、爾上帝耶和華賜爾爲業、凡有氣息者、勿留其一、"],[5,20,17,"赫人、亞摩利人、迦南人、比利洗人、希未人、耶布斯人、爾必盡行殄滅、循爾上帝耶和華命、"],[5,20,18,"免彼教爾、效其行於諸神可惡之事、致獲罪於爾上帝耶和華、○"],[5,20,19,"爾欲取城、環攻日久、毋以斧斫樹、其果可食、故勿伐之、田間之樹、豈人也耶、而可攻乎、"],[5,20,20,"惟爾所知非結果之樹、則可伐之、以爲營壘、迨至敵城破降之日、"],[5,21,1,"在爾上帝耶和華所錫爲業之地、若見有被殺者、臥於田間、不知誰殺、"],[5,21,2,"則爾之長老士師、必至其處、於四周之邑、度其遠近、"],[5,21,3,"最近之邑、其長老必取牝犢、未負軛服役者、"],[5,21,4,"牽至活水之谷、其地未經耕種、則於谷中折犢之頸、"],[5,21,5,"利未人祭司必適其所、蓋其爲爾上帝耶和華所簡、以供役事、藉耶和華之名、爲民祝嘏、凡諸爭競鬬毆、俱憑其言而定、"],[5,21,6,"離見殺者最近之邑、其長老必在谷中、盥手於折頸之犢上、"],[5,21,7,"曰、我手未流此血、我目亦未之見、"],[5,21,8,"耶和華歟、爾所贖之以色列族、求爾宥之、勿使無辜之血、歸於爾名、於是流血之罪得赦、"],[5,21,9,"爾行耶和華所視爲正者、則流血之罪、可除於爾中、○"],[5,21,10,"爾出與敵戰、爾上帝耶和華付之爾手、爾卽虜之、"],[5,21,11,"其間見有美女、爾戀慕之、欲納爲妻、"],[5,21,12,"可攜之歸、使薙髮修甲、"],[5,21,13,"去被虜時所衣之衣、居於爾家、哀其父母、歷至一月、然後與之同寢、成爲夫婦、"],[5,21,14,"如後不見悅於爾、可容之去、俾其自由、爾旣玷之、勿鬻而得金、勿待之若婢、○"],[5,21,15,"人有二妻、一見愛、一被惡、均生子、而被惡者之子居長、"],[5,21,16,"使子承業時、不可廢被惡者之子、而立見愛者之子爲長子、"],[5,21,17,"必認被惡者之子爲長子、倍其業以與之、蓋彼爲強健時所首生者、宜得長子之業、○"],[5,21,18,"人有悖逆之子、不聽父母之言、雖責之仍不聽、"],[5,21,19,"父母當執之、攜至其邑門長老前、"],[5,21,20,"告曰、此子悖逆、不聽我言、饕餮沉湎、"],[5,21,21,"其邑之民、必石擊之致死、以除惡於爾中、使以色列衆聞之而懼、○"],[5,21,22,"人犯死罪、而致之死、懸之於木、"],[5,21,23,"毋使其尸懸木竟夕、必是日葬之、免汚爾上帝耶和華所賜爲業之地、蓋被懸者、乃上帝所詛也、"],[5,22,1,"爾見昆弟之牛羊、迷於歧路、勿佯爲不見、必反之於昆弟、"],[5,22,2,"如昆弟離爾遠、或不相識、則牽之歸、留於爾家、待其求之、然後反之、"],[5,22,3,"其驢其衣、凡昆弟所失之物、爲爾所得、俱必如是反之、勿佯爲不見、"],[5,22,4,"爾見昆弟之牛驢、躓於途間、勿佯爲不見、必助其主起之、○"],[5,22,5,"女勿衣男衣、男勿衣女衣、凡行此者、乃爾上帝耶和華所惡也、○"],[5,22,6,"途間如遇鳥巢、在樹在地、有雛有卵、母鳥伏之、不可母子兼取、"],[5,22,7,"必縱其母、惟取其雛、則可納福、且以延年、○"],[5,22,8,"爾建新室、其頂必環以堞、免人墮落、流血之罪、歸於爾家、"],[5,22,9,"葡萄園中、勿播二種、若然、則種之所產、園之所出、俱爲聖物、○"],[5,22,10,"勿以牛驢並耕、"],[5,22,11,"勿衣麻毛雜織之衣、○"],[5,22,12,"所披之衣、當於四周、緣之以繸、○"],[5,22,13,"人若娶妻、同室後而惡之、"],[5,22,14,"謗以惡事、加以惡名、曰、我娶此女、與之同室、見非童貞、"],[5,22,15,"女之父母、必攜童貞之據、至邑門長老前、"],[5,22,16,"其父告曰、我以女適此人、而爲其所惡、"],[5,22,17,"謗以惡事、謂非童貞、然我女誠童貞、確據在此、遂展其布於長老前、"],[5,22,18,"長老必執其人而責之、"],[5,22,19,"罰金一百、予女之父、因加惡名於以色列處女故也、使女仍爲其妻、畢生不休、"],[5,22,20,"如所告屬實、童貞無據、"],[5,22,21,"乃行不端於以色列中、在父家爲妓、則必攜女至父家門、邑人以石擊之致死、以除惡於爾中、○"],[5,22,22,"人與有夫之婦同寢、爲人所見、則姦夫淫婦俱致之死、以除惡於以色列中、"],[5,22,23,"處女受聘於人、而他人遇於邑中、與之苟合、"],[5,22,24,"其女旣在邑中、而不呼號、其男玷辱他人之妻、則必攜至邑門、俱以石擊斃之、以除惡於爾中、"],[5,22,25,"人遇受聘之女在田、強之苟合、則獨殺淫女之人、"],[5,22,26,"女無當死之罪、不可懲之、人遇女於田、女呼號而無救、其事與攻殺鄰里同、"],[5,22,27,"女無當死之罪、不可懲之、人遇女於田、女呼號而無救、其事與攻殺鄰里同、"],[5,22,28,"人遇未聘之女、強之苟合、爲人所見、"],[5,22,29,"則淫女之人、必以金五十、予女之父、旣辱是女、必娶爲妻、畢生不休、○"],[5,22,30,"勿烝父之繼室、勿辱父、"],[5,23,1,"外腎受傷、與被閹者、不得入耶和華會、"],[5,23,2,"姦生之子、雖至十世、亦不得入耶和華會、○"],[5,23,3,"亞捫人、摩押人、不得入耶和華會、凡屬斯族者、雖歷十世、至於永遠、亦不得入耶和華會、"],[5,23,4,"因爾昔出埃及、彼不以餅與水、迎爾於途、且買米所波大米之比奪人、比珥子巴蘭詛爾、"],[5,23,5,"惟爾上帝耶和華愛爾、不聽巴蘭、變詛爲祝、"],[5,23,6,"緣此、爾畢生勿求其平安、祈其利達、○"],[5,23,7,"勿憾以東人、以其爲爾同族、勿憾埃及人、以爾曾旅其地、"],[5,23,8,"彼之子孫、至於三世、可入耶和華會、○"],[5,23,9,"爾出列營攻敵、宜戒諸惡、"],[5,23,10,"若有夜間遺洩、以致不潔、則當出營、"],[5,23,11,"薄暮以水濯身、日入乃入、"],[5,23,12,"營外必有一所、"],[5,23,13,"器中有鍬、在外遺矢、必先掘土、反身而掩之、"],[5,23,14,"蓋爾上帝耶和華行於營中、以拯爾曹、付敵於爾、故營必潔、免其見有穢物、與爾相離、○"],[5,23,15,"僕逃主投爾、勿反於其主、"],[5,23,16,"於爾邑中、隨其所欲而居、勿虐待之、○"],[5,23,17,"以色列女中不可有娼妓、男中不可有孌童、"],[5,23,18,"娼妓之值、犬類之價、勿入爾上帝耶和華室以酬願、皆爲其所惡也、○"],[5,23,19,"以金與糧、及凡生利之物、貸於同儕、勿取其利、"],[5,23,20,"取於外族則可、於同儕則不可、如是在爾所據之地、爾上帝耶和華必於凡爾所爲、錫以福祉、○"],[5,23,21,"許願於爾上帝耶和華、償之勿遲、彼必討之於爾、若不償之、則爲有罪、"],[5,23,22,"不許願、則無罪、"],[5,23,23,"言出於口、則必行之、循其所許、樂輸於爾上帝耶和華者、○"],[5,23,24,"入人之葡萄園、任意飽啖其果則可、盛之於器則不可、"],[5,23,25,"入人禾稼、手摘其穗則可、刈之以鐮則不可、"],[5,24,1,"人娶妻後、見其有疵、而不之悅、當書離書、付於其手、使出其家、"],[5,24,2,"旣出之後、則可他適、"],[5,24,3,"如其後夫亦不之悅、付以離書而出之、或後夫死、"],[5,24,4,"其前夫旣出之、爲人所玷、勿復娶之、此乃耶和華所惡者、爾上帝耶和華所賜爲業之地、不可汚之、"],[5,24,5,"人新娶、不可往戰、不可任職、必處於家、歷至一年、以悅其妻、○"],[5,24,6,"毋取上下磨爲質、蓋質人之生命也、○"],[5,24,7,"如以色列人竊取同族以爲奴、或鬻於人、必致之死、以除惡於爾中、○"],[5,24,8,"宜愼癩疾、遵行利未人祭司所訓之例、我所命祭司者、俱當守之、"],[5,24,9,"昔爾出埃及時、爾上帝耶和華在途間、所行於米利暗者、爾當憶之、○"],[5,24,10,"如貸於人、勿入其家取質、"],[5,24,11,"必立於外、待其攜質出以予爾、"],[5,24,12,"如其人貧、勿留其質越宿、"],[5,24,13,"日入時、必反之、使其有衣以寢、爲爾祝嘏、則爾上帝耶和華必以爲義、"],[5,24,14,"貧乏傭人、或爾同族、或寓於爾邑之賓旅、勿虐待之、"],[5,24,15,"屆期必給以值、勿至日沒、以其貧乏、厥心在此、恐其籲耶和華、致罪歸爾、○"],[5,24,16,"毋因子而殺父、毋因父而殺子、惟依其罪、而殺其人、○"],[5,24,17,"賓旅與孤、勿反其正、勿以嫠衣爲質、"],[5,24,18,"當憶昔在埃及、爾爲奴隸、爾上帝耶和華贖爾以出、故我命爾行此、○"],[5,24,19,"爾刈田禾、若遺一束、勿返取、當留與賓旅及孤寡、致爾上帝耶和華於爾凡百所爲、錫嘏於爾、"],[5,24,20,"旣撲橄欖、毋得再撲、必歸賓旅及孤寡、"],[5,24,21,"旣摘葡萄、毋得再摘、必歸賓旅及孤寡、"],[5,24,22,"當憶昔在埃及、爾爲奴隸、故我命爾行此也、"],[5,25,1,"人有訟事、就於士師、士師聽之、必直其義者、罪其惡者、"],[5,25,2,"惡人罪當受笞、士師使伏於前、如數笞之、"],[5,25,3,"笞數勿踰四十、若笞之過多、恐賤爾昆弟、○"],[5,25,4,"踏穀之牛、勿籠其口、○"],[5,25,5,"兄弟同居、其一無子而死、死者之妻、不可他適、夫弟當娶爲妻、以盡厥分、"],[5,25,6,"首生之子、必爲兄嗣、使於以色列中、不絕其名、"],[5,25,7,"如弟不欲娶之、則婦當至邑門、見長老曰、我夫之弟、不欲其兄留名於以色列中、不盡爲弟之分、"],[5,25,8,"邑之長老必召而問之、如執意言不欲娶之、"],[5,25,9,"則婦於長老前、就而解其履、唾其面曰、不欲爲兄立家者、必如是待之、"],[5,25,10,"後在以色列中、必稱之曰解履之家、○"],[5,25,11,"二人相鬬、其一之妻、前欲援其夫、脫於擊者之手、而執其下體、"],[5,25,12,"則必斷其手、勿惜之、○"],[5,25,13,"囊中勿有異權、一大一小、"],[5,25,14,"家中勿有異量、一大一小、"],[5,25,15,"惟權與量、俱必準確公平、致可延年、於爾上帝耶和華所錫之地、"],[5,25,16,"凡行此非義者、乃爾上帝耶和華所惡也、○"],[5,25,17,"昔爾出埃及時、亞瑪力人所行於爾者、爾當憶之、"],[5,25,18,"彼不畏上帝、乘爾途間疲憊、殺爾後行之荏弱者、"],[5,25,19,"爾上帝耶和華、拯爾脫於四周之敵、俾得綏安、於其所賜爲業之地、則必塗亞瑪力誌於天下、爾勿忘之、"],[5,26,1,"旣至爾上帝耶和華所賜爲業之地、據而居之、"],[5,26,2,"必以斯土所產之初實、盛之於筐、詣爾上帝耶和華所選寄名之處、"],[5,26,3,"見當時之祭司曰、我今敬告爾上帝耶和華、耶和華所誓許我祖、錫我之地、我已至之、"],[5,26,4,"祭司取筐於爾手、置爾上帝耶和華壇前、"],[5,26,5,"爾在爾上帝耶和華前必曰、我祖亞蘭人、乃瀕死者、往旅埃及、人數無多、而成大族、強盛繁衍、"],[5,26,6,"埃及人惡待我儕、而虐遇之、加以苦役、"],[5,26,7,"我籲我列祖之上帝耶和華、蒙其垂聽、鑒我所受之艱難、勞苦暴虐、"],[5,26,8,"耶和華以能手、奮臂、異蹟、奇事、大而可畏之事、導我出埃及、"],[5,26,9,"攜我至此、錫我流乳與蜜之地、"],[5,26,10,"耶和華歟、爾所賜我之地、其所產之初實、我攜之至、遂置於爾上帝耶和華前、而行崇拜、"],[5,26,11,"爾與利未人、及居爾中之賓旅、緣爾上帝耶和華賜爾曁家之福、而喜樂焉、○"],[5,26,12,"每至三載、什輸其一之年、凡土所產、什輸其一旣畢、必以給利未人及賓旅孤寡、使食於爾邑內、而得果腹、"],[5,26,13,"則於爾上帝耶和華前告曰、爲聖之物、我已出之我家、給與利未人及賓旅孤寡、循爾所諭、爾之命令、我未干犯、亦未遺忘、"],[5,26,14,"維此聖物、居喪時、我未食之、不潔時、我未移之、爲死者、我未用之、惟聽我上帝耶和華命、遵爾所諭而行、"],[5,26,15,"祈自天上聖所俯察、錫嘏於爾民以色列、並所賜我流乳與蜜之地、如所誓於我列祖者、○"],[5,26,16,"爾上帝耶和華、今日命爾行此典章律例、故當一心一意守之、"],[5,26,17,"今日爾以耶和華爲爾上帝、願行其道、聽其言、守其典章、誡命律例、"],[5,26,18,"耶和華亦循其所許、以爾爲己民、俾從其命、"],[5,26,19,"使爾在於榮耀、名譽尊貴、超乎所造萬民、爾爲聖民、歸爾上帝耶和華、循其所言、"],[5,27,1,"摩西與以色列長老諭民曰、我今日所諭爾者、爾當遵守、"],[5,27,2,"爾渡約但、至爾上帝耶和華所賜之地、其日必立大石、塗之以灰、"],[5,27,3,"旣渡之後、當錄斯律諸言於上、致可入爾上帝耶和華所賜流乳與蜜之地、如爾祖之上帝耶和華所許者、"],[5,27,4,"旣渡約但、循我今日所諭、必立斯石於以巴路山、塗之以灰、"],[5,27,5,"在彼爲爾上帝耶和華建壇、以石爲之、毋用鐵器而造、"],[5,27,6,"建爾上帝耶和華之壇、必以未經雕鑿之石在壇之上、獻燔祭於爾上帝耶和華、"],[5,27,7,"亦獻酬恩祭、在彼食之、樂於爾上帝耶和華前、"],[5,27,8,"錄斯律諸言於石、當詳明焉、○"],[5,27,9,"摩西與利未人祭司、告以色列民曰、以色列人歟、爾其靜默以聽、今日爾成爲爾上帝耶和華之民、"],[5,27,10,"故必聽從其言、行其誡命典章、乃我今日所諭爾者也、○"],[5,27,11,"當日摩西諭民曰、"],[5,27,12,"旣濟約但、西緬、利未、猶大、以薩迦、約瑟、便雅憫諸支派、當立於基利心山、爲民祝嘏、"],[5,27,13,"流便、迦得、亞設、西布倫、但、拿弗他利諸支派、當立於以巴路山、宣其詛詞、"],[5,27,14,"利未人當大聲以向以色列民曰、"],[5,27,15,"凡人雕偶鑄像、匠人所造、乃耶和華所惡、立於隱處者、必受詛、衆民當應曰、阿們、"],[5,27,16,"輕視父母者、必受詛、衆民當應曰、阿們、"],[5,27,17,"移鄰里之界址者、必受詛、衆民當應曰、阿們、"],[5,27,18,"使瞽迷途者、必受詛、衆民當應曰、阿們、"],[5,27,19,"屈抑賓旅孤寡者、必受詛、衆民當應曰、阿們、"],[5,27,20,"烝父繼室、辱其父者、必受詛、衆民當應曰、阿們、"],[5,27,21,"淫於獸者、必受詛、衆民當應曰、阿們、"],[5,27,22,"姦亂同父異母、異父同母之姊妹者、必受詛、衆民當應曰、阿們、"],[5,27,23,"烝妻母者、必受詛、衆民當應曰、阿們、"],[5,27,24,"陰擊鄰里者、必受詛、衆民當應曰、阿們、"],[5,27,25,"受賄以殺不辜者、必受詛、衆民當應曰、阿們、"],[5,27,26,"不遵斯律之言而行者、必受詛、衆民當應曰、阿們、"],[5,28,1,"如爾聽從爾上帝耶和華之言、遵行其誡、我今日所諭爾者、則爾上帝耶和華必舉爾升高、超乎天下萬民、"],[5,28,2,"如爾聽從爾上帝耶和華之言、則此諸福、必臨及爾、"],[5,28,3,"在邑獲福、在田獲福、"],[5,28,4,"身之所生、土之所產、畜之所出、牛羣之犢、羊羣之羔、並皆獲福、"],[5,28,5,"盛糧之筐、搏麪之器獲福、"],[5,28,6,"爾出獲福、爾入獲福、"],[5,28,7,"敵起攻爾、耶和華必使爾擊敗之、其攻爾也由一途、其逃爾也由七途、"],[5,28,8,"耶和華必降福於爾倉、及爾手之所爲、錫嘏於爾、在爾上帝耶和華所賜之地、"],[5,28,9,"如爾守爾上帝耶和華之誡、遵行其道、則耶和華必踐其所誓、立爾爲己之聖民、"],[5,28,10,"天下億兆、將見爾稱以耶和華名、惟爾是畏、"],[5,28,11,"耶和華必使爾昌熾、身之所生、畜之所出、土之所產、俱蒙福祉、於耶和華所誓爾祖賜爾之地、"],[5,28,12,"耶和華必爲爾啟其寶藏、使天降時雨於爾土、於爾凡百所爲、錫嘏於爾、爾貸金於列邦、而不告貸於彼、"],[5,28,13,"如爾聽從爾上帝耶和華之誡命、我今日所諭爾者、謹守遵行、不偏左右、離我今日所諭之言、不從他神、而崇事之、則耶和華必以爾爲首、不以爾爲尾、使爾居上、不居於下、○"],[5,28,14,"如爾聽從爾上帝耶和華之誡命、我今日所諭爾者、謹守遵行、不偏左右、離我今日所諭之言、不從他神、而崇事之、則耶和華必以爾爲首、不以爾爲尾、使爾居上、不居於下、○"],[5,28,15,"如爾不聽爾上帝耶和華之言、不守其誡命典章、我今日所諭爾者、則此諸詛、必臨及爾、"],[5,28,16,"在邑受詛、在田受詛、"],[5,28,17,"盛糧之筐、搏麪之器受詛、"],[5,28,18,"身之所生、土之所產、畜之所出、牛羣之犢、羊羣之羔、並皆受詛、"],[5,28,19,"爾入受詛、爾出受詛、"],[5,28,20,"耶和華因爾行惡離棄彼、必於凡爾所爲、加爾咒詛、擾亂譴責、以致速亡、"],[5,28,21,"耶和華必使疫癘附於爾身、以至滅爾於爾入據之地、"],[5,28,22,"耶和華必以癆疾、熱疾、炎疾、瘧疾、兵革、枯槁、霉爛擊爾、此災必追襲爾、致爾隕沒、"],[5,28,23,"覆爾之天如銅、載爾之地如鐵、"],[5,28,24,"耶和華必以塵沙爲雨、自天降於爾土、俾爾滅亡、"],[5,28,25,"耶和華必使爾爲敵所敗、爾攻之也由一途、爾逃之也由七途、拋棄於天下萬國之中、"],[5,28,26,"爾屍必爲飛禽走獸所食、無人逐之、"],[5,28,27,"耶和華必以埃及人所患之癰、痔、疥、癬、不治之症、加乎爾身、"],[5,28,28,"又必使爾顚狂、目瞽心驚、"],[5,28,29,"雖在日中、猶如瞽者暗中摸索、所行所爲、不獲亨通、恆遭暴虐刦奪、無人救援、"],[5,28,30,"聘妻而人與之寢、築室而己不得居、植葡萄園而不得食其果、"],[5,28,31,"爾牛被宰、爾目擊之、而不得食、爾驢被奪、爾目擊之、而不見返、爾羊付於爾敵、無人救爾、"],[5,28,32,"子女付於異族、爾將終日瞻望、至於目盲、無力拯之、"],[5,28,33,"爾之土產、及爾勞而得者、將爲爾所未識之民吞噬、爾惟受虐見迫、歷久如是、"],[5,28,34,"爾目所見、必致顚狂、"],[5,28,35,"耶和華必以惡瘡、加於爾膝與股、自踵延及於頂、無術以療、"],[5,28,36,"耶和華必以爾及爾所立之王、徙至爾與爾祖素所未識之國、在彼奉事木石之神、"],[5,28,37,"於耶和華徙爾所至之國、必爲人所駭異、作諺語及話柄、"],[5,28,38,"爾之田畝、播種則多、獲實則少、蝗食故也、"],[5,28,39,"植葡萄園而治之、不收其果、不飲其酒、蟲食故也、"],[5,28,40,"四境有橄欖樹、不以其油膏身、果隕故也、"],[5,28,41,"爾生子女、不爲爾有、被虜故也、"],[5,28,42,"爾囿之樹、爾地之產、爲蝗所食、"],[5,28,43,"爾中賓旅、必愈升愈高、爾愈降愈卑、"],[5,28,44,"彼可貸金於爾、爾不貸金於彼、彼爲首、爾爲尾、"],[5,28,45,"凡此諸詛、必追襲爾、臨及爾、俾爾滅亡、因爾不聽爾上帝耶和華所諭之言、守其誡命典章、"],[5,28,46,"凡此諸詛、必爲異蹟奇事於爾、爰及子孫、歷世靡曁、"],[5,28,47,"爾當富有之時、不中心欣喜、奉事爾上帝耶和華、"],[5,28,48,"爾必饑渴、裸裎、匱乏、服役於敵、耶和華所遣攻爾者、彼以鐵軛置於爾頸、迨爾滅亡、"],[5,28,49,"耶和華必使遠民、如鷹之飛、來自地極、以攻擊爾、其言爾不之識、"],[5,28,50,"其容強悍、不顧耆老、不恤幼穉、"],[5,28,51,"爾畜所生、爾土所產、俱爲所食、迨爾滅亡、爾穀與酒及油、牛羣之犢、羊羣之羔、取之無遺、迨爾滅亡、"],[5,28,52,"爾上帝耶和華所賜爾之全地、其中諸邑、城垣高固、爾所恃也、敵必困爾於中、迨其傾圮、"],[5,28,53,"被圍之時、受敵窘迫、至食子女之肉、爾上帝耶和華所賜者、"],[5,28,54,"爾中荏弱嬌嫩之人、必怒視其兄弟、及懷中之妻室、遺留之子女、"],[5,28,55,"甚至彼於敵圍爾邑、窘迫之際、食其子女之肉、不肯分給親屬、無所遺餘故也、"],[5,28,56,"爾中荏弱嬌嫩之婦、因其嫋娜、以足踐地、猶且不屑、必怒視其懷中之夫、與其子女、曁膝間之嬰孩、及凡所生、緣敵圍邑窘迫、而無所得、則私食之、"],[5,28,57,"爾中荏弱嬌嫩之婦、因其嫋娜、以足踐地、猶且不屑、必怒視其懷中之夫、與其子女、曁膝間之嬰孩、及凡所生、緣敵圍邑窘迫、而無所得、則私食之、"],[5,28,58,"如爾不守此書所載法律之言、不畏爾上帝耶和華尊榮可畏之名、"],[5,28,59,"則耶和華必使爾遘奇異之災、至重至久之殃、艱苦纏綿之病、爰及苗裔、"],[5,28,60,"加以埃及諸疾、爾所畏者、必附爾身、"],[5,28,61,"更有諸疾諸災、律書所未載者、耶和華亦以相加、迨爾滅亡、"],[5,28,62,"昔爾人數、如天星之多、因不聽爾上帝耶和華命、致所遺無幾、"],[5,28,63,"昔耶和華以善待爾、昌熾爾爲悅、厥後以毀滅爾、殲殄爾爲悅、使爾絕於所入而得之地、"],[5,28,64,"耶和華必散爾於列邦、自地極至天涯、在彼奉事木石之神、爾與爾祖所未識者、"],[5,28,65,"在此族中、不獲綏安、無有駐足之所、耶和華必使爾心慄目盲、精神衰敗、"],[5,28,66,"爾之生命、懸寄危境、晝夜驚惶、料難保全、"],[5,28,67,"因心所懼、與目所見、朝必曰願得及暮、暮必曰願得及朝、"],[5,28,68,"往埃及之途、我曾諭爾、不復見之、耶和華必使爾駕舟復返、在彼自鬻於敵、爲僕爲婢、無人市爾、"],[5,29,1,"耶和華在何烈、與以色列人立約、此外又在摩押、諭摩西與以色列人立約、其言如左、"],[5,29,2,"摩西召以色列衆、告之曰、昔爾目擊耶和華在埃及、行於法老與臣、及其全地之事、"],[5,29,3,"卽大試鍊、與異蹟奇事、爾所見者、"],[5,29,4,"惟至今日、耶和華未嘗賜爾心能明、目能見、耳能聽、"],[5,29,5,"我導爾於野、歷四十年、爾衣在身而不敝、爾履在足而不壞、"],[5,29,6,"餅則未食、清酒醇醪未飲、使爾知耶和華乃爾之上帝、"],[5,29,7,"爾曹至此地、希實本王西宏、巴珊王噩、出與我戰、而我擊之、"],[5,29,8,"據有其地、給於流便迦得二支派、及瑪拿西支派之半、以爲恆業、"],[5,29,9,"故當遵行此約之言、使凡所爲、無不亨通、○"],[5,29,10,"今爾有衆、牧伯、族長、長老、有司、以色列諸丁男、"],[5,29,11,"爾之子女妻室、營中賓旅、自採薪者、及汲水者、俱立於爾上帝耶和華前、"],[5,29,12,"使爾與於爾上帝耶和華之約與誓、卽其今日與爾所立者、"],[5,29,13,"彼以爾爲己民、己爲爾之上帝、踐其前言、循其與爾列祖亞伯拉罕以撒雅各所誓者、"],[5,29,14,"此約與誓、我不第與爾曹立也、"],[5,29,15,"凡今日於我上帝耶和華前、與我同在、及不同在者、亦與立之、"],[5,29,16,"昔我儕居埃及、曁經歷諸邦、爾所知也、"],[5,29,17,"其中所可憎者、木石金銀偶像、爾亦見之、"],[5,29,18,"此約之立、以免爾中男女、宗族支派、今日中心違棄我上帝耶和華、往事斯族之神、致有荼毒之根、生於爾中、"],[5,29,19,"聞此詛言、猶中心自慰曰、我雖剛愎自用、渴時痛飲、亦可獲安、"],[5,29,20,"若此者、耶和華必不赦宥、其怒與忌、如烟之出、必攻斯人、以書所載之詛、加乎其身、塗其名於天下、"],[5,29,21,"在以色列諸支派中、耶和華必區別之、循律書所載約中之詛言、加以禍害、"],[5,29,22,"爾後世子孫、及彼遠人、見此地之災、曁耶和華所降之疾、"],[5,29,23,"又見硫磺與鹽、火焚遍地、不種不產、不生草萊、如所多瑪、蛾摩拉、押瑪、洗扁、爲耶和華忿怒所傾覆者、"],[5,29,24,"列邦人皆問曰、耶和華何爲行此於斯土、其怒若是之烈、果何故乎、"],[5,29,25,"人將對曰、其祖之上帝耶和華、導之出埃及時、與之立約、而彼背之、"],[5,29,26,"奉事崇拜他神、素所未識、耶和華亦未嘗聽其服從者、"],[5,29,27,"故耶和華震怒斯土、以書所載之詛加之、"],[5,29,28,"耶和華以氣憤、忿怒恚恨、拔之斯土、投於異邦、有如今日、"],[5,29,29,"隱微之事、屬我上帝耶和華、惟明顯之事、永屬於我、爰及子孫、俾守此律之言、"],[5,30,1,"我所陳於爾前之祝與詛、旣已臨爾、於爾上帝耶和華逐爾而至之邦、追憶此事、"],[5,30,2,"與爾子孫、一心一意歸爾上帝耶和華、遵從其言、循我今日所諭爾者、"],[5,30,3,"則爾上帝耶和華將矜恤爾、返爾俘囚、自散爾而至之列邦集爾、"],[5,30,4,"爾見逐者至於天涯、爾上帝耶和華必由彼集爾、攜之而歸、"],[5,30,5,"爾祖所據之地、爾上帝耶和華必導爾入而得之、降福於爾、俾爾昌熾、較祖尤衆、"],[5,30,6,"爾上帝耶和華必制爾情欲、爰及子孫、使一心一意愛爾上帝耶和華、致得生存、"],[5,30,7,"爾上帝耶和華、必以是詛、加諸爾敵、及憾爾迫爾者、"],[5,30,8,"爾將旋歸、聽從耶和華之言、遵行其誡、我今日所諭爾者、"],[5,30,9,"爾若聽從爾上帝耶和華之言、守此律書所載之誡命典章、一心一意歸爾上帝耶和華、則爾上帝耶和華必於凡爾所爲、錫以福祉、身之所生、畜之所出、土之所產、盡皆蕃衍、耶和華心復悅爾、錫以福祉、如昔悅爾祖然、"],[5,30,10,"爾若聽從爾上帝耶和華之言、守此律書所載之誡命典章、一心一意歸爾上帝耶和華、則爾上帝耶和華必於凡爾所爲、錫以福祉、身之所生、畜之所出、土之所產、盡皆蕃衍、耶和華心復悅爾、錫以福祉、如昔悅爾祖然、"],[5,30,11,"我今諭爾之誡、行之非難、離爾非遠、"],[5,30,12,"不在天上、致爾自謂、誰升天攜之以至、使我聞而行之、"],[5,30,13,"不在海外、致爾自謂、誰濟海攜之以至、使我聞而行之、"],[5,30,14,"斯道密邇乎爾、在爾口、在爾心、俾爾行之、○"],[5,30,15,"我今日以生與福、死與禍、陳於爾前、"],[5,30,16,"諭爾愛爾上帝耶和華、遵行其道、守其誡命、典章律例、致得生存昌熾、爾上帝耶和華於爾所入而據之地、錫爾以嘏、"],[5,30,17,"如爾中心違離、不欲聽從、爲人所誘、崇事他神、"],[5,30,18,"我今告爾、爾必滅亡、於渡約但而得之地、不得延年、"],[5,30,19,"我今呼籲天地爲證、以生死祝詛、陳於爾前、爾其選生、俾爾及爾子孫、得以生存、"],[5,30,20,"且愛爾上帝耶和華、聽從其言、而依附之、蓋耶和華爲爾生命、及爾延年之由、使爾居於其所誓賜爾祖亞伯拉罕以撒雅各之地、"],[5,31,1,"摩西以斯言告以色列衆曰、"],[5,31,2,"我今百有二十歲矣、不復能出入於爾中、耶和華亦曾諭我曰、爾不得渡此約但、"],[5,31,3,"爾上帝耶和華爲爾先導、殲斯族於爾前、使爾據有其地、約書亞必導爾濟河、如耶和華所言、"],[5,31,4,"耶和華翦滅亞摩利二王西宏與噩、及其國、亦必如是待斯族、"],[5,31,5,"耶和華旣付之於爾、當如我所諭而待之、"],[5,31,6,"強乃志、壯乃心、勿畏葸、勿恐惶、爾上帝耶和華與爾偕往、不棄爾、不遺爾、"],[5,31,7,"摩西召約書亞、於以色列衆前諭之曰、強乃志、壯乃心、爾必與民偕往、入耶和華誓賜其祖之地、使得爲業、"],[5,31,8,"耶和華爲爾先導、與爾同在、不棄爾、不遺爾、勿畏懼、勿驚惶、○"],[5,31,9,"摩西書此律、授舁耶和華約匱之利未人祭司、及以色列長老、"],[5,31,10,"諭之曰、每七載、豁免年、構廬節期、"],[5,31,11,"以色列衆咸至、覲爾上帝耶和華於其所選之處、當誦此律、使衆聞之、"],[5,31,12,"集民男女幼穉、及旅於爾邑者、俾其聽之、學習寅畏爾上帝耶和華、遵守此律之言、"],[5,31,13,"子女尚無識者、亦使聽之、學習畢生寅畏爾上帝耶和華、於渡約但而得之地、○"],[5,31,14,"耶和華諭摩西曰、爾之死期伊邇、當召約書亞偕詣會幕、我將付託之、摩西與約書亞乃詣會幕、"],[5,31,15,"耶和華乘雲柱見於幕中、雲柱止於幕門、"],[5,31,16,"耶和華諭摩西曰、爾與列祖偕眠、斯民必於所至之地、狥欲從異族之神、離棄我、背我與立之約、"],[5,31,17,"是日我必怒而棄之、掩面不顧、使被吞噬、多遭災禍、時彼必曰、此災臨我、豈非以我上帝不在我中乎、"],[5,31,18,"因其轉從他神、行此惡事、我必掩面不顧之、"],[5,31,19,"故當作歌、教以色列人、使其口誦、以爲之證、"],[5,31,20,"我所誓許其祖流乳與蜜之地、旣導之入、彼得飽食、身體豐肥、斯時也、彼轉從他神、藐視乎我、背我之約、"],[5,31,21,"洎乎多遭災禍、斯歌在其後裔之口、尚未遺忘、必爲其證、蓋我未導之入所誓賜之地、已知其所圖、"],[5,31,22,"當日摩西作歌、教以色列人、"],[5,31,23,"耶和華諭嫩之子約書亞曰、強乃志、壯乃心、爾將導以色列人入我所誓賜之地、我必偕爾、○"],[5,31,24,"摩西以此律言、書之旣畢、"],[5,31,25,"遂諭舁耶和華約匱之利未人曰、"],[5,31,26,"以此律書、置於爾上帝耶和華約匱之側、爲證於爾、"],[5,31,27,"蓋我知爾悖逆強項、我今猶存、與爾同在、爾尚悖逆耶和華、況我歿後乎、"],[5,31,28,"當使爾支派之長老有司咸集、我將以此言告之、呼籲天地、於彼爲證、"],[5,31,29,"我知我死之後、爾必自壞、離我所諭之道、至於末期、災禍必臨爾身、因爾行耶和華所視爲惡者、爾之所爲、激其震怒、"],[5,31,30,"摩西盡誦歌詞、使以色列會衆聽聞、"],[5,32,1,"天其側耳、我將有言、地其聽我口中之語、"],[5,32,2,"我道淋漓若雨、我言滴瀝如露、猶小雨之潤草、似時雨之灌蔬、"],[5,32,3,"我將揚耶和華之名、爾其稱我上帝爲大、"],[5,32,4,"維彼磐石、其工純全、其道正直、上帝誠實旡妄、公正無私、"],[5,32,5,"惟此世代、乖戾邪曲、對於上帝、行事邪僻、弗爲其子、乃爲點汚、"],[5,32,6,"愚昧無知之民、報耶和華乃如是乎、彼非爾父而購爾乎、彼乃造爾立爾、"],[5,32,7,"追憶往古之日、思念歷代之年、問於爾父、彼必示爾、詢諸長老、彼必告爾、"],[5,32,8,"至高者使諸族得業、俾世人散處、爰定列邦之疆域、循以色列之人數、"],[5,32,9,"耶和華之分乃其庶民、雅各爲其恆業、"],[5,32,10,"彼遇之於荒漠之地、獸嘷之野、護衞之、眷顧之、保之如眸子、"],[5,32,11,"如鷹攪巢、振翮於雛、舒翼以引、負之其上、"],[5,32,12,"獨耶和華導之、無異族之神偕在、"],[5,32,13,"使其駕行地之高處、食田所產、㗖巖穴所出之蜜、哺堅石所產之油、"],[5,32,14,"使食牛酪、羊乳羔脂、及巴珊之牡綿羊、牡山羊、至嘉之麥、亦飲葡萄之汁、"],[5,32,15,"耶書崙豐肥而奔踶、碩大而光澤、乃違離造之之上帝、藐視救之之磐石、"],[5,32,16,"崇事異族之神、以觸其忌、行作可憎之事、以激其怒、"],[5,32,17,"祭祀鬼魔、非是上帝、乃彼素所未識、新造初立之神、爾祖未嘗寅畏者、"],[5,32,18,"產爾之磐石、爾不憶之、生爾之上帝、爾乃忘之、"],[5,32,19,"耶和華見而憎之、因其子女干厥震怒、"],[5,32,20,"曰、我將掩面、不加眷顧、觀其終局如何、彼乃乖戾之族、無誠信之子女、"],[5,32,21,"彼以非神者觸我忌、以虛無者激我怒、我將以異族觸彼忌、以蚩氓激彼怒、"],[5,32,22,"蓋我怒如火燎、燒及陰府、焚燬大地、曁其出產、燃彼山基、"],[5,32,23,"我將以災積於其身、以我之矢、射之務盡、"],[5,32,24,"使其因饑而瘦、因熱而敗、因苦而滅、害於獸齒、傷於蟲毒、"],[5,32,25,"外遭鋒刃、內受驚惶、少男幼女、乳子白叟、淪胥以亡、"],[5,32,26,"我曰、將散之於遠方、絕其誌於人間、"],[5,32,27,"第恐敵人激我、仇人誤視、自謂我手力大、非耶和華所行、"],[5,32,28,"斯民無謀猷、中心無聰慧、"],[5,32,29,"願其有智、明乎此事、思厥終局、"],[5,32,30,"若非其磐石鬻之、耶和華付之、則敵一焉能驅千、二焉能逐萬、"],[5,32,31,"敵之磐石、不如我之磐石、此敵自爲證也、"],[5,32,32,"其葡萄樹屬所多瑪、產自蛾摩拉田、其果如膽、其穗甚苦、"],[5,32,33,"其酒乃蛇之毒、蝮之惡毒、"],[5,32,34,"其惡非積於我前、封於我庫乎、"],[5,32,35,"伸寃在我、其足躓時、我必報之、禍日伊邇、災難速臨、"],[5,32,36,"耶和華見其民之力已廢、被束者、自由者、靡有孑遺、必爲其民伸寃、爲其僕回意、"],[5,32,37,"曰、彼之神安在、所恃之磐石奚存、"],[5,32,38,"饗爾祭牲之脂、飲爾灌祭之酒者、其起而助爾護爾、"],[5,32,39,"當知我之爲我、無神偕我、我使人死、亦使人生、我傷之、亦醫之、無能拯於我手、"],[5,32,40,"我向天舉手曰、我指永生而誓、"],[5,32,41,"倘礪閃爍之刃、施行審鞫、敵我者、我必罰之、憾我者、我必報之、"],[5,32,42,"必使我矢醉於血、我刃吞厥肉、卽被虜見殺者之血、敵魁頭顱之肉、"],[5,32,43,"爾列族歟、當與其民同樂、蓋彼必爲其僕之血伸寃、報復厥敵、必爲其地與民贖罪、○"],[5,32,44,"摩西與嫩之子約書亞、以此歌詞、誦與以色列民、"],[5,32,45,"誦之旣畢、"],[5,32,46,"摩西謂之曰、我今日告爾之詞、當存於心、命爾子孫、遵守斯律之言、"],[5,32,47,"此事於爾、所關非淺、乃爾之生命、由此得以延年、於渡約但而得之地、○"],[5,32,48,"當日耶和華諭摩西曰、"],[5,32,49,"摩押地、耶利哥相對之所、亞巴琳山、尼波崗、爾其陟之、瞻望迦南、我所錫於以色列族爲業之地、"],[5,32,50,"爾旣陟之、必死於彼、而歸乃祖、如爾兄亞倫死於何珥山、而歸其祖然、"],[5,32,51,"昔在尋野、加低斯米利巴水、爾曹不於以色列人中、尊我爲聖、干罪於我、"],[5,32,52,"故我所錫以色列族之地、爾惟遙觀、不得入之、"],[5,33,1,"上帝僕摩西、於未死之先、爲以色列人祝嘏、"],[5,33,2,"曰、耶和華至自西乃、起自西珥、著自巴蘭、來自萬聖、法律出其右手、勢如烈火、"],[5,33,3,"彼眷愛斯民、衆聖在其手中、坐其足下、領受其言、"],[5,33,4,"摩西命以法律、爲雅各會衆之恆業、"],[5,33,5,"彼於耶書崙爲王、民之族長咸集、以色列支派皆就之、○"],[5,33,6,"願流便生存不死、惟人數維寡、○"],[5,33,7,"論猶大則曰、耶和華歟、俯聽猶大之呼籲、導歸故族、彼以手爲己搏戰、爾必助之攻敵、○"],[5,33,8,"論利未則曰、耶和華歟、爾之土明烏陵、與爾聖者偕、爾於瑪撒試之、於米利巴水與之爭、"],[5,33,9,"言及父母、彼曰我未見之、不認兄弟、不識子女、乃因遵行爾命、謹守爾約、"],[5,33,10,"彼將以爾律例教雅各、以爾法律誨以色列、焚香於爾前、獻全牲燔祭於爾壇、"],[5,33,11,"耶和華歟、錫嘏其財物、悅納其所爲、洞穿其敵、及憾之者之腰、使不復起、○"],[5,33,12,"論便雅憫則曰、耶和華所眷愛者、將安居其側、耶和華終日庇護之、使處兩肩之間、○"],[5,33,13,"論約瑟則曰、願耶和華錫嘏其地、賜以天上之寶、空際之露、地中之泉、"],[5,33,14,"日所生之果、月所產之寶、"],[5,33,15,"古山之上品、恆嶽之嘉物、"],[5,33,16,"地與其中所韞之珍奇、及居荊棘中者之恩惠、願悉歸於約瑟之首、臨於冠兄弟者之頂、"],[5,33,17,"彼如牛之首生、有威可畏、其角如兕角、將抵觸異邦、至於地極、以法蓮之萬萬、瑪拿西之千千是也、○"],[5,33,18,"論西布倫則曰、西布倫歟、爾出外可歡欣、以薩迦歟、爾居幕可喜樂、"],[5,33,19,"必召萬民登山、奉獻義祭、因其必享海中之豐裕、沙中之珍藏、○"],[5,33,20,"論迦得則曰、恢廓迦得者、宜頌美焉、迦得伏如牝獅、斷傷人之首臂、"],[5,33,21,"彼先選得其業、乃爲立律者所遺留、遂偕族長而來、行耶和華之公義、及其與以色列所立之律例、○"],[5,33,22,"論但則曰、但乃稚獅、踴躍出於巴珊、○"],[5,33,23,"論拿弗他利則曰、拿弗他利歟、沾恩旣足、受福且盈、由耶和華所賜、西方南方、爾其據以爲業、○"],[5,33,24,"論亞設則曰、願亞設因多子而獲福、爲兄弟所悅納、浸足於油、"],[5,33,25,"爾之楗乃鐵乃銅、爾之力隨日所需、○"],[5,33,26,"耶書崙歟、無有若上帝者、乘雲而行、赫赫於天、惟爾是輔、"],[5,33,27,"永生上帝、爲爾居所、恆久之臂、惟爾是扶、逐敵於爾前、命爾殄滅之、"],[5,33,28,"以色列族、居處綏安、雅各之源、獨在產穀與酒之地、天滴甘露、"],[5,33,29,"以色列歟、爾有福祉、何民若爾、爲耶和華所拯、彼乃護爾之干、榮爾之刃、敵必屈伏於爾、爾將履其崇邱、"],[5,34,1,"摩西自摩押平原、登尼波山、陟耶利哥相對之毘斯迦嶺、耶和華示以基列全地、至於但境、"],[5,34,2,"及拿弗他利全地、以法蓮瑪拿西地、猶大全地、至於西海、"],[5,34,3,"南方與椶樹城耶利哥谷之平原、至於瑣珥、"],[5,34,4,"耶和華諭之曰、此地乃我所誓於亞伯拉罕以撒雅各、以賜其後裔者、我使爾目覩、惟不得濟、"],[5,34,5,"於是耶和華之僕摩西卒於摩押、如耶和華所言、"],[5,34,6,"葬於摩押之谷、在伯毘珥相對之所、越至今日、無有知其墓者、"],[5,34,7,"摩西卒時、年百有二十、其目未眊、其力未衰、"],[5,34,8,"以色列人於摩押平原、爲之哀哭三旬、盈其日數、"],[5,34,9,"嫩之子約書亞、因摩西曾按手其首、充以智慧之神、以色列人聽從之、遵耶和華所諭摩西之命、"],[5,34,10,"此後以色列中、未有挺生先知、若摩西者、爲耶和華晤對相識、"],[5,34,11,"遣之在埃及地、行異蹟奇事於法老、及其諸臣、與其四境、"],[5,34,12,"並顯大能之手、行可畏之事、以色列衆目覩、"],[6,1,1,"耶和華僕摩西死後、耶和華諭摩西從者、嫩之子約書亞曰、"],[6,1,2,"我僕摩西死矣、今爾與民起而濟此約但、往我所賜以色列族之地、"],[6,1,3,"凡爾足所履之處、我悉以錫爾、如我昔與摩西所言、"],[6,1,4,"自曠野曁利巴嫩、至伯拉大河、赫族全地、爰及大海日入之所、咸爲爾境、"],[6,1,5,"爾之畢生、無人能禦爾、我必偕爾、如昔偕摩西然、必不遺爾、不棄爾也、"],[6,1,6,"強乃心、壯乃志、以爾必導斯民、得我誓賜其祖之地、"],[6,1,7,"惟當強乃心、壯乃志、悉守我僕摩西命爾之律、而遵行之、勿偏於左、勿偏於右、俾爾無論何往、靡不亨通、"],[6,1,8,"惟此律書、勿離爾口、晝夜思維、守其所錄、致獲坦途、而得利達、"],[6,1,9,"我豈不命爾乎、強乃心、壯乃志、勿畏葸、勿恐惶、無論何往、爾上帝耶和華與爾偕焉、○"],[6,1,10,"於是約書亞命民間有司曰、"],[6,1,11,"巡營諭民、宜備餱糧、三日之內、必濟約但、入據爾上帝耶和華賜爾爲業之地、"],[6,1,12,"時、約書亞語流便人、迦得人、及瑪拿西支派之半曰、"],[6,1,13,"爾當追念耶和華僕摩西諭爾之言云、爾上帝耶和華旣已錫爾綏安、亦必錫爾斯土、"],[6,1,14,"爾之妻孥牲畜、可留於約但東、摩西予爾之地、惟爾勇士、必皆執兵、先爾兄弟而濟以助之、"],[6,1,15,"迨耶和華錫爾兄弟綏安、如錫於爾、使之亦得爾上帝耶和華所賜之地、後乃返得爾業、卽耶和華僕摩西所予約但東日出之地、"],[6,1,16,"對曰、凡爾所諭、我必行之、凡爾所遣、我必往焉、"],[6,1,17,"昔我諸事聽從摩西、今亦如是聽從爾、惟願爾上帝耶和華偕爾、如偕摩西然、"],[6,1,18,"凡逆爾命、不遵爾所諭者、必致之死、惟當強乃心、壯乃志、"],[6,2,1,"嫩之子約書亞由什亭潛遣二諜、曰、往窺其地及耶利哥、二人遂往、入宿妓室、妓名喇合、"],[6,2,2,"或告耶利哥王曰、今夜有以色列人至此察地、"],[6,2,3,"耶利哥王遣人謂喇合曰、詣爾入爾室者、當攜之出、蓋彼爲察全地而來、"],[6,2,4,"婦匿二人、則曰、其人誠至此、我不知其奚自、"],[6,2,5,"昏暮閉邑門時、其人出矣、不知何往、速追必及、"],[6,2,6,"婦已引之陟屋巔、以所陳麻稭藏之、"],[6,2,7,"使者由約但津之道而追、旣出、邑門遂閉、"],[6,2,8,"二人未寢、婦陟屋巔就之、"],[6,2,9,"曰、耶和華以此地賜爾、我所知也、緣爾之故、吾儕畏懼、斯土之民喪膽、"],[6,2,10,"爾出埃及時、耶和華使紅海之水涸於爾前、約但東之亞摩利二王西宏及噩、爲爾所滅、我已聞之、"],[6,2,11,"我儕聞而心怯、以爾之故、無不氣餒者、蓋爾上帝耶和華、乃上天下地之上帝也、"],[6,2,12,"今我以仁慈待爾、請指耶和華而誓、亦必以仁慈待我父家、示我以實證、"],[6,2,13,"保存我父母、兄弟姊妹、及凡所有、拯我性命、免於死亡、"],[6,2,14,"二人曰、爾若不洩我事、我以己命代爾、迨耶和華予我地時、我必以仁慈誠實待爾、"],[6,2,15,"婦之居室、在於城垣、遂以繩縋二人、由牖而下、"],[6,2,16,"謂之曰、當往於山、免追者遇爾、自匿三日、迨追者返、然後前行、"],[6,2,17,"二人曰、爾使我所發之誓、我必守之而無咎、"],[6,2,18,"我儕至斯土時、爾須以此絳繩、繫於縋我之牖、集爾父母兄弟、及父全家、入於此室、"],[6,2,19,"凡出爾門、入衢遇害、血歸其首、我則無辜、惟偕居爾家者、有人害之、血歸我首、"],[6,2,20,"如洩我事、則爾使我所發之誓、與我無與、"],[6,2,21,"曰、可如爾言以行、遂遣之去、以絳繩繫於牖、"],[6,2,22,"二人至山、居之三日、待追者返、追者沿途求之不獲、"],[6,2,23,"二人下山、濟河而返、至嫩之子約書亞、以所遇者悉告之、"],[6,2,24,"又曰、耶和華果以全地付我、斯土之民、盡爲我而喪膽、"],[6,3,1,"約書亞夙興、偕以色列衆離什亭、至約但、未濟而宿、"],[6,3,2,"越三日、有司巡營、"],[6,3,3,"諭民曰、爾見利未人祭司舁爾上帝耶和華之約匱、則離爾所、從諸其後、"],[6,3,4,"相距約二千肘、不可近前、藉知當行之途、昔爾所未行者、"],[6,3,5,"約書亞告民曰、爾當潔己、明日耶和華將行奇事於爾中、"],[6,3,6,"又告祭司曰、當舁約匱、先民而濟、祭司遂舁約匱、先民而行、"],[6,3,7,"耶和華諭約書亞曰、自今日始、我將使爾爲大於以色列衆前、俾知我今偕爾、如昔偕摩西然、"],[6,3,8,"當命舁約匱之祭司、至約但濱、立於水中、"],[6,3,9,"約書亞告以色列人曰、爾曹前來、聽爾上帝耶和華之言、"],[6,3,10,"又曰、爾可知維生上帝在於爾中、必於爾前驅逐迦南人、赫人、希未人、比利洗人、革迦撒人、亞摩利人、耶布斯人、"],[6,3,11,"全地主宰之約匱、先爾而入約但河中、"],[6,3,12,"今在以色列支派中、當簡十二人、每支派一人、"],[6,3,13,"祭司舁全地主宰耶和華之約匱、立足約但水中時、水必斷流、自上而下之水、必立爲堆、"],[6,3,14,"民旣離幕、欲濟約但、祭司舁約匱先民而行、"],[6,3,15,"時值收穫、約但水溢於岸、舁約匱之祭司至河、足濡於水、"],[6,3,16,"自上而下之水、遂立爲堆、相離甚遠、在撒拉但旁之亞當邑、其流於亞拉巴鹽海之水悉絕、民乃由耶利哥相對之處而濟、"],[6,3,17,"舁耶和華約匱之祭司、穩立燥土、在約但河中、待以色列族盡由陸地、而過約但、"],[6,4,1,"民衆旣濟約但、耶和華諭約書亞曰、"],[6,4,2,"當於民中簡十二人、每支派一人、"],[6,4,3,"命之曰、自約但河中、祭司立足之所、取石十二、攜之過河、置於今夜宿處、"],[6,4,4,"約書亞乃召所備之以色列人十二、每支派一人、"],[6,4,5,"謂之曰、入約但河、至爾上帝耶和華之匱前、按以色列支派之數、各取一石、荷之以肩、"],[6,4,6,"以爲證於爾中、異日爾子孫問爾曰、此石何意、"],[6,4,7,"則曰、昔耶和華之約匱濟約但、水絕流於其前、此石永爲以色列人之誌、"],[6,4,8,"以色列人按其支派之數、自約但中取石十二、攜至宿處而置之、遵耶和華諭約書亞之命、"],[6,4,9,"約書亞又立石十二於約但河中、在舁約匱祭司立足之所、至今猶存、"],[6,4,10,"舁匱之祭司立約但中、待耶和華命約書亞諭民之事、摩西所命約書亞者、行之已畢、民濟甚速、"],[6,4,11,"民旣盡濟、耶和華之匱與祭司亦濟、爲民目擊、"],[6,4,12,"流便人、迦得人、及瑪拿西支派之半、遵摩西所言、執兵先以色列人而濟、"],[6,4,13,"備戰者約四萬、於耶和華前濟河、至耶利哥平原以待戰、"],[6,4,14,"是日耶和華使約書亞爲大於以色列衆前、畢生民畏之、如畏摩西然、○"],[6,4,15,"耶和華諭約書亞曰、"],[6,4,16,"命舁法匱之祭司、自約但而上、"],[6,4,17,"乃命之曰、爾其自約但而上、"],[6,4,18,"舁耶和華約匱之祭司、旣自約但而上、立足陸地、河水復流原處、漲溢於岸如故、"],[6,4,19,"正月十日、民自約但而上、建營於耶利哥東界之吉甲、"],[6,4,20,"自河中所取之十二石、約書亞立之於吉甲、"],[6,4,21,"謂以色列人曰、異日爾之子孫、問其祖父曰、此石何意、"],[6,4,22,"可告之曰、昔以色列人由陸地過約但、"],[6,4,23,"蓋爾上帝耶和華使約但水涸於爾前、以待爾濟、如昔使紅海涸於我前、以待我濟然、"],[6,4,24,"使地上億兆、皆知耶和華手有巨能、俾爾寅畏爾上帝耶和華、至於永世、"],[6,5,1,"約但西亞摩利列王、海濱迦南列王、聞耶和華使約但水涸於以色列人前、以待其濟、則爲之心怯而氣餒、○"],[6,5,2,"時、耶和華諭約書亞曰、以石製刀、復爲以色列人行割、"],[6,5,3,"約書亞遂以石製刀、爲以色列人行割於阿珥拉山、"],[6,5,4,"其所以行此、因出埃及之衆、所有丁男戰士、出埃及後、皆死於曠野途間也、"],[6,5,5,"凡出埃及之民、俱已受割、惟生於曠野途間者、未之受焉、"],[6,5,6,"蓋以色列人遊行曠野、歷四十年、迨出埃及民之戰士皆死、以其不遵耶和華命故也、耶和華昔所誓於列祖、必錫我儕流乳與蜜之地、今則發誓、不許見之、"],[6,5,7,"彼之子孫、耶和華所使似續者、途間未受割、約書亞爲彼行之、"],[6,5,8,"行割已畢、民在營中、各居其所、以待痊愈、"],[6,5,9,"耶和華諭約書亞曰、埃及之辱、我今使之轉離乎爾、故其地名曰吉甲、至於今日、○"],[6,5,10,"以色列人建營於吉甲、至月之十四日夕、守逾越節於耶利哥平原、"],[6,5,11,"翌日、民食其地所產、無酵之餅、火烘之穀、"],[6,5,12,"旣食其地所產、翌日瑪那遂止、以色列人不復得之、是年食迦南土產、○"],[6,5,13,"約書亞近耶利哥時、舉目見有一人、拔刃對立、約書亞就而問曰、爾爲我乎、爲敵乎、"],[6,5,14,"曰、非也、我來爲耶和華軍長、約書亞遂伏地拜曰、我主諭僕何詞、"],[6,5,15,"耶和華軍長曰、爾所立者聖地也、解爾足履、約書亞遵命而行、"],[6,6,1,"耶利哥緣以色列人、嚴閉邑門、無人出入、"],[6,6,2,"耶和華諭約書亞曰、我以耶利哥、及其王與勇士、悉付爾手、"],[6,6,3,"爾諸戰士、日當遶城一周、六日皆然、"],[6,6,4,"祭司七人、當執七角、行於匱前、越至七日、遶城七次、祭司吹角、"],[6,6,5,"吹角聲長、爾曹聞之、衆當大聲而呼、城垣則圮、民各直前、"],[6,6,6,"嫩之子約書亞召諸祭司曰、當舁耶和華約匱、祭司七人執七角、行於匱前、"],[6,6,7,"又諭民曰、前往遶城、戰士行於耶和華匱前、"],[6,6,8,"諭民已畢、祭司七人執七角、行於耶和華前而吹之、耶和華約匱隨其後、"],[6,6,9,"戰士行於吹角之祭司前、後隊行於匱後、祭司且行且吹其角、"],[6,6,10,"約書亞命民曰、勿號呼、勿發聲、勿出言、迨我命爾號呼之日、始可號呼、"],[6,6,11,"遂使耶和華匱遶城一次、返營而宿、○"],[6,6,12,"詰朝、約書亞夙興、祭司舁耶和華匱、"],[6,6,13,"祭司七人執七角、行於耶和華匱前而吹之、戰士行於其前、後隊行於耶和華匱後、祭司且行且吹其角、"],[6,6,14,"次日遶城一次、而返於營、如是者六日、"],[6,6,15,"越至七日、黎明夙興、遶城如前、惟是日七次、"],[6,6,16,"遶至七次、祭司吹角、約書亞諭民曰、爾其號呼、蓋耶和華以城付爾、"],[6,6,17,"城曁所有、必歸耶和華以滅之、惟妓喇合、及其全家、可俾生存、以其曾匿我儕所遣之使也、"],[6,6,18,"當滅之物、爾宜愼而遠之、免取當滅之物、使以色列營服詛而遭禍、"],[6,6,19,"金銀曁銅鐵諸器、悉歸耶和華爲聖、入於其庫、"],[6,6,20,"於是民衆號呼、祭司吹角、民聞角聲、遂大號呼、城垣則圮、衆各直入、而取其城、"],[6,6,21,"邑中男女老幼、牛羊與驢、皆以刃殲之、"],[6,6,22,"約書亞命窺地之二人曰、入妓之室、以婦及其所有、攜之而出、循爾所誓、"],[6,6,23,"少年二諜遂入、以喇合、與其父母兄弟、及凡所有、並其親屬、攜之而出、置以色列營外、"],[6,6,24,"衆以火燬其城、曁其中所有、惟金銀及銅鐵諸器、置於耶和華室之庫、"],[6,6,25,"約書亞因妓喇合曾匿所遣窺耶利哥之使、故生存之、與其父家、及凡所有、使居以色列中、至於今日、"],[6,6,26,"時、約書亞以誓戒衆曰、起而重建耶利哥城者、必服詛於耶和華、築基時、必喪長子、置門時、必喪季子、"],[6,6,27,"耶和華與約書亞偕、其聲名洋溢乎四方、"],[6,7,1,"以色列人緣當滅之物而獲罪、蓋猶大支派、謝拉曾孫、撒底孫、迦米子亞干、取當滅之物、致耶和華怒以色列人、○"],[6,7,2,"約書亞自耶利哥、遣人往伯特利東近伯亞文之艾、告之曰、往窺其地、遂往窺之、"],[6,7,3,"返見約書亞曰、艾人維寡、毋勞民衆皆往、二三千人斯可擊之、"],[6,7,4,"於是約三千人往彼、爲艾人所敗而遁、"],[6,7,5,"艾人殺其三十六人、自邑門追之、至示巴琳、擊之於阪、民遂喪膽、荏弱如水、"],[6,7,6,"約書亞裂衣、與以色列長老蒙塵於首、在耶和華匱前、伏地至暮、"],[6,7,7,"約書亞曰、噫、主耶和華歟、何爲導斯民過約但、付我於亞摩利人手、以滅我乎、我願仍居約但東爲幸、"],[6,7,8,"主歟、以色列人背敵而遁、余復何言、"],[6,7,9,"迦南族與此地居民聞之、必圍困我、滅我名於天下、而爾爲爾大名、將何爲耶、"],[6,7,10,"耶和華諭約書亞曰、起、何爲伏地若此、"],[6,7,11,"以色列人犯罪、背我所命之約、擅取當滅之物、匿於己器、行竊作僞、"],[6,7,12,"故以色列人見詛、不能禦敵、背敵而遁、若不除當滅之物於爾中、我必不復偕爾、"],[6,7,13,"起、使民自潔、諭之曰、自潔以備明日、蓋以色列之上帝耶和華云、以色列歟、爾中匿有當滅之物、非先除之、不能禦敵、"],[6,7,14,"詰朝必循支派而至、耶和華所取支派、必循宗族而至、耶和華所取宗族、必循室家而至、耶和華所取室家、必使盡人而至、"],[6,7,15,"被取之人、匿有當滅之物、必燬其人、及凡所有、緣背耶和華之約、妄爲於以色列中也、"],[6,7,16,"翌日、約書亞夙興、使以色列人循其支派而至、取猶大支派、"],[6,7,17,"使猶大宗族至、而取謝拉族、使謝拉族至、而取撒底、"],[6,7,18,"使其室家盡人而至、則取猶大支派、謝拉曾孫、撒底孫、迦米子亞干、"],[6,7,19,"約書亞謂亞干曰、我子歟、爾當歸榮於以色列之上帝耶和華、向之認罪、以爾所行告我、毋隱、"],[6,7,20,"亞干對曰、我誠獲罪於以色列之上帝耶和華、所行如是、"],[6,7,21,"我於所奪之物中、見有示拿之美衣、及銀二百舍客勒、金鋌五十舍客勒、則貪而取之、今在我幕、匿於地中、銀在其下、"],[6,7,22,"約書亞遣人趨至厥幕、其衣果藏於幕、銀在其下、"],[6,7,23,"乃自幕中取出、攜至約書亞及以色列衆、置於耶和華前、"],[6,7,24,"約書亞同以色列衆、取謝拉裔亞干、與銀衣金鋌、曁子女牛羊驢幕、及凡所有、攜至亞割谷、"],[6,7,25,"約書亞曰、爾何貽禍我儕、今日耶和華必禍爾、於是以色列人以石擊之、以火焚之、及其全家、"],[6,7,26,"堆石其上、至今猶存、耶和華乃息其烈怒、故其地名曰亞割谷、至於今日、"],[6,8,1,"耶和華諭約書亞曰、勿畏葸、勿恐惶、起率軍旅往艾、我以艾王、與其民邑地、悉付爾手、"],[6,8,2,"宜待艾與其王、如昔之待耶利哥與其王然、惟所獲之貨財牲畜、爾曹可取爲己有、當設伏於邑西、"],[6,8,3,"約書亞與軍旅皆起、欲往於艾、遂簡勇士三萬、夤夜遣之、"],[6,8,4,"命之曰、伏於邑西、距城勿甚遠、咸備以戰、"],[6,8,5,"我與所率民衆、近於其邑、彼必如昔出而攻我、我則遁逃、"],[6,8,6,"誘之出而追我、遠離其邑、自謂其人遁逃如昔、"],[6,8,7,"我旣遁逃、爾則起自伏所、而取其邑、爾上帝耶和華必付之於爾手、"],[6,8,8,"旣取邑、必焚之、遵耶和華所言、此我所命爾者、"],[6,8,9,"約書亞旣遣之、遂往艾西、伏於伯特利與艾之間、是夜約書亞宿於民中、○"],[6,8,10,"詰朝、約書亞夙興、核其民衆、偕以色列長老、先民往艾、"],[6,8,11,"所從軍旅、近於邑前、建營艾北、有谷間於營艾、"],[6,8,12,"又簡五千人伏於艾西、在伯特利與艾之間、"],[6,8,13,"民之全軍列於邑北、伏兵列於邑西、是夜約書亞至谷中、"],[6,8,14,"艾王見之、與民夙興、急出、至亞拉巴前、尅期與以色列人戰、不知邑西有伏兵也、"],[6,8,15,"約書亞與以色列衆佯爲敗北、循野之道而遁、"],[6,8,16,"艾民咸集、追襲約書亞、被誘離邑、"],[6,8,17,"艾與伯特利、不留一男、悉追以色列族、邑門不閉、"],[6,8,18,"耶和華諭約書亞曰、以所執之戟指艾、我必付之爾手、約書亞以戟指之、"],[6,8,19,"旣舉手、伏兵急起、離伏所、趨入邑而取之、卽焚以火、"],[6,8,20,"艾人回顧、望見邑中煙燄沖天、欲遁、左右維艱、遁於野之以色列人、轉而攻追之者、"],[6,8,21,"約書亞與以色列衆、見伏兵已取邑、邑中煙燄上騰、反殺艾人、"],[6,8,22,"伏兵亦出邑擊之、艾人困於其中、以色列人前後擊之、靡有孑遺、無得脫者、"],[6,8,23,"生擒艾王、解至約書亞、"],[6,8,24,"以色列人在田野、旣盡殺所追之艾人、使殞於刃、乃返於邑、以刃屠之、"],[6,8,25,"是日艾民亡者、男女計一萬二千人、"],[6,8,26,"蓋約書亞執戟指艾、不縮其手、迨及盡滅其民、"],[6,8,27,"惟邑中之牲畜貨財、以色列人取而歸己、遵耶和華諭約書亞之命、"],[6,8,28,"約書亞焚艾、使永爲邱墟、荒廢至今、"],[6,8,29,"懸艾王於木、至於暮、日入時、循約書亞命、取屍下木、投諸邑門、壘石爲堆、至今猶存、○"],[6,8,30,"時、約書亞爲以色列之上帝耶和華、建壇於以巴路山、"],[6,8,31,"乃循耶和華僕摩西所命以色列人、摩西律書所載、以原石未加鐵器者建壇、民衆爲耶和華獻燔祭、及酬恩祭於其上、"],[6,8,32,"約書亞在彼、於以色列人前、以摩西所書法律、錄之於石、"],[6,8,33,"以色列衆、與長老、有司、士師、或宗族、或賓旅、咸立於匱之左右、在舁耶和華約匱之利未人祭司前、其半向基利心山、其半向以巴路山、爲以色列人祝嘏、循耶和華僕摩西所命、"],[6,8,34,"厥後、約書亞宣讀律書所載祝詛諸言、"],[6,8,35,"摩西所命者、約書亞於以色列會衆、與其婦孺、及其中賓旅前、悉宣讀之、不遺一詞、"],[6,9,1,"約但之西、山地、窪地、及利巴嫩相對大海之濱、赫人、亞摩利人、迦南人、比利洗人、希未人、耶布斯人、諸王聞此、"],[6,9,2,"同心會集、欲與約書亞、及以色列族戰、○"],[6,9,3,"基遍居民、聞約書亞所行於耶利哥及艾之事、"],[6,9,4,"乃行詭譎、佯爲使者、以驢負舊囊、與旣裂復縫之酒革囊、"],[6,9,5,"足著舊而且補之履、身服舊衣、所備之餅、則乾而霉焉、"],[6,9,6,"至吉甲營、見約書亞、謂彼與以色列人曰、我自遠方來、請與立約、"],[6,9,7,"以色列人謂希未人曰、爾殆居於我中、焉能與爾立約、"],[6,9,8,"其人謂約書亞曰、我乃爾僕、約書亞曰、爾曹何人、奚自而來、"],[6,9,9,"曰、僕緣爾上帝耶和華之名、來自極遠之地、蓋我聞其聲譽、及其所行於埃及、"],[6,9,10,"曁所行於約但東之亞摩利二王、卽希實本王西宏、都亞斯他錄之巴珊王噩、"],[6,9,11,"我之長老、與我本土居民、謂我曰、當攜途間餱糧、往迎之曰、我乃爾僕、請與立約、"],[6,9,12,"我啟行詣爾時、自家所取之餅尚熱、今則乾而霉矣、"],[6,9,13,"革囊盛酒、其時尚新、今則裂矣、因路甚遠、衣履悉敝、"],[6,9,14,"以色列人遂食其糧、而不諮諏耶和華、"],[6,9,15,"約書亞與之修好立約、容其生存、會中牧伯向之發誓、"],[6,9,16,"立約後、越三日、聞其爲鄰、居於其中、"],[6,9,17,"以色列人啟行、三日至其邑、卽基遍、基非拉、比錄、基列耶琳、"],[6,9,18,"以色列人不擊之、因其牧伯曾指以色列之上帝耶和華、向之發誓、會衆遂怨牧伯、"],[6,9,19,"牧伯謂會衆曰、我儕旣指以色列之上帝耶和華而誓、不可害之、"],[6,9,20,"旣與之誓、必容其生存、免震怒及我、"],[6,9,21,"又曰、當容其生存、於是使爲採薪者、汲水者、服事會衆、遵牧伯所言、"],[6,9,22,"約書亞召之曰、爾居我中、何言離此甚遠、以欺我耶、"],[6,9,23,"因此爾必服詛、爲奴之人歷世不絕、採薪汲水、以供我上帝室、"],[6,9,24,"對曰、有人確告僕云、爾上帝耶和華曾諭其僕摩西、以此全地賜爾、悉滅其民、故我甚懼、以命難保、遂行是事、"],[6,9,25,"今我在爾手、爾所視爲善爲正者、則行之、"],[6,9,26,"於是約書亞救之、脫於以色列人手、免遭殺戮、其待之如此、"],[6,9,27,"是日使在耶和華所簡之處、爲會衆及耶和華之壇、採薪汲水、至於今日、"],[6,10,1,"耶路撒冷王亞多尼洗德、聞約書亞取艾盡滅之、待艾與王、如昔之待耶利哥及其王然、亦聞基遍居民與以色列人修好、而處其中、"],[6,10,2,"則懼甚、蓋基遍爲大邑、如王都、較艾尤大、人皆勇士、"],[6,10,3,"於是耶路撒冷王亞多尼洗德、遣人見希伯崙王何咸、耶末王毘蘭、拉吉王雅非亞、伊磯倫王底璧、告之曰、"],[6,10,4,"其來助我、以擊基遍、因其與約書亞及以色列人修好、"],[6,10,5,"亞摩利五王、卽耶路撒冷王、希伯崙王、耶末王、拉吉王、伊磯倫王、遂相會集、率諸軍往基遍、建營攻之、"],[6,10,6,"基遍人遣使至吉甲營、見約書亞曰、居山之亞摩利諸王、集以攻我、請爾速來、救助爾僕、勿遲、"],[6,10,7,"約書亞與軍旅勇士、遂自吉甲而往、"],[6,10,8,"耶和華諭約書亞曰、勿懼之、我付之於爾手、無一能禦爾者、"],[6,10,9,"約書亞自吉甲終夜而行、猝然臨敵、"],[6,10,10,"耶和華潰敵於以色列人前、遂於基遍大行殺戮、追及伯和崙阪擊之、至於亞西加、瑪基大、"],[6,10,11,"適敵遁於以色列人前、在伯和崙阪、耶和華自天降大雹擊之、至亞西加、死於雹者、較以色列人以刃殺者尤衆、"],[6,10,12,"耶和華以亞摩利人付以色列族之日、約書亞祈禱耶和華、在以色列衆前曰、日其停於基遍、月其止於亞雅崙谷兮、"],[6,10,13,"日則停、月則止、待民復仇於敵、此事非書於雅煞珥紀乎、載云、日停於天中、不速下者竟日、"],[6,10,14,"前乎此、後乎此、未有如是之一日、耶和華俯聽人言、爲以色列人戰也、○"],[6,10,15,"約書亞與以色列衆返吉甲營、"],[6,10,16,"五王逃至瑪基大、匿於穴、"],[6,10,17,"或告約書亞曰、五王旣遇、匿於瑪基大穴、"],[6,10,18,"約書亞曰、轉大石於穴口、使人守之、"],[6,10,19,"爾衆勿緩、追襲爾敵、擊其後軍、勿容入邑、爾上帝耶和華付之於爾手矣、"],[6,10,20,"約書亞與以色列人大行殺戮、而翦滅之、其餘入於堅城、"],[6,10,21,"民則安返瑪基大營、見約書亞、無人鼓舌、訾以色列族者、"],[6,10,22,"約書亞曰、啟穴口、攜五王出而詣我、"],[6,10,23,"遂攜耶路撒冷希伯崙耶末拉吉伊磯倫五王、出穴、詣之、"],[6,10,24,"旣攜詣約書亞、約書亞召以色列衆至、謂諸軍長曰、來前、足踐王頸、遂前踐之、"],[6,10,25,"約書亞謂之曰、勿畏葸、勿恐惶、強乃心、壯乃志、耶和華待爾所攻之敵、俱必如是、"],[6,10,26,"厥後、約書亞擊殺之、懸諸五木、至於日暮、"],[6,10,27,"日入時、循約書亞命、取屍下木、擲於所匿之穴、置大石於穴口、至今猶存、○"],[6,10,28,"是日約書亞取瑪基大、刃擊其邑與其王、滅其居民、靡有孑遺、其待瑪基大王、如昔之待耶利哥王然、"],[6,10,29,"約書亞與以色列衆、自瑪基大往攻立拿、"],[6,10,30,"耶和華以邑與王、付於以色列人手、刃擊其邑、殺其居民、靡有孑遺、其待立拿王、如昔之待耶利哥王然、"],[6,10,31,"約書亞與以色列衆、自立拿往拉吉、建營攻之、"],[6,10,32,"耶和華以拉吉付於以色列人手、翌日取之、擊之以刃、殺其居民、如待立拿然、"],[6,10,33,"時基色王荷蘭來助拉吉、約書亞擊之、及其民衆、靡有孑遺、"],[6,10,34,"約書亞與以色列衆、自拉吉往伊磯倫、建營攻之、"],[6,10,35,"卽日取之、擊之以刃、滅其居民、如待拉吉然、"],[6,10,36,"約書亞與以色列衆、自伊磯倫往攻希伯崙、"],[6,10,37,"取之、刃擊其邑與其王、曁厥屬邑、殺其居民、靡有孑遺、如待伊磯倫然、其邑與民、悉翦滅之、"],[6,10,38,"約書亞與以色列衆、返攻底璧、"],[6,10,39,"取之、並取其王、曁厥屬邑、以刃擊之、滅其居民、靡有孑遺、其待底璧與其王、如待希伯崙立拿與其王然、"],[6,10,40,"如是約書亞徧擊四境、山地、山麓、南土、窪地、及其諸王、靡有孑遺、凡有氣息者、悉翦滅之、循以色列之上帝耶和華所命、"],[6,10,41,"自加低斯巴尼亞至迦薩、又歌珊四境、爰及基遍、悉爲約書亞所擊、"],[6,10,42,"斯王與其土地、約書亞一時取之、蓋以色列之上帝耶和華爲以色列人戰也、"],[6,10,43,"約書亞與以色列衆、遂返吉甲營、"],[6,11,1,"夏瑣王耶賓旣聞此事、遣人往見瑪頓王約巴、曁伸崙押煞二王、"],[6,11,2,"與居北方山地、曁基尼烈南之亞拉巴、那弗多珥西之窪地諸王、"],[6,11,3,"及居東西之迦南人、與亞摩利人、赫人、比利洗人、並居山地之耶布斯人、米斯巴地、黑門山麓之希未人、"],[6,11,4,"皆率軍旅而出、其人多如海沙、車馬甚衆、"],[6,11,5,"列王咸集、建營米倫水濱、欲與以色列人戰、"],[6,11,6,"耶和華諭約書亞曰、勿緣之而懼、明日此時、我以見殺之衆、付以色列人、爾當斷其馬筋、焚其車輛、"],[6,11,7,"約書亞率軍旅、猝至米倫水濱攻之、"],[6,11,8,"耶和華付之於以色列人手、遂擊之、追至大西頓、與米斯利弗瑪音、迄於東方之米斯巴平原、俱翦滅之、靡有孑遺、"],[6,11,9,"約書亞遵耶和華命而行、斷其馬筋、焚其車輛、"],[6,11,10,"夏瑣素爲諸國之首、約書亞返取之、刃擊其王、"],[6,11,11,"以色列人刃擊居民、悉行翦滅、凡有氣息者、靡有孑遺、火焚夏瑣、"],[6,11,12,"約書亞取斯諸邑與其王、刃擊其衆、而翦滅之、循耶和華僕摩西所命、"],[6,11,13,"建於山岡之邑、以色列人不焚、惟夏瑣爲約書亞所燬、"],[6,11,14,"諸邑貨財牲畜、以色列人取而歸己、人則以刃擊之、至於盡滅、凡有氣息者、靡有孑遺、"],[6,11,15,"昔耶和華所命其僕摩西、摩西傳命約書亞者、約書亞悉遵行之、一無所違、○"],[6,11,16,"約書亞盡取斯土、卽山地、南土、歌珊四境、及其窪地、亞拉巴與以色列山地、及其窪地、"],[6,11,17,"自上西珥之哈拉山、至黑門山麓、利巴嫩谷之巴力迦得、並取其王、擊而殺之、"],[6,11,18,"約書亞與諸王相戰日久、"],[6,11,19,"居基遍之希未人而外、無一邑與以色列人修好者、以色列人悉戰而取之、"],[6,11,20,"蓋耶和華聽其剛愎厥心、與以色列人戰、而被翦滅、不蒙矜恤、循耶和華諭摩西之命、○"],[6,11,21,"是時約書亞往山地、滅亞衲族、卽自希伯崙、底璧、亞拿伯、猶大山地、以色列山地、盡滅其衆、而毀其邑、"],[6,11,22,"亞衲族於以色列地、靡有孑遺、惟於迦薩、迦特、亞實突有之、"],[6,11,23,"約書亞循耶和華諭摩西之命、取斯全地、以給以色列人爲業、依其支派班列、厥後其地息戰、"],[6,12,1,"約但東日出之所、自亞嫩谷至黑門山、及東方亞拉巴全地、以色列人擊其二王、取其土地如左、"],[6,12,2,"亞摩利王西宏都希實本、其所轄之地、自亞嫩谷濱之亞羅珥、及谷中之邑、與基列之半、至亞捫界之雅博溪、"],[6,12,3,"又東方亞拉巴、至基尼烈海、又至東方亞拉巴之鹽海、通伯耶西末之道、南至毘斯迦山麓、"],[6,12,4,"又巴珊王噩、利乏音族所遺者、都亞斯他錄、曁以得來、"],[6,12,5,"其所轄之地、黑門山、撒迦、巴珊全地、至基述瑪迦二族之界、及基列之半、至希實本王西宏之界、"],[6,12,6,"此二王、爲耶和華僕摩西與以色列人所擊、摩西以其地予流便人、迦得人、及瑪拿西半支派爲業、○"],[6,12,7,"約但之西、自利巴嫩谷之巴力迦得、至上西珥之哈拉山、約書亞與以色列人擊其王、以其地予以色列支派爲業、循其班列、"],[6,12,8,"卽山地、窪地、亞拉巴、山麓、曠野、南土、乃赫人、亞摩利人、迦南人、比利洗人、希未人、耶布斯人之地、"],[6,12,9,"其王如左、耶利哥王、近伯特利之艾王、"],[6,12,10,"耶路撒冷王、希伯崙王、"],[6,12,11,"耶末王、拉吉王、"],[6,12,12,"伊磯倫王、基色王、"],[6,12,13,"底璧王、基德王、"],[6,12,14,"何珥瑪王、亞拉得王、"],[6,12,15,"立拿王、亞杜蘭王、"],[6,12,16,"瑪基大王、伯特利王、"],[6,12,17,"他普亞王、希弗王、"],[6,12,18,"亞弗王、拉沙崙王、"],[6,12,19,"瑪頓王、夏瑣王、"],[6,12,20,"伸崙米崙王、押煞王、"],[6,12,21,"他納王、米吉多王、"],[6,12,22,"基低斯王、都迦密之約念王、"],[6,12,23,"都那法多珥之多珥王、都吉甲之戈印王、"],[6,12,24,"得撒王、共三十一王、"],[6,13,1,"約書亞壽高年邁、耶和華諭之曰、爾壽高年邁、當取之地、尚存甚多、"],[6,13,2,"卽非利士四境、基述全地、"],[6,13,3,"自埃及東之西曷溪、北至以革倫界、屬迦南族之地、非利士五伯之迦薩、亞實突、亞實基倫、迦特、以革倫、及南方之亞衞、"],[6,13,4,"又迦南全地、屬西頓之米亞拉、至亞弗、及亞摩利界、"],[6,13,5,"又迦巴勒人之地、東方之利巴嫩全地、自黑門山麓之巴力迦得、至哈馬道、"],[6,13,6,"又自利巴嫩、至米斯利弗瑪音、所有居山之西頓人、我必逐之於以色列人前、當循我命、籤分其地、予以色列人爲業、"],[6,13,7,"斯地分與九支派、及瑪拿西半支派爲業、"],[6,13,8,"瑪拿西半支派、及流便迦得二支派、已得其業於約但東、卽耶和華僕摩西所予者、"],[6,13,9,"其地自亞嫩谷濱之亞羅珥、及谷中之邑、與米底巴平原全地、至於底本、"],[6,13,10,"曁都希實本之亞摩利王西宏諸邑、至亞捫族之界、"],[6,13,11,"又有基列、與基述瑪迦二族之境、及黑門全山、巴珊全地、至於撒迦、"],[6,13,12,"都亞斯他錄及以得來、利乏音族所遺者、巴珊王噩之國、斯地之人、摩西擊而逐之、"],[6,13,13,"惟基述瑪迦二族、以色列人未逐、二族居以色列中、至於今日、"],[6,13,14,"利未支派、摩西不與之業、奉以色列上帝耶和華之火祭爲其業、如其所諭、○"],[6,13,15,"摩西給業於流便支派、循其室家、"],[6,13,16,"其界自亞嫩谷濱之亞羅珥、及谷中之邑、沿米底巴平原、"],[6,13,17,"希實本與其平原諸邑、底本、巴末巴力、伯巴力勉、"],[6,13,18,"雅雜、基底莫、米法押、"],[6,13,19,"基列亭、西比瑪、與谷中山上之細列哈沙轄、"],[6,13,20,"伯毘珥、毘斯迦山麓、伯耶西末、"],[6,13,21,"平原諸邑、與都希實本亞摩利王西宏之國、此王及其所轄米甸諸伯、以未、利金、蘇珥、戶珥、利巴、俱爲摩西所擊、"],[6,13,22,"以色列人殺彼衆時、並以刃殺術士、比珥子巴蘭、"],[6,13,23,"流便族之西界乃約但、以上諸邑、與其鄉里、爲流便族之業、循其室家、○"],[6,13,24,"摩西給業於迦得支派、循其室家、"],[6,13,25,"其境乃雅謝基列諸邑、亞捫人地之半、至拉巴相對之亞羅珥、"],[6,13,26,"又自希實本至拉抹米斯巴、及比多寧、更自瑪哈念至底璧界、"],[6,13,27,"谷中之伯亞蘭、伯寧拉、疎割、撒分、卽希實本王西宏國之餘地、沿約但河濱、至基尼烈海隅、在約但東、"],[6,13,28,"以上諸邑、與其鄉里、爲迦得族之業、循其室家、○"],[6,13,29,"摩西給業於瑪拿西半支派、循其室家、"],[6,13,30,"其境自瑪哈念、巴珊全地、卽巴珊王噩之全國、與巴珊境內、睚珥諸邑六十、"],[6,13,31,"基列之半、及巴珊王噩之邑、亞斯他錄以得來、俱歸瑪拿西子瑪吉裔之半、循其室家、○"],[6,13,32,"以上諸業、乃摩西在約但東、摩押平原、耶利哥相對之處所分者、"],[6,13,33,"惟利未支派、摩西不給以業、以色列之上帝耶和華爲其業、如其所諭、"],[6,14,1,"以色列族在迦南地所得之業、卽祭司以利亞撒、嫩之子約書亞、曁以色列支派族長所分者、臚列如左、"],[6,14,2,"其地循耶和華藉摩西所命、掣籤分與九支派有半、"],[6,14,3,"蓋摩西已給業於二支派有半、在約但東、不給業於利未人、"],[6,14,4,"因約瑟裔、分爲瑪拿西以法蓮二支派、故於斯土、不給業於利未人、惟給邑以居、給郊以牧牲畜、而藏貨財、"],[6,14,5,"以色列人循耶和華諭摩西之命、以分其地、○"],[6,14,6,"時、猶大族至吉甲見約書亞、有基尼洗族耶孚尼子迦勒謂之曰、昔在加低斯巴尼亞、耶和華諭其僕摩西關乎爾我之事、爾所知也、"],[6,14,7,"其時我年四十、耶和華僕摩西自加低斯巴尼亞遣我窺地、我以誠心復之、"],[6,14,8,"偕行兄弟使民喪膽、惟我專從我上帝耶和華、"],[6,14,9,"當日摩西誓曰、爾旣專從我上帝耶和華、爾足所履之地、必歸於爾及裔爲業、永世靡曁、"],[6,14,10,"自耶和華諭摩西時、以色列人遊行曠野、迄今四十五年、耶和華依其所言、使我生存、今我年八十有五、"],[6,14,11,"我猶強健、同於摩西遣我之日、昔我有力出入戰鬬、今猶如是、"],[6,14,12,"求爾以耶和華當日所許之山地予我、爾曾聞亞衲族在彼、邑垣宏固、庶耶和華偕我、使我逐之、如其所言、"],[6,14,13,"約書亞乃爲耶孚尼子迦勒祝嘏、以希伯崙給之爲業、"],[6,14,14,"故希伯崙歸基尼洗族耶孚尼子迦勒爲業、至於今日、因其專從以色列之上帝耶和華也、"],[6,14,15,"希伯崙昔名基列亞巴邑、在亞衲族中、亞巴爲至大、厥後其地息戰、"],[6,15,1,"猶大支派、循其室家、掣籤而得之地、其境至以東之邊陲、南至尋野、"],[6,15,2,"其南界、自鹽海之隅、向南之澳、"],[6,15,3,"出亞克拉濱阪之南、延及於尋、由加低斯巴尼亞之南、通希斯崙、至亞達珥、轉至甲加、"],[6,15,4,"由此至押們與埃及溪、至海爲極、是爲南界、○"],[6,15,5,"其東界、卽鹽海、至約但河口、其北界、自海澳、卽約但河口、"],[6,15,6,"至伯曷拉、經伯亞拉巴之北、至流便裔波罕之石、"],[6,15,7,"又自亞割谷而北、至底璧、沿吉甲、卽亞都冥阪相對之所、在河之南、經隱示麥泉、至隱羅結、"],[6,15,8,"由此而往欣嫩子谷、至耶布斯、卽耶路撒冷之南、上及欣嫩谷西之山巔、在利乏音谷之北極、"],[6,15,9,"自此山巔、至尼弗多亞泉、及以弗崙山諸邑、延至巴拉、卽基列耶琳、"],[6,15,10,"自巴拉轉西、至西珥山、經耶琳山之北、耶琳卽基撒崙、下至伯示麥、越亭納、"],[6,15,11,"出以革倫之北、延及施基倫、經巴拉山、至雅比聶、極於海、"],[6,15,12,"西界大海、此乃猶大族四周之界、循其室家、"],[6,15,13,"約書亞遵耶和華命、於猶大族中、以亞衲族祖基列亞巴邑、卽希伯崙、予耶孚尼子迦勒爲業、"],[6,15,14,"迦勒驅亞衲三子、示篩、亞希幔、撻買、"],[6,15,15,"自此往攻底璧居民、底璧昔名基列西弗、"],[6,15,16,"迦勒曰、擊基列西弗而取之者、我必以女押撒妻之、"],[6,15,17,"迦勒弟基納斯子俄陀聶取之、迦勒遂妻以女押撒、"],[6,15,18,"于歸時、勸夫求田於父、女旣下驢、迦勒曰、爾何欲、"],[6,15,19,"曰、求錫嘏於我、父旣嫁我於南土、請賜我以泉、遂以上下泉予之、○"],[6,15,20,"猶大支派、循其室家、所得之業如左、"],[6,15,21,"其近以東界、極南之邑、乃甲薛、以得、雅姑珥、"],[6,15,22,"基拿、底摩拿、亞大達、"],[6,15,23,"基低斯、夏瑣、以提楠、"],[6,15,24,"西弗、提鍊、比亞綠、"],[6,15,25,"夏瑣哈大他、加畧希斯崙、卽夏瑣、"],[6,15,26,"亞曼、示瑪、摩拉大、"],[6,15,27,"哈薩迦大、黑實門、伯帕列、"],[6,15,28,"哈薩書亞、別是巴、比斯約他、"],[6,15,29,"巴拉、以因、以森、"],[6,15,30,"伊勒多臘、基失、何珥瑪、"],[6,15,31,"洗革拉、麥瑪拿、三撒拿、"],[6,15,32,"利巴勿、實忻、亞因、臨門、共二十九邑、與其鄉里、"],[6,15,33,"在窪地有以實陶、瑣拉、亞實拿、"],[6,15,34,"撒挪亞、隱干寧、他普亞、以楠、"],[6,15,35,"耶末、亞杜蘭、梭哥、亞西加、"],[6,15,36,"沙拉音、亞底他音、基底拉、基底羅他音、共十四邑、與其鄉里、"],[6,15,37,"洗楠、哈大沙、麥大迦得、"],[6,15,38,"底連、米斯巴、約帖、"],[6,15,39,"拉吉、波斯加、伊磯倫、"],[6,15,40,"迦本、拉幔、基提利、"],[6,15,41,"基低羅、伯大袞、拿瑪、瑪基大、共十六邑、與其鄉里、"],[6,15,42,"立拿、以帖、亞珊、"],[6,15,43,"益弗他、亞實拿、尼悉、"],[6,15,44,"基伊拉、亞革悉、瑪利沙、共九邑、與其鄉里、"],[6,15,45,"以革倫、與其屬邑鄉里、"],[6,15,46,"自以革倫至海、附近亞實突之處、與其鄉里、"],[6,15,47,"亞實突與其屬邑鄉里、迦薩與其屬邑鄉里、至埃及溪、延及大海爲界、"],[6,15,48,"在山地有沙密、雅提珥、梭哥、"],[6,15,49,"大拿、基列薩拿、卽底璧、"],[6,15,50,"亞拿伯、以實提莫、亞念、"],[6,15,51,"歌珊、何倫、基羅、共十一邑、與其鄉里、"],[6,15,52,"亞拉、度瑪、以珊、"],[6,15,53,"雅農、伯他普亞、亞非加、"],[6,15,54,"宏他、基列亞巴、卽希伯崙、洗珥、共九邑、與其鄉里、"],[6,15,55,"瑪雲、迦密、西弗、淤他、"],[6,15,56,"耶斯列、約甸、撒挪亞、"],[6,15,57,"該隱、基比亞、亭拿、共十邑、與其鄉里、"],[6,15,58,"哈忽、伯夙、基突、"],[6,15,59,"瑪臘、伯亞諾、伊勒提君、共六邑、與其鄉里、"],[6,15,60,"基列巴力、卽基列耶琳、拉巴、共二邑、與其鄉里、"],[6,15,61,"在曠野有伯亞拉巴、密丁、西迦迦、"],[6,15,62,"匿珊、鹽城、隱基底、共六邑、與其鄉里、"],[6,15,63,"居耶路撒冷之耶布斯人、猶大人不能逐之、與之同居耶路撒冷、至於今日、"],[6,16,1,"約瑟後裔掣籤而得之地、自近耶利哥之約但、耶利哥水東之野、由耶利哥而上、越乎山地、至伯特利、"],[6,16,2,"自伯特利至路斯、沿亞基界、至亞他綠、"],[6,16,3,"西至押利提界、延及下伯和崙界、至基色、極於海、"],[6,16,4,"此乃約瑟子瑪拿西以法蓮所得之業、"],[6,16,5,"以法蓮裔循其室家、所得之地、其東界、沿亞他綠亞達、至上伯和崙、"],[6,16,6,"西通北方之密米他、轉東至他納示羅、延及雅挪哈之東、"],[6,16,7,"自雅挪哈、下至亞他綠與拿拉、延及耶利哥、極於約但、"],[6,16,8,"自他普亞而西、至加拿溪、極於海、此乃以法蓮支派循其室家、所得之業、"],[6,16,9,"又有數邑、與其鄉里、在瑪拿西人業中、分歸以法蓮人、"],[6,16,10,"居基色之迦南人、以法蓮人未逐之、仍居以法蓮人中、爲僕服役、至於今日、"],[6,17,1,"瑪拿西支派掣籤而得其地、瑪拿西乃約瑟長子、瑪吉乃瑪拿西長子、基列之父、素爲戰士、故得基列、巴珊、"],[6,17,2,"瑪拿西其餘子孫、循其室家、掣籤得業、其人如左、亞比以謝之裔、希勒之裔、亞斯列之裔、示劍之裔、希弗之裔、示米大之裔、此皆約瑟子瑪拿西之丁男、循其室家、"],[6,17,3,"瑪拿西玄孫、瑪吉曾孫、基列孫、希弗子西羅非哈、無子有女、名瑪拉、挪阿、曷拉、密迦、得撒、"],[6,17,4,"咸就祭司以利亞撒、及嫩之子約書亞、與諸牧伯、曰、耶和華命摩西、在兄弟中以業給我、約書亞遂遵耶和華命、以業給之、在叔伯中、"],[6,17,5,"除約但東之基列巴珊外、瑪拿西族得業十區、"],[6,17,6,"蓋瑪拿西之女、得業於其諸子中、基列地乃屬瑪拿西餘子、"],[6,17,7,"瑪拿西族之界、自亞設至示劍相對之密米他、轉右至隱他普亞居民之地、"],[6,17,8,"他普亞地、屬瑪拿西人、惟近其界之他普亞邑、屬以法蓮人、"],[6,17,9,"其界下至加拿溪南、瑪拿西境內之邑、有屬以法蓮者、瑪拿西界、沿溪北、極於海、"],[6,17,10,"溪南屬以法蓮、溪北屬瑪拿西、海爲其界、北至亞設、東至以薩迦、"],[6,17,11,"瑪拿西在以薩迦亞設境內、得伯善與其鄉里、以伯蓮與其鄉里、多珥與其居民鄉里、隱多珥與其居民鄉里、他納與其居民鄉里、米吉多與其居民鄉里、上乃三岡之邑、"],[6,17,12,"斯邑之民、瑪拿西人不能逐之、迦南人執意居其地、"],[6,17,13,"迨以色列人強盛、使之服役、不盡逐之、○"],[6,17,14,"約瑟裔謂約書亞曰、耶和華旣錫嘏於我、使爲大族、何僅予我一區爲業、"],[6,17,15,"約書亞曰、爾若爲大族、以法蓮山地狹小、可往比利洗利乏音地、伐木以居、"],[6,17,16,"約瑟裔曰、此地不足容我、而居伯善與其鄉里、及耶斯列谷之迦南人、皆有鐵車、"],[6,17,17,"約書亞謂約瑟家以法蓮瑪拿西人曰、爾乃大族、且有大力、不可僅有一區、"],[6,17,18,"山與附近之地、必悉歸爾、雖爲森林、可伐其木而居、迦南人雖強、而有鐵車、爾必逐之、"],[6,18,1,"斯土旣服、以色列會衆集於示羅、而立會幕、"],[6,18,2,"以色列中、尚有七支派、未得其業、"],[6,18,3,"約書亞謂以色列族曰、爾祖之上帝耶和華予爾之地、爾遲遲不往取之、將至何時乎、"],[6,18,4,"爾於各支派中、宜簡三人、我將遣之周行其地、循所應得之業繪圖、歸而就我、"],[6,18,5,"分地爲七、猶大族居南境、約瑟家居北境、"],[6,18,6,"其地繪爲七區、以覆於我、我爲爾掣籤於我上帝耶和華前、"],[6,18,7,"利未人在爾中無業、因供耶和華祭司之職爲其業、迦得流便二支派、瑪拿西半支派、已得其業在約但東、卽耶和華僕摩西所予者、"],[6,18,8,"所委繪圖之人起而往、約書亞囑之曰、爾往周行其地、繪圖歸而就我、我在示羅、爲爾掣籤於耶和華前、"],[6,18,9,"其人遂往、周行其地、依其城邑、繪爲七區、註之於册、返示羅營、見約書亞、"],[6,18,10,"約書亞在示羅、爲之掣籤於耶和華前、以地分與以色列人、循其班列、○"],[6,18,11,"首掣籤、乃便雅憫支派、循其室家得業、其境攝乎猶大約瑟二族之間、"],[6,18,12,"其北界、自約但上至耶利哥北、轉西越乎山地、極於伯亞文野、"],[6,18,13,"由此而南、至路斯阪、路斯卽伯特利、又下至亞他綠亞達、近下伯和崙南之山、"],[6,18,14,"由此而西轉南、自伯和崙南相對之山、至猶大族之邑基列巴力、卽基列耶琳、是爲西境、"],[6,18,15,"南界自基列耶琳極處、轉西至尼弗多亞泉、"],[6,18,16,"下至欣嫩子谷相對之麓、在利乏音谷之北、又至欣嫩谷、近耶布斯南、延及隱羅結、"],[6,18,17,"轉北至隱示麥、及基利綠、在亞都冥阪相對之所、下至流便子波罕之石、"],[6,18,18,"沿亞拉巴之隅、下至亞拉巴、"],[6,18,19,"又沿伯曷拉北、至鹽海之北澳、卽約但河南口、是爲南界、"],[6,18,20,"東則約但爲界、此乃便雅憫裔之業、依其四界、循其室家、"],[6,18,21,"便雅憫支派、循其室家、所得之邑、乃耶利哥、伯曷拉、伊麥基悉、"],[6,18,22,"伯亞拉巴、洗瑪臉、伯特利、"],[6,18,23,"亞文、巴拉、俄弗拉、"],[6,18,24,"基法阿摩尼、俄弗尼、迦巴、共十二邑、與其鄉里、"],[6,18,25,"基遍、拉瑪、比錄、"],[6,18,26,"米斯巴、基非拉、摩撒、"],[6,18,27,"利堅、伊利毘勒、他拉拉、"],[6,18,28,"洗拉、以利弗、耶布斯、卽耶路撒冷、基比亞、基列、共十四邑、與其鄉里、此乃便雅憫裔之業、循其室家、"],[6,19,1,"次掣籤、乃西緬支派、循其室家得業、其境在猶大人業中、"],[6,19,2,"所得之業、乃別是巴、或名示巴、及摩拉大、"],[6,19,3,"哈薩書亞、巴拉、以森、"],[6,19,4,"伊利多拉、比土力、何珥瑪、"],[6,19,5,"洗革拉、伯瑪加博、哈薩蘇撒、"],[6,19,6,"伯利巴勿、沙魯險、共十三邑、與其鄉里、"],[6,19,7,"亞因、利門、以帖、亞珊、共四邑、與其鄉里、"],[6,19,8,"及上諸邑四周鄉里、延至巴拉比珥、卽南方拉瑪、此乃西緬支派之業、循其室家、"],[6,19,9,"因猶大人之業不可勝用、故西緬人得業、在於其中、○"],[6,19,10,"三掣籤、乃西布倫裔、循其室家得業、其境極於撒立、"],[6,19,11,"轉西、上至瑪拉拉、達於大巴設、延及約念相對之溪、"],[6,19,12,"自撒立轉東、向日出之所、至吉斯綠他泊界、延及大比拉、上至雅非亞、"],[6,19,13,"自此而東、至迦特希弗、及以特加汛、出臨門、至尼亞、"],[6,19,14,"沿此而北、至哈拿頓、極於伊弗他伊勒谷、"],[6,19,15,"又有加他、拿哈拉、伸崙、以大拉、伯利恆、共十二邑、與其鄉里、"],[6,19,16,"以上諸邑、與其鄉里、乃西布倫裔之業、循其室家、○"],[6,19,17,"四掣籤、乃以薩迦裔、循其室家得業、"],[6,19,18,"其界內、有耶斯列、基蘇律、書念、"],[6,19,19,"哈弗連、示按、亞拿哈拉、"],[6,19,20,"拉璧、基善、亞別、"],[6,19,21,"利蔑、隱干寧、隱哈大、伯帕薛、"],[6,19,22,"延至他泊、沙哈洗瑪、伯示麥、極於約但、共十六邑、與其鄉里、"],[6,19,23,"以上諸邑、與其鄉里、乃以薩迦支派之業、循其室家、○"],[6,19,24,"五掣籤、乃亞設支派、循其室家得業、"],[6,19,25,"其界內、有黑甲、哈利、比田、押煞、"],[6,19,26,"亞拉米勒、亞末、米沙勒、西至迦密及希曷立納、"],[6,19,27,"轉往日出之所、至伯大袞、及細布倫、轉北至伊弗他伊勒谷、及伯以墨、尼業、達於迦步勒之左、"],[6,19,28,"又至義伯崙、利合、哈們、加拿、及西頓大邑、"],[6,19,29,"轉至拉瑪、及推羅堅城、又轉至何薩、極於海、在亞革悉境、"],[6,19,30,"又有烏瑪、亞弗、利合、共二十二邑、與其鄉里、"],[6,19,31,"以上諸邑、與其鄉里、乃亞設支派之業、循其室家、○"],[6,19,32,"六掣籤、乃拿弗他利裔、循其室家得業、"],[6,19,33,"其界自希利弗、及撒拿音橡樹、亞大米尼吉、雅比聶、至拉共、極於約但、"],[6,19,34,"轉西至亞斯納他泊、由此而往戶割、南至西布倫、西至亞設、東至猶大、在約但濱、日出之所、"],[6,19,35,"其堅城、乃西丁、側珥、哈末、拉甲、基尼烈、"],[6,19,36,"亞大瑪、拉瑪、夏瑣、"],[6,19,37,"基低斯、以得來、隱夏瑣、"],[6,19,38,"以利穩、密大伊勒、和璉、伯亞納、伯示麥、共十九邑、與其鄉里、"],[6,19,39,"以上諸邑、與其鄉里、乃拿弗他利支派之業、循其室家、○"],[6,19,40,"七掣籤、乃但之支派、循其室家得業、"],[6,19,41,"其界內、有瑣拉、以實陶、伊珥示麥、"],[6,19,42,"沙拉賓、亞雅崙、伊提拉、"],[6,19,43,"以倫、亭拿他、以革倫、"],[6,19,44,"伊利提基、基比頓、巴拉、"],[6,19,45,"伊胡得、比尼比拉、迦特臨門、"],[6,19,46,"美耶昆、拉昆、與約帕相對之境、"],[6,19,47,"厥後但人之界開拓、因其往攻利善而取之、擊之以刃、據而居之、以祖但之名、名利善曰但、"],[6,19,48,"以上諸邑、與其鄉里、乃但支派之業、循其室家、○"],[6,19,49,"依界分地旣畢、以色列人乃於其中、以地給嫩之子約書亞爲業、"],[6,19,50,"遵耶和華命、以其所求之邑、以法蓮山地亭拿西拉與之、遂重建其邑而居焉、"],[6,19,51,"以上所載、乃祭司以利亞撒、與嫩之子約書亞、及以色列支派族長、在示羅會幕門、耶和華前、掣籤所分之業、於是分地之事畢焉、"],[6,20,1,"耶和華諭約書亞曰、"],[6,20,2,"告以色列人云、當遵我藉摩西所命爾者、簡立逃城、"],[6,20,3,"俾無心而誤殺人者、可遁於彼、爲爾逃避復仇之所、"],[6,20,4,"逃至斯邑者、當立邑門、自訴其事於長老、長老接之入邑、給之以所、使居其中、"],[6,20,5,"若復仇者追之、勿以殺人者付於其手、蓋彼誤殺其鄰、素無仇恨、"],[6,20,6,"彼居是邑、迨其受鞫於會衆前、俟當時之大祭司卒、乃返所逃出之故邑、而歸其家、"],[6,20,7,"遂簡立加利利之基低斯、在拿弗他利山地、示劍、在以法蓮山地、基列亞巴、卽希伯崙、在猶大山地、"],[6,20,8,"又於約但濱、耶利哥東、簡立流便支派平原、在野之比悉、迦得支派基列之拉末、瑪拿西支派巴珊之哥蘭、"],[6,20,9,"斯邑旣定、凡以色列人、與其中賓旅、誤殺人者、可逃於彼、免死於復仇者之手、迨其受鞫於會衆前、"],[6,21,1,"維時、利未族長就祭司以利亞撒、與嫩之子約書亞、及以色列支派族長、於迦南地示羅、"],[6,21,2,"謂之曰、耶和華藉摩西命給邑爲我居所、給郊以牧牲畜、"],[6,21,3,"以色列人、遂遵耶和華命、由其業中、以邑與郊給利未人如左、○"],[6,21,4,"爲哥轄室家掣籤、利未人中、祭司亞倫之裔、由猶大西緬便雅憫三支派中、得十三邑、"],[6,21,5,"哥轄他裔、由以法蓮及但二支派、與瑪拿西半支派室家中、得十邑、"],[6,21,6,"革順裔、由以薩迦亞設拿弗他利三支派、與巴珊瑪拿西半支派室家中、得十三邑、"],[6,21,7,"米拉利裔、循其室家、由流便迦得西布倫三支派中、得十二邑、"],[6,21,8,"以上邑郊、乃以色列人掣籤、予利未人、循耶和華藉摩西所命、○"],[6,21,9,"由猶大西緬二支派中、所予利未人之邑如左、"],[6,21,10,"利未人哥轄室家、亞倫裔、首掣籤而得邑、"],[6,21,11,"乃亞衲族祖亞巴之邑、卽猶大山地之基列亞巴、及其四郊、"],[6,21,12,"惟邑之田疇鄉里、予耶孚尼子迦勒爲業、"],[6,21,13,"予祭司亞倫裔者、乃殺人者之逃城希伯崙與其郊、立拿與其郊、"],[6,21,14,"雅提珥與其郊、以實提摩與其郊、"],[6,21,15,"何崙與其郊、底璧與其郊、"],[6,21,16,"亞因與其郊、淤他與其郊、伯示麥與其郊、由此二支派中、共予九邑、"],[6,21,17,"又由便雅憫支派中、予以基遍與其郊、迦巴與其郊、"],[6,21,18,"亞拿突與其郊、亞勒們與其郊、共四邑、"],[6,21,19,"亞倫裔爲祭司者、共得十三邑、與其郊、○"],[6,21,20,"利未人哥轄他裔之室家、由以法蓮支派中、掣籤得邑、"],[6,21,21,"乃殺人者之逃城、卽以法蓮山地之示劍與其郊、基色與其郊、"],[6,21,22,"基伯先與其郊、伯和崙與其郊、共四邑、"],[6,21,23,"由但之支派中、得伊利提基與其郊、基比頓與其郊、"],[6,21,24,"亞雅崙與其郊、迦特臨門與其郊、共四邑、"],[6,21,25,"由瑪拿西半支派中、得他納與其郊、迦特臨門與其郊、共二邑、"],[6,21,26,"哥轄他裔之室家、共得十邑與其郊、○"],[6,21,27,"利未室家革順裔、由瑪拿西半支派中、得殺人者之逃城、卽巴珊之哥蘭與其郊、比施提拉與其郊、共二邑、"],[6,21,28,"由以薩迦支派中、得基善與其郊、大比拉與其郊、"],[6,21,29,"耶末與其郊、隱干寧與其郊、共四邑、"],[6,21,30,"由亞設支派中、得米沙勒與其郊、押頓與其郊、"],[6,21,31,"黑甲與其郊、利合與其郊、共四邑、"],[6,21,32,"由拿弗他利支派中、得殺人者之逃城、卽加利利之基低斯與其郊、哈末多珥與其郊、加珥坦與其郊、共三邑、"],[6,21,33,"革順裔循其室家、共得十三邑與其郊、○"],[6,21,34,"其餘利未人、米拉利裔之室家、由西布倫支派中、得約念與其郊、加珥他與其郊、"],[6,21,35,"丁拿與其郊、拿哈拉與其郊、共四邑、"],[6,21,36,"由流便支派中、得比悉與其郊、雅雜與其郊、"],[6,21,37,"基底莫與其郊、米法押與其郊、共四邑、"],[6,21,38,"由迦得支派中、得殺人者之逃城、卽基列之拉末與其郊、瑪哈念與其郊、"],[6,21,39,"希實本與其郊、雅謝與其郊、共四邑、"],[6,21,40,"利未人米拉利裔、循其室家、共得十二邑、"],[6,21,41,"利未人在以色列族中、共得四十八邑與其郊、"],[6,21,42,"邑有四郊、各邑皆然、○"],[6,21,43,"耶和華以全地賜以色列人、卽昔誓許其列祖者、以色列人據而居之、"],[6,21,44,"耶和華使之四周綏安、如其所誓厥祖之言、以敵付於其手、諸敵莫之能禦、"],[6,21,45,"耶和華所許錫嘏以色列家、其言悉應無遺、"],[6,22,1,"維時、約書亞召流便人、迦得人、及瑪拿西半支派人、"],[6,22,2,"告之曰、耶和華僕摩西所命、爾悉遵守、我之所命、爾亦聽從、"],[6,22,3,"至今日久、不離爾兄弟、且守爾上帝耶和華所命、"],[6,22,4,"今爾上帝耶和華踐其前言、使爾兄弟得其綏安、爾可返幕、在約但東、耶和華僕摩西所賜爾爲業之地、"],[6,22,5,"惟當謹愼、遵行耶和華僕摩西所諭爾之誡命法度、愛爾上帝耶和華、悉從其道、盡守其誡、一心一意附而事之、"],[6,22,6,"於是約書亞爲之祝嘏、而遣之往、遂歸其幕、○"],[6,22,7,"昔摩西在巴珊、給業於瑪拿西半支派、其他半支派、約書亞給之以業於兄弟中、在約但西、遣之歸幕時、爲之祝嘏、"],[6,22,8,"謂曰、爾攜資財豐裕、牲畜殷繁、金銀銅鐵、衣服孔多、今返爾幕、以爾所獲敵財、分與兄弟、○"],[6,22,9,"於是流便人、迦得人、瑪拿西半支派人、別以色列族、離迦南之示羅、歸基列地、卽循耶和華藉摩西所命、而據之業、"],[6,22,10,"旣至迦南地、近約但之境、乃築高壇、巍然可觀、"],[6,22,11,"以色列人聞流便人、迦得人、瑪拿西半支派人、在迦南地、近約但之境、以色列人界內築壇、"],[6,22,12,"以色列會衆遂集於示羅、欲往攻之、"],[6,22,13,"遣祭司以利亞撒子非尼哈往基列地、見流便人、迦得人、瑪拿西半支派人、"],[6,22,14,"又遣以色列各支派牧伯十人、卽以色列億兆之族長偕往、"],[6,22,15,"咸至基列地、見流便人、迦得人、瑪拿西半支派人曰、"],[6,22,16,"耶和華會衆云、爾今轉離、不從耶和華、干犯以色列之上帝、爲己築壇、悖逆耶和華、此何罪耶、"],[6,22,17,"昔拜毘珥之罪、我儕以爲小乎、耶和華會衆緣此遘癘、至今罪未盡免、"],[6,22,18,"爾今又欲轉離、不從耶和華乎、今日悖逆耶和華、明日彼必怒以色列會衆、"],[6,22,19,"如爾所得之地、以爲不潔、可歸耶和華會幕所在之地、得業於我儕中、但除我上帝耶和華壇外、勿築別壇、悖逆耶和華及我儕、"],[6,22,20,"昔謝拉裔亞干、豈非於當滅之物干罪、致怒及於以色列會衆乎、是其人之罪、不獨亡一人也、○"],[6,22,21,"流便人、迦得人、瑪拿西半支派人、對以色列億兆之族長曰、"],[6,22,22,"全能之上帝耶和華、全能之上帝耶和華知之、以色列人亦將知之、如我悖逆耶和華、或干犯之、願其今日不救我、"],[6,22,23,"若我築壇、轉離不從耶和華、或獻燔祭素祭酬恩祭於其上、願耶和華討之、"],[6,22,24,"我儕行此、乃由預防之故、有意而爲、言恐日後爾裔謂我裔曰、爾與以色列之上帝耶和華何與、"],[6,22,25,"爾流便人、迦得人歟、耶和華旣定約但爲爾我之界、爾與耶和華無與、如是、爾裔必使我裔不寅畏耶和華、"],[6,22,26,"故曰、不如築壇、非爲獻燔祭或他祭、"],[6,22,27,"惟在爾我間、及爾我之裔間爲證、使我亦以燔祭、酬恩祭、及他祭、供事於耶和華前、免日後爾裔謂我裔曰、爾與耶和華無與、"],[6,22,28,"故曰、日後有人以此問我、或我後裔、則可答曰、試觀我祖所築耶和華壇之式、非爲獻燔祭及他祭、惟在爾我間爲證而已、"],[6,22,29,"我今決不悖逆耶和華、轉離不從之、在我上帝耶和華幕前之壇外、更築他壇、以獻燔祭素祭及他祭、○"],[6,22,30,"祭司非尼哈、及所偕會衆之牧伯、卽以色列億兆之族長、聞流便迦得瑪拿西人之言則悅、"],[6,22,31,"祭司以利亞撒子非尼哈、謂流便迦得瑪拿西人曰、我今日知耶和華在我儕中、因爾未干罪於耶和華、援以色列人脫於耶和華手、"],[6,22,32,"祭司以利亞撒子非尼哈、與諸牧伯、別流便迦得人、離基列、返迦南、見以色列人而覆之、"],[6,22,33,"以色列人亦悅之、頌美上帝、不復言往攻流便迦得人、毀其所居之地、"],[6,22,34,"流便迦得人名其壇曰證、蓋曰耶和華爲上帝、是壇於爾我間爲證也、"],[6,23,1,"耶和華使以色列人綏安、脫於四周之敵、歷日已久、約書亞亦壽高年邁、"],[6,23,2,"乃召以色列衆、及其長老族長、士師有司、謂之曰、我壽高年邁、"],[6,23,3,"爾上帝耶和華緣爾故、所行於列國者、爾所目擊、蓋爲爾戰者、乃爾上帝耶和華也、"],[6,23,4,"自約但至大海日入之鄉、所遺之民、及我所滅之族、我以其地分與爾諸支派爲業、"],[6,23,5,"爾上帝耶和華必逐斯民於爾前、使離爾目、爾則據有其地、如爾上帝耶和華所言、"],[6,23,6,"故當毅然遵行摩西律書所錄、勿偏於左、勿偏於右、"],[6,23,7,"爾中遺民、勿與之交、勿稱其神之名、勿指以誓、勿奉事、勿跪拜、"],[6,23,8,"惟親近爾上帝耶和華、如素所爲、"],[6,23,9,"強大之民、耶和華逐之於爾前、無能禦爾、至於今日、"],[6,23,10,"爾中之人、一能驅千、蓋爾上帝耶和華爲爾戰、如其所言、"],[6,23,11,"故當謹愼、愛爾上帝耶和華、"],[6,23,12,"爾若轉而合於爾中遺民、與之嫁娶往來、"],[6,23,13,"則當確知爾上帝耶和華、必不復逐斯民於爾目前、彼必於爾爲網羅、爲機檻、脇下之鞭、目中之刺、迨爾滅亡、於爾上帝耶和華所賜之美地、"],[6,23,14,"今我將行舉世必行之路、爾乃一心一意、知爾上帝耶和華所許賜爾之福、無或少遺、無一弗應、"],[6,23,15,"爾上帝耶和華所許之福旣已臨爾、諸禍亦必臨爾、迨爾上帝耶和華滅絕爾、於其所賜之美地、"],[6,23,16,"如爾背爾上帝耶和華所命之約、崇事他神、而跪拜之、耶和華必震怒乎爾、致爾速亡於其所賜之美地、"],[6,24,1,"約書亞集以色列諸支派於示劍、召其長老族長、士師有司、咸至、立於上帝前、"],[6,24,2,"約書亞謂民曰、以色列之上帝耶和華云、古昔爾祖亞伯拉罕、及拿鶴之父他拉、居於河東、崇事他神、"],[6,24,3,"我攜爾祖亞伯拉罕、自河東導之徧行迦南地、賜之以撒、繁其苗裔、"],[6,24,4,"又賜以撒生雅各、以掃、以西珥山錫以掃爲業、惟雅各與其子孫下埃及、"],[6,24,5,"我遣摩西亞倫、且降災於埃及、依我所行、後導爾出、"],[6,24,6,"爾祖出埃及、至紅海、埃及人率車騎追至海濱、"],[6,24,7,"彼呼籲耶和華、則置幽暗於爾與埃及人間、並使海水反淹其人、我所行於埃及、乃爾目擊、爾居曠野、歷時旣久、"],[6,24,8,"我導爾入亞摩利人所居之地、在約但東、彼與爾戰、我付之於爾手、滅之於爾前、爾遂據有其地、"],[6,24,9,"其時摩押王西撥子巴勒、起攻以色列人、遣人召比珥子巴蘭詛爾、"],[6,24,10,"我不聽之、彼乃祝爾、如是救爾脫於其手、"],[6,24,11,"爾過約但、至耶利哥、耶利哥人、亞摩利人、比利洗人、迦南人、赫人、革迦撒人、希未人、耶布斯人、咸與爾戰、我悉付之爾手、"],[6,24,12,"使大蜂驅亞摩利二王於爾前、不藉爾刃爾弓、"],[6,24,13,"非爾所墾之地、我以賜爾、非爾所建之邑、賜爾居之、非爾所植之葡萄園、橄欖園、爾食其果、"],[6,24,14,"今當寅畏耶和華、以眞以誠崇事之、去除爾祖昔在河東、曁在埃及所事之神、惟崇事耶和華、"],[6,24,15,"爾若以事耶和華爲不善、今日可擇所欲事者、或爾祖在河東所事之神、或爾所居斯土、亞摩利人之神、至我及我家、必事耶和華、"],[6,24,16,"民對曰、我決不離棄耶和華、而事他神、"],[6,24,17,"蓋我上帝耶和華導我祖及我出埃及、脫於奴隸之室、行大異蹟、使我目擊、護我於所行之途、所過之國、"],[6,24,18,"耶和華又於我前驅逐諸民、卽居斯土之亞摩利人、故我亦必事耶和華、以其爲我上帝也、"],[6,24,19,"約書亞曰、爾不能事耶和華、因彼乃維聖之上帝、忌邪之上帝、不赦爾之罪愆、"],[6,24,20,"爾若離棄耶和華、而事異族之神、則彼福爾之後、轉而禍爾、至於滅亡、"],[6,24,21,"民曰、不然、我必奉事耶和華、"],[6,24,22,"約書亞曰、爾擇耶和華而事之、爾自爲證、曰、我自爲證、"],[6,24,23,"曰、爾中所有異族之神、今當去之、專心歸從以色列之上帝耶和華、"],[6,24,24,"民曰、我必奉事我上帝耶和華、而聽其言、"],[6,24,25,"是日約書亞與民立約、爲之定典章律例於示劍、"],[6,24,26,"約書亞以此言錄於上帝律書、立大石於橡下、在耶和華聖所之側、"],[6,24,27,"謂民曰、耶和華諭我之言、此石悉聞之、可對我爲證、必爲爾證、免爾違爾上帝、"],[6,24,28,"約書亞遂遣衆各歸其業、○"],[6,24,29,"此後、耶和華僕嫩之子約書亞卒、年百有十歲、"],[6,24,30,"葬於其業之界、卽亭拿西拉、在以法蓮山地、迦實岡北、"],[6,24,31,"約書亞存日、以色列人奉事耶和華、約書亞卒後、長老尚在時、亦然、以斯長老知耶和華爲以色列人所行之事也、○"],[6,24,32,"約瑟之骨、以色列人自埃及攜出者、葬於示劍、在雅各以百金、自示劍父哈抹裔所購之地、爲約瑟裔之業、"],[6,24,33,"亞倫子以利亞撒卒、葬於以法蓮山地、其子非尼哈所得之岡、"],[7,1,1,"約書亞卒後、以色列人諮諏耶和華曰、孰可先往、爲我攻迦南人、與之戰、"],[7,1,2,"耶和華曰、猶大人可往、我以斯土付於其手、"],[7,1,3,"猶大人謂其兄弟西緬人曰、爾與我同往、至我所得之地、與迦南人戰、厥後我亦與爾同往、至爾所得之地、西緬人遂偕行、"],[7,1,4,"猶大人乃往、耶和華以迦南人比利洗人付於其手、在比色殺其人一萬、"],[7,1,5,"於彼遇亞多尼比色、與之戰、擊敗迦南人、比利洗人、"],[7,1,6,"亞多尼比色遁、追而擒之、斷其手之巨擘、足之將指、"],[7,1,7,"亞多尼比色曰、昔有七十王、斷其手之巨擘、足之將指、拾食於我几下、今上帝依我所行以報、乃攜至耶路撒冷、而死於彼、○"],[7,1,8,"猶大人攻耶路撒冷取之、擊之以刃、燬之以火、"],[7,1,9,"厥後、往攻居山地南土窪地之迦南人、"],[7,1,10,"又攻居希伯崙之迦南人、擊示篩、亞希幔、撻買、希伯崙昔名基列亞巴、"],[7,1,11,"由此往攻底璧居民、底璧昔名基列西弗、"],[7,1,12,"迦勒曰、擊基列西弗而取之者、我必以女押撒妻之、"],[7,1,13,"迦勒弟基納斯子俄陀聶取之、迦勒遂妻以女押撒、"],[7,1,14,"于歸時、勸夫求田於父、女旣下驢、迦勒曰、爾何欲、"],[7,1,15,"曰、求錫嘏於我、父旣嫁我於南土、今請賜我以泉、迦勒遂以上下泉予之、○"],[7,1,16,"摩西外戚、基尼人也、其裔偕猶大人離椶樹城、至亞拉得南之猶大野、與民同居、"],[7,1,17,"猶大人與其兄弟西緬人偕往、擊居洗法之迦南人、毀滅其邑、遂名曰何珥瑪、"],[7,1,18,"猶大人又取迦薩、亞實基倫、以革倫、曁其四境、"],[7,1,19,"耶和華與猶大人偕、遂據有山地、惟不能逐居谷中者、以其有鐵車故也、"],[7,1,20,"遵摩西命、以希伯崙予迦勒、遂逐亞衲三子、"],[7,1,21,"居耶路撒冷之耶布斯人、便雅憫人未逐之、仍在耶路撒冷、與便雅憫人偕居、至於今日、○"],[7,1,22,"約瑟家往攻伯特利、耶和華偕之、"],[7,1,23,"伯特利昔名路斯、約瑟家遣人窺之、"],[7,1,24,"偵者見一人自邑出、謂之曰、入邑之路、請爾示我、我必善待爾、"],[7,1,25,"其人示以入邑之路、遂刃擊其邑、惟釋其人、及其全家、"],[7,1,26,"其人乃往赫人之地建邑、名曰路斯、迄今其名尚存、○"],[7,1,27,"伯善、他納、多珥、以伯蓮、米吉多、及其鄉里之民、瑪拿西人未逐之、迦南人執意居其地、"],[7,1,28,"迨以色列族強盛、使迦南人服役、不盡逐之、○"],[7,1,29,"居基色之迦南人、以法蓮人未逐之、仍居基色、在以法蓮人中、○"],[7,1,30,"基倫拿哈拉之居民、西布倫人未逐之、仍居西布倫人中、而服其役、○"],[7,1,31,"亞柯、西頓、亞黑拉、亞革悉、黑巴、亞弗革、利合之居民、亞設人未逐之、"],[7,1,32,"居於土著迦南人中、蓋不逐之、○"],[7,1,33,"伯示麥伯亞納之居民、拿弗他利人未逐之、居於土著迦南人中、二邑居民、乃服其役、○"],[7,1,34,"但人爲亞摩利人所逼、使居山地、不許下至平原、"],[7,1,35,"亞摩利人執意居希烈山、亞雅倫、沙賓、厥後約瑟家勝之、使之服役、"],[7,1,36,"亞摩利人之界、自亞克拉濱阪、由西拉而上、"],[7,2,1,"耶和華之使者自吉甲上至波金、曰、我使爾出埃及、攜至所誓爾祖之地、曾言與爾之約、永久不廢、"],[7,2,2,"勿與斯土之民立約、必毀其壇、而爾不聽我言、果何爲哉、"],[7,2,3,"故我又曰、必不逐斯民於爾前、彼將爲爾脇下之棘、其神將爲爾擭、"],[7,2,4,"耶和華之使者向以色列衆言此、民遂大聲號哭、"],[7,2,5,"名其地曰波金、在彼獻祭於耶和華、○"],[7,2,6,"昔約書亞遣民、以色列人各歸其業、據有斯土、"],[7,2,7,"約書亞存日、以色列人奉事耶和華、約書亞卒後、長老尚在時、亦然、以斯長老見耶和華爲以色列人所行大事也、"],[7,2,8,"耶和華僕、嫩之子約書亞卒、年百有十歲、"],[7,2,9,"葬於其業之界、卽亭拿希列、在以法蓮山地、迦實岡北、"],[7,2,10,"斯代之人、咸歸其祖、又興一代、不知耶和華、及其爲以色列人所行之事、○"],[7,2,11,"以色列人行耶和華所惡、崇事巴力、"],[7,2,12,"違棄耶和華、其祖之上帝、卽導之出埃及者、而從四周諸族之神、向之跪拜、激耶和華怒、"],[7,2,13,"違棄耶和華、而崇事巴力、曁亞斯他錄、"],[7,2,14,"耶和華怒以色列族、付於虜者之手、鬻於四周之敵、使不能禦之、"],[7,2,15,"無論何往、耶和華以災禍擊之、如其誓言、民極困苦、"],[7,2,16,"耶和華興起士師、拯民於虜者之手、"],[7,2,17,"乃民不聽士師、狥欲而從他神、向之跪拜、速違厥祖所行之道、不效其從耶和華之命、"],[7,2,18,"耶和華旣爲興起士師、則偕之拯民於敵手、至終其世、蓋耶和華見民受人虐迫而哀歎、乃回其意、"],[7,2,19,"迨士師沒後、民仍轉而行惡、較甚於祖、從事他神、而跪拜之、不改其行、與其頑梗、"],[7,2,20,"耶和華怒以色列人曰、斯民乃背我命其祖所守之約、不聽我言、"],[7,2,21,"故約書亞卒時所遺諸族、我必不復逐之、"],[7,2,22,"以試以色列族效其列祖、遵行耶和華之道否、"],[7,2,23,"耶和華遂留此諸族、不速逐之、亦不付於約書亞手、"],[7,3,1,"耶和華留此諸族、是欲試以色列人未知迦南戰事者、"],[7,3,2,"使以色列後代知習前所未悉之武事、所留諸族如左、"],[7,3,3,"非利士之五伯、迦南人、西頓人、居利巴嫩山之希未人、自巴力黑們山、至哈馬道、"],[7,3,4,"所以留此、爲試以色列人遵耶和華藉摩西諭其祖之誡否、"],[7,3,5,"於是以色列人居迦南人、赫人、亞摩利人、比利洗人、希未人、耶布斯人之中、"],[7,3,6,"取其女爲妻、以女嫁其子、崇事其神、○"],[7,3,7,"以色列人行耶和華所惡、忘其上帝耶和華、而崇事諸巴力、曁木偶、"],[7,3,8,"故耶和華怒以色列人、付之米所波大米王古珊利薩田手、事之八年、"],[7,3,9,"以色列人籲耶和華、耶和華爲之興起救者、卽迦勒弟基納斯子俄陀聶以拯之、"],[7,3,10,"耶和華之神臨之、爲以色列士師出戰、耶和華以米所波大米王古珊利薩田付於其手、使之獲勝、"],[7,3,11,"其地綏安、歷四十年、基納斯子俄陀聶卒、○"],[7,3,12,"以色列人又行耶和華所惡、耶和華因此、使摩押王伊磯倫強盛、以攻以色列、"],[7,3,13,"遂集亞捫亞瑪力二族、往攻以色列、據椶樹城、"],[7,3,14,"以色列人事摩押王伊磯倫、十有八年、"],[7,3,15,"以色列人籲耶和華、耶和華爲之興起救者、卽便雅憫人基拉之子以笏、其人左手較捷、以色列人藉之進貢摩押王伊磯倫、"],[7,3,16,"以笏鑄兩刃之劍、長一肘、繫右股衣內、"],[7,3,17,"進貢摩押王伊磯倫、其王肥甚、"],[7,3,18,"進貢已畢、遣舁者去、"],[7,3,19,"以笏至吉甲偶像處而返、告曰、王歟、我有密事奏爾、王曰、肅靜、侍者咸出、"],[7,3,20,"王在樓上、獨坐涼室、以笏詣之曰、我奉上帝命、有言告爾、王遂起、"],[7,3,21,"以笏伸其左手、拔劍於右股際、以刺王腹、"],[7,3,22,"劍柄亦入、其刃爲脂所蔽、不拔之出、乃洞穿之、"],[7,3,23,"以笏出至廊廡、扃鍵樓門、"],[7,3,24,"旣出、王僕至、見樓門上鍵、曰、王必在內室更衣、"],[7,3,25,"俟久而門不啟、則惶愧、取鑰啟之、見主已死、偃仆於地、"],[7,3,26,"遲疑之際、以笏已遁、過偶像處、逃於西伊拉、"],[7,3,27,"至則吹角於以法蓮山地、以色列人隨之而下、以笏導之、"],[7,3,28,"曰、爾其從我、耶和華以爾敵摩押人付於爾手、衆遂從之、據約但津、不容摩押一人濟、"],[7,3,29,"殺摩押人以萬計、皆壯勇之士、無一逃者、"],[7,3,30,"當時摩押服於以色列人、其地綏安、歷八十年、"],[7,3,31,"厥後、有亞拿子珊迦、以牛杖殺非利士人六百、亦拯以色列人、"],[7,4,1,"以笏旣沒、以色列人又行耶和華所惡、"],[7,4,2,"耶和華付於都夏瑣之迦南王耶賓手、其帥西西拉、居外邦之夏羅設、"],[7,4,3,"有鐵車九百乘、虐待以色列人特甚、歷二十年、以色列人籲耶和華、○"],[7,4,4,"時、有女先知、拉比多妻底波拉、爲以色列士師、"],[7,4,5,"居以法蓮山地、拉瑪伯特利間、在底波拉之椶樹下、以色列人赴之、聽其審鞫、"],[7,4,6,"彼遣人召亞比挪菴子巴拉、自拿弗他利之基低斯至、謂之曰、以色列之上帝耶和華、豈非諭爾云、當率拿弗他利西布倫二族萬人、往他泊山、"],[7,4,7,"我必使耶賓之帥西西拉率車與衆、往基順河詣爾、付於爾手、"],[7,4,8,"巴拉曰、爾偕我往則往、否則不往、"],[7,4,9,"曰、我必與爾偕往、然爾此行不獲榮顯、蓋耶和華將以西西拉付於婦手、遂起、偕往基低斯、"],[7,4,10,"巴拉集西布倫拿弗他利人於基低斯、隨之上者一萬、底波拉偕行、"],[7,4,11,"摩西外戚、何巴之裔、基尼人希百、曾離本族、張幕於撒拿音之橡下、附近基低斯、"],[7,4,12,"或告西西拉曰、亞比挪菴子巴拉上他泊山、"],[7,4,13,"西西拉乃集鐵車九百、與其軍旅、由外邦之夏羅設至基順河、"],[7,4,14,"底波拉謂巴拉曰、爾起、今日乃耶和華以西西拉付於爾手之日、耶和華非爲爾先導乎、於是巴拉下他泊山、萬人隨之、"],[7,4,15,"耶和華刃擊、潰亂西西拉及其車乘軍旅、於巴拉前、西西拉下車、徒行而遁、"],[7,4,16,"巴拉追其車卒、至外邦夏羅設、西西拉全軍悉隕於刃、靡有孑遺、"],[7,4,17,"西西拉徒行、逃至基尼人希百妻雅億之幕、蓋夏瑣王耶賓與希百家和好、"],[7,4,18,"雅億出迎、謂曰、我主請入、毋懼、遂入其幕、雅億以衾覆之、"],[7,4,19,"西西拉曰、我渴、請以少許之水飲我、遂啟革囊、飲之以乳、仍覆以衾、"],[7,4,20,"又曰、爾立幕門、如有來詢者曰、有人在此否、爾則曰無、"],[7,4,21,"西西拉憊而酣寢、雅億取幕釘、手執椎、輕步而前、以釘貫其鬢際、釘之於地、遂昏眩而死、"],[7,4,22,"時、巴拉追至、雅億出迓曰、來、我以爾所求者示爾、巴拉入幕、見西西拉偃臥而死、幕釘尚在鬢際、"],[7,4,23,"如是上帝使迦南王耶賓服於以色列人、"],[7,4,24,"以色列人日強、勝迦南王耶賓、至於滅之、"],[7,5,1,"是日底波拉與亞比挪菴子巴拉歌曰、"],[7,5,2,"以色列之軍長率其軍旅、民亦樂從、當頌美耶和華、"],[7,5,3,"列王歟、爾其俯聞、諸伯歟、爾其傾聽、我必歌頌耶和華、讚揚以色列之上帝耶和華、"],[7,5,4,"耶和華歟、爾出自西珥境、行由以東田、斯時也、地震天漏、雲密雨零、"],[7,5,5,"於耶和華前、山嶽震撼、於以色列之上帝耶和華前、西乃動搖、"],[7,5,6,"當亞拿子珊迦之時、雅億在世之日、通衢寂寞、行人曲徑是由、"],[7,5,7,"以色列中鄉里無人、迨我底波拉起、而爲以色列母、"],[7,5,8,"民簡新神、戰及邑門、以色列族四萬人中、干戈無存、"],[7,5,9,"以色列之渠魁、在民中樂意出戰者、我心愛之、爾其頌美耶和華、"],[7,5,10,"凡爾乘白驢、坐繢罽、及遊行通衢者、咸宜宣揚、"],[7,5,11,"在汲水之所、遠射者之囂、人必稱述耶和華之義事、卽治以色列之義事、其時耶和華民復至邑門、"],[7,5,12,"寤哉寤哉、底波拉歟、寤哉寤哉、爾其謳歌、巴拉歟、爾其興起、亞比挪菴之子歟、引去所虜之人、"],[7,5,13,"維時、所遺貴胄庶民、下攻強敵、耶和華涖臨、爲我下擊勇士、"],[7,5,14,"自以法蓮來者、其原在亞瑪力、相隨便雅憫、雜於爾民中、渠魁由瑪吉而至、執元戎之杖者、由西布倫而來、"],[7,5,15,"以薩迦之牧伯、與底波拉相偕、以薩迦族與巴拉同意、隨之疾趨入谷、維彼流便、在其溪濱、大定厥志、"],[7,5,16,"爾何坐於牢中、聽牧者之笛乎、流便在其溪濱、深自揣度、"],[7,5,17,"基列安居約但東、但何待於舟、亞設坐於海濱、仍處其澳、"],[7,5,18,"西布倫冒死不顧、拿弗他利在田野之高處亦然、"],[7,5,19,"列王來戰、迦南諸王戰於他納、在米吉多水濱、未獲金幣、"],[7,5,20,"列宿自天而戰、由其道而攻西西拉、"],[7,5,21,"基順古河、漂流敵衆、我之靈歟、奮然前往、"],[7,5,22,"健馬騰踔、蹄蹴於途、"],[7,5,23,"耶和華之使者曰、爾其詛米羅斯、嚴詛其居民、以其不來助耶和華、不助耶和華攻勇士、"],[7,5,24,"基尼人希百妻雅億、較衆婦尤爲有福、較居幕之婦尤爲有福、"],[7,5,25,"其人求水、給之以乳、奉之以酥、盛於貴盂、"],[7,5,26,"手執幕釘、右手取匠人之椎、擊西西拉、貫厥頭顱、穿其鬢際、"],[7,5,27,"彼乃卷曲於其足前、顚仆偃臥、卷曲顚仆於其足前、在彼卷曲之處、偃臥而死、"],[7,5,28,"西西拉之母、自窗而望、由櫺而呼、曰、其車何久不至、其輪何行之遲、"],[7,5,29,"其貴婦之慧者應之、彼自言曰、"],[7,5,30,"豈非獲財、共分所虜、各得一二女子、西西拉得文彩之衣、錦繡之服、表裏文繡、以飾所虜者之項、"],[7,5,31,"耶和華歟、願爾諸敵如是滅亡、願愛爾者、如日皎然而出、○其地綏安、歷四十年、"],[7,6,1,"以色列人又行耶和華所惡、耶和華付之於米甸人手、凡歷七年、"],[7,6,2,"米甸之勢、勝於以色列人、以色列人因之在山營窟、爲穴建寨、"],[7,6,3,"旣播厥種、米甸亞瑪力與東方之人、咸上攻之、"],[7,6,4,"築營壘、毀土產、至於迦薩、以色列中食物無存、牛羊及驢俱盡、"],[7,6,5,"蓋敵攜畜與幕而來、如蝗衆多、其人與駝、不可勝數、入於斯土、欲行毀滅、"],[7,6,6,"以色列人緣米甸故、微弱特甚、乃籲耶和華、"],[7,6,7,"旣籲耶和華、"],[7,6,8,"耶和華遣先知告以色列族曰、以色列之上帝耶和華云、我曾導爾出埃及、脫於奴隸之室、"],[7,6,9,"拯爾脫埃及人、曁凡虐爾者之手、驅之於爾前、以其地錫爾、"],[7,6,10,"諭爾曰、我乃爾之上帝耶和華、爾居亞摩利人之地、勿寅畏其神、惟爾不聽我言、○"],[7,6,11,"耶和華之使者至俄弗拉、坐亞比以謝人約阿施橡下、適約阿施子基甸打麥於醡酒處、以避米甸人、"],[7,6,12,"耶和華之使者見曰、英武之人歟、耶和華偕爾、"],[7,6,13,"基甸曰、我主歟、如耶和華偕我、何至遭此、我祖嘗言耶和華導我出埃及、今其異蹟安在、茲乃棄我、付於米甸人手、"],[7,6,14,"耶和華顧之曰、藉爾此力、往救以色列人、脫於米甸人手、非我遣爾往乎、"],[7,6,15,"曰、主歟、瑪拿西中、我家至貧、在我父家、我又至微、何以拯以色列人乎、"],[7,6,16,"耶和華曰、我必偕爾、爾擊米甸之衆、如擊一人、"],[7,6,17,"曰、我若蒙恩於爾前、求示我以徵、俾知與我言者爲爾也、"],[7,6,18,"請勿去此、待我復返、陳禮物於爾前、曰、我必待爾返、"],[7,6,19,"基甸入備山羊羔一、取麪一伊法、作無酵餅、置肉於筐、盛湯於壺、攜至橡下獻之、"],[7,6,20,"上帝之使曰、以肉與餅置於此磐、傾湯其上、乃如是而行、"],[7,6,21,"耶和華之使者以所執之杖端、觸肉與餅、火自磐出、焚肉與餅、使者遂往、不復見、"],[7,6,22,"基甸知爲耶和華之使者、曰、哀哉、主耶和華歟、我面晤耶和華之使者矣、"],[7,6,23,"耶和華曰、安哉、勿懼、爾不至死、"],[7,6,24,"基甸在彼、爲耶和華築壇、名之曰耶和華沙龍、在亞比以謝族之俄弗拉、至今猶存、○"],[7,6,25,"是夕耶和華諭之曰、取爾父之牡犢、及七歲之牛爲第二、毀爾父所築巴力之壇、斫其旁之木偶、"],[7,6,26,"依其常例、爲爾上帝耶和華築壇於此保障之上、以第二牛獻爲燔祭、以所斫之木偶爲柴、"],[7,6,27,"基甸簡僕十人、遵耶和華命而行、但懼父家與邑衆、不敢行之於晝、而行之於夜、"],[7,6,28,"邑衆夙興、見巴力之壇已毀、在旁之木偶已斫、第二牛獻於所築之壇、"],[7,6,29,"遂相問曰、行此者誰、察問之後、則曰、約阿施子基甸所爲也、"],[7,6,30,"邑衆謂約阿施曰、爾子毀巴力壇、斫其旁之木偶、當攜之出、而致之死、"],[7,6,31,"約阿施對敵之者曰、爾欲爲巴力爭辯乎、抑援之乎、凡爲之爭辯者、今晨必死、如巴力果爲神、人毀其壇、任彼自爭可也、"],[7,6,32,"當日以耶路巴力名基甸、曰、旣毀巴力之壇、任巴力與之爭、○"],[7,6,33,"米甸亞瑪力與東方之人咸集、濟河、建營於耶斯列谷、"],[7,6,34,"耶和華之神臨基甸、乃吹角、亞比以謝族咸集從之、"],[7,6,35,"基甸遣使遍行瑪拿西、其人亦集從之、又遣使至亞設、西布倫、拿弗他利、咸來迎之、"],[7,6,36,"基甸謂上帝曰、如爾果循所言、假我手而拯以色列人、"],[7,6,37,"今我以綿羊毛一束、置於禾場、若露獨在毛、而土壤皆乾燥、則知爾假我手拯以色列人、依爾所言、"],[7,6,38,"詰朝、事果如是、基甸夙興、取毛揉之、擠露盈盂、"],[7,6,39,"基甸又謂上帝曰、祈勿我怒、我復進一辭而後已、容再一次試之以毛、我欲羊毛乾燥、而土壤皆霑露、"],[7,6,40,"是夜上帝如言而行、羊毛獨乾燥、土壤皆霑露、"],[7,7,1,"耶路巴力卽基甸、與相從之衆夙興、附哈律泉建營、米甸軍於其北、在谷中、近摩利岡、"],[7,7,2,"耶和華諭基甸曰、從爾者過衆、我不以米甸人付於其手、免以色列人向我自詡曰、我手自救、"],[7,7,3,"當宣告於民曰、凡畏懼戰慄者、可遶基列山而歸、於是歸者二萬二千、留者一萬、"],[7,7,4,"耶和華又諭基甸曰、民猶過衆、導至水濱、我將爲爾試之、所言可偕爾往者、則偕往、不可偕爾往者、則不偕往、"],[7,7,5,"遂導至水濱、耶和華諭基甸曰、凡以舌餂水如犬者、別立一處、跪而飲者亦然、"],[7,7,6,"以手掬水而餂者、計三百人、其餘皆跪而飲、"],[7,7,7,"耶和華諭基甸曰、我必藉此餂水之三百人救爾、以米甸人付於爾手、餘民可歸其所、"],[7,7,8,"於是三百人取餱糧與角、其餘以色列人、則遣之歸己幕、只留三百人、米甸營在其下之谷中、"],[7,7,9,"是夜耶和華諭基甸曰、起、下入敵營、我付之於爾手、"],[7,7,10,"如爾畏葸、不敢往、可攜爾僕普拉、偕至其營、"],[7,7,11,"得聞敵言、則有勇力、可下攻營、遂攜僕普拉而往、至其營隅、近於行伍、"],[7,7,12,"米甸亞瑪力與東方之人、偃臥於谷、如蝗衆多、其駝無數、如海濱之沙、"],[7,7,13,"基甸旣至、適有以夢告同儕曰、我夢麰麥餅一、轉入米甸營、至於一幕、衝而覆之、"],[7,7,14,"同儕曰、此非他、乃以色列人約阿施子基甸之刃、上帝已以米甸全軍付於其手、"],[7,7,15,"基甸聞夢及其占、則崇拜上帝、歸以色列營、曰、起、耶和華已付米甸軍於爾手、"],[7,7,16,"遂分三百人爲三隊、使各執角、並攜空甁、中藏火炬、"],[7,7,17,"命之曰、惟予是瞻是效、我至營隅、所行之事、爾亦行之、"],[7,7,18,"我與從者吹角、爾亦吹之、於營四周呼曰、爲耶和華與基甸、○"],[7,7,19,"時值中更之初、甫易守營、基甸與從者百人至營隅、吹角破甁、"],[7,7,20,"三隊亦吹角破甁、左手執炬、右手執角而吹、呼曰、耶和華與基甸之刃、"],[7,7,21,"各立其所、環營四周、全軍潰亂、呼號而遁、"],[7,7,22,"三百人吹角、耶和華使全營之人以刃自相攻擊、其軍逃至西利拉之伯哈示他、又至亞伯米何拉之界、近於他巴、"],[7,7,23,"以色列人自拿弗他利、亞設、瑪拿西會集、追襲米甸人、"],[7,7,24,"基甸遣使徇於以法蓮山地曰、爾下、迎擊米甸人、據守諸津、至伯巴拉及約但、以法蓮衆咸集、據守諸津、至伯巴拉及約但、"],[7,7,25,"擒米甸二伯俄立西伊伯、殺俄立於俄立磐、殺西伊伯於西伊伯醡酒處、追米甸人、攜俄立西伊伯之首濟約但、至基甸所、"],[7,8,1,"以法蓮人謂基甸曰、爾與米甸人戰、而不招我、何待我如是、遂切責之、"],[7,8,2,"基甸曰、我之所爲、豈能比爾之所爲、以法蓮所採之遺果、詎不勝於亞比以謝所斂之葡萄乎、"],[7,8,3,"上帝以米甸二伯俄立西伊伯、付於爾手、爾之所爲、我焉能及、基甸言此、以法蓮人之怒遂息、"],[7,8,4,"基甸與從者三百人、至約但濟河、雖困憊、而仍追敵、"],[7,8,5,"基甸謂疎割人曰、我追米甸二王西巴撒慕拿、從者困憊、請給以餅、"],[7,8,6,"疎割牧伯曰、西巴撒慕拿之手、豈在爾手、而使我以餅給爾軍乎、"],[7,8,7,"基甸曰、迨耶和華以西巴撒慕拿、付於我手、我必以曠野之荊棘、扑爾之體、"],[7,8,8,"由此而上、至毘努伊勒、亦如是以請、其人所答、如疎割人、"],[7,8,9,"基甸謂之曰、我平安而歸時、必毀此臺、○"],[7,8,10,"當時東方執刃之軍旅、隕者十有二萬、所遺一萬五千、從西巴撒慕拿在加各、"],[7,8,11,"敵營方宴然、基甸由挪巴約比哈東、從居幕者之道、往而擊之、"],[7,8,12,"米甸二王西巴撒慕拿遁、基甸追而擒之、潰其全軍、"],[7,8,13,"約阿施子基甸、自希列斯阪戰場而返、"],[7,8,14,"擒疎割一少者訊之、遂書疎割牧伯長老之名、凡七十七人、"],[7,8,15,"至疎割、語其人曰、昔爾譏我云、西巴撒慕拿之手、豈在爾手、而使我以餅給爾之憊卒乎、試觀其人在此、"],[7,8,16,"遂執邑中長老、以曠野之荊棘懲疎割人、"],[7,8,17,"毀毘努伊勒之臺、殺其邑人、"],[7,8,18,"問西巴撒慕拿曰、爾在他泊、所殺之人若何、曰、似爾、俱有王子之狀、"],[7,8,19,"曰、是我同母兄弟也、我指耶和華之生而誓、爾若存其命、我亦不殺爾、"],[7,8,20,"遂諭長子益帖曰、爾起殺之、惟孺子不拔劍、以尚幼而懼故也、"],[7,8,21,"西巴撒慕拿曰、爾起殺我、蓋人若何、其力亦如之、基甸遂起殺之、取其駝項之新月環、○"],[7,8,22,"以色列人謂基甸曰、爾旣救我脫於米甸人手、爾及子孫當治我儕、"],[7,8,23,"基甸曰、我不治爾、我子亦不治爾、治爾者乃耶和華也、"],[7,8,24,"又曰、我有所求、各以所獲耳環予我、蓋敵乃以實瑪利人、有金耳環、"],[7,8,25,"衆曰、我樂與之、遂鋪其衣、各以所獲耳環、擲於其中、"],[7,8,26,"基甸所索之金耳環、重一千七百舍客勒、此外又得米甸王所佩之月環垂環、所衣之絳衣、及其駝項之索、"],[7,8,27,"基甸用之作聖衣、置於己邑俄弗拉、以色列人狥欲拜之、成爲基甸與其家之機檻、"],[7,8,28,"米甸人服於以色列人、不復昂首、基甸在日、其地綏安、歷四十年、○"],[7,8,29,"約阿施子耶路巴力歸居己第、"],[7,8,30,"基甸妻室衆多、生子七十、"],[7,8,31,"其妾在示劍、亦生一子、基甸命名亞比米勒、"],[7,8,32,"約阿施子基甸壽高而卒、葬於父約阿施之墓、在亞比以謝族之俄弗拉、○"],[7,8,33,"基甸旣沒、以色列人轉而狥欲從諸巴力、立巴力比利土爲其神、"],[7,8,34,"不憶其上帝耶和華、救之脫於四周敵人手者、"],[7,8,35,"亦不依耶路巴力卽基甸、所施於彼之恩、而厚遇其家、"],[7,9,1,"耶路巴力子亞比米勒往示劍、見其母之兄弟、及外祖之眷屬、語之曰、"],[7,9,2,"請爾謂示劍之衆曰、耶路巴力七十子治爾、與一人治爾、孰善、當念我與爾乃骨肉之親、"],[7,9,3,"其母之兄弟、以此言告示劍衆、僉曰、斯乃我兄弟也、遂歸心亞比米勒、"],[7,9,4,"由巴力比利土廟、取銀七十予之、亞比米勒用以募游蕩無賴之徒從之、"],[7,9,5,"乃往俄弗拉、入於父家、殺其兄弟七十人於一石上、皆耶路巴力子、僅遺季子約坦、因其自匿也、○"],[7,9,6,"示劍人曁米羅族、咸集於示劍誌石之橡下、立亞比米勒爲王、"],[7,9,7,"或以告約坦、乃立於基利心山巔、揚聲呼曰、示劍人歟、其聽我言、致上帝亦聽爾言、"],[7,9,8,"昔諸樹欲膏一樹爲其王、謂橄欖樹曰、請爾治我、"],[7,9,9,"橄欖樹曰、我有膏油、可以尊榮上帝與人、豈舍此而搖於衆樹之上乎、"],[7,9,10,"諸樹謂無花果樹曰、爾來治我、"],[7,9,11,"無花果樹曰、我味甘、我果佳、豈舍此而搖於衆樹之上乎、"],[7,9,12,"諸樹謂葡萄樹曰、爾來治我、"],[7,9,13,"葡萄樹曰、我之新釀、可以愉悅上帝與人、豈舍此而搖於衆樹之上乎、"],[7,9,14,"諸樹謂棘曰、爾來治我、"],[7,9,15,"棘曰、若誠膏我爲王治爾、則來匿我蔭下、不然、則願火自棘出、燬利巴嫩之香柏、"],[7,9,16,"今爾立亞比米勒爲王、如爾所爲、果誠且義、善待耶路巴力及其家、酬其夙恩、則可喜悅、"],[7,9,17,"昔我父冒死爲爾戰、拯爾脫於米甸人手、"],[7,9,18,"今爾起而攻我父家、殺其子七十人於一石上、立婢之子亞比米勒爲示劍人王、以其爲爾兄弟也、"],[7,9,19,"如爾今日待耶路巴力及其家、果誠且義、則可因亞比米勒而樂、彼亦可因爾而樂、"],[7,9,20,"否則願火自亞比米勒出、燬示劍人及米羅族、亦願火自示劍人及米羅族出、燬亞比米勒、"],[7,9,21,"約坦畏其兄亞比米勒而避之、逃往比珥居焉、○"],[7,9,22,"亞比米勒爲以色列長、凡歷三年、"],[7,9,23,"上帝使惡神在亞比米勒與示劍人間、示劍人則以詐僞待亞比米勒、"],[7,9,24,"用報耶路巴力七十子所受之殘害、使流血之罪、歸其兄弟亞比米勒及助殺之示劍人、"],[7,9,25,"示劍人設伏於山巔、以伺亞比米勒、凡過之者咸被刦、或以告亞比米勒、○"],[7,9,26,"以別子迦勒、與其昆弟至示劍、示劍人恃之、"],[7,9,27,"出於田間、斂葡萄而醡之、設筵獻頌、入其神廟、式飲式食、而詛亞比米勒、"],[7,9,28,"以別子迦勒曰、亞比米勒爲誰、示劍爲誰、而使我事之、彼非耶路巴力子乎、其督非西布勒乎、莫若事示劍父哈抹之裔、曷爲事彼、"],[7,9,29,"願斯民歸我掌握、我必除亞比米勒、又告亞比米勒曰、增益爾軍而出、"],[7,9,30,"邑長西布勒聞迦勒之言、則怒、"],[7,9,31,"密遣使往見亞比米勒曰、以別子迦勒、偕其昆弟至示劍、慫恿邑衆攻爾、"],[7,9,32,"爾與相從之衆夜起、伏於田間、"],[7,9,33,"詰朝日出之時、夙興攻城、彼與從者出而禦爾、則可相機而行、"],[7,9,34,"亞比米勒與相從之衆夜起、分爲四隊、伏伺示劍、"],[7,9,35,"以別子迦勒出、立於邑門、亞比米勒與從者、自伏處並起、"],[7,9,36,"迦勒見其民衆、謂西布勒曰、有人自山巔而下、西布勒曰、爾見山影、誤以爲人、"],[7,9,37,"迦勒又曰、試觀有人自高地而下、更有一隊、從術士橡樹之路而來、"],[7,9,38,"西布勒曰、爾昔言亞比米勒爲誰、而使我事之、爾之前言、今安在哉、此非爾所藐視之民乎、請出而與之戰、"],[7,9,39,"迦勒遂率示劍人出、與亞比米勒戰、"],[7,9,40,"亞比米勒追之、迦勒逃遁、傷者沿路而仆、直至邑門、"],[7,9,41,"亞比米勒居亞魯瑪、西布勒逐迦勒與其昆弟、不容其居示劍、"],[7,9,42,"翌日、民出至田、或以告亞比米勒、"],[7,9,43,"遂分從者爲三隊、伏於田間、見民由邑出、則起而擊之、"],[7,9,44,"亞比米勒率其隊突前、立於邑門、其餘二隊、擊在田者、"],[7,9,45,"亞比米勒終日攻邑、取之、殺其民、傾其城、布之以鹽、"],[7,9,46,"守示劍臺者聞此、遂入巴力比利土廟之保障、"],[7,9,47,"或告亞比米勒曰、守示劍臺者咸集一處、"],[7,9,48,"亞比米勒與相從之衆陟撒們山、亞比米勒手執斧、斫樹枝、置之於肩、諭從者曰、見我所爲、爾速效之、"],[7,9,49,"衆遂各斫樹枝、從之、置於保障、縱火焚之、居示劍臺者皆死、男女約千人、○"],[7,9,50,"亞比米勒往提備斯、建營取之、"],[7,9,51,"邑中有堅臺、民衆男女皆逃入、閉門而登臺巔、"],[7,9,52,"亞比米勒至臺前攻之、近臺門、欲焚以火、"],[7,9,53,"有婦以磨之上石、擲亞比米勒首、破其頭顱、"],[7,9,54,"亞比米勒急呼執兵之少者曰、拔刃殺我、免人云我見戮於婦、少者遂刺之而死、"],[7,9,55,"以色列人見亞比米勒已死、各歸其所、"],[7,9,56,"亞比米勒殺兄弟七十人、所行於父之惡、上帝報之若是、"],[7,9,57,"示劍人之惡、上帝亦報之、耶路巴力子約坦之詛、悉臨之焉、"],[7,10,1,"亞比米勒後、以薩迦人朵多孫、普亞子陀拉興起、救以色列人、居以法蓮山地之沙密、"],[7,10,2,"爲以色列士師、歷二十三年、卒而葬於沙密、○"],[7,10,3,"厥後、基列人睚珥興起、爲以色列士師、歷二十二年、"],[7,10,4,"有子三十、乘驢駒三十、治邑三十、在基列地、至今名曰睚珥鄉里、"],[7,10,5,"睚珥卒、葬於加們、○"],[7,10,6,"以色列人又行耶和華所惡、事諸巴力、與亞斯他錄、曁亞蘭、西頓、摩押、亞捫族、非利士之諸神、違棄耶和華、不崇事之、"],[7,10,7,"耶和華怒以色列人、付於非利士人、及亞捫人之手、"],[7,10,8,"以色列人居約但東、屬基列之亞摩利地者、自是受其擾害暴虐、歷十八年、"],[7,10,9,"亞捫人亦渡約但、攻猶大便雅憫曁以法蓮族、以色列人窘甚、"],[7,10,10,"籲耶和華曰、我棄我之上帝而事巴力、獲罪於爾、"],[7,10,11,"耶和華諭以色列人曰、我豈未拯爾於埃及亞摩利亞捫非利士人乎、"],[7,10,12,"昔西頓亞瑪力馬雲人虐爾、爾呼籲我、我亦拯爾於其手、"],[7,10,13,"爾乃棄我、而事他神、我不復拯爾矣、"],[7,10,14,"爾可往籲所簡之神、爾遭難時、任其拯之、"],[7,10,15,"以色列人謂耶和華曰、我干罪矣、任爾隨意待我、惟求今日救援、"],[7,10,16,"遂去其中異族之神、而事耶和華、耶和華因其困苦、中心愀然、"],[7,10,17,"時、亞捫人集而建營於基列、以色列人亦集而建營於米斯巴、"],[7,10,18,"基列民之牧伯相議曰、誰先戰亞捫人、彼必爲基列民長、"],[7,11,1,"基列人耶弗他、大勇士也、乃基列之子、妓之所生、"],[7,11,2,"基列妻亦生子、旣長、逐耶弗他、曰、爾乃外婦子、不可嗣業於我父家、"],[7,11,3,"耶弗他避兄弟、居陀伯地、游蕩之徒歸而從之、○"],[7,11,4,"逾時、亞捫人與以色列戰、"],[7,11,5,"基列長老往陀伯地、招耶弗他、"],[7,11,6,"曰、爾來爲我軍長、與亞捫人戰、"],[7,11,7,"耶弗他曰、爾非憾我、逐我於父家乎、今爾遭難、何就我耶、"],[7,11,8,"基列長老曰、我今就爾、請爾偕行、與亞捫人戰、爲我基列民長、"],[7,11,9,"耶弗他曰、爾若導我歸、與亞捫人戰、而耶和華付之於我手、我則爲爾長乎、"],[7,11,10,"曰、爾我間耶和華爲證、我必依爾言而行、"],[7,11,11,"耶弗他與基列長老偕行、民遂立之爲長爲帥、耶弗他在米斯巴、陳述其辭於耶和華前、○"],[7,11,12,"耶弗他遣使見亞捫王曰、爾與我何與、致爾至我、而攻我地乎、"],[7,11,13,"亞捫王謂使者曰、以色列人出埃及時、奪我土地、自亞嫩至雅博、迄於約但、今可安然反我斯土、"],[7,11,14,"耶弗他又遣使見亞捫王曰、"],[7,11,15,"耶弗他云、摩押及亞捫人之地、以色列人未嘗奪之、"],[7,11,16,"以色列人出埃及、過荒野、至紅海、及加低斯、"],[7,11,17,"遣使告以東王曰、請容我過爾境、以東王不允、遣使見摩押王、亦不允、以色列人遂居加低斯、"],[7,11,18,"旣經曠野、遶以東摩押之境、由摩押東而來、建營於亞嫩外、亞嫩爲摩押界、不入其境、"],[7,11,19,"以色列人遣使見都希實本之亞摩利王西宏、告之曰、請容我過爾境、以適我土、"],[7,11,20,"西宏不信以色列人、不令過其境、乃集民衆、建營於雅雜、與以色列戰、"],[7,11,21,"以色列之上帝耶和華、以西宏及其民衆、付於以色列人手、以色列人擊之、取亞摩利人所居之地、"],[7,11,22,"得亞摩利境、自亞嫩至雅博、自曠野至約但、"],[7,11,23,"以色列之上帝耶和華、旣逐亞摩利人於其民前、則爾豈可得其地乎、"],[7,11,24,"爾神基抹賜爾之地、爾豈不取之乎、我之上帝耶和華逐人於我前、其地我亦取之、"],[7,11,25,"爾豈愈於摩押王西撥子巴勒乎、彼豈嘗攻以色列人、而與之戰乎、"],[7,11,26,"以色列人居希實本、亞羅珥、與其鄉里、曁沿亞嫩諸邑、歷三百年、當時爾何不取之、"],[7,11,27,"我未嘗獲罪於爾、爾乃攻我、以惡相待、願鞫人之耶和華、今日在以色列人亞捫人間、判其是非、"],[7,11,28,"亞捫王不聽耶弗他使所言、○"],[7,11,29,"耶和華之神臨耶弗他、遂巡基列瑪拿西地、至基列之米斯巴、自此而往、至亞捫族、"],[7,11,30,"耶弗他許願於耶和華曰、如爾果以亞捫人付於我手、"],[7,11,31,"則我自亞捫族安然而歸時、出我門而迓者、必歸於耶和華、我必獻之爲燔祭、"],[7,11,32,"耶弗他抵亞捫族、與之戰、耶和華付之於其手、"],[7,11,33,"遂擊之、自亞羅珥至米匿、及亞備勒基拉明、取邑二十、大行殺戮、於是亞捫族服於以色列人、○"],[7,11,34,"耶弗他止有一女、別無子女、返米斯巴、至己家、其女執鼗、舞蹈出迎、"],[7,11,35,"耶弗他見之、則裂衣曰、嗚呼吾女、使我憯怛、加我苦難、我向耶和華啟口、不能食言、"],[7,11,36,"女曰、我父歟、爾旣向耶和華啟口、請踐其言、以行於我、蓋耶和華爲爾、復仇於爾敵亞捫族、"],[7,11,37,"又謂父曰、求父允我一事、假我二月、俾我得與女伴登山、哀我以處子終、"],[7,11,38,"曰、往哉、乃遣之、期以二月、遂與女伴偕往、在山哀其以處子終、"],[7,11,39,"二月旣盈、女歸父所、父循所許之願、以待其女、乃不字而終、"],[7,11,40,"厥後以色列女立爲常例、每年爲基列人、耶弗他女哀悼四日、"],[7,12,1,"以法蓮人集而北往、謂耶弗他曰、爾與亞捫族戰、而不招我偕往、曷故、我必以火燬爾、及爾第宅、"],[7,12,2,"耶弗他曰、我曁我民、與亞捫族大戰、我曾招爾、爾不救我脫於其手、"],[7,12,3,"我見爾不我救、遂冒死往攻亞捫族、而耶和華付之於我手、今日爾來攻我、曷故、"],[7,12,4,"耶弗他乃集基列人、與以法蓮人戰、而擊殺之、因以法蓮人曰、爾基列人、在以法蓮瑪拿西間、乃以法蓮之逋逃者也、"],[7,12,5,"基列人據約但津、以禦以法蓮人、以法蓮人逃遁者、有言請許我濟、基列人則問之曰、爾爲以法蓮人否、如其言否、"],[7,12,6,"則曰、試言示播列、其人音不相符、而言西播列、則執之、殺於約但津旁、當時以法蓮人隕沒者、四萬二千人、○"],[7,12,7,"基列人耶弗他、爲以色列士師、凡歷六年、卒而葬於基列之一邑、○"],[7,12,8,"厥後、伯利恆人以比讚爲以色列士師、"],[7,12,9,"有子三十、女三十、皆出嫁、爲子娶媳三十、"],[7,12,10,"彼爲以色列士師、凡歷七年、卒而葬之於伯利恆、○"],[7,12,11,"厥後、西布倫人以倫爲以色列士師、凡歷十年、"],[7,12,12,"卒而葬於西布倫之亞雅倫、○"],[7,12,13,"厥後、比拉頓人希列子押頓爲以色列士師、"],[7,12,14,"有子四十、孫三十、共乘驢駒七十、彼爲以色列士師、凡歷八年、"],[7,12,15,"卒而葬於以法蓮地之境比拉頓、在亞瑪力之山地、"],[7,13,1,"以色列人又行耶和華所惡、耶和華付之於非利士人手、歷四十年、"],[7,13,2,"但之室家、有瑣拉人名瑪挪亞者、其妻不姙不育、"],[7,13,3,"耶和華之使者見於婦曰、爾素不姙不育、今必懷姙生子、"],[7,13,4,"爾其謹愼、酒與醇醪皆勿飲、不潔之物皆勿食、"],[7,13,5,"爾必懷姙生子、薙髮之刀、勿加其首、子自出胎、爲拿細耳人、歸於上帝、肇救以色列人、脫於非利士人手、"],[7,13,6,"婦歸告夫曰、有上帝僕就我、其容髣髴上帝之使、可畏之甚、我未問其奚自、彼未以名告我、"],[7,13,7,"乃謂我曰、爾將懷姙生子、酒與醇醪皆勿飲、不潔之物皆勿食、蓋此子自出胎、爲拿細耳人歸於上帝、至於死日、"],[7,13,8,"瑪挪亞禱於耶和華曰、主歟、請使所遣上帝僕、復至我所、教我如何以待將生之子、"],[7,13,9,"上帝允其所祈、婦坐於田、上帝使復就之、夫不在焉、"],[7,13,10,"婦趨告夫曰、昔就我者、今復顯見、"],[7,13,11,"瑪挪亞起、隨妻詣其人曰、昔與婦言者爾乎、曰、是也、"],[7,13,12,"瑪挪亞曰、願爾言驗、我待此子、當循何例、其行若何、"],[7,13,13,"耶和華之使者曰、我所告婦者、俱宜愼之、"],[7,13,14,"勿食葡萄樹所產、勿飲酒與醇醪、勿食不潔之物、凡我所諭、彼必守之、"],[7,13,15,"瑪挪亞謂使者曰、請爾少留、待我爲備山羊之羔、"],[7,13,16,"耶和華之使者曰、爾雖留我、我不食爾餐、如備燔祭、必以獻耶和華、其言此者、因瑪挪亞不知其爲耶和華之使也、"],[7,13,17,"瑪挪亞曰、爾何名、爾言驗時、我則尊爾、"],[7,13,18,"耶和華之使者曰、我名奇妙、何以詢爲、"],[7,13,19,"瑪挪亞取山羊之羔、及素祭、陳於磐上、以獻耶和華、使者所行奇妙、瑪挪亞與其妻並覩之、"],[7,13,20,"壇上火燄上騰、使者乘之而昇、瑪挪亞曁妻見之、則俯伏於地、"],[7,13,21,"耶和華之使者不復見於瑪挪亞與其妻、瑪挪亞乃知其爲耶和華之使也、"],[7,13,22,"語其妻曰、我儕必死、因覩上帝也、"],[7,13,23,"妻曰、如耶和華意欲殺我、必不納我之燔祭素祭、亦不示我以此事、告我以斯言、"],[7,13,24,"婦生子、命名參孫、子長、耶和華錫嘏焉、"],[7,13,25,"耶和華之神始感之、在瑣拉以實陶間之瑪哈尼但、"],[7,14,1,"參孫下亭拿、見一非利士女、"],[7,14,2,"歸告父母曰、我在亭拿見一非利士女、請爲我娶之、"],[7,14,3,"父母曰、爾同儕我衆民中、豈無女子、致爾娶於未受割之非利士人乎、參孫謂父曰、我深悅斯女、請爲我娶之、"],[7,14,4,"其父母不知斯事由於耶和華、參孫尋釁、欲攻非利士人、是時非利士人轄以色列人、"],[7,14,5,"參孫與父母下亭拿、至葡萄園、有一稚獅、咆哮迎之、"],[7,14,6,"參孫大爲耶和華之神所感、手雖無械、而裂獅如羔羊、不以所行告其父母、"],[7,14,7,"遂往與女語、甚悅之、"],[7,14,8,"未幾復至、欲娶以歸、離途轉視獅尸、見羣蜂與蜜在其中、"],[7,14,9,"取蜜於手、且行且食、至父母所、亦予之食、不以蜜出獅尸告、"],[7,14,10,"父至女所、參孫設筵於彼、蓋少者素有此例、"],[7,14,11,"衆見參孫、則簡三十人爲其伴侶、"],[7,14,12,"參孫語之曰、容我以隱語試爾、七日宴間、如能詳釋告我、我則給爾枲衣三十領、外衣三十襲、"],[7,14,13,"若不能詳釋、爾則給我枲衣三十領、外衣三十襲、僉曰、請宣隱語、使我聞之、"],[7,14,14,"曰、自食者出食、自強者出甘、歷至三日、未能解其隱語、"],[7,14,15,"迨及七日、謂參孫妻曰、可誘爾夫、爲我詳釋隱語、不然、我必以火燬爾、及爾父家、爾延我來、欲奪我所有乎、"],[7,14,16,"參孫妻哭於其前曰、爾乃惡我、而不我愛、爾以隱語試我同族、而不以之告我、曰、我未告父母、豈告爾乎、"],[7,14,17,"宴歷七日、妻哭其前、至於七日、爲妻所迫、乃以隱語告之、妻告同族、"],[7,14,18,"七日日未入時、邑人告曰、孰甘於蜜、孰強於獅、參孫曰、若不用我牝牛而耕、則不能解我隱語、"],[7,14,19,"耶和華之神大感參孫、遂下亞實基倫、殺三十人、褫其衣、以給解隱語者、盛怒而返父家、"],[7,14,20,"其妻適其所友之伴侶、"],[7,15,1,"厥後、時值麥秋、參孫攜一山羊之羔探妻、曰、吾欲入室見之、妻父不許、"],[7,15,2,"曰、我意爾憾之甚、故嫁於爾伴侶、其妹較彼不尤美乎、可娶以代、"],[7,15,3,"參孫語衆曰、今我加害於非利士人、亦無尤焉、"],[7,15,4,"遂往執野犬三百、以尾相繫、束炬於二尾間、"],[7,15,5,"炬旣燃、放火入非利士人之禾稼、凡束而堆積者、與未刈者、曁橄欖園、悉爲所焚、"],[7,15,6,"非利士人問曰、行此者誰、或曰、亭拿人之壻參孫、因以其妻適伴侶故也、非利士人遂至、以火焚女及其父、"],[7,15,7,"參孫曰、爾旣行是、我必復仇而後已、"],[7,15,8,"遂擊非利士人、大行殺戮、尸相枕籍、後往以坦巖穴居焉、○"],[7,15,9,"非利士人上、建營於猶大、布於利希、"],[7,15,10,"猶大人曰、爾來攻我、曷故、曰、我來欲縛參孫、以其所行於我者加乎其身、"],[7,15,11,"有猶大人三千、至以坦巖穴、謂參孫曰、豈不知我爲非利士人所轄乎、何行此以累我耶、曰、以其所行於我者、行之於彼也、"],[7,15,12,"猶大人曰、我來欲縛爾、付於非利士人手、參孫曰、與我誓約、爾不親擊我、"],[7,15,13,"曰、否、祇縛爾付於其手、必不殺爾、遂以新索二縛之、由巖攜之而上、"],[7,15,14,"旣至利希、非利士人呼而迎之、參孫大爲耶和華之神所感、臂上之索、如經火之麻、脫於其手、"],[7,15,15,"參孫見驢之新頰骨、伸手取之、擊人以千計、"],[7,15,16,"曰、我以驢頰骨行戮、積尸成壘、我以驢頰骨殺人、其數盈千、"],[7,15,17,"言畢、手擲頰骨、其地遂名拉末利希、"],[7,15,18,"參孫渴甚、籲耶和華曰、爾藉僕手、大施拯救、今將渴死、而陷未受割者之手、"],[7,15,19,"上帝裂利希之窪處、有水湧出、飲之、精神頓復而蘇、故其泉名曰隱哈歌利、在於利希、至今猶存、"],[7,15,20,"非利士人轄以色列族時、參孫爲士師、歷二十年、"],[7,16,1,"參孫往迦薩、見一妓、就之、"],[7,16,2,"或告迦薩人曰、參孫至此、遂伏邑門、竟夕環守、靜默無聲、意謂待至黎明、我必殺之、"],[7,16,3,"參孫旣臥、中夜而興、取邑門之扉與楗、倂二橛而拔之、荷之於肩、至希伯崙前之山巔、○"],[7,16,4,"厥後、參孫在梭烈谷、愛一女、名大利拉、"],[7,16,5,"非利士牧伯就女曰、爾其誘之、察其何由有此大力、我儕何以勝之、致能縛而苦之、則我各以銀一千一百給爾、"],[7,16,6,"大利拉謂參孫曰、請爾告我、何由有此大力、何術可以縛而苦爾、"],[7,16,7,"參孫曰、如以未乾之新弦七縛我、我則荏弱、無異他人、"],[7,16,8,"於是非利士牧伯攜未乾之新弦七予女、女則縛之、"],[7,16,9,"女旣設伏於內室、告曰、參孫、非利士人涖爾、參孫遂斷其弦、如斷經火之麻縷、仍不知其力之奚自、"],[7,16,10,"大利拉謂參孫曰、爾欺我而言誑、請告我何以縛爾、"],[7,16,11,"曰、如以未用之新索縛我、我則荏弱、無異他人、"],[7,16,12,"大利拉遂以新索縛之、曰、參孫、非利士人涖爾、是時伏者俟於內室、參孫卽斷臂索、如斷一縷、"],[7,16,13,"大利拉謂參孫曰、爾欺我而言誑、越至於今、請告我何以縛爾、曰、以我首髮七綹、與緯同織、則可、"],[7,16,14,"女遂以橛釘其髮、曰、參孫、非利士人涖爾、參孫卽寤、拔機之橛與緯、"],[7,16,15,"女曰、爾心不在我、何云愛我乎、爾欺我者三、未告我以大力何由而有、"],[7,16,16,"女日以言促迫之、參孫中心憂鬱、幾及於死、"],[7,16,17,"以心所藏悉告之、曰、我自母胎、爲拿細耳人歸於上帝、薙髮之刀、未加於首、如薙我髮、我力自去、我則荏弱、無異他人、"],[7,16,18,"大利拉見其以心所藏悉告之、則遣人召非利士牧伯曰、今彼以心所藏悉告於我、請爾復至、惟此一次、非利士牧伯遂至、攜金於手、"],[7,16,19,"女使參孫枕膝而寢、招人薙其髮七綹、遂困苦之、其力果去、"],[7,16,20,"女曰、參孫、非利士人涖爾、參孫寤曰、我且出、逍遙如昔、而不知耶和華已離之矣、"],[7,16,21,"非利士人遂執之、抉其目、解至迦薩、繫以銅鏈、使旋磨於獄、"],[7,16,22,"其髮薙後漸長、○"],[7,16,23,"非利士牧伯集衆、大祭其神大袞、而取歡樂、曰、我神以敵參孫付於我手、"],[7,16,24,"民見之、則頌讚其神曰、我神付敵於我手、彼乃敗我邦國、殺我多人者也、"],[7,16,25,"中心欣喜時、則曰、其召參孫、爲我作劇、遂召參孫出獄、置之柱間、乃作劇於其前、"],[7,16,26,"參孫謂執手之童曰、容捫室柱、使我倚之、"],[7,16,27,"室充男女、非利士牧伯咸在、室頂亦有男女、約三千人、觀參孫作劇、"],[7,16,28,"參孫籲耶和華曰、主耶和華歟、求爾垂念我、上帝歟、求爾堅固我、惟此一次、以報非利士人抉我二目之仇、"],[7,16,29,"乃執室所賴之二中柱、一以左手、一以右手、而憑依之、"],[7,16,30,"曰、願與非利士人偕亡、遂屈身盡力曳之、室乃傾圮、覆於諸伯衆民之上、如是、參孫死時所殺、較之生時所殺尤多、"],[7,16,31,"其兄弟與父家俱至、取之而歸、葬於父瑪挪亞之墓、在瑣拉以實陶間、參孫爲以色列士師、歷二十年、"],[7,17,1,"以法蓮山地、有人名米迦、"],[7,17,2,"謂其母曰、爾銀一千一百被竊、因而咒詛、且告於我、其銀在此、我取之矣、母曰、願耶和華錫嘏我子、"],[7,17,3,"其子以銀一千一百反其母、母曰、我已以此銀、爲吾子獻於耶和華、以造雕像及鑄像、故仍反於爾、"],[7,17,4,"子復以銀反母、母取二百、以予金工、使造雕像及鑄像、置於米迦室、"],[7,17,5,"米迦有神室、遂作聖衣與家神、區別一子、爲其祭司、"],[7,17,6,"時、以色列無王、人各任意而行、○"],[7,17,7,"有少者利未人、居於猶大伯利恆、"],[7,17,8,"離猶大伯利恆邑、覓地以居、行抵以法蓮山地、至於米迦家、"],[7,17,9,"米迦曰、爾奚自、曰、我利未人、自猶大伯利恆來、欲覓地而居、"],[7,17,10,"米迦曰、可偕我居、爲我之父與祭司、歲給十金、衣服一襲、供爾之饌、利未人遂入室、"],[7,17,11,"樂與同居、米迦視之若子、"],[7,17,12,"米迦區別之、乃爲其祭司、居於米迦家、"],[7,17,13,"米迦曰、今有利未人爲祭司、我知耶和華必錫嘏於我、"],[7,18,1,"維時、以色列無王、但之支派、在以色列中、未得其業、故覓地以居、"],[7,18,2,"於族中遣勇士五人、由瑣拉以實陶而往、窺察土地、語之曰、往窺其地、乃適以法蓮山地、至米迦室宿焉、"],[7,18,3,"近其室時、識少者利未人之聲、就而問曰、誰導爾至此、在此何爲、何所得乎、"],[7,18,4,"少者以米迦如何相待告曰、米迦雇我爲其祭司、"],[7,18,5,"曰、請諮諏上帝、使知我之前途、是否利達、"],[7,18,6,"祭司曰、安然而往、爾之前途、耶和華所顧也、"],[7,18,7,"五人遂往、至拉億、見其居民、如西頓人、安逸無慮、因無強者相害也、地離西頓甚遠、不與他人交際、"],[7,18,8,"五人返於瑣拉以實陶、告其昆弟、昆弟問曰、爾意若何、"],[7,18,9,"曰、可起、而往攻之、我見其地甚美、豈可閒居、宜往勿緩、據以爲業、"],[7,18,10,"旣至、必見其民安逸無慮、土壤寬廣、天下物產、罔有所缺、上帝付之爾手、○"],[7,18,11,"於是但之室家六百人、各佩器械、自瑣拉以實陶啟行、"],[7,18,12,"上至猶大之基列耶琳、建營其後、名其地曰瑪哈尼但、至於今日、"],[7,18,13,"由此往以法蓮山地、至米迦室、"],[7,18,14,"昔窺拉億之五人、謂昆弟曰、此室有聖衣家神、雕像鑄像、爾知之乎、當思如何而爲、"],[7,18,15,"遂轉詣米迦室、入少者利未人之室、而問其安、"],[7,18,16,"但人六百、各佩器械、立於門外、"],[7,18,17,"窺地之五人入室、取雕像鑄像、家神聖衣、祭司與佩器械之六百人、立於門外、"],[7,18,18,"五人入室、旣取諸物而出、祭司問曰、爾欲何爲、"],[7,18,19,"曰、勿語、以手掩口、與我偕往、爲我之父與祭司、汝爲一家之祭司、與爲以色列一支派一族之祭司、孰愈、"],[7,18,20,"祭司心悅、取聖衣曁家神雕像、入於民中、"],[7,18,21,"衆遂轉而前往、使幼稚牲畜貨財先行、"],[7,18,22,"離米迦室已遠、米迦之鄰咸集、追及但人呼之、"],[7,18,23,"但人回顧、問米迦曰、爾有何事、率斯羣衆而來、"],[7,18,24,"曰、我所作之神像、及所任之祭司、爾攜之去、一無所遺、而問我有何事耶、"],[7,18,25,"但人曰、勿使爾聲聞於我衆、恐暴戾者擊爾、致爾與爾家人、俱喪厥命、"],[7,18,26,"但人乃行其途、米迦見其強於己、則轉而歸家、"],[7,18,27,"但人攜米迦所製之物、及其祭司、至於拉億、見其安逸無慮之民、擊之以刃、火焚其邑、無人救援、"],[7,18,28,"蓋邑在近伯利合之谷中、離西頓甚遠、不與他人交際、但人復建邑而居之、"],[7,18,29,"此邑昔名拉億、今依其祖以色列子但之名、名之曰但、"],[7,18,30,"立彼雕像、摩西子革順之裔約拿單、曁其子孫、爲但支派之祭司、迨至斯土見虜之日、"],[7,18,31,"米迦雕像之設、所歷時日、與上帝室在示羅同、"],[7,19,1,"當以色列無王時、有利未人旅以法蓮山隅、娶妾於猶大伯利恆、"],[7,19,2,"妾不貞、離夫、歸伯利恆父家、居歷四月、"],[7,19,3,"夫起、攜一僕二驢往見妾、欲以善言慰藉、冀其旋歸、妾導入父室、其父見之、欣喜承迎、"],[7,19,4,"留之三日、飲食而宿、"],[7,19,5,"越至四日、夙興欲行、女之父謂其壻曰、食餅少許、壯爾心力而後行、"],[7,19,6,"二人同坐飲食、女之父曰、是夜請仍宿此、以快爾心、"],[7,19,7,"其人起而欲往、女之父強留之、乃復宿焉、"],[7,19,8,"越至五日、夙興欲往、女之父曰、請復壯爾心力、延至日昃、於是二人同食、"],[7,19,9,"其人與妾及僕、起而欲往、女之父曰、日已昃、天將暮矣、請留一宿、以快爾心、詰旦夙興而歸可也、"],[7,19,10,"其人不欲復宿、乃備二驢、攜妾啟行、至耶布斯卽耶路撒冷相對之所、"],[7,19,11,"近耶布斯時、日將暮矣、僕謂主曰、請偏行、入耶布斯邑而宿、"],[7,19,12,"主曰、外族之邑、不屬以色列人者、我不入之、必往基比亞、"],[7,19,13,"又謂僕曰、可適此處一邑而宿、或基比亞、或拉瑪、"],[7,19,14,"遂前行、近屬便雅憫之基比亞時、日已入、"],[7,19,15,"至基比亞、入邑以宿、無人接其入室寓之、乃坐於衢、"],[7,19,16,"旣暮、有老者自田工作而歸、彼乃以法蓮山地人、旅於基比亞、此地之人、屬便雅憫族、"],[7,19,17,"老者舉目、見旅人在衢、問曰、爾奚自、將何往、"],[7,19,18,"曰、我自猶大伯利恆來、往以法蓮山隅、原居於彼、曾至猶大伯利恆、今詣耶和華室、無人接我入室、"],[7,19,19,"驢有芻糧、我與妾僕有餅及酒、罔有所缺、"],[7,19,20,"老者曰、願爾平安、爾之所需、我之責也、勿宿於衢、"],[7,19,21,"遂導之入室、以芻飼驢、乃濯足飲食、"],[7,19,22,"適快心時、邑之匪徒環宅叩門、謂室主老者曰、入爾室者、攜之出、以遂我欲、"],[7,19,23,"室主出、謂之曰、兄弟乎、勿行此惡、斯人旣入我室、勿妄爲、"],[7,19,24,"我有處女、及彼之妾在此、我俱出之、任爾玷辱、遂爾所欲、惟於斯人勿妄爲、"],[7,19,25,"衆不聽、旅人執其妾出之、衆與淫合、竟夕狎侮、黎明始釋、"],[7,19,26,"昧爽、婦至其主所寓之室、仆於門前、迨乎旣旦、"],[7,19,27,"其主夙興、啟門而出、欲行其途、見妾仆於門前、二手在閾、"],[7,19,28,"謂之曰、起、我儕行矣、不應、遂置之於驢、啟行而歸、"],[7,19,29,"至家、以刀肢解其妾、分爲十二、徧送於以色列四境、"],[7,19,30,"見之者曰、自以色列人出埃及、以迄於今、未有若此之事、未之見也、今當思議、而宣言焉、"],[7,20,1,"於是以色列衆咸出、自但至別是巴、曁基列地之民、有如一人、集於米斯巴、在耶和華前、"],[7,20,2,"民長與以色列諸支派、集爲上帝民會、執兵步卒、共四十萬、"],[7,20,3,"以色列人至米斯巴、爲便雅憫人所聞、以色列人問曰、此惡之由、請以告我、"],[7,20,4,"被殺之婦、其夫利未人對曰、我與妾至便雅憫之基比亞、止宿於彼、"],[7,20,5,"及夜、基比亞人起而攻我、環室、意欲殺我、淫汚我妾致死、"],[7,20,6,"彼行淫亂謬妄之事、在以色列中、故我取妾而臠之、徧送於以色列四境、"],[7,20,7,"請爾以色列衆爲之畫策、而建議焉、"],[7,20,8,"民衆悉起、有如一人、曰、我不返幕歸家、"],[7,20,9,"必掣籤、往攻基比亞、"],[7,20,10,"於以色列諸支派中、百取十、千取百、萬取千、使備餱糧、迨衆至便雅憫之基比亞、則依其在以色列中、所行謬妄之事以待之、"],[7,20,11,"於是以色列衆咸集、連絡爲一、以攻斯邑、"],[7,20,12,"以色列支派遣人謂便雅憫支派曰、爾中所行何惡、"],[7,20,13,"今以基比亞之匪徒付我、俾致之死、以除惡於以色列中、便雅憫人不聽同儕以色列人之言、"],[7,20,14,"乃由諸邑、集於基比亞、欲與以色列人戰、"],[7,20,15,"便雅憫諸邑執兵之士、計二萬六千、其外有基比亞選兵、計七百、"],[7,20,16,"衆中有所簡左手較捷之卒七百、以繩發石、不爽毫髮、"],[7,20,17,"除便雅憫人外、以色列人之執兵者、計四十萬、皆戰士也、"],[7,20,18,"以色列人起、往伯特利、諮諏上帝曰、與便雅憫人戰、我中誰當先往、耶和華曰、猶大先往、"],[7,20,19,"以色列人晨興、對基比亞建營、"],[7,20,20,"出而列陳於基比亞、欲與便雅憫人戰、"],[7,20,21,"便雅憫人自基比亞出、戮以色列人二萬二千、"],[7,20,22,"以色列人共奮厥志、復列陳於前日之陳所、"],[7,20,23,"上至耶和華前、哭泣至暮、諮諏耶和華曰、我可再與昆弟便雅憫人戰否、耶和華曰、可往攻之、"],[7,20,24,"翌日、以色列人進攻便雅憫族、"],[7,20,25,"便雅憫人是日自基比亞出而逆之、又戮以色列執兵之士一萬八千、"],[7,20,26,"以色列民衆、上至伯特利哭泣、坐於耶和華前、禁食至暮、獻燔祭及酬恩祭於耶和華、"],[7,20,27,"時、上帝約匱在彼、亞倫孫、以利亞撒子非尼哈、侍於其前、"],[7,20,28,"以色列人諮諏耶和華曰、我可復出、與我昆弟便雅憫人戰乎、抑止乎、耶和華曰、往哉、明日我必付之爾手、"],[7,20,29,"以色列人設伏於基比亞四周、"],[7,20,30,"越至三日、以色列人往攻便雅憫人、列陳於基比亞如前、"],[7,20,31,"便雅憫人出而迎戰、被誘離邑、如前擊殺以色列人、約有三十、於二通衢、一往伯特利、一往基比亞之郊野、"],[7,20,32,"便雅憫人曰、其敗如故、以色列人曰、我儕其遁、誘之離邑、至於通衢、"],[7,20,33,"衆遂起離其所、列陳於巴力他瑪、伏者自基比亞草場而出、"],[7,20,34,"有以色列選兵一萬、往攻基比亞、戰勢劇烈、然便雅憫人不知禍之將及、"],[7,20,35,"耶和華使便雅憫人敗於以色列人前、是日以色列人殺便雅憫人、二萬五千一百、皆執兵之士、"],[7,20,36,"便雅憫人乃自知敗北、初、以色列人恃有伏兵在基比亞、故暫避便雅憫人、"],[7,20,37,"伏兵驟出、進攻基比亞、刃擊舉邑之人、"],[7,20,38,"以色列人曾約伏兵、以使邑中烟雲上騰爲號、"],[7,20,39,"以色列人戰時稍卻、便雅憫人殺其人約有三十、自謂以色列人爲我所敗、如前戰然、"],[7,20,40,"迨邑中烟雲起、其狀如柱、便雅憫人回顧、見舉邑烟焰冲天、"],[7,20,41,"以色列人旋轉、便雅憫人見禍及之、不勝駭懼、"],[7,20,42,"遂背以色列人、轉向曠野之路而遁、軍士急追於後、民自諸邑而出、戮之於其間、"],[7,20,43,"追襲之、圍困之、在其駐足之所蹂躪之、至於相對日出處之基比亞、"],[7,20,44,"便雅憫人仆者一萬八千、皆勇士也、"],[7,20,45,"其餘轉向曠野而逃、至臨門磐、以色列人又於通衢、收其五千人、追至基頓、又殺二千人、"],[7,20,46,"是日便雅憫執兵之士死者、共二萬五千、皆勇士也、"],[7,20,47,"惟有六百人、轉向曠野而逃、至臨門磐、居之四月、"],[7,20,48,"以色列人反攻便雅憫、刃擊邑衆、與其牲畜、及凡所遇、所至諸邑、以火焚之、"],[7,21,1,"以色列人曾在米斯巴誓曰、我儕皆不以女妻便雅憫人、"],[7,21,2,"民至伯特利、坐於上帝前、迨及薄暮、舉聲痛哭、曰、"],[7,21,3,"以色列之上帝耶和華歟、今日以色列中缺一支派、何爲有此事乎、"],[7,21,4,"翌日、民衆夙興、築壇、獻燔祭及酬恩祭、"],[7,21,5,"以色列人曾重誓曰、凡不上米斯巴、詣耶和華者、必致之死、故相問曰、以色列支派中、孰不與會、詣耶和華、"],[7,21,6,"以色列人爲其昆弟便雅憫人而悔、曰、以色列支派中、今日絕其一矣、"],[7,21,7,"我旣指耶和華而誓、不以我女妻之、則其遺民若何得妻、"],[7,21,8,"又曰、以色列支派中、孰不上米斯巴、詣耶和華乎、察知基列雅比無人入營與會、"],[7,21,9,"蓋核民時、見其居民無一在者、"],[7,21,10,"會衆遣其最勇之士一萬二千、命之曰、往哉、刃擊基列雅比居民、曁厥婦孺、"],[7,21,11,"所有丁男、及已適人之女、悉殲滅之、"],[7,21,12,"於其居民中、遇處子四百、未適人者、攜至迦南地示羅營、"],[7,21,13,"會衆遣使至臨門磐、以和告便雅憫人、"],[7,21,14,"便雅憫人遂歸、則以基列雅比生存之女妻之、尚爲不足、"],[7,21,15,"民爲便雅憫人而悔、蓋耶和華使以色列支派有闕如也、"],[7,21,16,"會之長老曰、便雅憫之婦女旣滅、則其遺民何以妻之、"],[7,21,17,"又曰、便雅憫人之逃脫者、必有其業、免以色列支派泯沒其一、"],[7,21,18,"但我儕不可妻之以女、因以色列人曾誓曰、以女妻便雅憫人者、必受詛也、"],[7,21,19,"遂曰、在利波拿南、伯特利北、往示劍道東之示羅、歲有耶和華節期、"],[7,21,20,"乃命便雅憫人曰、爾往伏於葡萄園、"],[7,21,21,"見示羅女出而舞蹈、則由葡萄園出、各執其女爲妻、而歸便雅憫地、"],[7,21,22,"如其父兄赴愬於我、我則曰、請爾施恩、以之予我、蓋昔戰時、我不留女以爲其妻、今亦非爾所妻、若然、則爲有罪、"],[7,21,23,"便雅憫人如言而行、循其人數、執舞蹈之女爲妻、歸其故業、復建諸邑以居、"],[7,21,24,"於是以色列人歸其支派室家、自彼各復本業、"],[7,21,25,"是時以色列無王、人各任意而行、"],[8,1,1,"當士師主治時、斯土薦饑、有猶大伯利恆人、與妻及二子、往旅於摩押地、"],[8,1,2,"其人名以利米勒、妻名拿俄米、二子名瑪倫、基連、俱爲猶大伯利恆之以法他人、至摩押地居焉、"],[8,1,3,"拿俄米夫以利米勒死、遺其妻及二子、"],[8,1,4,"二子娶摩押女、一名俄珥巴、一名路得、居彼約十年、"],[8,1,5,"瑪倫基連俱亡、遺拿俄米、無夫、亦無子、"],[8,1,6,"在摩押地、聞耶和華垂顧其民、賜之以糧、則起、攜其二媳、欲自摩押地歸、"],[8,1,7,"婦離所居、偕其二媳、循途以返猶大、"],[8,1,8,"拿俄米謂二媳曰、各歸母家、願耶和華恩待爾、如爾之待死者及我然、"],[8,1,9,"願耶和華賜爾各得綏安於夫家、遂吻之、二媳發聲而哭、"],[8,1,10,"曰、否、我必與爾偕歸爾國、"],[8,1,11,"拿俄米曰、吾女歟、其歸哉、曷欲與我偕往、我猶孕子爲爾夫乎、"],[8,1,12,"我女歟、其歸哉、我年已邁、不復有夫、如曰我尚有望、是夜得夫、且能誕子、"],[8,1,13,"爾豈欲待其長、而不嫁他人乎、我女歟、勿若是、我緣爾故、更爲愁苦、蓋耶和華之手擊我、"],[8,1,14,"二媳復發聲而哭、俄珥巴吻其姑而別、惟路得依附之、"],[8,1,15,"拿俄米曰、爾之妯娌、已歸其國其神、汝其從之而歸、"],[8,1,16,"路得曰、勿勸我離爾、不汝從、汝之所往、我必俱往、汝之所寓、我必偕寓、汝民必爲我民、汝上帝必爲我上帝、"],[8,1,17,"汝所死之處、我亦死於彼、葬於彼、除死而外、我若與爾相離、願耶和華罰我維倍、"],[8,1,18,"拿俄米見路得決志偕往、則不復言、"],[8,1,19,"二人乃往伯利恆、旣至、舉邑聳動、婦女咸曰、此乃拿俄米乎、"],[8,1,20,"曰、勿稱我拿俄米、當稱我爲瑪拉、蓋全能者待我苦甚、"],[8,1,21,"我富有而出、耶和華使我匱乏而歸、耶和華旣責我、全能者旣苦我、奚稱我爲拿俄米哉、"],[8,1,22,"拿俄米與其媳摩押女路得、歸自摩押乃若此、彼至伯利恆時、適穫麰麥之際、"],[8,2,1,"拿俄米之夫以利米勒、其家有富豪之戚屬、名波阿斯、"],[8,2,2,"摩押女路得謂拿俄米曰、容我適田、蒙誰之恩、則隨其後、而拾遺穗、曰、我女、往哉、"],[8,2,3,"遂往於田、從穫者後、而拾所遺、偶至以利米勒家波阿斯之田、"],[8,2,4,"波阿斯自伯利恆至、謂穫者曰、願耶和華偕爾、對曰、願耶和華錫嘏於爾、"],[8,2,5,"波阿斯問督穫之僕曰、此爲誰氏女、"],[8,2,6,"督穫之僕曰、乃摩押女、與拿俄米自摩押偕來、"],[8,2,7,"彼曰、請容我從穫者後、在禾束間以拾所遺、彼至、自朝迄今在此、惟有時少待於廬耳、"],[8,2,8,"波阿斯謂路得曰、我女、請聽、勿離此而往他田拾遺、在此偕我使女、"],[8,2,9,"視人穫於何田、卽隨其後、我命少者勿犯爾、渴時、則往器所、飲少者所汲、"],[8,2,10,"婦俯伏於地曰、我乃異邦人、何蒙爾恩、得爾之顧、"],[8,2,11,"波阿斯曰、自爾夫沒後、爾於爾姑所爲、並離父母故土、至素所未識之民中、是事人悉告我、"],[8,2,12,"願耶和華報爾所爲、爾來託庇於以色列上帝耶和華翼下、願其大賚爾、"],[8,2,13,"曰、我主歟、願蒙爾恩、我雖不如爾使女之一、爾乃慰藉爾婢、語以愜心之言、"],[8,2,14,"食時、波阿斯曰、來此食餅、濡所擘者於醯、婦則坐於穫者之側、波阿斯予以烘穀、婦食果腹、猶有所餘、"],[8,2,15,"婦旣起而拾遺、波阿斯命其少者曰、容其在禾束間拾遺、勿責之、"],[8,2,16,"可由禾束、少抽數莖、故遺於地、容其拾之、勿叱之、"],[8,2,17,"路得在田拾穗、至於薄暮、撲其所拾、得麰麥約一伊法、"],[8,2,18,"取之入邑以示姑、亦以果腹所餘者、出而與姑、"],[8,2,19,"姑曰、爾今日拾穗何處、工作何方、願顧爾者得福、婦以所與工作之人告姑曰、今日我所與工作者、名波阿斯、"],[8,2,20,"拿俄米謂媳曰、彼施恩於存者亡者弗輟、願耶和華錫嘏之、又曰、其人爲我近戚、可贖我產者、此其一也、"],[8,2,21,"摩押女路得曰、彼謂我云、附近我少者、迨及刈畢、"],[8,2,22,"拿俄米曰、我女歟、汝與其使女偕出、不令人見爾於他田、善也、"],[8,2,23,"由是路得與波阿斯使女偕、而拾穗焉、迨麰麥小麥盡刈、仍與姑居、"],[8,3,1,"拿俄米謂媳曰、我女歟、我不當爲爾求安處之所、俾爾獲福乎、"],[8,3,2,"昔爾與波阿斯使女偕、波阿斯非我之戚族乎、彼今夜在禾場、簸揚麰麥、"],[8,3,3,"爾其浴身、沐膏衣衣、住於禾場、惟勿令其見之、迨其飲食旣畢、"],[8,3,4,"彼偃臥時、爾察其處、然後入、啟其足而臥、彼必告爾以所當行、"],[8,3,5,"曰、凡爾所言、我必遵行、"],[8,3,6,"遂往禾場、凡姑所命、悉遵行之、"],[8,3,7,"波阿斯飲食已畢、中心歡悅、往臥於麥積之首、婦乃潛至、啟其足而臥焉、"],[8,3,8,"中夜波阿斯驚駭、反側、知有婦附其足而臥、"],[8,3,9,"曰、爾爲誰、曰、爾婢路得、請以裾覆我、蓋爾乃宜贖我產者、"],[8,3,10,"曰、我女歟、願耶和華錫嘏於爾、爾於少者、無論貧富、俱不相從、爾之施恩、其終較隆於始、"],[8,3,11,"我女歟、毋懼、舉邑皆知爾乃淑女、爾所言者、我必爲爾行之、"],[8,3,12,"我誠宜贖爾產、惟尚有一人、較我尤近、"],[8,3,13,"今夜且宿於此、迨至詰朝、如彼欲贖爾產、則善、如其不贖、我指耶和華之生而誓、我必爲爾贖之、臥此以待旦可也、"],[8,3,14,"遂附其足而臥、未能相辨之時卽起、蓋波阿斯曰、勿使人知有婦至場、"],[8,3,15,"又曰、持所衣之外衣、旣持之、則量麰麥六量、置諸其肩、乃入於邑、"],[8,3,16,"至其姑所、姑曰、我女歟、爾所遇若何、婦以波阿斯所待悉告之、"],[8,3,17,"又曰、其人給我麰麥六量、曰、勿徒手詣爾姑、"],[8,3,18,"姑曰、我女歟、其安坐、以覿其事若何而成、蓋今日事苟未成、其人必不中止、"],[8,4,1,"波阿斯至邑門而坐、見其所言宜贖產者過焉、則呼之曰、某歟、請離途、坐於此、遂離途而坐、"],[8,4,2,"乃簡邑之長老十人、謂曰、請坐於此、遂坐、"],[8,4,3,"語宜贖產者曰、自摩押而歸之拿俄米、將鬻我昆弟以利米勒之田、"],[8,4,4,"我意告爾、於坐此者、及我民之長老前、爾其購之、當贖之者乃爾、其次則我、別無他人、如爾欲贖、則贖之、不然、明白告我、其人曰、我欲贖之、"],[8,4,5,"波阿斯曰、爾由拿俄米手贖田之日、亦由死者之婦、摩押女路得而購之、俾承其業、以繼死者之名、"],[8,4,6,"宜贖產者曰、我不能爲己贖之、恐害我業、贖產之權、請爾操之、蓋我不能贖也、"],[8,4,7,"昔在以色列中、凡贖物易物、欲定其事者、必解其履、以予鄰里、此以色列人爲據之例也、"],[8,4,8,"故宜贖產者謂波阿斯曰、汝其購之、則解其履、"],[8,4,9,"波阿斯謂長老與民衆曰、凡屬以利米勒、及基連瑪倫之業、我由拿俄米手購之、今日汝衆爲證、"],[8,4,10,"更購瑪倫妻摩押女路得爲妻、俾承其業、以繼死者之名、免其名絕於昆弟、及故鄉之門、汝衆爲證、"],[8,4,11,"在邑門之衆、與諸長老曰、我儕爲證、願耶和華使適爾家之婦、如拉結利亞、肇造以色列家者、亦願爾稱豪於以法他、得名於伯利恆、"],[8,4,12,"願爾之家、由耶和華賜此少婦之子成立、如他瑪從猶大所生法勒斯之家、"],[8,4,13,"波阿斯遂娶路得、與之同室、耶和華賜之懷姙生子、"],[8,4,14,"衆婦謂拿俄米曰、當頌美那和華、今日使爾不缺親屬、願此子得名於以色列中、"],[8,4,15,"彼必使爾振興、供養爾於老年、彼爲愛爾之媳所生、此媳於爾、較七子尤善、"],[8,4,16,"拿俄米取子、抱之於懷、爲其阿保、"],[8,4,17,"鄰婦曰、拿俄米得子矣、乃名之曰俄備得、俄備得爲耶西父、耶西爲大衞父、○"],[8,4,18,"法勒斯之世胄如左、法勒斯生希斯倫、"],[8,4,19,"希斯倫生蘭、蘭生亞米拿達、"],[8,4,20,"亞米拿達生拿順、拿順生撒門、"],[8,4,21,"撒門生波阿斯、波阿斯生俄備得、"],[8,4,22,"俄備得生耶西、耶西生大衞、"],[9,1,1,"以法蓮山地之拉瑪瑣非、有以法蓮人以利加拿者、乃蘇弗玄孫、託戶曾孫、以利戶孫、耶羅罕子也、"],[9,1,2,"有二妻、一名哈拿、一名毘尼拿、毘尼拿有子、哈拿無子、"],[9,1,3,"以利加拿歲由其邑上示羅、崇拜祭祀萬軍之耶和華、以利二子、何弗尼非尼哈在彼、爲耶和華祭司、"],[9,1,4,"以利加拿獻祭之日、頒胙於妻毘尼拿、及其子女、"],[9,1,5,"因愛哈拿、頒之維倍、然耶和華禁其產育、"],[9,1,6,"其敵毘尼拿激之使憂、以耶和華禁其產育也、"],[9,1,7,"歲往耶和華室時、其夫如是待之、毘尼拿仍激之、致其哭而不食、"],[9,1,8,"其夫以利加拿謂之曰、哈拿、奚爲哭而不食、中心愀然哉、我之於爾、非愈於十子乎、"],[9,1,9,"衆在示羅、飲食旣畢、哈拿興、時、祭司以利坐其座、在耶和華殿之橛旁、"],[9,1,10,"哈拿中懷憂戚、禱於耶和華而痛哭、"],[9,1,11,"許願曰、萬軍之耶和華歟、如爾垂顧婢苦、憶我弗忘、賜婢生男、則必奉之耶和華、至於畢生、薙髮之刀、不加其首、"],[9,1,12,"哈拿在耶和華前、祈禱不輟、以利注目觀其口、"],[9,1,13,"夫哈拿中心默語、脣動而聲不聞、以利以爲醉、"],[9,1,14,"曰、爾醉將至何時、其戒爾酒、"],[9,1,15,"哈拿曰、我主歟、非也、我乃憂心之婦、清酒醇醪不飲、惟於耶和華前傾我衷懷、"],[9,1,16,"勿以婢爲惡女、我言迄今、由於寃抑憤激、"],[9,1,17,"以利曰、爾可安然而歸、願以色列之上帝允爾所祈、"],[9,1,18,"婦曰、願沾爾恩、遂往而食、不復有憂容、"],[9,1,19,"舉家夙興、拜於耶和華前、乃返拉瑪、而歸其家、以利加拿與妻哈拿同室、耶和華垂念之、"],[9,1,20,"哈拿懷姙、屆期生子、命名撒母耳、曰、我由耶和華而求之、"],[9,1,21,"以利加拿與其全家、往獻歲祭於耶和華、而償其願、"],[9,1,22,"惟哈拿不往、謂其夫曰、俟子斷乳、我將攜之覲耶和華、使恆居其所、"],[9,1,23,"以利加拿曰、爾視爲善者則行之、待子斷乳可也、惟願耶和華踐其言、婦遂居家哺子、迨及斷乳、"],[9,1,24,"乳旣斷、婦攜之往、亦牽牡牛三、麪一伊法、酒一革囊、至示羅、詣耶和華室、時子尚幼、"],[9,1,25,"遂宰一牛、攜子詣以利、"],[9,1,26,"曰、我主歟、我指爾生命以誓、昔在此立於爾側、禱於耶和華之婦、卽我也、"],[9,1,27,"我爲此子而禱、耶和華允我所求、"],[9,1,28,"我奉之耶和華、使其歸耶和華、至於畢生、遂在彼崇拜耶和華、"],[9,2,1,"哈拿禱曰、我心因耶和華歡悅、我角因耶和華崢嶸、我口向敵而孔張、因爾拯救而喜樂、"],[9,2,2,"惟耶和華爲聖、無如之者、其外無他、無有磐石、似我上帝、"],[9,2,3,"勿復出言驕矜、勿容口發狂妄、蓋耶和華爲睿智之上帝、人之所行、爲彼所衡、"],[9,2,4,"勇士折其弓、躓者束以力、"],[9,2,5,"素飽足者爲傭得食、飢餓者不復飢、不育者乃產七子、多子者反致衰弱、"],[9,2,6,"耶和華殺人生人、使人歸墓、使人復起、"],[9,2,7,"耶和華使人貧、使人富、使人卑微、使人高顯、"],[9,2,8,"舉貧賤者於塵埃、拔匱乏者於糞壤、使坐牧伯之間、俾嗣尊榮之位、蓋地之柱屬耶和華、立宇宙於其上、"],[9,2,9,"彼之聖民、必護衞其步履、使惡人緘默於幽暗、蓋恃力者、無有得勝也、"],[9,2,10,"與耶和華爭者、必被擊碎、彼必自天以雷擊之、耶和華將行鞫於地極、賜力於其王、高其受膏者之角、"],[9,2,11,"以利加拿往拉瑪、歸其家、小子在祭司以利前、奉事耶和華、○"],[9,2,12,"以利二子、匪類也、不識耶和華、"],[9,2,13,"其爲祭司、與民立規、人獻祭烹肉時、祭司之僕至、手執三股之叉、"],[9,2,14,"入於釜甑鼎鑊、叉所得者、祭司取之、凡以色列族至示羅者、祭司待之若此、"],[9,2,15,"未焚脂、祭司之僕至、謂獻祭者曰、給肉於祭司以炙、彼不取爾烹者、必取生腥、"],[9,2,16,"如人曰、必先焚脂、然後任爾所欲取之、彼則曰、非也、今當予我、不然、我強取之、"],[9,2,17,"二少者之罪、耶和華視爲甚重、蓋輕視耶和華之祭也、○"],[9,2,18,"撒母耳尚幼、衣枲聖衣、侍於耶和華前、"],[9,2,19,"母爲之歲作小袍、偕夫往獻歲祭時、攜而予之、"],[9,2,20,"以利爲以利加拿及其妻祝嘏曰、願耶和華由此婦賜爾後裔、以代從耶和華所求者、夫婦遂歸、"],[9,2,21,"耶和華眷顧哈拿、彼則懷姙、生三子二女、小子撒母耳生長於耶和華前、○"],[9,2,22,"以利年邁、聞其子待以色列衆之事、並聞其與會幕門供役之婦同寢、"],[9,2,23,"謂之曰、我由民衆聞爾惡行、胡爲作此、"],[9,2,24,"我子、勿爾、我所風聞、非善言也、爾使耶和華之民干罪、"],[9,2,25,"人若相犯、上帝鞫之、若犯耶和華、誰爲之祈、惟二子不聽父言、蓋耶和華決意殺之、"],[9,2,26,"小子撒母耳漸長、益得耶和華與人之愛、○"],[9,2,27,"有上帝僕至以利曰、耶和華云、爾祖之家、在埃及法老室、我非向之顯見乎、"],[9,2,28,"以色列支派中、我非簡彼爲我祭司、使焚香於我壇、衣聖衣於我前乎、以色列族所獻之火祭、我非賜爾祖之家乎、"],[9,2,29,"我所命獻於我室之祭品禮物、爾何踐踏之、重爾子過於我、取我民以色列所獻之嘉者、以肥己乎、"],[9,2,30,"故以色列之上帝耶和華曰、昔我有言、爾與爾祖之家、將恆久行於我前、今我則曰、決不如是、凡尊我者、我必重之、凡藐我者、我必輕之、"],[9,2,31,"其日將至、必斷爾臂、及爾祖家之臂、使爾家中無一耆老、"],[9,2,32,"以色列富有之際、爾必目擊敵在我室、爾家永無耆老、"],[9,2,33,"爾家之人、我不滅於我壇者、必使爾目壞心憂、爾家所育、皆必壯年夭逝、"],[9,2,34,"爾之二子、何弗尼非尼哈所遇之事、可以爲徵、彼必同日而亡、"],[9,2,35,"我將挺生忠藎之祭司、彼將循我心意而行、我必鞏固其家、彼必恆久行於我受膏者前、"],[9,2,36,"爾家所遺、必來拜之、求一金一餅、曰、請立我任祭司之職、俾得少許之餅以食、"],[9,3,1,"小子撒母耳、在以利前、奉事耶和華、是時耶和華之言罕聞、異象不恆顯見、"],[9,3,2,"以利目眊不明、臥於己所、"],[9,3,3,"上帝之燈未滅、撒母耳臥於耶和華殿、上帝法匱之所、"],[9,3,4,"耶和華呼撒母耳、對曰、我在此、"],[9,3,5,"遂趨詣以利曰、汝呼我、我在此、曰、我未呼爾、復臥可也、遂反而臥、"],[9,3,6,"耶和華又呼曰、撒母耳、撒母耳起、就以利曰、汝呼我、我在此、曰、我子、我未呼爾、復臥可也、"],[9,3,7,"時、撒母耳未識耶和華、耶和華未嘗以言示之、"],[9,3,8,"耶和華三呼撒母耳、遂起、就以利曰、汝呼我、我在此、以利始知耶和華呼之、"],[9,3,9,"故謂撒母耳曰、汝反而臥、如再呼爾、則曰、耶和華歟、請言、爾僕謹聽、撒母耳遂往、臥於己所、"],[9,3,10,"耶和華蒞止、如前呼曰、撒母耳、撒母耳、對曰、請言、爾僕謹聽、"],[9,3,11,"耶和華曰、我於以色列中、將行一事、使凡聽之者、兩耳必震、"],[9,3,12,"我指以利家所言者、自始及終、屆期必應於彼、"],[9,3,13,"我曾告之、必鞫其家、蓋彼知子行惡、自招呪詛、而不之禁、"],[9,3,14,"故我對以利家誓曰、祭品禮物、永不能贖其罪、"],[9,3,15,"撒母耳臥及旦、啟耶和華室門、不敢以異象告以利、"],[9,3,16,"以利呼之曰、我子撒母耳、曰、我在此、"],[9,3,17,"曰、耶和華告爾何事、請毋隱於我、與爾所言之事、若有所隱、願上帝罰爾維倍、"],[9,3,18,"撒母耳悉以告之、無所隱、以利曰、是耶和華也、願其行所視爲善者、"],[9,3,19,"撒母耳漸長、耶和華偕之、使其所言、無有不應、"],[9,3,20,"以色列衆、自但至別是巴、皆知撒母耳見立、爲耶和華之先知、"],[9,3,21,"耶和華復見於示羅、以言示撒母耳、撒母耳宣於以色列衆、"],[9,4,1,"以色列族出、與非利士人戰、建營於以便以謝之側、非利士人建營於亞弗、"],[9,4,2,"非利士人列陳、攻以色列族、戰時、以色列族敗於其前、見殺於陳者、約四千人、"],[9,4,3,"民歸營時、以色列長老曰、耶和華今日何擊我於非利士人前、當舁耶和華約匱、自示羅至此、援我於敵手、"],[9,4,4,"於是民遣人詣示羅、舁居基路伯間、萬軍之耶和華約匱而至、以利二子、何弗尼非尼哈、與約匱偕、"],[9,4,5,"耶和華約匱旣入營、以色列衆大聲號呼、地爲響應、"],[9,4,6,"非利士人聞號呼之聲、則曰、希伯來營大聲號呼、曷故、嗣知耶和華匱入營、"],[9,4,7,"乃懼曰、上帝至其營矣、又曰、禍哉我也、前此未嘗有是、"],[9,4,8,"禍哉我也、孰克拯我、脫斯大能之神之手、昔在曠野、以諸災擊埃及人者、卽斯神也、"],[9,4,9,"非利士人歟、當壯乃志、爲大丈夫、免爲奴於希伯來族、如彼爲奴於爾、當爲大丈夫而戰、"],[9,4,10,"遂戰、以色列族敗北、各遁歸幕、殺戮甚鉅、步卒隕者三萬、"],[9,4,11,"上帝之匱見奪、以利二子、何弗尼非尼哈被殺、"],[9,4,12,"是日有一便雅憫人、自裂其衣、以塵蒙首、由陳奔於示羅、"],[9,4,13,"至時、以利在路旁、坐於座以待、爲上帝匱中心戰慄、其人入城以告、邑衆號呼、"],[9,4,14,"以利聞號呼之聲、則曰、如此喧譁、何意、其人趨至、而告以利、"],[9,4,15,"以利年九十有八、目眊不明、"],[9,4,16,"其人曰、我乃自陳而來、今日自陳而逃、曰、吾子、其事若何、"],[9,4,17,"曰、以色列族遁於非利士人前、殺戮甚鉅、爾之二子、何弗尼非尼哈皆死、上帝之匱見奪、"],[9,4,18,"以利年老體重、聞言及上帝匱、則自座仰跌、隕於門側、折頸而死、以利爲以色列士師、歷四十年、"],[9,4,19,"其媳非尼哈妻臨產、聞上帝匱見奪、舅與夫並死、劬勞卽至、卷曲以產、"],[9,4,20,"臨死之際、旁侍之婦曰、勿懼、爾生男矣、婦不答、不以爲意、"],[9,4,21,"遂名子以迦博、曰、以色列之榮已去、乃因上帝之匱見奪、舅與夫已死也、"],[9,4,22,"又曰、上帝之匱見奪、以色列之榮去矣、"],[9,5,1,"非利士人奪上帝之匱、自以便以謝舁至亞實突、"],[9,5,2,"置於大袞廟、在大袞側、"],[9,5,3,"翌晨、亞實突人夙興、見大袞仆、伏於地、在耶和華匱前、遂取而置之於其所、"],[9,5,4,"次日夙興、見大袞仆、伏於地、在耶和華匱前、其首與手、並斷於閾、惟遺殘體而已、"],[9,5,5,"故在亞實突、大袞祭司、及入大袞廟者、不履其閾、至於今日、○"],[9,5,6,"耶和華之手、加重禍於亞實突人、擊之以痔、而翦滅之、至於四境、"],[9,5,7,"亞實突人見此、則曰、以色列上帝之匱、不可留此、蓋其手加烈禍於我、及我神大袞、"],[9,5,8,"遂遣人集非利士牧伯曰、以色列上帝之匱、何以處之、僉曰、當運至迦特、乃運於彼、"],[9,5,9,"運至之後、耶和華之手擊其邑、使大擾亂、其人無論尊卑、悉被擊、咸生痔、"],[9,5,10,"乃運上帝匱至以革倫、旣至、以革倫人呼曰、彼舁以色列上帝之匱至此、欲殺我、及我民、"],[9,5,11,"上帝之手、加以重禍、舉邑擾亂、多有死者、遂遣人集非利士牧伯曰、其遣以色列上帝之匱、歸於故土、免殺我、及我民、"],[9,5,12,"未死之人俱生痔、舉邑哀號、聲聞於天、"],[9,6,1,"耶和華匱在非利士人之地、凡歷七月、"],[9,6,2,"非利士人招其祭司卜師曰、耶和華匱、何以處之、當用何物遣歸故土、請以示我、"],[9,6,3,"曰、如欲遣以色列上帝之匱、勿使徒去、必獻補過之祭、乃可得醫、且知其手不離於爾之故、"],[9,6,4,"曰、補過之祭、當獻何物、曰、金製之痔五、金製之鼠五、循非利士牧伯之數、蓋爾曹及牧伯、俱罹一災、"],[9,6,5,"當作痔形、及害爾田之鼠形、且尊榮以色列之上帝、庶彼輕加其手於爾、及爾神、與爾地、"],[9,6,6,"何剛愎乃心、如埃及人與法老之剛愎乎、上帝行奇事於其間、彼豈非釋其民、使之往乎、"],[9,6,7,"今當備新車一、未嘗負軛、方字之牝牛二、繫牛於車、牽犢離之而歸、"],[9,6,8,"以耶和華匱、載之於車、以汝所獻金器、爲補過之祭者、藏於櫝中、置之匱旁、遣之而去、"],[9,6,9,"觀其匱若由其境之道而行、至伯示麥、則知加重禍於我者、乃耶和華、不然、則知擊我者非其手、乃我偶遇之、"],[9,6,10,"其人如言而行、取方字之牝牛二、繫之於車、禁其犢於家、"],[9,6,11,"以耶和華匱、及藏金鼠金痔之形之櫝、咸載於車、"],[9,6,12,"牛徑往伯示麥道、行於通衢、且行且鳴、不偏於左、不偏於右、非利士牧伯隨之、至伯示麥界、"],[9,6,13,"伯示麥人在谷刈麥、舉目見匱、則悅、"],[9,6,14,"車至伯示麥人約書亞田而止、田有巨石、遂劈車爲柴、獻其牛於耶和華爲燔祭、"],[9,6,15,"利未人取耶和華匱、與藏金器之櫝而下、置於巨石、是日伯示麥人、獻燔祭及他祭於耶和華、"],[9,6,16,"非利士五牧伯見此、卽日反以革倫、"],[9,6,17,"非利士人所獻金痔於耶和華、爲補過之祭者、其數如左、亞實突一、迦薩一、亞實基倫一、迦特一、以革倫一、"],[9,6,18,"亦獻金鼠、循非利士五牧伯所屬之邑、與其鄉里、爰及巨石、卽置耶和華匱之石、此石在伯示麥人約書亞田間、至今猶存、"],[9,6,19,"伯示麥人窺耶和華匱、耶和華擊之、死者七十、其人計有五萬、民因耶和華大行殺戮而悲、"],[9,6,20,"伯示麥人曰、此維聖之上帝耶和華、孰能立於其前、彼離我、當何往、"],[9,6,21,"遂遣人告基列耶琳居民曰、非利士人返耶和華匱、爾曹其下舁至爾所、"],[9,7,1,"基列耶琳人至舁耶和華匱、詣山中亞比拿達室、區別其子以利亞撒守之、○"],[9,7,2,"匱在基列耶琳、歷日已久、凡二十年、以色列家思慕耶和華、"],[9,7,3,"撒母耳告以色列家曰、如爾一心歸耶和華、則必除異族之神、及亞斯他錄於爾中、專心歸耶和華、而獨事之、則彼援爾於非利士人手、"],[9,7,4,"以色列人遂去諸巴力、及亞斯他錄、獨事耶和華、○"],[9,7,5,"撒母耳曰、當集以色列衆於米斯巴、我將爲爾祈禱耶和華、"],[9,7,6,"遂集於米斯巴、汲水傾於耶和華前、是日禁食、曰、我獲罪於耶和華、撒母耳在米斯巴、爲以色列族聽訟、"],[9,7,7,"非利士人聞以色列衆集於米斯巴、其牧伯遂上、欲攻之、以色列族聞之、則懼、"],[9,7,8,"謂撒母耳曰、爲我籲我上帝耶和華勿輟、俾援我於非利士人手、"],[9,7,9,"撒母耳取哺乳之羔一、獻於耶和華、爲全牲燔祭、爲以色列族籲耶和華、耶和華允焉、"],[9,7,10,"撒母耳獻燔祭時、非利士人進與以色列人戰、是日耶和華發大雷、潰亂非利士人、遂敗於以色列人前、"],[9,7,11,"以色列人出米斯巴追擊之、至伯甲之下、"],[9,7,12,"撒母耳取一石、立於米斯巴與善間、名之曰以便以謝、曰、延及此時、耶和華助我儕、"],[9,7,13,"於是非利士人屈服、不再侵以色列境、撒母耳存日、耶和華之手、制非利士人、"],[9,7,14,"非利士人所取以色列之邑、自以革倫至迦特、悉反之、邑之四境、以色列人亦援之於非利士人手、是時以色列人與亞摩利人和好、"],[9,7,15,"撒母耳畢生爲以色列士師、"],[9,7,16,"歲巡伯特利、吉甲、米斯巴、在此聽其訟、"],[9,7,17,"後歸拉瑪、其家在焉、爲以色列族聽訟、爲耶和華築壇、"],[9,8,1,"撒母耳年邁、立其子爲以色列士師、"],[9,8,2,"長名約珥、次名亞比亞、俱在別是巴爲士師、"],[9,8,3,"其子不行父道、偏私牟利、受賄反正、○"],[9,8,4,"以色列長老咸集、詣拉瑪見撒母耳、"],[9,8,5,"曰、爾年已邁、爾子不行爾道、今當爲我立王、聽我之訟、與列國同、"],[9,8,6,"彼言立王聽訟、撒母耳不悅其事、禱於耶和華、"],[9,8,7,"耶和華諭之曰、凡民所言、爾可從之、彼非棄爾、乃棄我也、不欲我爲其王、"],[9,8,8,"自我導之出埃及、迄於今日、彼之所行、離我而事他神、今待爾亦若是、"],[9,8,9,"可從其言、惟當加以警戒、示以治之之王、其制度若何、"],[9,8,10,"撒母耳以耶和華之言、悉告於求立王之民、"],[9,8,11,"曰、治爾之王、其制度若此、必取爾子、使御車、爲騎兵、趨於車前、"],[9,8,12,"或立爲千夫長、五十夫長、或使耕其田、穫其穡、作其戰具、造其車器、"],[9,8,13,"亦取爾女、使爲製香品者、爲廚婢、爲膳女、"],[9,8,14,"又取爾至嘉之田畝、葡萄園、橄欖園、以賜其臣僕、"],[9,8,15,"爾種所生、及葡萄園所產、十取其一、以供其宦豎、與其臣僕、"],[9,8,16,"且取爾僕婢、及少年之壯者、與爾之驢、以供其役、"],[9,8,17,"爾之羊羣、十取其一、爾必爲之僕隸、"],[9,8,18,"是時爾必因所簡之王而呼籲、惟耶和華不俞允焉、"],[9,8,19,"民不聽撒母耳言、曰、不然、我欲得王治我、"],[9,8,20,"使我同於列國、聽我之訟、導我而出、爲我而戰、"],[9,8,21,"撒母耳聞民言、述於耶和華、"],[9,8,22,"耶和華諭之曰、可從其言、爲之立王、撒母耳遂告以色列人曰、其各歸邑、"],[9,9,1,"便雅憫人、有名基士者、乃亞斐亞玄孫、比歌拉曾孫、洗羅孫、亞別子也、甚爲豪富、"],[9,9,2,"有子壯健俊秀、名曰掃羅、在以色列人中、俊秀爲最、軀幹修偉、自肩而上、高於凡民、"],[9,9,3,"其父基士失驢、謂子掃羅曰、汝攜一僕、往尋厥驢、"],[9,9,4,"乃經以法蓮山地、與沙利沙地、不得、又經沙琳地、亦不在彼、又經便雅憫地、亦未之見、"],[9,9,5,"至蘇弗地、掃羅謂所偕之僕曰、不如旋歸、恐父不驢之顧、而我是慮、"],[9,9,6,"曰、此邑有上帝僕、爲衆所尊、所言必應、莫若就之、庶幾示我以當行之路、"],[9,9,7,"掃羅謂僕曰、如往、將以何物饋之、器中之糧已罄、無禮物以饋上帝僕、尚有何物乎、"],[9,9,8,"僕曰、我手有金一舍客勒四分之一、以饋上帝僕、求其示我以當行之路、"],[9,9,9,"昔以色列中、有人諮諏上帝、則曰、其來詣先見、蓋今稱先知、昔稱先見也、"],[9,9,10,"掃羅曰、爾言善也、我儕往哉、遂詣上帝僕所在之邑、"],[9,9,11,"登入邑之阪、遇數少女出汲、問曰、先見在此乎、"],[9,9,12,"曰、然、卽在爾前、當速往、彼今日至邑、因民在崇邱獻祭、"],[9,9,13,"今彼未陟崇邱赴讌、爾入邑、必遇之、蓋彼未臨、則民不食、以其先祝嘏祭品、而後被請者食焉、爾其上、是時必遇之、"],[9,9,14,"二人遂上、入邑時、見撒母耳迎之而來、將陟崇邱、○"],[9,9,15,"掃羅未至前一日、耶和華示撒母耳曰、"],[9,9,16,"明日斯時、我遣便雅憫地之人就爾、爾必膏之、立爲我民以色列之長、拯我民於非利士人手、蓋我民之呼籲達於我前、我垂顧之、"],[9,9,17,"撒母耳見掃羅、耶和華諭之曰、我所言者、卽斯人也、彼必統轄我民、"],[9,9,18,"掃羅就撒母耳於邑門、曰、請以先見之室告我、"],[9,9,19,"撒母耳曰、我卽先見、爾其先我陟崇邱、今日與我共食、詰朝則任爾去、且以爾心所懷告爾、"],[9,9,20,"三日前所失之驢、爾毋庸慮、已獲之矣、以色列所仰慕者誰乎、非爾及爾父全家乎、"],[9,9,21,"掃羅曰、我非便雅憫人、屬以色列支派之至小者乎、便雅憫支派諸家之中、我家非至微者乎、曷與我言若是、"],[9,9,22,"撒母耳攜掃羅與其僕入客堂、於被請者中、使坐首位、客約三十、"],[9,9,23,"撒母耳謂庖人曰、我所付爾、命爾別置之一臠、今其進之、"],[9,9,24,"庖人取腿、與其上所有、置掃羅前、撒母耳曰、此所存者、置於爾前食之、昔我宴賓、特爲爾存之、以待斯時、是門掃羅與撒母耳共食、"],[9,9,25,"旣下崇邱入邑、相敍於屋上、"],[9,9,26,"翌日夙興、黎明時、撒母耳呼掃羅於屋上曰、起、我遣爾往、掃羅遂起、與撒母耳偕出、"],[9,9,27,"至於邑隅、撒母耳謂掃羅、命僕先行、僕旣行、則又曰、爾暫立、我將使爾聞上帝之言焉、"],[9,10,1,"撒母耳取膏之甁、傾於掃羅首、與之接吻、曰、此非耶和華膏爾爲其業之長乎、"],[9,10,2,"爾今日離我、至便雅憫界之泄撒、近拉結墓、必遇二人、將告爾曰、所尋之驢已得、爾父不顧驢、而慮爾、曰、我爲我子將若何、"],[9,10,3,"由此而往、至他泊之橡、必遇三人上伯特利、而覲上帝、一攜三羔、一攜三餅、一攜革囊盛酒、"],[9,10,4,"彼將問爾安、給爾二餅、爾可受焉、"],[9,10,5,"後詣上帝之山、在彼有非利士人之汛、爾旣抵邑、必遇先知一班、自崇邱而下、俱感靈而言、有琴鼗簫瑟在其前、"],[9,10,6,"耶和華之神必大臨爾、爾則化爲新人、同彼感靈而言、"],[9,10,7,"爾見此徵、則相機而行、蓋上帝偕爾、"],[9,10,8,"必先我下吉甲、我亦下就爾、獻燔祭及酬恩祭、爾必待及七日、我至、以所當行示爾、"],[9,10,9,"掃羅轉離撒母耳、上帝錫以新心、是日諸徵咸應、"],[9,10,10,"掃羅與僕至基比亞、有先知一班迎之、上帝之靈大臨掃羅、遂在先知中、感神而言、"],[9,10,11,"素識掃羅者、見其同先知感靈而言、則相語曰、基士之子何所遇耶、掃羅亦在先知中乎、"],[9,10,12,"斯處一人曰、孰爲若輩之父、故成諺曰、掃羅亦在先知中乎、"],[9,10,13,"掃羅感靈而言已畢、則至崇邱、"],[9,10,14,"其叔問掃羅及僕曰、爾曹何往、曰、尋驢不遇、遂詣撒母耳、"],[9,10,15,"叔曰、撒母耳語爾之言、請以告我、"],[9,10,16,"掃羅曰、彼明告我、驢已得矣、惟撒母耳所言國事、不以告之、○"],[9,10,17,"撒母耳集民於米斯巴、詣耶和華、"],[9,10,18,"告以色列人曰、以色列之上帝耶和華云、昔我導爾出埃及、援爾於埃及人手、及虐爾之諸國、"],[9,10,19,"爾之上帝、救爾出諸災禍艱苦者、爾今日棄之、謂曰、立王治我、今當循爾支派億兆、進於耶和華前、"],[9,10,20,"撒母耳使以色列諸支派進前、而得便雅憫支派、"],[9,10,21,"使便雅憫支派、循其室家進前、而得瑪特利家、後得基士子掃羅、索之不獲、"],[9,10,22,"問於耶和華曰、其人至此乎、耶和華曰、彼匿於什物之間、"],[9,10,23,"乃趨而攜之出、立於民中、軀幹修偉、自肩而上、高於凡民、"],[9,10,24,"撒母耳謂民衆曰、耶和華所簡者、爾其觀之、衆民之中、無其匹也、民衆呼曰、願王萬歲、○"],[9,10,25,"撒母耳以國之制度示民、錄之於書、置於耶和華前、遣民各歸其家、"],[9,10,26,"掃羅亦往基比亞、歸其第、爲上帝所感者、成羣從之、"],[9,10,27,"有匪徒曰、斯人焉能拯我、遂藐視之、不饋禮物、掃羅置若罔聞、"],[9,11,1,"亞捫人拿轄上、建營以攻基列雅比、雅比人謂拿轄曰、與我立約、我則事爾、"],[9,11,2,"拿轄曰、與爾立約、必有所憑、卽抉爾衆右目、以辱以色列衆、"],[9,11,3,"雅比長老曰、予我七日之限、俾我遣使至以色列四境、如無援者、我則出降、"],[9,11,4,"使者至掃羅所居之基比亞、以此告民、民咸舉聲號哭、"],[9,11,5,"掃羅自田驅牛而歸、問曰、民遭何事而哭、衆以雅比人之言告之、"],[9,11,6,"掃羅聞之、大感於上帝之神、怒甚、"],[9,11,7,"取牛一雙臠之、遣使徧送於以色列四境、曰、不出而從掃羅撒母耳者、待其牛亦若是、耶和華使民恐懼、乃咸出、如一人焉、"],[9,11,8,"掃羅在比色核其數、以色列人三十萬、猶大人三萬、"],[9,11,9,"遂語使者曰、告基列雅比人云、明日亭午、爾必得援、使者反告、雅比人悅、"],[9,11,10,"謂拿轄曰、明日我將出降、可從所欲以待我、"],[9,11,11,"翌日、掃羅分民爲三隊、晨更時、入亞捫營擊之、迨及亭午、存者四散、無二人在一處者、"],[9,11,12,"民謂撒母耳曰、言掃羅焉能治我者誰乎、當攜之至、我致之死、"],[9,11,13,"掃羅曰、今日耶和華於以色列中施行拯救、一人亦不可殺、○"],[9,11,14,"撒母耳謂民曰、我儕其往吉甲、在彼復建其國、"],[9,11,15,"衆民遂往吉甲、於耶和華前、立掃羅爲王、獻酬恩祭於耶和華、掃羅與以色列衆、欣喜不勝、"],[9,12,1,"撒母耳謂以色列衆曰、爾所求於我者、我悉允之、立王治爾、"],[9,12,2,"今有王出入於爾前、我已年邁皓首、我子與爾相處、我自幼出入於爾前、至於今日、"],[9,12,3,"我在此、爾於耶和華及其受膏者前、可爲我證、我曾強取何人之牛、刦奪何人之驢、欺侮何人、苛虐何人、受賕於何人之手、以蔽我目、若有、我必償之、"],[9,12,4,"僉曰、爾未嘗欺我虐我、亦未嘗受何物於人手、"],[9,12,5,"曰、今日耶和華爲證、其受膏者亦爲證、汝於我手、索之無獲、僉曰、彼爲證、"],[9,12,6,"撒母耳語民曰、昔立摩西亞倫導爾列祖出埃及者、卽耶和華也、"],[9,12,7,"爾當屹立、我於耶和華前、將以耶和華爲爾及爾列祖、所行之義事、與爾辨之、"],[9,12,8,"雅各旣至埃及、爾祖籲耶和華、耶和華遣摩西亞倫導之出、使居斯土、"],[9,12,9,"惟彼忘其上帝耶和華、耶和華付之於夏瑣軍長西西拉、及非利士人、與摩押王之手、遂與之戰、"],[9,12,10,"爾祖籲耶和華曰、我干罪戾、因離棄耶和華、事諸巴力、與亞斯他錄、今求拯我於敵手、我必事爾、"],[9,12,11,"耶和華遣耶路巴力、比但、耶弗他、及撒母耳、援爾於四周敵人之手、爾則安居、"],[9,12,12,"爾見亞捫王拿轄來攻爾、則謂我曰、必有一王治我、是時爾上帝耶和華爲爾之王、"],[9,12,13,"今觀爾曹所求所簡之王、耶和華立王治爾、"],[9,12,14,"如爾寅畏耶和華、而服事之、聽從其言、不違其命、且與治爾之王、順從爾上帝耶和華、則善矣、"],[9,12,15,"如弗聽從耶和華之言、背逆其命、則耶和華之手必敵爾、如昔敵爾祖然、"],[9,12,16,"今當屹立、觀耶和華於爾目前、所行之大事、"],[9,12,17,"今非刈麥之時乎、我籲耶和華、彼將發雷降雨、令爾明知爾求立王、乃爲大惡於耶和華前、"],[9,12,18,"撒母耳遂籲耶和華、是日耶和華發雷降雨、衆民甚畏耶和華、與撒母耳、"],[9,12,19,"告撒母耳曰、爾爲僕祈爾上帝耶和華、免我死亡、我之求王、乃加罪於罪也、"],[9,12,20,"撒母耳曰、毋畏、汝誠行此諸惡、然勿轉離不從耶和華、惟盡心服事之、"],[9,12,21,"其勿偏離、從事虛僞、不能益爾、不能救爾之物、以其虛僞故也、"],[9,12,22,"耶和華旣喜立爾爲己民、必因其大名、不汝離棄、"],[9,12,23,"若我、決不止息爲爾祈禱、而獲罪於耶和華、必以善道正途訓爾、"],[9,12,24,"惟當寅畏耶和華、專誠盡心服事之、念其爲爾所行之大事、"],[9,12,25,"如爾仍行惡、則爾與爾之王、俱必滅亡、"],[9,13,1,"掃羅卽位、"],[9,13,2,"爲以色列王、越至二年、由以色列中、簡三千人、二千從掃羅、在密抹及伯特利山、一千從約拿單、在便雅憫之基比亞、餘民遣歸其家、"],[9,13,3,"約拿單擊非利士人汛於迦巴、非利士人聞之、掃羅吹角遍於國中、曰、希伯來人聽之、"],[9,13,4,"以色列衆聞掃羅擊非利士人汛、以色列人爲非利士人所惡、民從掃羅、集於吉甲、"],[9,13,5,"非利士人集、欲與以色列族戰、率車三萬、騎兵六千、民衆如海沙之多、至伯亞文東之密抹建營、"],[9,13,6,"以色列民見事危急、窘迫特甚、則匿於山洞、叢林巖穴、營窟坎阱、"],[9,13,7,"亦有希伯來人濟約但、至迦得與基列地、掃羅仍在吉甲、民戰慄而從之、"],[9,13,8,"掃羅依撒母耳所定之期、待之七日、而撒母耳未至吉甲、民漸離散、"],[9,13,9,"掃羅曰、攜燔祭及酬恩祭至此、遂獻燔祭、"],[9,13,10,"獻燔祭畢、撒母耳至、掃羅出迓問安、"],[9,13,11,"撒母耳曰、汝所行何事、掃羅曰、定期旣屆、爾未式臨、我見斯民離散、而非利士人集於密抹、"],[9,13,12,"則曰、非利士人必至吉甲攻我、而我未求耶和華恩施、故我強獻燔祭、"],[9,13,13,"撒母耳曰、爾所爲者愚也、不遵爾上帝耶和華所命、如其遵之、則耶和華必在以色列中、堅爾國祚、歷久弗替、"],[9,13,14,"今爾不守厥命、爾之國祚不永、耶和華已尋獲一人、遂乎其心、立爲其民之長、"],[9,13,15,"撒母耳遂起、自吉甲往便雅憫之基比亞、掃羅核其從者、計六百人、"],[9,13,16,"掃羅及其子約拿單、與其從者、俱居於便雅憫之迦巴、非利士人建營於密抹、"],[9,13,17,"有掠者自非利士營出、分爲三隊、一由俄弗拉道、至書亞地、"],[9,13,18,"一由伯和崙道、一由洗波音谷相對之境、往於曠野、○"],[9,13,19,"時、以色列全地無有鐵工、蓋非利士人曰、恐希伯來人製作劍戟也、"],[9,13,20,"以色列人欲利其耒耜斧钁、則詣非利士人所、"],[9,13,21,"惟有銼、以削其钁耜鍤斧、並利其錣、"],[9,13,22,"故臨戰時、從掃羅與約拿單之民、手無劍戟、惟掃羅與約拿單有之、"],[9,13,23,"非利士戍卒、出至密抹隘口、"],[9,14,1,"一日掃羅子約拿單、謂執兵之少者曰、我儕過彼、至非利士汛、惟不告其父、"],[9,14,2,"時、掃羅居基比亞之隅、米磯崙石榴樹下、從者約六百人、"],[9,14,3,"又有衣聖衣之亞希亞、乃居示羅爲耶和華祭司之以利曾孫、非尼哈孫、亞希突子、亞希突卽以迦博之兄、民不知約拿單已往、"],[9,14,4,"約拿單往非利士汛、道經隘口、巉巖對峙、一名播薛、一名西尼、"],[9,14,5,"一在北、與密抹相對、一在南、與迦巴相對、"],[9,14,6,"約拿單謂執兵之少者曰、我儕往未受割者之汛、庶耶和華祐我、蓋耶和華施行拯救、不在人之衆寡也、"],[9,14,7,"執兵者曰、隨爾心欲行之、往哉、我與爾有同志焉、"],[9,14,8,"約拿單曰、我儕過彼、使彼見之、"],[9,14,9,"如彼曰、俟我至爾、我則佇立、不往就之、"],[9,14,10,"如彼曰、爾其上而就我、此爲我徵、我則前往、蓋耶和華付之於我手、"],[9,14,11,"二人使非利士戍卒見之、非利士人曰、希伯來人出所匿之穴矣、"],[9,14,12,"戍卒謂約拿軍及執兵者曰、汝其至此、我有一事示爾、約拿單告執兵者曰、隨我而上、耶和華付之於以色列人手矣、"],[9,14,13,"約拿單攀援而登、執兵者隨之、敵仆於約拿單前、執兵者從而戮之、"],[9,14,14,"二人在半畝之地、始殺之人、約二十、"],[9,14,15,"於是在營在田、庶民戍卒掠者、無不戰慄、地亦震動、致其戰慄特甚、"],[9,14,16,"在便雅憫之基比亞、掃羅之戍卒、見敵軍漸銷亂竄、"],[9,14,17,"掃羅謂從者曰、核民、視離我者爲誰、旣核之、則知約拿單與其執兵者不在、"],[9,14,18,"斯時上帝之匱在以色列族中、掃羅謂亞希亞曰、舁上帝之匱至、"],[9,14,19,"掃羅與祭司相語時、非利士營中喧譁益甚、掃羅告祭司曰、姑止爾手、"],[9,14,20,"乃集從者往戰、見非利士人以刃自相攻擊、致大潰亂、"],[9,14,21,"昔自四方而來、入非利士營之希伯來人、斯時轉從掃羅約拿單所率之以色列人、"],[9,14,22,"匿於以法蓮山地之以色列人、聞非利士人遁、亦臨陳亟襲其後、"],[9,14,23,"是日耶和華拯救以色列族、戰事至伯亞文、○"],[9,14,24,"當日以色列人困憊、蓋掃羅以誓戒民曰、未至日夕、報我仇於我敵之先、凡食物者、必見詛、於是民不食、"],[9,14,25,"民入林、有蜜在地、"],[9,14,26,"民於林見蜜滴瀝、無以手取食者、畏誓言也、"],[9,14,27,"掃羅以誓戒民、約拿單未之聞、故以所執之杖端濡蜜、反手入口、其目卽明、"],[9,14,28,"民中一人曰、爾父以誓戒民云、今日凡食物者、必見詛、民俱疲憊、"],[9,14,29,"約拿單曰、我父累及斯土、爾試觀之、我嘗蜜少許、而目卽明、"],[9,14,30,"今日民若任意而食由敵所獲、則殺非利士人、豈非尤多乎、"],[9,14,31,"是日民擊非利士人、自密抹至亞雅崙、疲憊殊甚、"],[9,14,32,"乃急取所得牛羊與犢、宰之於地、倂血而食之、"],[9,14,33,"或告掃羅曰、民食有血之肉、獲罪於耶和華、掃羅曰、爾曹行詐、當轉巨石至此、"],[9,14,34,"又曰、散行民中告曰、各牽其牛其羊至此、宰而食之、勿食有血之肉、獲罪於耶和華、是夜民各牽牛、宰之於彼、"],[9,14,35,"掃羅爲耶和華築壇、是乃掃羅爲耶和華始築之壇、○"],[9,14,36,"掃羅曰、我儕夤夜追襲非利士人、掠其所有、以至黎明、不留其一人、僉曰、爾視爲善者行之、祭司曰、當詣上帝、"],[9,14,37,"掃羅諮諏上帝曰、我追襲非利士人可否、爾付之於以色列人手乎、是日上帝不之應、"],[9,14,38,"掃羅曰、爾民長俱前來、察知今日之罪何在、"],[9,14,39,"我指救以色列、維生之耶和華而誓、雖我子約拿單、亦必死亡、民中無人應之、"],[9,14,40,"乃謂以色列衆曰、爾曹在彼、我與我子約拿單在此、民曰、爾視爲善者行之、"],[9,14,41,"掃羅告以色列之上帝耶和華曰、願爾指示其實、乃掣籤、得掃羅及約拿單、民得免焉、"],[9,14,42,"掃羅曰、於我及我子約拿單間掣籤、乃得約拿單、"],[9,14,43,"掃羅謂約拿單曰、爾以所爲告我、約拿單曰、我誠以所執之杖端、嘗蜜少許、我必死也、"],[9,14,44,"掃羅曰、約拿單、爾必死、不然、願上帝罰我維倍、"],[9,14,45,"民謂掃羅曰、約拿單大行拯救於以色列中、豈可死乎、斷乎不可、我儕指維生之耶和華以誓、其首之一髮、不隕於地、蓋彼今日與上帝偕行、於是民援約拿單、免於死亡、"],[9,14,46,"掃羅去非利士人、不追襲之、非利士人歸故土、○"],[9,14,47,"掃羅治以色列國、攻四周之敵、卽摩押亞捫以東諸族、瑣巴列王、及非利士人、無論所往、俱擊敗之、"],[9,14,48,"奮勇擊亞瑪力人、拯以色列族於虜者之手、○"],[9,14,49,"掃羅之子、約拿單、亦施韋、麥基舒亞、又有二女、長名米拉、季名米甲、"],[9,14,50,"其妻名亞希暖、乃亞希瑪斯之女、其軍長名押尼珥、乃掃羅叔尼珥之子、"],[9,14,51,"基士乃掃羅之父、押尼珥父尼珥、乃亞別之子、"],[9,14,52,"掃羅存日、與非利士人力戰、見壯士及勇士、則招募之、"],[9,15,1,"撒母耳謂掃羅曰、昔耶和華遣我膏爾、立爲其民以色列之王、今爾當聽耶和華言、"],[9,15,2,"萬軍之耶和華云、以色列族出埃及時、亞瑪力人若何待之、途間禦之、我記憶焉、"],[9,15,3,"今往擊之、滅其所有、毋加矜恤、男女、童穉、乳子、牛羊駝驢、悉殺戮之、○"],[9,15,4,"掃羅集民於提拉因、核其軍數、步卒二十萬、猶大人一萬、"],[9,15,5,"掃羅至亞瑪力邑、伏於谷中、"],[9,15,6,"謂基尼人曰、離亞瑪力人而去、免爾爲我同滅、蓋以色列人出埃及時、爾善待之、基尼人遂離之而去、"],[9,15,7,"掃羅擊亞瑪力人、自哈腓拉、至埃及相對之書珥、"],[9,15,8,"生擒亞瑪力王亞甲、以刃盡滅其民、"],[9,15,9,"掃羅與民惜亞甲、曁牛羊犢羔之嘉者、及諸美物、不盡滅之、惟陋劣者、則悉殲焉、○"],[9,15,10,"耶和華諭撒母耳曰、"],[9,15,11,"我立掃羅爲王、今則悔之、以其背我、而不我從、亦不遵行我命、撒母耳怒、終夜籲耶和華、"],[9,15,12,"夙興、欲迓掃羅、或告之曰、掃羅至迦密立碑、轉往吉甲、"],[9,15,13,"撒母耳就掃羅、掃羅曰、願耶和華錫嘏於爾、耶和華所命、我已行之、"],[9,15,14,"撒母耳曰、然則我聞羊鳴牛鳴、是何意耶、"],[9,15,15,"掃羅曰、乃衆自亞瑪力攜至、蓋民惜其牛羊之嘉者、欲以祭爾上帝耶和華、其餘我儕盡滅之、"],[9,15,16,"撒母耳曰、姑少待、我以耶和華前夕諭我者告爾、曰、請言之、"],[9,15,17,"撒母耳曰、昔爾自視雖微、非立爲以色列支派之長乎、耶和華膏爾爲以色列王、"],[9,15,18,"遣爾就途曰、爾往盡滅罪人亞瑪力族、戰而殲之、"],[9,15,19,"爾何不聽耶和華言、急於刦奪、行耶和華所惡、"],[9,15,20,"掃羅曰、我實聽耶和華言、往所遣我之途、虜亞瑪力王亞甲、盡滅亞瑪力人、"],[9,15,21,"惟所獲當滅之牛羊、民取其嘉者、欲在吉甲、以祭爾上帝耶和華、"],[9,15,22,"撒母耳曰、耶和華豈喜燔祭及他祭、如喜聽其言乎、夫順服愈於祭祀、聽從愈於羊脂、"],[9,15,23,"違逆與卜筮同罪、頑梗與拜偶像事家神同科、爾棄耶和華命、耶和華亦棄爾、不使爲王、"],[9,15,24,"掃羅曰、我干罪矣、我畏斯民、聽從其言、故違耶和華命、及爾之言、"],[9,15,25,"今則請赦我罪、偕我旋歸、俾我崇拜耶和華、"],[9,15,26,"撒母耳曰、我不偕爾旋歸、蓋爾棄耶和華命、耶和華亦棄爾、不使爲以色列王、"],[9,15,27,"撒母耳轉而欲行、掃羅執其衣裾、裾裂、"],[9,15,28,"撒母耳曰、是日耶和華裂以色列國、使之離爾、以賜爾鄰、賢於爾者、"],[9,15,29,"以色列所恃者、必不誑言、亦不回意、蓋非世人、決不回意也、"],[9,15,30,"掃羅曰、我干罪矣、雖然、求爾於我民之長老、及以色列衆前尊我、偕我旋歸、俾我崇拜爾上帝耶和華、"],[9,15,31,"於是撒母耳轉隨其後、掃羅則崇拜耶和華、○"],[9,15,32,"撒母耳曰、攜亞瑪力王亞甲至我、亞甲懽然而來、曰、死亡之苦、庶乎免矣、"],[9,15,33,"撒母耳曰、爾之刃使婦無子、則爾之母、於婦中亦必無子、遂在吉甲、於耶和華前、斫亞甲而碎之、"],[9,15,34,"撒母耳往拉瑪、掃羅往基比亞、歸其家、"],[9,15,35,"撒母耳至於沒日、不復往見掃羅、爲之懷憂、耶和華立掃羅爲以色列王、亦悔之、"],[9,16,1,"耶和華謂撒母耳曰、我旣棄掃羅、不使爲以色列王、爾爲之懷憂、伊於胡底、可盛膏於角而往、我將遣爾詣伯利恆人耶西、其衆子中、我簡其一爲王、"],[9,16,2,"撒母耳曰、我何可往、掃羅聞之必殺我、耶和華曰、爾可牽犢、言我來欲祭耶和華、"],[9,16,3,"召耶西與祭、爾所當爲、我將示爾、我所言者、爲我膏之、"],[9,16,4,"撒母耳遵耶和華言而行、至伯利恆、邑之長老戰慄迎之、曰、爾爲平康而來乎、"],[9,16,5,"曰、爲平康也、我來祭耶和華、爾當潔己而至、同我與祭、撒母耳遂潔耶西及其子、召之與祭、"],[9,16,6,"旣至、撒母耳見以利押、意謂耶和華之受膏者、果在其前也、"],[9,16,7,"耶和華謂之曰、毋觀其容、及軀幹之修偉、此人乃我所擯、蓋耶和華所見、迥異於人、人觀外貌、耶和華則視內心、"],[9,16,8,"耶西召亞比拿達、使過撒母耳前、撒母耳曰、耶和華亦不簡之、"],[9,16,9,"耶西又使沙瑪過焉、撒母耳曰、耶和華亦不簡之、"],[9,16,10,"耶西使七子咸過其前、撒母耳曰、皆非耶和華所簡也、"],[9,16,11,"又曰、爾子咸在此乎、曰、尚有季者牧羊、撒母耳曰、召之使來、彼未至、我儕不席坐、"],[9,16,12,"遂遣人攜之入、其人赤色、目秀貌美、耶和華曰、斯人是也、起而膏之、"],[9,16,13,"撒母耳取角中之膏、於其諸兄中膏之、自是以後、耶和華之靈大臨大衞、撒母耳啟行、歸於拉瑪、○"],[9,16,14,"耶和華之神離掃羅、有惡神擾之、耶和華使然也、"],[9,16,15,"其臣僕謂之曰、上帝使惡神擾爾、"],[9,16,16,"我主當命侍臣、求善鼓琴者、迨惡神臨爾時、使之鼓琴、則爾愈焉、"],[9,16,17,"掃羅命侍臣曰、爲我求善鼓琴者、攜之至我、"],[9,16,18,"有一少者對曰、我嘗見伯利恆人耶西之子善鼓琴、大勇善戰、愼言語、美姿容、耶和華亦偕之、"],[9,16,19,"掃羅遣使詣耶西曰、爾子大衞、與羊同在、遣至我所、"],[9,16,20,"耶西以驢負餅、以酒一革囊、與山羊羔一、付其子大衞、奉於掃羅、"],[9,16,21,"大衞旣至、侍立於掃羅前、掃羅愛之甚、遂爲其執兵者、"],[9,16,22,"掃羅遣人詣耶西曰、大衞已沾我恩、容侍我側、"],[9,16,23,"值上帝使惡神臨掃羅時、大衞取琴鼓之、掃羅則快然而愈、惡神離之、"],[9,17,1,"非利士人集其軍旅以戰、至猶大之梭哥、建營於以弗大憫、在梭哥亞西加間、"],[9,17,2,"掃羅亦與以色列人會集、建營於以拉谷、陳列行伍、與非利士人戰、"],[9,17,3,"非利士人立於此山、以色列人立於彼山、其間有谷、"],[9,17,4,"有挑戰者迦特人歌利亞、自非利士營出、體長六肘及一布指、"],[9,17,5,"首戴銅冑、身擐銅甲、重五千舍客勒、"],[9,17,6,"股著銅袚、肩負銅戟、"],[9,17,7,"其槍之柯、大如織器之梁、其鋒之鐵重六百舍客勒、持干者行於前、"],[9,17,8,"彼立而呼以色列軍旅曰、爾曹出而列陳、欲何爲、我非非利士人乎、爾曹非掃羅之臣僕乎、當簡一人、使下而就我、"],[9,17,9,"如能戰而殺我、我儕則爲爾役、如我勝而殺彼、爾曹則爲我役、而服事我、"],[9,17,10,"又曰、以色列軍旅、今日爲我所侮、可遣一人與我戰鬬、"],[9,17,11,"掃羅與以色列衆聞其言、驚惶懼甚、○"],[9,17,12,"夫大衞、乃猶大伯利恆之以法他人耶西子也、掃羅時、耶西壽高年邁、有子八人、"],[9,17,13,"年長之三子、從掃羅出戰、長以利押、次亞比拿達、三沙瑪、"],[9,17,14,"大衞乃季子也、其兄三人、俱從掃羅、"],[9,17,15,"大衞屢離掃羅、返伯利恆、牧父之羊、"],[9,17,16,"非利士人朝夕進前而立、歷四十日、○"],[9,17,17,"耶西謂其子大衞曰、爾取烘穀一伊法、與餅十、速攜至營、給爾諸兄、"],[9,17,18,"又取乳餅十、以餽千夫長、省視爾兄、取質而返、"],[9,17,19,"時、掃羅與大衞三兄、及以色列衆、在以拉谷、與非利士人戰、"],[9,17,20,"大衞晨興、以羊付守者、遵耶西命、取物而行、至列車之所、適軍旅列陳而出、鼓譟以戰、"],[9,17,21,"以色列人與非利士人列陳、兩軍相對、"],[9,17,22,"大衞以其什物付守者手、趨入行伍、問其兄安、"],[9,17,23,"相語時、非利士之挑戰者、迦特人歌利亞、自其行伍出、語如前言、爲大衞所聞、"],[9,17,24,"以色列衆見之、大懼而遁、"],[9,17,25,"相語曰、爾見斯人乎、彼來欲侮以色列族、如有殺之者、王將賜以厚財、以女妻之、並於以色列中、復其父家、"],[9,17,26,"大衞謂旁立之人曰、有人殺此非利士人、洒以色列人之辱、將如何待之、此未受割之非利士人爲誰、而可侮維生上帝之軍乎、"],[9,17,27,"民如前言對曰、殺此人者、必如是待之、"],[9,17,28,"長兄以利押聞大衞與衆言、怒之曰、爾來曷故、彼野間數羊、付於誰乎、爾之驕矜、中心之惡、我知之矣、爾來特欲觀戰耳、"],[9,17,29,"大衞曰、我何所爲、惟問一言而已、"],[9,17,30,"遂轉離之而他顧、問以前言、民答之如故、"],[9,17,31,"或聞大衞所言、述於掃羅前、掃羅乃召之、"],[9,17,32,"大衞謂掃羅曰、人勿爲之喪膽、僕將前往、與彼非利士人戰、"],[9,17,33,"掃羅曰、爾不能與之戰、蓋爾年少、彼自幼爲戰士、"],[9,17,34,"大衞曰、爾僕爲父牧羊、有獅或熊至羣中、攫羔而去、"],[9,17,35,"我出追而擊之、援羔於其口、彼起而攻我、我執其鬣、擊而殺之、"],[9,17,36,"爾僕殺獅與熊、此未受割之非利士人、侮維生上帝之軍、亦必如斯獸之一焉、"],[9,17,37,"又曰、耶和華旣援我於獅之爪、熊之掌、亦必援我於此非利士人之手、掃羅曰、往哉、耶和華必與爾偕、"],[9,17,38,"掃羅以其戎衣衣大衞、以銅冑冠其首、以鎧甲被其身、"],[9,17,39,"大衞佩劍衣外、因未嫻習、欲試而行、乃謂掃羅曰、我未嫻此、不能服之而行、遂卸之、"],[9,17,40,"手執杖、擇谿間光潔之石五、置於所攜牧人之囊、亦執發石之繩、往迎非利士人、"],[9,17,41,"非利士人前迎大衞、持干者爲先導、"],[9,17,42,"非利士人環視、見大衞則藐之、蓋其年少、色亦貌美、"],[9,17,43,"謂之曰、爾執杖迎我、我豈犬乎、遂指其神而詛之、"],[9,17,44,"又謂大衞曰、爾來、我取爾肉、給於空中之鳥、野間之獸、"],[9,17,45,"大衞曰、爾來迎我、以劍與槍及戟、我來迎爾、以萬軍耶和華之名、卽爾所侮以色列軍旅之上帝、"],[9,17,46,"今日耶和華必付爾於我手、我必擊爾、斬爾首級、以非利士軍旅之屍、給於空中之鳥、野間之獸、使天下咸知以色列中有上帝、"],[9,17,47,"亦使此會咸知耶和華施行拯救、非以劍以槍、蓋戰事屬於耶和華、彼必付爾於我手、"],[9,17,48,"非利士人進迎大衞、大衞亦向行伍疾趨迎之、"],[9,17,49,"以手探囊取石、以繩發之、擊非利士人、深入其顙、遂仆於地、"],[9,17,50,"如是大衞以繩與石、勝非利士人、擊而殺之、手不持劍、"],[9,17,51,"遂趨而前、立於非利士人身側、拔其劍出鞘殺之、斬其首級、非利士人見其勇士已死、則遁、"],[9,17,52,"以色列與猶大人並起、鼓譟而追、至於該、及以革倫邑門、非利士人被創者、仆於沙拉音道、延至迦特與以革倫、"],[9,17,53,"以色列人追非利士人而返、刦掠其營、"],[9,17,54,"大衞取非利士人首級、攜至耶路撒冷、以其兵甲置於己幕、○"],[9,17,55,"初、掃羅見大衞出擊非利士人、則謂軍長押尼珥曰、押尼珥、此少者誰氏子、押尼珥曰、王歟、我指爾生命而誓、我不知也、"],[9,17,56,"王曰、爾詢此孺子爲誰之子、"],[9,17,57,"大衞擊非利士人而返、手執首級、押尼珥引之見掃羅、"],[9,17,58,"掃羅曰、少者、爾爲誰之子、大衞曰、我乃爾僕伯利恆人耶西之子也、"],[9,18,1,"大衞與掃羅言畢、約拿單之心、與大衞之心相契、約拿單愛之如命、"],[9,18,2,"當日掃羅留之、不使復歸父家、"],[9,18,3,"約拿單與大衞結約、愛之如命故也、"],[9,18,4,"遂解衣賜之、又以戎衣、弓劍與紳予之、"],[9,18,5,"大衞爲掃羅所遣、處事明敏、掃羅立之爲武士長、民衆與掃羅臣僕咸視爲善、○"],[9,18,6,"大衞戮彼非利士人、偕衆歸時、婦女自以色列諸邑出、謳歌舞蹈、擊鼓擊磐、欣然以迎掃羅王、"],[9,18,7,"舞蹈唱和曰、掃羅殺其千千、大衞殺其萬萬、"],[9,18,8,"掃羅怒甚、不悅斯言、曰、稱大衞以萬數、稱我僅以千數、此外、彼之所得、非國而何、"],[9,18,9,"自是以後、掃羅見大衞、則睚眦之、○"],[9,18,10,"翌日、上帝使惡神大臨掃羅、遂在室中發狂言、大衞鼓琴如平日、掃羅手執戟、"],[9,18,11,"以戟擲之、曰、我必刺大衞、釘之於牆、大衞逃避者再、"],[9,18,12,"掃羅以耶和華離己、而偕大衞、則懼之、"],[9,18,13,"使其離側、立之爲千夫長、率民出入、"],[9,18,14,"大衞處事明敏、耶和華與之偕、"],[9,18,15,"掃羅見其處事明敏、懼之益甚、"],[9,18,16,"惟以色列與猶大人咸愛之、以率其出入故也、○"],[9,18,17,"掃羅謂大衞曰、我以長女米拉妻爾、惟當爲我奮勇、爲耶和華戰、蓋掃羅意謂、我不可親手害之、願非利士人加手害之、"],[9,18,18,"大衞曰、我何人斯、我之戚族、及我父家、於以色列中爲何、致我爲王之壻乎、"],[9,18,19,"屆期、掃羅當以其女米拉妻大衞、乃妻於米何拉人亞得利、"],[9,18,20,"掃羅之女米甲愛大衞、或告掃羅、掃羅悅、"],[9,18,21,"曰、我妻以女、以爲機檻、使非利士人加手害之、遂謂大衞曰、今日復爲我壻、"],[9,18,22,"掃羅命其臣僕私語大衞曰、王悅爾、其臣僕亦愛爾、可爲王壻、"],[9,18,23,"臣僕以此言告大衞、大衞曰、我素貧賤、爲王之壻、爾以爲細事乎、"],[9,18,24,"臣僕以大衞之言反告、"],[9,18,25,"掃羅曰、當告大衞云、王不受聘禮、第求非利士人之陽皮一百、以報王仇、掃羅之意、欲假手於非利士人殺之、"],[9,18,26,"臣僕以此言告大衞、大衞樂爲王壻、"],[9,18,27,"尚未屆期、大衞與從者起、往殺非利士人二百、攜其陽皮、悉數進王、致爲王壻、掃羅遂以其女米甲妻之、"],[9,18,28,"掃羅見耶和華偕大衞、知其女米甲亦愛之、"],[9,18,29,"故懼之愈甚、恆與爲敵、○"],[9,18,30,"非利士之牧伯迭出以戰、大衞處事、每較掃羅臣僕明敏、以致其名大見尊重焉、"],[9,19,1,"掃羅語其子約拿單、及其臣僕、使殺大衞、"],[9,19,2,"惟約拿單甚悅大衞、告之曰、我父謀殺爾、詰朝請自愼、匿於僻處、"],[9,19,3,"我出至爾所在之田、立於父側、與言爾事、若有所見、卽以告爾、"],[9,19,4,"約拿單對父掃羅、褒揚大衞、曰、王勿獲罪於爾僕大衞、蓋大衞未嘗獲罪於爾、彼之所爲、於爾甚善、"],[9,19,5,"昔冒死擊非利士人、耶和華爲以色列衆大施拯救、爾見之喜、今何無故殺之、流無辜之血、而干罪戾乎、"],[9,19,6,"掃羅從約拿單言、指維生之耶和華而誓、必不殺之、"],[9,19,7,"約拿單招大衞、以是告之、導見掃羅、侍前如故、○"],[9,19,8,"厥後又有戰鬬、大衞出與非利士人戰、大行殺戮、其衆遂遁、"],[9,19,9,"耶和華使惡神臨於掃羅、掃羅執戟、坐於室中、大衞鼓琴、"],[9,19,10,"掃羅欲以戟刺大衞、釘之於牆、大衞避焉、戟入於牆、是夕大衞遁而獲免、"],[9,19,11,"掃羅遣使守大衞第、待旦殺之、大衞妻米甲告大衞曰、今夕不自救、明日必見殺、"],[9,19,12,"米甲自牖縋之、逃而獲免、"],[9,19,13,"米甲取家神之像置於牀、以羊毧衾蔽其首、覆之以裯、"],[9,19,14,"掃羅遣使執大衞、婦曰、彼病矣、"],[9,19,15,"掃羅復遣其使視大衞曰、以牀舁之來、俾我殺之、"],[9,19,16,"使者入、見像於牀、羊毧衾蔽其首、"],[9,19,17,"掃羅謂米甲曰、何欺我若此、容我敵逃而獲免、米甲對曰、彼云任我去、勿使我殺爾、○"],[9,19,18,"大衞逃而獲免、至拉瑪見撒母耳、以掃羅所待告之、遂與撒母耳往拿約居焉、"],[9,19,19,"或告掃羅曰、大衞在拉瑪之拿約、"],[9,19,20,"掃羅遣使執之、至則見彼先知一班、感神而言、撒母耳立於其中爲之長、上帝之神臨於使者、彼亦感靈而言、"],[9,19,21,"或告掃羅、又遣他使、亦感靈而言、三遣使、亦感靈而言、"],[9,19,22,"乃親往拉瑪、至西沽大井、問撒母耳大衞安在、或曰、在拉瑪之拿約、"],[9,19,23,"遂往拉瑪之拿約、上帝之神亦臨之、且行且言、至拉瑪之拿約、"],[9,19,24,"解其衣、在撒母耳前、感靈而言、永朝永夕、裸體而臥、故有言曰、掃羅亦在先知中乎、"],[9,20,1,"大衞自拉瑪之拿約遁、詣約拿單、言曰、我何所爲、有何過惡、干何罪戾於爾父前、致索我命、"],[9,20,2,"約拿單曰、不然、爾必不死、我父所爲、事之巨細、無不示我、豈獨隱此於我、無是事也、"],[9,20,3,"大衞誓曰、爾父明知我蒙爾恩、故曰、勿令約拿單知之、恐其憂戚、然我指維生之耶和華、及爾生命而誓、我離死地、僅一步耳、"],[9,20,4,"約拿單曰、爾心所欲、我必爲爾行之、"],[9,20,5,"大衞曰、明日月朔、我當侍王宴、容我匿於田、越至三日之夕、"],[9,20,6,"如爾父見我不在、可言大衞切請於我、許其趨歸伯利恆故邑、蓋其全家獻歲祭於彼、"],[9,20,7,"如爾父言善、則爾僕得安、如其震怒、可知其決意害我、"],[9,20,8,"昔爾使僕指耶和華、與爾盟約、故當以仁慈待我、如我有罪、爾自殺我、何攜我詣爾父乎、"],[9,20,9,"約拿單曰、決不爲此、我若確知我父決意害爾、豈不以告、"],[9,20,10,"大衞曰、如爾父以厲言叱爾、誰以告我、"],[9,20,11,"約拿單曰、爾來、偕往於田、二人遂往、"],[9,20,12,"約拿單謂大衞曰、願以色列之上帝耶和華爲證、明日此時、或至三日、我窺我父於爾、若有善意、豈不遣人示爾乎、"],[9,20,13,"我父若欲害爾、我不示爾、使爾安然而去、則願耶和華罰約拿單維倍、惟願耶和華偕爾、如昔偕我父然、"],[9,20,14,"爾當以耶和華之仁慈待我、不第在我存日、免我死亡、"],[9,20,15,"厥後耶和華殲大衞諸敵於地時、亦勿絕爾仁慈於我家、歷世靡曁、"],[9,20,16,"約拿單遂與大衞家盟約曰、不守此約者、願耶和華於大衞之敵討之、"],[9,20,17,"約拿單愛大衞、如愛己命、故使之復誓、"],[9,20,18,"謂之曰、明日月朔、爾虛其位、人必見之、"],[9,20,19,"越至三日、爾必速往、至昔相議之時、爾所匿跡之處、俟於以色石旁、"],[9,20,20,"我將射三矢於其側、佯欲射的、"],[9,20,21,"命童取矢、如曰矢在此、可取之來、我指維生之耶和華而誓、爾必平安無害、"],[9,20,22,"如我謂童曰、矢在彼、則行爾途、乃耶和華使爾去也、"],[9,20,23,"至於爾我所言之事、耶和華恆在爾我間爲證、○"],[9,20,24,"大衞匿於田、月朔王席坐、"],[9,20,25,"如常附牆而坐、約拿單侍立、押尼珥坐於掃羅側、大衞之位虛焉、"],[9,20,26,"是日掃羅無言、意大衞遇事、或蒙不潔、必不潔也、"],[9,20,27,"翌日乃月之二日、大衞之位仍虛、掃羅謂其子約拿單曰、耶西之子、昨日今日不赴宴、曷故、"],[9,20,28,"約拿單對曰、大衞切求於我、許其往伯利恆、"],[9,20,29,"曰、請容我往、家有祭祀於邑、兄命必至、如沾爾恩、請容我往、見我諸兄、故未赴王宴、"],[9,20,30,"掃羅怒約拿單曰、頑梗悖逆之婦所生者、我豈不知爾簡耶西之子、致辱爾身、及母體乎、"],[9,20,31,"耶西之子在世、爾與爾國、必不堅立、今當遣人執之詣我、彼必死、"],[9,20,32,"約拿單謂父曰、何故致之於死、彼何所爲、"],[9,20,33,"掃羅擲戟欲刺之、於是約拿單知父決意殺大衞、"],[9,20,34,"則忿然離席、月之二日不食、因其父辱大衞、而爲之憂也、○"],[9,20,35,"詰朝、約拿單依前與大衞所約之時、出於田、一童偕之、"],[9,20,36,"謂童子曰、爾其疾趨、尋我所射之矢、童趨之時、約拿單射矢過之、"],[9,20,37,"童至其矢所射之處、約拿單呼曰、矢非過於爾乎、"],[9,20,38,"又呼曰、速往勿遲、童拾其矢、返詣厥主、"],[9,20,39,"童不知其意、惟約拿單大衞知之、"],[9,20,40,"約拿單以器械與童曰、攜之入邑、"],[9,20,41,"童旣去、大衞自石之南而出、伏地三拜、彼此接吻、相向而哭、大衞尤甚、"],[9,20,42,"約拿單謂大衞曰、安然而去、我儕二人曾指耶和華名而誓、願耶和華在爾我間、及爾我後裔中、至於永世、大衞遂起而往、約拿單入於邑、"],[9,21,1,"大衞至挪伯、見祭司亞希米勒、亞希米勒戰慄迎之、曰、爾奚獨至、無人與偕、"],[9,21,2,"大衞曰、王以事委我、且曰所遣所命者、勿令人知、我約僕從、俟於某處、"],[9,21,3,"今爾手中何所有、請以五餅給我、或予所有他物、"],[9,21,4,"祭司曰、我手中無常餅、聖餅則有之、惟僕從不近婦女、乃可給焉、"],[9,21,5,"大衞曰、迄今三日、未近婦女、我儕啟行、雖爲常事、然僕從之器乃潔、況今日乎、"],[9,21,6,"祭司遂以聖餅給之、蓋除陳設餅外、罔有他餅、此餅徹於耶和華前時、卽以新餅陳之、"],[9,21,7,"是日掃羅之僕留於耶和華前、乃以東人多益、掃羅之牧長也、"],[9,21,8,"大衞謂亞希米勒曰、王事孔亟、我未攜刃與械、爾有劍戟乎、"],[9,21,9,"祭司曰、昔爾在以拉谷、殺非利士人歌利亞、其劍在此、裹之以布、置聖衣後、其外無他、爾欲取之可也、大衞曰、無似此者、請以給我、○"],[9,21,10,"大衞因畏掃羅、是日遁至迦特王亞吉、"],[9,21,11,"亞吉臣僕謂王曰、此非彼國之王大衞乎、昔衆舞蹈唱和曰、掃羅殺其千千、大衞殺其萬萬、非指此人乎、"],[9,21,12,"大衞以此言藏於心、甚懼迦特王亞吉、"],[9,21,13,"乃於衆前變其舉動、佯狂、妄塗於門、流涎於鬚、"],[9,21,14,"亞吉謂其臣僕曰、爾觀此人、乃顚狂者、何爲攜之詣我、"],[9,21,15,"我豈乏狂者、而攜至我所、顚狂於我前、夫夫也、豈可入我室乎、"],[9,22,1,"大衞去彼、遁於亞杜蘭穴、其兄弟及父全家聞之、咸來相就、"],[9,22,2,"凡困迫者、逋負者、不得志者、咸集歸之、約四百人、大衞爲其長、○"],[9,22,3,"大衞去彼、往摩押之米斯巴、謂摩押王曰、請容我父母出、與爾偕居、俟我知上帝爲我何爲、"],[9,22,4,"遂導父母詣摩押王、大衞處寨時、其父母與摩押王同居、"],[9,22,5,"先知迦得謂大衞曰、毋居於寨、宜往猶大地、遂去彼、入哈列林、"],[9,22,6,"大衞與從者爲人所見、掃羅聞之、是時掃羅在基比亞崇邱、坐於垂絲柳下、手執其戟、僕從環侍、"],[9,22,7,"掃羅謂之曰、便雅憫人、爾其聽之、耶西之子、豈以田畝葡萄園賜爾、立爲千夫長、百夫長、"],[9,22,8,"使爾同謀攻我、我子與耶西子結盟、無人以告、罔爲我憂、我子激我臣僕、伏以害我、有如今日、亦無人以告、"],[9,22,9,"時、以東人多益立於臣僕中、對曰、我覩耶西子至挪伯、見亞希突子亞希米勒、"],[9,22,10,"亞希米勒爲之諮諏耶和華、且給以食、以非利士人歌利亞之劍予之、"],[9,22,11,"王遂遣人召祭司亞希突子亞希米勒、與其父家、在挪伯爲祭司者、咸至王所、"],[9,22,12,"掃羅曰、亞希突子宜聽我言、曰、我主、我在此、"],[9,22,13,"掃羅曰、爾與耶西之子、同謀攻我、給之以餅、予之以劍、爲之諮諏上帝、致彼伏以害我、有如今日、何也、"],[9,22,14,"亞希米勒對曰、大衞乃王之壻、進爲謀臣、尊於王室、諸臣僕中、忠孰如之、"],[9,22,15,"我爲之諮諏上帝、豈自今日始耶、決不爲此、王勿罪僕、與我父家、此事鉅細、僕俱不知、"],[9,22,16,"王曰、亞希米勒、爾與爾父全家必死、"],[9,22,17,"王謂左右侍衞曰、往殺耶和華之祭司、因彼助大衞、知其遁逃、而不以告、惟王臣僕不欲伸手、擊耶和華之祭司、"],[9,22,18,"王謂多益曰、爾往擊之、以東人多益遂擊祭司、當日殺衣枲聖衣者、八十五人、"],[9,22,19,"祭司之邑挪伯、男女、童穉、乳子、牛羊及驢、皆刃擊之、"],[9,22,20,"亞希突孫、亞希米勒子亞比亞他得免、逃往大衞、"],[9,22,21,"以掃羅殺耶和華祭司之事告之、"],[9,22,22,"大衞曰、當日以東人多益在彼、我知其必告掃羅、爾父全家死亡、我使之也、"],[9,22,23,"與我偕居、勿懼、索我命者、卽索爾命、偕我則得保全、"],[9,23,1,"或告大衞曰、非利士人攻基伊拉、刦其禾場、"],[9,23,2,"大衞諮諏耶和華曰、我往擊非利士人可否、耶和華曰、其往擊之、以援基伊拉、"],[9,23,3,"大衞之從者曰、今在猶大尚懼、況往基伊拉、攻非利士之軍旅乎、"],[9,23,4,"大衞復諮諏耶和華、耶和華曰、起往基伊拉、我將以非利士人付於爾手、"],[9,23,5,"大衞及從者往基伊拉、與非利士人戰、大行殺戮、虜其牲畜、而救基伊拉居民、○"],[9,23,6,"初、亞希米勒子亞比亞他逃至基伊拉、見大衞時、手攜聖衣、"],[9,23,7,"或以大衞至基伊拉告掃羅、掃羅曰、上帝付之於我手矣、蓋入有門有楗之邑、受困於其中也、"],[9,23,8,"掃羅乃招民衆出戰、欲下基伊拉、圍困大衞、及其從者、"],[9,23,9,"大衞知掃羅蓄謀害己、遂謂祭司亞比亞他曰、攜聖衣至、"],[9,23,10,"大衞禱曰、以色列之上帝耶和華歟、爾僕確聞掃羅欲至基伊拉、以我之故、翦滅斯邑、"],[9,23,11,"基伊拉人付我於其手乎、掃羅果來、如僕所聞乎、以色列之上帝耶和華歟、請告爾僕、耶和華曰、掃羅將至矣、"],[9,23,12,"大衞曰、基伊拉人以我及從者、付於掃羅手乎、耶和華曰、彼必付焉、"],[9,23,13,"大衞與其從者、約六百人、遂去基伊拉、擇地而往、或告掃羅曰、大衞脫離基伊拉、掃羅遂止不出、○"],[9,23,14,"大衞居曠野之山寨、恆在西弗野之山地、掃羅索之無虛日、惟上帝不付於其手、"],[9,23,15,"大衞知掃羅已出、而索其命、時、大衞在西弗野之林中、"],[9,23,16,"掃羅子約拿單入林、見大衞、使賴上帝以爲固、"],[9,23,17,"謂之曰、毋懼、我父掃羅之手、必不獲爾、爾將爲以色列王、我居其次、是我父掃羅所知也、"],[9,23,18,"二人乃於耶和華前立約、大衞居林、約拿單歸其家、"],[9,23,19,"西弗人上基比亞、見掃羅曰、大衞匿於我所、處於林中之寨、在曠野南之哈基拉山、"],[9,23,20,"王歟、隨意往彼、付之於王手、乃我之責也、"],[9,23,21,"掃羅曰、爾旣恤我、願耶和華錫嘏於爾、"],[9,23,22,"人言大衞甚狡、請爾旋歸、復察其實、觀其匿於何方、爲誰所見、"],[9,23,23,"察其所匿諸處、旣得其實、則返以告、我偕爾往、若在斯土、我必於猶大億兆中、索之務獲、"],[9,23,24,"西弗人遂起、先掃羅而返、時、大衞與從者、在瑪雲曠野南之亞拉巴、"],[9,23,25,"掃羅率從者往索之、或告大衞、大衞遂下至磐石、居瑪雲野、掃羅聞之、追於其野、"],[9,23,26,"掃羅行於山左、大衞與從者行於山右、大衞畏掃羅、急欲逃避、因掃羅與從者圍大衞及其從者、欲執之、"],[9,23,27,"有使者至、謂掃羅曰、非利士人犯境、其速返、"],[9,23,28,"掃羅乃舍大衞、轉攻非利士人、故名其處曰西拉哈瑪希羅結、"],[9,23,29,"大衞去彼、居隱基底山寨、"],[9,24,1,"掃羅追非利士人而歸、或告曰、大衞在隱基底野、"],[9,24,2,"掃羅簡以色列衆三千人、往索大衞及其從者、於野羊磐石、"],[9,24,3,"至途間之羊牢、有穴在焉、掃羅入而遺矢、時、大衞與從者居穴深處、"],[9,24,4,"從者曰、昔耶和華謂爾曰、我將以敵付於爾手、任意待之、今日是矣、大衞遂起、竊斷掃羅衣裾、"],[9,24,5,"旣而中心自責、"],[9,24,6,"謂從者曰、我主乃耶和華之受膏者、願耶和華禁我舉手攻之、以其爲耶和華所膏也、"],[9,24,7,"大衞言此、阻其從者、不許起攻掃羅、掃羅出穴而去、"],[9,24,8,"後大衞亦起出穴、呼掃羅曰、我主、我王、掃羅回顧、大衞伏地而拜、"],[9,24,9,"謂掃羅曰、有言大衞欲加害於爾、曷聽之哉、"],[9,24,10,"今在穴中、耶和華付爾於我手、爾所目擊、或勸我殺爾、惟我惜爾、自謂不可舉手害我主、緣爲耶和華所膏也、"],[9,24,11,"我父乎、請觀爾裾在於我手、我旣斷之、而不殺爾、可知我手無惡無過、爾雖獵取我命、而我未嘗獲罪於爾、"],[9,24,12,"願耶和華在爾我間判斷、爲我伸寃、惟我手不加諸爾、"],[9,24,13,"古諺有云、惡自惡人出、惟我手不加諸爾、"],[9,24,14,"以色列王出、所蹤跡者誰、所追襲者誰、乃死犬躍蚤耳、"],[9,24,15,"願耶和華在爾我間審鞫之、判斷之、鑒察之、爲我伸寃、援我於爾手、"],[9,24,16,"大衞言畢、掃羅曰、我子大衞、此爾聲乎、遂大聲而哭、"],[9,24,17,"謂大衞曰、爾待我以善、我待爾以惡、爾較義於我、"],[9,24,18,"今爾顯明以善待我、蓋耶和華付我於爾手、爾不殺我、"],[9,24,19,"人遇敵、豈任其安然去耶、願耶和華因爾今日所行於我、而報以善、"],[9,24,20,"我知爾必爲王、以色列國堅定於爾手、"],[9,24,21,"今當指耶和華而誓、不絕我嗣、不滅我名於我父家、"],[9,24,22,"大衞與掃羅誓、掃羅遂歸、大衞及其從者往於寨、"],[9,25,1,"撒母耳沒、以色列衆咸集、爲之哀悼、在拉瑪葬於其第、大衞啟行、至巴蘭野、○"],[9,25,2,"有居瑪雲者、業在迦密、甚富、有綿羊三千、山羊一千、適在迦密剪羊毛、"],[9,25,3,"其人屬迦勒族、名拿八、剛愎凶惡、妻名亞比該、聰慧豔麗、"],[9,25,4,"大衞在野、聞拿八剪羊毛、"],[9,25,5,"遣少者十人、謂之曰、爾上迦密、往見拿八、託我名問其安、"],[9,25,6,"曰、願爾畢生綏安、願爾舉家綏安、願爾凡所有者皆安、"],[9,25,7,"我聞有人爲爾剪羊毛、昔爾牧者偕我、我未辱之、在迦密時、終無所失、"],[9,25,8,"問爾少者、彼必告爾、我於佳日而至、故願少者得沾爾恩、隨爾手中所有、以賜爾僕、及爾子大衞、"],[9,25,9,"大衞之少者至、依此言託大衞名告拿八、不贅一詞、"],[9,25,10,"拿八曰、大衞爲誰、耶西之子爲誰、邇時僕逃其主者甚衆、"],[9,25,11,"豈可以我餅水、及爲剪羊毛者所宰之肉、給於不知奚自之人乎、"],[9,25,12,"少者旋歸、以斯言告大衞、"],[9,25,13,"大衞謂從者曰、各佩劍、遂佩之、大衞亦佩劍、從大衞而上者、約四百人、留守什物者二百人、○"],[9,25,14,"有少者一人、告拿八妻亞比該曰、大衞自野遣使、問我主安、主反詈之、"],[9,25,15,"彼待我甚厚、我在野間與之往來、終不見辱、亦無所失、"],[9,25,16,"我牧羊時、彼與我偕、晝夜爲我垣墉、"],[9,25,17,"今當自籌、如何以行、蓋禍必及我主、與其全家、彼乃庸人、不可與言、"],[9,25,18,"亞比該急取餅二百、酒二囊、已烹之羊五、烘穀五細亞、葡萄乾一百穗、無花果餅二百、俱負於驢、"],[9,25,19,"謂其少者曰、爾先往、我後至、惟不告其夫拿八、"],[9,25,20,"乘驢下山之坳、大衞率衆而來、與之相遇、"],[9,25,21,"大衞曾曰、昔我在野、守此鄙夫所有、毫無遺失、實爲徒勞、蓋彼以惡報善、"],[9,25,22,"凡屬彼者、我若留其一男、至於明晨、則願上帝罰大衞之敵維倍、○"],[9,25,23,"亞比該見大衞、急下驢、伏地而拜、"],[9,25,24,"跪其足下曰、我主歟、願咎歸於我、容婢進言、請垂聽焉、"],[9,25,25,"求我主勿以庸人拿八爲意、其人與名相符、其名拿八、其人愚妄也、我主所遣之少者、婢不及見、"],[9,25,26,"我主歟、耶和華旣禁爾流人之血、阻爾親手復仇、我指維生之耶和華、與爾生命以誓、願爾敵及謀害爾者、俱如拿八、"],[9,25,27,"婢所攜之禮物、奉於我主、請以給相從之少者、"],[9,25,28,"求赦婢過、我主爲耶和華戰、耶和華必鞏固我主之家、我主終身無疵可求、"],[9,25,29,"人雖起而追爾、以索爾命、然我主之命、乃封於生命包中、與爾上帝耶和華偕、若夫敵之生命、耶和華則必棄擲之、如以繩發石焉、"],[9,25,30,"迨耶和華踐其前言、施諸善於我主、立爲以色列君、"],[9,25,31,"我主不以今日流無辜之血、爲己復仇、懷憂抱憾、耶和華厚待我主時、垂念爾婢、"],[9,25,32,"大衞曰、以色列之上帝耶和華、今日遣爾迎我、當頌美之、"],[9,25,33,"爾今阻我流人之血、親手復仇、爾智可稱、爾躬可讚、"],[9,25,34,"以色列之上帝、維生之耶和華、阻我加害於爾、我指之而誓、如爾不速來迎、凡屬拿八者、至於明晨、不遺一男、"],[9,25,35,"大衞受其物、曰、爾安然以歸、我聽爾言、徇爾情、"],[9,25,36,"亞比該返至拿八、見其家中設宴、可擬王筵、拿八中心歡樂、醉甚、事無巨細、亞比該俱不以告、以待明晨、"],[9,25,37,"詰朝、拿八宿酲已解、其妻告以此事、拿八心神喪失、塊然如石、"],[9,25,38,"越十日、耶和華擊之、遂死、"],[9,25,39,"大衞聞拿八死、則曰、我見辱於拿八、耶和華伸我之寃、又禁厥僕行惡、以拿八之惡歸於其首、當頌美之、大衞遣人語亞比該、欲娶爲室、"],[9,25,40,"大衞之僕至迦密、見亞比該曰、大衞遣我至此、欲娶爾爲室、"],[9,25,41,"亞比該遂起、俯伏於地、曰、爾婢爲役、以濯我主衆僕之足、"],[9,25,42,"急起乘驢、五女相從、隨大衞之使而往、爲大衞妻、"],[9,25,43,"大衞先娶耶斯列人亞希暖、二人俱爲其妻、"],[9,25,44,"掃羅之女米甲、曾爲大衞之妻、掃羅使之改適迦琳人拉億子帕提、"],[9,26,1,"西弗人至基比亞、見掃羅曰、大衞匿於曠野前之哈基拉山、"],[9,26,2,"掃羅起、率其所簡以色列衆三千人、下至西弗野、以索大衞、"],[9,26,3,"在曠野前之哈基拉山、建營途側、大衞居野、聞掃羅追之、"],[9,26,4,"乃遣偵者、察知掃羅果至、"],[9,26,5,"遂起、至掃羅建營之所、觀掃羅及其軍長尼珥子押尼珥所臥之處、掃羅臥於車營、民衆列營四周、"],[9,26,6,"大衞謂赫人亞希米勒、及洗魯雅子約押弟亞比篩曰、誰願偕我、至掃羅營、亞比篩曰、我願偕往、"],[9,26,7,"大衞與亞比篩夜至民所、見掃羅寢於車營、首旁有戟、插於地、押尼珥與民、四周而臥、"],[9,26,8,"亞比篩謂大衞曰、今日上帝以敵付於爾手、許我以戟擊之、釘之於地、一擊而已、毋庸再擊、"],[9,26,9,"大衞曰、毋加殺害、耶和華之受膏者、誰舉手攻之、而無罪乎、"],[9,26,10,"又曰、我指維生之耶和華而誓、耶和華必擊之、或使及期而死、或使臨陳而亡、"],[9,26,11,"耶和華之受膏者、願耶和華禁我舉手攻之、爾第取其首旁之戟、及其水甁而去、"],[9,26,12,"於是大衞取戟及水甁、二人卽去、衆皆不見、不知不寤、以耶和華使其沉睡也、"],[9,26,13,"大衞越至相對之所、遙立山巔、其間有隙甚巨、"],[9,26,14,"呼民及尼珥子押尼珥曰、押尼珥歟、爾不答乎、押尼珥曰、爾爲誰、乃呼王乎、"],[9,26,15,"大衞曰、爾非豪傑乎、以色列中誰可擬爾、有人入營、欲殺王、爾之主、曷不護衞之、"],[9,26,16,"爾所爲者非善、我指維生之耶和華而誓、爾曹不衞爾主、耶和華之受膏者、宜死、試觀王戟、曁首旁之水甁安在、"],[9,26,17,"掃羅識大衞聲、遂曰、我子大衞、此爾聲乎、大衞曰、王歟、我主、是我聲也、"],[9,26,18,"又曰、我主追僕、曷故、我何所爲、我手中有何惡、"],[9,26,19,"我主我王、請聽僕言、如耶和華激爾攻我、願其歆享祭物、若由人意、願耶和華詛之、蓋今逐我、不容附於耶和華之業、命我往事他神、"],[9,26,20,"以色列王之出、乃索躍蚤、如人獵鶉於山、今願勿使我血、流於遠耶和華之地、"],[9,26,21,"掃羅曰、我有罪矣、我子大衞可歸、今日爾以我命爲寶、我亦不復害爾、我爲人愚昧、謬妄之甚、"],[9,26,22,"大衞曰、王戟在此、命一少者來取可也、"],[9,26,23,"耶和華必依人公義誠實而報之、蓋今日耶和華付爾於我手、而我不願舉手攻其受膏者、"],[9,26,24,"我今日以爾命爲重、願耶和華亦以我命爲重、且援我於諸難、"],[9,26,25,"掃羅曰、我子大衞、願爾得福、爾將大有作爲、而獲勝焉、大衞遂行、掃羅亦歸、"],[9,27,1,"大衞意謂、必有一日、我亡於掃羅手、不如遁入非利士地、掃羅則絕其望、不復索我於以色列境、我乃脫於其手、"],[9,27,2,"遂起、與從者六百人、往投迦特王瑪俄子亞吉、"],[9,27,3,"大衞與其二妻、耶斯列女亞希暖、及曾適拿八、迦密女亞比該、同僕從並眷聚、咸偕亞吉居於迦特、"],[9,27,4,"或以大衞逃於迦特告掃羅、掃羅不復索焉、○"],[9,27,5,"大衞謂亞吉曰、如沾爾恩、請以郊外之邑、賜我居處、何必偕王居京都乎、"],[9,27,6,"亞吉賜以洗革拉、故洗革拉屬猶大王、迄於今日、○"],[9,27,7,"大衞居非利士地、計一年有四月、"],[9,27,8,"大衞與其從者、往侵基述人、基色人、亞瑪力人、此族素居斯土、自書珥至埃及、"],[9,27,9,"大衞擊之、無論男女、不存其生、取牛羊驢駝及衣服、歸見亞吉、"],[9,27,10,"亞吉曰、今日所侵何地、曰、猶大南境、耶拉篾南境、基尼南境、"],[9,27,11,"大衞不生存男女、攜至迦特、蓋曰、恐其以我事告人云、大衞所爲如此、彼居非利士地、所爲常若是、"],[9,27,12,"亞吉信大衞、曰、彼使其民以色列深恨之、必永爲我僕、"],[9,28,1,"維時、非利士人集其軍旅、欲與以色列戰、亞吉謂大衞曰、爾知爾與從者、必在軍中、偕我而出、"],[9,28,2,"大衞曰、僕之所爲、爾必知之、亞吉曰、如是、我立爾爲侍衞、恆保我首、○"],[9,28,3,"撒母耳旣沒、以色列衆爲之哀悼、葬於故邑拉瑪、掃羅曾於國中、逐憑鬼者及巫覡、"],[9,28,4,"非利士人咸集、往書念建營、掃羅集以色列衆、建營於基利波、"],[9,28,5,"掃羅見非利士之軍旅、則懼、中心戰慄、"],[9,28,6,"詢於耶和華、耶和華不以夢與烏陵先知答之、"],[9,28,7,"掃羅謂其僕曰、爲我尋一女巫、我將就而問焉、僕曰、在隱多珥有女巫、"],[9,28,8,"掃羅改裝易服而往、二人偕之、夜至婦所、曰、請爾憑神、爲我卜筮、我所稱其名者、可招之上、"],[9,28,9,"婦曰、掃羅絕憑鬼者及巫覡於國中、彼之所爲、爾所知也、何設機檻、以害我命、致我於死乎、"],[9,28,10,"掃羅指耶和華而誓曰、我指維生之耶和華而誓、爾不因此受刑、"],[9,28,11,"婦曰、爲爾招誰上乎、曰、招撒母耳、"],[9,28,12,"婦見撒母耳、則大聲而呼、謂掃羅曰、何欺我耶、爾乃掃羅、"],[9,28,13,"王曰、勿畏、爾所見者何、婦曰、我見有神由地而出、"],[9,28,14,"曰、其狀若何、曰、有一老者、身衣禮服、掃羅知爲撒母耳、則伏地而拜、"],[9,28,15,"撒母耳謂掃羅曰、爾何擾我、使我上耶、掃羅曰、我甚窘急、非利士人將與我戰、上帝離我、不以先知與夢答我、故招爾至、示我以所當行、"],[9,28,16,"撒母耳曰、耶和華旣已離爾、爲爾之敵、曷問我哉、"],[9,28,17,"昔耶和華藉我所言、今行於爾、奪國於爾手、以畀爾鄰大衞、"],[9,28,18,"爾不聽耶和華命、成其烈怒於亞瑪力、故今日耶和華以此加諸爾、"],[9,28,19,"且將爾與以色列人、付於非利士人手、明日爾及爾子、必與我偕、以色列軍旅、亦付於非利士人手、"],[9,28,20,"掃羅聞撒母耳言、懼甚、身仆於地、因其永朝永夕、飲食俱廢、遂致無力、"],[9,28,21,"婦近掃羅、見其憂甚、謂之曰、婢聽王言、冒死不顧、遵諭而行、"],[9,28,22,"請納婢言、容以片餅陳於爾前、食之、則可得力、以便遄征、"],[9,28,23,"掃羅辭曰、我不食、僕與婦強之、乃允、起於地、坐於牀、"],[9,28,24,"婦家有肥犢、遂速宰之、取麪摶之、炊無酵餅、"],[9,28,25,"進於掃羅及其僕前、俱食之、是夜起而往、"],[9,29,1,"非利士人集其軍旅於亞弗、以色列人建營於耶斯列泉旁、"],[9,29,2,"非利士牧伯率軍、或百或千、向前而進、大衞與其從者偕亞吉、隨諸其後、"],[9,29,3,"非利士牧伯曰、此希伯來人何爲、亞吉曰、此非以色列王掃羅臣僕大衞乎、彼與我偕、有日有年、自投誠至今、未見其有過、"],[9,29,4,"牧伯怒亞吉曰、可使此人返爾所置之地、毋令偕我出戰、恐戰陳之間、反爲我敵、彼欲與其主和、何所需耶、非以我衆之首級乎、"],[9,29,5,"昔有人舞蹈唱和曰、掃羅殺其千千、大衞殺其萬萬、非此大衞乎、"],[9,29,6,"亞吉召大衞曰、我指維生之耶和華而誓、爾乃端正、偕我出入軍中、我視爲善、自爾來歸、未嘗見爾有惡、惟牧伯不愛爾、"],[9,29,7,"今當安然以歸、勿使牧伯不悅、"],[9,29,8,"大衞曰、我何所爲、自我從爾、至於今日、爾視爾僕有何事故、不容往攻我主我王之敵、"],[9,29,9,"亞吉曰、爾在我前爲善、如上帝之使然、此我所知、但牧伯謂爾不可偕我往戰、"],[9,29,10,"爾及爾主之僕、明晨夙興、及旦而去、"],[9,29,11,"翌日、大衞與從者夙興、歸非利士地、非利士人遂往耶斯列、"],[9,30,1,"越至三日、大衞與從者至洗革拉、亞瑪力人已侵南土、及洗革拉、且擊洗革拉而燬之、"],[9,30,2,"其中婦女、無少長、悉虜之、不殺一人、俱攜之去、"],[9,30,3,"大衞與從者至、見邑已燬、妻孥被虜、"],[9,30,4,"遂皆大聲而哭、至於力盡乃已、"],[9,30,5,"大衞二妻、耶斯列女亞希暖、及曾適迦密人拿八之亞比該、亦被虜、"],[9,30,6,"民爲子女、衷懷苦惱、相語以石擊大衞、大衞窘甚、然恃其上帝耶和華、而強厥志、○"],[9,30,7,"大衞謂祭司亞希米勒子亞比亞他曰、請攜聖衣至、亞比亞他遂攜之至、"],[9,30,8,"大衞詢於耶和華曰、若追其軍、可及之乎、曰、追之必及、而反所有、"],[9,30,9,"大衞與從者六百人、往至比梭溪、"],[9,30,10,"有二百人憊甚、不能渡、故留於彼、惟大衞與四百人往追、"],[9,30,11,"在田遇一埃及人、攜至大衞、給之以餅、飲之以水、"],[9,30,12,"又給以無花果餅一角、葡萄乾二穗、食之、精神乃復、蓋彼歷三晝夜、未嘗飲食、"],[9,30,13,"大衞曰、汝屬何人、奚自而來、曰、我乃埃及少者、爲亞瑪力人僕、三日前遘疾、見棄於主、"],[9,30,14,"我軍曾侵基利提南方、與猶大境、攻迦勒之南、且燬洗革拉、"],[9,30,15,"大衞曰、願導我至其軍乎、曰、爾指上帝以誓、必不殺我、不付我於主手、我則導爾至其軍、"],[9,30,16,"旣至、見亞瑪力人徧布於地、飲食舞蹈、因在非利士地、及猶大境、攘奪貨財甚多故也、"],[9,30,17,"大衞擊之、自黎明至次日之夕、除四百少者乘駝而遁外、無一得免者、"],[9,30,18,"大衞盡返亞瑪力人所掠之物、拯其二妻、"],[9,30,19,"無論少長子女、及所掠之物、大衞悉返之、未失其一、"],[9,30,20,"且奪敵之牛羊、驅於其前、曰、此大衞所獲也、"],[9,30,21,"大衞至二百人所、昔彼困憊、不能相從、留於比梭溪、今出迎大衞、與其從者、大衞前問其安、"],[9,30,22,"大衞從者中、有惡人匪徒曰、彼不偕我往、所獲之物勿與、第其妻孥、可攜而去、"],[9,30,23,"大衞曰、兄弟乎、耶和華旣輔翼我、以敵軍付於我手、其所賜之物、勿若是以行、"],[9,30,24,"所言之事、誰欲從之、臨陳與守物者、所得維均、"],[9,30,25,"是日大衞定此爲以色列之典章律例、至於今日、○"],[9,30,26,"大衞至洗革拉、由所獲之物中、取而饋其友朋猶大長老、曰、自耶和華敵所獲之物、奉爾爲禮、"],[9,30,27,"在伯特利、南土拉末、雅提珥、"],[9,30,28,"亞羅珥、息末、以實提莫、"],[9,30,29,"拉哈勒、耶拉篾諸邑、基尼諸邑、"],[9,30,30,"何珥瑪、歌拉珊、亞撻、"],[9,30,31,"希伯崙、及大衞與從者素所往來之地、俱有饋焉、"],[9,31,1,"非利士人與以色列人戰、以色列人遁、在基利波山、見殺而仆、"],[9,31,2,"非利士人急追掃羅及其子、殺其三子、約拿單、亞比拿達、麥基舒亞、"],[9,31,3,"掃羅被攻、戰勢劇烈、射者追及之、窘急特甚、"],[9,31,4,"謂執兵者曰、爾其拔劍刺我、免未受割者至、刺而侮我、執兵者懼甚、不敢奉命、掃羅遂伏劍而死、"],[9,31,5,"執兵者見掃羅死、亦伏劍偕死、"],[9,31,6,"是日掃羅與其三子、及執兵者、曁其僕從俱亡、"],[9,31,7,"居山谷相對之所、與約但河東之以色列人、見以色列人遁、掃羅及子皆死、遂棄邑而逃、非利士人至而居之、○"],[9,31,8,"翌日、非利士人來剝尸、見掃羅及三子、仆於基利波山、"],[9,31,9,"乃斬掃羅首、剝其鎧甲、遣使至非利士四境、傳於偶像之廟、以及民間、"],[9,31,10,"置其鎧甲於亞斯他錄廟、釘其尸於伯珊城垣、"],[9,31,11,"基列雅比居民、聞非利士人待掃羅之事、"],[9,31,12,"壯士咸起、竟夕而行、自伯珊城垣、取掃羅及其子之尸、攜至雅比焚之、"],[9,31,13,"取其骸骨、葬於雅比垂絲柳下、禁食七日、"],[10,1,1,"掃羅沒後、大衞戮亞瑪力人而歸、居洗革拉二日、"],[10,1,2,"越至三日、有人自掃羅營來、其衣撦裂、其首蒙塵、詣大衞、伏地而拜、"],[10,1,3,"大衞曰、爾奚自、曰、自以色列營、逃遁而至、"],[10,1,4,"大衞曰、其事若何、請以告我、曰、民自陳而遁、仆斃者衆、掃羅及其子約拿單亦死、"],[10,1,5,"大衞問來告之少者曰、掃羅及其子約拿單死、爾安知之、"],[10,1,6,"少者曰、吾偶於基利波山、見掃羅倚其槍、車騎追襲甚急、"],[10,1,7,"彼回顧見我、則呼我、我曰、我在此、"],[10,1,8,"曰、爾爲誰、曰、亞瑪力人也、"],[10,1,9,"曰、請立我側而殺我、因我昏眩、而命猶存、"],[10,1,10,"吾知彼旣傾覆、不能生活、遂立其側而殺之、取其首上之冕、臂上之釧、攜詣吾主、"],[10,1,11,"大衞遂裂己衣、從者亦然、"],[10,1,12,"爲掃羅及其子約拿單、與耶和華之民、以色列家、哀悼哭泣、禁食至暮、以其隕於刃也、"],[10,1,13,"大衞謂來告之少者曰、汝籍何處、曰、我乃亞瑪力旅人之子也、"],[10,1,14,"大衞曰、爾伸手殺耶和華之受膏者、何不懼乎、"],[10,1,15,"大衞召一少者曰、前攻之、遂擊斃之、"],[10,1,16,"大衞曰、爾血歸於爾首、爾口自證殺耶和華之受膏者、○"],[10,1,17,"大衞爲掃羅及其子約拿單、作哀歌而悼之、"],[10,1,18,"其歌名曰弓歌、命教猶大人、載於雅煞珥紀、"],[10,1,19,"歌曰、以色列歟、爾之榮光滅於崇邱、英武者其亡乎、"],[10,1,20,"毋告於迦特、毋播於亞實基倫衢、恐非利士女歡欣、未受割者之女奏凱、"],[10,1,21,"基利波山歟、願爾不霑雨露、無田可產祭品、蓋英武者之干見汚於彼、掃羅之干、如未受膏者之干然、"],[10,1,22,"飲見殺者之血、剖英武者之脂、約拿單之弓不卻退、掃羅之劍不徒返、"],[10,1,23,"掃羅及約拿單、生時相愛相悅、沒時亦弗相離、二人疾於鷹、強於獅、"],[10,1,24,"以色列女歟、爾其爲掃羅哀哭、彼曾慨然衣爾以絳衣、加金飾於爾服、"],[10,1,25,"英武者其隕於陳乎、約拿單見殺於爾之崇邱、"],[10,1,26,"吾兄約拿單歟、我爲爾悲傷、我悅爾殊甚、爾愛我之情奇異、深於愛婦女之情、"],[10,1,27,"英武者其隕乎、戰具其亡乎、"],[10,2,1,"厥後、大衞詢於耶和華曰、我往猶大之邑可否、耶和華曰、可、曰、當往何邑、曰、希伯崙、"],[10,2,2,"大衞遂往、其二妻、耶斯列女亞希暖、與曾適迦密人拿八之亞比該亦往、"],[10,2,3,"大衞率從者、及其眷聚咸至、居希伯崙諸邑、"],[10,2,4,"猶大人至、膏大衞爲猶大族王、○"],[10,2,5,"或告大衞曰、葬掃羅者、乃基列雅比人也、大衞遣使詣基列雅比人曰、爾厚待爾主掃羅而葬之、願耶和華錫嘏於爾、"],[10,2,6,"爾旣行此、願耶和華以仁慈誠實待爾、我亦報爾之恩、"],[10,2,7,"爾主掃羅旣沒、猶大族膏我爲其王、爾當強乃手而奮勇、○"],[10,2,8,"掃羅軍長尼珥子押尼珥、攜掃羅子伊施波設濟河、至瑪哈念、"],[10,2,9,"立之爲王、治基列、亞書利、耶斯列、以法蓮、便雅憫、及以色列衆、"],[10,2,10,"掃羅子伊施波設立爲以色列王、時年四十、在位二年、惟猶大族從大衞、"],[10,2,11,"大衞在希伯崙爲猶大族王、歷七年有六月、○"],[10,2,12,"尼珥子押尼珥、及掃羅子伊施波設之臣僕、出瑪哈念、至基遍、"],[10,2,13,"洗魯雅子約押、及大衞之臣僕亦出、相遇於基遍池側、一軍坐池左、一軍坐池右、"],[10,2,14,"押尼珥謂約押曰、任少者起而戲於我前、約押曰、可、"],[10,2,15,"遂起、各如其數而過、屬便雅憫、及掃羅子伊施波設者十二人、大衞之僕從十二人、"],[10,2,16,"互相執首、以刃刺脇、彼此偕仆、故其處稱曰希利甲哈素林、卽在基遍、"],[10,2,17,"是日戰勢劇烈、押尼珥與以色列人、敗於大衞之僕從前、"],[10,2,18,"有洗魯雅三子、約押、亞比篩、亞撒黑在彼、亞撒黑足疾如野鹿、"],[10,2,19,"追襲押尼珥、不偏於左、不偏於右、"],[10,2,20,"押尼珥回顧曰、汝爲亞撒黑乎、曰、是也、"],[10,2,21,"曰、爾其偏於左右、執一少者、奪其兵甲、惟亞撒黑仍追不舍、"],[10,2,22,"押尼珥曰、其偏之、不我追、奚使我擊爾仆地、若然、我何面目、與爾兄約押相見、"],[10,2,23,"惟彼弗偏、於是押尼珥以槍鐏刺其腹、自後而出、遂仆而死、凡至其死所者、皆止焉、"],[10,2,24,"約押及亞比篩追押尼珥、至基亞相對之亞瑪岡、在基遍野之道、時日入矣、"],[10,2,25,"便雅憫人咸集、從押尼珥、成爲一隊、立於岡巔、"],[10,2,26,"押尼珥呼約押曰、刃之吞人、永不已乎、豈不知終必有苦乎、民追兄弟、爾不止之、將至何時、"],[10,2,27,"約押曰、我指維生上帝而誓、如爾無言啟釁、則民清晨已返、不追兄弟、"],[10,2,28,"於是約押吹角、民衆乃止、不追以色列人、不復戰鬬、"],[10,2,29,"押尼珥及其從者、終夜而行、經亞拉巴、濟約但、越畢倫、至瑪哈念、○"],[10,2,30,"約押追押尼珥而歸、集其民衆、大衞僕從少十九人、及亞撒黑、"],[10,2,31,"便雅憫人及押尼珥之從者、爲大衞僕從所殺者、三百六十人、"],[10,2,32,"衆舁亞撒黑、葬於父墓、在伯利恆、約押及從者、終夜而行、至希伯崙、時適黎明、"],[10,3,1,"掃羅家與大衞家、相戰日久、大衞漸強、掃羅家漸弱、○"],[10,3,2,"大衞在希伯崙生子、長暗嫩、乃耶斯列女亞希暖所出、"],[10,3,3,"次基利押、乃曾適迦密人拿八之亞比該所出、三押沙龍、乃基述王達買女瑪迦之子、"],[10,3,4,"四亞多尼雅、乃哈及之子、五示法提雅、乃亞比他之子、"],[10,3,5,"六以特念、乃大衞妻以格拉所出、此皆大衞在希伯崙所生者、○"],[10,3,6,"掃羅家與大衞家相戰時、押尼珥在掃羅家自強、"],[10,3,7,"昔掃羅有妃利斯巴、愛亞之女也、伊施波設謂押尼珥曰、爾何與我父之妃同室、"],[10,3,8,"押尼珥聞言、怒甚、曰、我豈爲猶大之犬首乎、我厚待爾父掃羅家、及其兄弟友朋、不以爾付於大衞手、今日乃以此婦罪我、"],[10,3,9,"耶和華曾與大衞誓、我必爲大衞成其事、否則願上帝罰我維倍、"],[10,3,10,"我必奪國於掃羅家、立大衞之位、治以色列及猶大、自但至別是巴、"],[10,3,11,"伊施波設畏押尼珥、不答一詞、○"],[10,3,12,"押尼珥遣使見大衞曰、斯土屬誰乎、又曰、爾與我約、我手必助爾、使以色列衆悉歸爾、"],[10,3,13,"曰、善、我與爾約、惟索一事、爾來見時、必攜掃羅女米甲至、否則毋覿我面、"],[10,3,14,"大衞遣使見掃羅子伊施波設曰、以我妻米甲反我、卽昔我以非利士人之陽皮一百所聘者、"],[10,3,15,"伊施波設遣使、自其夫拉億子帕鐵取之、"],[10,3,16,"夫隨其後、且行且哭、偕至巴戶琳、押尼珥謂之曰、歸哉、乃歸、○"],[10,3,17,"押尼珥曾與以色列長老相議曰、昔爾求大衞爲爾王、"],[10,3,18,"今可行之、蓋耶和華論大衞曰、我必藉我僕大衞手、拯我民以色列、脫於非利士人、及諸敵之手、"],[10,3,19,"押尼珥亦與便雅憫人言之、遂往希伯崙、以以色列及便雅憫家所願者、告大衞、"],[10,3,20,"押尼珥與從者二十人、至希伯崙見大衞、大衞爲之設筵、"],[10,3,21,"押尼珥謂大衞曰、我將啟行、集以色列衆、歸我主我王、與爾立約、使爾隨心所欲而王、大衞遣押尼珥、遂安然而去、"],[10,3,22,"約押及大衞之臣僕、侵敵而歸、大獲貨財、時、押尼珥不與大衞共在希伯崙、已被遣安然而去、"],[10,3,23,"約押與其軍旅旣至、或告約押曰、尼珥子押尼珥來見王、而王遣之、彼安然而去矣、"],[10,3,24,"約押詣王曰、爾何所爲、押尼珥來見、奚爲遣之、而彼已去、"],[10,3,25,"爾知尼珥子押尼珥至此、乃欺爾也、欲窺爾之出入、與爾凡所爲耳、"],[10,3,26,"約押旣出、遂遣使追押尼珥、自西拉井攜之返、而大衞不知也、"],[10,3,27,"押尼珥返希伯崙、約押引至邑門、佯欲私語、刺其腹、致之死、以報流弟亞撒黑血之仇、"],[10,3,28,"大衞聞之、曰、流尼珥子押尼珥之血、我與我國、在耶和華前、永無罪辜、"],[10,3,29,"願歸約押之首、與其父全家、願約押家、或患白濁、或患癩疾、或扶杖而行、或隕沒於刃、或乏食、歷世不絕其人、"],[10,3,30,"約押及弟亞比篩戮押尼珥、因其於基遍戰場、殺其弟亞撒黑故也、○"],[10,3,31,"大衞命約押與相從之衆曰、裂衣束麻、哀悼於押尼珥前、大衞王隨柩而行、"],[10,3,32,"葬押尼珥於希伯崙、王於墓旁大聲而哭、民衆亦哭、"],[10,3,33,"王悼押尼珥曰、押尼珥之死、可如庸人之亡乎、"],[10,3,34,"爾手未縛、爾足未桎、爾之隕沒、猶人之亡於匪類也、民復哭之、"],[10,3,35,"日尚未入、民咸至、請大衞食餅、大衞誓曰、如日未入、而我食餅、或食他物、願上帝罰我維倍、"],[10,3,36,"民見此、則悅、凡王所爲、民皆悅之、"],[10,3,37,"當日以色列民衆、咸知殺尼珥子押尼珥、非由於王、"],[10,3,38,"王謂臣僕曰、汝豈不知今日在以色列中、爲牧伯爲大人者隕沒乎、"],[10,3,39,"我雖受膏爲王、今猶荏弱、此洗魯雅之子、逼我太甚、願耶和華依惡人之惡而報之、"],[10,4,1,"掃羅子伊施波設聞押尼珥死於希伯崙、則喪膽、以色列衆亦悚惶、"],[10,4,2,"掃羅子有隊長二人、一名巴拿、一名利甲、皆便雅憫族、比錄人臨門子也、蓋比錄屬便雅憫、"],[10,4,3,"昔比錄人遁於基他音、至今仍旅於彼、○"],[10,4,4,"掃羅子約拿單有一子名米非波設、跛者也、昔掃羅及約拿單之音耗、自耶斯列傳至時、子方五歲、媼抱之而遁、疾趨、子墜致跛、○"],[10,4,5,"一日比錄人臨門子利甲巴拿、於炎熱時、至伊施波設家、值其午寢、"],[10,4,6,"入室、佯欲取麥、"],[10,4,7,"見伊施波設偃臥於牀、則刺其腹而殺之、斬其首、取之而去、由亞拉巴道、終夜而行、"],[10,4,8,"攜伊施波設之首、至希伯崙、見大衞王曰、爾敵掃羅索爾命、試觀其子伊施波設之首在此、今日耶和華報我主我王之仇於掃羅、及其後裔、"],[10,4,9,"大衞謂之曰、我指贖我命脫諸難、維生之耶和華以誓、"],[10,4,10,"昔有人告我曰、掃羅已死、以爲報嘉音、我執而戮之於洗革拉、此我爲其報信音所加之賞也、"],[10,4,11,"況惡人入義者之室、殺之於牀、我豈不討其血於爾、絕爾於地乎、"],[10,4,12,"遂命少者戮之、斷其手足、懸於希伯崙池側、取伊施波設首、葬於希伯崙押尼珥之墓、"],[10,5,1,"以色列支派咸至希伯崙、見大衞曰、我乃爾之骨肉、"],[10,5,2,"昔掃羅爲我王時、爾率以色列人出入、耶和華謂爾曰、爾必爲我民以色列之牧、而作其君、"],[10,5,3,"以色列長老、咸至希伯崙見王、大衞王在希伯崙、於耶和華前與之立約、遂膏大衞爲以色列王、"],[10,5,4,"大衞卽位時、年三十、在位四十年、"],[10,5,5,"在希伯崙爲猶大王、歷七年有六月、在耶路撒冷爲以色列及猶大王、歷三十三年、○"],[10,5,6,"王及從者往耶路撒冷、攻斯土之耶布斯人、耶布斯人謂大衞曰、爾必不得入此、瞽者跛者必逐爾、意謂大衞不能入也、"],[10,5,7,"然大衞取錫安之保障、卽大衞城、"],[10,5,8,"當日大衞曰、擊耶布斯人者、其至水溝、擊大衞中心所惡之跛者瞽者、故成諺曰、有彼瞽者跛者、人不能入其室、"],[10,5,9,"大衞居其保障、名之曰大衞城、在米羅之內、四周築垣、"],[10,5,10,"大衞日漸昌大、萬軍之上帝耶和華偕之、○"],[10,5,11,"推羅王希蘭遣使見大衞、攜香柏及木工石工而至、爲大衞建宮室、"],[10,5,12,"大衞乃知耶和華立之爲以色列王、且爲其民以色列振興其國、○"],[10,5,13,"大衞至自希伯崙、在耶路撒冷又娶后妃、誕生子女、"],[10,5,14,"在耶路撒冷所生者、其名如左、沙母亞、朔罷、拿單、所羅門、"],[10,5,15,"益轄、以利書亞、尼斐、雅非亞、"],[10,5,16,"以利沙瑪、以利雅大、以利法列、○"],[10,5,17,"非利士人聞大衞受膏爲以色列王、咸至而索之、大衞聞之、乃入保障、"],[10,5,18,"非利士人旣至、布於利乏音谷、"],[10,5,19,"大衞詢於耶和華曰、我往攻非利士人可否、爾付之於我手乎、耶和華曰、往哉、我必付之於爾手、"],[10,5,20,"大衞遂至巴力毘拉心、擊之於彼、則曰、耶和華破敵於我前、如水之衝流然、故其名地曰巴力毘拉心、"],[10,5,21,"敵遺其偶像、大衞與從者取之、○"],[10,5,22,"非利士人復至、布於利乏音谷、"],[10,5,23,"大衞詢於耶和華、耶和華曰、毋往迎之、宜遶其後、於桑林相對之所攻之、"],[10,5,24,"聞桑杪有步履之聲、則急往、蓋耶和華先爾而行、擊非利士軍旅、"],[10,5,25,"大衞遵耶和華命、擊非利士人、自迦巴至基色、"],[10,6,1,"大衞又集以色列中所簡三萬人、"],[10,6,2,"起而率之至巴拉猶大、欲舁上帝之匱、此匱乃以居基路伯上、萬軍之耶和華名而名者、"],[10,6,3,"取上帝之匱、載於新車、自山中亞比拿達室而出、亞比拿達之子烏撒亞希約御車、"],[10,6,4,"載匱自亞比拿達室而出、亞希約行於匱前、"],[10,6,5,"大衞與以色列家、舞蹈於耶和華前、以松木樂器、及琴瑟鼓鈸鑼作樂、"],[10,6,6,"至拿艮禾場、牛蹶、烏撒伸手扶上帝匱、"],[10,6,7,"耶和華怒烏撒、因其過而擊之、遂死於上帝匱側、"],[10,6,8,"耶和華擊烏撒、大衞不悅、稱其地曰毘列斯烏撒、至於今日、"],[10,6,9,"是日大衞畏耶和華、曰、耶和華之匱、何可至我所、"],[10,6,10,"故大衞不舁耶和華匱入大衞城、至於己所、乃轉舁至迦特人俄別以東室、"],[10,6,11,"耶和華匱在迦特人俄別以東室三月、耶和華錫嘏於俄別以東、及其全家、"],[10,6,12,"或告大衞王曰、耶和華緣上帝之匱、錫嘏於俄別以東家、及凡所有、大衞遂往、懽然舁上帝匱、自俄別以東室、至大衞城、"],[10,6,13,"舁耶和華匱者旣行六步、大衞獻牛與肥犢各一、"],[10,6,14,"大衞衣枲聖衣、竭力舞蹈於耶和華前、"],[10,6,15,"大衞及以色列家歡呼吹角、舁耶和華匱而至、"],[10,6,16,"耶和華匱入大衞城時、掃羅女米甲自牖而窺、見大衞王踴躍舞蹈於耶和華前、中心鄙夷之、"],[10,6,17,"衆舁耶和華匱而入、置於其所、在大衞所張之幕、大衞獻燔祭及酬恩祭於耶和華、"],[10,6,18,"獻祭已畢、則以萬軍之耶和華名、爲民祝嘏、"],[10,6,19,"頒賜以色列衆、無論男女、各得餅一方、肉一臠、葡萄乾餅一方、民衆乃歸、○"],[10,6,20,"大衞歸、爲眷聚祝嘏、掃羅女米甲出迓曰、今日以色列王、何其榮哉、於臣僕之婢前露體、若鄙夫之無恥、"],[10,6,21,"大衞曰、我之爲此、乃在耶和華前、彼簡我超於爾父、及其全家、立我爲其民以色列之君、故我必舞蹈於其前、"],[10,6,22,"今必更爲鄙陋、自視卑賤、惟爾所言之婢、必尊崇我、"],[10,6,23,"掃羅女米甲至死無子、"],[10,7,1,"王居宮室、耶和華錫以綏安、得免四周諸敵之擾、"],[10,7,2,"王謂先知拿單曰、我居香柏之室、而上帝之匱乃在帳中、"],[10,7,3,"拿單曰、爾其從心所欲而行、蓋耶和華偕爾、"],[10,7,4,"是夜耶和華諭拿單曰、"],[10,7,5,"往告我僕大衞曰、耶和華云、爾爲我建室以居乎、"],[10,7,6,"我自導以色列族出埃及、至於今日、未嘗居室、乃行於帷幕中、"],[10,7,7,"凡我與以色列人偕行之地、豈曾語所命牧我民以色列支派之一者曰、曷不爲我建香柏之室乎、"],[10,7,8,"故當謂我僕大衞曰、萬軍之耶和華云、我自羊牢中、羊羣後、取爾爲我民以色列之君、"],[10,7,9,"爾之所往、我皆與偕、絕爾諸敵、將錫爾大名、如世間大人之名、"],[10,7,10,"我欲爲我民以色列定一區域、而栽植之、使居己所、不復遷移、不復遭惡類之窘迫、有如疇昔、"],[10,7,11,"及我命士師治我民以色列時、我必使爾安居、得免諸敵之擾、且耶和華告爾、耶和華必爲爾建立家室、"],[10,7,12,"迨爾之日已盈、與列祖偕眠、我必立爾所出之裔以嗣爾、鞏固其國、"],[10,7,13,"彼將爲我名建室、我必固其國位、歷久弗替、"],[10,7,14,"我將爲其父、彼將爲我子、彼若作惡、我必以人之杖、世人之鞭責之、"],[10,7,15,"惟我仁慈不離之、如昔奪之於掃羅、卽我爲爾所棄者、"],[10,7,16,"爾家爾國必堅立、爾位必堅定、至於永遠、"],[10,7,17,"拿單循此諸言、依此啟示、告大衞、○"],[10,7,18,"大衞王入坐於耶和華前、曰、主耶和華歟、我何人斯、我家若何、爾乃導我至此乎、"],[10,7,19,"主耶和華歟、此於爾目、猶以爲小、爾又言及爾僕之家、至於久遠、主耶和華歟、此豈世人所常有乎、"],[10,7,20,"主耶和華歟、大衞更有何辭、蓋爾洞悉爾僕、"],[10,7,21,"爾行此大事、乃踐爾言、循爾志、使僕知之、"],[10,7,22,"耶和華上帝歟、惟爾爲大、依我所聞、無可比擬、爾外無他上帝、"],[10,7,23,"地上何民、如爾民以色列、上帝親往贖之、以爲己民、而顯己名、且爲爾國、行大而可畏之事、驅逐列邦、及其諸神、於爾自埃及所贖之民前、"],[10,7,24,"爾立以色列民、永爲爾民、爾耶和華爲其上帝、"],[10,7,25,"耶和華上帝歟、爾論爾僕、與其家所言者、求爾堅固之、至於永遠、如言而行、"],[10,7,26,"願人永尊爾名爲大、曰、萬軍之耶和華、乃治以色列之上帝、爾僕大衞之家、必堅立於爾前、"],[10,7,27,"萬軍之耶和華、以色列之上帝歟、旣啟示爾僕曰、我必爲爾建立家室、故爾僕敢以此而求、"],[10,7,28,"主耶和華歟、爾乃上帝、所言眞實、以此福許爾僕、"],[10,7,29,"今願錫嘏於爾僕家、俾永存於爾前、主耶和華歟、爾旣言之、願爾僕家永享爾福、"],[10,8,1,"厥後、大衞擊非利士人服之、奪京都之權於其手、"],[10,8,2,"又擊摩押、使其人伏地、以繩量度、殺戮者二繩之長、生存者一繩有奇、摩押人遂服役於大衞、而納貢焉、"],[10,8,3,"瑣巴王利合子哈大底謝、往河欲恢復其權時、大衞擊之、"],[10,8,4,"虜其騎兵一千七百、步卒二萬、御車之馬、則斷其筋、惟存百乘之馬、"],[10,8,5,"大馬色之亞蘭人、來助瑣巴王哈大底謝、大衞擊殺其人二萬二千、"],[10,8,6,"大衞置戍於大馬色之亞蘭、亞蘭人遂服役於大衞、而納貢焉、大衞無論何往、耶和華使之獲勝、"],[10,8,7,"大衞奪哈大底謝臣僕之金盾、攜至耶路撒冷、"],[10,8,8,"又自屬哈大底謝之比他比羅他二邑、取銅甚多、"],[10,8,9,"哈大底謝屢與哈馬王陀以戰、陀以聞大衞擊敗哈大底謝全軍、遂遣子約蘭見大衞王問安、爲之祝嘏、約蘭攜金銀銅諸器、"],[10,8,10,"哈大底謝屢與哈馬王陀以戰、陀以聞大衞擊敗哈大底謝全軍、遂遣子約蘭見大衞王問安、爲之祝嘏、約蘭攜金銀銅諸器、"],[10,8,11,"大衞王區別此物、獻於耶和華、與曩昔所獻降國之金銀同、"],[10,8,12,"卽自亞蘭、摩押、亞捫、非利士、亞瑪力諸族、及瑣巴王利合子哈大底謝所獲之物、"],[10,8,13,"大衞於鹽谷、擊殺亞蘭人一萬八千而歸、得其名譽、"],[10,8,14,"置戍於以東全國、以東人咸服役於大衞、大衞無論何往、耶和華使之獲勝、○"],[10,8,15,"大衞爲以色列全族之王、爲其民衆施行公義、"],[10,8,16,"洗魯雅子約押爲軍長、亞希律子約沙法爲史官、"],[10,8,17,"亞希突子撒督、與亞比亞他子亞希米勒爲祭司、西萊雅爲繕寫、"],[10,8,18,"耶何耶大子比拿雅統轄基利提人、比利提人、大衞衆子爲相、"],[10,9,1,"大衞曰、掃羅家尚有遺存者乎、我緣約拿單故、將施仁慈於彼、"],[10,9,2,"掃羅家有僕名洗巴、或召之見大衞、王曰、爾洗巴乎、曰、僕是也、"],[10,9,3,"王曰、掃羅家尚有人乎、我以上帝之仁慈待之、洗巴曰、約拿單尚有一子、跛者也、"],[10,9,4,"王曰、彼何在、曰、在羅底巴亞米利子瑪吉家、"],[10,9,5,"大衞王遣人自羅底巴亞米利子瑪吉家、攜之而至、"],[10,9,6,"掃羅孫、約拿單子米非波設詣大衞、伏地而拜、大衞曰、米非波設歟、曰、爾僕在此、"],[10,9,7,"大衞曰、毋懼、我緣爾父約拿單故、必施仁慈於爾、以爾祖掃羅之田、悉反於爾、爾可恆食於我席、"],[10,9,8,"米非波設拜曰、僕何人斯、若此死犬、而得爾之眷顧乎、"],[10,9,9,"王呼掃羅僕洗巴曰、凡屬掃羅及其家者、我已咸賜爾主之子、"],[10,9,10,"爾與爾子爾僕、必爲之耕田、納其所產、使爾主之子有糧可食、惟爾主之子米非波設、必恆食於我席、洗巴有子十五人、僕二十人、"],[10,9,11,"洗巴謂王曰、我主我王所命、爾僕必悉行之、米非波設乃食於王席、與王子同、"],[10,9,12,"米非波設有幼子名米迦、凡居洗巴家者、皆爲米非波設之僕、"],[10,9,13,"米非波設居耶路撒冷、恆食於王席、二足俱跛、"],[10,10,1,"厥後、亞捫族王沒、其子哈嫩嗣位、"],[10,10,2,"大衞曰、昔哈嫩父拿轄施仁慈於我、今我將施仁慈於其子哈嫩、遂遣僕往、唁其喪父、大衞僕至亞捫族地、"],[10,10,3,"亞捫族之牧伯謂其主哈嫩曰、大衞遣唁者詣爾、爾意大衞果敬爾父乎、大衞遣僕詣爾、詎非窺察此城、而傾之耶、"],[10,10,4,"哈嫩遂執大衞僕、薙其鬚之半、中斷其衣至臀、而遣之歸、"],[10,10,5,"其人深以爲恥、或以告大衞、乃遣人迎之曰、可居耶利哥、俟鬚長而後歸、○"],[10,10,6,"亞捫族知己爲大衞所惡、遂遣人募伯利合與瑣巴之亞蘭人、步卒二萬、及瑪迦王所偕之人一千、陀伯人一萬二千、"],[10,10,7,"大衞聞之、則遣約押率勇士全軍、"],[10,10,8,"亞捫族出、列陳於邑門、瑣巴利合之亞蘭人、及陀伯人、瑪迦人、別列於野、"],[10,10,9,"約押見其前後列陳、則簡以色列之精兵、陳列行伍、以禦亞蘭人、"],[10,10,10,"以餘軍付弟亞比篩、陳列行伍、以禦亞捫族、"],[10,10,11,"曰、如亞蘭人強於我、爾則助我、如亞捫人強於爾、我則助爾、"],[10,10,12,"宜強乃志、爾我當爲我民、及我上帝邑、爲大丈夫、願耶和華成其所欲、"],[10,10,13,"約押與所偕之民、進與亞蘭人戰、亞蘭人遁於其前、"],[10,10,14,"亞捫族見亞蘭人遁、亦遁於亞比篩前、而入於邑、約押遂離亞捫族、返耶路撒冷、○"],[10,10,15,"亞蘭人見己爲以色列所敗、則咸集焉、"],[10,10,16,"哈大底謝遣使招河外之亞蘭人出、遂至希蘭、哈大底謝之軍長朔法率之、"],[10,10,17,"或告大衞、遂集以色列衆、濟約但、至希蘭、亞蘭人列陳、與大衞戰、"],[10,10,18,"亞蘭人遁於以色列衆前、大衞戮其戰車七百乘之卒、騎兵四萬、擊其軍長朔法、致死於彼、"],[10,10,19,"臣服哈大底謝之諸王、見其爲以色列所敗、遂與以色列修好、而服事之、嗣後亞蘭人不敢助亞捫族、"],[10,11,1,"歲初、列王出戰時、大衞遣約押偕其臣僕、及以色列衆出、遂敗亞捫族、圍拉巴、大衞居於耶路撒冷、○"],[10,11,2,"日夕大衞自牀起、遊行於宮巔、見一婦沐浴、貌甚美、"],[10,11,3,"大衞遣人問婦爲誰、或曰、非以連女、赫人烏利亞妻拔示巴乎、"],[10,11,4,"大衞遣使取之、旣至、濯其不潔、大衞與之同寢、婦乃歸、"],[10,11,5,"婦懷姙、遣人告大衞曰、我懷姙矣、"],[10,11,6,"大衞遣人諭約押曰、遣赫人烏利亞見我、約押遂遣之入覲、"],[10,11,7,"烏利亞旣至、大衞問約押若何、民衆之況若何、戰事之效若何、"],[10,11,8,"又謂烏利亞曰、爾其歸家濯足、烏利亞出王宮、王賜饌隨其後、"],[10,11,9,"惟烏利亞寢於宮門、與其主之僕偕、不歸私第、"],[10,11,10,"或告大衞曰、烏利亞未歸其第、大衞謂烏利亞曰、爾非自遄征而至乎、奚不歸第、"],[10,11,11,"烏利亞曰、匱及以色列猶大族、咸居柴柵、我主約押與我主之僕、屯於田野、我豈可歸第飲食、與妻偕寢乎、我指爾及爾生命以誓、我決不爲此、"],[10,11,12,"大衞曰、今日仍居於此、明日我遣爾往、烏利亞是日居耶路撒冷、"],[10,11,13,"翌日、大衞召之、乃飲食於其前、大衞使之醉、至夕而出、仍寢於牀、與其主之僕偕、不歸其第、"],[10,11,14,"詰朝、大衞致書約押、付於烏利亞手以達、"],[10,11,15,"書曰、可置烏利亞於前茅、劇戰之處、爾衆則退、俾其被擊而死、"],[10,11,16,"約押窺城、知敵勇士所在、則委烏利亞於彼、"],[10,11,17,"邑人出、與約押戰、大衞之僕、沒者數人、赫人烏利亞亦死、"],[10,11,18,"約押遣人以戰事告大衞、"],[10,11,19,"囑使者曰、爾以戰事告王旣畢、"],[10,11,20,"如王怒曰、爾何迫城以戰、豈不知敵必自城而射乎、"],[10,11,21,"耶路比設子亞比米勒爲誰所擊、非婦自城擲磨石於其身、而彼死於提備斯乎、爾傅於城何耶、則曰、爾僕赫人烏利亞亦死、"],[10,11,22,"使者遂行、見大衞、以約押所命告之、"],[10,11,23,"曰、敵勝於我、出而逆我於野、我追襲之、逼近城門、"],[10,11,24,"射者自城射爾僕、王之僕中、數人隕亡、爾僕赫人烏利亞亦死、"],[10,11,25,"大衞謂使者曰、爾其語約押曰、毋以此爲憂、刃之吞人、或彼或此、當益奮厥力、攻城而毀之、以此勉勵約押、"],[10,11,26,"烏利亞妻聞夫烏利亞死、爲之哀哭、"],[10,11,27,"喪事旣畢、大衞召之入宮、遂爲其妻、因而生子、然大衞所爲、耶和華不悅之、"],[10,12,1,"耶和華遣拿單見大衞、遂詣之、曰、有二人居於一邑、一富一貧、"],[10,12,2,"富者牛羊甚多、"],[10,12,3,"貧者無所有、惟一小牝羔、乃彼所購而養者、與彼及子同長、食其食、飲其杯、臥於其懷、視若己女、"],[10,12,4,"有旅人詣富者、富者惜其牛羊、不以供客、乃取貧者之羔、備而供之、"],[10,12,5,"大衞甚怒其人、謂拿單曰、我指維生之耶和華以誓、行此者宜死、"],[10,12,6,"必償其羔四倍、緣彼行此事、無憐憫也、○"],[10,12,7,"拿單謂大衞曰、爾卽其人也、以色列之上帝耶和華云、我膏爾爲以色列王、援爾於掃羅手、"],[10,12,8,"以爾主之家業賜爾、以爾主之妻室付於爾懷、以以色列及猶大家畀爾、若以爲寡、我必有以加之、"],[10,12,9,"爾何藐視耶和華命、行其所惡、藉亞捫族之刃、擊殺赫人烏利亞、而取其妻爲妻、"],[10,12,10,"爾旣藐視我、而取赫人烏利亞妻爲妻、故兵刃永不離爾家、"],[10,12,11,"耶和華又曰、我必肇禍於爾家、加諸爾身、以爾妻室付於他人、爲爾目擊、彼於日光之下、與之同寢、"],[10,12,12,"爾行之於隱、我則行之於日光之下、爲以色列衆目擊、"],[10,12,13,"大衞謂拿單曰、我獲罪於耶和華矣、拿單曰、耶和華已宥爾罪、不致死亡、"],[10,12,14,"然爾行此、使耶和華之敵得毀謗之由、故爾所生之子必死、"],[10,12,15,"拿單乃歸、耶和華擊烏利亞妻爲大衞所生之子、使之疾甚、"],[10,12,16,"大衞爲子祈禱上帝、禁食、入室終夜伏地、"],[10,12,17,"家之老者侍側、欲自地起之、大衞不從、亦不偕食、"],[10,12,18,"越至七日、子死、大衞之僕不敢以子死告之、蓋曰、子尚生時、我與之言、彼不之聽、若以子死相告、其憂傷將何如乎、"],[10,12,19,"大衞見僕切切私語、知子已死、問僕曰、子死乎、曰、死矣、"],[10,12,20,"大衞自地而起、沐浴、膏身、更衣、入耶和華室而崇拜、回宮命具饌、則設席而食、"],[10,12,21,"僕曰、爾所爲者何耶、子尚生時、爾爲之禁食哭泣、子死、乃起而食、"],[10,12,22,"曰、子尚生時、我之禁食哭泣、蓋曰、耶和華或施恩於我、俾子生存、未可知也、"],[10,12,23,"今子已死、禁食何爲、豈能使之返乎、我必往彼所、彼不返於我、"],[10,12,24,"大衞慰其妻拔示巴、入而與之同寢、婦乃生子、命名所羅門、耶和華愛之、"],[10,12,25,"藉先知拿單名子曰耶底底亞、緣耶和華之故也、○"],[10,12,26,"約押攻亞捫族之拉巴、取其王城、"],[10,12,27,"遣使見大衞曰、我攻拉巴、取其水城、"],[10,12,28,"今爾可集餘民、建營攻而取之、免爲我取、人以我名名之、"],[10,12,29,"大衞乃集民衆往拉巴、攻而取之、"],[10,12,30,"奪其王首之冕、其金重一他連得、飾以寶石、置於大衞首、又自邑中、攜出貨財甚多、"],[10,12,31,"且出其邑民、使之服役於鋸、及鐵耙與鐵斧、或服役於瓦窰、大衞待亞捫族諸邑、皆若是、大衞率民衆歸耶路撒冷、"],[10,13,1,"大衞子押沙龍有妹貌美、名曰他瑪、大衞子暗嫩愛之、"],[10,13,2,"暗嫩爲其妹他瑪、抑鬱成疾、他瑪乃處子、暗嫩自知難與之近、"],[10,13,3,"暗嫩有友名約拿達、乃大衞兄示米亞子、爲人甚狡、"],[10,13,4,"謂暗嫩曰、王子歟、爾日益瘠瘦、曷故、爾不告我乎、暗嫩曰、我愛弟押沙龍之妹他瑪、"],[10,13,5,"約拿達曰、可臥於牀、佯爲遘疾、父來視爾、則謂之曰、請容我妹他瑪至此、以食與我、備於我前、使我見之、我由其手受而食之、"],[10,13,6,"暗嫩遂臥、佯爲遘疾、王來視之、暗嫩曰、請容我妹他瑪、來作二餅於我前、我由其手受而食之、"],[10,13,7,"大衞遣人入內諭他瑪曰、往爾兄暗嫩室、爲之備饌、"],[10,13,8,"他瑪往其兄暗嫩室、見暗嫩偃臥、遂取溼麪摶於其前、作餅炊之、"],[10,13,9,"以釜傾於其前、暗嫩不食、曰、屛衆、遂咸出、"],[10,13,10,"暗嫩謂他瑪曰、攜餅入內室、我由爾手受而食之、他瑪取所作之餅、攜入內室、至其兄暗嫩、"],[10,13,11,"進而食之、暗嫩執之、曰、我妹與我同寢、"],[10,13,12,"曰、我兄不可、毋玷辱我、在以色列中不可行此、毋爲此愚妄之事、"],[10,13,13,"我負斯辱、將焉往、爾在以色列中、必如愚妄人矣、祈言於王、必不禁我歸爾、"],[10,13,14,"暗嫩不聽其言、因強於彼、強與同寢、"],[10,13,15,"厥後、暗嫩憾之極甚、其憾之之情、較愛之之情更切、遂謂之曰、起、往哉、"],[10,13,16,"他瑪曰、不可、爾遣我去、較前所行、其咎尤重、暗嫩不聽、"],[10,13,17,"呼侍立之僕曰、驅此女出、從而上楗、"],[10,13,18,"時、他瑪衣彩衣、循王女處室之制也、僕攜之出、從而上楗、"],[10,13,19,"他瑪裂其彩衣、蒙灰於首、按手其上、且行且哭、"],[10,13,20,"其兄押沙龍謂之曰、爾兄暗嫩與爾偕乎、我妹今且緘默、彼乃爾兄、勿以爲意、於是他瑪在兄押沙龍家獨處、"],[10,13,21,"大衞王聞之、怒甚、"],[10,13,22,"押沙龍因暗嫩強玷其妹他瑪、憾之、善惡之言、俱不與語、○"],[10,13,23,"越二年、有人爲押沙龍剪羊毛在近以法蓮之巴力夏瑣、押沙龍邀王衆子、"],[10,13,24,"乃覲王曰、有人爲僕剪羊毛、請王及臣僕、與爾僕偕往、"],[10,13,25,"王曰、吾子、我儕無庸俱往、恐累爾、押沙龍固請之、亦不往、第爲祝嘏、"],[10,13,26,"押沙龍曰、如爾不往、則請許兄暗嫩偕往、王曰、彼偕爾往、曷故、"],[10,13,27,"押沙龍固請之、乃使暗嫩及王衆子偕往、"],[10,13,28,"押沙龍命其僕曰、當伺暗嫩飲酒快心、我諭爾曰擊暗嫩、則殺之毋畏、命爾者非我乎、當壯膽而奮勇、"],[10,13,29,"僕循押沙龍命、以處暗嫩、王子咸起、各乘其驢而遁、"],[10,13,30,"尚在途間、有音耗傳於大衞曰、王子盡爲押沙龍所殺、靡有孑遺、"],[10,13,31,"王遂起、裂衣仆地、臣僕裂衣侍立、"],[10,13,32,"大衞兄示米亞子約拿達曰、我主、毋以爲少者王子悉見殺、死者惟暗嫩一人耳、自彼強玷其妹之日、此事押沙龍已定之、"],[10,13,33,"我主我王毋懷憂、以爲王子皆死、死者惟暗嫩一人耳、"],[10,13,34,"押沙龍遁、守望之少者舉目以觀、見後有多人、由山麓之途而至、"],[10,13,35,"約拿達謂王曰、王子至矣、如僕所言、"],[10,13,36,"言甫畢、王子至、發聲而哭、王與臣僕亦哭、慟甚、○"],[10,13,37,"押沙龍遁於基述王亞米忽子達買所、大衞日爲其子悲哀、"],[10,13,38,"押沙龍遁於基述、居彼三年、"],[10,13,39,"大衞王見暗嫩旣死、乃得慰藉、而想念押沙龍殊切、"],[10,14,1,"洗魯雅子約押、知王中心嚮往押沙龍、"],[10,14,2,"乃遣人往提哥亞、攜哲婦至、謂之曰、爾其佯爲居喪者、身衣喪服、勿沐以膏、若爲死者久哀之婦、"],[10,14,3,"入見王、與之言、遂以言授之、"],[10,14,4,"提哥亞婦與王言時、伏地拜曰、王歟、助我、"],[10,14,5,"王曰、爾有何事、曰、我乃嫠婦、我夫已死、"],[10,14,6,"婢有二子、在田相鬬、排解無人、此擊彼而斃之、"],[10,14,7,"今舉家起而攻婢曰、擊昆弟者、當付於我、而致之死、以償所殺昆弟之命、而絕其嗣、如是、則滅我餘燼、不爲我夫留名與後於世、"],[10,14,8,"王曰、爾歸、我將爲爾下令、"],[10,14,9,"提哥亞婦曰、我主我王歟、罪歸於我、及我父家、王與國位、均無尤焉、"],[10,14,10,"王曰、凡咎爾者、攜至我前、彼必不復犯爾、"],[10,14,11,"婦曰、請王念爾上帝耶和華、不許報仇者復加殺害、免滅吾子、曰、我指維生之耶和華而誓、爾子之一髮、不隕於地、"],[10,14,12,"婦曰、祈我主我王、容婦復進一詞、曰、其言之、"],[10,14,13,"婦曰、胡爲謀害上帝之民、王出此言、似有差失、因不令亡人旋歸也、"],[10,14,14,"吾儕必死、如水傾地、不能復收、上帝不奪人命、乃設法俾亡者得免驅逐、"],[10,14,15,"我以此言告我主我王、乃因民使我恐懼、故曰、我必與王言之、庶幾王允婢之所求、"],[10,14,16,"人欲滅我及子、俾絕於上帝之業、王必俞允、援婢脫於其手、"],[10,14,17,"婢則曰、願我主我王之言慰我、蓋我主我王之辨是非、如上帝之使、願爾上帝耶和華偕爾、"],[10,14,18,"王曰、我所問於爾者、願爾無隱、婦曰、請我主我王言之、"],[10,14,19,"王曰、此事非約押與爾同謀乎、婦曰、我主我王歟、我指爾生命以誓、我主我王所言、無人能左右轉移之、蓋爾僕約押命我、以此言授婢、"],[10,14,20,"爾僕約押爲此、欲使事勢變遷、我主聰睿、如上帝之使、洞悉世事、○"],[10,14,21,"王謂約押曰、我允此事、爾往、攜少者押沙龍以歸、"],[10,14,22,"約押伏地而拜、爲王祝嘏、曰、我主我王允僕所求、今日我知沾恩於爾前、"],[10,14,23,"約押遂起、往基述、攜押沙龍至耶路撒冷、"],[10,14,24,"王曰、使歸私第、毋覿我面、押沙龍遂歸、不見王面、○"],[10,14,25,"押沙龍丰采甚都、見譽於衆、遍以色列、無能比擬、自踵至頂、無有瑕疵、"],[10,14,26,"因髮甚重、每歲剪之、循王權衡計之、得二百舍客勒、"],[10,14,27,"押沙龍生三子一女、女名他瑪、美貌女也、○"],[10,14,28,"押沙龍居耶路撒冷二年、未見王面、"],[10,14,29,"乃召約押、欲遣之見王、約押不至、再召之、仍不至、"],[10,14,30,"遂謂僕曰、約押之田、與我接壤、中有麰麥、爾往焚之、僕遂縱火於田、"],[10,14,31,"約押起、至押沙龍室、謂之曰、爾僕奚縱火於吾田、"],[10,14,32,"押沙龍曰、我遣人召爾至此、欲使爾覲王曰、吾自基述而歸何爲、不如仍居於彼、今請許我覿王面、如我有咎、王可殺我、"],[10,14,33,"約押入覲、以此告王、王乃召之、押沙龍入覲、伏地拜於王前、王與接吻、"],[10,15,1,"此後、押沙龍備車馬與五十人、奔走於前、"],[10,15,2,"夙興、立於邑門途側、見有訟事宜受王鞫者、則呼之曰、爾屬何邑、曰、僕屬以色列某支派、"],[10,15,3,"押沙龍曰、爾事善且正、然王未嘗委人聽之、"],[10,15,4,"又曰、我深願立爲士師於斯土、凡有爭端訟事、咸詣我所、我必爲之公斷、"],[10,15,5,"或有近而拜之者、押沙龍伸手執之、而與接吻、"],[10,15,6,"凡以色列人欲詣王以訟者、押沙龍待之若此、因而陰得以色列人之心、○"],[10,15,7,"越四年、押沙龍謂王曰、我曾許願於耶和華、請允我往希伯崙以酬之、"],[10,15,8,"蓋爾僕居亞蘭之基述、嘗許願曰、如耶和華使我歸耶路撒冷、我必崇事之、"],[10,15,9,"王曰、安然而去、遂起而往希伯崙、"],[10,15,10,"押沙龍遣諜、徧行以色列衆支派曰、一聞角聲、則當言曰、押沙龍在希伯崙爲王矣、"],[10,15,11,"押沙龍自耶路撒冷、招二百人偕行、其人樸誠、不知其事、"],[10,15,12,"大衞之謀士亞希多弗、基羅人也、押沙龍獻祭時、遣人召之、自其本邑基羅而來、叛黨勢強、民歸押沙龍者日衆、○"],[10,15,13,"有使者來告大衞曰、以色列人之心、咸歸押沙龍矣、"],[10,15,14,"大衞謂在耶路撒冷相偕之僕曰、當起而遁、否則不得避押沙龍、其速往哉、恐其猝至、加害我儕、刃擊邑民、"],[10,15,15,"王之僕謂王曰、我主我王所欲、僕願行之、"],[10,15,16,"王出、眷屬隨之、留妃十人、以守宮闈、"],[10,15,17,"王出、民衆相從、止於伯墨哈、"],[10,15,18,"衆僕與基利提人、比利提人、及自迦特從王而至者六百人、過於王前、"],[10,15,19,"王謂迦特人以太曰、爾與吾儕偕往何爲、可返與王同居、爾爲異族、出亡在外、或歸故土、"],[10,15,20,"爾來爲日無幾、今我觀勢而往、安忍使爾偕我流離、可攜爾昆弟而歸、願恩寵誠實臨爾、"],[10,15,21,"以太曰、我指維生之耶和華、及我主我王之生命而誓、我主我王所在、僕必與偕、死生以之、"],[10,15,22,"大衞曰、往哉、其濟諸、迦特人以太與其從者、及其幼稚同濟、"],[10,15,23,"斯土之人、大聲而哭、民濟汲淪溪、王亦濟、衆望曠野之路而行、"],[10,15,24,"撒督亦至、衆利未人從之、舁上帝匱、置之於彼、亞比亞他登山、待民出邑、"],[10,15,25,"王謂撒督曰、舁上帝匱返城、若我蒙恩於耶和華前、必使我反、見匱及其居所、"],[10,15,26,"如云我不悅爾、願任其所欲而待我、"],[10,15,27,"又謂祭司撒督曰、爾非先見乎、爾與爾子亞希瑪斯、及亞比亞他子約拿單、安然歸邑、"],[10,15,28,"我將留於曠野之津、待爾有言告我、"],[10,15,29,"撒督與亞比亞他、遂舁上帝之匱、歸耶路撒冷居焉、○"],[10,15,30,"大衞蒙首跣足、陟橄欖山、且陟且哭、所偕之衆、亦皆蒙首而陟、且陟且哭、"],[10,15,31,"或告大衞曰、亞希多弗從押沙龍、在叛黨之中、大衞曰、耶和華歟、求爾使亞希多弗之謀、變爲愚昧、"],[10,15,32,"大衞旣至山巔、崇拜上帝之所、有亞基人戶篩、自裂其衣、以塵蒙首來迎、"],[10,15,33,"大衞謂之曰、爾偕我往、適以累我、"],[10,15,34,"若歸邑語押沙龍曰、王歟、我欲爲爾僕、昔爲爾父之僕、今亦如是爲爾僕、則必爲我敗亞希多弗之謀、"],[10,15,35,"祭司撒督及亞比亞他、非偕爾在彼乎、爾於王室有所聞、當告之、"],[10,15,36,"撒督子亞希瑪斯、亞比亞他子約拿單、二子亦與之偕、凡有所聞、遣之告我、"],[10,15,37,"大衞之友戶篩遂入城、押沙龍亦至耶路撒冷、"],[10,16,1,"大衞過山巔未遠、米非波設僕洗巴來迎、攜備鞍之驢二、載餅二百、葡萄乾一百穗、夏果一百、酒一革囊、"],[10,16,2,"王曰、汝攜此何意、洗巴曰、驢爲王眷聚所乘、餅及夏果爲少者所食、酒爲曠野困憊者所飲、"],[10,16,3,"王曰、爾主之子安在、曰、在耶路撒冷、蓋曰、今日以色列家、必以父之國反我、"],[10,16,4,"王曰、米非波設所有者、咸歸於爾、洗巴曰、我跪拜、願蒙恩於我主我王之前、○"],[10,16,5,"大衞王至巴戶琳、有掃羅族、基拉子名示每者出、且行且詛、"],[10,16,6,"以石擲大衞、及其臣僕、時、民庶勇士在王左右、"],[10,16,7,"示每詛曰、往哉、往哉、爾流血之人、鄙陋之徒也、"],[10,16,8,"爾代掃羅爲王、今耶和華將掃羅家之血、悉歸於爾、以此國付於爾子押沙龍、爾流血之人、自取其禍也、"],[10,16,9,"洗魯雅子亞比篩謂王曰、此死犬胡爲詛我主我王、求爾允我往斬其首、"],[10,16,10,"王曰、洗魯雅子、我與爾何與、彼詛大衞、因耶和華命其詛之、孰敢言胡爲行此乎、"],[10,16,11,"又謂亞比篩及諸臣僕曰、我子己身所出、尚索我命、況此便雅憫人乎、姑容之、聽其詛、蓋耶和華命之矣、"],[10,16,12,"庶幾耶和華鑒我之寃、緣其今日之詛、報我以善、"],[10,16,13,"大衞及從者行於道、示每行於相對之阪、且行且詛、擲石揚塵、"],[10,16,14,"王及從者困憊、至一處養其精力、○"],[10,16,15,"押沙龍與以色列衆至耶路撒冷、亞希多弗偕之、"],[10,16,16,"大衞友亞基人戶篩詣押沙龍、曰、願王萬歲、願王萬歲、"],[10,16,17,"押沙龍曰、爾愛友之情如是乎、何不與友偕行乎、"],[10,16,18,"戶篩曰、不然、惟耶和華與斯民、及以色列衆所選者、我必歸之、而與之俱、"],[10,16,19,"且我宜事者爲誰、非王之子乎、昔我若何事爾父、今亦如是事爾、"],[10,16,20,"押沙龍謂亞希多弗曰、我儕當若何而行、爾其謀之、"],[10,16,21,"亞希多弗曰、爾父留妃以守宮闈、爾入其中、以色列衆聞爾爲父所憾、則從爾者、皆強厥手矣、"],[10,16,22,"於是爲押沙龍張幕宮巔、押沙龍遂入御父妃、以色列人目覩之、"],[10,16,23,"當日亞希多弗所設之謀、如諮諏於上帝、爲大衞、爲押沙龍、皆如是、"],[10,17,1,"亞希多弗謂押沙龍曰、許我簡卒一萬二千、今夜啟行、追襲大衞、"],[10,17,2,"乘其困憊手弱臨之、使之驚惶、侍從必遁、而我獨擊其王、"],[10,17,3,"俾衆悉歸於爾、得爾所索之人、則如衆返、而民安焉、"],[10,17,4,"押沙龍及以色列長老、皆悅此言、"],[10,17,5,"押沙龍曰、召亞基人、戶篩至、俾得與聞其言、"],[10,17,6,"戶篩旣至、押沙龍曰、亞希多弗所言若此、可從之乎、否則爾言之、"],[10,17,7,"戶篩曰、亞希多弗此次之謀不嘉、"],[10,17,8,"又曰、爾父與其侍從、乃爲英武、爾所知也、今其衷懷暴怒、如熊在野、而亡其子、爾父又嫻戰事、必不宿於民中、"],[10,17,9,"今必藏於坑坎、或在他所、如爾從者數人先仆、聞者必曰、從押沙龍者見戮、"],[10,17,10,"則人雖驍勇、心猛如獅、必喪厥膽、蓋以色列族咸知爾父英武、從者亦驍勇、"],[10,17,11,"我之謀議、悉集以色列衆、自但至別是巴、如海沙之多、爾親出戰、"],[10,17,12,"於其所在、倏然臨之、如露降於土壤、使彼及其侍從、靡有孑遺、"],[10,17,13,"彼若入城、以色列衆必攜繩至、曳城入河、卷石不遺、"],[10,17,14,"押沙龍及以色列衆曰、亞基人戶篩之謀、較亞希多弗之謀尤善、蓋耶和華預定敗亞希多弗之謀、以禍押沙龍、○"],[10,17,15,"戶篩謂祭司撒督亞比亞他曰、亞希多弗爲押沙龍、及以色列長老、所謀如此、我所謀如此、"],[10,17,16,"宜急遣人告大衞曰、今夜勿宿曠野之津、必濟河、免王與侍從、俱見吞噬、"],[10,17,17,"時、約拿單亞希瑪斯待於隱羅結、因不可入城、爲人所見、有婢數來告之、則往轉告大衞王、"],[10,17,18,"有孺子見之、以告押沙龍、二人遂急去、至巴戶琳人家、其院有井、二人下焉、"],[10,17,19,"婦以蓋掩井口、布麥屑於上、而事不洩、"],[10,17,20,"押沙龍僕至其家、問婦曰、亞希瑪斯約拿單安在、婦曰、已濟溪矣、索之不得、乃歸耶路撒冷、"],[10,17,21,"去後、二人自井出、往告大衞王曰、亞希多弗設謀害爾、宜起、速濟河、"],[10,17,22,"大衞與僕從遂起、濟約但、及黎明、民衆悉濟、不遺一人、"],[10,17,23,"亞希多弗見其所謀不從、卽備驢反故邑、歸私第、處置家事、自縊而死、葬於父墓、○"],[10,17,24,"大衞至瑪哈念、押沙龍及以色列衆濟約但、"],[10,17,25,"押沙龍立亞瑪撒爲軍長、以代約押、其人乃以實瑪利人以特拉、與拿轄女亞比該同室而生者、亞比該與約押母洗魯雅爲姊妹、"],[10,17,26,"押沙龍與以色列衆、建營於基列地、○"],[10,17,27,"大衞旣至瑪哈念、亞捫族拉巴人拿轄子朔比、與羅底巴人亞米利子瑪吉、曁基列之羅基琳人巴西萊咸至、"],[10,17,28,"攜牀盆瓦器、小麥、麰麥、細麪、烘穀、大豆、小豆、烘豆、"],[10,17,29,"蜜酥與羊、牛酪之餅、以供大衞、及其侍從、蓋曰、民在曠野、飢渴困憊、"],[10,18,1,"大衞核其所偕之民、立千夫長、百夫長以率之、"],[10,18,2,"大衞遣民出戰、分之爲三、以一委約押、以一委洗魯雅子、約押弟亞比篩、以一委迦特人以太、王曰、我亦必與爾偕往、"],[10,18,3,"民曰、爾不可往、如我逃遁、敵不以我爲意、死亡者半、敵亦不以爲意、惟爾一人、可當我萬、爾自城助我尤善、"],[10,18,4,"王曰、爾所視爲善者、我必行之、王乃立於門側、民衆或百或千、分隊而出、"],[10,18,5,"王命約押亞比篩以太曰、爾緣我故、寬待少者押沙龍、王爲押沙龍囑諸將、民悉聞之、"],[10,18,6,"於是民出至田、以迎以色列衆、戰於以法蓮林、"],[10,18,7,"以色列衆敗於大衞僕從之前、是日被戮者衆、計有二萬、"],[10,18,8,"因其戰鬬四方散布、死於林者、較死於刃者尤多、"],[10,18,9,"押沙龍偶與大衞之僕相遇、乘騾過於大橡繁枝之下、其首爲樹所絓、懸於空際、騾逸而去、"],[10,18,10,"或見之、告約押曰、我見押沙龍懸於橡樹、"],[10,18,11,"約押曰、爾旣見之、何不擊之隕地、若然、我以十金與紳予爾、"],[10,18,12,"曰、雖獲千金、我不伸手擊王之子、我儕聞王囑爾、與亞比篩以太曰、愼勿加害少者押沙龍、"],[10,18,13,"如我妄害其命、無事隱於王、而爾亦必敵我、"],[10,18,14,"約押曰、我不可與爾遲延、遂執三戈而往、時、押沙龍懸於橡樹、氣猶未絕、則刺其胸、"],[10,18,15,"爲約押執兵之少者十人、環攻押沙龍而斃之、"],[10,18,16,"約押吹角止衆、民乃旋返、不追以色列族、"],[10,18,17,"擲押沙龍尸於林中巨阱、壘石其上、成爲大阜、以色列衆遁歸己幕、"],[10,18,18,"押沙龍存時、嘗曰、我無遺子、以傳我名、故在王谷建柱、稱以己名、至於今日、稱爲押沙龍碑、○"],[10,18,19,"撒督子亞希瑪斯曰、請容我趨、以耶和華伸寃之音信報王、"],[10,18,20,"約押曰、今日勿報音信、他日可也、王子旣死、今日不可報音信也、"],[10,18,21,"約押謂古示人曰、爾往、以所見者告王、古示人跪拜約押而趨、"],[10,18,22,"撒督子亞希瑪斯復請曰、無論如何、容我隨古示人後、約押曰、我子歟、爾報音信、必不獲賞、疾趨何爲、"],[10,18,23,"曰、無論如何、我必趨之、曰、趨哉、亞希瑪斯乃趨、道經平原、越古示人、○"],[10,18,24,"大衞坐城兩門之間、守望者登樓巔、舉目望見一人獨趨、"],[10,18,25,"呼而告王、王曰、若惟一人來、必報音信、其人趨而漸近、"],[10,18,26,"守望者又見一人趨、告閽者曰、又有一人獨趨、王曰、彼亦報音信者也、"],[10,18,27,"守望者曰、我視在前者、其趨之勢、如撒督子亞希瑪斯然、王曰、彼善人也、必報嘉音、"],[10,18,28,"亞希瑪斯至、呼王曰安、伏地而拜、曰、爾之上帝耶和華、宜頌美焉、以舉手攻我主我王者付與矣、"],[10,18,29,"王曰、少者押沙龍安否、亞希瑪斯曰、約押遣王之僕時、我見衆大喧譁、不知何故、"],[10,18,30,"王曰、且退、侍於側、乃退而立、"],[10,18,31,"古示人至、曰、有音信報於我主我王、今日耶和華已伸爾寃於凡攻爾者、"],[10,18,32,"王曰、少者押沙龍安否、古示人曰、願我主我王之敵、及凡起而害爾者、咸如彼少者、"],[10,18,33,"王慟甚、登門樓而哭、且行且言曰、我子押沙龍、我子、我子押沙龍、我願代爾死、押沙龍我子、我子、"],[10,19,1,"或告約押曰、王緣押沙龍哭而哀、"],[10,19,2,"民聞王爲子憂、故是日奏凱、轉爲悲哀、"],[10,19,3,"當日民私歸邑、如戰敗者、含羞而退、"],[10,19,4,"王掩面、大聲呼曰、我子押沙龍、押沙龍我子、我子、"],[10,19,5,"約押入宮覲王曰、今日爾僕拯爾、及爾后妃子女之命、爾乃使之赧顏、"],[10,19,6,"惡爾者、爾反愛之、愛爾者、爾反惡之、今日明示、牧伯臣僕、於爾無足介意、我知若押沙龍生存、而我儕咸死、爾乃懽悅矣、"],[10,19,7,"今爾當起而出、以言慰藉爾僕、否則我指耶和華而誓、今夕必無一人偕爾、此禍較爾自幼所遭者尤甚、"],[10,19,8,"王遂起、坐於邑門、有告民曰、王坐邑門、民遂覲王、○"],[10,19,9,"以色列族旣遁歸幕、諸支派之民相爭曰、王拯我於敵手、又援我於非利士人手、今避押沙龍、出亡於外、"],[10,19,10,"我膏押沙龍以治我、今亡於陳、爾曹何不出言、以請王歸、○"],[10,19,11,"大衞王遣人見祭司撒督亞比亞他曰、當告猶大長老云、以色列衆所言請王返宮、傳聞於王、爾何居後、"],[10,19,12,"爾乃我之昆弟骨肉、則請王歸、何居人後、"],[10,19,13,"亦告亞瑪撒曰、爾非我之骨肉乎、如爾不代約押爲軍長、恆在我前、願上帝罰我維倍、"],[10,19,14,"於是猶大衆如懷一心、遣使告王曰、請王及臣僕偕歸、"],[10,19,15,"王乃歸、至約但、猶大人至吉甲以迎王、欲導之濟河、○"],[10,19,16,"巴戶琳之便雅憫人基拉子示每、急與猶大人偕下、迎大衞王、"],[10,19,17,"有便雅憫人一千、與掃羅家僕洗巴、及其子十五人、僕二十人從之、涉約但以迎王、"],[10,19,18,"有舟往還濟王眷聚、隨王所欲、王將濟時、基拉子示每伏於王前、"],[10,19,19,"曰、我主勿罪我、當我主我王出耶路撒冷時、僕所行悖逆之事、祈勿念之、勿介於懷、"],[10,19,20,"僕自知干罪、故今日約瑟家中、我至獨先、以迎我主我王、"],[10,19,21,"洗魯雅子亞比篩曰、耶和華之受膏者、示每詛之、可不致之死乎、"],[10,19,22,"大衞曰、洗魯雅子、我與爾曹何與、使爾今日敵我、我豈不知今日我爲以色列王、詎可在以色列中、致人於死乎、"],[10,19,23,"遂語示每曰、爾必不死、加之以誓、○"],[10,19,24,"掃羅孫米非波設亦來迎王、自王出亡、及王安歸、不治其足、不理其鬚、不澣其衣、"],[10,19,25,"至耶路撒冷迎王、王曰、米非波設、不與我同行、曷故、"],[10,19,26,"對曰、我主我王、爾僕跛足、意欲備驢乘之、與王同行、而我僕欺我、"],[10,19,27,"且謗爾僕於我主我王前、惟我主我王如上帝之使、依爾所視爲善者行之、"],[10,19,28,"蓋我祖全家、於我主我王前、咸如死者、然爾使僕列於同席者中、我尚有何理、可籲於王、"],[10,19,29,"王曰、何復言爾事乎、我命爾與洗巴、均分田畝、"],[10,19,30,"米非波設曰、我主我王旣安然還宮、任其悉取可也、○"],[10,19,31,"基列人巴西萊自羅基琳至、偕王而行、送之濟約但、"],[10,19,32,"巴西萊老邁、年已八十、其家巨富、王在瑪哈念時、嘗以所需供王、"],[10,19,33,"王謂巴西萊曰、與我偕往、我在耶路撒冷、以贍養爾、"],[10,19,34,"巴西萊曰、我生存之日、尚有幾何、可偕王上耶路撒冷乎、"],[10,19,35,"今僕年八十、所食所飲、豈能知其味、辨其美惡乎、男女謳歌、豈能聞其聲乎、何爲累我主我王、"],[10,19,36,"僕第偕王濟約但、何必加我若是之賞賚乎、"],[10,19,37,"容僕旋歸、死於故邑、在我父母墓側、爾僕金罕在此、請准其與我主我王偕濟、依爾所視爲善者待之、"],[10,19,38,"王曰、金罕必與我偕往、我依爾所視爲善者待之、爾有所求、我必爲爾行之、"],[10,19,39,"於是民衆濟約但、王亦濟、王與巴西萊接吻、爲之祝嘏、巴西萊遂歸故土、○"],[10,19,40,"王旣濟、至吉甲、金罕偕行、猶大民衆、及以色列民之半送之、"],[10,19,41,"以色列衆來見王曰、我之昆弟猶大人、何爲私導王、與眷聚及僕從、濟約但河、"],[10,19,42,"猶大人曰、王與我同宗、何因此事而怒、我豈食王祿、王豈有所餽於我乎、"],[10,19,43,"以色列人曰、我儕於王、分有其十、與大衞之情誼、較爾尤深、爾導我王歸、曷藐視我、不先與我議乎、然猶大人之言、較以色列人尤厲、"],[10,20,1,"在彼適有匪徒、便雅憫人比基利子示巴、吹角、曰、我與大衞無與、於耶西子無業、以色列族、各歸故幕可也、"],[10,20,2,"於是以色列人不從大衞、而從比基利子示巴、惟猶大人自約但至耶路撒冷、附於其王、○"],[10,20,3,"大衞王至耶路撒冷、入宮、將前所留守宮之妃十人、幽於別室、供其所需、不復進御、使如嫠婦、至於死日、"],[10,20,4,"王謂亞瑪撒曰、限以三日、爲我集猶大人、與爾偕至、"],[10,20,5,"亞瑪撒往集猶大人、稽延逾限、"],[10,20,6,"大衞謂亞比篩曰、今比基利子示巴、必將貽害、更甚於押沙龍、當率爾主之僕、追襲其後、免其入於堅城、得以避我、"],[10,20,7,"約押之卒、與基利提人、比利提人、及衆勇士從之、咸出耶路撒冷、追襲比基利子示巴、"],[10,20,8,"至基遍之大磐、亞瑪撒來迓、約押身衣戎衣、腰束以帶、中挾刃、藏於鞘、行時刃墜、"],[10,20,9,"約押謂亞瑪撒曰、吾兄安乎、乃以右手握其鬚、欲與接吻、"],[10,20,10,"亞瑪撒不防約押手中之刃、約押刺其腹、腸流於地、不再擊而卽斃、約押與弟亞比篩、追襲比基利子示巴、"],[10,20,11,"約押軍中、有少者一人立於尸旁曰、凡悅約押、爲大衞者、其從約押、"],[10,20,12,"時、亞瑪撒仆於途間、臥於血中、少者見民至此而立、卽移其尸、自大道至田間、掩之以衣、"],[10,20,13,"旣自大道移尸、民衆遂從約押、追襲比基利子示巴、"],[10,20,14,"約押徧行以色列諸支派、至伯瑪迦之亞比拉、及比利人所、其人咸集相從、"],[10,20,15,"遂至、圍示巴於伯瑪迦之亞比拉、附城築壘、陷其牆垣、欲傾圮之、"],[10,20,16,"有一哲婦自邑呼曰、聽之聽之、請約押來前、吾欲與言、"],[10,20,17,"旣近、婦曰、爾約押乎、曰、是也、婦曰、請聽婢言、曰、吾聽之、"],[10,20,18,"婦曰、昔人有言、必問於亞比拉、乃畢其事、"],[10,20,19,"我邑在以色列中、和平忠信、今爾欲滅以色列之母邑、何爲幷吞耶和華之業乎、"],[10,20,20,"約押曰、我決不幷吞毀滅之、"],[10,20,21,"其事非若是也、惟以法蓮山地之人、比基利子示巴、舉手攻大衞王、今獨以之付我、我卽離邑而去、婦曰、必以其首擲於城外、"],[10,20,22,"婦以智慧勸衆、遂斬比基利子示巴首、擲與約押、約押吹角、衆乃離邑而散、各歸其幕、約押返耶路撒冷覲王、○"],[10,20,23,"約押爲以色列軍長、耶何耶大子比拿雅、統轄基利提人、比利提人、"],[10,20,24,"亞多蘭統轄工役、亞希律子約沙法爲史官、"],[10,20,25,"示法爲繕寫、撒督與亞比亞他爲祭司、"],[10,20,26,"睚珥人以拉爲大衞之相、"],[10,21,1,"大衞在位之時、饑饉歷三載、大衞諮諏耶和華、耶和華曰、緣掃羅及其流血之家、殺基遍人也、"],[10,21,2,"夫基遍人、原爲亞摩利族之遺民、不屬以色列族、以色列族與之盟約、掃羅爲以色列及猶大人熱中、謀殺戮之、"],[10,21,3,"大衞召基遍人、謂之曰、我當爲爾何爲、何以贖此罪、俾爾爲耶和華之業祝嘏、"],[10,21,4,"基遍人曰、我儕與掃羅及其家、其間之事、不在金銀、殺以色列一人、亦非我儕所爲、王曰、爾所言者、我必爲爾行之、"],[10,21,5,"曰、昔耶和華簡掃羅爲王、彼謀害我、欲行殲滅、使我不存於以色列四境、我願以其後裔七人付我、我將爲耶和華、懸之於其邑基比亞、王曰、我必付焉、"],[10,21,6,"曰、昔耶和華簡掃羅爲王、彼謀害我、欲行殲滅、使我不存於以色列四境、我願以其後裔七人付我、我將爲耶和華、懸之於其邑基比亞、王曰、我必付焉、"],[10,21,7,"昔大衞與掃羅子約拿單、指耶和華而誓、故王惜掃羅孫、約拿單子米非波設、"],[10,21,8,"乃以掃羅妃、愛雅女利斯巴所生二子、亞摩尼米非波設、及掃羅女米拉、適米何拉人巴西萊子亞得利、所生五子、"],[10,21,9,"付於基遍人手、懸於山上、在耶和華前、七人俱亡、其見殺時、乃始刈麰麥之際、"],[10,21,10,"愛雅女利斯巴、取麻布張於磐、自初穫之時、迄天降雨、晝不容飛鳥、夜不容走獸、來犯其尸、"],[10,21,11,"或以掃羅妃、愛雅女利斯巴所爲、告大衞、"],[10,21,12,"昔非利士人殺掃羅在基利波、懸掃羅及約拿單尸於伯珊之衢、基列雅比人盜之而歸、"],[10,21,13,"今大衞命取其骸骨、並取被懸者之骸骨、"],[10,21,14,"俱葬於便雅憫地之洗拉、掃羅父基士之墓、衆循王命而行、嗣後上帝垂顧其地、○"],[10,21,15,"非利士人復與以色列戰、大衞率其臣僕迎擊、大衞困憊、"],[10,21,16,"利乏裔以實比執銅戟、重三百舍客勒、且佩新刃、欲殺大衞、"],[10,21,17,"洗魯雅子亞比篩救之、擊殺非利士人、於是大衞僕從誓曰、嗣後爾勿復偕我出戰、恐滅以色列之燈光、○"],[10,21,18,"厥後、又與非利士人戰於歌伯、戶沙人西比該、殺利乏裔撒弗、"],[10,21,19,"又與非利士人戰於歌伯、伯利恆人雅雷俄珥金子伊勒哈難殺迦特人歌利亞、其槍之柯、大如織器之梁、"],[10,21,20,"又戰於迦特、有利乏裔一人、軀幹修偉、手足各有六指、共二十有四、"],[10,21,21,"其人侮以色列時、大衞兄示米亞子約拿單殺之、"],[10,21,22,"此四人、皆利乏裔、生於迦特、死於大衞及其臣僕之手、"],[10,22,1,"耶和華拯大衞於諸敵、及掃羅之手時、大衞作歌以頌之、"],[10,22,2,"曰、耶和華爲我磐石、我之保障、我之救援兮、"],[10,22,3,"上帝我之磐石、我託庇於彼兮、爲我之盾、拯救之角、我之高臺、避難之所兮、我救者歟、爾乃援我於凶暴兮、"],[10,22,4,"耶和華宜頌美兮、我呼籲之、則見拯於諸敵兮、"],[10,22,5,"死亡之波濤環我、匪勢之衝激怖我、"],[10,22,6,"陰府之繩索繞我、死亡之機檻逮我、"],[10,22,7,"我苦難中呼耶和華、籲我上帝兮、彼自殿中垂聽我聲、我之呼籲達於其耳兮、"],[10,22,8,"因彼奮怒、大地震動、天基搖撼兮、"],[10,22,9,"煙自其鼻升、火從其口出、炭爲所燃兮、"],[10,22,10,"垂諸天而臨格、足下幽且深兮、"],[10,22,11,"乘基路伯而飛、藉風翼而顯見兮、"],[10,22,12,"使玄冥爲幕以環之、卽水之匯聚、雲之濃密兮、"],[10,22,13,"由其前之光輝、炭爲所燃兮、"],[10,22,14,"耶和華自天起雷、至高者發其聲兮、"],[10,22,15,"彼發矢以潰敵、閃電而亂之兮、"],[10,22,16,"因耶和華叱咤、鼻息之發、海底見而地基露兮、"],[10,22,17,"彼自上垂手、援我於巨浸兮、"],[10,22,18,"拯我於勁敵、及憾我者、以其強於我兮、"],[10,22,19,"我遭難時、敵來攻我、惟耶和華爲我所恃兮、"],[10,22,20,"導我入寬廣之區、施行救援、以其悅我兮、"],[10,22,21,"耶和華依我行之義而賞賚、循我手之潔而報施、"],[10,22,22,"因我守耶和華之道、未嘗爲惡、離我上帝兮、"],[10,22,23,"彼之律例、悉在我前、未嘗違其典章兮、"],[10,22,24,"我於其前爲完人、自守而遠惡兮、"],[10,22,25,"故耶和華依我之義、視我之潔、而報我兮、"],[10,22,26,"爾於仁慈者應以仁慈、純全者應以純全、"],[10,22,27,"清潔者應以清潔、乖戾者應以拂逆、"],[10,22,28,"困苦之民、爾救援之、驕泰之輩、爾目鑒察、而卑抑之兮、"],[10,22,29,"耶和華歟、爾爲我之燈光、耶和華必燭我幽暗兮、"],[10,22,30,"我賴爾衝突敵軍、恃我上帝逾越垣墉兮、"],[10,22,31,"上帝之道純全、耶和華之言經驗、凡託庇於彼者、彼爲其盾兮、"],[10,22,32,"耶和華而外、孰爲上帝兮、我上帝而外、孰爲磐石兮、"],[10,22,33,"上帝爲我鞏固之保障、導完人行其道途兮、"],[10,22,34,"令我足捷如鹿、置我於高處兮、"],[10,22,35,"教我手習戰鬬、致我臂挽銅弓兮、"],[10,22,36,"爾賜我拯救之盾、爾之温和、俾我爲大兮、"],[10,22,37,"使我步履寬裕、我足未嘗滑跌兮、"],[10,22,38,"我追敵而殲之、未行殄滅、不旋歸兮、"],[10,22,39,"我施剿而破之、使之不振、仆我足下兮、"],[10,22,40,"蓋爾以力束我、使備戰爭、起而攻我者、俾服於我兮、"],[10,22,41,"使我諸敵背我而馳、致我翦滅憾我者兮、"],[10,22,42,"彼瞻望而無援、籲耶和華亦弗應兮、"],[10,22,43,"我則擣之若地上之塵、踐之若街中之泥、散之四方兮、"],[10,22,44,"爾援我於我民之競爭、保我爲列邦之元首、我所不識之民、必服役我兮、"],[10,22,45,"外族之人、必歸誠我、聞我之名、立卽順從兮、"],[10,22,46,"外族衰落、出其衞所、戰慄而來兮、"],[10,22,47,"耶和華維生兮、我之磐石、宜頌美兮、上帝我拯救之磐石、當尊崇兮、"],[10,22,48,"上帝爲我復仇、使諸民服於我兮、"],[10,22,49,"援我於敵、舉我超乎攻我者、拯我於強暴兮、"],[10,22,50,"耶和華歟、我必於列邦中稱謝爾、歌頌爾名兮、"],[10,22,51,"耶和華大施拯救於所立之王、施恩於其受膏者、卽大衞及其後裔、永世靡曁兮、"],[10,23,1,"大衞末終之言列左、耶西子大衞、得居高位、受膏於雅各之上帝、爲以色列之善歌者曰、"],[10,23,2,"耶和華之神感我而言、厥詞在於我口、"],[10,23,3,"以色列之上帝有言、以色列之磐石謂我曰、以義治人、寅畏上帝、而秉權者、"],[10,23,4,"譬如旭日朝暉、清晨無雲、雨後日照、嫩草自地而發、"],[10,23,5,"我家之於上帝、非若是乎、彼與我立永約、諸事堅定、救我之事、及我所望、彼豈不成之乎、"],[10,23,6,"惟彼匪徒、如被棄之荊棘、手不得執、"],[10,23,7,"人欲取之、必以鐵器與槍柯、終於其地、焚之務盡、○"],[10,23,8,"從大衞之勇士、名列於左、軍長之首、他革捫人約設巴設、又稱伊斯尼人亞底挪、一時擊斃八百人、"],[10,23,9,"其次亞合裔、朵多子以利亞撒、昔非利士人集戰、以色列人逆之、從大衞者、有三勇士挑戰、此人與焉、"],[10,23,10,"彼擊非利士人、至於手倦、握刃不能釋、當日耶和華使之大獲勝捷、民衆但隨其後、掠取貨財、"],[10,23,11,"其次哈拉人亞基子沙瑪、昔非利士人羣集於荳田、以色列衆遁逃、"],[10,23,12,"沙瑪立於田間、以護其地、殺非利士人、耶和華使之大獲勝捷、"],[10,23,13,"穡時、三十首領中、有三人至亞杜蘭穴、以覲大衞、非利士軍建營於利乏音谷、"],[10,23,14,"時、大衞在保障、非利士汛在伯利恆、"],[10,23,15,"大衞歆羡曰、深願有人由伯利恆門側之井、汲水以飲我、"],[10,23,16,"勇士三人衝過非利士軍、由伯利恆門側之井汲水、攜詣大衞、大衞不飲、乃灌之於耶和華前、"],[10,23,17,"曰、耶和華歟、我決不爲此、豈飲冒死者之血乎、故不飲、三勇士所爲若此、"],[10,23,18,"其中洗魯雅子、約押弟亞比篩爲首、嘗揮戈擊斃三百人、遂在三百人中得名譽、"],[10,23,19,"彼在三人中爲最尊、故爲其魁、惟不得與首三人同列、"],[10,23,20,"又有甲薛勇士耶何耶大子比拿雅、大有作爲、殺摩押人亞利伊勒二子、又當雨雪時、下阱擊獅、"],[10,23,21,"又殺埃及壯士、其人執戈、比拿雅以杖往迎、奪其戈而殺之、"],[10,23,22,"比拿雅所爲如是、遂在三勇士中得名譽、"],[10,23,23,"彼較三十首領爲尊、惟不及前三人、大衞立之爲侍衞長、○"],[10,23,24,"三十人中、有約押弟亞撒黑、伯利恆人朵多子伊勒哈難、"],[10,23,25,"哈律人沙瑪、及以利加、"],[10,23,26,"帕勒提人希利斯、提哥亞人益吉子以拉、"],[10,23,27,"亞拿突人亞比以謝、戶沙人米本乃、"],[10,23,28,"亞合人撒們、尼陀法人瑪哈萊、"],[10,23,29,"尼陀法人巴拿子希立、便雅憫族、基比亞人利拜子以太、"],[10,23,30,"比拉頓人比拿雅、迦實溪人希太、"],[10,23,31,"伯亞拉巴人亞比亞本、巴魯米人押斯瑪弗、"],[10,23,32,"沙本人以利雅哈巴、雅善衆子中約拿單、"],[10,23,33,"哈拉人沙瑪、及沙拉子亞希暗、"],[10,23,34,"瑪迦族、亞哈拜子以利法列、基羅人亞希多弗子以連、"],[10,23,35,"迦密人希斯萊、亞巴人帕萊、"],[10,23,36,"瑣巴人拿單子以甲、迦得人巴尼、"],[10,23,37,"亞捫人西勒、比錄人拿哈萊、此二人、爲洗魯雅子約押執兵之士、"],[10,23,38,"以帖人以拉、及迦立、"],[10,23,39,"赫人烏利亞、共三十七人、"],[10,24,1,"耶和華復怒以色列人、遂感大衞、命人往核以色列猶大二族、"],[10,24,2,"軍長約押在側、王諭之曰、爾徧行以色列諸支派、自但至別是巴、核其民數、俾我知之、"],[10,24,3,"約押謂王曰、無論民數多寡、惟願爾之上帝耶和華增益百倍、我主我王目擊其事、然我主我王何樂行此、"],[10,24,4,"但約押及諸軍長爲王命所迫、遂退而核以色列民、"],[10,24,5,"旣濟約但、至迦得谷中之亞羅珥、建營於邑南、雅謝相對之所、"],[10,24,6,"後至基列、與他停合示、及但雅安、繞至西頓、"],[10,24,7,"又至推羅保障、與希未迦南二族諸邑、延及猶大南方、至別是巴、"],[10,24,8,"徧行其地、凡歷九月有二旬、而返耶路撒冷、"],[10,24,9,"約押以民數進於王、以色列人執刃之丁壯八十萬、猶大人五十萬、○"],[10,24,10,"大衞核民之後、中心自責、禱耶和華曰、我行此事、大干罪戾、愚昧之甚、耶和華歟、求爾宥僕之過、"],[10,24,11,"詰朝、大衞起時、耶和華諭大衞之先見迦得曰、"],[10,24,12,"往告大衞曰、耶和華云、我以三者示爾、可擇其一、我行於爾、"],[10,24,13,"迦得遂詣大衞曰、或饑饉臨於爾土七年、或爲敵追襲遁逃三月、或疫癘流行爾國三日、爾其思之、俾我覆遣我者、"],[10,24,14,"大衞曰、我處窘迫之境、耶和華矜恤維大、願陷於其手、勿陷於人手、"],[10,24,15,"於是耶和華降疫癘於以色列、自清晨至所定之期、自但至別是巴、民間死者七萬人、"],[10,24,16,"天使向耶路撒冷舉手、將滅之、耶和華悔禍、謂剿民之使曰、足矣、可止爾手、其時耶和華之使者、在耶布斯人亞勞拿之禾場、"],[10,24,17,"大衞見擊民之天使、則禱耶和華曰、犯罪者我、悖逆者我、惟此羣羊何爲、願爾攻我、及我父家、○"],[10,24,18,"當日迦得詣大衞曰、爾往爲耶和華築壇、在耶布斯人亞勞拿之禾場、"],[10,24,19,"遂依迦得之言、遵耶和華命而往、"],[10,24,20,"亞勞拿望見王與僕從至、遂出、伏地拜王、"],[10,24,21,"曰、我主我王蒞臨僕所曷故、大衞曰、欲購禾場、爲耶和華築壇、使疫止於民間、"],[10,24,22,"亞勞拿曰、我主我王可依視爲善者、取而獻之、牛爲燔祭、打穀之具、與牛之軛爲柴、"],[10,24,23,"王歟、亞勞拿悉以此物與王、又曰、願爾上帝耶和華悅納爾、"],[10,24,24,"王曰、不然、我必依其值而購之、不費財之燔祭、我不欲獻於我上帝耶和華、於是大衞以金五十舍客勒、購禾場與牛、"],[10,24,25,"在彼爲耶和華築壇、獻燔祭及酬恩祭、耶和華允其所祈、垂顧斯土、疫癘止於以色列中、"],[11,1,1,"大衞王壽高年邁、覆以衾而不暖、"],[11,1,2,"臣僕告曰、當爲我主我王、求一處女、侍於王前、以奉養王、臥於王懷、使我主我王得温暖焉、"],[11,1,3,"遂於以色列四境、求佳麗之女、得書念女亞比煞、攜之詣王、"],[11,1,4,"女豔甚、乃以奉養服事王、惟王不御焉、○"],[11,1,5,"哈及之子亞多尼雅自高曰、我必爲王、遂備車騎、簡五十人、趨於其前、"],[11,1,6,"彼乃後押沙龍而生、姿容甚美、其父未嘗使之不樂、曰、爾何行此、"],[11,1,7,"亞多尼雅、與洗魯雅子約押、及祭司亞比亞他同議、二人從而助之、"],[11,1,8,"惟祭司撒督、及耶何耶大子比拿雅、先知拿單、示每、利以、曁大衞之勇士、皆弗從之、"],[11,1,9,"亞多尼雅在隱羅結側、瑣希列石旁、宰牛羊肥畜、請其兄弟、王之諸子、及王臣僕猶大衆、"],[11,1,10,"惟先知拿單、與比拿雅、及衆勇士、曁弟所羅門、俱不請焉、"],[11,1,11,"拿單告所羅門母拔示巴曰、哈及子亞多尼雅爲王、爾未聞之乎、我主大衞未之知也、"],[11,1,12,"今請容我爲爾畫策、拯爾及爾子所羅門之命、"],[11,1,13,"當入覲大衞王、告之曰、我主我王歟、昔非與婢誓曰、爾子所羅門、必繼我爲王、而坐我位乎、今亞多尼雅爲王、何也、"],[11,1,14,"爾與王言之際、我亦踵入、以證爾言、"],[11,1,15,"拔示巴遂入內室覲王、王甚老邁、書念女亞比煞侍之、"],[11,1,16,"拔示巴鞠躬拜王、王曰、爾何所欲、"],[11,1,17,"曰、我主歟、昔爾指爾上帝耶和華、與婢誓曰、爾子所羅門、必繼我爲王、而坐我位、"],[11,1,18,"今亞多尼雅爲王、我主我王不之知也、"],[11,1,19,"彼宰牛羊肥畜甚多、請王衆子、與祭司亞比亞他、及軍長約押、惟爾僕所羅門、彼未請之、"],[11,1,20,"我主我王歟、今以色列衆目仰爾、而待爾言、誰繼我主我王之位、"],[11,1,21,"不然、則我主我王、與列祖偕眠時、我與我子所羅門、必視爲罪人矣、○"],[11,1,22,"婦與王言時、先知拿單入、"],[11,1,23,"或告王曰、先知拿單至矣、拿單旣至王前、俯伏於地、"],[11,1,24,"曰、我主我王、爾豈言亞多尼雅繼我爲王、而坐我位乎、"],[11,1,25,"今日彼往、多宰牛羊肥畜、請王衆子、與諸軍長、及祭司亞比亞他、衆飲食於其前、呼曰、亞多尼雅王萬歲、"],[11,1,26,"惟我爾僕、與祭司撒督、及耶何耶大子比拿雅、曁爾僕所羅門、彼未請之、"],[11,1,27,"此豈我主我王所爲、而不示爾僕、誰繼我主我王之位乎、"],[11,1,28,"大衞王曰、召拔示巴、遂詣王所、立於王前、"],[11,1,29,"王發誓云、我指援我生命、脫於諸難、維生之耶和華而誓、"],[11,1,30,"我旣指以色列之上帝耶和華、與爾誓曰、爾子所羅門、必繼我爲王、而坐我位、今日必如是而行、"],[11,1,31,"拔示巴伏地拜王曰、我主大衞王萬歲、○"],[11,1,32,"王曰、召祭司撒督、先知拿單、耶何耶大子比拿雅詣我、遂至王前、"],[11,1,33,"王諭之曰、其率爾主之僕、令吾子所羅門乘我騾、送至基訓、"],[11,1,34,"使祭司撒督、與先知拿單、膏之爲以色列王、吹角曰、所羅門王萬歲、"],[11,1,35,"爾則隨之而上、使踐我位、蓋彼代我爲王、我立之爲以色列及猶大之君、"],[11,1,36,"耶何耶大子比拿雅曰、阿們、願我主我王之上帝耶和華、亦如是言之、"],[11,1,37,"耶和華與我主我王偕、願彼亦如是與所羅門偕、使其國位、較我主大衞王之國位尤大、"],[11,1,38,"於是祭司撒督、先知拿單、耶何耶大子比拿雅、及基利提人、比利提人、俱往、使所羅門乘大衞王之騾、送至基訓、"],[11,1,39,"祭司撒督由幕中、取盛膏之角、以膏所羅門、乃吹角、民衆呼曰、所羅門王萬歲、"],[11,1,40,"民衆隨之而上、吹簫、欣喜不勝、呼聲震地、"],[11,1,41,"亞多尼雅及所偕之賓客食畢、咸聞之、約押聞角聲、則曰、城中喧譁曷故、"],[11,1,42,"言時、祭司亞比亞他子約拿單至、亞多尼雅謂之曰、入、爾乃善人、必報嘉音、"],[11,1,43,"約拿單答之曰、我主大衞王、已立所羅門爲王、"],[11,1,44,"遣祭司撒督、先知拿單、耶何耶大子比拿雅、及基利提人、比利提人從之、使乘王騾、"],[11,1,45,"祭司撒督、及先知拿單、在基訓膏之爲王、由彼歡呼而上、舉邑響應、爾所聞之喧譁此也、"],[11,1,46,"今所羅門踐其國位、"],[11,1,47,"王之臣僕至、祝我主大衞王曰、願爾上帝、使所羅門之名、較爾名尤尊、其國位、較爾國位尤大、王乃俯伏於牀、"],[11,1,48,"曰、以色列之上帝耶和華、宜頌美焉、賜我一人、今日坐於我位、俾我目擊、"],[11,1,49,"亞多尼雅賓客、恐懼而起、各行其途、"],[11,1,50,"亞多尼雅畏所羅門、亦起、往執壇角、"],[11,1,51,"或告所羅門曰、亞多尼雅畏王、執壇角曰、所羅門王、今日當與我誓、不以刃殺其僕、"],[11,1,52,"所羅門曰、如其爲善人、則彼之一髮、不隕於地、如其作惡、則必死亡、"],[11,1,53,"所羅門王遣人自壇攜之下、至則拜王、所羅門謂之曰、可歸爾家、"],[11,2,1,"大衞逝世之期伊邇、乃囑其子所羅門曰、"],[11,2,2,"我今將行舉世必行之路、當強乃志、爲大丈夫、"],[11,2,3,"遵守爾上帝耶和華之命、行其道途、循其典章誡命、律例法度、依摩西律所載、俾爾無論何爲何往、咸得利達、"],[11,2,4,"致耶和華應其指我所言曰、若爾子孫、愼其道途、一心一意行於我前、眞實無妄、則爾必不乏人、踐以色列國位、"],[11,2,5,"昔洗魯雅子約押、所行於我、殺以色列軍長二人、尼珥子押尼珥、益帖子亞瑪撒、於綏安之日、流戰鬬之血、以染所束之紳、所著之履、爾所知也、"],[11,2,6,"當循爾智而行、不容其白首安然歸墓、"],[11,2,7,"昔我避爾兄押沙龍時、基列人巴西萊衆子來迓、爾當恩待之、使與同席而食、"],[11,2,8,"我往瑪哈念時、巴戶琳人、便雅憫族、基拉子示每、以厲詞詛我、厥後迎我於約但、我指耶和華而誓、必不戮之以刃、"],[11,2,9,"勿寬其罪、爾乃哲人、知所當爲、使其白首流血歸墓、"],[11,2,10,"大衞與列祖偕眠、葬於大衞城、"],[11,2,11,"大衞治以色列四十年、在希伯崙七年、在耶路撒冷三十三年、"],[11,2,12,"所羅門踐其父大衞之位、其國甚固、○"],[11,2,13,"哈及子亞多尼雅、詣所羅門母拔示巴、拔示巴曰、汝爲平康而來乎、曰、爲平康也、"],[11,2,14,"又曰、我有事告爾、曰、其言之、"],[11,2,15,"曰、國原屬我、以色列衆咸仰望我、欲我爲王、乃爾所知、惟今反歸我弟、乃由於耶和華也、"],[11,2,16,"今有一事求爾、請毋辭、曰、其言之、"],[11,2,17,"曰、請爾求所羅門王、以書念女亞比煞予我爲妻、彼必不拒、"],[11,2,18,"拔示巴曰、善、我必與王言之、"],[11,2,19,"拔示巴遂詣所羅門王、爲亞多尼雅言之、王起、迎而拜之、復坐於位、命爲王母設座、乃坐於其右、"],[11,2,20,"母曰、我有瑣事求爾、請勿拒、王曰、我母、請言之、我必不拒、"],[11,2,21,"曰、請以書念女亞比煞、予爾兄亞多尼雅爲妻、"],[11,2,22,"王謂母曰、爾爲亞多尼雅求書念女亞比煞、曷故、彼爲我兄、爾其爲之求國、並爲祭司亞比亞他、與洗魯雅子約押求之、"],[11,2,23,"所羅門王乃指耶和華而誓曰、亞多尼雅言此、是自喪其命、不然、願上帝罰我維倍、"],[11,2,24,"維生之耶和華堅立我、使踐我父大衞之位、依其所許、爲我建立家室、我指之而誓、亞多尼雅、今日必致之死、"],[11,2,25,"遂遣耶何耶大子比拿雅擊斃之、"],[11,2,26,"王謂祭司亞比亞他曰、歸亞拿突、返爾田畝、爾原當死、惟爾在我父大衞前、舁主耶和華之匱、又與我父共苦、此時我不殺爾、"],[11,2,27,"遂黜亞比亞他、不容其爲耶和華祭司、應耶和華在示羅、論以利家所言、"],[11,2,28,"昔約押不從押沙龍、乃從亞多尼雅、聞此音耗、則遁於耶和華幕、而執壇角、"],[11,2,29,"或告所羅門王曰、約押遁於耶和華幕、今在壇側、所羅門遣耶何耶大子比拿雅曰、爾往擊之、"],[11,2,30,"比拿雅至耶和華幕、謂約押曰、王命爾出、曰、否、我死於此、比拿雅以約押所答覆王、"],[11,2,31,"王曰、如其言而行、擊而葬之、俾約押無故流人之血、其血不歸於我、及我父家、"],[11,2,32,"彼刃擊二人、較己尤義尤善者、卽以色列軍長、尼珥子押尼珥、猶大軍長、益帖子亞瑪撒、我父大衞不之知也、耶和華必使約押所流之血、歸於其首、"],[11,2,33,"此血必永歸約押、及其苗裔之首、惟綏安由耶和華、永歸大衞、曁其苗裔、與家及國、"],[11,2,34,"耶何耶大子比拿雅、遂往擊斃之、葬於其第、在於曠野、"],[11,2,35,"王立耶何耶大子比拿雅、代之爲軍長、使祭司撒督、代亞比亞他、"],[11,2,36,"王遣人召示每至、諭之曰、爾當建室於耶路撒冷居之、勿出而他往、"],[11,2,37,"當知爾出濟汲淪溪、其日必死、爾血歸於己首、"],[11,2,38,"示每曰、斯言善也、我主我王所命、僕必遵行、於是示每久居耶路撒冷、"],[11,2,39,"越三年、其僕二人、遁於迦特王、瑪迦子亞吉所、或告之曰、爾僕在迦特、"],[11,2,40,"示每起、備驢、往迦特亞吉所、尋獲其僕、攜之而返、"],[11,2,41,"或告所羅門、示每離耶路撒冷、往迦特而返、"],[11,2,42,"王遣人召之曰、我非使爾指耶和華而誓、又戒爾云、當知爾出而他往、其日必死乎、爾對曰、我所聞者善也、"],[11,2,43,"爾何不守指耶和華所誓、及我戒爾之命乎、"],[11,2,44,"又曰、昔爾行於我父大衞之惡、爾心所存、爾悉知之、今耶和華必使爾惡、歸於爾首、"],[11,2,45,"惟所羅門王、必蒙錫嘏、大衞之國、在耶和華前、恆久鞏固、"],[11,2,46,"王命耶何耶大子比拿雅擊之、遂出而擊斃之、於是國祚、堅定於所羅門手、"],[11,3,1,"所羅門與埃及王法老聯婚、娶其女、攜入大衞城、待建王宮、及耶和華室、並耶路撒冷四周之垣竣工、"],[11,3,2,"當時因未爲耶和華名建室、民在崇邱獻祭、"],[11,3,3,"所羅門敬愛耶和華、遵父大衞之典章而行、惟獻祭焚香於崇邱、○"],[11,3,4,"所羅門往基遍獻祭、在彼之崇邱維大、王獻牲一千於其壇、以爲燔祭、"],[11,3,5,"耶和華夜間見夢於所羅門曰、爾欲我錫爾者、可求之、"],[11,3,6,"所羅門曰、昔爾僕我父大衞、以誠實公義中正、行於爾前、爾循是而施以鴻恩、復加厚惠、賜之一子、踐乎其位、有如今日、"],[11,3,7,"我上帝耶和華歟、汝使爾僕、代父大衞爲王、惟我幼冲、不知若何出入、"],[11,3,8,"爾之選民乃大、其數不可勝數、爾僕居於其中、"],[11,3,9,"誰能鞫此衆民、祈賜爾僕智慧之心、爲民折中、而辨是非、"],[11,3,10,"所羅門求此、主悅其言、"],[11,3,11,"上帝曰、因爾求此、不求壽富、亦不求滅敵之命、惟求智慧以聽訟、"],[11,3,12,"我依爾所求、以聰明智慧之心錫爾、致爾之前、未有如爾者、爾之後、亦未有如爾者、"],[11,3,13,"爾所未求者、我兼賜爾、卽豐富尊榮、爾之畢生、列王之中、無可比儗、"],[11,3,14,"爾若行我道途、守我典章誡命、循爾父大衞所行、我必延爾年齡、"],[11,3,15,"所羅門旣寤、則知爲夢、遂返耶路撒冷、立於耶和華約匱前、獻燔祭酬恩祭、宴其臣僕、○"],[11,3,16,"時、有二妓至、立於王前、"],[11,3,17,"其一曰、我主歟、我與此婦同居一室、相偕在室、我產一子、"],[11,3,18,"越至三日、彼亦產子、惟我二人同處、此外無人與居、"],[11,3,19,"彼於夜間、壓死其子、"],[11,3,20,"中夜彼起、乘婢尚寢、取我子於我側、抱於其懷、而置死子於我懷、"],[11,3,21,"昧爽、我起哺子、見子已死、迨旦察之、見其非我所產、"],[11,3,22,"彼婦曰、不然、生者我子、死者爾子、曰、不然、死者爾子、生者我子、二人如是訴於王前、"],[11,3,23,"王曰、此云生者我子、死者爾子、彼云不然、死者爾子、生者我子、"],[11,3,24,"王曰、爲我取刃、則取刃至王前、"],[11,3,25,"王曰、剖生子爲二、各給其半、"],[11,3,26,"生子之母心痛其子、告王曰、我主歟、願以生子給之、決不可殺、彼婦曰、勿歸我、勿歸爾、剖之可也、"],[11,3,27,"王曰、彼乃生子之母、以子予之、決不可殺、"],[11,3,28,"以色列衆聞王所判、知其具有上帝之智慧以行鞫、遂咸寅畏焉、"],[11,4,1,"所羅門治以色列衆、"],[11,4,2,"其臣如左、撒督子亞撒利亞爲祭司、"],[11,4,3,"示沙二子、以利何烈亞希亞爲繕寫、亞希律子約沙法爲史官、"],[11,4,4,"耶何耶大子比拿雅爲軍長、撒督亞比亞他爲祭司、"],[11,4,5,"拿單子亞撒利亞爲官吏之長、拿單子撒布得爲相、亦爲王友、"],[11,4,6,"亞希煞掌宮闈、亞比大子亞多尼蘭理工役、"],[11,4,7,"所羅門又於以色列全地、設官十二、月委其一、爲王及宮廷備食物、"],[11,4,8,"其名如左、便戶珥在以法蓮山地、"],[11,4,9,"便底甲在瑪迦斯、沙賓、伯示麥、以倫伯哈南、"],[11,4,10,"便希悉在亞魯泊、梭哥希弗屬之、"],[11,4,11,"便亞比拿達在多珥四境、彼娶所羅門女他法爲妻、"],[11,4,12,"亞希律子巴拿、在他納、米吉多、及伯善四境、在耶斯列之下、近撒拉他拿、自伯善至亞伯米何拉、延及約念之外、"],[11,4,13,"便基別在基列拉末、瑪拿西子睚珥之基列諸邑、與巴珊之亞珥歌伯境、有牆垣銅楗之大邑六十、俱屬之、"],[11,4,14,"易多子亞希拿達在瑪哈念、"],[11,4,15,"亞希瑪斯在拿弗他利、彼亦娶所羅門女巴實抹爲妻、"],[11,4,16,"戶篩子巴拿在亞設及亞祿、"],[11,4,17,"帕路亞子約沙法在以薩迦、"],[11,4,18,"以拉子示每在便雅憫、"],[11,4,19,"烏利子基別在基列、卽亞摩利王西宏、巴珊王噩之地、此地惟彼爲官、○"],[11,4,20,"猶大與以色列人、多如海濱之沙、飲食歡樂、"],[11,4,21,"所羅門轄諸國、自大河至非利士地、延及埃及境、皆納貢服事所羅門、至其畢生、"],[11,4,22,"所羅門食物、日需細麪三十歌珥、粗麪六十歌珥、"],[11,4,23,"肥牛十、草場之牛二十、羊一百、又有鹿麞赤鹿、及肥禽、"],[11,4,24,"大河之西自提弗薩、延及迦薩列王、皆爲所羅門所轄、四周綏安、"],[11,4,25,"所羅門存日、猶大與以色列人、自但至別是巴、各安居於其葡萄無花果樹下、"],[11,4,26,"所羅門有服車之馬四萬厩、騎兵一萬二千、"],[11,4,27,"十二官各按月期、爲所羅門王、及與王同席之人備食物、無所缺乏、"],[11,4,28,"又攜麰麥蒭蕘而至、以養馬及捷足之驥、各循其職、○"],[11,4,29,"上帝賜所羅門智慧、明哲、宏博、如海濱之沙、不可測焉、"],[11,4,30,"其智慧超乎東方人、與埃及人、"],[11,4,31,"其明哲勝於萬人、超乎以斯拉人以探、及瑪曷子、希幔、甲各、達大、其聲名洋溢於四周之國、"],[11,4,32,"所羅門作箴三千言、作詩千有五篇、"],[11,4,33,"亦論草木、自利巴嫩之香柏、及牆上之牛膝草、又論鳥獸蟲魚、"],[11,4,34,"天下列王、聞所羅門之智慧、其民遂來聽之、"],[11,5,1,"推羅王希蘭素愛大衞、聞所羅門受膏、繼父爲王、則遣臣僕見之、"],[11,5,2,"所羅門亦遣人見希蘭曰、"],[11,5,3,"昔我父大衞、因四方戰鬬、待耶和華服諸敵於其足下、不能爲其上帝耶和華之名建室、爾所知也、"],[11,5,4,"今我上帝耶和華、錫我四周綏安、無敵無殃、"],[11,5,5,"我決志爲我上帝耶和華之名建室、應耶和華諭我父大衞之言曰、我將使爾子繼爾踐位、彼必爲我名建室、"],[11,5,6,"請爾命人、爲我斫香柏於利巴嫩、我僕與爾僕偕、爾言其值、我必予之、蓋爾知西頓人能斫木、我中無人如之、"],[11,5,7,"希蘭聞所羅門言、欣喜不勝、曰、今當頌美耶和華、賜大衞智慧之子、治此大國、"],[11,5,8,"遂遣人告所羅門曰、爾所言者、我已聞之、論及香柏松木、我必如爾所欲而爲、"],[11,5,9,"我僕必自利巴嫩、運至海濱、編之爲桴、浮海至爾所定之地、在彼解之、爾可受焉、以食物供我宮廷、則盈我願、"],[11,5,10,"希蘭以香柏松木予所羅門、如其所欲、"],[11,5,11,"所羅門以麥二萬歌珥、清油二十歌珥、供希蘭之宮廷、每歲如此、"],[11,5,12,"希蘭與所羅門和好、彼此立約、耶和華循其所許、以智慧賜所羅門、○"],[11,5,13,"所羅門王在以色列中、徵人爲役、共計三萬、"],[11,5,14,"每月遞更、遣人一萬至利巴嫩、居利巴嫩一月、居家二月、亞多尼蘭督之、"],[11,5,15,"所羅門又有七萬人負荷、八萬人在山鑿石、"],[11,5,16,"此外有督工者、三千三百人、以督操作之衆、"],[11,5,17,"王命人鑿大而且貴之石、以立室基、"],[11,5,18,"所羅門與希蘭之匠、曁迦巴勒人琢之、備具木石、以建殿宇、"],[11,6,1,"以色列族出埃及後、四百八十年、所羅門在位之四年、西弗月、卽二月、始建耶和華室、"],[11,6,2,"室長六十肘、廣二十肘、高三十肘、"],[11,6,3,"聖所前之廊、長二十肘、與室之廣同、其廣十肘、"],[11,6,4,"爲室作牖、其櫺方罫、"],[11,6,5,"殿與內殿四周、依牆建樓、四周有屋、"],[11,6,6,"其下廣五肘、中廣六肘、上廣七肘、室外四周、相間以凹、使梁弗入室牆、"],[11,6,7,"建室乃以鑿處所備之石、建時不聞椎斧鐵器之聲、"],[11,6,8,"中屋之門在室右、自下至中、延及上層、其梯曲折而登、"],[11,6,9,"所羅門建室旣畢、乃置香柏之梁、蓋以香柏之板、"],[11,6,10,"室之四周建屋、各高五肘、以香柏接連之、○"],[11,6,11,"耶和華諭所羅門曰、"],[11,6,12,"論爾所建之室、如爾循我典章、守我律例、遵我誡命而行、則我與爾父大衞所言者、必成之於爾、"],[11,6,13,"亦必居以色列中、不棄我民以色列、○"],[11,6,14,"所羅門建室旣畢、"],[11,6,15,"室中之壁、自下及梁、以香柏板蓋之、以松木板鋪地、"],[11,6,16,"室之後、二十肘、以香柏板作壁、自下至梁、以爲內殿、卽至聖所、"],[11,6,17,"內殿前之室、長四十肘、"],[11,6,18,"室內之壁、俱以香柏蓋之、雕以匏瓜花蕊之形、其石弗露、"],[11,6,19,"室中備至聖所、以置耶和華約匱、"],[11,6,20,"內殿長二十肘、廣二十肘、高二十肘、蓋以精金、以香柏作壇、蓋以精金、"],[11,6,21,"室中、所羅門悉以精金蓋之、內殿之前、間以金索、亦蓋以金、"],[11,6,22,"室之四周、咸蓋以金、內殿之壇、亦蓋以金、"],[11,6,23,"以橄欖木作基路伯二、各高十肘、在於內殿、"],[11,6,24,"此翮長五肘、彼翮亦長五肘、由此之末、達彼之末、共長十肘、"],[11,6,25,"其二基路伯之翮、亦長十肘、兩基路伯、其長短形式皆同、"],[11,6,26,"其一高十肘、其二亦然、"],[11,6,27,"置二基路伯於內室、各張其翮、其一之翮、及於此牆、其二之翮、及於彼牆、當室之中、二者之翮、彼此相接、"],[11,6,28,"以金飾基路伯、"],[11,6,29,"內殿外殿、其牆四周、皆雕基路伯、與椶樹花蕊之形、"],[11,6,30,"內殿外殿之地板、悉以金蓋之、"],[11,6,31,"以橄欖木作內殿之門扉、及楣與橛、其門當壁之中、五分得一、"],[11,6,32,"橄欖木所製之門扉二、以金蓋之、上刻基路伯、與椶樹花蕊之形、俱飾以金、"],[11,6,33,"以橄欖木製外殿門橛、其門當壁之中、四分得一、"],[11,6,34,"二扉乃松木爲之、各分爲二、可以摺疊、"],[11,6,35,"其上雕基路伯、與椶樹花蕊之形、以金飾之、"],[11,6,36,"內院以雕石三層、香柏一層建之、"],[11,6,37,"所羅門四年西弗月立耶和華室基、"],[11,6,38,"越至十一年布勒月、卽八月、建室已竣、遵式以造、凡歷七年、"],[11,7,1,"所羅門爲己建宮室、歷十三年、始竣厥工、"],[11,7,2,"所建之宅、名利巴嫩林宮、長一百肘、廣五十肘、高三十肘、有柱四行、其上有梁、悉用香柏、"],[11,7,3,"柱上有屋、蓋以香柏、屋計四十有五、每層十五、"],[11,7,4,"有牖三層、牖與牖相對、"],[11,7,5,"所有門橛、俱以木作、形製維方、其牖三層、皆相對、"],[11,7,6,"復豎柱建廊、長五十肘、廣三十肘、廊前有廈、廈前有柱與階、"],[11,7,7,"又建一廊、其中設座、卽聽訟之所、自下及上、蓋以香柏、"],[11,7,8,"廊後別院、王所居之室、製造亦若是、又爲所娶法老之女建宮、製造與此廊同、"],[11,7,9,"凡此、自基至檐、自外至大院、皆用珍貴之石、循其量度、以鋸齊之、"],[11,7,10,"基乃珍貴之石、其形甚巨、長十肘者有之、長八肘者有之、"],[11,7,11,"基上亦用珍貴之石、循其量度、亦有香柏、"],[11,7,12,"大院四周、有雕石三層、香柏一層、與耶和華室之內院、及廊同式、○"],[11,7,13,"所羅門王遣人召戶蘭、自推羅至、"],[11,7,14,"彼乃拿弗他利支派嫠婦之子、其父推羅人、業銅工、戶蘭聰明智慧、技藝俱備、善於銅工、乃詣所羅門王、爲之製造、"],[11,7,15,"鑄銅柱二、各高十八肘、圍十二肘、"],[11,7,16,"鑄銅頂二、置於柱首、各高五肘、"],[11,7,17,"柱頂有綺文之網、及鏈索之環、其數各七、"],[11,7,18,"又作石榴二行、環網以蓋柱頂、二頂皆然、"],[11,7,19,"廊中柱頂、高四肘、狀如百合花、"],[11,7,20,"柱頂凸處、附網環以石榴二行、其數二百、"],[11,7,21,"立柱於殿廊、右名雅斤、左名波阿斯、"],[11,7,22,"柱頂有百合花之製、作柱之工乃竣、"],[11,7,23,"鑄銅海、其式維圓、徑十肘、高五肘、圍三十肘、"],[11,7,24,"其邊之下、四周有匏瓜二行、環於其海、十肘之長、海與匏瓜、同時而鑄、"],[11,7,25,"海有十二牛負之、北向三、西向三、南向三、東向三、海在其上、牛後內向、"],[11,7,26,"海厚一掌、邊製如盂、式若百合花、可容二千罷特、"],[11,7,27,"又鑄銅座十、每座長四肘、廣四肘、高三肘、"],[11,7,28,"其制如左、座之四旁、緣內各有鑲版、"],[11,7,29,"鑲板上、有獅牛與基路伯之像、緣上有座、獅牛之下、垂有結綵之狀、"],[11,7,30,"座各有銅輪四、銅軸四、座之四足、各有肩形、肩鑄於海下、其側有結綵之狀、"],[11,7,31,"自肩至口、高一肘、其口乃圓、與座無異、廣一肘有半、口上有雕刻之形、其鑲版方而不圓、"],[11,7,32,"四輪在鑲版下、輪軸與座相連、輪高各一肘有半、"],[11,7,33,"其輪之製如車輪、其軸、其環、其輻、其轂、俱以銅鑄之、"],[11,7,34,"座之四隅、各有肩形、與座相連、"],[11,7,35,"座上有緣、其形維圓、高半肘、座之斜柱及鑲版、俱與座同鑄、"],[11,7,36,"斜柱鑲版上、雕基路伯、及獅與椶樹、悉依其度而作、四周有結綵之狀、"],[11,7,37,"十座皆如是而製、其鎔鑄、度量、狀式、俱維一、"],[11,7,38,"又鑄銅盤十、各容四十罷特、其徑四肘、十座各置一盤、"],[11,7,39,"置座於室、左五右五、置海於室右、在東向南、"],[11,7,40,"又製鼎鏟碗、戶蘭爲所羅門王、所作耶和華室之工、於是告竣、"],[11,7,41,"卽柱二、及柱頂之球二、蓋頂球之網二、"],[11,7,42,"網上之石榴四百、網各二行、以蓋柱頂之球、"],[11,7,43,"座十、及座上之十盤、"],[11,7,44,"銅海一、及其下之牛十二、"],[11,7,45,"鼎鏟碗、戶蘭爲所羅門王、所作耶和華室之器、俱以磨光之銅而製、"],[11,7,46,"在約但平原、疎割撒拉但間、膠土之地鑄之、"],[11,7,47,"所作之器繁多、所羅門未權之、銅之輕重、不得而知、"],[11,7,48,"所羅門又作耶和華室所有器皿、卽金壇、及陳餅之金几、"],[11,7,49,"內殿前之燈臺、左右各五、製以精金、其花、其燈、其鑷、俱以金製、"],[11,7,50,"其盂、其剪、其盌、其匙、其鼎、悉精金所製、內殿卽至聖所之門樞、與外殿之門樞、俱以金製、"],[11,7,51,"所羅門王爲耶和華室所作之工竣、攜父大衞所獻之金銀、及器皿、置於耶和華室中之府庫、"],[11,8,1,"所羅門集以色列長老、諸支派之長、室家之顯者、至耶路撒冷、所羅門王所、欲自大衞城、卽錫安、舁耶和華約匱、"],[11,8,2,"以他念月、卽七月節期、以色列衆集於所羅門王所、"],[11,8,3,"以色列長老旣至、祭司乃舁匱、"],[11,8,4,"祭司利未人、舁耶和華匱、與會幕、及幕中聖器、"],[11,8,5,"所羅門王與所集之以色列會衆、咸在匱前、獻牛羊爲祭、其多不可勝數、"],[11,8,6,"祭司舁耶和華約匱、入於其所、在內殿、卽至聖所、基路伯翮下、"],[11,8,7,"基路伯於匱之上、展其雙翮、覆匱及杠、"],[11,8,8,"其杠甚長、在內殿前之聖所、可見其末、惟室外不得見之、迄今猶在、"],[11,8,9,"匱內惟二石版、卽以色列人出埃及、耶和華與之立約、摩西在何烈山所置者、此外別無他物、"],[11,8,10,"祭司出聖所時、有雲盈耶和華室、"],[11,8,11,"祭司因雲之故、不能侍立奉事、蓋耶和華之榮光充其室也、○"],[11,8,12,"所羅門曰、耶和華曾云、必居於幽深之處、"],[11,8,13,"我爲爾建室、俾爾永居、"],[11,8,14,"王乃回顧、爲以色列會衆祝嘏、會衆咸立、"],[11,8,15,"王曰、以色列之上帝耶和華、宜頌美焉、昔以口諭我父大衞者、今以手成之、"],[11,8,16,"彼曰、自我導我民以色列出埃及、於以色列支派中、我未嘗簡一邑以建室、爲我寄名之所、惟簡大衞、治我民以色列、"],[11,8,17,"我父大衞、有意爲以色列上帝耶和華之名建室、"],[11,8,18,"惟耶和華諭之曰、爾欲爲我名建室、此意誠善、"],[11,8,19,"然爾不可建室、惟爾所生之子、將爲我名建室、"],[11,8,20,"今耶和華之言驗矣、蓋我循其所許、起而繼父大衞、居以色列國位、又爲以色列上帝耶和華之名建室、備所以置匱、"],[11,8,21,"昔耶和華導我列祖出埃及、所立之約、藏於其中、○"],[11,8,22,"所羅門立於耶和華壇前、以色列會衆咸在、王乃張手向天、"],[11,8,23,"曰、以色列之上帝耶和華歟、在天在地、無神可比、爾僕克盡厥心、行於爾前、爾爲之踐約施恩、"],[11,8,24,"爾許爾僕我父大衞之言應矣、爾口許之、而手成之、有如今日、"],[11,8,25,"以色列之上帝耶和華歟、爾許爾僕我父大衞曰、若爾子孫愼其道途、行於我前、克肖乎爾、則爾必不乏人、居以色列國位、今求踐爾所言、"],[11,8,26,"以色列之上帝歟、爾與爾僕我父大衞所言者、願爾成之、"],[11,8,27,"然上帝豈果居於地乎、天與天上之天、不足容爾、況我所建之室乎、"],[11,8,28,"惟求我之上帝耶和華、垂顧爾僕之禱告祈求、俯聽爾僕今在爾前之籲禱、"],[11,8,29,"願爾之目、晝夜垂顧此室、卽爾所言寄名之所、俯聽爾僕向此所祈、"],[11,8,30,"爾僕與爾民以色列、向此祈禱時、求爾在天爾之居所垂聽、而加赦宥、"],[11,8,31,"人若獲罪於鄰、令其發誓、則至此室、在爾壇前發誓、"],[11,8,32,"求爾在天垂聽、訊鞫爾僕、惡者罪之、依其所行、報於其首、義者義之、如其義以賞之、"],[11,8,33,"爾民以色列因獲罪爾、敗於敵前、若轉歸爾、而認爾名、在此室禱告祈求於爾、"],[11,8,34,"願爾在天垂聽、赦爾民以色列之罪、導之歸爾所錫其列祖之地、"],[11,8,35,"民獲罪爾、致天閉塞不雨、遭爾罰時、若向此祈禱、而認爾名、改悔厥罪、"],[11,8,36,"求爾在天垂聽、赦宥爾僕及爾民以色列之罪、誨以當行之善道、降雨於爾地、卽爾所錫爾民爲業者、"],[11,8,37,"若斯土有饑饉疫癘、五穀枯稿霉爛、或有蝻蝗蚱蜢、或有仇敵犯境、圍其城邑、無論何災何疾、"],[11,8,38,"爾民以色列或一人、或衆人、自覺己心之殃、若向此室張手、無論何所禱、何所祈、"],[11,8,39,"願爾在天爾之居所垂聽、而加赦宥、爾知其心、循各人所行而報之、世人之心、惟爾知之、"],[11,8,40,"使其在爾錫我列祖之地、畢生寅畏爾、"],[11,8,41,"至於外族、不屬爾民以色列者、爲爾之名而至、"],[11,8,42,"蓋彼必聞爾之大名、能手奮臂、自遠方來、向斯室祈禱、"],[11,8,43,"願爾在天爾之居所垂聽、依外族所祈者而行、使天下億兆、咸知爾名、而寅畏爾、如爾民以色列然、亦知我所建之室、以爾名稱之、"],[11,8,44,"如爾民奉爾所遣、無論何途、出與敵戰、向爾所簡之邑、及我爲爾名所建之室、祈禱耶和華、"],[11,8,45,"願爾在天聽其禱告祈求、而保其義、"],[11,8,46,"夫人未有不干罪者、若爾民獲罪於爾、因爾震怒、付之於敵、虜至其地、或遠或近、"],[11,8,47,"如在虜至之地、思念改悔、懇求於爾曰、我儕犯罪、悖逆作惡、"],[11,8,48,"在敵人虜者之地、一心一意歸爾、向其故土、爾所錫其列祖者、與爾所簡之邑、及我爲爾名所建之室、祈禱於爾、"],[11,8,49,"願爾在天爾之居所、聽其禱告祈求、而保其義、"],[11,8,50,"寬恕獲罪於爾之民、宥其對爾所干之咎、使於虜者之前、得其矜憫、"],[11,8,51,"彼爲爾民爾業、昔爾導之出埃及、脫於鐵爐、"],[11,8,52,"願爾垂顧爾僕、及爾民以色列之祈禱、無論何時呼籲、求爾聽之、"],[11,8,53,"主耶和華歟、爾由億兆中、區別斯民、爲爾之業、如爾導我列祖出埃及時、藉爾僕摩西所言、○"],[11,8,54,"所羅門屈膝、跪於耶和華壇前、張手向天、禱告祈求於耶和華旣畢、則起、"],[11,8,55,"立而大聲爲以色列會衆祝嘏、"],[11,8,56,"曰、耶和華宜頌美焉、踐其前言、錫綏安於其民以色列、昔藉其僕摩西所許之福、一言不廢、"],[11,8,57,"願我上帝耶和華偕我儕、如偕我列祖然、勿我離、勿我棄、"],[11,8,58,"使我心歸之、行其道途、守其諭我列祖之誡命、典章律例、"],[11,8,59,"我於耶和華前、祈禱之言、願我上帝耶和華晝夜垂念、而爲其僕、及其民以色列伸寃、適每日之所宜、"],[11,8,60,"使天下億兆、皆知耶和華爲上帝、其外無他、"],[11,8,61,"故爾有衆、當誠心對越我上帝耶和華、從其典章、守其誡命、有如今日、○"],[11,8,62,"王與以色列衆、獻祭於耶和華前、"],[11,8,63,"所羅門獻於耶和華爲酬恩祭、牛二萬二千、羊十二萬、如是、王與以色列衆、區別耶和華室爲聖、"],[11,8,64,"是日、王亦區別耶和華室前院中爲聖、以獻燔祭素祭、與酬恩祭之脂、因耶和華前之銅壇小、不能容其祭品也、"],[11,8,65,"是時所羅門與以色列衆、自哈馬道、至埃及溪、集爲大會、在我上帝耶和華前、同守節期、歷七日、復七日、共十四日、"],[11,8,66,"越至八日、王遣散民衆、民爲王祝嘏、緣耶和華善待其僕大衞、及其民以色列、中心歡悅、各歸其幕、"],[11,9,1,"所羅門建耶和華室、及其宮室、與凡所欲爲者、厥工旣竣、"],[11,9,2,"耶和華又見於彼、與昔在基遍同、"],[11,9,3,"諭之曰、爾於我前、所祈所禱者、我聞之矣、爾所建之室、我區別爲聖、以永寄我名、我目我心、必恆久在彼、"],[11,9,4,"如爾存誠心、秉正直、行於我前、克肖爾父大衞、遵我所命、守我典章律例、"],[11,9,5,"則我必永固爾國位於以色列、循我所許爾父大衞曰、爾不乏人、踐以色列國位、"],[11,9,6,"如爾及子孫、轉而不從我、不守我所示爾之誡命典章、往事他神、而崇拜之、"],[11,9,7,"我必於所賜之地、拒絕以色列族、棄此爲我名區別爲聖之室、而不之顧、使以色列族、於列國之中、作諺語、爲話柄、"],[11,9,8,"此室雖高、凡過之者、必駭異而嗤笑曰、耶和華曷如是待此地此室乎、"],[11,9,9,"則將應之曰、昔其上帝耶和華、導其列祖出埃及、彼乃棄之、歸向他神、崇拜奉事之、故降是災於彼、○"],[11,9,10,"所羅門建二室、卽耶和華室、及王宮室、歷二十年、始竣其工、"],[11,9,11,"推羅王希蘭、曾以香柏松木及金、給所羅門、任其所欲、所羅門王乃以加利利地二十邑予之、"],[11,9,12,"希蘭自推羅來、觀所羅門所予之邑、不悅之、"],[11,9,13,"曰、我兄弟歟、所予何邑、遂名之曰迦步勒地、迄於今日、"],[11,9,14,"希蘭遺金一百二十他連得於王、○"],[11,9,15,"所羅門王徵人服役、乃爲建耶和華室、與己宮室、及米羅曁耶路撒冷城垣、並夏瑣、米吉多、基色、"],[11,9,16,"昔埃及王法老攻取基色、焚之以火、殺居其邑之迦南人、以邑畀其女、所羅門之后爲業、"],[11,9,17,"故所羅門建基色、及下伯和崙、"],[11,9,18,"與巴拉、曁達莫、在境內之曠野、"],[11,9,19,"亦建府庫車騎之邑、在耶路撒冷、與利巴嫩、及所轄之境、凡所羅門欲建者、悉建之、"],[11,9,20,"斯土所遺亞摩利人、赫人、比利洗人、希未人、耶布斯人、非屬以色列族、"],[11,9,21,"卽以色列人不能盡滅者、所羅門徵其子孫服役、迄於今日、"],[11,9,22,"惟以色列族、所羅門不使之服役、乃爲戰士、臣僕、牧伯、軍長、及車騎之長、"],[11,9,23,"所羅門有監工者、五百五十人、以督操作之衆、"],[11,9,24,"法老之女、自大衞城、至所羅門爲彼所建之宮、其時、所羅門建米羅、"],[11,9,25,"所羅門獻燔祭及酬恩祭、於爲耶和華所築之壇、在耶和華前、亦焚香於其上、歲凡三次、於是建室之功告成、○"],[11,9,26,"所羅門王在以東紅海之濱、近以祿之以旬迦別、製造羣舶、"],[11,9,27,"希蘭遣其僕、諳航海者、與所羅門僕偕往、"],[11,9,28,"至俄斐、得金四百二十他連得、運至所羅門王、"],[11,10,1,"示巴女王、聞所羅門由耶和華名、而得之聲譽、遂來、欲以難語試之、"],[11,10,2,"彼至耶路撒冷、從者甚衆、有駝負香品、及黃金甚多、亦有寶石、見所羅門、悉以中心所存者與之言、"],[11,10,3,"其所問者、所羅門俱答之、無有一事不明、而不告之、"],[11,10,4,"示巴女王、見所羅門之智慧、所建之宮室、"],[11,10,5,"筵席之餚饌、羣臣之坐次、衆僕之侍立、與其服飾、及其酒政、曁陞耶和華室之階、則神爲之奪、"],[11,10,6,"謂王曰、我在我國、所聞爾之行爲智慧、洵不誣也、"],[11,10,7,"我未至而目擊、則不信其言、今知所告我者、猶未及半、爾之智慧福祉、過於我之所聞、"],[11,10,8,"爾之羣臣、爾之衆僕、恆侍爾前、聞爾智慧、其有福矣、"],[11,10,9,"爾上帝耶和華悅爾、使居以色列國位、宜頌美焉、蓋耶和華恆愛以色列、故立爾爲王、施行公義、"],[11,10,10,"於是示巴女王、以黃金一百二十他連得、香品甚多、及厥寶石、饋所羅門王、所饋王之香品、此後未有若是之多也、"],[11,10,11,"希蘭之羣舶、自俄斐運金者、亦運檀木、寶石甚多、"],[11,10,12,"王以檀木、爲耶和華室及王宮作欄、又爲謳歌者作琴與瑟、自昔迄今、未見若此之檀木、"],[11,10,13,"示巴女王所欲所求者、所羅門王悉予之、且循王之厚意、更有饋焉、遂與臣僕、返其故土、○"],[11,10,14,"所羅門歲得金六百六十六他連得、"],[11,10,15,"此外又有商賈、與雜族諸王、及國中牧伯、所進之金、"],[11,10,16,"所羅門王以煉金、作盾二百、每盾需金六百舍客勒、"],[11,10,17,"又以煉金作干三百、每干需金三彌那、王置於利巴嫩林宮、"],[11,10,18,"又以象牙製大寶座一、包以精金、"],[11,10,19,"座階六級、座後維圓、左右有扶手、二獅旁立、"],[11,10,20,"六級各有二獅、左一右一、共十有二、他國未有若是之製也、"],[11,10,21,"所羅門王所有之爵、悉以金製、利巴嫩林宮諸器、皆爲精金、當所羅門時、銀不爲貴、"],[11,10,22,"王有他施羣舶、與希蘭之羣舶航海、三年一返、載金銀、象牙、猿猴、孔雀而歸、○"],[11,10,23,"所羅門王之貨財與智慧、超乎天下列王、"],[11,10,24,"天下億兆、咸求見所羅門、以聽其智慧、卽上帝賦於其心者、"],[11,10,25,"各進貢物、卽金器銀器、衣服軍械、香品馬騾、歲有定例、"],[11,10,26,"所羅門集車騎、有車一千四百、騎兵一萬二千、置於屯車之邑、及王都耶路撒冷、"],[11,10,27,"王使銀在耶路撒冷如石、香柏多如谷中之桑、"],[11,10,28,"所羅門之馬、來自埃及、乃王之商賈、依各羣之值而購者、"],[11,10,29,"自埃及而得之車、每乘值銀六百舍客勒、每馬值銀一百五十舍客勒、赫族諸王、與亞蘭諸王、亦依其值、由此商賈而購之、"],[11,11,1,"所羅門王寵法老女、此外、又寵異族之女甚多、卽摩押亞捫以東西頓赫人之女、"],[11,11,2,"耶和華曾諭以色列人云、勿與彼族往來相通、彼必誘惑爾心、俾從其神、然所羅門戀愛其女、"],[11,11,3,"公主爲后妃者七百、嬪嬙三百、皆蠱惑其心、"],[11,11,4,"所羅門年邁時、后妃誘之、附於他神、不專心從其上帝耶和華、如父大衞、"],[11,11,5,"乃從西頓人之女神亞斯他錄、及亞捫人可憎之神米勒公、"],[11,11,6,"所羅門行耶和華所惡、不效其父大衞、盡心從耶和華、"],[11,11,7,"在耶路撒冷東之山、爲摩押可憎之神基抹、與亞捫人可憎之神摩洛築壇、"],[11,11,8,"爲其異族后妃亦行此、彼皆焚香獻祭與其神、○"],[11,11,9,"耶和華怒所羅門、因其心轉離以色列之上帝耶和華、二次見於彼者、"],[11,11,10,"耶和華命其不可從事他神、彼乃不遵其命、"],[11,11,11,"故耶和華諭之曰、爾旣行是、不守我約、及我命爾之典章、我必奪爾國祚、以予爾僕、"],[11,11,12,"第緣爾父大衞之故、於爾存日、我不行是、惟必奪於爾子之手、"],[11,11,13,"然不奪其全國、因我僕大衞、及我所簡之耶路撒冷故、以一支派錫予爾子、○"],[11,11,14,"耶和華使以東王裔哈達、起而敵所羅門、"],[11,11,15,"昔大衞征以東、其軍長約押、往葬陳亡者、盡殺以東之丁男、"],[11,11,16,"約押與以色列衆居彼六月、迨其地之丁男殲焉、"],[11,11,17,"時、哈達尚幼、與父臣僕以東數人、遁於埃及、"],[11,11,18,"自米甸啟行、至巴蘭、由彼攜人、偕至埃及、覲埃及王法老、王賜以第宅、定其糈糧、錫以土地、"],[11,11,19,"哈達蒙厚恩於法老前、法老以其后答比匿妹妻之、"],[11,11,20,"生子基努拔、答比匿使在法老宮斷乳、基努拔遂居宮中、與法老諸子偕、"],[11,11,21,"哈達在埃及聞大衞與列祖偕眠、軍長約押已死、則謂法老曰、容我歸故土、"],[11,11,22,"法老曰、爾與我偕、何所缺、致欲歸故土耶、對曰、我無所缺、惟請容我歸、○"],[11,11,23,"上帝又興一敵、以利亞大子利遜、以攻所羅門、昔利遜逃其主、瑣巴王哈大底謝、"],[11,11,24,"大衞殺瑣巴人時、利遜集人成羣、而爲其首、往居大馬色、在彼爲王、"],[11,11,25,"所羅門存日、哈達爲患而外、利遜爲亞蘭王、憾以色列人、亦爲其敵、○"],[11,11,26,"以法蓮族、洗利達人、尼八子耶羅波安、其母名洗魯阿、嫠婦也、彼爲所羅門臣僕、亦起而叛王、"],[11,11,27,"其叛逆之故、乃因所羅門建米羅、修其父大衞城之破壞、"],[11,11,28,"耶羅波安乃勇士、所羅門見其少年殷勤、委之督約瑟家之工、"],[11,11,29,"時、耶羅波安出耶路撒冷、示羅人先知亞希雅、遇之於途、亞希雅衣新衣、惟二人在田野、"],[11,11,30,"亞希雅取其所衣之新衣、裂爲十二、"],[11,11,31,"謂之曰、爾取其十、蓋以色列之上帝耶和華曰、我必分裂此國、奪於所羅門手、以十支派予爾、"],[11,11,32,"惟因我僕大衞、及我於以色列支派中、所簡之邑耶路撒冷故、彼必得一支派、"],[11,11,33,"我之行此、乃因其人棄我、崇拜西頓人之女神亞斯他錄、摩押之神基抹、亞捫族之神米勒公、不從我道、行我所悅、不守我之典章律例、如父大衞所爲、"],[11,11,34,"然我不奪全國於其手、必使之爲君、以畢其生、緣我所簡之僕大衞、守我誡命典章故也、"],[11,11,35,"惟必奪國於其子手、以十支派予爾、"],[11,11,36,"以一支派予其子、使我僕大衞、在我前恆有燈光、於我所簡耶路撒冷、卽我寄名之所、"],[11,11,37,"我將簡爾、俾從所欲而主治、爲以色列王、"],[11,11,38,"爾若聽我所命、從我之道、行我所悅、守我典章誡命、如我僕大衞所爲、我必偕爾、爲爾建鞏固之家室、如爲大衞所建、且以以色列族畀爾、"],[11,11,39,"我必困苦大衞之裔、然不至久遠、"],[11,11,40,"緣此、所羅門欲殺耶羅波安、耶羅波安起而遁於埃及、至埃及王示撒、居彼、迨所羅門薨、○"],[11,11,41,"所羅門其餘事蹟、凡其所爲、與其智慧、俱載於所羅門紀、"],[11,11,42,"所羅門在耶路撒冷、爲以色列全國之王、歷四十年、"],[11,11,43,"所羅門與列祖偕眠、葬於父大衞城、子羅波安嗣位、"],[11,12,1,"羅波安往示劍、因以色列衆至彼、欲立之爲王、"],[11,12,2,"昔尼八子耶羅波安、避所羅門王、遁於埃及居焉、今聞此事、"],[11,12,3,"民衆遣人招之、遂與以色列會衆、來見羅波安曰、"],[11,12,4,"爾父使我儕負軛艱苦、爾其輕爾父之重軛、與艱苦之役事、我則服事爾、"],[11,12,5,"王曰、姑退、越三日、復來見我、民乃去、"],[11,12,6,"其父所羅門存日、有侍其前之耆老、羅波安王與之議曰、汝有何謀、以答斯民、"],[11,12,7,"僉曰、今日爾若願爲斯民之僕、而服事之、答以善言、彼必永爲爾僕、"],[11,12,8,"惟王違棄耆老之謀、與侍其前、偕己同長之少者謀、"],[11,12,9,"曰、斯民謂我云、爾父加我之軛、求爾輕之、汝有何謀、以答斯民、"],[11,12,10,"偕彼同長之少者曰、斯民謂爾云、爾父使我負重軛、求爲我輕之、可答之曰、我之小指、巨於我父之腰、"],[11,12,11,"我父使爾負重軛、我必益之、我父責爾以鞭、我則責爾以蠍、"],[11,12,12,"越三日、耶羅波安與民衆、咸詣羅波安、循王所命、越三日復來見我之言、"],[11,12,13,"王以厲詞答之、違棄耆老之謀、"],[11,12,14,"依少者之謀、告之曰、我父使爾負重軛、我必益之、我父責爾以鞭、我則責爾以蠍、"],[11,12,15,"王不聽民所求、是事由於耶和華、以應耶和華藉示羅人亞希雅、告尼八子耶羅波安之言、"],[11,12,16,"以色列衆見王不聽、則謂王曰、我與大衞何與、我於耶西子無業、以色列人歟、爾其歸幕、大衞家歟、爾其自顧、以色列人遂歸其幕、"],[11,12,17,"惟居猶大諸邑之以色列人、羅波安爲其王、"],[11,12,18,"羅波安王遣司力役之亞多蘭至以色列人、以色列人以石擊斃之、羅波安王亟登車、遁於耶路撒冷、"],[11,12,19,"於是以色列人叛大衞家、至於今日、"],[11,12,20,"以色列衆聞耶羅波安歸、則遣人招之詣會衆、立爲以色列衆之王、猶大支派而外、無有從大衞家者、○"],[11,12,21,"羅波安至耶路撒冷、集猶大全家、及便雅憫支派、所簡戰士、十有八萬、欲與以色列家戰、俾國復歸所羅門子羅波安、"],[11,12,22,"上帝諭上帝僕示瑪雅曰、"],[11,12,23,"告猶大王、所羅門子羅波安、與猶大便雅憫全家、及餘民曰、"],[11,12,24,"耶和華云、勿往與兄弟以色列人戰、其各歸家、蓋是事由於我也、衆從耶和華言、遵命而歸、○"],[11,12,25,"耶羅波安在以法蓮山地、建示劍而居之、自此而出、建毘努伊勒、"],[11,12,26,"意謂此國將歸大衞家、"],[11,12,27,"倘斯民往耶路撒冷、獻祭於耶和華室、其心必歸厥主猶大王羅波安、則殺我而歸彼、"],[11,12,28,"王旣籌思、乃作金犢二、告民曰、爾曹上耶路撒冷甚難、以色列人歟、導爾出埃及之神卽此、"],[11,12,29,"遂置一犢於伯特利、一犢於但、"],[11,12,30,"此事陷人於罪、因民往但、崇拜其一、"],[11,12,31,"王於崇邱建廟、由衆民中、不屬利未族者、簡立祭司、"],[11,12,32,"又設節期於八月之望、若猶大之節期、而登其壇、在伯特利亦如是、獻祭於所作之犢、以所立爲邱壇之祭司、置於伯特利、"],[11,12,33,"八月之望、卽以己意所定之期、詣伯特利所作之壇、爲以色列族設筵、登壇焚香、"],[11,13,1,"耶羅波安立於壇側、欲焚香時、適有上帝僕、奉耶和華命、自猶大至伯特利、"],[11,13,2,"奉耶和華命、向壇而呼曰、壇乎、壇乎、耶和華云、大衞家必生一子、名約西亞、彼將取崇邱之祭司、焚香於爾上者、獻於爾上、人之骸骨、亦必焚於爾上焉、"],[11,13,3,"是日上帝僕示預兆曰、此壇必裂、灰必傾、是乃耶和華所言之預兆、"],[11,13,4,"王聞上帝僕向伯特利壇所呼之言、自壇伸手曰、執之、所伸之手卽枯、不能縮、"],[11,13,5,"壇亦裂、灰亦傾、應上帝僕、奉耶和華命所示之預兆、"],[11,13,6,"王謂上帝僕曰、請爾爲我祈禱、求爾上帝耶和華施恩、俾我手復原、上帝僕求於耶和華、王手遂愈如初、"],[11,13,7,"王謂上帝僕曰、偕我歸家、補爾精力、我必加以賞賚、"],[11,13,8,"上帝僕曰、爾卽以家之半賜我、我必不偕爾歸、亦不食餅飲水於此、"],[11,13,9,"蓋耶和華諭我曰、勿食餅飲水於此、勿循原途而返、"],[11,13,10,"乃由他途而歸、不循來伯特利之路、○"],[11,13,11,"有老先知居伯特利、其子至、以上帝僕當日在伯特利所行、及對王所言者、悉告其父、"],[11,13,12,"父問之曰、彼由何途而往、子以來自猶大之上帝僕、所往之途告父、"],[11,13,13,"父曰、爲我備驢、遂備驢、其父乘之、"],[11,13,14,"追上帝僕、遇其坐於橡下、問曰、自猶大來之上帝僕、乃爾乎、曰、是也、"],[11,13,15,"曰、請偕我歸、食餅、"],[11,13,16,"曰、我不得與爾歸、入爾室、亦不食餅飲水於此、"],[11,13,17,"蓋耶和華諭我云、勿食餅飲水於此、勿循原途而返、"],[11,13,18,"老先知曰、我亦先知如爾、有天使奉耶和華命、諭我曰、攜彼歸爾家、俾其食餅飲水、乃誑之也、"],[11,13,19,"上帝僕遂與偕歸、食餅飲水於其家、"],[11,13,20,"席間、耶和華諭攜其返之先知、"],[11,13,21,"遂向自猶大來之上帝僕呼曰、耶和華云、因爾違耶和華之言、不守爾上帝耶和華所命、"],[11,13,22,"乃返而食餅飲水、於耶和華禁爾食餅飲水之所、故爾尸不得入爾列祖之墓、"],[11,13,23,"飲食旣畢、老先知爲所攜歸之先知備驢、"],[11,13,24,"旣往、有獅在途、遇而殺之、尸仆於途、驢立其側、獅亦立其旁、"],[11,13,25,"有人過之、見尸仆於途、獅立於旁、則入老先知所居之邑以告、"],[11,13,26,"攜其離途而返之先知聞之、則曰、此上帝僕、違耶和華之言、故耶和華付之於獅、獅攫而殺之、如耶和華所諭、"],[11,13,27,"又謂其子曰、爲我備驢、遂備之、"],[11,13,28,"旣往、見尸仆於途、驢與獅立於旁、獅未食尸、亦不攫驢、"],[11,13,29,"先知取上帝僕之尸、置於驢、攜歸老先知之邑、哀悼而葬之、"],[11,13,30,"置尸於己塚、悼之曰、哀哉、我兄弟乎、"],[11,13,31,"葬畢、則謂其子曰、我死、當葬我於上帝僕所葬之墓、以我骨置其骨側、"],[11,13,32,"蓋彼奉耶和華命、指伯特利壇、及撒瑪利亞諸邑崇邱之廟、所言必應、○"],[11,13,33,"耶羅波安雖遇此事、仍不悛其惡行、復由衆民中、簡立崇邱之祭司、凡欲之者、則區別之、使爲崇邱祭司、"],[11,13,34,"是事陷耶羅波安家於罪、以致滅絕於地上、"],[11,14,1,"耶羅波安子亞比雅遘疾、"],[11,14,2,"耶羅波安謂妻曰、爾起改裝、免人知爾爲耶羅波安妻、往於示羅、在彼有先知亞希雅、卽昔告我必爲斯民之王者、"],[11,14,3,"當攜十餅、曁薄餅、與蜜一甁見之、彼必告爾、子將若何、"],[11,14,4,"耶羅波安妻如是而行、起往示羅、至亞希雅家、亞希雅年老、目眊不能視、"],[11,14,5,"耶和華告之曰、耶羅波安之妻將至、以子遘疾、而問於爾、彼入室時、必佯爲他婦、爾當依我言告之、"],[11,14,6,"入門、亞希雅聞其足音、曰、耶羅波安之妻其入、奚佯爲他婦哉、我已奉命、以凶事告爾、"],[11,14,7,"往告耶羅波安曰、以色列之上帝耶和華云、我自民中舉爾、立爲我民以色列之君、"],[11,14,8,"奪國於大衞家、以賜爾、而爾不效我僕大衞、守我誡命、一心從我、行我所悅、"],[11,14,9,"乃行惡較前人尤甚、立他神、鑄偶像、激我之怒、棄而背我、"],[11,14,10,"故我必降災於耶羅波安家、彼之丁男、無論被束者、自由者、悉絕之於以色列中、掃除耶羅波安全家、猶人掃除糞壤、以至淨盡、"],[11,14,11,"凡屬耶羅波安、死於邑者、犬必食之、死於野者、鳥必食之、耶和華言之矣、"],[11,14,12,"爾起旋歸、足入城時、子必死焉、"],[11,14,13,"以色列衆將爲哀悼而葬之、屬耶羅波安者、惟此子得入於墓、蓋在耶羅波安家中、彼向以色列之上帝耶和華、顯有善行、"],[11,14,14,"耶和華必興一人、爲以色列王、將絕耶羅波安家於彼日、何云彼日、卽今是也、"],[11,14,15,"耶和華必擊以色列、若葦搖於水中、拔之出於所錫列祖之美地、散之河外、因其作木偶、激耶和華之怒也、"],[11,14,16,"緣耶羅波安所犯之罪、使以色列人陷之、耶和華必棄以色列族、"],[11,14,17,"耶羅波安妻起而往、至得撒、履門閾、而子死焉、"],[11,14,18,"以色列衆葬之、爲之哀悼、如耶和華藉其僕先知亞希雅所言、"],[11,14,19,"耶羅波安其餘事蹟、及其戰績、與其政治、俱載於以色列列王紀、"],[11,14,20,"耶羅波安爲王二十二年、與列祖偕眠、子拿答嗣位、○"],[11,14,21,"所羅門子羅波安爲猶大王、卽位時、年四十有一、在耶路撒冷爲王、歷十七年、耶路撒冷卽耶和華自以色列諸支派中、所簡以爲寄名之所、羅波安母名拿瑪、亞捫女也、"],[11,14,22,"猶大人行耶和華所惡、犯罪激耶和華之忌、較其列祖尤甚、"],[11,14,23,"在高岡之上、綠樹之下、建崇邱、作柱像木偶、"],[11,14,24,"其地且有孌童、衆行異邦可憎之事、卽耶和華於以色列人前、所逐諸族之事、○"],[11,14,25,"羅波安王五年、埃及王示撒、上攻耶路撒冷、"],[11,14,26,"掠耶和華室及王宮之寶物、悉攜之去、又掠所羅門所製之金干、"],[11,14,27,"羅波安王製銅干以代之、付於守宮門之侍衞長、"],[11,14,28,"王入耶和華室時、侍衞執干、後則反諸侍衞之室、"],[11,14,29,"羅波安其餘事蹟、凡其所爲、俱載於猶大列王紀、"],[11,14,30,"羅波安與耶羅波安、常相戰鬬、"],[11,14,31,"羅波安與列祖偕眠、同葬於大衞城、子亞比央嗣位、羅波安之母拿瑪、亞捫女也、"],[11,15,1,"尼八子耶羅波安王十八年、亞比央卽位、爲猶大王、"],[11,15,2,"在耶路撒冷爲王、凡歷三年、其母名瑪迦、押沙龍女也、"],[11,15,3,"亞比央從其父所行諸罪、不效厥祖大衞、專心於其上帝耶和華、"],[11,15,4,"然以大衞之故、其上帝耶和華賜以燈光、在於耶路撒冷、俾其子嗣位、鞏固耶路撒冷、"],[11,15,5,"蓋大衞除於赫人烏利亞之事外、皆行耶和華所悅、畢生不違其所命、"],[11,15,6,"羅波安存日、與耶羅波安常相戰鬬、"],[11,15,7,"亞比央與耶羅波安、亦相戰鬬、亞比央其餘事蹟、凡其所爲、俱戴於猶大列王紀、"],[11,15,8,"亞比央與列祖偕眠、葬於大衞城、子亞撒嗣位、○"],[11,15,9,"以色列王耶羅波安二十年、亞撒卽位、爲猶大王、"],[11,15,10,"在耶路撒冷爲王、歷四十一年、其祖母瑪迦、押沙龍女也、"],[11,15,11,"亞撒行耶和華所悅、效其祖大衞所爲、"],[11,15,12,"驅孌童於斯土、除其列祖所作之偶像、"],[11,15,13,"貶其祖母瑪迦太后之位、緣其爲亞舍拉作可憎之像、亞撒斫其像、焚於汲淪溪旁、"],[11,15,14,"惟崇邱未廢、然亞撒畢生、專心於耶和華、"],[11,15,15,"以父所獻、及己所獻之金銀與器皿、進於耶和華室、"],[11,15,16,"亞撒與以色列王巴沙存日、常相戰鬬、"],[11,15,17,"以色列王巴沙上攻猶大、建拉瑪、使人不得出入於猶大王亞撒之所、"],[11,15,18,"亞撒取耶和華室及王宮府庫、所餘之金銀、付其臣僕、遣詣居大馬色之亞蘭王、希旬孫、他伯利們子便哈達、曰、"],[11,15,19,"爾我有約、如昔爾父與我父然、今我饋爾金銀、請廢爾與以色列王巴沙之約、使之去我、"],[11,15,20,"便哈達從亞撒王之言、遣其軍長攻以色列之邑、乃擊以雲、但、亞伯伯瑪迦、與基尼烈四境、拿弗他利全地、"],[11,15,21,"巴沙聞之、則止建拉瑪之工、而居得撒、"],[11,15,22,"亞撒王宣告猶大衆、不遺一人、遂取巴沙建拉瑪之木石、亞撒王以之建便雅憫之迦巴、與米斯巴、"],[11,15,23,"亞撒其餘事蹟、凡其所爲、與其勇力、及所建之邑、俱載於猶大列王紀、亞撒年老、而有足疾、"],[11,15,24,"與列祖偕眠、同葬於大衞城、子約沙法嗣位、○"],[11,15,25,"猶大王亞撒二年、耶羅波安子拿答卽位、爲以色列王、凡歷二年、"],[11,15,26,"拿答行耶和華所惡、循父之道、干父陷以色列人之罪、"],[11,15,27,"以薩迦族、亞希雅子巴沙叛、弒之於非利士人之基比頓、其時拿答與以色列衆、圍基比頓、"],[11,15,28,"猶大王亞撒三年、巴沙弒之、而篡其位、"],[11,15,29,"甫卽位、則戮耶羅波安全家、凡有血氣者、悉行翦滅、靡有孑遺、如耶和華藉其僕、示羅人亞希雅所言、"],[11,15,30,"因耶羅波安所犯之罪、使以色列人陷之、激以色列上帝耶和華之怒、"],[11,15,31,"拿答其餘事蹟、凡其所爲、俱載於以色列列王紀、"],[11,15,32,"亞撒與以色列王巴沙存日、常相戰鬬、○"],[11,15,33,"猶大王亞撒三年、亞希雅子巴沙、在得撒卽位、爲以色列王、歷二十四年、"],[11,15,34,"行耶和華所惡、循耶羅波安之道、干其陷以色列人之罪、"],[11,16,1,"耶和華諭哈拿尼子耶戶、責巴沙曰、"],[11,16,2,"昔我舉爾於塵埃、立爲我民以色列之君、而爾行耶羅波安之道、使我民以色列陷罪、激我之怒、"],[11,16,3,"我必掃除巴沙及其家、使如尼八子耶羅波安家然、"],[11,16,4,"凡屬巴沙、死於邑者、犬必食之、死於野者、鳥必食之、"],[11,16,5,"巴沙其餘事蹟、凡其所爲、及其勇力、俱載於以色列列王紀、"],[11,16,6,"巴沙與列祖偕眠、葬於得撒、子以拉嗣位、"],[11,16,7,"耶和華藉哈拿尼子先知耶戶、責巴沙及其家、因其行耶和華所惡、以其手所爲、激厥震怒、效耶羅波安家、而殺其人、○"],[11,16,8,"猶大王亞撒二十六年、巴沙子以拉、在得撒卽位、爲以色列王、凡歷二年、"],[11,16,9,"其僕心利、統戰車之半者叛之、以拉在得撒家宰亞雜之室飲醉、"],[11,16,10,"心利入室、擊而弒之、繼之爲王、事在猶大王亞撒二十七年、"],[11,16,11,"心利卽位、則擊巴沙全家、彼之戚屬友朋、不遺一男、"],[11,16,12,"心利滅巴沙全家、乃依耶和華藉先知耶戶、責巴沙之言、"],[11,16,13,"因巴沙及其子以拉所犯之罪、使以色列人陷之、且事虛無、激以色列上帝耶和華之怒、"],[11,16,14,"以拉其餘事蹟、凡其所爲、俱載於以色列列王紀、○"],[11,16,15,"猶大王亞撒二十七年、心利在得撒爲王、僅歷七日、時、民衆建營、攻屬非利士人之基比頓、"],[11,16,16,"在營之民、聞心利叛而弒王、是日以色列衆、於其營中、立軍長暗利爲以色列王、"],[11,16,17,"暗利率以色列衆、自基比頓、上圍得撒、"],[11,16,18,"心利見城已陷、乃入王宮之衞所、縱火焚宮而死、"],[11,16,19,"緣其犯罪、行耶和華所惡、循耶羅波安之道、干其陷以色列人之罪、"],[11,16,20,"心利其餘事蹟、及其叛逆、俱載於以色列列王紀、○"],[11,16,21,"時、以色列民分而爲二、半從基納子提比尼、欲立之爲王、半從暗利、"],[11,16,22,"從暗利之民、勝於從基納子提比尼之民、提比尼旣沒、暗利爲王、○"],[11,16,23,"猶大王亞撒三十一年、暗利卽位、爲以色列王、歷十有二年、在得撒爲王六年、"],[11,16,24,"以銀二他連得與撒瑪、購撒瑪利亞山、建邑於山、以山主撒瑪之名、稱其邑曰撒瑪利亞、"],[11,16,25,"暗利行耶和華所惡、較前王尤甚、"],[11,16,26,"循尼八子耶羅波安之道、干其陷以色列人之罪、且事虛無、激以色列上帝耶和華之怒、"],[11,16,27,"暗利其餘事蹟、及其所著之勇力、俱載於以色列列王紀、"],[11,16,28,"暗利與列祖偕眠、葬於撒瑪利亞、子亞哈嗣位、○"],[11,16,29,"猶大王亞撒三十八年、暗利子亞哈卽位、在撒瑪利亞爲以色列王、歷二十二年、"],[11,16,30,"行耶和華所惡、較前王尤甚、"],[11,16,31,"循尼八子耶羅波安之道、以爲細事、乃娶西頓王謁巴力女耶洗別爲后、從而服事崇拜巴力、"],[11,16,32,"在撒瑪利亞建巴力廟、爲之築壇於廟中、"],[11,16,33,"亦作木偶、亞哈所行、激以色列上帝耶和華之怒、較以色列前王尤甚、"],[11,16,34,"亞哈時、伯特利人希伊勒、重建耶利哥、立基時、則喪長子亞比蘭、置門時、則喪季子西割、應耶和華藉嫩之子約書亞所言、"],[11,17,1,"旅於基列之提斯比人以利亞、告亞哈曰、我指所事維生之耶和華、以色列之上帝而誓、此數年間、非我有言、則雨露不降、"],[11,17,2,"耶和華諭以利亞曰、"],[11,17,3,"去此東往、匿於約但東之基立溪濱、"],[11,17,4,"可飲溪水、我命烏食爾、"],[11,17,5,"遂遵耶和華命、往約但東之基立溪濱居焉、"],[11,17,6,"烏朝夕以餅與肉給之、所飲者、此溪之水、"],[11,17,7,"日久無雨降於其地、溪水盡涸、○"],[11,17,8,"耶和華諭以利亞曰、"],[11,17,9,"起往西頓之撒勒法、而居於彼、我已命在彼之嫠婦供養爾、"],[11,17,10,"遂起、往撒勒法、至邑門、見嫠婦採薪、呼之曰、請爾以器、取水少許以飲我、"],[11,17,11,"婦往時、又呼之曰、請爾手持片餅與我、"],[11,17,12,"曰、我指爾之上帝、維生之耶和華以誓、我無餅、惟餘一握之麪於罌、少許之油於甁、今採薪二、歸而爲我及子備之、食之而死、"],[11,17,13,"以利亞曰、勿懼、其往、如爾所言而行、先爲我作小餅、攜之至、後爲爾及子作餅、"],[11,17,14,"蓋以色列之上帝耶和華曰、罌內之麪不減、甁中之油不罄、迨耶和華降雨於地、"],[11,17,15,"婦往、遵以利亞言而行、婦與其家、及以利亞、食之多日、"],[11,17,16,"罌內之麪不減、甁中之油不罄、如耶和華藉以利亞所言、"],[11,17,17,"厥後、家主之子遘疾甚劇、至無氣息、"],[11,17,18,"婦謂以利亞曰、上帝僕歟、我與爾何與、爾來此、使憶我罪、而殺我子耶、"],[11,17,19,"曰、以子付我、遂取諸母懷、抱至所居之樓、置於己牀、"],[11,17,20,"籲耶和華曰、我上帝耶和華歟、我旅此嫠之家、汝豈降災於彼、以殺其子乎、"],[11,17,21,"乃伏於子身者三、籲耶和華曰、我上帝耶和華歟、祈使此子之魂、返於其軀、"],[11,17,22,"耶和華允其所祈、子魂乃返而甦、"],[11,17,23,"以利亞攜之下樓、入室、付於其母、曰、汝子復生矣、"],[11,17,24,"婦曰、我今知爾乃上帝僕、耶和華藉爾口所言者、眞實無妄、"],[11,18,1,"歷時旣久、越至三年、耶和華諭以利亞曰、往見亞哈、我將降雨於地、"],[11,18,2,"以利亞遂往、見於亞哈、時、撒瑪利亞饑甚、"],[11,18,3,"亞哈召家宰俄巴底、俄巴底深寅畏耶和華、"],[11,18,4,"昔耶洗別滅耶和華諸先知、俄巴底匿先知百人於穴、每穴五十人、以餅與水供之、"],[11,18,5,"亞哈謂俄巴底曰、遍巡斯土、至諸水泉溪澗、或得芻蕘、以救騾馬、免喪羣畜、"],[11,18,6,"於是分地巡行、亞哈與俄巴底、各往一途、"],[11,18,7,"俄巴底行於途間、以利亞遇焉、俄巴底識之、則俯伏曰、爾爲我主以利亞歟、"],[11,18,8,"曰、是也、往告爾主云、以利亞在此、"],[11,18,9,"曰、我干何罪、致爾付僕於亞哈手、以殺我乎、"],[11,18,10,"我指爾之上帝、維生之耶和華而誓、無一邦一族、我主不遣人索爾、若云不在者、則令是邦是族誓曰、未遇爾也、"],[11,18,11,"今爾云、往告爾主曰、以利亞在此、"],[11,18,12,"我離爾而往、耶和華之神、將攜爾至我所不知之地、我往告亞哈、彼索爾不得、則必殺我、然爾僕自幼寅畏耶和華、"],[11,18,13,"昔耶洗別殺耶和華先知時、我匿先知百人於穴、每穴五十人、以餅與水供之、我之所爲、無人告我主乎、"],[11,18,14,"今爾云往告爾主曰、以利亞在此、彼必殺我、"],[11,18,15,"以利亞曰、我指所事萬軍之主、維生之耶和華而誓、今日我必見於彼、"],[11,18,16,"俄巴底乃往迓亞哈而告之、亞哈遂往迓以利亞、"],[11,18,17,"見之則曰、困苦以色列者、乃爾乎、"],[11,18,18,"對曰、困苦以色列者、非我也、乃爾及爾父家、緣爾離棄耶和華之誡命、從諸巴力、"],[11,18,19,"今當遣人集以色列衆、與巴力之先知四百五十人、及木偶之先知四百人、食於耶洗別之席者、至迦密山見我、"],[11,18,20,"亞哈遂遣人詣以色列衆、集諸先知、至迦密山、"],[11,18,21,"以利亞前謂民衆曰、爾持兩端、躊躇莫決、將至何時、如以耶和華爲上帝、則從之、如以巴力爲上帝、則從彼、民不答一詞、"],[11,18,22,"以利亞謂民曰、耶和華之先知、僅遺我一人耳、巴力之先知、則有四百五十人、"],[11,18,23,"當以二牡牛與我儕、彼簡其一而臠之、置於柴、惟不縱火、我亦備一、置於柴、亦不縱火、"],[11,18,24,"爾籲爾神之名、我則籲耶和華之名、以火俞允者、則爲上帝、民咸曰、所言善也、"],[11,18,25,"以利亞謂巴力之先知曰、爾曹衆多、先簡一牛備之、而籲爾神之名、惟不縱火、"],[11,18,26,"乃取所予之牛備之、自朝至午、籲巴力之名曰、巴力歟、其聽我、然無聲響、無應者、彼則踊於壇之四周、"],[11,18,27,"亭午、以利亞戲之曰、大聲而呼、彼乃神、或默想、或暫出、或遠行、或假寐、必使之醒、"],[11,18,28,"遂大聲而呼、以刃與戟自刺、迨及血流、循其常例、"],[11,18,29,"自午後至獻素祭時、託神而言、仍無聲響、無應者、無顧者、"],[11,18,30,"以利亞謂衆曰、其來就我、民咸就之、以利亞修葺耶和華傾圮之壇、"],[11,18,31,"昔耶和華諭雅各曰、爾名以色列、以利亞循雅各裔支派之數、取石十二、"],[11,18,32,"奉耶和華之名築壇、四周作溝、可容穀種二細亞、"],[11,18,33,"列柴、臠牛置於柴上、曰、以水充四甕、傾於燔祭及柴、"],[11,18,34,"又曰、再行之、則行之再、復曰、三行之、則行之三、"],[11,18,35,"水流於壇之四周、以充其溝、"],[11,18,36,"獻素祭時、先知以利亞前曰、亞伯拉罕以撒以色列之上帝、耶和華歟、願爾今日顯示、爾在以色列中爲上帝、我爲爾僕、凡我所爲、悉遵爾命、"],[11,18,37,"耶和華歟、尚其聽我、尚其聽我、使斯民皆知、爾耶和華乃上帝、爾使其心翻然而轉、"],[11,18,38,"耶和華之火遂降、焚其燔祭、以及其柴、其石、其塵土、亦涸溝中之水、"],[11,18,39,"民衆見此、則俯伏曰、耶和華乃上帝、耶和華乃上帝、"],[11,18,40,"以利亞謂衆曰、執巴力之先知、毋使一人逸、遂執之、以利亞曳至基順溪、殺之於彼、○"],[11,18,41,"以利亞謂亞哈曰、上而飲食、蓋有霖雨之聲也、"],[11,18,42,"亞哈乃往飲食、以利亞陟迦密巔、屈身在地、面伏膝間、"],[11,18,43,"謂其僕曰、上而望海、則上而望、曰、無所見也、曰、再往、歷至七次、"],[11,18,44,"迨及七次、則曰、有雲自海而起、小若人掌、曰、上告亞哈云、備車而下、免爲雨阻、"],[11,18,45,"頃之、風雲驟起、黑遍穹蒼、沛然下雨、亞哈乘車、往耶斯列、"],[11,18,46,"耶和華加手於以利亞、遂束腰、趨於亞哈前、至耶斯列邑門、"],[11,19,1,"亞哈以以利亞所爲、及以刃殺諸先知之事、告耶洗別、"],[11,19,2,"耶洗別遣人謂以利亞曰、明日斯時、我若不喪爾命、如爾喪彼衆之命、則願諸神罰我維倍、"],[11,19,3,"以利亞聞之、則起而遁、以保其命、至猶大之別是巴、留其僕於彼、獨行曠野一日之程、坐於羅騰樹下、祈死曰、耶和華歟、已矣、望取我命、蓋我不愈於我列祖也、"],[11,19,4,"遂臥於羅騰樹下而睡、有天使撫之曰、起而食、"],[11,19,5,"則見有炭炙之餅、及水一甁、在於首側、遂飲食而復臥、"],[11,19,6,"耶和華之使者再至、撫之曰、起而食、爾行斯途、力有未逮、"],[11,19,7,"遂起飲食、藉其力行四十晝夜、詣上帝之山何烈、"],[11,19,8,"入穴而居、耶和華諭之曰、以利亞、爾在此何爲、"],[11,19,9,"曰、我爲萬軍之上帝耶和華、熱中特甚、蓋以色列人背爾約、毀爾壇、以刃殺爾先知、僅遺我一人、彼索我命、欲奪取之、"],[11,19,10,"曰、爾其出穴、立於山崗、在耶和華前、時、耶和華過焉、其前有風、大而且猛、裂山碎石、惟耶和華不在風中、風後地震、耶和華不在其中、"],[11,19,11,"地震之後有火、耶和華不在火中、火後有聲、微細而肅、"],[11,19,12,"以利亞聞之、以衣蒙面而出、立於穴口、有聲謂之曰、"],[11,19,13,"以利亞、爾在此何爲、"],[11,19,14,"曰、我爲萬軍之上帝耶和華、熱中特甚、蓋以色列人背爾約、毀爾壇、以刃殺爾先知、僅遺我一人、彼索我命、欲奪取之、"],[11,19,15,"耶和華曰、爾其旋歸、由曠野而往大馬色、旣至、則膏哈薛、爲亞蘭王、"],[11,19,16,"亦膏寧示子耶戶、爲以色列王、又膏亞伯米何拉人、沙法子以利沙、代爾爲先知、"],[11,19,17,"避哈薛之刃者、必爲耶戶所殺、避耶戶之刃者、必爲以利沙所殺、"],[11,19,18,"然在以色列中、我遺七千人、其膝未嘗屈於巴力、其口未嘗吻之、"],[11,19,19,"以利亞遂去彼、遇沙法子以利沙耕於田、其前有牛十二雙、以利沙御其最後者、以利亞過之、以己衣置於其身、"],[11,19,20,"乃棄牛、趨於以利亞後、曰、請容我與父母接吻、後必從爾、曰、歸哉、我於爾何爲乎、"],[11,19,21,"遂離之而歸、取牛一雙宰之、以駕牛之具烹其肉、與民食之、乃起、從以利亞、而服事之、"],[11,20,1,"亞蘭王便哈達集其全軍、有三十二王偕之、統率車騎、上圍撒瑪利亞、攻之、"],[11,20,2,"遣使入城、見以色列王亞哈曰、便哈達云、"],[11,20,3,"爾之金銀屬我、爾妻孥之佳者亦屬我、"],[11,20,4,"以色列王曰、我主我王歟、我與所有、咸屬於爾、如爾所言、"],[11,20,5,"使者復至、曰、便哈達云、我已遣人曰、必以爾之金銀妻孥、悉付於我、"],[11,20,6,"惟明日斯時、我將遣我臣僕、遍索爾宮、與爾臣僕之室、凡爾目所悅者、必取之而去、"],[11,20,7,"以色列王召國中之長老曰、請觀斯人、如何謀害、遣人詣我、欲取我妻孥金銀、我未之辭、"],[11,20,8,"長老與民衆對曰、勿聽之、勿允焉、"],[11,20,9,"王謂便哈達之使曰、反告我主我王曰、爾先遣之使索於僕者、僕願爲之、惟今所索者、我不能爲、使者反而復命、"],[11,20,10,"便哈達更遣人曰、撒瑪利亞之塵、若足從我之衆、各取一掬、則願諸神罰我維倍、"],[11,20,11,"以色列王曰、爾告之云、披甲者、勿效卸甲者而誇、"],[11,20,12,"便哈達與列王飲於幕、聞所對、則命臣僕曰、列陳、遂列陳攻城、"],[11,20,13,"有先知進見以色列王亞哈曰、耶和華云、此羣衆、爾見之乎、今日我必付於爾手、爾則知我乃耶和華、"],[11,20,14,"亞哈曰、藉誰乎、曰、耶和華云、藉諸州方伯之少者、曰、誰啟戰、曰、爾、"],[11,20,15,"遂核諸州方伯之少者、得二百三十二人、後核以色列民衆、得七千人、"],[11,20,16,"日中而出、便哈達與助之之三十二王、在幕飲醉、"],[11,20,17,"方伯之少者爲前鋒、便哈達使窺之、返曰、有人自撒瑪利亞出、"],[11,20,18,"曰、彼出、或欲修和、或欲戰鬬、當生執之、"],[11,20,19,"方伯之少者出城、軍旅從其後、"],[11,20,20,"各殺其敵、亞蘭人遁、以色列人追之、亞蘭王便哈達乘馬、與騎兵遁而獲免、"],[11,20,21,"以色列王出邑、擊亞蘭車騎、大戮其衆、○"],[11,20,22,"先知進見以色列王曰、往哉、自強、愼爾所爲、歲月旣周、亞蘭王必來攻爾、"],[11,20,23,"亞蘭王臣僕謂之曰、彼之神、乃山嶽之神、故強於我、當在平原與戰、則我必強於彼、"],[11,20,24,"可如是而行、去厥列王、以軍長代之、"],[11,20,25,"宜核一軍、與所喪者相同、以馬代馬、以車代車、我在平原與戰、必強於彼、王從其言而行、"],[11,20,26,"歲月旣周、便哈達核亞蘭之衆、往亞弗、與以色列人戰、"],[11,20,27,"以色列族亦核其衆、備糧食、而往逆之、以色列族建營於敵前、若山羊羔二小羣、惟亞蘭人充斥遍地、"],[11,20,28,"有上帝僕進見以色列王曰、耶和華云、亞蘭人謂耶和華乃山嶽之神、非平原之神、故我必以此羣衆付於爾手、爾則知我乃耶和華、"],[11,20,29,"兩軍相對建營、歷至七日、然後交戰、是日以色列人、殺亞蘭人步卒十萬、"],[11,20,30,"其餘遁入亞弗邑、城垣傾圮、壓斃二萬七千人、便哈達遁入城、匿於內室、"],[11,20,31,"其臣僕曰、我聞以色列家之王、咸懷矜恤、我儕曷若腰束麻、首繫索、乞降於以色列王、庶存爾命、"],[11,20,32,"遂束麻於腰、繫索於首、詣以色列王曰、爾僕便哈達云、請存我命、曰、彼尚在乎、我兄弟也、"],[11,20,33,"其人諦聽其言、迅卽乘機而應曰、便哈達爾兄弟也、曰、往攜之至、便哈達遂出見王、王令登車、"],[11,20,34,"便哈達曰、昔我先人所奪爾父之邑、我必反爾、我先人在撒瑪利亞爲市、今爾在大馬色亦可爲市、亞哈曰、有此盟約、可釋爾歸、於是立約、而使之歸、○"],[11,20,35,"有先知徒一人、奉耶和華命、謂同儕曰、爾其撲我、同儕不從、"],[11,20,36,"曰、因爾不聽耶和華命、爾離我時、必見殺於獅、同儕離之、果遇獅被殺、"],[11,20,37,"又遇一人、曰、爾其撲我、遂撲而傷之、"],[11,20,38,"先知乃往、俟王於途、改其儀容、以巾掩目、"],[11,20,39,"王過之、則呼曰、僕在陳時、有人執敵、轉詣我曰、爾守此人、如其失之、必以爾命代其命、或罰爾銀一他連得、"],[11,20,40,"爾僕怱迫之間、其人已逸、以色列王曰、依爾所言爲讞、汝自定之、"],[11,20,41,"其人急去巾於目、以色列王乃知其爲先知、"],[11,20,42,"彼謂王曰、耶和華云、我定當滅之人、爾由爾手釋之、故必以爾命代其命、以爾民代其民、"],[11,20,43,"以色列王抑鬱不樂、歸撒瑪利亞、返其宮、"],[11,21,1,"此後、耶斯列人拿伯、有葡萄園在耶斯列、鄰於撒瑪利亞王亞哈之宮、"],[11,21,2,"亞哈謂拿伯曰、爾之葡萄園、鄰於我宮、給我爲圃、我易以尤佳之園、爾若欲得其值、我則予爾以金、"],[11,21,3,"拿伯曰、願耶和華禁我、以我祖之遺業給爾、"],[11,21,4,"亞哈聞耶斯列人拿伯言、我不以祖遺業給爾、乃抑鬱不樂、回宮臥牀、面壁不食、"],[11,21,5,"其后耶洗別詣之曰、心憂不食、曷故、"],[11,21,6,"曰、我謂耶斯列人拿伯曰、以爾葡萄園給我以易金、或爾欲之、易以他園、彼曰、不以我之葡萄園給爾、"],[11,21,7,"其后耶洗別曰、爾今治以色列國乎、其起而食、中心歡暢、我必以耶斯列人拿伯之葡萄園給爾、"],[11,21,8,"遂假亞哈名作書、鈐以王印、致於拿伯邑中、與彼偕居之長老顯者、"],[11,21,9,"書曰、宣告禁食、在民間舉拿伯於高坐、"],[11,21,10,"置二匪徒於其前、對之證曰、爾詛上帝及王、卽曳之出、以石擊斃之、"],[11,21,11,"邑中之長老顯者、遵耶洗別所致之書而行、"],[11,21,12,"宣告禁食、在民間舉拿伯於高坐、"],[11,21,13,"有匪徒二人入、對之而坐、於衆前作證、訟拿伯曰、拿伯詛上帝與王、乃曳之出邑、以石擊斃之、"],[11,21,14,"遣人告耶洗別曰、拿伯已石擊而死、"],[11,21,15,"耶洗別聞之、則告亞哈曰、起據耶斯列人拿伯之葡萄園、卽不欲給爾以易金者、蓋拿伯已死、而不在矣、"],[11,21,16,"亞哈聞拿伯死、乃起、欲往耶斯列人拿伯之園、據而有之、○"],[11,21,17,"耶和華諭提斯比人以利亞曰、"],[11,21,18,"居撒瑪利亞之以色列王亞哈、今在拿伯之園、欲據而有之、爾起往迓、"],[11,21,19,"告之曰、耶和華云、汝旣殺人、又據其業乎、又告之曰、耶和華云、犬於何處舐拿伯之血、亦必於彼舐爾之血、"],[11,21,20,"亞哈謂以利亞曰、我敵、爾遇我乎、曰、我遇爾矣、因爾自鬻、行耶和華所惡、"],[11,21,21,"耶和華云、我必降災於爾、掃除乎爾、爾之丁男、無論被束者、自由者、悉絕之於以色列中、"],[11,21,22,"亦必使爾家、如尼八子耶羅波安之家、亦如亞希雅子巴沙之家、緣爾激我震怒、使以色列族陷罪、"],[11,21,23,"論及耶洗別、耶和華云、耶洗別必爲犬所噬、在耶斯列城側、"],[11,21,24,"凡屬亞哈、死於邑者、犬必食之、死於野者、鳥必食之、"],[11,21,25,"從未有若亞哈自鬻、行耶和華所惡者、爲其后耶洗別所慫恿也、"],[11,21,26,"彼從偶像、行極可憎之事、效亞摩利人所爲、卽耶和華於以色列人前、所逐之族之事、"],[11,21,27,"亞哈聞言、則裂其衣、衣麻禁食、臥亦衣麻、行亦柔謹、"],[11,21,28,"耶和華諭提斯比人以利亞曰、"],[11,21,29,"亞哈自卑於我前、爾見之乎、緣此、於彼尚存之日、我不降災、迨其子時、乃降災於其家、"],[11,22,1,"亞蘭與以色列國、三年無有戰事、"],[11,22,2,"越至三年、猶大王約沙法、下詣以色列王、"],[11,22,3,"以色列王謂其臣僕曰、爾豈不知基列拉末屬我、我乃寂然、不奪之於亞蘭王手乎、"],[11,22,4,"遂問約沙法曰、爾願與我偕往基列拉末以戰乎、曰、爾我無異、我民如爾民、我馬如爾馬、"],[11,22,5,"又曰、請先諮諏耶和華、"],[11,22,6,"以色列王乃集先知、約四百人、謂之曰、我往基列拉末以戰、可否、曰、往哉、主必付之於王手、"],[11,22,7,"約沙法曰、在此、非尚有耶和華之先知、可詢之乎、"],[11,22,8,"以色列王曰、尚有一人、音拉子米該雅、可藉之諮諏耶和華、然我憾之、因其論我之預言、有凶而無吉、約沙法曰、王勿言是、"],[11,22,9,"以色列王召一宦者、曰、速令音拉子米該雅至、"],[11,22,10,"以色列王與猶大王約沙法、各衣朝服、坐於位、在撒瑪利亞邑門之場、衆先知預言於其前、"],[11,22,11,"基拿拿子西底家曾製鐵角、曰、耶和華云、爾必以此角觸亞蘭人、至於盡滅、"],[11,22,12,"衆先知亦如是預言曰、可往基列拉末、而得利達、蓋耶和華將付之於王手、"],[11,22,13,"往召米該雅之使謂之曰、諸先知衆口一辭、以吉語告王、請爾與彼同辭、告以吉語、"],[11,22,14,"米該雅曰、我指維生之耶和華而誓、耶和華所諭我者、我必言之、"],[11,22,15,"旣至王前、王曰、米該雅、我儕往基列拉末以戰、可否、曰、可往、而得利達、耶和華必付之王手、"],[11,22,16,"王曰、我須幾次囑爾、奉耶和華名與我言、惟以誠實乎、"],[11,22,17,"曰、我觀以色列衆散布於山、猶羊無牧、耶和華曰、斯衆無主、可各安歸其家、"],[11,22,18,"以色列王謂約沙法曰、我豈不云、彼論我之預言、有凶無吉乎、"],[11,22,19,"米該雅曰、其聽耶和華之言、我見耶和華坐於其位、天上萬軍咸侍左右、"],[11,22,20,"耶和華曰、誰願誘亞哈往基列拉末、而隕沒乎、其一曰如此、其一曰如彼、"],[11,22,21,"後有神出、立於耶和華前曰、我願誘之、"],[11,22,22,"曰、何以誘之、曰、我將出爲誑言之神、在其衆先知之口、曰、爾往爲之、必成其事、"],[11,22,23,"今耶和華以誑言之神、置爾衆先知之口、耶和華有言、將加禍於爾、"],[11,22,24,"基拿拿子西底家、前批米該雅之頰曰、耶和華之神、自我往與爾言、由於何途、"],[11,22,25,"米該雅曰、爾匿密室之日、則必見之、"],[11,22,26,"以色列王曰、執米該雅、歸付邑宰亞們、及王子約阿施、"],[11,22,27,"告之曰、王命拘此夫於獄、食以艱苦之餅、飲以艱苦之水、待我安歸、"],[11,22,28,"米該雅曰、如爾安歸、則是耶和華未藉我而言、又曰、諸民、爾其聽之、○"],[11,22,29,"以色列王與猶大王約沙法、往基列拉末、"],[11,22,30,"以色列王謂約沙法曰、我將改裝入陳、惟爾當衣王服、以色列王遂改裝入陳、"],[11,22,31,"亞蘭王曾命車長三十二人曰、尊卑俱勿與戰、惟與以色列王而已、"],[11,22,32,"車長見約沙法、則曰、此必以色列王也、遂轉戰之、約沙法號呼、"],[11,22,33,"車長見非以色列王、則返而不追、"],[11,22,34,"有人偶爾挽弓、射中以色列王甲縫、王謂御者曰、我重傷矣、旋車載我出軍、"],[11,22,35,"是日戰勢劇烈、王被扶立於車、以禦亞蘭人、創劇血流、至於車底、迨夕而死、"],[11,22,36,"日入之際、有令傳於軍中曰、各歸故邑故土、"],[11,22,37,"王薨、舁至撒瑪利亞、而葬於彼、"],[11,22,38,"有人在撒瑪利亞池、洗濯其車、犬舐其血、如耶和華所言、此池、娼妓素浴其中、"],[11,22,39,"亞哈其餘事蹟、凡其所爲、與建象牙之宮、曁築諸邑、俱載於以色列列王紀、"],[11,22,40,"亞哈與列祖偕眠、子亞哈謝嗣位、○"],[11,22,41,"以色列王亞哈四年、亞撒子約沙法卽位、爲猶大王、"],[11,22,42,"時、年三十有五、在耶路撒冷爲王、歷二十五年、其母阿蘇巴、示利希女也、"],[11,22,43,"約沙法循其父亞撒之道、不偏離之、行耶和華所悅、惟崇邱未廢、民仍獻祭焚香於其上、"],[11,22,44,"約沙法與以色列王修好、"],[11,22,45,"約沙法其餘事蹟、及所著之勇力、與其戰績、俱載於猶大列王紀、"],[11,22,46,"其父亞撒時所遺孌童、約沙法盡除之於國中、"],[11,22,47,"當時以東無王、方伯主治、"],[11,22,48,"約沙法造他施舟、欲往俄斐取金、因在以旬迦別舟破、不果、"],[11,22,49,"亞哈子亞哈謝告約沙法曰、容我僕與爾僕、同舟偕往、約沙法不許、"],[11,22,50,"約沙法與列祖偕眠、同葬於大衞城、子約蘭嗣位、○"],[11,22,51,"猶大王約沙法十七年、亞哈子亞哈謝卽位、在撒瑪利亞、爲以色列王、凡歷二年、"],[11,22,52,"行耶和華所惡、循其父母之道、與尼八子耶羅波安使以色列族陷罪之道、"],[11,22,53,"奉事崇拜巴力、激以色列上帝耶和華之怒、皆如其父所行、"],[12,1,1,"亞哈旣卒、摩押叛以色列、"],[12,1,2,"亞哈謝在撒瑪利亞、墜樓櫺致疾、乃遣使曰、往詢以革倫神巴力西卜、我病得愈否、"],[12,1,3,"耶和華之使者諭提斯比人以利亞曰、起迎撒瑪利亞王之使、謂之曰、以色列中豈無上帝、乃往詢以革倫神巴力西卜乎、"],[12,1,4,"故耶和華云、爾所登之牀、不得再下、必死矣、以利亞遂往、"],[12,1,5,"使者返、王曰、爾返何爲、"],[12,1,6,"曰、有人迎而告我曰、返見遣爾之王曰、耶和華云、以色列中豈無上帝、乃遣人詢以革倫神巴力西卜乎、故爾所登之牀、不得再下、必死矣、"],[12,1,7,"曰、迎爾而告以斯言者、其人形狀如何、"],[12,1,8,"曰、身衣毛衣、腰束革帶、王曰、是乃提斯比人以利亞也、"],[12,1,9,"遂遣五十夫長、率五十人詣之、見其坐於山巔、謂之曰、上帝僕歟、王命爾下、"],[12,1,10,"以利亞謂五十夫長曰、如我爲上帝僕、願火從天降、燬滅爾及爾之五十人、於是火降自天、燬滅五十夫長、曁五十人、"],[12,1,11,"王復遣五十夫長、率五十人往、謂之曰、上帝僕歟、王命爾速下、"],[12,1,12,"以利亞曰、如我爲上帝僕、願火從天降、燬滅爾及爾之五十人、於是上帝之火降自天、燬滅五十夫長、曁五十人、"],[12,1,13,"王又遣五十夫長、率五十人、旣至、登山、屈膝於以利亞前、懇求曰、上帝僕歟、祈視我命、曁此五十僕之命爲寶、"],[12,1,14,"火從天降、燬滅五十夫長、及其五十人、如是者再、今祈視我命爲寶、"],[12,1,15,"耶和華之使者、謂以利亞曰、爾偕之下、勿懼之、以利亞遂起偕下、往而見王、"],[12,1,16,"謂之曰、耶和華云、以色列中豈無上帝、可以諮諏、乃遣使詢以革倫神巴力西卜乎、故爾所登之牀、不得再下、必死矣、"],[12,1,17,"王遂死、如以利亞所傳耶和華之言、王無子、弟約蘭嗣位、在猶大王、約沙法子約蘭之二年、"],[12,1,18,"亞哈謝其餘事蹟、俱載於以色列列王紀、"],[12,2,1,"耶和華欲以旋風、接以利亞升天時、以利亞偕以利沙、由吉甲而往、"],[12,2,2,"以利亞謂以利沙曰、耶和華遣我至伯特利、請爾待此、以利沙曰、我指維生之耶和華、及爾生命而誓、我不離爾、於是二人下伯特利、"],[12,2,3,"居伯特利之先知徒、出迓以利沙曰、耶和華今日將接爾師、與爾相離、爾知之乎、曰、我知之、爾其緘默、"],[12,2,4,"以利亞謂以利沙曰、耶和華遣我至耶利哥、請爾待此、曰、我指維生之耶和華、及爾生命而誓、我不離爾、於是二人至耶利哥、"],[12,2,5,"居耶利哥之先知徒、詣以利沙曰、耶和華今日將接爾師、與爾相離、爾知之乎、曰、我知之、爾其緘默、"],[12,2,6,"以利亞謂之曰、耶和華遣我至約但、請爾待此、曰、我指維生之耶和華、及爾生命而誓、我不離爾、於是二人前往、"],[12,2,7,"先知徒五十人、往而遙立、與之相對、二人立於約但河濱、"],[12,2,8,"以利亞卷其外衣擊水、水分左右、二人履陸而過、"],[12,2,9,"旣過、以利亞謂以利沙曰、我未被接離爾之先、爾欲我爲爾何爲、則求之、以利沙曰、求使感爾之神、臨我維倍、"],[12,2,10,"曰、爾所求者、難矣哉、雖然、我被接離爾之時、爾若見我、則必得之、否則不得、"],[12,2,11,"二人且行且語、忽有火車火馬間之、以利亞乘旋風升天、"],[12,2,12,"以利沙見而呼曰、我父歟、我父歟、以色列之車騎也、後不復見、遂取己衣、裂之爲二、"],[12,2,13,"又拾以利亞所墜之衣、返而立於約但河濱、"],[12,2,14,"以其衣擊水曰、以利亞之上帝耶和華安在、水旣見擊、亦分左右、以利沙過焉、"],[12,2,15,"居耶利哥之先知徒望見之、則曰、以利亞之神臨以利沙矣、遂來迎之、伏於其前、"],[12,2,16,"謂之曰、爾僕有壯士五十在此、請爾容其往尋爾師、或耶和華之神取而投之某山某谷、曰、勿遣之、"],[12,2,17,"彼衆促之、致其愧怍、則曰、可遣之、遂遣五十人尋之、三日不遇、"],[12,2,18,"以利沙俟於耶利哥、被遣者返、以利沙曰、我豈未告爾勿往乎、○"],[12,2,19,"邑民謂以利沙曰、試觀此邑、地勢佳美、我主所見也、惟其水惡劣、土產不稔而隕、"],[12,2,20,"曰、取新盂盛鹽予我、遂取而予之、"],[12,2,21,"以利沙出至水泉、投鹽其中、曰、耶和華云、我治此水、自茲以往、不復令人死、不使土產不稔而隕、"],[12,2,22,"其水卽佳、至於今日、如以利沙所言、○"],[12,2,23,"以利沙由此上伯特利、行於途間、有童子自邑出、戲之曰、頭童者其上歟、頭童者其上歟、"],[12,2,24,"以利沙回顧、奉耶和華名詛之、遂有牝熊二、自林中出、裂童子四十二、"],[12,2,25,"以利沙自此往迦密山、由彼返撒瑪利亞、"],[12,3,1,"猶大王約沙法十八年、亞哈子約蘭在撒瑪利亞卽位、爲以色列王、歷十二年、"],[12,3,2,"行耶和華所惡、然不似其父母、蓋其父所製巴力之柱、彼除去之、"],[12,3,3,"惟從尼八子耶羅波安陷以色列人之罪、不離棄之、○"],[12,3,4,"摩押王米沙、畜羊者也、以羔羊十萬、牡羊十萬之毛、貢以色列王、"],[12,3,5,"亞哈旣沒、摩押王叛以色列王、"],[12,3,6,"時、約蘭王出撒瑪利亞、核以色列衆、"],[12,3,7,"遣人詣猶大王約沙法曰、摩押王叛我、爾願偕我往攻摩押乎、曰、願往、爾我無異、我民如爾民、我馬如爾馬、"],[12,3,8,"曰、當由何路而往、曰、由以東之曠野、"],[12,3,9,"於是以色列王、與猶大王以東王偕往、紆道而行、歷程七日、軍旅及所隨之牲畜、無水以飲、"],[12,3,10,"以色列王曰、哀哉、耶和華集此三王、欲付於摩押人手、"],[12,3,11,"約沙法曰、在此、非有耶和華之先知、可藉以諮諏耶和華乎、以色列王之一僕對曰、昔傾水於以利亞之手者、沙法子以利沙在此、"],[12,3,12,"約沙法曰、彼有耶和華之言、以色列王與約沙法、及以東王、遂往見之、"],[12,3,13,"以利沙謂以色列王曰、我與爾何與、其詣爾父母之先知、以色列王曰、不然、耶和華集此三王、欲付於摩押人手、"],[12,3,14,"以利沙曰、我指所事萬軍之主、維生之耶和華而誓、我若不視猶大王約沙法在此、必不顧爾、不見爾、"],[12,3,15,"今當召一鼓琴者至、鼓琴時、耶和華之手臨之、"],[12,3,16,"以利沙曰、耶和華云、於此谷中、遍掘溝洫、"],[12,3,17,"蓋耶和華云、爾不見風、亦不見雨、水必盈於斯谷、爾及牲畜飲之、"],[12,3,18,"耶和華視此猶爲細事、亦必付摩押人於爾手、"],[12,3,19,"凡諸堅城美邑、爾必毀之、伐其嘉木、塞其水泉、以石毀其腴壤、"],[12,3,20,"詰朝獻素祭時、有水自以東道而來、充溢斯地、"],[12,3,21,"摩押人聞三王至、欲與之戰、則集民衆、自甫能執兵者以上、悉立於邊界、"],[12,3,22,"及旦、日照於水、摩押人夙興、遙望其水、色紅如血、"],[12,3,23,"曰、此乃血也、三王必亡、互相攻擊、摩押人乎、其往掠之、"],[12,3,24,"旣至以色列營、以色列人起而攻之、使遁於其前、從而追擊、入於摩押境、"],[12,3,25,"毀其城邑、各擲石以填其腴壤、塞其水泉、伐其嘉木、僅存吉珥哈列設石垣、發石之卒環而攻之、"],[12,3,26,"摩押王見戰勢劇烈、則率執刃之士七百、欲衝過之、至以東王、而不能焉、"],[12,3,27,"乃取當繼位之冢子、獻爲燔祭於垣上、以色列人深恨之、於是三王去之、各返故土、"],[12,4,1,"有一婦、先知徒之妻也、呼以利沙曰、爾僕我夫已死、彼素寅畏耶和華、爾所知也、今債主至、欲取我二子爲奴、"],[12,4,2,"以利沙曰、我可爲爾何爲、家中何所有、其告我、曰、婢家無長物、惟油一甁、"],[12,4,3,"曰、爾往於外、假空器於諸鄰、勿少假焉、"],[12,4,4,"入室閉門、爾與爾子在內、傾油於諸器、盈則移於側、"],[12,4,5,"乃別以利沙、閉門與子在室、子運器、婦傾油、"],[12,4,6,"諸器旣盈、婦謂子曰、再取一器、子曰、無之、油卽止、"],[12,4,7,"婦遂往告上帝僕、上帝僕曰、鬻油償債、所餘者、爾與子賴以度日、○"],[12,4,8,"一日以利沙經書念、在彼有一貴婦、強之食、後每經其所、則入而食、"],[12,4,9,"婦謂夫曰、我知屢經我所者、乃上帝聖僕也、"],[12,4,10,"我儕當於屋巔、建一小室、內置牀几椅及燈臺、彼至我所、可寓其間、"],[12,4,11,"一日以利沙至、入室而臥、"],[12,4,12,"謂其僕基哈西曰、召書念婦來、遂召之至、立於其前、"],[12,4,13,"以利沙謂其僕曰、告之云、爾旣爲我思慮周密、我當爲爾何爲、爾於王、或軍長、有所求乎、婦曰、我居於我民中、安甚、"],[12,4,14,"以利沙曰、然則爲之何爲、基哈西曰、婦無子、其夫已老矣、"],[12,4,15,"曰、再召之至、旣至立於門、"],[12,4,16,"以利沙曰、歲月旣周、至於此時、爾必抱子、曰、不然、我主上帝僕歟、勿誑爾婢、"],[12,4,17,"婦果懷姙、屆期生子、如以利沙所言、"],[12,4,18,"子稍長、一日往穫者所、見其父、"],[12,4,19,"謂父曰、我首、我首、父謂僕曰、抱至其母、"],[12,4,20,"旣抱之付其母、子坐母膝、日中而死、"],[12,4,21,"母抱之而上、置於上帝僕之牀、閉門而出、"],[12,4,22,"呼夫曰、請遣一僕、攜一驢至、我趨詣上帝僕而返、"],[12,4,23,"夫曰、今日非月朔、非安息日、爾往見之何爲、曰、此行平安、"],[12,4,24,"遂備驢、謂僕曰、驅驢前往、非我命爾、則勿緩、"],[12,4,25,"乃往迦密山、詣上帝僕、上帝僕遙見之、謂僕基哈西曰、試觀書念婦至矣、"],[12,4,26,"汝趨迎之、問曰、爾安乎、爾夫安乎、爾子安乎、婦曰、安、"],[12,4,27,"婦登山、詣上帝僕、則抱其足、基哈西近而推之、上帝僕曰、聽之、其心憂苦、而耶和華隱之、未以示我、"],[12,4,28,"婦曰、我豈求於我主、欲得子乎、我非曰勿誑我乎、"],[12,4,29,"以利沙謂基哈西曰、束爾腰、執我杖而往、遇人勿問安、人問安勿答之、置我杖於子面、"],[12,4,30,"子之母曰、我指維生之耶和華、與爾生命而誓、我不離爾、以利沙遂起隨之、"],[12,4,31,"基哈西先往、置杖於子面、而無聲無覺、乃返迎以利沙、告之曰、子未醒、"],[12,4,32,"以利沙入室、見子已死、臥於其牀、"],[12,4,33,"遂閉門、惟其二人在內、祈禱耶和華、"],[12,4,34,"旣而登牀、伏於子身、口與口、目與目、手與手、皆相對、又伏於子身、子體漸温、"],[12,4,35,"乃下、往來於室中、復上、伏於子身、子發嚏七、目遂啟、"],[12,4,36,"以利沙召基哈西曰、召書念婦至、乃召之、旣至、以利沙曰、抱爾子、"],[12,4,37,"婦入、在其足前、俯伏於地、抱子而出、○"],[12,4,38,"以利沙復至吉甲、其地適饑、先知徒坐於其前、以利沙命其僕曰、置巨釜、爲先知徒煮羹、"],[12,4,39,"有人往田採蔬、遇野瓜摘之、盈懷而歸、剖之、投於煮羹之釜、不識之也、"],[12,4,40,"傾之出、以予衆、食時、衆呼曰、上帝僕歟、釜中有死毒、遂不能食、"],[12,4,41,"以利沙曰、攜麪至、遂投麪於釜、曰、傾之出、予衆食、而釜中無毒矣、○"],[12,4,42,"有人自巴力沙利沙來、攜初實之麰麥餅二十、及新穗、藏於囊中、奉於上帝僕、上帝僕曰、予衆食之、"],[12,4,43,"其僕曰、何也、豈陳此以供百人乎、曰、予衆食之、蓋耶和華云、衆必食之而有餘、"],[12,4,44,"僕遂陳於衆前、食之而有餘、如耶和華所言、"],[12,5,1,"亞蘭王之軍長乃縵、在其主前爲大爲尊、緣耶和華藉之使亞蘭獲勝、素爲英武、第患癩疾、"],[12,5,2,"昔亞蘭人結隊而出、自以色列境虜一少女、服事乃縵之妻、"],[12,5,3,"女謂主母曰、深願我主與先知偕、在於撒瑪利亞、彼必愈其癩、"],[12,5,4,"乃縵入告其主曰、以色列地之女、所言如此、"],[12,5,5,"亞蘭王曰、爾往哉、我致書於以色列王、乃縵遂往、攜銀十他連得、金六千舍客勒、衣十襲、"],[12,5,6,"賷書致以色列王曰、爾得此書、則知我遣臣僕乃縵詣爾、俾愈其癩、"],[12,5,7,"以色列王閱書、裂其衣曰、我豈爲上帝、能死生人乎、彼乃遣人詣我、使愈其癩、爾其思之、可知彼乃搆釁於我、"],[12,5,8,"上帝僕以利沙聞以色列王裂衣、則遣人詣之、曰、何爲裂衣、令其人就我、則知以色列中有先知也、"],[12,5,9,"於是乃縵率車馬而至、立於以利沙宅門、"],[12,5,10,"以利沙遣使謂之曰、往約但河沐浴七次、則爾膚復原而得潔、"],[12,5,11,"乃縵怒而退曰、我意彼必出而見我、立而籲其上帝耶和華之名、搖手於患處、使癩者得愈、"],[12,5,12,"大馬色之河、亞罷拿與法珥法、較以色列諸水、豈不尤佳乎、我不可浴於彼、而得潔乎、遂忿然反身而去、"],[12,5,13,"其僕進而謂之曰、我父歟、先知若命爾行一大事、爾豈不行之、況僅言沐浴而得潔乎、"],[12,5,14,"乃縵遂下、遵上帝僕之言、濡於約但七次、其膚復原、如嬰孩之膚而潔焉、"],[12,5,15,"遂與從者返詣上帝僕、立於其前曰、今我知以色列而外、天下無上帝、祈受爾僕之餽、"],[12,5,16,"曰、我指所事維生之耶和華而誓、我必不受、乃縵強之、惟彼固辭、"],[12,5,17,"乃縵曰、如不受、求爾以二騾可負之土賜爾僕、今而後、爾僕不獻燔祭及他祭於他神、惟獻於耶和華、"],[12,5,18,"但有一事、願耶和華宥爾僕、卽我主入臨門廟崇拜時、倚於我手、我隨之而鞠躬、願耶和華宥爾僕於此事、"],[12,5,19,"曰、安然而去、遂行、相去未遠、○"],[12,5,20,"上帝僕以利沙之僕基哈西曰、我主惜此亞蘭人乃縵之費、不受其手所攜者、我指維生之耶和華而誓、我必追之、少索其物、"],[12,5,21,"基哈西遂追乃縵、乃縵見人趨而追之、下車迓之曰、安乎、"],[12,5,22,"曰、安、我主遣我告爾曰、適有先知徒少者二人、自以法蓮山地至我、請爾以銀一他連得、衣二襲予之、"],[12,5,23,"乃縵曰、請受二他連得、強之受、乃以銀二他連得、置於二囊、及衣二襲、付於二僕、二僕荷之、行於其前、"],[12,5,24,"旣至山岡、則由僕手接之、藏於室、遣二人去、"],[12,5,25,"基哈西入、立於主前、以利沙曰、基哈西、汝奚自、曰、爾僕無所往、"],[12,5,26,"曰、其人下車、轉而迓爾時、我心豈不偕往乎、是時豈可受銀與衣、以購橄欖園、葡萄園、牛羊僕婢乎、"],[12,5,27,"緣此、乃縵之癩必附爾身、爰及苗裔、至於永世、基哈西退而出、遂爲癩者、其白如雪、"],[12,6,1,"先知徒謂以利沙曰、我與爾同居之處、狹隘太甚、"],[12,6,2,"求爾容我往約但、各取材木、在彼建室以居、曰、往哉、"],[12,6,3,"或曰、求爾與僕偕往、曰、我往、"],[12,6,4,"遂與俱往、至約但伐木、"],[12,6,5,"一人斫木時、斧脫柯墜於水、呼曰、惜哉、我主歟、此乃貸於人者、"],[12,6,6,"上帝僕曰、墜於何所、遂示其處、則斬木投水、鐵上浮、"],[12,6,7,"曰、爾其取之、遂伸手取之、○"],[12,6,8,"亞蘭王與以色列戰、與其臣議曰、我必於某處建營、"],[12,6,9,"上帝僕遣人詣以色列王曰、爾其愼之、勿經某處、蓋亞蘭人至矣、"],[12,6,10,"以色列王遣人至上帝僕所戒之處、而脫其害、非僅一二次已也、"],[12,6,11,"亞蘭王緣此中心煩擾、召其臣謂之曰、我中誰助以色列王、爾曹不告我乎、"],[12,6,12,"一臣曰、我主我王歟、非也、乃以色列之先知以利沙、以王在寢室所言者、告以色列王、"],[12,6,13,"王曰、往視其人何在、我則遣人執之、或告曰、在多坍、"],[12,6,14,"乃遣車馬大軍夜至、而圍其邑、"],[12,6,15,"上帝僕之僕夙興而出、見軍旅車馬圍城、則曰、哀哉、我主歟、我儕將何爲、"],[12,6,16,"曰、勿懼、偕我者較偕彼者尤衆、"],[12,6,17,"以利沙禱曰、耶和華歟、求爾啟其目、使之得見、耶和華啟少者之目、則見遍山火車火馬、環繞以利沙、"],[12,6,18,"敵軍旣至、以利沙禱耶和華曰、祈使斯衆目瞶、耶和華卽瞶其目、如以利沙之言、"],[12,6,19,"以利沙謂之曰、此非其途、亦非其邑、爾其從我、我導爾至所尋者、遂導之至撒瑪利亞、"],[12,6,20,"旣入撒瑪利亞、以利沙曰、耶和華歟、啟斯衆之目、使之得見、耶和華啟其目、彼乃得見、知在撒瑪利亞邑中、"],[12,6,21,"以色列王見之、謂以利沙曰、我父歟、我擊之可乎、我擊之可乎、"],[12,6,22,"曰、不可擊之、以刃以弓所虜者、可擊之乎、當陳餅與水於其前、使之飲食、而返其主、"],[12,6,23,"王爲之設盛饌、飲食旣畢、遣之去、乃歸其主、自此亞蘭軍旅、不再侵以色列境、○"],[12,6,24,"厥後、亞蘭王便哈達集其全軍而上、圍撒瑪利亞、"],[12,6,25,"撒瑪利亞饑甚、被困、至一驢之首、售銀八十舍客勒、鴿糞二升、售銀五舍客勒、"],[12,6,26,"以色列王經行城垣、有婦呼曰、我主我王歟、其助我、"],[12,6,27,"曰、如耶和華不助爾、我何由助爾、由禾場或酒醡乎、"],[12,6,28,"又曰、爾有何事、婦曰、此婦謂我曰、取爾子、我儕今日食之、明日則食我子、"],[12,6,29,"於是烹我子而食之、次日我曰、取爾子、我儕食之、彼匿其子、"],[12,6,30,"王聞婦言則裂其衣、由城垣而過、民見其內衣麻衣、"],[12,6,31,"王曰、今日若容沙法子以利沙之首、仍在其身、則願上帝罰我維倍、"],[12,6,32,"以利沙坐於室、長老偕坐、王遣侍者先往、使者未至、以利沙謂長老曰、試觀此兇人之子、遣人取我首、使者至、爾則閉門、嚴守而禦之、其主之足音、非隨其後乎、"],[12,6,33,"言時、使者至、王隨至、曰、此災降自耶和華、我何爲復徯耶和華乎、"],[12,7,1,"以利沙曰、宜聽耶和華之言、耶和華云、明日此時、在撒瑪利亞邑門、細麪一細亞、售銀一舍客勒、麰麥二細亞、售銀一舍客勒、"],[12,7,2,"扶王之軍長謂上帝僕曰、卽耶和華啟牖於天、豈能有此事乎、以利沙曰、爾必目覩、惟不得食、○"],[12,7,3,"邑門有癩者四人、相語曰、我坐此待斃、何爲哉、"],[12,7,4,"若云入邑、則邑中饑、必死於彼、如坐於此、亦必死焉、其來、我儕往降於亞蘭軍、如存我生、則生、如殺我、則死耳、"],[12,7,5,"薄暮遂起、往亞蘭營、至營之邊隅、闃其無人、"],[12,7,6,"蓋耶和華使亞蘭軍旅、聞車聲馬聲、大軍之聲、則相語曰、以色列王必賄赫族、與埃及諸王、來攻我矣、"],[12,7,7,"薄暮卽起而遁、棄其帳幕馬驢、留營如故、祇逃其生、"],[12,7,8,"癩者至營之邊隅、入一幕、式食式飲、攜其金銀衣服、出而匿之、返入他幕、亦攜其物匿之、"],[12,7,9,"乃相語曰、我所爲者未善、今日有佳音、而我儕默爾、待至平旦、罪必及我、我儕其往、報於王家、"],[12,7,10,"遂往、呼守門者、告之曰、我至亞蘭營、見無人在、亦無人聲、惟馬驢繫焉、帳幕如故、"],[12,7,11,"守門者乃呼告於王家、"],[12,7,12,"王夜起、謂其臣曰、亞蘭人於我所爲、我以示爾、彼知我飢、故出營伏於田、意謂其人出城時、我儕則生擒之、而入其邑、"],[12,7,13,"一臣對曰、請於邑中所遺之馬、遣人取其五匹、而往窺之、以色列人幾至滅絕、此馬之數、如遺民焉、"],[12,7,14,"遂取馬與二車、王遣之追襲亞蘭軍曰、往而察之、"],[12,7,15,"乃追襲之、至約但、見衣械遍於途、卽亞蘭人疾遁而棄者、使者返告於王、"],[12,7,16,"民遂出、掠亞蘭營、於是細麪一細亞、售銀一舍客勒、麰麥二細亞、售銀一舍客勒、如耶和華所言、"],[12,7,17,"王委扶之之軍長監邑門、民於邑門踐之而死、如上帝僕於王來見時所言、"],[12,7,18,"蓋上帝僕曾言於王曰、明日此時、在撒瑪利亞邑門、細麪一細亞、售銀一舍客勒、麰麥二細亞、售銀一舍客勒、"],[12,7,19,"其時軍長謂上帝僕曰、卽耶和華啟牖於天、豈能有此事乎、曰、爾必目覩、惟不得食、"],[12,7,20,"斯皆應於其身、民於邑門踐之而死、"],[12,8,1,"以利沙曾謂所甦其子之婦曰、爾與爾家、起往可居之地而居、蓋耶和華必使饑饉臨於斯土、歷至七年、"],[12,8,2,"婦起、遵上帝僕之言、攜其家往居非利士地、歷至七年、"],[12,8,3,"七年之末、婦自非利士地而返、爲其第宅田畝、往籲於王、"],[12,8,4,"時、王與上帝僕之僕基哈西相語曰、請以以利沙所行之大事告我、"],[12,8,5,"基哈西以其甦死者之事告王、適所甦其子之婦、爲第宅田畝籲王、基哈西曰、我主我王、此卽其婦、此卽其子、乃以利沙所甦者、"],[12,8,6,"王問婦、婦告之、遂命一宦者曰、凡屬此婦、曁其離國至今、田畝所產者、悉反之、○"],[12,8,7,"以利沙至大馬色、亞蘭王便哈達遘疾、或告之曰、上帝僕至此、"],[12,8,8,"王命哈薛曰、爾攜禮物、往迎上帝僕、託之詢於耶和華、我病得愈否、"],[12,8,9,"哈薛遂往迎之、以四十駝、負大馬色各種佳品、以爲禮物、旣至、立於其前曰、爾子亞蘭王便哈達、遣我詣爾曰、我病得愈否、"],[12,8,10,"以利沙曰、汝往告之曰、爾必愈、然耶和華曾示我彼必死、"],[12,8,11,"遂注視哈薛、致其愧怍、上帝僕乃哭、"],[12,8,12,"哈薛曰、我主何爲而哭、曰、我知爾於以色列人將行之惡、以火燬其堅城、以刃殺其丁壯、擲斃其嬰孩、刳剔其孕婦、"],[12,8,13,"哈薛曰、僕何人斯、乃一犬耳、焉能行此大事、以利沙曰、耶和華已示我、爾必爲亞蘭王、"],[12,8,14,"哈薛別以利沙、返見其主、其主問曰、以利沙與爾何言、曰、言爾必愈、"],[12,8,15,"翌日、哈薛以裯濡水、覆其面、致之死、哈薛遂繼其位、○"],[12,8,16,"以色列王亞哈子約蘭五年、猶大王約沙法尚在位時、其子約蘭卽位、"],[12,8,17,"時、年三十有二、在耶路撒冷爲王、凡歷八年、"],[12,8,18,"循以色列諸王之道、如亞哈家所爲、蓋娶亞哈女爲妻、行耶和華所惡、"],[12,8,19,"然耶和華以其僕大衞故、不滅猶大、依其所許、永錫燈光於大衞、爰及子孫、"],[12,8,20,"當約蘭時、以東叛猶大、脫於其手、立王自治、"],[12,8,21,"約蘭率所有之車至撒益、以東人圍之、約蘭夜起擊之、及其車長、猶大民遁、各歸其幕、"],[12,8,22,"如是以東叛猶大、至於今日、立拿亦同時而叛、"],[12,8,23,"約蘭其餘事蹟、凡其所行、俱載於猶大列王紀、"],[12,8,24,"約蘭與列祖偕眠、同葬於大衞城、子亞哈謝嗣位、○"],[12,8,25,"以色列王亞哈子約蘭十二年、猶大王約蘭子亞哈謝卽位、"],[12,8,26,"時、年二十有二、在耶路撒冷爲王、僅歷一年、其母名亞他利雅、乃以色列王暗利之孫也、"],[12,8,27,"亞哈謝循亞哈家之道、行耶和華所惡、如亞哈家所爲、因其爲亞哈家之壻也、"],[12,8,28,"彼與亞哈子約蘭往基列拉末、與亞蘭王哈薛戰、約蘭爲亞蘭人所傷、"],[12,8,29,"約蘭返耶斯列、醫其在拉末與亞蘭王哈薛戰時、所受之傷、猶大王約蘭子亞哈謝因其疾病、下耶斯列視之、"],[12,9,1,"先知以利沙召先知徒一人、命之曰、束爾腰、執膏一甁、往基列拉末、"],[12,9,2,"旣至、尋寧示孫、約沙法子耶戶、使之起而離其昆弟、攜入內室、"],[12,9,3,"以膏甁傾於其首曰、耶和華云、我膏爾爲以色列王、卽啟門而遁、勿延、"],[12,9,4,"先知少者遂往基列拉末、"],[12,9,5,"旣至、見諸軍長皆坐、曰、軍長歟、我有言告汝、耶戶曰、我中何人、曰、軍長歟、卽爾也、"],[12,9,6,"耶戶起而入室、少者傾膏於其首、謂之曰、以色列之上帝耶和華云、我膏爾爲耶和華民以色列之王、"],[12,9,7,"爾必擊爾主亞哈家、俾我於耶洗別之身、報我僕衆先知、及耶和華諸僕之血仇、"],[12,9,8,"亞哈全家必滅、亞哈丁男、無論被束者、自由者、悉絕之於以色列中、"],[12,9,9,"我必使亞哈家、如尼八子耶羅波安、及亞希雅子巴沙之家然、"],[12,9,10,"耶洗別必在耶斯列田、爲犬所噬、無人葬之、言竟、啟門而遁、"],[12,9,11,"耶戶出、至其主之諸臣、其一問曰、安乎、此顚狂者詣爾何事、曰、爾識其人、亦知其言、"],[12,9,12,"曰、此誑言也、爾其告我、曰、彼如此謂我曰、耶和華云、我膏爾爲以色列王、"],[12,9,13,"衆急以其衣置於階之上級、使耶戶坐其上、吹角曰、耶戶爲王矣、"],[12,9,14,"於是寧示孫、約沙法子耶戶叛約蘭、初、約蘭與以色列衆禦亞蘭王哈薛、戍守基列拉末、"],[12,9,15,"約蘭王返耶斯列、醫其與亞蘭王哈薛戰時、所受之傷、耶戶告衆曰、若愜爾意、則勿容人出邑、往報於耶斯列、"],[12,9,16,"耶戶乃乘車往耶斯列、因約蘭臥病於彼、猶大王亞哈謝來視之、"],[12,9,17,"守望者立於耶斯列臺、見耶戶之軍將至、曰、我見一軍、約蘭曰、遣騎兵往迎之、問曰、安否、"],[12,9,18,"騎兵遂往迎之、曰、王云安否、耶戶曰、安否與爾何與、其轉而隨我後、守望者告曰、使者至彼而不返、"],[12,9,19,"又遣騎兵、旣至、曰、王云安否、耶戶曰、安否與爾何與、其轉而隨我後、"],[12,9,20,"守望者又告曰、使者至彼而不返、來者御車之勢、有若寧示孫耶戶、蓋其御猛甚也、"],[12,9,21,"約蘭曰、駕、遂備車、以色列王約蘭、猶大王亞哈謝、各乘其車、往迎耶戶、遇於耶斯列人拿伯之田、"],[12,9,22,"約蘭見耶戶、則曰、耶戶歟、安否、曰、爾母耶洗別、淫行巫術若是之多、焉得安乎、"],[12,9,23,"約蘭旋轅而遁、謂亞哈謝曰、亞哈謝歟、是叛也、"],[12,9,24,"耶戶極力彎弓、射中約蘭兩臂之間、矢穿其心而出、遂仆於車、"],[12,9,25,"耶戶謂其軍長畢甲曰、取而投於耶斯列人拿伯之田、爾其追思、爾我同乘、隨其父亞哈時、耶和華預言之、"],[12,9,26,"曰、昨日我見拿伯及其諸子之血、必於是田報之、今投之於此田、循耶和華所言、"],[12,9,27,"猶大王亞哈謝見此、遂由園亭之道而遁、耶戶追之、曰、擊之於車中、至近以伯蓮之姑珥阪、擊之、乃遁至米吉多而死、"],[12,9,28,"其臣載之於車、至耶路撒冷、葬於其墓、偕其列祖、在大衞城、○"],[12,9,29,"亞哈謝卽位、爲猶大王時、乃在亞哈子約蘭之十一年、○"],[12,9,30,"耶戶旣至耶斯列、耶洗別聞之、畫眉飾首、自牖而觀、"],[12,9,31,"耶戶入門、耶洗別曰、弒主之心利歟、安乎、"],[12,9,32,"耶戶仰視其牖曰、爲我者誰乎、有二三宦者自牖觀之、"],[12,9,33,"耶戶曰、擲之下、遂擲之、血濺於壁及馬、耶戶以足踐之、"],[12,9,34,"耶戶入而飲食、旣而命曰、收此服詛之婦葬之、以其爲王女也、"],[12,9,35,"遂往葬之、僅得其頭顱、與足及手掌而已、"],[12,9,36,"反告耶戶、耶戶曰、此乃耶和華藉其僕、提斯比人以利亞所言曰、耶洗別之肉、必在耶斯列田、爲犬所噬、"],[12,9,37,"其屍必在耶斯列田、如田間之糞壤、致人不得曰、此乃耶洗別也、"],[12,10,1,"亞哈有子七十、在撒瑪利亞、耶戶作書、寄撒瑪利亞、致耶斯列之首領卽長老、及教育亞哈諸子者、"],[12,10,2,"曰、爾主之子偕爾、亦有車馬、器械堅城、"],[12,10,3,"爾接此書、可擇爾主衆子中、賢而適宜者、俾踐其父之位、而爲爾主之家戰爭、"],[12,10,4,"彼衆懼甚、曰、二王不能禦之、我儕何能禦乎、"],[12,10,5,"家宰邑宰長老、及教育亞哈子者、遣人詣耶戶曰、我爲爾僕、凡所命者、我必行之、我不立人爲王、爾視爲善者則行之、"],[12,10,6,"耶戶復致書曰、爾若爲我、聽從我言、明日此時、攜爾主衆子之首、至耶斯列見我、時、王子七十人、與邑中顯貴教育之者偕居、"],[12,10,7,"書至、遂執王子七十人殺之、盛首於筐、送至耶斯列耶戶所、"],[12,10,8,"或告耶戶曰、彼攜王子之首而至、耶戶曰、列爲二堆、在於邑門、至於明旦、"],[12,10,9,"詰朝、耶戶出、立而告衆曰、爾曹皆義、我叛我主而弒之、惟殺此衆者爲誰、"],[12,10,10,"可知耶和華論亞哈家所言、無一或失、蓋耶和華藉其僕以利亞所言、今悉成焉、"],[12,10,11,"凡在耶斯列、亞哈家所遺者、及其大臣、密友祭司、耶戶盡殺之、靡有孑遺、"],[12,10,12,"遂起、往撒瑪利亞、途間至剪羊所、"],[12,10,13,"遇猶大王亞哈謝之昆弟、問之曰、爾爲誰、曰、我乃亞哈謝昆弟、今往問王與太后之子安、"],[12,10,14,"耶戶命曰、生擒之、遂生擒之、戮於剪羊所之阬側、四十二人、靡有孑遺、○"],[12,10,15,"耶戶離彼而往、遇利甲子約拿達來迎、乃問其安曰、爾心正直向我、如我心之正直向爾乎、約拿達曰、然、曰、如是、則與我攜手、遂與攜手、耶戶挽之登車、"],[12,10,16,"曰、與我偕往、視我爲耶和華之熱中、乃使之乘車、"],[12,10,17,"旣至撒瑪利亞、則殺亞哈家所遺者、至於盡滅、如耶和華語以利亞之言、○"],[12,10,18,"耶戶集民衆、謂之曰、亞哈奉事巴力猶少、耶戶將事之加多焉、"],[12,10,19,"今我欲獻大祭於巴力、當召巴力之衆先知、與崇拜巴力者、及其祭司、使悉詣我、勿遺一人、凡不至者、必不得生、耶戶言此、乃施詭計、欲滅崇拜巴力之人耳、"],[12,10,20,"耶戶曰、當爲巴力特設肅會、遂宣告焉、"],[12,10,21,"耶戶遣人徧行以色列境、凡崇拜巴力者咸至、不遺一人、入巴力廟、充塞其間、"],[12,10,22,"耶戶命掌禮服者曰、取禮服、予崇拜巴力者衣之、遂取而予之、"],[12,10,23,"耶戶與利甲子約拿達、入巴力廟、謂崇拜巴力者曰、試觀察之、免有耶和華之僕在爾中、惟崇拜巴力者而已、"],[12,10,24,"乃入獻燔祭與他祭、耶戶預置八十人於廟外、告之曰、我所付於爾手者、若遁其一、縱之去者、必以己命代之、"],[12,10,25,"獻燔祭畢、耶戶命衞士及諸軍長曰、入而殺之、勿容一人出、衞士及軍長遂以刃殺之、擲屍於外、而往巴力廟之邑、"],[12,10,26,"取廟中之柱像、出而焚之、"],[12,10,27,"毀巴力之柱像、摧其廟以爲廁、迄於今日、"],[12,10,28,"如是耶戶滅巴力於以色列中、"],[12,10,29,"惟不離棄尼八子耶羅波安陷以色列人之罪、卽在伯特利與但之金犢、"],[12,10,30,"耶和華諭耶戶曰、因爾行我所視爲善者、依我心意、待亞哈家、爾之子孫必居以色列國位、歷至四世、"],[12,10,31,"然耶戶不專心注意、遵行以色列上帝耶和華之法律、不離棄耶羅波安陷以色列人之罪、○"],[12,10,32,"當時耶和華始割裂以色列、哈薛擊其四境、"],[12,10,33,"卽約但東、基列全地、自亞嫩溪之亞羅珥、擊迦得流便瑪拿西人之地、基列與巴珊、"],[12,10,34,"耶戶其餘事蹟、凡其所行、與其勇力、俱載於以色列列王紀、"],[12,10,35,"耶戶與列祖偕眠、葬於撒瑪利亞、子約哈斯嗣位、"],[12,10,36,"耶戶在撒瑪利亞爲以色列王、凡二十有八年、"],[12,11,1,"亞哈謝母亞他利雅見子已死、起而殲滅王室、"],[12,11,2,"約蘭王女、亞哈謝妹約示巴於見殺之王子中、竊亞哈謝子約阿施出、與其乳媼、藏於寢室、以避亞他利雅、免其被殺、"],[12,11,3,"約阿施與其乳媼、偕匿於耶和華室、歷有六年、亞他利雅治理斯土、○"],[12,11,4,"越至七年、耶何耶大遣人召迦利族與衞士之百夫長、導入耶和華室、與之立約、使在耶和華室發誓、以王子示之、"],[12,11,5,"命之曰、爾當如是而行、凡安息日入值者、三分之一宜守王宮、"],[12,11,6,"三分之一守蘇珥門、三分之一守衞士後之門、如是守護王宮、以爲防禦、"],[12,11,7,"安息日退值之二隊、必守護耶和華室、在王四周、"],[12,11,8,"各執器械以環之、凡侵爾班列者、必殺之、王出入時、爾必與偕、"],[12,11,9,"百夫長咸遵祭司耶何耶大之命而行、各率其人、安息日入值退值者、俱詣祭司耶何耶大、"],[12,11,10,"祭司以耶和華室所藏大衞之干戈、予百夫長、"],[12,11,11,"衞士手執器械、立於王之四周、自室右至室左、環壇與室、"],[12,11,12,"祭司導王子出、加冕於其首、予以法律、膏之爲王、衆鼓掌曰、願王萬歲、"],[12,11,13,"亞他利雅聞衞士與民之聲、則入耶和華室、至於民所、"],[12,11,14,"望見王循常例立於柱側、百夫長與吹角者侍於王側、四境之民懽忻吹角、亞他利雅裂衣、呼曰、叛矣、叛矣、"],[12,11,15,"祭司耶何耶大命統軍之百夫長曰、由隊伍之間擁之出、隨其後者、必殺以刃、蓋祭司曰、勿殺之於耶和華室、"],[12,11,16,"遂辟易而出之、婦由馬道至王宮、見殺於彼、○"],[12,11,17,"耶何耶大使王及民、與耶和華立約、俾爲耶和華之民、又使王與民立約、"],[12,11,18,"四境之民、往巴力廟毀之、摧其壇、碎其像、殺巴力之祭司瑪坦於壇前、祭司設官守耶和華室、"],[12,11,19,"率諸百夫長、曁迦利族與衞士、以及四境之民、自耶和華室、導王而下、由衞士門、入於王宮、遂卽王位、"],[12,11,20,"四境之民歡樂、邑內平康、亞他利雅見殺於王宮、約阿施卽位時、年甫七齡、"],[12,12,1,"耶戶七年、約阿施卽位、在耶路撒冷爲王、歷四十年、其母名西比亞、別是巴人也、"],[12,12,2,"約阿施在祭司耶何耶大訓誨之日、行耶和華所悅、"],[12,12,3,"惟崇邱未廢、民仍獻祭焚香於其上、○"],[12,12,4,"約阿施謂諸祭司曰、凡輸入耶和華室、區別爲聖之物、所值通用之金、或各人所估身價之金、或從心所願、輸於耶和華室之金、"],[12,12,5,"祭司各自相識之人受之、修葺殿宇破壞之處、"],[12,12,6,"至約阿施王二十三年、殿宇之破壞、祭司尚未修葺、"],[12,12,7,"故約阿施王召大祭司耶何耶大、與衆祭司、謂之曰、殿宇破壞、胡不修葺、今而後、勿復受相識者之金、宜出此金、修葺殿宇之破壞、"],[12,12,8,"諸祭司應命、不復受金於民、亦不修葺殿宇、"],[12,12,9,"惟祭司耶何耶大取一匱、鑿孔於蓋、置諸壇側、在入耶和華室之右、凡輸耶和華室之金、守門之祭司咸納於其中、"],[12,12,10,"匱中金多、則王之繕寫與祭司長至、將耶和華室所得之金、核而封之、"],[12,12,11,"以所權之金、付於督耶和華室之工作者、轉予建造之木工及匠役、"],[12,12,12,"又予瓦工石工、復購材木、及鑿成之石、以修葺耶和華室之破壞、並爲一切修室之用、"],[12,12,13,"惟所輸耶和華室之金、不以製耶和華室中之銀杯剪盂角、及諸金銀器皿、"],[12,12,14,"乃以予督工者、修葺耶和華室、"],[12,12,15,"以金付於督理、轉予工匠、不與核算其數、因其行事誠實也、"],[12,12,16,"惟補過祭與贖罪祭之金、不入耶和華室、俱歸祭司、○"],[12,12,17,"時、亞蘭王哈薛、上攻迦特取之、遂定志上耶路撒冷、"],[12,12,18,"猶大王約阿施、以其祖父猶大王約沙法、約蘭、亞哈謝、所區別之物、與己所獻爲聖之物、及耶和華室與王宮府庫、所有之金、悉饋亞蘭王哈薛、哈薛乃去耶路撒冷、"],[12,12,19,"約阿施其餘事蹟、凡其所行、俱載於猶大列王紀、"],[12,12,20,"約阿施之臣叛、弒之於近悉羅之米羅宮、"],[12,12,21,"弒王之臣、乃示米押子約撒甲、朔默子約薩拔、王與列祖同葬於大衞城、子亞瑪謝嗣位、"],[12,13,1,"猶大王亞哈謝子約阿施二十三年、耶戶子約哈斯卽位、在撒瑪利亞爲以色列王、歷十七年、"],[12,13,2,"行耶和華所惡、從尼八子耶羅波安陷以色列人之罪、不離棄之、"],[12,13,3,"耶和華遂怒以色列人、常付之於亞蘭王哈薛、及其子便哈達之手、"],[12,13,4,"約哈斯懇求耶和華、耶和華垂聽、因見以色列人受亞蘭王之虐也、"],[12,13,5,"耶和華賜救者於以色列人、俾脫亞蘭人手、居於其幕如故、"],[12,13,6,"然不離棄耶羅波安家之罪、卽陷以色列人之罪、從之而行、留木偶於撒瑪利亞、"],[12,13,7,"亞蘭王殲滅約哈斯之民、蹂躪之如禾場之土、惟遺騎兵五十、戰車十乘、步卒一萬、"],[12,13,8,"約哈斯其餘事蹟、凡其所行、與其勇力、俱載於以色列列王紀、"],[12,13,9,"約哈斯與列祖偕眠、葬於撒瑪利亞、子約阿施嗣位、○"],[12,13,10,"猶大王約阿施三十七年、約哈斯子約阿施卽位、在撒瑪利亞爲以色列王、歷十六年、"],[12,13,11,"行耶和華所惡、不離棄尼八子耶羅波安陷以色列人之罪、從之而行、"],[12,13,12,"約阿施其餘事蹟、凡其所行、及與猶大王亞瑪謝戰鬬之勇力、俱載於以色列列王紀、"],[12,13,13,"約阿施與列祖偕眠、同以色列諸王葬於撒瑪利亞、耶羅波安踐其位、○"],[12,13,14,"初、以利沙遘致死之疾、以色列王約阿施下而詣之、俯於其面而哭、曰、我父歟、我父歟、以色列之車騎也、"],[12,13,15,"以利沙曰、取弓與矢、王遂取之、"],[12,13,16,"又曰、以手執弓、遂執之、以利沙按手於王手、"],[12,13,17,"曰、啟東牖、遂啟之、以利沙曰、射、遂射、以利沙曰、是耶和華獲勝之矢、卽勝亞蘭之矢、蓋爾必在亞弗、擊亞蘭人、至於盡滅、"],[12,13,18,"又曰、取矢、遂取之、曰、擊地、乃三擊而止、"],[12,13,19,"上帝僕怒之曰、爾宜擊地五六次、則必擊亞蘭人、至於盡滅、今擊之僅三次而已、○"],[12,13,20,"以利沙卒而葬、歲首摩押軍旅犯境、"],[12,13,21,"適有人葬死者、見軍旅至、則投屍於以利沙墓、屍觸以利沙之骨、則甦而立、○"],[12,13,22,"約哈斯在位時、亞蘭王哈薛恆虐以色列人、"],[12,13,23,"惟耶和華因與亞伯拉罕以撒雅各所立之約、施恩矜恤之、眷顧之、尚不滅之、不逐之於其前、"],[12,13,24,"亞蘭王哈薛卒、子便哈達嗣位、"],[12,13,25,"昔哈薛與約阿施父約哈斯戰、取其數邑、今約阿施三擊哈薛子便哈達、恢復以色列邑、"],[12,14,1,"以色列王約哈斯子約阿施二年、猶大王約阿施子亞瑪謝卽位、"],[12,14,2,"時、年二十有五、在耶路撒冷爲王、凡二十九年、其母名約耶但、耶路撒冷人也、"],[12,14,3,"亞瑪謝行耶和華所悅、惟不若厥祖大衞、乃效其父約阿施所爲、"],[12,14,4,"崇邱未廢、民仍獻祭焚香於其上、"],[12,14,5,"國旣堅定、則誅弒其父之臣、"],[12,14,6,"而弗殺兇人之子、依摩西律書所載、耶和華命云、勿因子而殺父、勿因父而殺子、各因己罪而死、"],[12,14,7,"亞瑪謝於鹽谷、擊以東人一萬、攻西拉取之、易其名曰約帖、至於今日、○"],[12,14,8,"亞瑪謝遣使見耶戶孫、約哈斯子、以色列王約阿施曰、來、爾我晤面、"],[12,14,9,"以色列王約阿施、遣使見猶大王亞瑪謝曰、利巴嫩之蒺藜、遣使謂利巴嫩之香柏曰、以爾女妻我子、有利巴嫩之野獸過之、踐其蒺藜、"],[12,14,10,"爾擊以東、心高而誇耀之、安居於家可耳、何爲招禍、以致傾覆、猶大與爾偕亡乎、"],[12,14,11,"亞瑪謝弗聽、以色列王約阿施遂上、與猶大王亞瑪謝晤面於猶大之伯示麥、"],[12,14,12,"猶大人敗於以色列人前、遁而歸幕、"],[12,14,13,"以色列王約阿施擒亞哈謝孫、約阿施子、猶大王亞瑪謝於伯示麥、遂至耶路撒冷、毀其城垣、自以法蓮門、至城隅之門、凡四百肘、"],[12,14,14,"取耶和華室與王宮府庫、所有之金銀、及器皿、並取人爲質、而返撒瑪利亞、"],[12,14,15,"約阿施其餘事蹟、凡其所行、與其勇力、及與猶大王亞瑪謝戰鬬、俱載於以色列列王紀、"],[12,14,16,"約阿施與列祖偕眠、同以色列諸王葬於撒瑪利亞、子耶羅波安嗣位、○"],[12,14,17,"以色列王約哈斯子約阿施卒後、猶大王約阿施子亞瑪謝、猶在世十五年、"],[12,14,18,"亞瑪謝其餘事蹟、俱載於猶大列王紀、"],[12,14,19,"耶路撒冷有人叛之、遂遁於拉吉、叛黨遣人至拉吉弒之、"],[12,14,20,"乃以馬負其屍、至耶路撒冷、同列祖葬於大衞城、"],[12,14,21,"猶大民衆立亞撒利雅、繼父亞瑪謝爲王、時、年十有六歲、"],[12,14,22,"亞瑪謝與列祖偕眠後、亞撒利雅恢復以拉他、歸於猶大、而重建之、○"],[12,14,23,"猶大王約阿施子亞瑪謝十五年、以色列王約阿施子耶羅波安卽位、在撒瑪利亞爲王、歷四十一年、"],[12,14,24,"行耶和華所惡、不離棄尼八子耶羅波安陷以色列人之罪、"],[12,14,25,"耶羅波安恢復以色列之境、自哈馬道、至亞拉巴海、如以色列之上帝耶和華藉其僕、迦特希弗人亞米太子先知約拿所言、"],[12,14,26,"蓋耶和華見以色列人艱苦殊甚、被束者、自由者、消亡殆盡、亦無輔助以色列者、"],[12,14,27,"耶和華未言必塗以色列之名於天下、乃藉約阿施子耶羅波安救之、"],[12,14,28,"耶羅波安其餘事蹟、凡其所行、與其勇力、並如何戰爭、如何恢復大馬色、及猶大之哈馬、歸以色列、俱載於以色列列王紀、"],[12,14,29,"耶羅波安與列祖以色列諸王偕眠、子撒迦利雅嗣位、"],[12,15,1,"以色列王耶羅波安二十七年、猶大王亞瑪謝子亞撒利雅卽位、"],[12,15,2,"時、年十有六歲、在耶路撒冷爲王、凡五十二年、其母名耶可利雅、耶路撒冷人也、"],[12,15,3,"亞撒利雅行耶和華所悅、效其父亞瑪謝所爲、"],[12,15,4,"惟崇邱未廢、民仍獻祭焚香於其上、"],[12,15,5,"耶和華擊王、使之患癩、至於畢生、獨居別室、其子約坦理家政、治國民、"],[12,15,6,"亞撒利雅其餘事蹟、凡其所行、俱載於猶大列王紀、"],[12,15,7,"亞撒利雅與列祖偕眠、同葬於大衞城、子約坦嗣位、○"],[12,15,8,"猶大王亞撒利雅三十八年、耶羅波安子撒迦利雅、在撒瑪利亞爲以色列王、僅歷六月、"],[12,15,9,"行耶和華所惡、效其列祖所爲、不離棄尼八子耶羅波安陷以色列人之罪、"],[12,15,10,"雅比子沙龍叛之、弒之於民前、而篡其位、"],[12,15,11,"撒迦利雅其餘事蹟、俱載於以色列列王紀、"],[12,15,12,"昔耶和華諭耶戶曰、爾之子孫、必踐以色列國位、迄於四代、此言應矣、○"],[12,15,13,"猶大王烏西雅三十九年、雅比子沙龍卽位、在撒瑪利亞爲王僅歷一月、"],[12,15,14,"迦底子米拿現、自得撒上至撒瑪利亞弒之、而篡其位、"],[12,15,15,"沙龍其餘事蹟、及其謀逆之事、俱載於以色列列王紀、"],[12,15,16,"當時米拿現攻提斐薩、殺戮其居民、刳剔其孕婦、並自得撒擊其四境、因不爲之啟門故也、○"],[12,15,17,"猶大王亞撒利雅三十九年、迦底子米拿現卽位、在撒瑪利亞爲以色列王、凡歷十年、"],[12,15,18,"行耶和華所惡、不離棄尼八子耶羅波安陷以色列人之罪、至於畢生、"],[12,15,19,"亞述王普勒來攻斯土、米拿現饋銀一千他連得、請輔助之、固其國位、"],[12,15,20,"米拿現強索以色列之富豪、使各出銀五十舍客勒、以予亞述王、於是亞述王旋返、不駐斯土、"],[12,15,21,"米拿現其餘事蹟、凡其所行、俱載於以色列列王紀、"],[12,15,22,"米拿現與列祖偕眠、子比加轄嗣位、○"],[12,15,23,"猶大王亞撒利雅五十年、米拿現子比加轄卽位、在撒瑪利亞爲以色列王、凡歷二年、"],[12,15,24,"行耶和華所惡、不離棄尼八子耶羅波安陷以色列人之罪、"],[12,15,25,"其軍長利瑪利子比加叛之、在撒瑪利亞王宮之衞所弒之、及亞珥歌伯與亞利耶、有基列人五十、與之同謀、弒王而篡其位、"],[12,15,26,"比加轄其餘事蹟、凡其所行、俱載於以色列列王紀、○"],[12,15,27,"猶大王亞撒利雅五十二年、利瑪利子比加卽位、在撒瑪利亞爲以色列王、歷二十年、"],[12,15,28,"行耶和華所惡、不離棄尼八子耶羅波安陷以色列人之罪、"],[12,15,29,"以色列王比加在位時、亞述王提革拉毘列色至、取以雲、亞伯伯瑪迦、亞挪、基低斯、夏瑣、基列、加利利、拿弗他利全地、虜其居民、至亞述、"],[12,15,30,"烏西雅子約坦二十年、以拉子何細亞叛利瑪利子比加、擊而弒之、而篡其位、"],[12,15,31,"比加其餘事蹟、凡其所行、俱載於以色列列王紀、○"],[12,15,32,"以色列王利瑪利子比加二年、猶大王烏西雅子約坦卽位、"],[12,15,33,"時、年二十有五、在耶路撒冷爲王、歷十六年、其母名耶路沙、撒督女也、"],[12,15,34,"約坦行耶和華所悅、效其父烏西雅所爲、"],[12,15,35,"惟崇邱未廢、民仍獻祭焚香於其上、約坦建耶和華室之上門、"],[12,15,36,"約坦其餘事蹟、凡其所行、俱載於猶大列王紀、"],[12,15,37,"是時耶和華始遣亞蘭王利汛、及利瑪利子比加、往攻猶大、"],[12,15,38,"約坦與列祖偕眠、同葬於大衞城、子亞哈斯嗣位、"],[12,16,1,"利瑪利子比加十七年、猶大王約坦子亞哈斯卽位、"],[12,16,2,"時、年二十歲、在耶路撒冷爲王、歷十六年、不若厥祖大衞、行其上帝耶和華所悅、"],[12,16,3,"乃循以色列諸王之道、並使其子經火、效異邦可憎之惡行、卽耶和華於以色列人前、所逐諸族之事、"],[12,16,4,"且於崇邱、山岡之上、綠樹之下、獻祭焚香、"],[12,16,5,"亞蘭王利汛與以色列王利瑪利子比加、上耶路撒冷欲戰、圍亞哈斯、而不能勝之、"],[12,16,6,"當時亞蘭王利汛恢復以拉他、歸於亞蘭、驅猶大人出、亞蘭人至而居之、迄於今日、"],[12,16,7,"亞哈斯遣使見亞述王提革拉毘列色曰、我爲汝僕汝子、今亞蘭王與以色列王起而攻我、請來救我脫於其手、"],[12,16,8,"亞哈斯以耶和華室與王宮府庫、所有之金銀、餽亞述王、"],[12,16,9,"亞述王允其所求、往攻大馬色而取之、虜其居民至吉珥、並殺利汛、"],[12,16,10,"亞哈斯王往大馬色、迎亞述王提革拉毘列色、見一壇在彼、遂以其規模制度之式、寄於祭司烏利亞、"],[12,16,11,"祭司烏利亞乃建壇、循亞哈斯王自大馬色所寄之式、以待亞哈斯王自大馬色返、"],[12,16,12,"王自大馬色返、見壇、則進而獻祭於其上、"],[12,16,13,"焚其燔祭素祭及灌祭、以酬恩祭牲之血沃於壇、"],[12,16,14,"又以耶和華前之銅壇、自耶和華室與其壇之間、移而置於其壇之北、"],[12,16,15,"亞哈斯王命祭司烏利亞曰、朝之燔祭、夕之素祭、王之燔祭素祭、與庶民之燔祭素祭灌祭、皆當焚於大壇、燔祭與他祭牲之血、悉沃其上、惟彼銅壇、爲我藉以諮諏之用、"],[12,16,16,"祭司烏利亞悉遵亞哈斯王所命、"],[12,16,17,"亞哈斯王移盤離座、折其座之鑲版、又以銅牛上之銅海、移置於鋪石處、"],[12,16,18,"耶和華室中、爲安息日所建之廊、及王自外入室之廊、王因亞述王故、移之以環耶和華室、"],[12,16,19,"亞哈斯其餘所行之事、俱載於猶大列王紀、"],[12,16,20,"亞哈斯與列祖偕眠、同葬於大衞城、子希西家嗣位、"],[12,17,1,"猶大王亞哈斯十二年、以拉子何細亞卽位、在撒瑪利亞爲以色列王、凡歷九年、"],[12,17,2,"行耶和華所惡、第不若以色列前王之甚、"],[12,17,3,"亞述王撒縵以色上而攻之、何細亞臣服之、而納貢焉、"],[12,17,4,"何細亞謀叛、遣使詣埃及王梭、不納歲貢於亞述王、如前所爲、亞述王知之、遂禁錮之、而囚於獄、"],[12,17,5,"侵其全地、往撒瑪利亞、圍之三年、"],[12,17,6,"何細亞九年、亞述王取撒瑪利亞、徙以色列人至亞述、置於哈臘與歌散之哈博河濱、及瑪代諸邑、"],[12,17,7,"此因以色列人獲罪於其上帝耶和華、卽導之出埃及、脫於埃及王法老手者、彼乃寅畏他神、"],[12,17,8,"循耶和華於以色列人前、所逐異族之例、及以色列諸王所立之例、"],[12,17,9,"以色列人私行不正之事、背逆其上帝耶和華、於其諸邑、自戍樓至堅城、建築崇邱、"],[12,17,10,"在山岡之上、綠樹之下、立柱像與木偶、"],[12,17,11,"焚香於諸崇邱、效耶和華於其前所逐之異族、行諸惡事、激耶和華之怒、"],[12,17,12,"崇事偶像、卽耶和華所言不可爲者、"],[12,17,13,"耶和華藉諸先知先見、戒以色列與猶大人曰、當轉離爾之惡途、守我誡命典章、循我所命爾列祖、及藉我僕衆先知授爾之法、"],[12,17,14,"惟彼弗聽、強項不馴、如其不信厥上帝耶和華之列祖、"],[12,17,15,"違棄上帝之典章、及與其列祖所立之約、並戒之之言、從虛無而變爲虛妄、效四周異邦、卽耶和華所命勿效之者、"],[12,17,16,"違棄其上帝耶和華一切誡命、鑄二犢像、製造木偶、崇拜天象、奉事巴力、"],[12,17,17,"使其子女經火、用卜筮邪術、自鬻而行耶和華所惡、以激其怒、"],[12,17,18,"耶和華震怒以色列人、擯於其前、惟遺猶大支派而已、"],[12,17,19,"猶大亦不守其上帝耶和華之誡命、乃從以色列人所立之例、"],[12,17,20,"耶和華棄以色列全族、而困苦之、付於虜者之手、擯於其前、"],[12,17,21,"奪以色列離大衞家、衆乃立尼八子耶羅波安爲王、耶羅波安誘以色列人不從耶和華、使干大罪、"],[12,17,22,"以色列人從耶羅波安所犯諸罪、不離棄之、"],[12,17,23,"致耶和華擯以色列人於其前、如藉其僕衆先知所言、於是以色列人被虜離故土、徙於亞述、迄於今日、○"],[12,17,24,"亞述王自巴比倫、古他、亞瓦、哈馬、西法瓦音、移人置於撒瑪利亞之邑、以代以色列人、遂據撒瑪利亞、居其諸邑、"],[12,17,25,"斯衆始居於彼之時、不寅畏耶和華、耶和華使獅入其中、殺其數人、"],[12,17,26,"或告亞述王曰、王所移居撒瑪利亞之族、不識斯土之神之律、故彼使獅入其中而殺之、"],[12,17,27,"亞述王命曰、爾曹自其地所虜之祭司、返其一人、使居其地、以其地之神之律誨衆、"],[12,17,28,"於是自撒瑪利亞被虜之祭司一人、來居伯特利、誨衆如何寅畏耶和華、"],[12,17,29,"然各族之人、於其所居之邑、各爲己造神像、置於撒瑪利亞人所造崇邱之廟、"],[12,17,30,"巴比倫人造疏割比訥像、古他人造匿甲像、哈馬人造亞示瑪像、"],[12,17,31,"亞瓦人造匿哈與他珥他像、西法瓦音人以火焚其子女、獻於西法瓦音之神、亞得米勒與亞拿米勒、"],[12,17,32,"斯衆乃寅畏耶和華、亦從其中簡立祭司、以司崇邱、爲之獻祭於崇邱之廟、"],[12,17,33,"如是、斯衆寅畏耶和華、又事己神、循其所自徙諸族之例、"],[12,17,34,"至今尚循往例、不誠畏耶和華、不循己之典章律例、不遵耶和華所命雅各後裔之法律誡命、夫雅各、昔耶和華名之曰以色列、"],[12,17,35,"耶和華與其後裔立約、誡之曰、勿寅畏他神、勿崇拜、勿奉事、勿祭祀、"],[12,17,36,"惟以大能奮臂、導爾出埃及之耶和華、爾當寅畏崇拜、而祭祀之、"],[12,17,37,"恆守其爲爾所錄之典章律例、法度誡命、而遵行之、勿寅畏他神、"],[12,17,38,"勿忘我與爾所立之約、勿寅畏他神、"],[12,17,39,"惟寅畏爾之上帝耶和華、彼必拯爾脫於諸敵之手、"],[12,17,40,"惟彼不聽、仍循往例、"],[12,17,41,"如是、斯族寅畏耶和華、又奉事其雕像、其子與孫亦若是、厥祖所行、彼亦效之、迄於今日、"],[12,18,1,"以色列王以拉子何細亞三年、猶大王亞哈斯子希西家卽位、"],[12,18,2,"時、年二十有五、在耶路撒冷爲王、歷二十九年、其母名亞比、撒迦利雅女也、"],[12,18,3,"希西家行耶和華所悅、悉效其祖大衞所爲、"],[12,18,4,"廢崇邱、毀其柱、斫木偶、昔摩西所作之銅蛇、至今以色列人對之焚香、希西家碎之、稱曰銅塊、"],[12,18,5,"惟倚恃以色列之上帝耶和華、其前後猶大列王中、無如之者、"],[12,18,6,"以其依附耶和華、從之弗離、遵守其所諭摩西之誡命、"],[12,18,7,"耶和華與之偕、凡其所往、無不亨通、背亞述王、不臣服之、"],[12,18,8,"擊非利士人、至於迦薩、與其四境、自戍樓以及堅城、○"],[12,18,9,"希西家王四年、卽以色列王以拉子何細亞七年、亞述王撒縵以色、上攻撒瑪利亞圍之、"],[12,18,10,"越至三年取之、卽希西家六年、以色列王何細亞九年、撒瑪利亞陷、"],[12,18,11,"亞述王虜以色列人至亞述、置於哈臘與歌散之哈博河濱、及瑪代諸邑、"],[12,18,12,"因彼不從其上帝耶和華之言、違背其約、凡耶和華僕摩西所命者、不聽不守之、○"],[12,18,13,"希西家王十四年、亞述王西拿基立、上攻猶大諸堅城取之、"],[12,18,14,"猶大王希西家遣使往拉吉、見亞述王曰、我獲罪矣、求爾離我、凡爾加諸我者、我必負之、亞述王遂定猶大王希西家納銀三百他連得、金三十他連得、"],[12,18,15,"希西家以耶和華室與王宮府庫、所有之銀餽之、"],[12,18,16,"當時猶大王希西家、斫耶和華殿門之金、與己所包柱之金、俱餽亞述王、"],[12,18,17,"亞述王遣他珥探、拉伯撒利、拉伯沙基、統率大軍、自拉吉至耶路撒冷、攻希西家王、旣至耶路撒冷、立於上沼之溝旁、漂工田之大路、"],[12,18,18,"呼王、有希勒家子家宰以利亞敬、與繕寫舍伯那、亞薩子史官約亞、俱出見之、"],[12,18,19,"拉伯沙基謂之曰、其告希西家曰、大王亞述王云、爾所恃者何耶、"],[12,18,20,"爾言有謀有勇、足以爲戰、此皆虛語、爾今恃誰而叛我、"],[12,18,21,"爾恃埃及、彼乃折葦之杖、人若賴之、必刺其手、凡恃埃及王法老者若是、"],[12,18,22,"如告我曰、我恃我之上帝耶和華、希西家非廢其崇邱與壇、命猶大及耶路撒冷人、惟於耶路撒冷壇前崇拜乎、"],[12,18,23,"今請以質予我主亞述王、若能備斯騎馬者、我則予爾馬二千、"],[12,18,24,"不然、曷能禦我主之僕、軍長至微之一、豈恃埃及、得其車騎耶、"],[12,18,25,"今我上攻此地而滅之、豈無耶和華之旨乎、耶和華乃命我曰、上攻此地而滅之、"],[12,18,26,"希勒家子以利亞敬、與舍伯那、約亞、謂拉伯沙基曰、請以亞蘭方言語爾僕、我儕識之、勿以猶大方言、使城上之民聞之、"],[12,18,27,"拉伯沙基曰、我主遣我、豈以此言僅告爾主及爾乎、非亦告坐於城上、將同爾食己矢、飲己溺之人乎、"],[12,18,28,"拉伯沙基遂立、以猶大方言、大聲呼曰、爾曹宜聽大王亞述王之言、"],[12,18,29,"王云、勿爲希西家所欺、彼不能拯爾脫於我手、"],[12,18,30,"勿聽希西家使爾恃耶和華曰、耶和華必拯我、此城必不付於亞述王手、"],[12,18,31,"勿聽希西家、蓋亞述王云、爾當與我修好、出而降我、則可各食己之葡萄、及無花果、各飲己井之水、"],[12,18,32,"迨我來遷爾至一地、如爾故土、有穀、有酒、有食品、及葡萄園、橄欖樹、與蜜、使爾生存、不至死亡、希西家勸爾曰、耶和華必拯我儕、勿聽其言、"],[12,18,33,"列國之神、有一曾拯其國、脫於亞述王手乎、"],[12,18,34,"哈馬與亞珥拔之神安在、西法瓦音希拿以瓦之神安在、凡此、曾拯撒瑪利亞脫於我手乎、"],[12,18,35,"列國之神、誰拯其國脫於我手、耶和華能拯耶路撒冷、脫於我手乎、"],[12,18,36,"民默然、不答一詞、蓋王命勿答之、"],[12,18,37,"希勒家子家宰以利亞敬、與繕寫舍伯那、亞薩子史官約亞、自裂其衣、詣希西家、以拉伯沙基言告之、"],[12,19,1,"希西家王聞之、自裂其衣、披麻入耶和華室、"],[12,19,2,"遣家宰以利亞敬、繕寫舍伯那、及祭司之長者、俱披麻、往見亞摩斯子先知以賽亞、"],[12,19,3,"謂之曰、希西家云、今乃急難譴責羞辱之日、子臨產、而無力出之、"],[12,19,4,"亞述王遣拉伯沙基侮維生之上帝、爾上帝耶和華或聞其言、加以譴責、請爾爲此遺民祈禱、"],[12,19,5,"希西家王之臣僕、遂詣以賽亞、"],[12,19,6,"以賽亞謂之曰、其告爾主曰、耶和華云、爾聞亞述王臣僕侮我之言、勿懼、"],[12,19,7,"我將以靈置於其衷、俾其聞風、而歸故土、在彼使仆於刃、○"],[12,19,8,"拉伯沙基聞亞述王已去拉吉、遂返、遇其適攻立拿、"],[12,19,9,"亞述王聞古實王特哈加出、欲與之戰、乃遣使見希西家曰、"],[12,19,10,"當告猶大王希西家云、爾所恃之上帝、謂耶路撒冷必不付於亞述王手、爾勿爲其所欺、"],[12,19,11,"亞述列王之待諸國、施行翦滅、爾旣聞之、而爾能得免乎、"],[12,19,12,"我祖所滅之邦、若歌散、哈蘭、利色、及居提拉撒之伊甸族、彼之諸神曾救之乎、"],[12,19,13,"哈馬王、亞珥拔王、西法瓦音邑之王、希拿與以瓦王、均安在哉、"],[12,19,14,"希西家自使者手接書讀之、遂上耶和華室、展於耶和華前、"],[12,19,15,"禱曰、居基路伯上、以色列之上帝耶和華歟、天下萬國、惟爾爲上帝、天地爲爾所造、"],[12,19,16,"耶和華歟、側耳而聽、耶和華歟、啟目而視、西拿基立遣使侮維生之上帝、請聽其言、"],[12,19,17,"耶和華歟、亞述列王毀滅列邦、荒其土地、誠有此事、"],[12,19,18,"投其神於火、蓋其神非神、乃木石、人手所造、故得而毀滅之、"],[12,19,19,"我之上帝耶和華歟、今求爾救我脫於其手、俾天下萬國、咸知惟爾耶和華爲上帝、○"],[12,19,20,"亞摩斯子以賽亞遣人告希西家曰、以色列之上帝耶和華云、爾緣亞述王西拿基立故、祈禱於我、我已聞之、"],[12,19,21,"耶和華指亞述王云、郇之處女藐視爾、姍笑爾、耶路撒冷女向爾搖首、"],[12,19,22,"爾所侮所謗者爲誰、向誰揚爾聲、高爾目、乃以色列之聖者也、"],[12,19,23,"爾藉使者侮主云、我率衆車陟於山巔、至利巴嫩之深處、伐其香柏之高者、松木之美者、將入其境之極處、卽腴壤之森林、"],[12,19,24,"我已掘井而飲異地之水、將以足掌涸竭埃及之河、"],[12,19,25,"耶和華曰、爾豈未聞我於元始所爲、上古所定、今則成之、使爾毀堅城爲瓦礫、"],[12,19,26,"故其居民力微、驚惶羞愧、如田草、如青蔬、如屋上之草、如未成而槁之禾、"],[12,19,27,"爾之居處、爾之出入、及向我之暴怒、我悉知之、"],[12,19,28,"因爾向我暴怒、及爾狂傲之聲、達於我耳、我必置鈎於爾鼻、置勒於爾口、使循原途而返、"],[12,19,29,"希西家乎、必有其徵、今歲食田所自生者、明年食其所復生者、迨及三年、可稼可穡、植葡萄園、而食其果、"],[12,19,30,"猶大家得脫之遺民、必下盤根、而上結實、"],[12,19,31,"將有遺民出自耶路撒冷、得脫之人出自錫安山、耶和華熱中、必成斯事、"],[12,19,32,"故耶和華指亞述王曰、彼必不至此城、不射一矢於彼、不執干至其前、不築壘以攻之、"],[12,19,33,"必循原途而返、不至此城、耶和華言之矣、"],[12,19,34,"蓋我爲己、及我僕大衞故、必扞衞此城、以拯救之、○"],[12,19,35,"是夜耶和華之使者出、在亞述營、擊其人十八萬五千、晨起視之、乃屍而已、"],[12,19,36,"亞述王西拿基立遂去而返、居於尼尼微、"],[12,19,37,"崇拜其神於尼斯洛廟時、亞得米勒與沙利色以刃弒之、遁於亞拉臘地、其子以撒哈頓嗣位、"],[12,20,1,"維時、希西家遘疾瀕死、亞摩斯子先知以賽亞來見之、曰、耶和華云、爾當處置家事、蓋爾必死、不得生存、"],[12,20,2,"希西家面壁、禱耶和華曰、"],[12,20,3,"耶和華歟、求爾垂念、我在爾前、行爲誠實、心志專一、行爾所悅、遂哭甚哀、"],[12,20,4,"以賽亞尚未出中院、耶和華諭之曰、"],[12,20,5,"返告我民之君希西家曰、爾祖大衞之上帝耶和華云、我已聞爾禱、見爾淚、必療爾疾、越至三日、爾必登耶和華室、"],[12,20,6,"我必增爾壽十五年、且救爾與此城、脫於亞述王手、亦爲己及我僕大衞故、扞衞此城、"],[12,20,7,"以賽亞曰、取一無花果餅至、遂取之、置於瘡處、王卽愈、"],[12,20,8,"希西家謂以賽亞曰、耶和華愈我、越至三日、我登耶和華室、有何徵乎、"],[12,20,9,"以賽亞曰、耶和華必成所言、有其徵焉、爾欲日影進十度乎、抑退十度乎、"],[12,20,10,"希西家曰、影進十度易、請使其退十度、"],[12,20,11,"先知以賽亞籲耶和華、遂使亞哈斯日晷已進之影退十度、○"],[12,20,12,"時、巴比倫王、巴拉但子比羅達巴拉但、聞希西家遘疾、致書饋禮、"],[12,20,13,"希西家聽使者之言、以其府庫之寶物、金銀香品寶膏、與武庫之器械、及所藏之寶物、悉示之、凡宮闈曁全國所有、無不示之、"],[12,20,14,"先知以賽亞詣希西家曰、斯人何言、奚自而來、希西家曰、來自遠方、卽巴比倫也、"],[12,20,15,"曰、彼於爾室、所見何物、希西家曰、凡我室中所有、彼悉觀之、我之寶藏、無不示之、"],[12,20,16,"以賽亞曰、其聽耶和華言、"],[12,20,17,"其日將至、爾室中所有者、與爾列祖至今所積者、必遷至巴比倫、不遺一物、耶和華言之矣、"],[12,20,18,"爾所生諸子中、必有被虜、在巴比倫王宮爲宦豎、"],[12,20,19,"希西家謂以賽亞曰、爾所傳耶和華之言善矣、又曰、若我尚存之日、得其綏安穩固、豈非善乎、"],[12,20,20,"希西家其餘事蹟、與其勇力、以及鑿池掘溝、引水入邑、俱載於猶大列王紀、"],[12,20,21,"希西家與列祖偕眠、子瑪拿西嗣位、"],[12,21,1,"瑪拿西卽位時、年十有二、在耶路撒冷爲王、歷五十五年、其母名協西巴、"],[12,21,2,"瑪拿西行耶和華所惡、效異邦可憎之事、卽耶和華於以色列人前、所逐諸族之事、"],[12,21,3,"復建其父希西家所毀之崇邱、爲巴力建壇、作木偶、效以色列王亞哈所爲、又崇拜天象、而奉事之、"],[12,21,4,"在耶和華室建壇、昔耶和華指此室而言曰、我必寄我名於耶路撒冷、"],[12,21,5,"又在耶和華室二院中、爲天象建壇、"],[12,21,6,"並使其子經火、用卜筮、行邪術、與憑鬼者及巫覡交、多行耶和華所惡、以激其怒、"],[12,21,7,"又於耶和華室、置所造之亞舍拉雕像、昔耶和華諭大衞、及其子所羅門曰、此室與耶路撒冷、乃我於以色列支派中所簡者、必永寄我名於其中、"],[12,21,8,"如以色列人謹守遵行我命、及我僕摩西所命之法律、則我不復使之流離、去我賜其列祖之地、"],[12,21,9,"惟彼不聽、瑪拿西又誘之、致其作惡、較耶和華在以色列人前、所滅之族尤甚、"],[12,21,10,"耶和華藉其僕諸先知曰、"],[12,21,11,"因猶大王瑪拿西行此可憎之事、較亞摩利人作惡尤甚、使猶大人因其偶像而陷於罪、"],[12,21,12,"故以色列之上帝耶和華云、我必降禍於耶路撒冷及猶大、使凡聞之者、兩耳必震、"],[12,21,13,"我將以量撒瑪利亞之繩、平亞哈家之準、施於耶路撒冷、且拭耶路撒冷、如人拭盂而覆之、"],[12,21,14,"亦必棄我遺民、付於敵手、使爲敵人虜掠刼奪、"],[12,21,15,"因其行我所惡、激我之怒、自其列祖出埃及、以迄於今、○"],[12,21,16,"瑪拿西行耶和華所惡、陷猶大人於罪、此外、又多流無辜之血、遍滿耶路撒冷四境、"],[12,21,17,"瑪拿西其餘事蹟、凡其所行、及其所犯之罪、俱載於猶大列王紀、"],[12,21,18,"瑪拿西與列祖偕眠、葬於己宮之園、卽烏撒園、子亞們嗣位、○"],[12,21,19,"亞們卽位時、年二十有二、在耶路撒冷爲王、凡歷二年、其母名米舒利密、約提巴人哈魯斯女也、"],[12,21,20,"亞們行耶和華所惡、如其父瑪拿西所爲、"],[12,21,21,"循其父所行之道、事其父所事之偶像、而崇拜之、"],[12,21,22,"離棄其列祖之上帝耶和華、不遵行耶和華之道、"],[12,21,23,"亞們之臣謀叛、弒之於其宮、"],[12,21,24,"國人盡殺凡叛亞們王者、立其子約西亞繼之爲王、"],[12,21,25,"亞們其餘所行之事、俱載於猶大列王紀、"],[12,21,26,"亞們葬於己墓、在烏撒園、子約西亞嗣位、"],[12,22,1,"約西亞卽位時、年八齡、在耶路撒冷爲王、歷三十一年、其母名耶底大、波斯加人亞大雅女也、"],[12,22,2,"約西亞行耶和華所悅、循其祖大衞之道、不偏於左、不偏於右、○"],[12,22,3,"約西亞王十八年、遣米書蘭孫、亞薩利子、繕寫沙番、至耶和華室、命之曰、"],[12,22,4,"往見大祭司希勒家、使核閽人所取於民、輸入耶和華室之金、"],[12,22,5,"俾付於督耶和華室之工作者、轉予在室之工匠、修葺其破壞、"],[12,22,6,"卽予木工、匠役、瓦工、又購材木、與鑿成之石、修葺殿宇、"],[12,22,7,"以金付於其手、不與核算其數、因其行事誠實也、"],[12,22,8,"大祭司希勒家謂繕寫沙番曰、我於耶和華室得律書、乃授書於沙番、沙番讀之、"],[12,22,9,"繕寫沙番詣王復命曰、爾之臣僕、已將室中所貯之金、傾而出之、付於督耶和華室之工作者、"],[12,22,10,"又奏王曰、祭司希勒家授我一書、遂讀於王前、"],[12,22,11,"王聞律書之言、自裂其衣、"],[12,22,12,"命祭司希勒家、沙番子亞希甘、米該亞子亞革波、繕寫沙番、及王侍臣亞撒雅曰、"],[12,22,13,"汝其往哉、爲我爲民、爲猶大衆、以此書之言、詢於耶和華、因我列祖不聽此書之言、不遵所載諭我儕者而行、故耶和華向我、發怒甚烈、"],[12,22,14,"有女先知戶勒大、乃哈珥哈斯孫、特瓦子、掌禮服者沙龍之妻也、居耶路撒冷之二區、祭司希勒家、亞希甘、亞革波、沙番、亞撒雅、咸往見之、與之共語、"],[12,22,15,"戶勒大謂之曰、以色列之上帝耶和華云、其告遣爾詣我者曰、"],[12,22,16,"耶和華云、我必降災於此處、及其居民、循猶大王所誦書中之言、"],[12,22,17,"蓋彼衆棄我、焚香於他神、以其手所爲、激我之怒、故我發怒於此而不息、"],[12,22,18,"惟猶大王遣爾詢於耶和華、當告之曰、以色列之上帝耶和華云、論爾所聞之言、"],[12,22,19,"爾聞我指此地、與其居民所言、必爲荒墟、而受呪詛、乃中心柔順、自卑於耶和華前、裂衣哭泣、我俞允爾、耶和華言之矣、"],[12,22,20,"我必使爾安然入墓、歸爾列祖、我將降於此地之災、爾不目擊、使者復命於王、"],[12,23,1,"王遣人集猶大及耶路撒冷諸長老、"],[12,23,2,"王與猶大人、耶路撒冷居民、祭司先知、及所有民衆、無論長幼、咸上耶和華室、王誦耶和華室中、所得約書之言、俾衆聽聞、"],[12,23,3,"王立於柱側、在耶和華前立約、一心一意順從耶和華、守其誡命、法度典章、以成約書所載之言、民亦服從此約、"],[12,23,4,"王命大祭司希勒家、與諸副祭司、及閽人、由耶和華殿、取出爲巴力亞舍拉曁天象、所製之器皿、焚於耶路撒冷外、汲淪田間、攜其灰至伯特利、"],[12,23,5,"昔猶大列王所立奉偶像之祭司、使於猶大諸邑之崇邱、曁耶路撒冷四周焚香者、王悉廢之、又廢焚香於巴力、與日月行星、及諸天象者、"],[12,23,6,"亦出亞舍拉像於耶和華室、攜至耶路撒冷外、焚於汲淪溪濱、搗之成粉、揚於平民之墓、"],[12,23,7,"毀耶和華室中孌童之舍、卽婦女織亞舍拉帷帳之所、"],[12,23,8,"又從猶大諸邑、攜諸祭司而出、汚衊祭司昔所焚香之崇邱、自迦巴至別是巴、並毀城門左、邑宰約書亞門前之崇邱、"],[12,23,9,"惟崇邱之祭司、不登耶路撒冷耶和華之壇、祇於其昆弟中、食無酵餅而已、"],[12,23,10,"又汚衊欣嫩子谷之陀斐特、免人使其子女經火、以奉摩洛、"],[12,23,11,"猶大列王所獻於日之馬、乃在耶和華室門之側、宦豎拿單米勒附近廊廡之室、王悉去之、且焚日車、"],[12,23,12,"猶大列王在亞哈斯樓巔所建之壇、及瑪拿西在耶和華室二院中所建之壇、王悉毀而碎之、攜其塵土、傾於汲淪溪、"],[12,23,13,"昔以色列王所羅門、在耶路撒冷東、邪僻山南、爲西頓人可憎之神亞斯他錄、摩押人可憎之神基抹、亞捫人可憎之神米勒公、所建之崇邱、王悉汚衊之、"],[12,23,14,"碎其柱像、斫其木偶、以人骨充其所、"],[12,23,15,"昔尼八子耶羅波安、在伯特利築壇及崇邱、陷以色列人於罪者、王悉毀之、焚其邱壇、搗之成粉、並焚木偶、"],[12,23,16,"約西亞回顧、見山中有墓、遣人自墓取骨、而焚於壇、以汚衊之、如上帝僕所傳耶和華之言、"],[12,23,17,"約西亞曰、我所見者、何碑也、邑人告曰、昔有上帝僕自猶大來、言王今所行於伯特利壇之事、此其墓碑也、"],[12,23,18,"約西亞曰、舍之、勿移其骨、遂舍之、亦舍自撒瑪利亞來之先知骨、"],[12,23,19,"昔以色列列王在撒瑪利亞諸邑、建崇邱之室、激耶和華怒、約西亞悉除之、如所行於伯特利然、"],[12,23,20,"殺崇邱之祭司於壇、焚人骨於其上、乃返耶路撒冷、○"],[12,23,21,"王命民衆曰、當爲爾之上帝耶和華、守逾越節、循此約書所載、"],[12,23,22,"自士師治以色列人、以及以色列列王猶大列王時、未嘗守如是之逾越節、"],[12,23,23,"乃於約西亞王十八年、在耶路撒冷、爲耶和華守此逾越節、"],[12,23,24,"猶大地及耶路撒冷、所有憑鬼者曁巫覡、與家神偶像、並一切可憎之物、約西亞悉除之、循祭司希勒家在耶和華室、所得律書記載之言、"],[12,23,25,"在約西亞以前、無王如彼盡心盡意盡力、歸向耶和華、遵行摩西一切法律、其後亦無如之者、"],[12,23,26,"然耶和華向猶大之烈怒猶未息、因瑪拿西諸事激之也、"],[12,23,27,"耶和華曰、我將屛猶大人於我前、如屛以色列人然、棄我所簡此邑耶路撒冷、及我所言必寄我名之室、"],[12,23,28,"約西亞其餘事蹟、凡其所行、俱載於猶大列王紀、"],[12,23,29,"當其在時、埃及王法老尼哥往伯拉河、攻亞述王、約西亞王出而禦之、法老尼哥遇之於米吉多殺之、"],[12,23,30,"臣僕以車載其屍、自米吉多至耶路撒冷、葬於其墓、國民膏約西亞子約哈斯、立之爲王、以繼其父、○"],[12,23,31,"約哈斯卽位時、年二十有三、在耶路撒冷爲王、僅歷三月、其母哈慕他、立拿人耶利米女也、"],[12,23,32,"約哈斯行耶和華所惡、效其列祖所爲、"],[12,23,33,"法老尼哥繫之於哈馬地之利比拉、不使爲王於耶路撒冷、又徵猶大國銀一百他連得、金一他連得、"],[12,23,34,"法老尼哥立約西亞子以利亞敬、繼其父爲王、易其名曰約雅敬、攜約哈斯至埃及、卒於彼、"],[12,23,35,"約雅敬循法老命、徵金銀於國民、乃按其人之力、爲定數而取之、以予法老尼哥、○"],[12,23,36,"約雅敬卽位時、年二十有五、在耶路撒冷爲王、歷十一年、其母名西布大、魯瑪人毘大雅女也、"],[12,23,37,"約雅敬行耶和華所惡、效其列祖所爲、"],[12,24,1,"約雅敬時、巴比倫王尼布甲尼撒至、約雅敬臣服之、歷至三年、乃背叛之、"],[12,24,2,"耶和華使迦勒底軍、亞蘭軍、摩押軍、及亞捫族軍攻之、侵猶大欲滅之、如耶和華藉其僕衆先知所言、"],[12,24,3,"此事臨及猶大、乃耶和華所命、以屛之於其前、因瑪拿西所犯諸罪也、"],[12,24,4,"且因其流無辜之血、遍滿耶路撒冷、耶和華不赦之、"],[12,24,5,"約雅敬其餘事蹟、凡其所行、俱載於猶大列王紀、"],[12,24,6,"約雅敬與列祖偕眠、子約雅斤嗣位、"],[12,24,7,"埃及王不復由其國而來、乃因巴比倫王攻取其地、自埃及溪至伯拉河、○"],[12,24,8,"約雅斤卽位時、年十八歲、在耶路撒冷爲王、僅歷三月、其母名尼護施他、耶路撒冷人以利拿單女也、"],[12,24,9,"約雅斤行耶和華所惡、效其父所爲、"],[12,24,10,"時、巴比倫王尼布甲尼撒之臣僕、上至耶路撒冷圍之、"],[12,24,11,"當其臣僕圍城時、尼布甲尼撒至、"],[12,24,12,"猶大王約雅斤與其母、及其臣僕、牧伯宦豎出降、巴比倫王執之、此巴比倫王八年事也、"],[12,24,13,"取耶和華室及王宮之寶物、悉攜之出、又碎以色列王所羅門所製耶和華殿中諸金器、如耶和華所言、"],[12,24,14,"又將耶路撒冷民衆、與牧伯勇士、共萬人、以及匠役鐵工、悉虜之去、除極貧者外、斯土無餘民焉、"],[12,24,15,"俘約雅斤與其母、及后妃宦豎、曁國中顯者、自耶路撒冷至巴比倫、"],[12,24,16,"又虜武士七千、匠役鐵工一千、皆善戰之壯士、俱攜至巴比倫、"],[12,24,17,"巴比倫王立約雅斤叔瑪探雅、代之爲王、易其名曰西底家、○"],[12,24,18,"西底家卽位時、年二十有一、在耶路撒冷爲王、歷十一年、其母名哈慕他、立拿人耶利米女也、"],[12,24,19,"西底家行耶和華所惡、效約雅敬所爲、"],[12,24,20,"耶和華怒耶路撒冷及猶大、致屛之於其前、"],[12,25,1,"西底家叛巴比倫王、九年十月十日、巴比倫王尼布甲尼撒率其全軍、至耶路撒冷建營、四周築壘攻之、"],[12,25,2,"城被困、至西底家王十一年、"],[12,25,3,"四月九日、邑中饑甚、斯土之民絕糧、"],[12,25,4,"於是穴城、戰士由附近王囿兩垣間之門夜遁、迦勒底人環城、王由亞拉巴道而走、"],[12,25,5,"迦勒底軍追之、及於耶利哥之平原、王軍潰散、"],[12,25,6,"迦勒底軍執王、解至利比拉、巴比倫王所、而審鞫之、"],[12,25,7,"戮其諸子、使之目睹、抉其兩目、縶之以鏈、攜至巴比倫、○"],[12,25,8,"巴比倫王尼布甲尼撒十九年五月七日、其臣侍衞長尼布撒拉旦至耶路撒冷、"],[12,25,9,"燬耶和華室與王宮、及耶路撒冷諸屋、所有第宅、悉焚以火、"],[12,25,10,"從侍衞長之迦勒底軍、毀耶路撒冷四周城垣、"],[12,25,11,"邑中餘民、與降於巴比倫王者、以及所遺之衆、侍衞長尼布撒拉旦悉虜之去、"],[12,25,12,"惟留極貧者於斯土、以治葡萄園、耕種田畝、"],[12,25,13,"耶和華室中之銅柱、銅座、及銅海、迦勒底人悉碎之、而攜其銅至巴比倫、"],[12,25,14,"其釜鏟剪匙、及諸銅器、供事所用者、悉攜之去、"],[12,25,15,"火鼎及盂、金製者取其金、銀製者取其銀、侍衞長悉攜之去、"],[12,25,16,"又攜所羅門爲耶和華室、所製二銅柱、及銅海與座、此諸器之銅、未詳其輕重、"],[12,25,17,"柱高十八肘、上有銅頂高三肘、頂之四圍有網、與石榴、悉以銅製、彼柱與網亦若是、"],[12,25,18,"侍衞長執祭司長西萊雅、副祭司西番亞、及閽者三人、"],[12,25,19,"又於城內、執統轄武士之宦豎一人、王之近臣五人、軍長之繕寫、募國民者一人、及邑中所獲之國民六十人、"],[12,25,20,"侍衞長尼布撒拉旦咸解至利比拉、巴比倫王所、"],[12,25,21,"巴比倫王擊而殺之於哈馬地之利比拉、如是猶大人被虜、離其故土、"],[12,25,22,"猶大地之餘民、卽巴比倫王尼布甲尼撒所遺者、巴比倫王立沙番孫、亞希甘子基大利、爲其方伯、○"],[12,25,23,"諸軍長及其從者、聞巴比倫王立基大利爲方伯、於是尼探雅子以實瑪利、加利亞子約哈難、尼陀法人單戶篾子西萊雅、瑪迦人子雅撒尼亞、及其從者、咸至米斯巴、見基大利、"],[12,25,24,"基大利與諸軍長、及其從者誓曰、毋緣迦勒底之臣僕而懼、其居斯土、服事巴比倫王、則獲平康、"],[12,25,25,"七月、王族以利沙瑪孫、尼探雅子以實瑪利、率十人至、擊斃基大利、及同在米斯巴之猶大人、迦勒底人、"],[12,25,26,"於是民衆無論尊卑、及諸軍長、咸起而往埃及、畏迦勒底人故也、○"],[12,25,27,"猶大王約雅斤被虜後三十七年、巴比倫王以未米羅達卽位元年、十二月二十七日、拔猶大王約雅斤出獄、"],[12,25,28,"以善言慰之、使其位高於同在巴比倫諸王之位、"],[12,25,29,"易其囚服、畢生與王共食、"],[12,25,30,"王日賜其所需、終身不匱、"],[13,1,1,"亞當之後、繼有塞特、以挪士、"],[13,1,2,"該南、瑪勒列、雅列、"],[13,1,3,"以諾、馬土撒拉、拉麥、"],[13,1,4,"挪亞、閃、含、雅弗、○"],[13,1,5,"雅弗子、歌篾、瑪各、瑪代、雅完、土巴、米設、提拉、"],[13,1,6,"歌篾子、亞實基拿、低法、陀迦瑪、"],[13,1,7,"雅完子、以利沙、他施、基提、多單、○"],[13,1,8,"含子、古實、麥西、弗、迦南、"],[13,1,9,"古實子、西巴、哈腓拉、撒弗他、拉瑪、撒弗提迦、拉瑪子、示巴、底但、"],[13,1,10,"古實生甯錄、在世始爲英武、"],[13,1,11,"麥西生路低、亞拿米、利哈比、拿弗土希、"],[13,1,12,"帕斯魯細、迦斯路希、迦斐託諸族、非利士族由迦斯路希而出、"],[13,1,13,"迦南生冢子西頓、又生赫、"],[13,1,14,"耶布斯、亞摩利、革迦撒、"],[13,1,15,"希未、亞基、西尼、"],[13,1,16,"亞瓦底、洗瑪利、哈馬諸族、○"],[13,1,17,"閃之子、以攔、亞述、亞法撒、路德、亞蘭、烏斯、戶勒、基帖、米設、"],[13,1,18,"亞法撒生沙拉、沙拉生希伯、"],[13,1,19,"希伯生二子、一名法勒、因其時世人分析也、法勒之弟名約坍、"],[13,1,20,"約坍生亞摩答、沙列、哈薩瑪非、耶拉、"],[13,1,21,"哈多蘭、烏薩、德拉、"],[13,1,22,"以巴錄、亞比瑪利、示巴、"],[13,1,23,"阿斐、哈腓拉、約巴、此皆約坍之子、○"],[13,1,24,"閃之後、繼有亞法撒、沙拉、"],[13,1,25,"希伯、法勒、拉吳、"],[13,1,26,"西鹿、拿鶴、他拉、"],[13,1,27,"亞伯蘭、卽亞伯拉罕、○"],[13,1,28,"亞伯拉罕子、以撒、以實瑪利、"],[13,1,29,"以實瑪利裔如左、長子尼拜約、次基達、押德別、米比衫、"],[13,1,30,"米施瑪、度瑪、瑪撒、哈達、提瑪、"],[13,1,31,"伊突、拿非施、基底瑪、此皆以實瑪利之子、○"],[13,1,32,"亞伯拉罕妾基土拉所生之子、乃心蘭、約珊、米但、米甸、伊施巴、書亞、約珊子、示巴、底但、"],[13,1,33,"米甸子、以法、以弗、哈諾、亞比大、以勒大、此皆基土拉之子孫、○"],[13,1,34,"亞伯拉罕子以撒、以撒子以掃、以色列、○"],[13,1,35,"以掃子、以利法、流珥、耶烏施、雅蘭、可拉、"],[13,1,36,"以利法子、提幔、阿抹、洗玻、迦坦、基納斯、亭納、亞瑪力、"],[13,1,37,"流珥子、拿哈、謝拉、沙瑪、米撒、○"],[13,1,38,"西珥子、羅坍、朔巴、祭便、亞拿、底順、以察、底珊、"],[13,1,39,"羅坍子、何利、荷幔、羅坍之妹、亭納、"],[13,1,40,"朔巴子、亞勒文、瑪拿轄、以巴錄、示非、阿南、祭便子、亞雅、亞拿、"],[13,1,41,"亞拿子、底順、底順子、哈默蘭、伊是班、益蘭、基蘭、"],[13,1,42,"以察子、辟罕、撒番、亞干、底珊子、烏斯、亞蘭、○"],[13,1,43,"當以色列人無王主治時、於以東地爲王者、其名如左、比珥子比拉、都亭哈巴、"],[13,1,44,"比拉薨、波斯拉人謝拉子約巴嗣位、"],[13,1,45,"約巴薨、提幔人戶珊嗣位、"],[13,1,46,"戶珊薨、比達子哈達、卽於摩押田擊米甸人者嗣位、都亞未得、"],[13,1,47,"哈達薨、瑪士利加人桑拉嗣位、"],[13,1,48,"桑拉薨、河濱利河伯人掃羅嗣位、"],[13,1,49,"掃羅薨、亞革波子巴勒哈南嗣位、"],[13,1,50,"巴勒哈南薨、哈達嗣位、都巴伊、其后米希他別、乃米薩合孫、瑪特列女也、"],[13,1,51,"哈達旣沒、在以東爲族長者如左、亭納族長、亞勒瓦族長、耶帖族長、"],[13,1,52,"亞何利巴瑪族長、以拉族長、比嫩族長、"],[13,1,53,"基納斯族長、提幔族長、米比薩族長、"],[13,1,54,"瑪基疊族長、以蘭族長、此皆以東之族長也、"],[13,2,1,"以色列子、流便、西緬、利未、猶大、以薩迦、西布倫、"],[13,2,2,"但、約瑟、便雅憫、拿弗他利、迦得、亞設、○"],[13,2,3,"猶大子、珥、俄南、示拉、皆迦南人書亞之女所出、猶大長子珥、行耶和華所惡、耶和華殺之、"],[13,2,4,"猶大媳他瑪、爲之生法勒斯、謝拉、猶大共五子、○"],[13,2,5,"法勒斯子、希斯崙、哈母勒、"],[13,2,6,"謝拉子、心利、以探、希幔、甲各、大拉、共五人、"],[13,2,7,"迦米子亞干、卽因當滅之物、困苦以色列族者、"],[13,2,8,"以探子亞撒利雅、○"],[13,2,9,"希斯崙所生之子、耶拉篾、蘭、基路拜、"],[13,2,10,"蘭生亞米拿達、亞米拿達生拿順、爲猶大族之牧伯、"],[13,2,11,"拿順生撒門、撒門生波阿斯、"],[13,2,12,"波阿斯生俄備得、俄備得生耶西、"],[13,2,13,"耶西生長子以利押、次子亞比拿達、三子示米亞、"],[13,2,14,"四子拿坦業、五子拉代、"],[13,2,15,"六子阿鮮、七子大衞、"],[13,2,16,"其姊妹乃洗魯雅、亞比該、洗魯雅生亞比篩、約押、亞撒黑三人、"],[13,2,17,"亞比該生亞瑪撒、亞瑪撒之父、乃以實瑪利人益帖、○"],[13,2,18,"希斯崙子迦勒、娶阿蘇巴與耶畧爲妻、生子、阿蘇巴生耶設、朔罷、押墩、"],[13,2,19,"阿蘇巴旣沒、迦勒又娶以法他、生戶珥、"],[13,2,20,"戶珥生烏利、烏利生比撒列、○"],[13,2,21,"厥後、希斯崙年六十、娶基列父瑪吉之女、生西割、"],[13,2,22,"西割生睚珥、睚珥在基列地、有邑二十三、"],[13,2,23,"後基述人與亞蘭人、奪睚珥諸邑、及基納與其鄉里、共六十、皆屬基列父瑪吉之子、"],[13,2,24,"希斯崙在迦勒以法他沒後、其妻亞比雅爲之生亞施戶、爲提哥亞族祖、○"],[13,2,25,"希斯崙長子耶拉篾、生長子蘭、又生布拿、阿連、阿鮮、亞希雅、"],[13,2,26,"耶拉篾又娶妻名亞他拉、乃阿南之母、"],[13,2,27,"耶拉篾長子蘭之子、瑪斯、雅憫、以結、"],[13,2,28,"阿南子、沙買、雅大、沙買子、拿答、亞比述、"],[13,2,29,"亞比述妻名亞比孩、爲之生亞辦、與摩利、"],[13,2,30,"拿答子、西列、亞遍、西列無子而死、"],[13,2,31,"亞遍子以示、以示子示珊、示珊子亞來、"],[13,2,32,"沙買弟雅大子、益帖、約拿單、益帖無子而死、"],[13,2,33,"約拿單子、比勒、撒薩、此皆耶拉篾之子孫、"],[13,2,34,"示珊無子、惟女而已、有僕埃及人、名耶哈、"],[13,2,35,"示珊以女妻之、生亞太、"],[13,2,36,"亞太生拿單、拿單生撒拔、"],[13,2,37,"撒拔生以弗拉、以弗拉生俄備得、"],[13,2,38,"俄備得生耶戶、耶戶生亞撒利雅、"],[13,2,39,"亞撒利雅生希利斯、希利斯生以利亞薩、"],[13,2,40,"以利亞薩生西斯買、西斯買生沙龍、"],[13,2,41,"沙龍生耶加米雅、耶加米雅生以利沙瑪、○"],[13,2,42,"耶拉篾弟迦勒生長子米沙、爲西弗族祖、又生瑪利沙、爲希伯崙族祖、"],[13,2,43,"希伯崙子、可拉、他普亞、利肯、示瑪、"],[13,2,44,"示瑪生拉含、爲約干族祖、利肯生沙買、"],[13,2,45,"沙買子瑪雲、爲伯夙族祖、"],[13,2,46,"迦勒妾以法生哈蘭、摩撒、迦謝、哈蘭生迦卸、"],[13,2,47,"雅代子、利健、約坦、基珊、毘力、以法、沙亞弗、"],[13,2,48,"迦勒妾瑪迦生示別、特哈拿、"],[13,2,49,"又生麥瑪拿族之祖沙亞弗、抹比拿族及基比亞族之祖示法、迦勒之女乃押撒、○"],[13,2,50,"迦勒之裔、以法他長子戶珥之子如左、基列耶琳族祖朔巴、"],[13,2,51,"伯利恆族祖薩瑪、伯迦得族祖哈勒、"],[13,2,52,"基列耶琳族祖朔巴、亦有子孫、爲哈羅以族、及米努哈族之半、"],[13,2,53,"基列耶琳諸族、乃以帖族、布特族、舒瑪族、密來族、瑣拉與以實陶二族、自此諸族而出、"],[13,2,54,"薩瑪子孫、乃伯利恆人、尼陀法人、亞他綠伯約押人、瑪拿哈族之半、及瑣利人、"],[13,2,55,"居雅比斯繕寫之家、特拉人、示米押人、蘇甲人、此皆基尼人、出於利甲家之祖哈末、"],[13,3,1,"大衞在希伯崙所生之子如左、長子暗嫩、耶斯列人亞希暖所出、次子但以利、迦密人亞比該所出、"],[13,3,2,"三子押沙龍、基述王達買女瑪迦所出、四子亞多尼雅、哈及所出、"],[13,3,3,"五子示法提雅、亞比他所出、六子以特念、大衞妻以格拉所出、"],[13,3,4,"此六子、皆大衞於希伯崙所生、大衞在彼爲王、七年有六月、在耶路撒冷爲王、三十三年、"],[13,3,5,"在耶路撒冷生子示米亞、朔罷、拿單、所羅門、四人俱亞米利女拔書亞所出、"],[13,3,6,"又生益轄、以利沙瑪、以利法列、"],[13,3,7,"挪迦、尼斐、雅非亞、"],[13,3,8,"以利沙瑪、以利雅大、以利法列九人、"],[13,3,9,"皆爲大衞之子、此外更有嬪妃所出、他瑪爲女弟、"],[13,3,10,"所羅門子羅波安、羅波安子亞比雅、亞比雅子亞撒、亞撒子約沙法、"],[13,3,11,"約沙法子約蘭、約蘭子亞哈謝、亞哈謝子約阿施、"],[13,3,12,"約阿施子亞瑪謝、亞瑪謝子亞撒利雅、亞撒利雅子約坦、"],[13,3,13,"約坦子亞哈斯、亞哈斯子希西家、希西家子瑪拿西、"],[13,3,14,"瑪拿西子亞們、亞們子約西亞、"],[13,3,15,"約西亞子如左、長子約哈難、次子約雅敬、三子西底家、四子沙龍、"],[13,3,16,"約雅敬子耶哥尼雅、西底家、"],[13,3,17,"耶哥尼雅被虜、其子撒拉鐵、"],[13,3,18,"瑪基蘭、毘大雅、示拿薩、耶加米、何沙瑪、尼大比雅、"],[13,3,19,"毘大雅子所羅巴伯、示每、所羅巴伯子米書蘭、哈拿尼雅、示羅密爲女弟、"],[13,3,20,"又有哈舒巴、阿黑、比利家、哈撒底、于沙希悉五人、"],[13,3,21,"哈拿尼雅子毘拉提、耶篩亞、又有利法雅衆子、亞珥難衆子、俄巴底亞衆子、示迦尼衆子、"],[13,3,22,"示迦尼子示瑪雅、示瑪雅子、哈突、以甲、巴利亞、尼利雅、沙法六人、"],[13,3,23,"尼利雅子、以利約乃、希西家、阿斯利干三人、"],[13,3,24,"以利約乃子、何大雅、以利亞實、毘萊雅、阿谷、約哈難、第萊雅、阿拿尼七人、"],[13,4,1,"猶大子、法勒斯、希斯崙、迦米、戶珥、朔巴、"],[13,4,2,"朔巴子利亞雅生雅哈、雅哈生亞戶買、拉哈、此爲瑣拉人之室家、"],[13,4,3,"以坦族祖生耶斯列、伊施瑪、伊得巴、哈悉勒玻尼爲女弟、"],[13,4,4,"基多族祖毘努伊勒、戶沙族祖以謝珥、皆伯利恆族祖、以法他長子戶珥所生、"],[13,4,5,"提哥亞族祖亞施戶有二妻、希拉、拿拉、"],[13,4,6,"拿拉生亞戶散、希弗、提米尼、哈轄斯他利、皆拿拉之子、"],[13,4,7,"希拉子、洗列、瑣轄、伊提南、"],[13,4,8,"哥斯生亞諾、瑣比巴、哈崙子亞哈黑諸家、亦其後裔、"],[13,4,9,"雅比斯較諸昆弟爲尊、其母命名雅比斯、曰、我劬勞產之、"],[13,4,10,"雅比斯籲以色列之上帝曰、願爾錫我福祉、擴我土宇、扶我以手、俾免遭難遇苦、上帝允其所祈、"],[13,4,11,"書哈兄基綠生米黑、爲伊施屯之父、"],[13,4,12,"伊施屯生伯拉巴、巴西亞、及珥拿轄人之祖提欣拿、皆利迦人、"],[13,4,13,"基納斯子俄陀聶、西萊雅、俄陀聶子哈塔、"],[13,4,14,"憫挪太生俄弗拉、西萊雅生約押、爲工師谷人之祖、其人皆工師也、"],[13,4,15,"耶孚尼子迦勒、其子以路、以拉、拿安、以拉子基納斯、"],[13,4,16,"耶哈利勒子、西弗、西法、提利、亞撒列、"],[13,4,17,"以斯拉子、益帖、米列、以弗、雅倫、米列娶法老女比提雅、生米利暗、沙買、與以實提摩族祖益巴、"],[13,4,18,"其妻猶大婦、生基多族祖雅列、梭哥族祖希伯、撒挪亞族祖耶古鐵、"],[13,4,19,"拿含之妹、荷第雅妻、生迦米人基伊拉、及瑪迦人以實提摩、"],[13,4,20,"示門子、暗嫩、林拿、便哈南、提倫、以示子、梭黑、便梭黑、"],[13,4,21,"猶大子示拉、生利迦族祖珥、瑪利沙族祖拉大、及屬亞實比族、織枲諸家、"],[13,4,22,"又生約敬、哥西巴人、與約阿施、及治摩押地之薩拉、並雅叔比利恆、此乃古昔之錄、"],[13,4,23,"皆爲陶人、居於尼他應、及基低拉、與王同處、爲王服役、○"],[13,4,24,"西緬子、尼母利、雅憫、雅立、謝拉、掃羅、"],[13,4,25,"掃羅子沙龍、沙龍子米比衫、米比衫子米施瑪、"],[13,4,26,"米施瑪子哈母利、哈母利子撒刻、撒刻子示每、"],[13,4,27,"示每有子十六、女六、惟其昆弟、子女無幾、其家不及猶大人之繁衍、"],[13,4,28,"西緬人居別是巴、摩拉大、哈薩書亞、"],[13,4,29,"辟拉、以森、陀臘、"],[13,4,30,"彼土利、何珥瑪、洗革拉、"],[13,4,31,"伯瑪嘉博、哈薩蘇撒、伯比利、沙拉音、至大衞爲王時、此諸邑悉屬西緬人、"],[13,4,32,"其鄉里凡五、乃以坦、亞因、臨門、陀健、亞珊、"],[13,4,33,"及其四周之鄉里、至於巴力、其所居之處卽此、各有譜系、"],[13,4,34,"亦有米所巴、雅米勒、亞瑪謝子約沙、"],[13,4,35,"約珥、約示比子耶戶、約示比乃西萊雅子、西萊雅乃亞薛子、"],[13,4,36,"又有以利約乃、雅哥巴、耶朔海、亞帥雅、亞底業、耶西篾、比拿雅、"],[13,4,37,"及示瑪雅耳孫、申利玄孫、耶大雅曾孫、亞龍孫、示非子細撒、"],[13,4,38,"以上所載、悉爲宗族牧伯、其家增益繁多、"],[13,4,39,"其衆往谷之東、至基多界、求芻以牧羣羊、"],[13,4,40,"乃得牧場、土壤膏腴、幅員寬廣、靜謐平康、居民本屬含族、"],[13,4,41,"當猶大王希西家時、以上所載之人、來攻其幕、及其同處之米烏尼人、盡滅其衆、據居其地、迄於今日、以斯土有芻牧羣羊也、"],[13,4,42,"西緬族五百人、往西珥山、以示子毘拉提、尼利雅、利法雅、烏薛爲之長、"],[13,4,43,"擊亞瑪力族逃脫之遺民、而居其地、迄於今日、"],[13,5,1,"流便爲以色列長子、因汚其父之榻、故長子之業、歸於以色列子約瑟之子、惟譜系不依此記載、"],[13,5,2,"猶大超越諸昆弟、君王由彼而出、第長子之業歸約瑟、"],[13,5,3,"以色列長子流便之子、哈諾、法路、希斯崙、迦米、"],[13,5,4,"約珥子示瑪雅、示瑪雅子歌革、歌革子示每、"],[13,5,5,"示每子米迦、米迦子利亞雅、利亞雅子巴力、"],[13,5,6,"巴力子備拉、乃流便族牧伯、爲亞述王提革拉毘尼色所虜、"],[13,5,7,"其昆弟按室家譜系爲長者、乃耶利、撒迦利雅、"],[13,5,8,"與約珥曾孫、示瑪孫、亞撒子比拉、彼居亞羅珥、延至尼波、及巴力免、"],[13,5,9,"又東、至伯拉河西之曠野、蓋在基列、其牲畜增多、"],[13,5,10,"當掃羅時、與夏甲人戰、仆之、而居其幕、在基列東之全境、○"],[13,5,11,"迦得子孫、居巴珊地、延至撒迦、與流便人相對、"],[13,5,12,"約珥爲族長、沙番次之、又有雅乃、及居巴珊之沙法、"],[13,5,13,"其家昆弟七人、乃米迦勒、米書蘭、示巴、約賴、雅干、細亞、希伯、"],[13,5,14,"此皆亞比孩子、亞比孩乃戶利子、戶利乃耶羅亞子、耶羅亞乃基列子、基列乃米迦勒子、米迦勒乃耶示篩子、耶示篩乃耶哈多子、耶哈多乃布斯子、"],[13,5,15,"又有古尼孫、押比疊子亞希爲族長、"],[13,5,16,"咸居基列、與巴珊及其鄉里、並沙崙郊野、至於邊境、"],[13,5,17,"當猶大王約坦、以色列王耶羅波安時、俱載入譜系、○"],[13,5,18,"流便人、迦得人、及瑪拿西半支派、能出征之武士、執干持刃、挽弓發矢、而善戰者、計四萬四千七百六十人、"],[13,5,19,"與夏甲人、伊突人、拿非施人、挪答人戰、"],[13,5,20,"戰時、呼籲上帝、上帝因其恃己、允其所祈而助之、以夏甲人及從之者、悉付其手、"],[13,5,21,"虜敵之牲畜、駝五萬、綿羊二十五萬、驢二千、人十萬、"],[13,5,22,"敵之被殺而仆者甚衆、蓋此戰由於上帝、遂據居其地、至被虜之時、○"],[13,5,23,"瑪拿西半支派居於斯土、自巴珊延至巴力黑門、及示尼珥與黑門山、"],[13,5,24,"其族長乃以弗、以示、以列、亞斯列、耶利米、何達威雅、雅疊、皆英武有名之族長、○"],[13,5,25,"斯民干犯其列祖之上帝、狥欲從斯土居民之神、卽上帝於其前、所滅諸族之神、"],[13,5,26,"以色列之上帝聳動亞述二王、普勒與提革拉毘尼色之心、遂虜流便人、迦得人、及瑪拿西半支派、至哈臘、哈博、哈拉、及歌散河濱、迄於今日、"],[13,6,1,"利未子、革順、哥轄、米拉利、"],[13,6,2,"哥轄子、暗蘭、以斯哈、希伯倫、烏薛、"],[13,6,3,"暗蘭子、亞倫、摩西、及米利暗、亞倫子、拿答、亞比戶、以利亞撒、以他瑪、"],[13,6,4,"以利亞撒生非尼哈、非尼哈生亞比書、"],[13,6,5,"亞比書生布基、布基生烏西、"],[13,6,6,"烏西生西拉希雅、西拉希雅生米拉約、"],[13,6,7,"米拉約生亞瑪利雅、亞瑪利雅生亞希突、"],[13,6,8,"亞希突生撒督、撒督生亞希瑪斯、"],[13,6,9,"亞希瑪斯生亞撒利雅、亞撒利雅生約哈難、"],[13,6,10,"約哈難生亞撒利雅、亞撒利雅任祭司職、於所羅門在耶路撒冷所建之室、"],[13,6,11,"亞撒利雅生亞瑪利雅、亞瑪利雅生亞希突、"],[13,6,12,"亞希突生撒督、撒督生沙龍、"],[13,6,13,"沙龍生希勒家、希勒家生亞撒利雅、"],[13,6,14,"亞撒利雅生西萊亞、西萊亞生約薩答、"],[13,6,15,"耶和華藉尼布甲尼撒手、徙猶大及耶路撒冷人時、約薩答亦往焉、○"],[13,6,16,"利未子革順、哥轄、米拉利、"],[13,6,17,"革順子、立尼、示每、"],[13,6,18,"哥轄子、暗蘭、以斯哈、希伯倫、烏薛、"],[13,6,19,"米拉利子、抹利、母示、此利未之室家、循其宗族、"],[13,6,20,"革順子立尼、立尼子雅哈、雅哈子薪瑪、"],[13,6,21,"薪瑪子約亞、約亞子易多、易多子謝拉、謝拉子耶特賴、"],[13,6,22,"哥轄子亞米拿達、亞米拿達子可拉、可拉子亞惜、"],[13,6,23,"亞惜子以利加拿、以利加拿子以比雅撒、以比雅撒子亞惜、"],[13,6,24,"亞惜子他哈、他哈子烏列、烏列子烏西雅、烏西雅子少羅、"],[13,6,25,"以利加拿子、亞瑪賽、亞希摩、"],[13,6,26,"亞希摩子以利加拿、以利加拿子瑣菲、瑣菲子拿哈、"],[13,6,27,"拿哈子以利押、以利押子耶羅罕、耶羅罕子以利加拿、"],[13,6,28,"撒母耳長子約珥、次子亞比亞、"],[13,6,29,"米拉利子抹利、抹利子立尼、立尼子示每、示每子烏撒、"],[13,6,30,"烏撒子示米亞、示米亞子哈基雅、哈基雅子亞帥雅、○"],[13,6,31,"約匱安設之後、大衞立人、以理謳歌之事、在耶和華室、"],[13,6,32,"遂以謳歌、供事於會幕前、迨所羅門建耶和華室於耶路撒冷、循其班次、以供厥職、"],[13,6,33,"侍立供職者、及其子孫如左、哥轄之裔、歌者希幔、希幔乃約珥子、約珥乃撒母耳子、"],[13,6,34,"撒母耳乃以利加拿子、以利加拿乃耶羅罕子、耶羅罕乃以列子、以列乃陀亞子、"],[13,6,35,"陀亞乃蘇弗子、蘇弗乃以利加拿子、以利加拿乃瑪哈子、瑪哈乃亞瑪賽子、"],[13,6,36,"亞瑪賽乃以利加拿子、以利加拿乃約珥子、約珥乃亞撒利雅子、亞撒利雅乃西番雅子、"],[13,6,37,"西番雅乃他哈子、他哈乃亞惜子、亞惜乃以比雅撒子、以比雅撒乃可拉子、"],[13,6,38,"可拉乃以斯哈子、以斯哈乃哥轄子、哥轄乃利未子、利未乃以色列子、"],[13,6,39,"希幔之昆弟亞薩、侍立其右、亞薩乃比利家子、比利家乃示米亞子、"],[13,6,40,"示米亞乃米迦勒子、米家勒乃巴西雅子、巴西雅乃瑪基雅子、"],[13,6,41,"瑪基雅乃伊特尼子、伊特尼乃謝拉子、謝拉乃亞大雅子、"],[13,6,42,"亞大雅乃以探子、以探乃薪瑪子、薪瑪乃示每子、"],[13,6,43,"示每乃雅哈子、雅哈乃革順子、革順乃利未子、"],[13,6,44,"其昆弟米拉利之裔、侍立其左者爲以探、以探乃基示子、基示乃亞伯底子、亞伯底乃瑪鹿子、"],[13,6,45,"瑪鹿乃哈沙比雅子、哈沙比雅乃亞瑪謝子、亞瑪謝乃希勒家子、"],[13,6,46,"希勒家乃暗西子、暗西乃巴尼子、巴尼乃沙麥子、"],[13,6,47,"沙麥乃末力子、末力乃母示子、母示乃米拉利子、米拉利乃利未子、"],[13,6,48,"其昆弟利未人、乃供諸役於上帝室、○"],[13,6,49,"惟亞倫及其子孫、獻祭於燔祭壇及香壇、又供諸役於至聖所、爲以色列人贖罪、循上帝僕摩西所命、"],[13,6,50,"亞倫子以利亞撒、以利亞撒子非尼哈、非尼哈子亞比書、"],[13,6,51,"亞比書子布基、布基子烏西、烏西子西拉希雅、"],[13,6,52,"西拉希雅子米拉約、米拉約子亞瑪利雅、亞瑪利雅子亞希突、"],[13,6,53,"亞希突子撒督、撒督子亞希瑪斯、○"],[13,6,54,"亞倫子孫所居之處、依其境內之營壘列左、哥轄族首籤掣而得地、"],[13,6,55,"在猶大地、給以希伯崙及其四郊、"],[13,6,56,"惟其田及鄉里、給予耶孚尼子迦勒、"],[13,6,57,"亦以逃城希伯崙、給亞倫子孫、並給立拿及其郊、雅提珥、以實提莫及其郊、"],[13,6,58,"希崙及其郊、底壁及其郊、"],[13,6,59,"亞珊及其郊、伯示麥及其郊、"],[13,6,60,"又由便雅憫支派中、給以迦巴及其郊、阿勒篾及其郊、亞拿突及其郊、其室家所得、共十三邑、"],[13,6,61,"哥轄其餘之裔、掣籤得十邑、在瑪拿西半支派中、"],[13,6,62,"革順之裔、依其室家、由以薩迦支派、亞設支派、拿弗他利支派、及居巴珊之瑪拿西支派中、得十三邑、"],[13,6,63,"米拉利裔、依其室家、由流便支派、迦得支派、西布倫支派中、掣籤得十二邑、"],[13,6,64,"以色列族以此諸邑及其郊、給利未人、"],[13,6,65,"以上所錄之邑、由猶大支派、西緬支派、便雅憫支派中、掣籤給之、"],[13,6,66,"哥轄裔有數家、由以法蓮支派中得邑、"],[13,6,67,"給以以法蓮山地之逃城示劍及其郊、並給基色及其郊、"],[13,6,68,"約緬及其郊、伯和崙及其郊、"],[13,6,69,"亞雅倫及其郊、迦特臨門及其郊、"],[13,6,70,"哥轄其餘之裔、由瑪拿西半支派中、給以亞乃及其郊、比連及其郊、"],[13,6,71,"革順之裔、由瑪拿西半支派中、給以巴珊之哥蘭及其郊、亞斯他錄及其郊、"],[13,6,72,"又由以薩迦支派中、給以基低斯及其郊、大比拉及其郊、"],[13,6,73,"拉末及其郊、亞年及其郊、"],[13,6,74,"又由亞設支派中、給以瑪沙及其郊、押頓及其郊、"],[13,6,75,"戶割及其郊、利合及其郊、"],[13,6,76,"又由拿弗他利支派中、給以加利利之基低斯及其郊、哈們及其郊、基列亭及其郊、"],[13,6,77,"米拉利其餘之裔、由西布倫支派中、給以臨摩挪及其郊、他泊及其郊、"],[13,6,78,"又在約但外、耶利哥東、由流便支派中、給以曠野之比悉及其郊、雅哈撒及其郊、"],[13,6,79,"基底莫及其郊、米法押及其郊、"],[13,6,80,"又由迦得支派中、給以基列之拉末及其郊、瑪哈念及其郊、"],[13,6,81,"希實本及其郊、雅謝及其郊、"],[13,7,1,"以薩迦子、陀拉、普亞、雅述、伸崙四人、"],[13,7,2,"陀拉子、烏西、利法雅、耶勒、雅買、易伯散、示母利、俱爲陀拉室家之長、當世英武之士、於大衞時、其數二萬二千六百人、"],[13,7,3,"烏西子伊斯拉希、伊斯拉希子米迦勒、俄巴底亞、約珥、伊示雅、父子五人、俱爲族長、"],[13,7,4,"與之偕者、按其譜系室家、能出戰之軍旅、計三萬六千人、蓋其妻子衆多也、"],[13,7,5,"其昆弟在以薩迦室家、皆爲英武之士、循其譜系、計八萬七千人、○"],[13,7,6,"便雅憫子、比拉、比結、耶疊三人、"],[13,7,7,"比拉子、以斯本、烏西、烏薛、耶利摩、以利五人、俱爲族長、英武之士、循其譜系、計二萬二千有三十四人、"],[13,7,8,"比結子、細米拉、約阿施、以利以謝、以利約乃、暗利、耶利摩、亞比雅、亞拿突、亞拉篾、皆比結之子、"],[13,7,9,"俱爲族長、英武之士、循其譜系、計二萬有二百人、"],[13,7,10,"耶疊子比勒罕、比勒罕子耶烏施、便雅憫、以忽、基拿拿、細坦、他施、亞希沙哈、"],[13,7,11,"皆耶疊之裔、俱爲族長、英武之士、能出戰之軍旅、計一萬七千二百人、"],[13,7,12,"以珥子書品、戶品、亞黑子戶伸、"],[13,7,13,"拿弗他利子、雅薛、沽尼、耶色、沙龍、皆辟拉之子、○"],[13,7,14,"瑪拿西子亞斯列、乃其妾亞蘭女所生、又生基列之父瑪吉、"],[13,7,15,"瑪吉之妻、乃戶品書品之妹、名瑪迦、次子名西羅非哈、西羅非哈僅有女、"],[13,7,16,"瑪吉妻瑪迦生子、命名毘利施、其弟名示利施、示利施子烏蘭、利金、"],[13,7,17,"烏蘭子比但、皆瑪拿西孫、瑪吉子基列之裔、"],[13,7,18,"其妹哈摩利吉生伊施荷、亞比以謝、瑪拉、"],[13,7,19,"示米大子、亞現、示劍、利克希、阿尼安、○"],[13,7,20,"以法蓮子書提拉、書提拉子比列、比列子他哈、他哈子以拉大、以拉大子他哈、"],[13,7,21,"他哈子撒拔、撒拔子書提拉、以法蓮又生以謝、以列、俱爲迦特土人所殺、因往奪其牲畜也、"],[13,7,22,"其父以法蓮爲之哀悼多日、兄弟咸來唁之、"],[13,7,23,"後以法蓮與妻同室、懷妊生子、緣其家遭禍、名子曰比利亞、"],[13,7,24,"其女舍伊拉、乃建上下伯和崙、及烏羨舍伊拉、"],[13,7,25,"比利阿子利法、利悉、利悉子他拉、他拉子他罕、"],[13,7,26,"他罕子拉但、拉但子亞米忽、亞米忽子以利沙瑪、"],[13,7,27,"以利沙瑪子嫩、嫩之子約書亞、"],[13,7,28,"其業及所居之處、乃伯特利及其鄉里、東有拿蘭、西有基色及其鄉里、示劍及其鄉里、延至迦薩及其鄉里、"],[13,7,29,"又有近瑪拿西境、伯善及其鄉里、他納及其鄉里、米吉多及其鄉里、多珥及其鄉里、以色列子約瑟之裔、居此諸邑、○"],[13,7,30,"亞設子、音拿、亦施瓦、亦施韋、比利亞、西拉爲女弟、"],[13,7,31,"比利亞子、希別、瑪結、瑪結爲比撒威之父、"],[13,7,32,"希別生雅弗勒、朔默、何坦、書雅爲女弟、"],[13,7,33,"雅弗列子、巴薩、賓哈、亞施法、皆雅弗列之子、"],[13,7,34,"朔默子、亞希、羅迦、耶戶巴、亞蘭、"],[13,7,35,"朔默弟希連子、瑣法、音那、示利斯、亞抹、"],[13,7,36,"瑣法子、書亞、哈尼弗、書阿勒、比利、音拉、"],[13,7,37,"比悉、河得、珊瑪、施沙、益蘭、比拉、"],[13,7,38,"益帖子、耶孚尼、毘斯巴、亞拉、"],[13,7,39,"烏拉子、亞拉、漢尼業、利寫、"],[13,7,40,"此皆亞設子孫、俱爲族長、卓犖英武之士、牧伯之首、循其譜系、能出戰者、計二萬六千人、"],[13,8,1,"便雅憫生長子比拉、次子亞實別、三子亞哈拉、"],[13,8,2,"四子挪哈、五子拉法、"],[13,8,3,"比拉子亞大、基拉、亞比忽、"],[13,8,4,"亞比書、乃幔、亞何亞、"],[13,8,5,"基拉、示孚汛、戶蘭、"],[13,8,6,"以忽子爲迦巴居民族長、被虜至瑪拿轄、"],[13,8,7,"以忽子乃幔、亞希亞、基拉、亦皆被虜、基拉生烏撒、亞希忽、"],[13,8,8,"沙哈連出其二妻戶伸巴拉之後、在摩押地生子、"],[13,8,9,"乃由其妻賀得生約巴、洗比雅、米沙、瑪拉干、"],[13,8,10,"耶烏斯、沙迦、米瑪、此皆其子、俱爲族長、"],[13,8,11,"又由戶伸生亞比突、以利巴力、"],[13,8,12,"以利巴力子、希伯、米珊、沙麥、沙麥建阿挪與羅德、及其鄉里、"],[13,8,13,"又生比利亞與示瑪、爲亞雅崙居民族長、逐迦特居民者、卽斯人也、"],[13,8,14,"亞希約、沙煞、耶利末、"],[13,8,15,"西巴第雅、亞拉得、亞得、"],[13,8,16,"米迦勒、伊施巴、約哈、皆比利亞之子、"],[13,8,17,"西巴第雅、米書蘭、希西基、希伯、"],[13,8,18,"伊施米萊、伊斯利亞、約巴、皆以利巴力之子、"],[13,8,19,"雅金、細基利、撒底、"],[13,8,20,"以利乃、洗勒太、以列、"],[13,8,21,"亞大雅、比拉雅、申拉、皆示每之子、"],[13,8,22,"伊施班、希伯、以列、"],[13,8,23,"亞伯頓、細基利、哈難、"],[13,8,24,"哈拿尼雅、以攔、安陀提雅、"],[13,8,25,"伊弗底雅、毘努伊勒、皆沙煞之子、"],[13,8,26,"珊示萊、示哈利、亞他利雅、"],[13,8,27,"雅利西、以利亞、細基利、皆耶羅罕之子、"],[13,8,28,"俱爲族長之卓越者、循其世系、咸居耶路撒冷、"],[13,8,29,"基遍之父耶利、居於基遍、其妻名瑪迦、"],[13,8,30,"生長子亞伯頓、及蘇珥、基士、巴力、拿答、"],[13,8,31,"基多、亞希約、撒迦、米基羅、"],[13,8,32,"米基羅生示米暗、此諸人亦居耶路撒冷、與其昆弟相對、"],[13,8,33,"尼珥生基士、基士生掃羅、掃羅生約拿單、麥基舒亞、亞比拿達、伊施巴力、"],[13,8,34,"約拿單子米力巴力、米力巴力生米迦、"],[13,8,35,"米迦子毘敦、米勒、他利亞、亞哈斯、"],[13,8,36,"亞哈斯生耶何阿達、耶何阿達生亞拉篾、亞斯瑪威、心利、心利生摩撒、"],[13,8,37,"摩撒生比尼亞、比尼亞子拉法、拉法子以利亞薩、以利亞薩子亞悉、"],[13,8,38,"亞悉有六子、名亞斯利干、波基路、以實瑪利、示亞利雅、俄巴底雅、哈難、皆亞悉之子、"],[13,8,39,"其弟以設、長子烏蘭、次子耶烏施、三子以利法列、"],[13,8,40,"烏蘭子爲射者、皆英武之士、子孫衆多、共五百十人、俱屬便雅憫裔、"],[13,9,1,"以色列族、循其譜系核之、載於以色列列王紀、猶大因干罪戾、被虜至巴比倫、"],[13,9,2,"先返居其邑中之業者、卽以色列族、與祭司利未人、及尼提甯人、"],[13,9,3,"居耶路撒冷者、有猶大人、便雅憫人、以法蓮人、瑪拿西人、"],[13,9,4,"猶大子法勒斯裔、巴尼玄孫、音利曾孫、暗利孫、亞米忽子烏太、"],[13,9,5,"示羅裔、長子亞帥雅及其衆子、"],[13,9,6,"謝拉裔、耶烏利及其昆弟、共六百九十人、"],[13,9,7,"便雅憫裔、哈西努曾孫、何達威雅孫、米書蘭子撒路、"],[13,9,8,"耶羅罕子伊比尼雅、米基立孫、烏西子以拉、伊比尼雅曾孫、流珥孫、示法提雅子米書蘭、"],[13,9,9,"及其昆弟、循其世系、共九百五十六人、俱爲族長、○"],[13,9,10,"祭司中有耶大雅、耶何雅立、雅斤、"],[13,9,11,"司上帝室者、希勒家子亞薩利雅、希勒家乃米書蘭子、米書蘭乃撒督子、撒督乃米拉約子、米拉約乃亞希突子、"],[13,9,12,"又有瑪基雅曾孫、巴施戶珥孫、耶羅罕子亞大雅、及亞第業子瑪賽、亞第業乃雅希細拉子、雅希細拉乃米書蘭子、米書蘭乃米實利密子、米實利密乃音麥子、"],[13,9,13,"及其昆弟、一千七百六十人、皆爲族長、最能供上帝室之役、○"],[13,9,14,"利未人米拉利裔、哈沙比雅曾孫、亞利甘孫、哈述子示瑪雅、"],[13,9,15,"又有拔巴甲、黑勒施、迦拉、及亞薩曾孫、細基利孫、米迦子瑪探雅、"],[13,9,16,"耶杜頓曾孫、迦拉孫、示瑪雅子俄巴底、及以利加拿孫、亞撒子比利家、皆居尼陀法人之鄉里、○"],[13,9,17,"司閽者乃沙龍、亞谷、達們、亞希幔、及其昆弟、沙龍爲長、"],[13,9,18,"斯衆昔守王之東門、今在利未營中爲閽、"],[13,9,19,"可拉曾孫、以比雅撒孫、可利子沙龍、及其昆弟可拉裔、司供役之事、守會幕之門、其祖曾理耶和華之營、且守其門、"],[13,9,20,"昔以利亞撒子非尼哈統轄斯衆、耶和華偕之、"],[13,9,21,"米施利米雅子撒迦利雅、爲會幕之閽人、"],[13,9,22,"被簡爲閽者、共二百十二人、在其鄉里、循其譜系核之、乃大衞與先見撒母耳所立、任此要職、"],[13,9,23,"彼與子孫循其班次、守耶和華室會幕之門、"],[13,9,24,"東西南北四方、皆有閽人、"],[13,9,25,"其昆弟居鄉里者、每七日入而與俱、"],[13,9,26,"閽長四人、皆利未族、任其要職、守上帝室之倉庫、"],[13,9,27,"旣任此職、每晨啟門、環上帝室而居、"],[13,9,28,"其中有守供事之器者、器之出入、皆核其數、"],[13,9,29,"亦有理器具、與聖所什物、及細麪酒油、乳香芳品、"],[13,9,30,"祭司中有以芳品製膏者、"],[13,9,31,"利未人可拉族、沙龍長子瑪他提雅、職司盤炙之物、"],[13,9,32,"其昆弟哥轄裔中、有理陳設之餅者、每安息日備之、"],[13,9,33,"謳歌者、有利未族長、居於倉舍、晝夜供役、無他職任、"],[13,9,34,"此乃利未族長之卓越者、循其世系、咸居耶路撒冷、○"],[13,9,35,"基遍之父耶利、居於基遍、其妻名瑪迦、"],[13,9,36,"生長子亞伯頓、及蘇珥、基士、巴力、尼珥、拿答、"],[13,9,37,"基多、亞希約、撒迦利雅、米基羅、"],[13,9,38,"米基羅生示米暗、此諸人亦居耶路撒冷、與其昆弟相對、"],[13,9,39,"尼珥生基士、基士生掃羅、掃羅生約拿單、麥基舒亞、亞比拿達、伊施巴力、"],[13,9,40,"約拿單子米力巴力、米力巴力生米迦、"],[13,9,41,"米迦子毘敦、米勒、他利亞、亞哈斯、"],[13,9,42,"亞哈斯生雅拉、雅拉生亞拉篾、亞斯瑪威、心利、心利生摩撒、"],[13,9,43,"摩撒生比尼亞、比尼亞生利法雅、利法雅生以利亞薩、以利亞薩生亞悉、"],[13,9,44,"亞悉有六子、名亞斯利干、波基路、以實瑪利、示亞利雅、俄巴底雅、哈難、皆亞悉之子、"],[13,10,1,"非利士人與以色列人戰、以色列人遁、在基利波山、見殺而仆、"],[13,10,2,"非利士人急追掃羅及其子、殺其三子、約拿單、亞比拿達、麥基舒亞、"],[13,10,3,"掃羅被攻、戰勢劇烈、射者追及之、窘急特甚、"],[13,10,4,"謂執兵者曰、爾其拔劍刺我、免未受割者至而侮我、執兵者懼甚、不敢奉命、掃羅遂伏劍而死、"],[13,10,5,"執兵者見掃羅死、亦伏劍而死、"],[13,10,6,"於是掃羅與其三子、全家偕亡、"],[13,10,7,"居谷中之以色列衆、見民遁、掃羅與子皆死、遂棄邑而逃、非利士人至而居之、○"],[13,10,8,"翌日、非利士人來剝尸、見掃羅與其子仆於基利波山、"],[13,10,9,"乃剝掃羅尸、斬其首、取其鎧甲、遣使至非利士四境、傳於偶像及庶民、"],[13,10,10,"置其鎧甲於彼之神廟、釘其首於大袞廟、"],[13,10,11,"基列雅比人聞非利士人待掃羅之事、"],[13,10,12,"壯士咸起、取掃羅及其子之屍、攜至雅比、葬其骨於雅比之橡下、禁食七日、"],[13,10,13,"夫掃羅之死、因其干犯耶和華、不遵其命、且請示於憑鬼者、"],[13,10,14,"而不諮諏耶和華、故耶和華殺之、以其國歸於耶西子大衞、"],[13,11,1,"以色列衆集於希伯崙、見大衞曰、我爲爾之骨肉、"],[13,11,2,"昔掃羅爲王時、爾率以色列人出入、爾上帝耶和華謂爾曰、爾必爲我民之牧、我民以色列之君、"],[13,11,3,"以色列長老、咸至希伯崙見王、大衞在希伯崙、於耶和華前、與之立約、遂膏大衞、爲以色列王、循耶和華藉撒母耳所言、"],[13,11,4,"大衞與以色列衆至耶路撒冷、卽耶布斯、時、耶布斯土人居彼、"],[13,11,5,"耶布斯人謂大衞曰、爾必不得入此、然大衞取錫安之保障、卽大衞城、"],[13,11,6,"大衞曰、先攻耶布斯人者、必爲首爲長、洗魯雅子約押先上、遂爲首、"],[13,11,7,"大衞居其保障、故稱曰大衞城、"],[13,11,8,"大衞自米羅起、四周築城、其餘乃約押修葺、"],[13,11,9,"大衞日漸昌大、萬軍之耶和華偕之也、○"],[13,11,10,"從大衞之勇士、爲首者有力於其國、與以色列衆立之爲王、循耶和華諭以色列之命、"],[13,11,11,"其人如左、哈革摩尼人雅朔班、爲諸將之首、一時揮戈擊斃三百人、"],[13,11,12,"其次爲亞合人、朵多子以利亞撒、爲三勇士之一、"],[13,11,13,"彼與大衞在巴斯達閔、非利士人咸集以戰、在彼有田、滿種麰麥、民遁於非利士人前、"],[13,11,14,"彼立於田間、以護其地、殺非利士人、耶和華拯之、使獲大勝、"],[13,11,15,"三十首領中、有三人下至山巖、入亞杜蘭穴、以覲大衞、非利士軍建營於利乏音谷、"],[13,11,16,"時、大衞在保障、非利士汛在伯利恆、"],[13,11,17,"大衞歆羨曰、深願有人由伯利恆門側之井、汲水以飲我、"],[13,11,18,"三人衝過非利士軍、由伯利恆門側之井汲水、攜詣大衞、大衞不飲、乃灌之於耶和華前、"],[13,11,19,"曰、願我上帝禁我行此、我豈飲冒死者之血乎、蓋彼舍命取之、故不飲、三勇士所爲若此、"],[13,11,20,"其中約押弟雅比篩爲首、嘗揮戈擊斃三百人、遂在三人中得名譽、"],[13,11,21,"彼在三人中爲尊、故爲其魁、惟不得與首三人同列、"],[13,11,22,"又有甲薛勇士耶何耶大子比拿雅、大有作爲、殺摩押人亞利伊勒二子、又當雨雪時、下阱擊獅、"],[13,11,23,"又殺埃及偉人、其人身長五肘、其手執戈、大如織器之梁、比拿雅執杖往迎、奪其戈而殺之、"],[13,11,24,"比拿雅所爲如是、遂在三勇士中得名譽、"],[13,11,25,"彼較三十首領爲尊、惟不及前三人、大衞立之爲侍衞長、○"],[13,11,26,"軍中之勇士、卽約押弟亞撒黑、伯利恆人朵多子伊勒哈難、"],[13,11,27,"哈律人沙瑪、比倫人希利斯、"],[13,11,28,"提哥亞人益吉子以拉、亞拿突人亞比以謝、"],[13,11,29,"戶沙人西比該、亞合人以來、"],[13,11,30,"尼陀法人瑪哈萊、尼陀法人巴拿子希立、"],[13,11,31,"便雅憫族、基比亞人利拜子以太、比拉頓人比拿雅、"],[13,11,32,"迦實溪人戶萊、亞拉巴人亞比、"],[13,11,33,"巴路米人押斯瑪弗、沙勒本人以利雅哈巴、"],[13,11,34,"基孫人哈深諸子、哈拉人沙基子約拿單、"],[13,11,35,"哈拉人沙甲子亞希暗、吾珥子以利法勒、"],[13,11,36,"米基拉人希弗、比倫人亞希雅、"],[13,11,37,"迦密人希斯羅、伊斯拜子拿萊、"],[13,11,38,"拿單弟約珥、哈基利子彌伯哈、"],[13,11,39,"亞捫人洗勒、比錄人拿哈萊、爲洗魯雅子約押執兵之士、"],[13,11,40,"以帖人以拉、及迦立、"],[13,11,41,"赫人烏利亞、亞萊子撒拔、"],[13,11,42,"流便人示撒子亞第拿、爲流便族長、與從者三十人、"],[13,11,43,"又有瑪迦子哈難、彌特尼人約沙法、"],[13,11,44,"亞施他拉人烏西亞、亞羅珥人何坦子沙瑪、耶利、"],[13,11,45,"申利子耶疊、與其弟提洗人約哈、"],[13,11,46,"瑪哈未人以利業、伊利拿安子耶利拜、約沙未雅、摩押人伊特瑪、"],[13,11,47,"以利業、俄備得、並米瑣八人雅西業、"],[13,12,1,"大衞避基士子掃羅、匿於洗革拉時、有勇士歸之、助其戰鬬、"],[13,12,2,"皆執弓爲械、發石射矢、左右手俱能之、乃掃羅之昆弟、便雅憫人也、"],[13,12,3,"其魁亞希以謝、次基比亞人示瑪子約阿施、及亞斯瑪威子耶薛、毘力、與比拉迦、亞拿突人耶戶、"],[13,12,4,"基遍人以實買雅、勇冠三十人、爲之長、又有耶利米、雅哈悉、約哈難、基得拉人約撒拔、"],[13,12,5,"伊利烏賽、耶利摩、比亞利雅、示瑪利雅、哈律弗人示法提雅、"],[13,12,6,"可拉族以利加拿、耶西雅、亞薩列、約以謝、押朔班、"],[13,12,7,"基多人耶羅罕子猶拉、西巴第雅、"],[13,12,8,"迦得族亦有人歸大衞、至曠野之保障、俱爲勇士、嫻習戰事、能執干戈、其貌如獅、足捷如山中之鹿、"],[13,12,9,"其魁以薛、次俄巴底雅、三以利押、"],[13,12,10,"四彌施瑪拿、五耶利米、"],[13,12,11,"六亞太、七以利業、"],[13,12,12,"八約哈難、九以利薩巴、"],[13,12,13,"十耶利米、十一末巴奈、"],[13,12,14,"此皆迦得人、俱爲軍長、小者當百人、大者當千人、"],[13,12,15,"正月約但漲溢、斯衆濟河、使居谷中之民逃遁、東西皆然、"],[13,12,16,"有便雅憫人、猶大人、至保障歸大衞、"],[13,12,17,"大衞出迓曰、爾若平和而來以助我、則我心與爾相契、我旣無辜、爾若鬻我於敵、願我列祖之上帝鑒察之、譴責之、"],[13,12,18,"三十首領之魁亞瑪撒、感於神曰、大衞歟、我儕屬爾、耶西子歟、我儕從爾、願爾平康、願助爾者平康、蓋爾上帝助爾也、大衞納之、立爲軍長、"],[13,12,19,"大衞偕非利士人、往戰掃羅時、有瑪拿西人歸之、惟未助非利士人、因非利士牧伯相議、遣之去曰、彼必歸降其主掃羅、危及我首、"],[13,12,20,"大衞往洗革拉時、瑪拿西人押拿、約撒拔、耶疊、米迦勒、約撒拔、以利戶、洗勒太、咸歸之、皆瑪拿西之千夫長也、"],[13,12,21,"斯衆助大衞攻羣寇、皆爲勇士、亦爲軍長、"],[13,12,22,"來助大衞者、日有其人、致成大軍、如上帝之軍、○"],[13,12,23,"備戰之士至希伯崙見大衞、欲以掃羅國位歸之、循耶和華言、其數如左、"],[13,12,24,"猶大族、執干戈而備戰者、六千八百人、"],[13,12,25,"西緬族、備戰之勇士七千一百人、"],[13,12,26,"利未族、四千六百人、"],[13,12,27,"亞倫家長耶何耶大、與從者三千七百人、"],[13,12,28,"少年勇士撒督、及族長二十二人、"],[13,12,29,"便雅憫族、掃羅之昆弟三千人、其族強半仍從掃羅家、"],[13,12,30,"以法蓮族之勇士、族中著名者、二萬有八百人、"],[13,12,31,"瑪拿西半支派、名錄於册、來立大衞爲王者、一萬八千人、"],[13,12,32,"以薩迦族、達於時務、知以色列人所當行者、族長二百、同宗之昆弟、咸聽厥命、"],[13,12,33,"西布倫族、能從軍列陳、執諸戰具、整肅行伍、不生二心者、五萬人、"],[13,12,34,"拿弗他利族、軍長一千、從之執干戈者、三萬七千人、"],[13,12,35,"但之族、能列陳者、二萬八千六百人、"],[13,12,36,"亞設族、能從軍列陳者、四萬人、"],[13,12,37,"約但東、流便族、迦得族、瑪拿西半支派、持諸軍器備戰者、十二萬人、"],[13,12,38,"以上所載、皆係戰士、能列行伍、誠心至希伯崙、欲立大衞爲以色列全族之王、其餘以色列民、亦懷一心、立之爲王、"],[13,12,39,"衆與大衞偕居三日、式飲式食、蓋其昆弟爲之備具也、"],[13,12,40,"附近之人、及以薩迦、西布倫、拿弗他利之人、以驢駝騾牛載餱糧、無花果餅、葡萄乾、與酒油、並攜牛羊甚多而至、因以色列人欣喜故也、"],[13,13,1,"大衞與千夫長、百夫長、諸將會議、"],[13,13,2,"謂以色列會衆曰、爾曹若以爲善、此事由於我上帝耶和華、則可遣人往以色列全地、請我儕其餘之昆弟、及居邑郊之祭司利未人、使之咸集於此、"],[13,13,3,"我儕舁上帝匱而至、蓋掃羅時、我儕未嘗諮諏於匱、"],[13,13,4,"會衆曰、我必如是而行、民衆咸視斯事爲善也、"],[13,13,5,"於是大衞集以色列人、自埃及之西曷溪、至哈馬界、欲自基列耶琳、舁上帝匱至、"],[13,13,6,"大衞率以色列衆至巴拉、卽屬猶大之基列耶琳、欲舁耶和華上帝之匱、此匱乃以居基路伯上、耶和華之名而名者、"],[13,13,7,"遂舁上帝匱、自亞比拿達室而出、載於斯車、烏撒與亞希約御之、"],[13,13,8,"大衞及以色列衆、在上帝前、極力舞蹈、謳歌、以琴瑟鑼鼓與角作樂、"],[13,13,9,"至基頓禾場、牛蹶、烏撒伸手扶匱、"],[13,13,10,"耶和華怒烏撒、因其伸手扶匱而擊之、遂死於上帝前、"],[13,13,11,"耶和華擊烏撒、大衞不悅、稱其地曰毘列斯烏撒、至於今日、"],[13,13,12,"是日大衞畏上帝曰、上帝之匱、何可至我所、"],[13,13,13,"於是大衞不舁匱入大衞城、至於己所、乃轉舁至迦特人俄別以東室、"],[13,13,14,"上帝匱在俄別以東室三月、耶和華錫嘏於俄別以東家、及其所有、"],[13,14,1,"推羅王希蘭遣使見大衞、攜香柏及石工木工而至、爲之建宮室、"],[13,14,2,"大衞乃知耶和華立之爲以色列王、蓋爲其民以色列故、振興其國也、○"],[13,14,3,"大衞在耶路撒冷又娶后妃、誕生子女、"],[13,14,4,"在耶路撒冷所生之子、名沙母亞、朔罷、拿單、所羅門、"],[13,14,5,"益轄、以利書亞、以利法列、"],[13,14,6,"挪迦、尼斐、雅非亞、"],[13,14,7,"以利沙瑪、比利雅大、以利法列、○"],[13,14,8,"非利士人聞大衞受膏、爲以色列全族之王、咸至而索之、大衞聞之、遂往迎焉、"],[13,14,9,"非利士人旣至、侵利乏音谷、"],[13,14,10,"大衞諮諏上帝曰、我往攻非利士人可否、爾付之於我手乎、耶和華曰、往哉、我必付之於爾手、"],[13,14,11,"非利士人至巴力毘拉心、大衞擊之、曰、上帝假我手破敵、如水之衝流然、故名其地曰巴力毘拉心、"],[13,14,12,"敵遺其偶像、大衞宣命、乃以火焚之、"],[13,14,13,"非利士人又侵谷中、"],[13,14,14,"大衞復諮諏上帝、上帝曰、勿往迎之、宜遶其後、於桑林相對之所攻之、"],[13,14,15,"聞桑杪有步履之聲、則出戰、蓋上帝先爾而行、擊非利士軍旅、"],[13,14,16,"大衞遵上帝命、擊非利士軍旅、自基遍至基色、"],[13,14,17,"大衞之聲名、遂洋溢於列國、耶和華使列國咸畏之、"],[13,15,1,"大衞於大衞城建宮室、又爲上帝匱備所張幕、"],[13,15,2,"大衞曰、耶和華旣簡利未人舁上帝匱、永久奉事之、他人不可舁也、"],[13,15,3,"大衞集以色列衆於耶路撒冷、以舁耶和華匱、至其所備之所、"],[13,15,4,"又集亞倫裔、及利未人、"],[13,15,5,"哥轄裔、族長烏列、與其昆弟百二十人、"],[13,15,6,"米拉利裔、族長亞帥雅、與其昆弟二百二十人、"],[13,15,7,"革順裔、族長約珥、與其昆弟百三十人、"],[13,15,8,"以利撒反裔、族長示瑪雅、與其昆弟二百人、"],[13,15,9,"希伯倫裔、族長以列、與其昆弟八十人、"],[13,15,10,"烏薛裔、族長亞米拿達、與其昆弟百十二人、"],[13,15,11,"大衞召祭司撒督、亞比亞他、與利未人烏列、亞帥雅、約珥、示瑪雅、以列、亞米拿達、"],[13,15,12,"諭之曰、爾曹爲利未族長、當與昆弟自潔、致可舁以色列上帝耶和華之匱、至我所備之所、"],[13,15,13,"爾曹初未舁之、亦未循例尋求上帝、故我上帝耶和華擊我儕、"],[13,15,14,"祭司利未人遂自潔、欲舁以色列上帝耶和華之匱而上、"],[13,15,15,"利未子孫、以杠肩舁上帝匱、循摩西遵耶和華言所命、"],[13,15,16,"大衞告利未族長、立其昆弟謳歌者、以樂器琴瑟與鈸、欣然大發其音、而揚厥聲、"],[13,15,17,"利未人遂立約珥子希幔、與其昆弟比利家子亞薩、及其同宗米拉利裔、古沙雅子以探、"],[13,15,18,"其次、昆弟撒迦利雅、便、雅薛、示米拉末、耶歇、烏尼、以利押、比拿雅、瑪西雅、瑪他提雅、以利斐利戶、彌克尼雅、閽人俄別以東、耶利、"],[13,15,19,"如是立謳歌者希幔、亞薩、以探、擊銅鈸大發其聲、"],[13,15,20,"撒迦利雅、雅薛、示米拉末、耶歇、烏尼、以利押、瑪西雅、比拿雅鼓瑟、其聲清以細、"],[13,15,21,"瑪他提雅、以利斐利戶、彌克尼雅、俄別以東、耶利、亞撒西雅鳴琴、其聲洪而緩、爲始作者、"],[13,15,22,"利未族長基拿尼雅、爲謳歌之長、訓謳歌之人、以其擅此技也、"],[13,15,23,"比利家以利加拿爲閽、以守匱、"],[13,15,24,"祭司示巴尼、約沙法、拿坦業、亞瑪賽、撒迦利雅、比拿亞、以利以謝、在上帝匱前吹角、俄別以東耶希亞爲閽、以守匱、"],[13,15,25,"於是大衞與以色列長老、及千夫長、歡然往舁耶和華之約匱、自俄別以東家而上、"],[13,15,26,"因上帝助舁耶和華約匱之利未人、則獻牡犢七、牡羊七爲祭、"],[13,15,27,"大衞與舁匱之利未人、及謳歌長基拿尼雅、曁衆謳歌者、皆衣細枲長服、大衞又衣枲聖衣、"],[13,15,28,"以色列衆歡呼、吹角吹箛、擊鈸鼓瑟、鳴琴奏樂、舁耶和華約匱而上、"],[13,15,29,"耶和華約匱入大衞城時、掃羅女米甲自牖而窺、見大衞王踴躍舞蹈、中心鄙夷之、"],[13,16,1,"衆舁上帝匱入城、置於大衞所張之幕、獻燔祭及酬恩祭於上帝前、"],[13,16,2,"大衞獻燔祭與酬恩祭旣畢、奉耶和華名、爲民祝嘏、"],[13,16,3,"頒賜以色列衆、無論男女、各予餅一方、肉一臠、葡萄乾餅一方、○"],[13,16,4,"又立利未人、供役於耶和華匱前、讚美稱謝、頌揚以色列之上帝耶和華、"],[13,16,5,"首亞薩、次撒迦利雅、及雅薛、示米拉末、耶歇、瑪他提雅、以利押、比拿雅、俄別以東、耶利鼓瑟鳴琴、亞薩擊鈸發聲、"],[13,16,6,"祭司比拿雅、雅哈悉、恆吹角於上帝約匱前、"],[13,16,7,"是日大衞始定、藉亞薩與其昆弟、稱謝耶和華、"],[13,16,8,"歌曰、當稱謝耶和華、呼籲其名、以其作爲、普告萬民兮、"],[13,16,9,"謳歌之、頌美之、道其奇行兮、"],[13,16,10,"以其聖名爲榮、凡求耶和華者、其心歡悅兮、"],[13,16,11,"求耶和華、與其能力、恆尋其面兮、"],[13,16,12,"其僕以色列之裔、卽其所選雅各子孫歟、念其所行奇事異蹟、及其口之讞兮、"],[13,16,13,"其僕以色列之裔、卽其所選雅各子孫歟、念其所行奇事異蹟、及其口之讞兮、"],[13,16,14,"彼乃耶和華、我之上帝、行鞫於全地兮、"],[13,16,15,"當永念其約、所諭萬世之言、"],[13,16,16,"卽與亞伯拉罕所立之約、對以撒所發之誓、"],[13,16,17,"且於雅各爲定例、於以色列爲永約兮、"],[13,16,18,"曰、我必賜爾以迦南地、爲爾所得之業兮、"],[13,16,19,"昔爾人寡、其數無幾、旅於斯土兮、"],[13,16,20,"由此族游於彼族、自此國至於彼國、"],[13,16,21,"上帝不容人虐遇之、因之譴責列王兮、"],[13,16,22,"曰、我受膏者勿犯之、我之先知勿傷之、"],[13,16,23,"全地當歌頌耶和華、日宣其拯救兮、"],[13,16,24,"述其尊榮於列邦、道其奇行於萬民兮、"],[13,16,25,"蓋耶和華爲大、極當頌讚、宜寅畏之、超越諸神兮、"],[13,16,26,"列邦之神、悉屬虛無、惟耶和華創造諸天兮、"],[13,16,27,"尊榮威嚴在於其前、能力懽愉在於其所兮、"],[13,16,28,"萬民諸族歟、當以尊榮能力、歸於耶和華、歸於耶和華兮、"],[13,16,29,"以耶和華名應得之榮歸之、奉獻禮物、至於其前、衣聖服而崇拜之兮、"],[13,16,30,"全地當戰慄於其前、世界堅定、不至動搖兮、"],[13,16,31,"諸天其歡、大地其喜、當宣告列邦曰、耶和華爲王兮、"],[13,16,32,"海及充其中者、當漰渤兮、田與其中所有、當歡欣兮、"],[13,16,33,"林間諸木、必在耶和華前歡呼、因其將臨、行鞫於地兮、"],[13,16,34,"當稱謝耶和華、以其爲善、慈惠永存兮、"],[13,16,35,"當曰救我之上帝歟、尚其救援我、會集我、拯我於列邦、俾我稱頌爾聖名、以讚美爾而獲勝、"],[13,16,36,"以色列之上帝耶和華、當頌美之、自亙古以迄永久兮、衆民咸曰、阿們、乃頌美耶和華、○"],[13,16,37,"大衞留亞薩與其昆弟、恆供事於耶和華約匱前、循每日所宜、"],[13,16,38,"俄別以東與其昆弟六十八人、及耶杜頓子俄別以東、並何薩爲閽人、"],[13,16,39,"祭司撒督、與其昆弟爲祭司者、咸居基遍之崇邱、在耶和華幕前、"],[13,16,40,"恆在燔祭壇、獻燔祭於耶和華、朝夕無間、循耶和華法律所載、命以色列人者、"],[13,16,41,"偕之者、又有希幔、耶杜頓、及其餘被簡、名錄於册者、稱謝耶和華、以其慈惠永存也、"],[13,16,42,"希幔耶杜頓、偕之吹角擊鈸、大發其聲、且以樂器和頌上帝之歌、耶杜頓子孫爲閽人、"],[13,16,43,"於是民衆各歸其家、大衞亦返、爲眷聚祝嘏、"],[13,17,1,"大衞居宮室時、謂先知拿單曰、我居香柏之室、而耶和華約匱乃在帳中、"],[13,17,2,"拿單曰、爾其從心所欲而行、蓋上帝偕爾、"],[13,17,3,"是夜上帝諭拿單曰、"],[13,17,4,"往告我僕大衞曰、耶和華云、爾勿建室、爲我居所、"],[13,17,5,"我自導以色列人出埃及、至於今日、未嘗居室、乃處帷幕、由此遷彼、"],[13,17,6,"凡我與以色列人偕行之地、豈曾語牧我民以色列之士師曰、曷不爲我建香柏之室乎、"],[13,17,7,"故當謂我僕大衞曰、萬軍之耶和華云、我自羊牢中、羊羣後、取爾爲我民以色列之君、"],[13,17,8,"爾之所往、我皆與偕、絕爾諸敵、將錫爾大名、如世間大人之名、"],[13,17,9,"我欲爲我民以色列定一區域、而栽植之、使居己所、不復遷移、不復遭惡類之敗壞、有如疇昔、"],[13,17,10,"及我命士師治我民以色列時、我必服爾諸敵、且我告爾、耶和華必爲爾建立家室、"],[13,17,11,"迨爾之日已盈、歸爾列祖、我必立爾後裔、卽爾子以嗣爾、鞏固其國、"],[13,17,12,"彼將爲我建室、我必固其國位、歷久弗替、"],[13,17,13,"我將爲其父、彼將爲我子、不使我之慈惠離之、如離乎先爾者、"],[13,17,14,"我必永立之於我家我國、鞏固其位、歷久弗替、"],[13,17,15,"拿單循此諸言、依此啟示、告大衞、○"],[13,17,16,"大衞王入坐於耶和華前、曰、耶和華上帝歟、我何人斯、我家若何、爾乃導我至此乎、"],[13,17,17,"上帝歟、此於爾目、猶以爲小、爾又言及爾僕之家、至於久遠、耶和華上帝歟、爾之待我、等於尊顯之人、"],[13,17,18,"爾僕受此尊榮、大衞更有何詞、蓋爾洞悉爾僕、"],[13,17,19,"耶和華歟、爾爲爾僕之故、循爾心志、行此大事、而顯示之、"],[13,17,20,"耶和華歟、以我所聞、爾無可比、爾外無他上帝、"],[13,17,21,"地上何民、如爾民以色列、上帝親往埃及贖之、以爲己民、且於所贖民前、行大而可畏之事、驅逐列邦、而顯爾名、"],[13,17,22,"爾立以色列民永爲爾民、爾耶和華爲其上帝、"],[13,17,23,"耶和華歟、爾論爾僕、與其家所言者、求爾堅固之、至於永遠、如言而行、"],[13,17,24,"願人永尊爾名爲大、曰、萬軍之耶和華、爲以色列之上帝、乃治以色列之上帝、爾僕大衞之家、必堅立於爾前、"],[13,17,25,"我上帝歟、旣啟示爾僕、必爲之建立家室、故爾僕敢祈於爾前、"],[13,17,26,"耶和華歟、爾乃上帝、以此福許爾僕、"],[13,17,27,"今爾樂錫嘏於僕家、俾永存於爾前、耶和華歟、爾旣錫福、則永享其福焉、"],[13,18,1,"厥後、大衞擊非利士人服之、奪取迦特、與其鄉里、"],[13,18,2,"又擊摩押、摩押人遂服役於大衞、而納貢焉、"],[13,18,3,"瑣巴王哈大利謝往伯拉河、欲恢復其權時、大衞擊之、至於哈馬、"],[13,18,4,"獲其戰車千乘、騎兵七千、步卒二萬、戰車之馬、則斷其筋、惟存百乘之馬、"],[13,18,5,"大馬色之亞蘭人、來助瑣巴王哈大利謝、大衞擊殺其人二萬二千、"],[13,18,6,"大衞置戍於大馬色之亞蘭、亞蘭人遂服役於大衞、而納貢焉、大衞無論何往、耶和華使之獲勝、"],[13,18,7,"大衞奪哈大利謝臣僕之金盾、攜至耶路撒冷、"],[13,18,8,"又自屬哈大利謝之提巴與均二邑、取銅甚多、所羅門用以製造銅海及柱、與諸銅器、"],[13,18,9,"哈大利謝屢與哈馬王陀烏戰、陀烏聞大衞擊敗瑣巴王哈大利謝全軍、遂遣子哈多蘭見大衞王問安、爲之祝嘏、哈多蘭攜金銀銅諸器、"],[13,18,10,"哈大利謝屢與哈馬王陀烏戰、陀烏聞大衞擊敗瑣巴王哈大利謝全軍、遂遣子哈多蘭見大衞王問安、爲之祝嘏、哈多蘭攜金銀銅諸器、"],[13,18,11,"大衞王以此、及得自以東、摩押、亞捫、非利士、亞瑪力、諸族之金銀、俱區別獻於耶和華、"],[13,18,12,"洗魯雅子亞比篩在鹽谷、擊殺以東人一萬八千、"],[13,18,13,"大衞置戍於以東、以東人遂服役於大衞、大衞無論何往、耶和華使之獲勝、○"],[13,18,14,"大衞爲以色列全族之王、爲其民衆施行公義、"],[13,18,15,"洗魯雅子約押爲軍長、亞希律子約沙法爲史官、"],[13,18,16,"亞希突子撒督、與亞比亞他子亞比米勒爲祭司、沙威沙爲繕寫、"],[13,18,17,"耶何耶大子比拿雅、統轄基利提人、比利提人、大衞諸子、在王左右爲相、"],[13,19,1,"厥後、亞捫族王拿轄沒、其子嗣位、"],[13,19,2,"大衞曰、昔哈嫩父拿轄施仁慈於我、今我將施仁慈於其子哈嫩、遂遣使往、唁其喪父、大衞僕至亞捫族地、見哈嫩以唁之、"],[13,19,3,"亞捫族之牧伯謂哈嫩曰、大衞遣唁者詣爾、爾意大衞果敬爾父乎、其僕詣爾、詎非窺察此地、而滅之耶、"],[13,19,4,"哈嫩遂執大衞僕、薙其鬚、中斷其衣至臀、而遣之歸、"],[13,19,5,"其人深以爲恥、或以所待告大衞、乃遣人迎之曰、可居耶利哥、俟鬚長而後歸、"],[13,19,6,"亞捫人知己爲大衞所惡、哈嫩與亞捫人、遂以銀一千他連得、由米所波大米、亞蘭瑪迦、瑣巴、僱戰車、募騎兵、"],[13,19,7,"得戰車三萬二千乘、及瑪迦王與其民衆咸至、建營於米底巴前、亞捫人亦自其諸邑、會集以戰、"],[13,19,8,"大衞聞之、則遣約押率勇士全軍、"],[13,19,9,"亞捫族出、列陳於邑門、偕來之王、別列於野、"],[13,19,10,"約押見其前後列陳、則簡以色列之精兵、陳列行伍、以禦亞蘭人、"],[13,19,11,"以餘軍付弟亞比篩、陳列行伍、以禦亞捫族、"],[13,19,12,"曰、如亞蘭人強於我、爾則助我、如亞捫人強於爾、我則助爾、"],[13,19,13,"宜強乃志、爾我當爲我民、及我上帝邑、爲大丈夫、願耶和華成其所欲、"],[13,19,14,"約押與所偕之民、進與亞蘭人戰、亞蘭人遁於其前、"],[13,19,15,"亞捫族見亞蘭人遁、亦遁於其弟亞比篩前、而入於邑、約押遂返耶路撒冷、○"],[13,19,16,"亞蘭人見己爲以色列所敗、則遣使招河外之亞蘭人出、哈大利謝之軍長朔法率之、"],[13,19,17,"或告大衞、遂集以色列衆、濟約但遇敵、列陳而攻之、亞蘭人則與之戰、"],[13,19,18,"亞蘭人遁於以色列衆前、大衞戮其戰車七千乘之卒、步卒四萬、殺其軍長朔法、"],[13,19,19,"哈大利謝臣僕見其爲以色列所敗、遂與大衞修好、而服事之、嗣後亞蘭人不復助亞捫族、"],[13,20,1,"歲初、列王出戰時、約押率軍毀亞捫族地、往圍拉巴、大衞居於耶路撒冷、約押攻拉巴墮之、"],[13,20,2,"大衞奪其王首之冕、權其金一他連得、飾以寶石、置於大衞首、又自邑中、攜出貨財甚多、"],[13,20,3,"且出其邑民、使之服役於鋸、及鐵耙與斧、大衞待亞捫族諸邑、皆若是、大衞率民衆歸耶路撒冷、○"],[13,20,4,"厥後、與非利士人戰於基色、戶沙人西比該、殺利乏裔細派、敵遂降服、"],[13,20,5,"又與非利士人戰、睚珥子伊勒哈難、殺迦特人歌利亞弟拉哈米、其槍之柯、大如織器之梁、"],[13,20,6,"又戰於迦特、有利乏裔一人、軀幹修偉、手足各有六指、共二十有四、"],[13,20,7,"其人侮以色列族時、大衞兄示米亞子約拿單殺之、"],[13,20,8,"此皆利乏裔、生於迦特、死於大衞、及其臣僕之手、"],[13,21,1,"撒但起敵以色列人、激大衞核數之、"],[13,21,2,"大衞諭約押及民長曰、往核以色列人、自別是巴至但、返而告我、使我知其數、"],[13,21,3,"約押曰、願耶和華增益其民、百倍於今、我主我王歟、斯衆非皆爾僕乎、我主何爲命此、何陷以色列人於罪乎、"],[13,21,4,"然約押爲王命所迫、遂往遍行以色列境、返耶路撒冷、"],[13,21,5,"以民數進於大衞、以色列人執刃者、百有十萬、猶大人執刃者、四十七萬、"],[13,21,6,"惟利未人與便雅憫人未核、因約押以王命爲可惡也、"],[13,21,7,"上帝不悅此事、遂擊以色列人、"],[13,21,8,"大衞禱上帝曰、我行此事、大干罪戾、愚昧之甚、求爾宥僕之過、"],[13,21,9,"耶和華諭大衞之先見迦得曰、"],[13,21,10,"往告大衞曰、耶和華云、我以三者示爾、可擇其一、我行於爾、"],[13,21,11,"迦得遂詣大衞曰、耶和華云、爾其擇所欲者、"],[13,21,12,"或饑饉三年、或爲敵所敗、被敵以刃追襲三月、或耶和華以疫爲刃、遍行斯土、耶和華之使者滅以色列四境三日、爾其思之、俾我覆遣我者、"],[13,21,13,"大衞謂迦得曰、我處窘迫之境、耶和華矜恤維大、願陷於其手、勿陷於人手、"],[13,21,14,"於是耶和華降疫癘於以色列、隕者七萬、"],[13,21,15,"上帝遣使往滅耶路撒冷、將滅之時、耶和華見之、悔降斯禍、遂諭施剿之使曰、足矣、可止爾手、其時耶和華之使者、立於耶布斯人阿珥楠之禾場、"],[13,21,16,"大衞舉目、見耶和華使者立於空際、拔刃在手、指耶路撒冷、大衞與諸長老、皆衣麻衣、俯伏於地、"],[13,21,17,"大衞禱上帝曰、命核民數者非我乎、我犯罪行惡、此羣羊何爲、願我上帝耶和華手攻我、及我父家、勿攻爾民、使遘斯災、"],[13,21,18,"耶和華之使者命迦得告大衞、宜上爲耶和華築壇、在耶布斯人阿珥楠之禾場、"],[13,21,19,"遂依迦得奉耶和華名、所諭之言而上、"],[13,21,20,"適阿珥楠打麥、回顧見天使、所偕四子俱避匿、"],[13,21,21,"大衞至阿珥楠處、阿珥楠見之、乃出禾場、伏地而拜、"],[13,21,22,"大衞謂之曰、以此禾場予我、我爲耶和華築壇其上、俾疫止於民間、必足其價、以場予我、"],[13,21,23,"阿珥楠曰、取之可也、願我主我王依所視爲善者而行、牛爲燔祭、打穀之具爲柴、麥爲素祭、我悉予之、"],[13,21,24,"大衞王曰、不然、我必足其價以購之、不取爾物獻於耶和華、不費財之燔祭、我不獻之、"],[13,21,25,"於是大衞權黃金六百舍客勒、予阿珥楠、以購其地、"],[13,21,26,"大衞爲耶和華築壇於彼、獻燔祭與酬恩祭、籲耶和華、耶和華自天允之、降火於燔祭壇、"],[13,21,27,"耶和華命使者韜刃於鞘、○"],[13,21,28,"是時大衞見耶和華於耶布斯人阿珥楠之禾場、允其所祈、則獻祭於彼、"],[13,21,29,"時、耶和華之幕、與燔祭壇、卽摩西在曠野所造者、皆在基遍崇邱、"],[13,21,30,"大衞不敢往彼諮諏上帝、因懼耶和華使者之刃也、"],[13,22,1,"大衞曰、此乃耶和華上帝之室、以色列燔祭之壇、○"],[13,22,2,"大衞命集旅於以色列地之人、選石工鑿石、以建上帝室、"],[13,22,3,"大衞備鐵甚多、以爲門扉之釘及鈎、又備銅無算、"],[13,22,4,"香柏無數、蓋西頓推羅人運之甚多也、"],[13,22,5,"大衞曰、我子所羅門尚冲弱、爲耶和華建室、必極壯麗、聲譽榮光、播於萬國、故我必爲之備、於是大衞未死之先、儲材豐盛、○"],[13,22,6,"大衞召子所羅門、囑其爲以色列之上帝耶和華建室、"],[13,22,7,"謂之曰、我子歟、我有意爲我上帝耶和華之名建室、"],[13,22,8,"惟耶和華降諭於我曰、爾流人血甚多、屢經大戰、不可爲我名建室、因爾多流人血於地、爲我目擊、"],[13,22,9,"爾將生子、彼處平康、厥名所羅門、我必錫以綏安、使免四周諸敵之擾、彼在位時、我必錫綏安於以色列族、"],[13,22,10,"彼將爲我名建室、彼必爲我子、我必爲其父、固其國位於以色列、歷世弗替、"],[13,22,11,"我子歟、願耶和華偕爾、願爾亨通、建爾上帝耶和華之室、循其所言、"],[13,22,12,"願耶和華賦爾睿智聰明、使爾受命治以色列、守爾上帝耶和華之律、"],[13,22,13,"爾若遵行耶和華藉摩西、命以色列人之典章律例、則必亨通、強乃心、壯乃志、勿畏葸、勿恐惶、"],[13,22,14,"我於困難中、爲耶和華室、備金十萬他連得、銀百萬他連得、銅鐵甚多、莫權其數、亦備木石、爾可增益之、"],[13,22,15,"且爾多有匠役、石工木工、及諸巧匠、"],[13,22,16,"金銀銅鐵無數、爾其興起造作、願耶和華偕爾、"],[13,22,17,"大衞又命以色列諸牧伯、助子所羅門曰、"],[13,22,18,"爾上帝耶和華非偕爾、賜爾四周平康乎、蓋彼以斯土之民付我手、俾地爲耶和華與其民所轄、"],[13,22,19,"今當專爾心、定爾志、尋求爾上帝耶和華、興起而建上帝耶和華之聖所、舁耶和華之約匱、及上帝之聖器、入於爲耶和華名所建之室、"],[13,23,1,"大衞壽高年邁、立子所羅門爲以色列王、"],[13,23,2,"集以色列諸牧伯、及祭司利未人、"],[13,23,3,"利未人自三十歲以上者、核其丁男、共三萬八千人、"],[13,23,4,"其中督耶和華室之工者、二萬四千、爲有司士師者六千、"],[13,23,5,"司閽者四千、以大衞所作之樂器、頌讚耶和華者四千、"],[13,23,6,"大衞循利未子革順、哥轄、米拉利、分其裔爲班次、"],[13,23,7,"革順裔拉但、示每、"],[13,23,8,"拉但子、耶歇爲長、又有細坦、約珥、共三人、"],[13,23,9,"示每子、示羅密、哈薛、哈蘭三人、皆爲拉但族長、"],[13,23,10,"示每子、雅哈、細拿、耶烏施、比利亞、此四人、皆示每之子、"],[13,23,11,"雅哈爲長、細撒次之、耶烏施與比利亞、丁男無多、故歸一族核數、"],[13,23,12,"哥轄子、暗蘭、以斯哈、希伯倫、烏薛四人、"],[13,23,13,"暗蘭子、亞倫、摩西、亞倫及其子孫、永別爲聖、以別至聖之物、焚香於耶和華前、而供役事、且奉其名爲人祝嘏、歷世靡曁、"],[13,23,14,"上帝僕摩西之裔、其名錄於利未支派中、"],[13,23,15,"摩西子、革舜、以利以謝、"],[13,23,16,"革舜子、細布業爲長、"],[13,23,17,"以利以謝子、利哈比雅爲長、以利以謝無他子、惟利哈比雅子甚多、"],[13,23,18,"以斯哈子、示羅密爲長、"]]};